window.BANNANJE_VERSE_MEANINGS_DEV = {
  "1.1": "[प्रथमाध्यायस्य बन्नञ्जे-पीठिका]\n\nसामान्यतः गीताभाष्यकाराः प्रथमाध्यायं न बहु मन्यन्ते, द्वितीयाध्यायात् एव आरभन्ते- 'युद्धभूमौ विषण्णाय अर्जुनाय कृष्णस्य उपदेशः' इति। किन्तु प्रथमाध्याये मनःशास्त्रसम्बद्धाः बहवः विषयाः सन्ति। अतः 'अर्जुनविषादयोगः' इति नाम अस्य अध्यायस्य न सम्यक् उचितम्। अस्मिन् अध्याये युद्धारम्भात् पूर्वं युद्धभूमौ स्थितयोः अर्जुनदुर्योधनयोः मनःस्थितिः अद्भुतरूपेण विश्लेषिता। अर्जुनस्य मनोविभ्रमाय कृष्णः उपदेशेन समाधानम् अयच्छत्, किन्तु दुष्टः दुर्योधनः विभ्रम एव मृतः। अतः प्रथमाध्यायः न केवलं ऐतिहासिकदृष्ट्या द्रष्टव्यः, अपि तु अत्र निहितं मनःशास्त्रम् अवगन्तव्यम्। इदं मनःशास्त्रं न केवलं युद्धभूमिस्थानां कृते, अपि तु अस्माकं दैनन्दिनजीवनाय अपि सम्बद्धम्। एतत् सावधानतया सूक्ष्मदृष्ट्या अवलोक्य एव अयम् अध्यायः अस्माकं बोधगम्यः भवति।\n\nभगवद्गीता धृतराष्ट्रस्य प्रश्नेन आरभ्यते। धृतराष्ट्रः इति राष्ट्रं धृतवान् इत्यर्थः- सत्यविषये अन्धः निमीलितनेत्रः जीवः एव धृतराष्ट्रः। दुर्योधनः अस्माकम् अन्तः दुष्टतायाः पराकाष्ठायाः प्रतीकम्। भीष्मद्रोणकृपशल्यकर्णाः सर्वे अस्मदीयानि इन्द्रियाणि इव। स्वमनसि वर्तमानेन दौष्ट्येन वयं स्वकीयानि बहुमूल्यानि इन्द्रियाणि दुष्कर्मणि नियोजयामः। वस्तुतः इन्द्रियाणि न दुष्टानि, किन्तु दुष्टेन सह संयुज्य दुष्कर्म कुर्वन्ति। एवं गीतायाः प्रतिश्लोकं महाभारतस्य च प्रतिपात्रं परमम् गूढं च अर्थं धारयति।\n\nधृतराष्ट्रः उवाच\n\nधर्मक्षेत्रे कुरुक्षेत्रे समवेताः युयुत्सवः ।\n\nमामकाः पाण्डवाः च एव किम् अकुर्वत सञ्जय ॥\n\nअन्धस्य धृतराष्ट्रस्य एषः प्रश्नः जीवस्य अपि अन्धप्रश्नः एव। वयं तथा अन्धाः यत् 'वयं किमपि न जानीमः' इति अपि न जानीमः। अत एव गीता धृतराष्ट्रप्रश्नेन एव आरभ्यते। परशुरामेण निर्मितं समन्तपञ्चकनामकं धर्मक्षेत्रम् इदम्, पश्चात् कुरुनाम्ना राज्ञा कुरुक्षेत्रम् अभवत्। अस्मदीयं हृदयम् एव धर्मक्षेत्रम्, धर्माधर्मनिर्णायकं मनः एव कुरुक्षेत्रम्। मनसः संघर्षः एव महाभारतम्। अत्र अन्धः धृतराष्ट्रः 'मामकाः पाण्डवाः च' इति सम्बोधनेन स्वकीयां दुर्बलतां प्रकटयति।",
  "1.2": "सञ्जय उवाच\n\nदृष्ट्वा तु पाण्डव अनीकम् व्यूढम् दुर्योधनः तदा ।\n\nआचार्यम् उपसङ्गम्य राजा वचनम् अब्रवीत् ॥\n\nपूर्वं 'अनीक' इति शब्दस्य अर्थः ज्ञातव्यः। महाभारतयुद्धे अष्टादश अक्षौहिण्यः योद्धुम् आगताः, तासु सप्त पाण्डवपक्षे शेषाः कौरवपक्षे। अक्षौहिणी नाम सेनायाः बृहत्तमो विभागः। पूर्वकाले सेना नवधा विभक्ता आसीत् — (1) पत्तिः: एकः गजः, एकः रथः, त्रयः अश्वाः, पञ्च च पदातयः, इत्येषा एका तुकडिः; (2) सेनामुखम्: तिस्रः पत्तयः; (3) गुल्मः: तीनि सेनामुखानि; (4) गणः: त्रीणि गुल्मानि; (5) वाहिनी: त्रयः गणाः; (6) पृतना: तिस्रः वाहिन्यः; (7) चमूः: तिस्रः पृतनाः; (8) अनीकिनी: तिस्रः चम्वः; (9) अक्षौहिणी: दश अनीकिन्यः — अर्थात् 21870 गजाः, 21870 रथाः, 65610 अश्वाः, 109350 च पदातयः। अस्य गणनानुसारम् एका अनीकिनी दशमांशः अक्षौहिण्याः — अर्थात् 2187 गजाः, 2187 रथाः, 6561 अश्वाः, 10935 पदातयः, यत् पाण्डवसेनायाः सप्ततितमो भागः। युद्धकाले अष्टादश अक्षौहिण्यः युगपत् न योधयन्ति, एका तुकडिः एव निश्चितव्यूहेन रचिता युध्यति। तस्य विशिष्टव्यूहेन (व्यूढं) शिस्तुबद्धं रचितां पाण्डवसेनायाः एकाम् अनीकां दृष्ट्वा दुर्योधनस्य मनः क्षुभ्यति। एषः तस्य प्रथमः मानसिकः आघातः। ततः सः आचार्यं द्रोणं गत्वा, राजोचितम् औद्धत्यं प्रदर्श्य, वदति। एकादशाक्षौहिणीबलं स्वस्मिन् सत्यपि, दुर्योधनः स्वसेनां प्रोत्साहयितुं विस्मृत्य पाण्डवसेनायाः वीरान् एव वर्णयति — इदम् एव तस्य मनःस्थितेः लक्षणम्।",
  "1.3": "पश्य एताम् पाण्डुपुत्राणाम् आचार्य महतीम् चमूम् ।\n\nव्यूढाम् द्रुपदपुत्रेण तव शिष्येण धी-मता ॥\n\nदुर्योधनः सेनापतिं भीष्मम् अगत्वा द्रोणाचार्यं गत्वा, भीष्मेण अपि श्रूयमाणं विषवचनं वदति — द्रोणं 'पाण्डवानाम् आचार्यः' इति कटाक्षेण सम्बोधयन्। द्रुपदपुत्रः धृष्टद्युम्नः पाण्डवसेनायाः नायकः। द्रुपदः द्रोणश्च बाल्यमित्रे आस्ताम्, किन्तु द्रुपदेन राज्यप्राप्त्यनन्तरं द्रोणः अपमानितः। तेन वैरेण द्रोणः कौरवपाण्डवयोः गुरुः अभवत्, विद्याभ्यासान्ते च द्रुपदस्य अर्धराज्यं जित्वा तम् उक्तवान् — 'अधुना तव समः अस्मि'। प्रतिशोधाय द्रुपदेन यज्ञेन प्राप्तः पुत्रः एव धृष्टद्युम्नः, द्रोणस्य एव शिष्यत्वेन शिक्षितः। दुर्योधनः तम् एव द्रोणस्य शिष्यम् इति स्मारयन् कुहकेन वदति। अन्तः भीतस्य दुर्योधनस्य एषा प्रथमा भ्रान्तिः — स्वराज्यलोभात् द्वेषः, द्वेषात् ईर्ष्या, ततः मनोविभ्रमः।",
  "1.4": "अत्र शूराः महा इषु आसाः भीमार्जुन समाः युधि ।\n\nयुयुधानः विराटः च द्रुपदः च महारथः ॥\n\nपाण्डवसेनां दृष्ट्वा भीतः दुर्योधनः द्रोणाचार्यं प्रति तत्र स्थितान् वीरान् वर्णयति। यस्मात् भयं भवति सः सर्वत्र दृश्यते — यथा कंसाय कृष्णः — इदम् एव मनोविज्ञानम्। अत्र दुर्योधनः भीमार्जुनयोः भयेन तान् एव सर्वत्र पश्यति, अतः वदति 'अत्र सर्वे वीराः महेषुः अतिरथाः च भीमार्जुनसमाः' इति। तत्कालिकं महाधनुः गाण्डीवम्, तेन युद्धं कर्तुं समर्थाः अर्जुनः भीमः श्रीकृष्णः च एव, अतः दुर्योधनाय पाण्डवसेनायाः सर्वे महावीराः भीमार्जुनसमानाः भाति। ततः सः सात्यकिं विराटं द्रुपदं च नामतः वदति — एते त्रयः पूर्वं कौरवपक्षे स्थातुम् अर्हाः आसन्, तथापि कारणान्तरैः पाण्डवपक्षम् आश्रिताः। जरासन्धेन सह कृष्णविरुद्धं युद्धं कृतवान् द्रुपदः पूर्वं पाण्डवैः बद्धः, अर्धराज्यं च हृतम्, तथापि द्रौपदीं पाण्डवेभ्यः दत्त्वा सम्बन्धं वर्धयित्वा पाण्डवपक्षे स्थितः। विराटः पूर्वं कीचकात् भीतः राज्यं शासितवान्, भीमेन कीचके हते सः पाण्डवपाळयं प्राप्तः। सात्यकिः बलरामस्य आज्ञाम् अनतिक्रम्य वर्तते — बलरामः 'युद्धे न प्रविशामि' इति तीर्थयात्रां गतः, अतः सात्यकिः अपि पाण्डवपक्षे स्थितः। एवं प्रत्येकं नाम स्मरन् दुर्योधनस्य अन्तः 'अहो, मत्पक्षे स्थातव्याः एते महारथाः पाण्डवपक्षे' इति वेदना वर्तते — एतत् एव तस्य विषादः, स्वयुद्धनीतिं विहाय एवं विलपन् कालं हरति।",
  "1.5": "धृष्टकेतुः चेकितानः काशिराजः च वीर्यवान् ।\n\nपुरुजित् कुन्तिभोजः च शैब्यः च नरपुङ्गवः ॥\n\nअत्र षट् वीराणां नामानि श्रूयन्ते, किन्तु द्रष्टव्यम् एतेषां नाम्नि दुर्योधनस्य अन्तर्वेदना। धृष्टकेतुः शिशुपालपुत्रः — शिशुपालः राजसूययज्ञकाले कृष्णेन हतः, अधुना तत्पुत्रः पाण्डवपक्षे! चेकितानः यादववीरः, बलरामस्य अनुपस्थितौ पाण्डवान् आश्रितः। काशिराजशब्देन द्वौ काशिराजौ स्मर्येते- वरणा-असीनद्योः सङ्गमे स्थितं काशीनगरं द्विधा विभक्तम्, तत्रत्यौ राजानौ उभौ काशिराजशब्देन उच्येते। एकः दुर्योधनस्य श्वशुरः आसीत्, अन्यः भीमसेनाय कन्यां दत्तवान्। अत्र भीमसेनस्य एव श्वशुरः अभिप्रेतः, यतः दुर्योधनस्य श्वशुरः पौण्ड्रकयुद्धे कृष्णचक्रेण पूर्वमेव हतः। अतः 'मम श्वशुरः अपि पाण्डवपक्षे' इति दुर्योधनस्य अन्तर्वेदना अत्र सूच्यते। पुरुजित् कुन्तिभोजश्च कुन्त्याः दत्तकबान्धवौ- कुन्ती हि मूलतः यादववंशजा वसुदेवस्य भगिनी 'पृथा' नाम्ना, कुन्तिराज्ञा दत्तकपुत्रीत्वेन गृहीता; अतः तत्सम्बन्धेन एतौ पाण्डवपक्षे स्थितौ इति दुर्योधनस्य विलापः। शैब्यः शिबिदेशस्य राजा, यस्य पुत्रः द्रौपदीहरणे जयद्रथस्य साहाय्येन भीमेन हतः, तथापि सः अपि पाण्डवपक्ष एव इति दुर्योधनः द्रोणं प्रति स्वहृदयवेदनां प्रकटयति। एतान् त्रीन् सः 'नरपुङ्गवाः' इति सम्बोधयति- वृषभ इव गतिशालिनः वीराः, येषां गतिः दृष्टिः च शत्रुहृदयं कम्पयति।\n\nएवं मानसिकसङ्क्षोभग्रस्तः पुरुषः पूर्वघटनाः पुनः पुनः स्मरन् आत्मस्थैर्यं त्यजति, स्वकीयं सामर्थ्यं विस्मृत्य तथा व्यवहरति इति अत्र स्पष्टं दृश्यते। एवंविधायां स्थितौ कस्यचित् अपि जयः न सम्भवति।",
  "1.6": "युधामन्युः च विक्रान्त उत्तमौजाः च वीर्यवान् ।\n\nसौभद्रः द्रौपदेयाः च सर्वे एव महारथाः ॥\n\nभीतः दुर्योधनः प्रत्येकं वीरं क्रमेण वर्णयति। युधामन्युः उत्तमौजाश्च द्रुपदस्य अपरौ द्वौ पुत्रौ — तौ विक्रान्तौ इति उक्तौ। अभिमन्युः सुभद्रापुत्रः, त्रयोदशाष्टादशवर्षीयाः पञ्च द्रौपदीपुत्राः च — एतान् अपि 'महारथान्' इति सः वदति! अत्र बोध्यम् — एकवारं भयेन आक्रान्ताः वयं रज्जौ अपि सर्पं पश्यामः, तथा अस्मदीयं वास्तविकं सामर्थ्यम् अपि व्यर्थं भवति। एकादशाक्षौहिणीबलं सत्यपि, स्वसैन्यं प्रोत्साहयितुं विहाय, दुर्योधनः पाण्डवसेनायाः एकादश वीरान् एव वर्णयति — इदम् एव तस्य मनःस्थितेः स्पष्टं लक्षणम्।",
  "1.7": "अस्माकं तु विशिष्टाः ये तान् निबोध द्विजोत्तम ।\n\nनायकाः मम सैन्यस्य सञ्ज्ञार्थं तान् ब्रवीमि ते ॥\n\nवीरः अल्पशक्तिः अपि युद्धकाले युक्त्या कार्यं साधयति। नायकः स्वसैन्यं शत्रुसैन्यात् अधिकबलम् इति विश्वास्य उत्साहयति। किन्तु अत्र दुर्योधनः स्वसेनापतिं भीष्मम् अपृष्ट्वा, द्रोणाचार्यम् एव शत्रुसैन्यस्य वीरान् वर्णयित्वा, 'तव संज्ञार्थं मम सैन्यस्य नायकान् कथयामि' इति वदति — विपरीतक्रमः एव अत्र सूचितः।",
  "1.8": "भवान् भीष्मः च कर्णः च कृपः च समितिञ्जयः ।\n\nअश्वत्थामा विकर्णः च सौमदत्तिः तथा एव च ॥\n\nपाण्डवसेनायाः एकादश महावीरान् षट् च कुमारान् वर्णयित्वा दुर्योधनाय स्वपक्षे कोऽपि वीरः न दृश्यते! अतः सः कुहकेन स्वकीयान् सप्त वीरान् नामतः वदति — पूज्यः भवान् द्रोणः, युद्धारम्भे धर्मराजाय जयम् आशीर्वदन् भीष्मः, भीष्मस्य रणभूमौ स्थितिपर्यन्तं न योत्स्यामि इति शपथं कृत्वा उपविष्टः कर्णः, वेदपारङ्गतः कृपाचार्यः, विक्षिप्तचित्तः अश्वत्थामा, द्रौपद्याः अपमानं निन्दित्वा अपि लाभं ग्रहीतुम् उद्युक्तः विकर्णः, तथा भीष्मपितुः भ्रातृपुत्रः सौमदत्तिः भूरिश्रवाः।",
  "1.9": "अन्ये च बहवः शूराः मत् अर्थे त्यक्त जीविताः ।\n\nनाना शस्त्र प्रहरणाः सर्वे युद्ध विशारदाः ॥\n\nअपरे अपि बहवः शूराः मदर्थं जीवितं त्यक्तुं उद्यताः, नानाशस्त्रयोद्धारः, सर्वे युद्धकुशलाः। ऊपरितः दुर्योधनः स्वपक्षीयान् वीरान् वर्णयति इति भाति, किन्तु सः द्रोणम् एव सम्बोध्य कुहकेन वदति — 'मम पक्षे अपि कोऽपि मत्कृते प्राणं दातुम् उद्यतः' इति स्वस्य असहायताम् एव प्रकटयन्।",
  "1.10": "अपर्याप्तं तत् अस्माकं बलम् भीष्म अभिरक्षितम् ।\n\nपर्याप्तं तु इदम् एतेषाम् बलम् भीम अभिरक्षितम् ॥\n\nअत्र दुर्योधनस्य वचनस्य उपसंहारः। सः वदति — भीष्माचार्यरक्षितं तत् अस्मदीयं बलम् अपर्याप्तम् एव, भीमरक्षितं तु एतेषां (पाण्डवानां) बलं पर्याप्तम्। सूक्ष्मं दृष्ट्वा, भीष्मः कौरवसेनापतिः, किन्तु भीमः पाण्डवसेनापतिः न। दुर्योधनस्य भीमे द्वेषः भयं च अस्ति, अतः सः पाण्डवसेनां 'भीमरक्षिता' इति सम्बोधयति।",
  "1.11": "अयनेषु च सर्वेषु यथा भागम् अवस्थिताः ।\n\nभीष्मम् एव अभिरक्षन्तु भवन्तः सर्वे एव हि ॥\n\n'सर्वे यूयं यथास्थानं व्यवस्थिताः भीष्मम् एव रक्षत' इति दुर्योधनः द्रोणम् उद्दिश्य वदति। इदं वचनम् 'अस्मदीयं वृद्धं सेनापतिं भीष्मं किञ्चित् रक्षत' इव भाति — स्वसेनापतौ विश्वासाभावम् एव सूचयत्। एतत् श्रुत्वा भीष्माचार्यस्य हृदि कियती वेदना अभूत् इति कल्पयितुम् अपि दुष्करम्, यतः सः स्वस्वजनानां विरुद्धं युद्धाय स्वात्मसाक्षिविरुद्धं धैर्येण उपस्थितः आसीत्।",
  "1.12": "तस्य सञ्जनयन् हर्षम् कुरुवृद्धः पितामहः ।\n\nसिंहनादम् विनद्य उच्चैः शङ्खम् दध्मौ प्रतापवान् ॥\n\nदुर्योधनं हर्षयितुं कुरुवृद्धः प्रतापवान् पितामहः भीष्मः उच्चैः सिंहनादं कृत्वा शंखं दध्मौ। भरवसाहीनं विषादेन वदन्तं दुर्योधनम् उत्साहयितुं, कुलस्य ज्येष्ठः भीष्मः स्वकर्तव्यानुसारं शंखनादं कृतवान्। शङ्खनादः दुष्टशक्तिनाशकः इति पुरा विश्वासः, यतः तस्य नादेन आसुरशक्तयः पलायन्ते। भीष्मः एतेन नादेन कौरवपाण्डवसेनयोः स्वसज्जताया संकेतं प्रेषितवान्।",
  "1.13": "ततः शङ्खाः च भेर्यः च पणव अनक गोमुखाः ।\n\nसहसा एव अभ्यहन्यन्त सः शब्दः तुमुलः अभवत् ॥\n\nप्रधानसेनापतौ भीष्मे शङ्खं ध्मातवति, कौरवसेनातः शङ्खाः भेर्यः पणवानकगोमुखाः च सहसा एव वादिताः, सः शब्दः तुमुलः अभवत्। न दुर्योधनः न तस्य भ्रातरः शङ्खं ध्मातवन्तः, अपि तु सेनापतितः प्रारभ्य क्रमेण सेनानायकाः सैनिकाश्च वादितवन्तः। एवं अव्यवस्थितरूपेण जातः नादः कोलाहलवत् एव आसीत् — दुर्योधनेन स्वशक्तिः व्यवस्थितरूपेण न नियोजिता इति अत्र स्पष्टम्। यत् किमपि साधनं भवतु, यावत् तस्य नियमबद्धः प्रयोगः न ज्ञायते, तावत् तत् साधनं व्यर्थम् एव।",
  "1.14": "ततः ।\n\nश्वेतैः हयैः युक्ते ।\n\nमहति स्यन्दने स्थितौ ।\n\nमाधवः पाण्डवः च एव ।\n\nदिव्यौ शङ्खौ प्रदध्मतुः ॥\n\nकौरवसेनायाः कोलाहलानन्तरं, श्वेताश्वयुक्ते महति रथे स्थितौ श्रीकृष्णार्जुनौ स्वदिव्यशङ्खौ ध्मातवन्तौ (प्रथमं कृष्णः, ततः अर्जुनः)। अत्र 'माधवः' 'पाण्डवः' इति द्वे विशेषणे प्रयुक्ते। 'मा' इति लक्ष्मीः, अतः माधवः लक्ष्मीपतिः भगवान्। मधुवंशे अवतीर्णत्वात् अपि सः माधवः। अर्जुनः कुन्त्याः कनिष्ठपुत्रः, अतः पार्थः कौन्तेयः पाण्डवः इति नामभिः उच्यते। तस्मिन् भगवतः विशेषसान्निध्यम् आसीत् — सः नारायणसहचरस्य 'नरस्य' रूपः अपि। अस्मदीयं शरीरम् अपि रथः, तत्र जीवं वहन् भगवान् सन्निहितः। चत्वारः अश्वाः चत्वारि वेदाः, श्वेतवर्णः सत्त्वगुणस्य संकेतः।",
  "1.15": "पाञ्चजन्यम् हृषीकेशः देवदत्तम् धनञ्जयः ।\n\nपौण्ड्रम् दध्मौ महाशङ्खम् भीमकर्मा वृकोदरः ॥\n\nपाण्डवपक्षतः प्रथमं श्रीकृष्णः स्वशङ्खं पाञ्चजन्यं ध्मातवान्। पाञ्चजन्याख्यायाः कथा — साम्दीपनिमुनेः आश्रमे विद्याभ्यासं समाप्य, गुरुदक्षिणारूपेण कृष्णः 'पाञ्चजन' नामकेन असुरेण हृतं गुरुपुत्रं मारयित्वा पुनः दत्तवान्, तस्य असुरस्य देहे स्थितः शङ्खः एव पाञ्चजन्यः — असुरसंहारस्य ज्ञानानन्दस्य च प्रतीकः। ततः अर्जुनः देवदत्तशङ्खं ध्मातवान् — वनवासकाले असुरैः युद्धं कृत्वा इन्द्रेण दत्तं दुष्टनिग्रहसंकेतम्। ततः वृकोदरः भीमः पौण्ड्रं महाशङ्खं ध्मातवान् — 'वृकोदरः' इति सः सर्वं विश्वं दग्धुं समर्थम् अग्निं स्वोदरे धारयन् इति अर्थः, तेन तस्य पराक्रमः सूचितः। अत्र कृष्णः 'हृषीकेशः' इति उक्तः — हृषीकाणाम् (इन्द्रियाणाम्) ईशः, यः अस्मभ्यं प्रतीन्द्रियं ददाति तत्र स्थित्वा नयति।",
  "1.16": "अनन्तविजयम् राजा कुन्तीपुत्रः युधिष्ठिरः ।\n\nनकुलः सहदेवः च सुघोष मणिपुष्पकौ ॥\n\nभीमानन्तरं कुन्त्याः ज्येष्ठपुत्रः युधिष्ठिरः धर्मविजययोः संकेतं 'अनन्तविजयम्' शङ्खं ध्मातवान्। नकुलसहदेवौ च क्रमेण सुघोषमणिपुष्पकनामकौ शङ्खौ ध्मातवन्तौ। महाभारते अन्येषां राज्ञां शङ्खनामानि न श्रूयन्ते — केवलं भगवद्गीतायाम् एव पाण्डवानां पञ्च शङ्खनामानि उक्तानि, प्रायः तानि अस्माभिः नित्यं स्मर्तव्यानि इति उद्देश्येन।",
  "1.17": "काश्यः च परम इषु आसः शिखण्डी च महारथः ।\n\nधृष्टद्युम्नः विराटः च सात्यकिः च अपराजितः ॥\n\nततः महाधनुर्धरः काशिराजः, महारथः शिखण्डी, धृष्टद्युम्नः विराटः च, अपराजितः सात्यकिः च — एकैकशः शङ्खनादं कृतवन्तः। अत्र शिखण्डिनं 'महारथः' इति सम्बोधनं ध्यातव्यम्। बहवः शिखण्डिनम् नपुंसकम् इति मन्यन्ते, किन्तु तत् न सत्यम्। 'शिखण्ड' अर्थात् शिखा-धारकः इत्यर्थः — केशान् सम्यक् संवार्य पृष्ठे बद्ध्वा धारयन्तः शिखण्डिनः उच्यन्ते। महाभारतस्य एषः शिखण्डी जन्मनि कन्या आसीत्, पश्चात् पुमान् महारथः अभवत्। 'स्त्रीपूर्वत्वात्' भीष्माचार्यः तस्य विरुद्धं बाणं न प्रायुङ्क्त।",
  "1.18": "द्रुपदः द्रौपदेयाः च सर्वशः पृथिवीपते ।\n\nसौभद्रः च महाबाहुः शङ्खान् दध्मुः पृथक् पृथक् ॥\n\nअत्र सूक्ष्मदृष्ट्या पाण्डवपक्षे विद्यमानम् अनुशासनं प्रकाशते। कौरवपाळयस्य कोलाहलरूपाय ध्वनये उत्तरं दातुम्, पाण्डवाः अनुशासितरूपेण, क्रमबद्धरूपेण शङ्खनादं कुर्वन्ति। मनोविज्ञानदृष्ट्या, अनुशासितं लघु सैन्यम् अनुशासनहीनस्य बृहत्सैन्यस्य हृदयं कथं कम्पयितुं शक्नोति इति अत्र दृश्यते। भगवते सर्वसमर्पणभावेन, निरहंकारेण, भगवत्सारथ्ये धर्मयुद्धाय सज्जा पाण्डवसेना मानसिकरूपेण सम्पूर्णं सज्जा आसीत्। अहंकारमत्ता, अधिकारेच्छया मनःस्थैर्यं हित्वा भगवद्विरुद्धं स्थितस्य दुर्योधनस्य नेतृत्वे कौरवसेना पूर्वम् एव आत्मविश्वासं हारितवती। अत्र अन्या विशेषता — पाण्डवपक्षतः क्रमेण अष्टादश जनाः शङ्खनादं कृतवन्तः, अष्टादशसंख्या च अक्षरांकपद्धत्या 'जय' इति सूचयति।",
  "1.19": "स घोषः धार्तराष्ट्राणाम् हृदयानि व्यदारयत् ।\n\nनभः च पृथिवीम् च एव तुमुलः व्यनुनादयन् ॥\n\nअत्र संजयः धृतराष्ट्रपुत्रान् 'धार्तराष्ट्राणाम्' इति सम्बोधयति, यतः तत् एव तेषाम् उपनाम। पूर्वं 'मामकाः पाण्डवाः च' इति सम्बोधितवते धृतराष्ट्राय संजयस्य एतत् कुहकपूर्णम् उत्तरम्। संजयः वदति — 'पाण्डवपक्षतः क्रमबद्धं शङ्खनादं नभः पृथिवीं च व्याप्य, प्रतिध्वनितम् अभूत्, तव धार्तराष्ट्रनामकानां पुत्राणां हृदयानि विदार्य गतम्' इति। पूर्वोक्तम् एव — पाण्डवानाम् अनुशासितं आचरणं युद्धारम्भात् पूर्वम् एव कौरवाणां हृदयं भित्तवत्।",
  "1.20": "अथ व्यवस्थितान् दृष्ट्वा धार्तराष्ट्रान् कपिध्वजः ।\n\nप्रवृत्ते शस्त्रसम्पाते धनुः उद्यम्य पाण्डवः ।\n\nहृषीकेशम् तदा वाक्यम् इदम् आह महीपते ॥\n\nउभयोः शङ्खनादे युद्धम् आरभ्यते। तस्मिन् काले स्वरथे आञ्जनेयस्य विशिष्टसान्निध्येन युक्तः अर्जुनः, इन्द्रियाणाम् ईशं श्रीकृष्णं (हृषीकेशम्) प्रति वदति। अर्जुनरथे प्राणदेवस्य विशिष्टं सान्निध्यम् आसीत्। अस्मदीयेऽपि देहरूपे रथे जीवं सदा 'भगवत्सान्निध्ये' प्राणः एव रक्षति। स्वध्वजे आञ्जनेयस्य सान्निध्यम्, हस्ते गाण्डीवम्, रथसारथिः कृष्णः, सहायः महापराक्रमी भीमसेनः — एवं युद्धाय सज्जं अर्जुनं अहंकारः बाधते। तेन अहंकारेण सः कृष्णं प्रति एवं वदति।",
  "1.21": "अर्जुनः उवाच —\n\nसेनयोः उभयोः मध्ये रथम् स्थापय मे अच्युत ॥\n\nअत्र अर्जुनस्य अहंकारध्वनिः सूक्ष्मरूपेण द्रष्टव्यः। 'मे' इति 'मम' इत्यर्थः — स्वयं श्रीकृष्णः सारथ्यं वहन् अपि, अर्जुनः तं सामान्यसारथिवत् आज्ञापयन् वदति। अत्र सः कृष्णं 'अच्युत' इति सम्बोधयति — अच्युतः अर्थात् स्वयं च्युतिरहितः, भक्तानां च्युतिं हरन् भगवान्। बाह्यतः अहंकारः प्रकटः अपि, अर्जुनस्य अन्तरात्मा सावधानः एव आसीत्, तेन एव नाम्ना उच्चरितेन। अहंकारः महात्मनः अपि न त्यजति — बलं स्वहस्ते इति ज्ञात्वा वयं सर्वं विस्मृत्य अहंकारस्य दासाः भवामः, तेन च अधोगतिं गच्छामः।",
  "1.22": "यावत् एतान् निरीक्षे अहम् योद्धुकामान् अवस्थितान् ।\n\nकैः मया सह योद्धव्यम् अस्मिन् रण समुद्यमे ॥\n\nमहाभारतयुद्धं इतिहासे प्रथमं वैश्विकं युद्धम् इति अभिलिखितम्। तादृशस्य युद्धस्य अग्रे स्थितः अर्जुनः अहंकारेण वदति — 'योद्धुकामान् इमान् एकवारं पश्यामि। कैः सह मया योद्धव्यम्' इति। अत्र 'मया सह योद्धुम् आगतान् एकवारं द्रष्टव्यम्' इति वचने अहंकारपूर्णः व्यङ्ग्यः निहितः — स्वयं महावीरः, स्वसमक्षं स्थिता एषा सेना किमपि न इति दर्पवचनम् एतत्।",
  "1.23": "योत्स्यमानान् अवेक्षे अहम् ये एते अत्र समागताः ।\n\nधार्तराष्ट्रस्य दुर्बुद्धेः युद्धे प्रिय चिकीर्षवः ॥\n\n'दुर्बुद्धेः दुर्योधनस्य हितम् इच्छन्तः, युद्धे तस्मै साहाय्यं कर्तुम् इच्छन्तः, अत्र समागतान् योद्धुकामान् एकवारं पश्यामि' इति अर्जुनः वदति। 'मम विरुद्धं स्थितान् एकवारं द्रष्टव्यम्' इति एतत् वचनम् अर्जुनस्य अहंकारदास्यं स्पष्टं दर्शयति। एतेन अहंकारेण अर्जुनः भगवन्तम् एव विस्मृत्य वदति।",
  "1.24": "सञ्जय उवाच —\n\nएवम् उक्तः हृषीकेशः गुडाकेशेन भारत ।\n\nसेनयोः उभयोः मध्ये स्थापयित्वा रथ उत्तमम् ॥\n\nइन्द्रियाणाम् ईशः श्रीकृष्णः किमपि अनुक्त्वा एव रथं सेनयोः मध्ये स्थापितवान्। अतः परम् अस्माभिः श्रीकृष्णस्य प्रत्येकं कर्मणि मनःशास्त्रीयां चिकित्साम् (Psychotherapy) द्रष्टुं शक्यते। अहंकारः इति मानसिकी अवस्था — तस्याः निवृत्त्यर्थं मानसचिकित्सा आवश्यकी। तत् एव कृष्णः अत्र कृत्वा दर्शितवान्। एतादृशं कृष्णं मनःशास्त्रस्य पितामहम् इति चेत् वदाम, न दोषः। अत्र कृष्णः 'हृषीकेशः', अर्जुनः च 'गुडाकेशः' इति उक्तौ — गुडाकेशः अर्थात् निद्रां जितवान् वीरः।",
  "1.25": "भीष्मः द्रोण प्रमुखतः सर्वेषाम् च महीक्षिताम् ।\n\nउवाच पार्थ पश्य एतान् समवेतान् कुरून् इति ॥\n\nभीष्मद्रोणादीनां सर्वेषां राज्ञां साक्षात् दृष्टिपथे रथं स्थापयित्वा कृष्णः वदति — 'हे पार्थ, पश्य एतान् समवेतान् कुरून्' इति। एषा कृष्णस्य अद्भुता मानसचिकित्सा (Psychotherapy)। अत्र अर्जुनस्य मनःपरीक्षा भवति। अर्जुनः राजा, धर्मरक्षणं प्रजापालनं च तस्य मूलकर्तव्यम्। एतत् कर्तव्यं निर्वहन् धर्मविरुद्धं यः कोऽपि स्थितः तं दण्डयितुम् एव तस्य कर्तव्यम् — सः न्यायाधीशवत् एव, अत्र 'मम बन्धवः, मम स्वजनाः' इति भेदः न कर्तव्यः।",
  "1.26": "तत्र अपश्यत् स्थितान् पार्थः पितॄन् अथ पितामहान् ।\n\nआचार्यान् मातुलान् भ्रातॄन् पुत्रान् पौत्रान् सखीन् तथा ।\n\nश्वशुरान् सुहृदः च एव सेनयोः उभयोः अपि ॥\n\nकृष्णेन रथः अर्जुनस्य आत्मीयबन्धूनाम् एव समक्षं स्थापितः, अतः अर्जुनः तत्र समवेतान् सर्वान् पश्यति — पितृतुल्यान्, पितामहान्, विद्यादातॄन् आचार्यान्, मातुलान्, भ्रातॄन्, पुत्रान्, पौत्रान्, सखीन्, श्वशुरान्, सुहृदः च — उभयोः सेनयोः। यावत्कालं दर्पवचनम् उक्तवते अर्जुनाय अधुना स्वसमक्षे स्थिताः एते सर्वे स्नेहबन्धवः दृश्यन्ते। सूक्ष्मदृष्ट्या अत्र द्रष्टव्यम् — रणभूमौ अनेके प्रमुखाः जनाः सन्ति अपि, अर्जुनाय केवलं गुरवः, बन्धवः, आत्मीयाः एव दृश्यन्ते — इदम् एव तस्य बन्धुप्रेमजागृतेः लक्षणम्। कर्तव्यनिरतस्य प्रजापालकस्य राज्ञः बन्धुप्रेमं न उचितम्।",
  "1.27": "तान् समीक्ष्य सः कौन्तेयः सर्वान् बन्धून् अवस्थितान् ।\n\nकृपया परया आविष्टः विषीदन् इदम् अब्रवीत् ॥\n\nतान् सर्वान् बन्धून् एकत्र स्थितान् दृष्ट्वा कौन्तेयः अर्जुनः परया कृपया आविष्टः विषीदन् एवं कृष्णं प्रति स्वहृदयं निवेदयति। अत्रतः परम् अर्जुनः बहुधा स्वदुःखं श्रीकृष्णस्य समक्षं निवेदयति। किन्तु अत्र एकं विश्लेषणं आवश्यकम् — यदि अर्जुनः सामान्यजनः स्यात्, तर्हि तस्य वचनम् अङ्गीकार्यम् एव आसीत्। किन्तु सः भरतखण्डस्य रक्षकः, धर्मराजस्य पक्षे युद्धाय स्थितः राजा। यदि सः वदेत् 'अस्मदर्थं भरतखण्डजनाः न म्रियन्ताम्' इति, तदा अङ्गीकार्यम् आसीत्। किन्तु तत् न उक्तवान् — तस्य दृष्टौ केवलं बन्धवः एव आसन्। राज्ञः धर्मपक्षे स्थितः एव बन्धुः, धर्मविरुद्धं यः कोऽपि स्थितः सः अपराधी एव — न्यायाधीशवत् राज्ञा अपि धर्मः एव द्रष्टव्यः, न बन्धुत्वम्। अग्रे अर्जुनः बहुभिः तर्कैः कृष्णं प्रबोधयितुं यतते, किन्तु कृष्णः कुत्रापि तेभ्यः तर्केभ्यः प्रत्युत्तरं न ददाति — कारणं यत् तथा कृते सः अनुचिततर्कं समर्थयेत् इव स्यात्। मानसिकतुमुले स्थितस्य अर्जुनस्य वचनं श्रोतृवत् शृण्वन्, पश्चात् मानसरोगिणे चिकित्सकवत् कृष्णः आचरति।",
  "1.28": "अर्जुनः उवाच —\n\nदृष्ट्वा इमम् स्वजनम् कृष्ण युयुत्सुम् समुपस्थितम् ॥\n\nसीदन्ति मम गात्राणि मुखम् च परिशुष्यति ।\n\nवेपथुः च शरीरे मे रोम हर्षः च जायते ॥\n\n[बन्नञ्जेगोविन्दाचार्यैः १.२८ इति १.२९ इति च श्लोकौ एकत्र व्याख्यातौ। व्याख्यानम् अस्मिन् एव १.२८ श्लोके अन्तर्भूतम्।]\n\n'कृष्ण, युद्धोत्साहेन अत्र समवेतान् अस्मदीयान् जनान् दृष्ट्वा मम गात्राणि सीदन्ति, मुखं च परिशुष्यति, शरीरे वेपथुः रोमहर्षः च जायते' इति अर्जुनः वदति। सः वदति — 'अत्र समवेतान् मम ज्येष्ठबन्धून् दृष्ट्वा मम अङ्गानि संकुचन्ति। परस्परं स्नेहेन जीवितव्यान् वयम् अद्य अस्मिन् रणभूमौ सम्मुखं योद्धुं स्थिताः, इति दृष्ट्वा मम मुखं लज्जया म्लायते। ज्ञानवन्तः वयमेव एतादृशं अकार्यं कर्तुम् उद्युक्ताः! एतत् निर्णयं वयमेव कृत्वा तस्मिन् बद्धाः रणभूमौ स्थिताः। स्वजनान् दृष्ट्वा शरीरं संकुचति, मुखं शुष्कं भूत्वा वक्तुम् अपि न शक्नोमि। कीदृशीं निम्नावस्थां प्राप्ताः वयम्! इदं चिन्तयन्तः मे कम्पः जायते' इति। अत्र अर्जुनस्य वचने प्रथमम् अनुकम्पा, ततः लज्जा, ततः भयं, ततः विस्मयः क्रमेण व्यज्यते।",
  "1.29": "[बन्नंजे गोविन्दाचार्यभाष्ये श्लोकौ १.२८ १.२९ इति एकत्र व्याख्यातौ। व्याख्यानम् १.२८ श्लोके एव अन्तर्भूतम्।]",
  "1.30": "गाण्डीवम् स्रंसते हस्तात् त्वक् च एव परिदह्यते ।\n\nनच शक्नोमि अवस्थातुं भ्रमति इव च मे मनः ॥\n\nआत्मविश्वासं हारितस्य पुंसः आन्तरिकानुभवः देहेन कथं प्रकटीभवति इति अत्र द्रष्टव्यम्। निर्विश्वासः जनः स्वमुष्टिं दृढं धर्तुं न शक्नोति। अर्जुनस्य अवस्था अपि तादृशी एव। सः वदति — 'गाण्डीवं मम हस्तात् स्रंसते, सर्वं शरीरं दह्यमानम् इव अनुभवामि' इति। एतत् अन्तरस्थभावस्य तुमुलस्य अभिव्यक्तिः। एकदा मनः अस्थिरं भवति चेत् देहः अपि अस्थिरः भवति, तथैव देहे अस्थिरे मनसः स्थैर्यम् अपि असम्भवम्। 'अस्मिन् रथे स्थातुम् अपि न शक्नोमि, मनः भ्रान्तम्' इति कृष्णं प्रति अर्जुनः परितप्यते।",
  "1.31": "निमित्तानि च पश्यामि विपरीतानि केशव ।\n\nन च श्रेयः अनुपश्यामि हत्वा स्वजनम् आहवे ॥\n\n'निमित्तानि' इति शकुनानि। अत्र अर्जुनः पूर्वदृष्टानि दुर्निमित्तानि स्मरति, यानि सः रणभूमिम् आगमनात् पूर्वम् एव लक्षितवान्, किन्तु अधुना एव तानि स्मरति। पुरातनाः जनाः शकुनेभ्यः बहु महत्त्वं ददति स्म, यतः अस्मिन् जगति सर्वं परस्परं सम्बद्धम्, परमाणुतः ब्रह्माण्डपर्यन्तं सर्वं गणितबद्धम्। अत एव किमपि आकस्मिकं नास्ति — अज्ञानात् एव तत् अस्मभ्यम् आकस्मिकम् इव भाति। महाभारतकाले दृष्टानि कानिचन निमित्तानि — गजाश्वाः युद्धात् पूर्वं अश्रूणि मुमुचुः, शृगालाः सेनां परितः रुदन्ति स्म। पशवः रक्तपातस्य मृत्योः च पूर्वसूचनां ग्रहीतुं शक्नुवन्ति। त्रयोदशदिनान्तरे द्वे ग्रहणे अपि तस्मिन् काले अभवताम् — मृत्युसूचकम् एतत् भीषणं निमित्तम्, यत् व्यासः पूर्वम् एव धृतराष्ट्राय कथितवान्। एवं पूर्वदृष्टानि निमित्तानि स्मृत्वा अर्जुनः कृष्णं 'केशव' इति सम्बोधयति — 'का' अर्थात् सृष्टिकर्ता ब्रह्मा, 'ईश' अर्थात् संहारकर्ता शङ्करः; केशवः अर्थात् सृष्टिसंहारयोः कारणभूता परा शक्तिः। 'भूम्यर्थं आनन्दं त्राणं दातुम् अवतीर्णः त्वम् एव अस्य महायुद्धस्य सूत्रधारः किमर्थम् अभवः?' इति एतस्य सम्बोधनस्य ध्वनिः।",
  "1.32": "न काङ्क्षे विजयम् कृष्ण न च राज्यम् सुखानि च ।\n\nकिम् नः राज्येन गोविन्द किम् भोग्यैः जीवितेन वा ॥\n\nअर्जुनः धर्मराजस्य पक्षे युद्धाय स्थितः। युद्धस्य स्थगनं वा निर्णयः वा धर्मराजस्य विवेकानुसारं एव भवितव्यः। अत्र अर्जुनः स्वयम् एव निर्णायकः इव वदति — 'कस्मै अपेक्षिता एषा विजयः, हे कृष्ण? मह्यं विजयः न अपेक्षितः, गुरुहितान् हत्वा विजयं न कामये' इति। अत्र सः पुनः 'कृष्ण' इति सम्बोधयति — कृष्णः अर्थात् आकर्षकः, स्वसौन्दर्येण आकृष्य उत्कर्षणं कुर्वन्। 'लोकाकर्षणशक्ते त्वं अस्मान्, एतत् अष्टादशाक्षौहिणीसैन्यम्, रणभूमौ किमर्थं आकृष्य आनयः?' इति भावार्थे अर्जुनः वदति। अग्रे सः वदति — 'किं फलं अस्मभ्यं राज्यप्राप्त्या? राज्यं भोगं वा प्राप्य किं प्रयोजनं, हे गोविंद?' इति। अत्र भगवन्तं 'गोविंदः' इति सम्बोधयति — गोविन्दः अर्थात् वेदैः वाच्यः, वेदार्थज्ञः, भूमिम् अवतीर्णः, गोपालकः च। कृष्णः बहून् दुष्टान् असुरान् राज्ञः च संहृतवान्, किन्तु कुत्रापि सिंहासनम् आरुह्य राज्यं न कृतवान् — गोपालकैः सह गाः एव रक्षितवान्। 'तव इव मम अपि सिंहासनारोहणेच्छा नास्ति। भूमौ अवतीर्णः त्वं मां किमर्थं युद्धाय प्रेरयसि?' इति भावेन अर्जुनः भगवन्तं 'गोविंद' इति सम्बोधयति।",
  "1.33": "येषाम् अर्थे काङ्क्षितं नः राज्यं भोगाः सुखानि च ।\n\nते इमे अवस्थिताः युद्धे प्राणान् त्यक्त्वा धनानि च ॥\n\n'येषां कृते राज्यं भोगान् सुखानि च वयं कामयामहे, त एव इमे प्राणधनयोः मोहं त्यक्त्वा युद्धाय स्थिताः' इति अर्जुनः वदति। यदि राज्यभोगः अपेक्षितः, कस्य कृते? गुरुहितानां मध्ये सन्तोषेण जीवितव्यम्, तान् हत्वा कीदृशं सौख्यम्? येषां कृते जीवनसौख्यं साम्राज्यं च कामयामहे, त एव सर्वे प्राणधनयोः निरपेक्षाः भूत्वा अस्मत्समक्षे युद्धाय स्थिताः सन्ति।",
  "1.34": "आचार्याः पितरः पुत्राः तथा एव च पितामहाः ।\n\nमातुलाः श्वशुराः पौत्राः स्यालाः सम्बन्धिनः तथा ॥\n\nअर्जुनः स्वबन्धूनां, कुटुम्बसदस्यानां सूचीं कृष्णस्य समक्षं वदति — आचार्याः, पितृतुल्याः, पुत्राः, पितामहाः, मातुलाः, श्वशुराः, पौत्राः, स्यालाः, सम्बन्धिनः च। एवं केवलं स्वसम्बन्धिनां सूचीं वदन् अर्जुनः स्वसामाजिकं कर्तव्यं विस्मृत्य वैयक्तिकरूपेण एव वदति इति अत्र स्पष्टं भवति।",
  "1.35": "एतान् न हन्तुम् इच्छामि घ्नतः अपि मधुसूदन ।\n\nअपि त्रैलोक्य राज्यस्य हेतोः किम् नु महीकृते ॥\n\n'हे मधुसूदन, एते मां घ्नन्तः अपि अहम् एतान् हन्तुं न इच्छामि। त्रैलोक्यराज्यस्य कृते अपि न, किं पुनः भूमेः कृते?' इति अर्जुनः वदति। अत्र सः कृष्णं 'मधुसूदनः' इति सम्बोधयति — मधु अर्थात् आनन्दः, मधुसूदनः अर्थात् धर्ममार्गं त्यक्त्वा मदेन गच्छताम् आनन्दस्य नाशकः, सज्जनानाम् उद्धारकः आनन्दस्वरूपः भगवान्। 'सात्त्विकेभ्यः आनन्दं दत्त्वा तामसानाम् आनन्दं हरन् त्वं किमर्थं अत्र आगतः?' इति एतस्य सम्बोधनस्य ध्वनिः। 'युद्धं कर्तव्यं न वा' इति संशयः मां बाधते इति अर्जुनः स्वतुमुलं कृष्णाय निवेदयति।",
  "1.36": "निहत्य धार्तराष्ट्रान् नः का प्रीतिः स्यात् जनार्दन ।\n\nपापम् एव आश्रयेत् अस्मान् हत्वा एतान् आततायिनः ॥\n\n'धार्तराष्ट्रान् हत्वा नः का प्रीतिः, हे जनार्दन? एतान् आततायिनः हत्वा पापम् एव अस्मान् आश्रयेत्' इति अर्जुनः वदति। अत्र 'आततायी' इति पदं प्रयुक्तम् — गृहदाहकः, अन्नविषदाता, परस्वापहर्ता, परस्त्रीगामी च आततायी उच्यते। शास्त्रं आततायिनं दृष्ट्वा हन्तुम् आज्ञापयति। दुर्योधनः एतानि सर्वाणि कर्माणि कृतवान् — भीमाय विषं दत्तवान्, द्रौपद्याः वस्त्रापहरणं कृतवान्, पाण्डवानां लाक्षागृहं दग्धवान्। तथापि अर्जुनस्य बन्धुप्रेम एतावत् बाधते यत् सः वदति — 'एते आततायिनः अपि, मम पितृव्यस्य पुत्राः न वा?' इति। अत्र सः कृष्णं 'जनार्दनः' इति सम्बोधयति — दुर्जनसंहारकः, सज्जनेभ्यः पुनर्जन्मरहितं मोक्षप्रदं मरणं ददाति यः सः। 'मोक्षप्रदः त्वं पुनः जन्ममरणचक्रे प्रवर्तमानम् इदं युद्धं अस्मान् किमर्थं कारयसि? युद्धं कदापि मोक्षप्रदं न भवति, तत् वैरद्वेषयुक्तम् एव भवति' इति एतस्य सम्बोधनस्य ध्वनिः।",
  "1.37": "तस्मात् न अर्हा वयम् हन्तुम् धार्तराष्ट्रान् स्व बान्धवान् ।\n\nस्व जनम् हि कथम् हत्वा सुखिनः स्याम माधव ॥\n\n'अतः स्वबान्धवान् धार्तराष्ट्रान् वयं हन्तुं न अर्हाः। स्वजनान् हत्वा वयं कथं सुखिनः स्याम, हे माधव?' इति अर्जुनः वदति। धार्तराष्ट्राः अस्माकं भ्रातरः, तान् हन्तुं न योग्यम्। स्वजनान् हत्वा कथं वयं सुखिनः भवेम — इति अर्जुनस्य प्रश्नः। सूक्ष्मदृष्ट्या अत्र स्पष्टं भवति यत् अर्जुनः स्वस्य प्रजापालकत्वं, धर्मरक्षणं स्वकर्तव्यम् इति सर्वं विस्मृत्य एव वदति।\n\nअत्र अर्जुनः कृष्णं 'माधवः' इति सम्बोधयति। 'मा' अर्थात् माता लक्ष्मीः, अतः माधवः लक्ष्मीपतिः भगवान्। 'मा' अर्थात् ज्ञानम् अपि — भगवान् ज्ञानस्य स्वामी, अतः सः माधवः। मधुवंशे अवतीर्णत्वात् अपि सः माधवः इति उच्यते। वेदे 'मातृ' इति पदं वाक् वा वाङ्मयम् इति अर्थे प्रयुक्तम् — समस्तवैदिकवाङ्मयप्रतिपाद्यः भगवान् माधवः। अर्जुनः कृष्णं बहुशः विविधैः विशेषणैः सम्बोधयति, यतः सः कृष्णं केवलं मातुलपुत्रम् इति न, अपि तु अतिमानुषशक्तिः इति जानाति। एतत् एव विचित्रम् — भगवत्सान्निध्ये स्थितः महाज्ञानी अर्जुनः अपि प्रतिक्षणं संभ्रान्तः भवति। मायायाः एषा विचित्रता — मृत्तिकां भक्षितवतः श्रीकृष्णस्य मुखे विश्वरूपं दृष्ट्वा अपि यशोदा तं शिक्षितुम् उद्युक्ता भवति, यतः सा 'मम शिशुः' इति स्नेहमायायां स्थिता। अर्जुनस्य अवस्था अपि तादृशी एव।",
  "1.38": "यदि अपि एते न पश्यन्ति लोभ उपहत चेतसः ।\n\nकुलक्षय कृतम् दोषम् मित्रद्रोहे च पातकम् ॥\n\n'एतेषां हृदयं लोभेन ग्रस्तम्, अतः कुलक्षयकृतं दोषं मित्रद्रोहजन्यं च पातकं ते न पश्यन्ति' इति अर्जुनः वदति। धनलोभेन अन्धीभूतं तेषां मनः विवेकशक्तिं हारितम्। तेन कुलक्षयः भविष्यति, सम्पूर्णं भरतकुलं निर्वंशं भविष्यति। बन्धुभिः वयं परस्परं मित्रवत् स्नेहेन जीवितव्याः आस्म, किन्तु अधुना परस्परं द्वेष्मः — इदम् एव द्रोहः। अत्र 'मित्र' इति पदं प्रयुक्तम् — कः वास्तविकः मित्रः? यः अस्मत्तः पूर्वम् एव आपदं आशङ्क्य, निष्कामभावेन, प्राणार्थं प्राणं ददाति सः एव मित्रम्।",
  "1.39": "कथम् न ज्ञेयम् अस्माभिः पापात् अस्मात् निवर्तितुम् ।\n\nकुलक्षय कृतम् दोषम् प्रपश्यद्भिः जनार्दन ॥\n\n'हे जनार्दन, कुलक्षयजन्यं दोषं पश्यद्भिः अस्माभिः एतस्मात् पापात् निवर्तितुं कथं न ज्ञायते?' इति अर्जुनः वदति। एतादृशं महापापं न कर्तव्यम् इति यदि वयं न जानीमः, तर्हि दुर्योधनस्य अस्माकं च भेदः कः? जन्ममृत्युबन्धनात् त्रातारं हे जनार्दन, कुलनाशकः दोषः मम दृष्ट्या स्पष्टः दृश्यते। युद्धानिष्टं ज्ञात्वा अपि यदि वयं तत्रैव प्रवर्तेमहि, तर्हि दुर्योधनवत् एव वयम् अधोगच्छामः न वा? इति अर्जुनस्य प्रश्नः।",
  "1.40": "कुलक्षये प्रणश्यन्ति कुल धर्माः सनातनाः ।\n\nधर्मे नष्टे कुलम् कृत्स्नम् अधर्मः अभिभवति उत ॥\n\nयुद्धेन बृहत्तमः दोषः 'कुलधर्मस्य' नाशः। अत्र अर्जुनः धर्मविषये कतिपयान् शब्दान् प्रयुङ्क्ते — जातिधर्मः, कुलधर्मः, सनातनधर्मः च। एतेषां बोधाय प्रथमं धर्मस्य स्वरूपं तस्य भेदाश्च ज्ञातव्याः। सामान्यतः जातिधर्मशब्देन ब्राह्मणक्षत्रियवैश्यशूद्रादिवर्णाः स्मर्यन्ते, कुलधर्मशब्देन च वंशपरम्परया प्राप्तं वृत्तिकर्म (यथा सूत्रकारस्य, कर्मकारस्य, चर्मकारस्य वा कुलगतं कर्म) — किन्तु अत्र नैतत् अभिप्रेतम्। अत्र कुलधर्मः अर्थात् समाजधर्मः (Religion of Society), जातिधर्मः अर्थात् जन्मना प्राप्तः स्वभावः — प्रत्येकस्य जीवस्य स्वकीयः सहजस्वभावः, यः अनुवंशेन परिवेशप्रभावेन च द्वाभ्यां आवरणाभ्यां आवृतः दुर्ज्ञेयश्च भवति। समाजधर्मः — वयं न एकाकिनः जीवामः, अतः संगठनार्थं पृथक् धर्मः, यत्र व्यक्तिधर्मः (वैयक्तिकी रुचिः) समाजधर्मार्थं परिवर्तनीयः (यथा उच्चैः भाषणं मम व्यक्तिधर्मः, किन्तु चिकित्सालये मौनपालनं समाजधर्मः)। समाजधर्मः कालदेशानुगुणं परिवर्तते — यथा विवाहधर्मः, कस्मिन् वयसि विवाहः कर्तव्यः इति कालानुगुणं भिद्यते। वेदकाले बालविवाहप्रथा आसीत्, यतः गुरुकुलपद्धतौ पुरुषाः अष्टमवर्षतः विंशतिवर्षपर्यन्तं गुरुकुले अधीत्य (समावर्तनं कृत्वा) गृहं प्रत्यागच्छन्ति स्म, तेभ्यश्च अष्टवर्षीयाः कन्याः शिष्यात्वेन दत्ताः प्रौढवयसि दाम्पत्यं प्रापयन्ति स्म — रामायणमहाभारतकालेऽपि बालविवाहः नासीत्, गुरुकुलपद्धतेः समाप्त्या सह सा अपि समाप्ता, पुनः सहस्रवर्षेभ्यः पूर्वं विदेशाक्रमणकाले सामाजिकदबावेन प्रवृत्ता — एवं समाजधर्मः समयानुगुणं समाजानुगुणं च परिवर्तते। सनातनधर्मः तु शाश्वतः, सर्वकाले सर्वदेशे च अपरिवर्तनीयः (यथा सत्यवचनं, अस्तेयं, ईश्वरश्रद्धा) — वेदः सनातनधर्मम् एव उपदिशति। जातिधर्मः समाजधर्मानुगुणं, समाजधर्मश्च सनातनधर्मानुगुणं योजनीयः। वस्तुनः असाधारणं लक्षणम् एव तस्य धर्मः — यथा दर्शनं चक्षुषः धर्मः, श्रवणं श्रोत्रस्य धर्मः; किन्तु यः धर्मः सः एव सीमातिक्रमे अधर्मः भवति — अद्रष्टव्यस्य दर्शनम् अधर्मः, दर्शनस्य अपि सीमा वर्तते, तस्याः अतिक्रमे धर्मः एव अधर्मः भवति। एवं कुलक्षये सति सनातनाः कुलधर्माः नश्यन्ति, धर्मे नष्टे च सम्पूर्णं कुलम् अधर्मः आक्रामति — इति अर्जुनः वदति। 'कुलक्षये समाजधर्मपालिका न्यायव्यवस्था नश्यति, समाजधर्मः नश्यति, सामाजिकव्यवस्था विशीर्यते, सम्पूर्णः समाजः अधर्मे निमज्जति — इदम् एव युद्धेन समाजाय दीयमानम् अस्मदीयम् उपहारः' इति सः वदति।",
  "1.41": "अधर्म अभिभवात् कृष्ण प्रदुष्यन्ति कुलस्त्रियः ।\n\nस्त्रीषु दुष्टासु वार्ष्णेय जायते वर्णसङ्करः ॥\n\nयुद्धेन युवानः म्रियन्ते, अधर्मः समाजम् आक्रामति, अयुवसमाजः निर्मीयते, स्त्रीभ्यः सामाजिकं संरक्षणं नश्यति, तेन तासां मुग्धतायाः दुरुपयोगः भवति, ततः समाजे वर्णसंकरः जायते इति अर्जुनः वदति। वर्णसंकरः अर्थात् जीवस्य वर्णस्य (स्वभावस्य) विकृतिः। शास्त्रेषु उक्तम् — स्त्रियाः स्वेच्छाविरुद्धं बलात् उच्चशिक्षणं न दातव्यम्, यतः तेन तस्याः गर्भकोशे परिणामः भवति, तस्य च परिणामः जनिष्यमाणे शिशौ भवति। यदा स्त्री अनिच्छया एव प्रवृत्ता भवति, बहुपुरुषसंसर्गं च करोति, तदा भाविसन्तानस्य उपरि घोरः परिणामः भवति — केनापि वचनेन अनियन्त्रिता, कस्यापि नियमस्य अवशा विक्षिप्ता सन्ततिः जन्म लभेत। एतत् एव अत्र अर्जुनोक्तः वर्णसंकरः। अत्र अर्जुनः कृष्णं 'वार्ष्णेयः' इति सम्बोधयति — वृष्णिवंशे अवतीर्णत्वात्। 'सर्वेषाम् अभीष्टं पूरयन्, धर्मसंस्थापनार्थम् अवतीर्णः त्वं इदं युद्धं किमर्थं न निवारयसि?' इति एतस्य सम्बोधनस्य ध्वनिः।",
  "1.42": "सङ्करः नरकाय एव कुलघ्नानाम् कुलस्य च ।\n\nपतन्ति पितरः हि एषाम् लुप्त पिण्ड उदक क्रियाः ॥\n\nवर्णसंकरेण कुलघ्नाः कुलं च नरकाय एव भवन्ति — एतेषां पितरः पिण्डोदकक्रियारहिताः पतन्ति। विक्षिप्तानां सन्तानानां जन्मना समाजः नरकतुल्यः भवति, तस्य कारणभूताः वयम् अपि नरकं गच्छामः। पिण्डः अर्थात् किम्, तस्य महत्त्वं किम् — इति ज्ञातव्यम्। स्थूलः पिण्डः मृतजीवं प्रत्यक्षं न गच्छति। जीवः स्वकर्मानुसारं यत्र गन्तव्यं तत्र गच्छति। पिण्डदानं पितृदेवताभ्यः क्रियते — एतत् देवतागणं शतसंख्यम्, तत्र त्रयः प्रधानाः पितरः। एते पितरः स्थूलशरीरत्यागानन्तरं जीवं रक्षन्ति। एतान् वसुरुद्रादित्याः नियन्त्रयन्ति। यदि हिरिजनानां मार्गे कश्चन बाधकः स्यात्, तत्परिहारार्थं एव पिण्डप्रदानम्।",
  "1.43": "दोषैः एतैः कुलघ्नानाम् वर्णसङ्करकारकैः ।\n\nउत्साद्यन्ते जातिधर्माः कुलधर्माः च शाश्वताः ॥\n\nवर्णसंकरकारकैः कुलघ्नानाम् एतैः दोषैः जातिधर्माः शाश्वताः कुलधर्माः च उन्मूल्यन्ते। युद्धस्य समाजे प्रत्यक्षः परिणामः — नायकरहितः, युवारहितः समाजः, स्त्रीपुरुषानुपातस्य विषमता। महाभारतयुद्धे न्यूनातिन्यूनं पञ्चाशल्लक्षजनाः मृताः। तादृशेन महायुद्धेन सम्पूर्णं समाजं नाशयन्तः कुलकण्टकाः वयं भवामः इति अर्जुनस्य चिन्ता। 'सामाजिकव्यवस्थायाः नाशेन स्वभावः नश्यति, व्यक्तित्वविकासः बाध्यते, शाश्वतमूल्ययुक्तः समाजधर्मः नश्यति, अनादिकालात् समाजेन स्वीकृतः स्थिरधर्मः प्रवाहितो भवति' इति अर्जुनः कृष्णस्य समक्षं स्ववादं मण्डयति।",
  "1.44": "उत्सन्न कुलधर्माणाम् मनुष्याणाम् जनार्दन ।\n\nनरके नियतम् वासः भवति इति अनुशुश्रुम ॥\n\n'हे जनार्दन, कुलधर्मरहितानां मनुष्याणां नियतं नरकवासः भवति इति वयं शुश्रुम' इति अर्जुनः वदति। इह अपि नरकः, पर अपि नरकः — सर्वदा नरके एव वयं निवसामः इति ज्ञानिनः वदन्ति, तत् मया श्रुतम्। एवं इह पर च नरकाय वयम् एव कारणं भवामः।",
  "1.45": "अहो बत महत् पापम् कर्तुम् व्यवसिताः वयम् ।\n\nयत् राज्यसुखलोभेन हन्तुम् स्वजनम् उद्यताः ॥\n\nक्षीणस्वरेण अर्जुनः वदति — 'अहो! कीदृशं महापापं कर्तुं वयम् उद्युक्ताः आस्म! कीदृशं प्रमादं करिष्यत् आस्म! राज्यसुखलोभेन स्वजनान् एव हत्वा सम्पूर्णं जनाङ्गम् अधःपातं नेतुम् उद्यताः आस्म' इति।",
  "1.46": "यदि माम् अप्रतीकारम् अशस्त्रम् शस्त्रपाणयः ।\n\nधार्तराष्ट्राः रणे हन्युः तत् मे क्षेम तरम् भवेत् ॥\n\n'अहं प्रतीकारं न करिष्यामि। यदि ते मां हन्तुम् आगच्छेयुः, अहम् अपि प्रत्याघातं न करिष्यामि। शस्त्रपाणिभिः धार्तराष्ट्रैः निःशस्त्रं मां रणे हतम् अपि तत् मे क्षेमतरं भवेत्' इति अर्जुनः हस्तौ त्यजति। यौद्धारम्भे दर्पेण 'सेनयोरुभयोर्मध्ये रथं स्थापय मे अच्युत' इति उक्तवान् अर्जुनः क्षणमात्रेण एव विगलितः अभवत्। एतत् तस्य सुप्तप्रज्ञायां अज्ञातरूपेण निहितं भावम्। कृष्णः स्वमानसचिकित्सया तत् सम्पूर्णं बहिः आनयत् — मानसिकसंघर्षग्रस्तस्य एतत् एव प्रथमा चिकित्सा। मनोरोगस्य निवारणं जगते दर्शितवान् प्रथमः महामनोवैज्ञानिकः कृष्णः एव।",
  "1.47": "सञ्जय उवाच —\n\nएवम् उक्त्वा अर्जुनः सङ्ख्ये रथ उपस्थे उपाविशत् ॥\n\nविसृज्य सशरम् चापम् शोक संविग्न मानसः ॥\n\nरथे स्थित्वा एव एतावत् उक्त्वा, अर्जुनः रथमध्ये विगलितः उपाविशत्। सर्वाणि शस्त्राणि त्यक्त्वा, हस्तौ त्यक्त्वा उपविष्टः। अस्मिन् अध्याये अर्जुनः स्वसर्वभावान् कृष्णस्य समक्षं उद्घाटितवान्। अर्जुनेन उक्तं प्रत्येकं विषयम् अस्माभिः ज्ञातम्, किन्तु अग्रे कृष्णः यत् वदति तत् अज्ञातम्। अन्धकारात् प्रकाशं प्रति नयत् भगवतः उत्तरं वयम् अग्रिमेषु अध्यायेषु द्रक्ष्यामः।\n\nअग्रिमाध्यायं गन्तुं पूर्वं लघुविश्लेषणम्। अस्माकं बहूनां संशयः — रणभूमौ कृष्णार्जुनयोः एतत् सप्तशतश्लोकात्मकं संवादं कथं जातम्? किं तयोः तावान् कालः आसीत्? अस्य प्रश्नस्य उत्तरं ज्ञातुं महाभारतकालीनं युद्धपद्धतिं ज्ञातव्यम्। तत्कालिकनियमानुसारं युद्धे अप्रस्तुतं शत्रुं न आक्रमेत्, एकः सज्जः यावत् न भवति तावत् युद्धं न आरभ्यते। अर्जुनः तत्कालीनमहामेधाविषु अन्यतमः। अत्र संवादः द्वयोः मेधाविनोः मध्ये। तादृशं ज्ञानस्तरम् अद्य कल्पयितुम् अपि दुष्करम्। तयोः सम्पूर्णसंवादः अद्यत्वे दृश्यमानसप्तशतश्लोकरूपेण न अभवत् — वेदव्यासः तं संवादम् अस्मभ्यं बोधगम्यरूपेण सप्तशतश्लोकैः प्रस्तुतवान्, इत्येव। अद्यत्वे अपि एतत् श्लोकं वयं न बुध्यामहे, अत एव गीताभाष्यं सहस्रशः पृष्ठेषु दृश्यते। किन्तु महामेधाविनः एतत् अतिसंक्षिप्तेन अतिस्वल्पेन कालेन वक्तुं ग्रहीतुं च शक्नुवन्ति। कृष्णार्जुनयोः संवादः अपि तादृशः विषयगर्भितः संक्षिप्तः संवादः एव।\n\nअन्यत् मुख्यं प्रश्नम् — गीता कृष्णेन अर्जुनाय एव किमर्थं उक्ता? तस्य अग्रजाय भीमाय अन्येभ्यः वा किमर्थं न उक्ता? अस्य उत्तरं सुलभम् — रोगिणे एव औषधम्, न अन्येभ्यः। तत्र मानसिकतुमुले स्थितः अर्जुनः एव आसीत्। अत एव श्रीकृष्णः अर्जुनाय (तन्मुखेन अस्मभ्यम्) गीतोपदेशं कृतवान्।",
  "2.1": "[द्वितीयाध्यायस्य बन्नञ्जे-पीठिका]\n\nयुद्धं न करिष्यामि इति शस्त्राणि त्यक्त्वा रथे उपविष्टाय अर्जुनाय कृष्णस्य उपदेशः अस्मात् द्वितीयाध्यायात् आरभ्यते। अयम् अध्यायः सम्पूर्णगीतायाः पञ्चाङ्गरूपः- अत्र व्यासः समग्रसन्देशस्य सारं संगृह्य स्थापितवान्। अत्रोक्तस्य उपदेशस्य विस्तृतं रूपम् एव शेषाः षोडश अध्यायाः।\n\nसञ्जय उवाच —\n\nतम् तथा कृपया आविष्टम् अश्रु पूर्ण आकुल ईक्षणम् ।\n\nविषीदन्तम् इदम् वाक्यम् उवाच मधुसूदनः ॥\n\nकृपया आविष्टं, अश्रुपूर्णाकुलनेत्रं, विषीदन्तं तं दृष्ट्वा मधुसूदनः इदं वाक्यम् अब्रवीत् — इति संजयः वदति।",
  "2.2": "भगवान् उवाच —\n\nकुतः त्वा कश्मलम् इदम् विषमे समुपस्थितम् ।\n\nअनार्य जुष्टम् अस्वर्ग्यम् अकीर्ति करम् अर्जुन ॥\n\n'हे अर्जुन, एतादृशे संकटे अनार्यसेवितम्, अस्वर्ग्यम्, अकीर्तिकरं च इदं कश्मलं कुतः त्वयि समुपस्थितम्?' इति भगवान् वदति। 'कुतः इयं बुद्धिः त्वयि आगता? एतत् भौतिकं कश्मलं त्वयि कथम् आसक्तम्? एतादृश्याम् आपत्काले, तत्क्षणं कार्यप्रवृत्तेन भवितव्ये क्षणे — किम् इदं मलिनं चिन्तनम्? आर्याः कदापि एवं न चिन्तयन्ति। एतादृशेन विचारेण पर​त्र स्वर्गः न, इह च कीर्तिः न। ज्ञानिनः वयोवृद्धाः च कदापि एवं न चिन्तयन्ति' इति निष्ठुरवचनेन कृष्णः अर्जुनस्य सम्पूर्णं वादं एकेनैव वचसा खण्डितवान्। अत्र प्रयुक्तः 'आर्य' शब्दः जातिवाचकः न — आर्यः अर्थात् ज्ञानवान्, वयोवृद्धः, गौरवान्वितः।",
  "2.3": "क्लैब्यम् मा स्म गमः पार्थ न एतत् त्वयि उपपद्यते ।\n\nक्षुद्रम् हृदय दौर्बल्यम् त्यक्त्वा उत्तिष्ठ परन्तप ॥\n\n'हे पार्थ, क्लैब्यं मा गमः, त्वयि एतत् न उपपद्यते। हे परन्तप, हृदयस्य क्षुद्रं दौर्बल्यं त्यक्त्वा उत्तिष्ठ' इति भगवान् वदति। \"नपुंसकवत् मा वद। अर्जुने एतादृशं कापुरुषत्वं मया न अपेक्षितम्। एतादृशं क्षुद्रं मानसिकदौर्बल्यं त्यक्त्वा, वीरः भूत्वा अन्यायस्य विरुद्धं युध्यस्व\" इति उक्त्वा कृष्णः अर्जुनाय दिग्भ्रान्तिकरं चिकित्सारूपम् (Shock Treatment) प्रयच्छति।\n\nकृष्णः किमर्थम् एवम् अब्रवीत्? किं सः युद्धं रक्तपातं वा कामयते स्म? एतादृशाः प्रश्नाः अस्माकं मनसि उदयन्ते इति स्वाभाविकम्। सूक्ष्मदृष्ट्या पश्येम — यदि युद्धं न भवेत्, अर्जुनेन उक्तात् सामाजिकापायात् दशगुणम् अन्यायम् अभविष्यत्। दुर्योधनः तत्कालीनः महान् लोककण्टकः — परिपूर्णसभायां स्वकीयाम् एव भ्रातृजायां परिभवितुम् उद्युक्तः। तादृशः पुरुषः राजगद्दीम् आरुह्य चेत्, समाजस्य का गतिः स्यात् इति चिन्तयत। अत्र कृष्णस्य आशयः — देशस्य नेतृत्वं कस्य हस्ते भवितव्यम् इति एव, न तु बन्धुप्रेम। जयापेक्षातः अधिकं महत्त्वपूर्णम् — अन्यायस्य विरुद्धं स्वरम् उत्थापनम्। अन्यायेन युध्यमानस्य मरणम् अपि न दोषाय, किन्तु तस्य विरुद्धं स्थातव्यम् एव — इति कृष्णस्य सन्देशः।\n\nमहाभारतद्वारा श्रीकृष्णः अस्मभ्यं धर्मस्य नूतनं सिद्धान्तं दत्तवान्। महाभारतात् पूर्वं धर्मस्य कल्पना भिन्ना आसीत्। यथा सत्यवचनम् — यत् यथावत् वर्तते तत् एव वदनं सत्यम् इति पूर्वं मन्यते स्म। किन्तु कृष्णस्य मतेन — येन असत्येन समाजस्य हितं भवति, तत् एव सत्यम्; येन सत्येन समाजस्य अहितं भवति, तत् एव असत्यम्। तथैव हिंसाविषये — एकया हिंसया बहवः अहिंसाः सम्भवन्ति चेत्, सा एव अहिंसा। यथा — नरभक्षकः व्याघ्रः प्रतिदिनं ग्रामम् आक्रम्य एकैकं जनं भक्षयति चेत्, तस्य वधः प्राणिहिंसा न भवति। एकेन युद्धेन पीढ्यन्तरं यावत् अहिंसा स्थापयितुं शक्यते चेत्, तादृशे युद्धे न दोषः। यतः सज्जनरक्षा भवति, तत् एव सत्यम्। धर्मे भावः एव मुख्यः — केन उद्देश्येन वयं युध्यामहे, तत् एव महत्त्वपूर्णम्।",
  "2.4": "अर्जुनः उवाच —\n\nकथम् भीष्मम् अहम् सङ्ख्ये द्रोणम् च मधुसूदन ।\n\nइषुभिः प्रतियोत्स्यामि पूजार्हा अरिसूदन ॥\n\n'हे मधुसूदन, अरिसूदन, पूजार्हौ भीष्मद्रोणौ रणे इषुभिः कथम् अहं प्रतियोत्स्यामि?' इति अर्जुनः वदति। कृष्णस्य तीक्ष्णोत्तरं तस्य स्मितं च दृष्ट्वा अर्जुनस्य वाचः शैली अधुना परिवर्तते। भावावेशं त्यक्त्वा सः अधुना भावुकतया शरणागतिं प्रति वर्तते।\n\nअर्जुनः वदति — \"मम नेत्रयोः पुरतः स्थितौ भीष्माचार्यौ द्रोणाचार्यौ च कथम् अहं प्रतिकुर्याम्? एकः अस्मद्वंशस्य मूलपुरुषः राजर्षिः; अपरः सर्वेषां क्षत्रियाणां विद्यादाता महर्षिः। तादृशान् पूजार्हान् महनीयान् प्रति कथं बाणान् प्रयोजयेयम्? सृष्ट्यादौ मधुकैटभौ संहृतवन् हे मधुसूदन, दुष्टसंहारार्थम् अवतीर्ण हे अरिसूदन, ज्ञानिनां आचार्याणां च हत्या तव मूलोद्देश्यं न भवति\" इति भिन्नस्वरेण अर्जुनः स्ववचनं प्रवर्तयति।",
  "2.5": "गुरून् अहत्वा हि महानुभावान् श्रेयः भोक्तुम् भैक्ष्यम् अपि इह लोके ।\n\nहत्वा अर्थ कामान् तु गुरून् इह एव भुञ्जीय भोगान् रुधिर प्रदिग्धान् ॥\n\n'एतान् महानुभावान् अहत्वा भैक्ष्यम् अपि भोक्तुं श्रेयः, अस्मिन् लोके। अर्थकामान् गुरून् हत्वा तु रुधिरप्रदिग्धान् भोगान् भुञ्जीय' इति अर्जुनः वदति। गुरून् हत्वा ऐश्वर्यभोगम् अनुभवनात् भैक्षचर्यया जीवनम् एव श्रेयः न वा? यत् सिंहासनं भीष्मद्रोणादीन् अन्तःसत्यसाक्षात्कारिणः महानुभावान् हन्तुं न शक्नोति, तादृशं सिंहासनम् अस्माभिः किमर्थम् अपेक्षितम्? दुर्योधनस्य वेतनदासाः, राजगृहस्य ऋणार्थम् एव युद्धाय स्थिताः एतान् हत्वा सिंहासनम् आरुह्य चेत्, गुरूणां रुधिरेण सिक्तं भोगम् एव भुञ्जीमहि इव भवेत्।",
  "2.6": "न च एतत् विद्मः कतरत् नः गरीयः यत् वा जयेम यदि वा नः जयेयुः ।\n\nयान् एव हत्वा न जिजीविषामः ते अवस्थिताः प्रमुखे धार्तराष्ट्राः ॥\n\n'वयं जयेम, यदि वा वयं जिताः स्याम, तत् एव न जानीमः। यान् हत्वा वयं जीवितुम् अपि न इच्छामः, ते एव धार्तराष्ट्राः अस्मत्समक्षे अवस्थिताः' इति अर्जुनः वदति। अद्यपर्यन्तं स्ववादं मण्डयित्वा अर्जुनः अधुना कृष्णाय शरणं गत्वा 'किं मे श्रेयः' इति पृच्छति। \"वयं युद्धे जयेम इति श्रेयः, अथवा गुरुहिरण्याः जयेयुः इति श्रेयः, तत् न जानीमः। युद्धे जयेच्छा अपि मे नष्टा\" इति स्वमनसः द्वैधीभावं कृष्णस्य समक्षम् अर्जुनः उद्घाटयति। पितृतुल्यः धृतराष्ट्रः, तस्य पुत्राः च अस्मत्समक्षे युद्धाय स्थिताः। यस्य पुत्रार्थं प्राणान् अपि त्यजेम, तादृशस्य अस्मत्पितृव्यस्य विरुद्धं योद्धुम् इच्छा नास्ति इति अर्जुनः वदति।",
  "2.7": "कार्पण्य दोष उपहत स्वभावः पृच्छामि त्वाम् धर्म सम्मूढ चेताः ।\n\nयत् श्रेयः स्यात् निश्चितम् ब्रूहि तत् मे शिष्यः ते अहम् शाधि माम् त्वाम् प्रपन्नम् ॥\n\n'कार्पण्यदोषेण उपहतस्वभावः, धर्मे सम्मूढचेताः त्वां पृच्छामि। यत् निश्चितं श्रेयः स्यात्, तत् मे ब्रूहि। अहं ते शिष्यः, त्वां प्रपन्नं मां शाधि' इति अर्जुनः वदति। \"मयि कार्पण्यदोषः आगतः। किं सम्यक् किं वा अयोग्यम् इति निर्णेतुम् अशक्तः दयनीयावस्थायाम् अस्मि। धर्मविषये मम चिन्तनशक्तिः संभ्रान्तिगृहम् अभवत्। योद्धव्यं न वा इति संशयः मां बाधते। किं मे हितम् इति न जानामि। तव शिष्यः भूत्वा त्वां प्रपन्नः अस्मि — मां मार्गदर्शय\" इति अर्जुनः कृष्णं प्रार्थयते। अद्यपर्यन्तं भगवतः समक्षं पण्डितवत् भाषमाणः अर्जुनः अधुना भगवति शरणागतिं याचमानः स्पष्टं दृश्यते।",
  "2.8": "न हि प्रपश्यामि मम अपनुद्यात् यत् शोकम् उच्छोषणम् इन्द्रियाणाम् ।\n\nअवाप्य भूमौ असपत्नम् ऋद्धम् राज्यम् सुराणाम् अपि च आधिपत्यम् ॥\n\n'मम इन्द्रियाणाम् उच्छोषणकारकं यत् शोकम्, तत् अपनुद्यात् किमपि उपायं न प्रपश्यामि — भूमौ असपत्नं समृद्धं राज्यं सुराणाम् आधिपत्यम् अपि प्राप्य' इति अर्जुनः वदति। \"मम इन्द्रियाणि क्षीणानि भवन्ति। मम शोकं दूरीकर्तुं मार्गम् एव न पश्यामि। भूमौ स्वर्गे वा प्रभुत्वं प्राप्य अपि अहम् एतत् शोकं त्यक्तुं न शक्नुयाम्\" इति अर्जुनः वदति।",
  "2.9": "सञ्जय उवाच —\n\nएवम् उक्त्वा हृषीकेशम् गुडाकेशः परन्तपः ।\n\nन योत्स्ये इति गोविन्दम् उक्त्वा तूष्णीम् बभूव ह ॥\n\n'एवम् उक्त्वा गुडाकेशः परन्तपः हृषीकेशं गोविन्दं प्रति \"न योत्स्ये\" इति उक्त्वा तूष्णीम् बभूव' इति संजयः धृतराष्ट्राय रणभूमौ अर्जुनस्य अवस्थां वर्णयन् वदति। सम्पूर्णं ब्रह्माण्डं व्याप्नुवतः अस्मदिन्द्रियाणां स्वामिनः गोविन्दस्य समक्षं निद्राजयी अर्जुनः \"न अहं योत्स्ये\" इति उक्त्वा मौनी अभवत् — इति सः वदति।",
  "2.10": "तम् उवाच हृषीकेशः प्रहसन् इव भारत ।\n\nसेनयोः उभयोः मध्ये विषीदन्तम् इदम् वचः ॥\n\n'हे भारत, उभयोः सेनयोः मध्ये विषीदन्तं तं प्रति हृषीकेशः स्मितं कुर्वन् इव इदं वचः उवाच' इति संजयः वदति। अर्जुने सम्पूर्णं शरणं गते, स्वसमक्षं दैन्येन स्थिते, श्रीकृष्णः मन्दस्मितं कुर्वन् स्ववचनम् आरभते। अत्र अर्जुनः कृष्णवचनं स्वीकर्तुं सज्जः अभवत् — तस्य भावावेशः निर्गतः, शरणागतिः आगता। यदि भगवान् अस्मभ्यं मार्गदर्शनं कर्तुम् अर्हति, वयम् अहंकारं त्यक्त्वा तस्मिन् सम्पूर्णं शरणागन्तव्याः। तदा एव नः निश्चयेन मार्गदर्शनं लभ्यते। अत्र कृष्णेन अर्जुनाय दत्तम् उपदेशं सर्वेभ्यः अस्मभ्यम् एव दत्तम् इति स्मृत्वा, कृष्णस्य उपदेशं शृणुयाम।",
  "2.11": "भगवान् उवाच —\nअशोच्यानन्वशोचस्त्वं प्रज्ञावादांश्च भाषसे ।\nगतासूनगतासूंश्च नानुशोचन्ति पण्डिताः ॥\n\nएतत् भगवदुपदेशस्य प्रथमं वचनम्, समग्रगीतायाः बीजरूपम्। अर्जुन! अशोच्यान् जनान् त्वं शोचसि, ज्ञानिवत् वदसि च — इदं तव दौर्बल्यस्य दर्पणम्। निहितः प्रश्नः — 'त्वं किमपि न जानासि' इति। अर्जुनस्य दुःखस्य मूलं भयम् — केचन म्रियन्ते, केचन दुष्टाः जीवन्ति इति भयात्। भयस्य मूलम् अज्ञानम् एव।\n\nजीवः अनादिनित्यः, कदापि न म्रियते। शरीरं जीवस्य पञ्जरम् इव — पञ्जरप्रवेशः जन्म, पञ्जरनिर्गमः मरणम्। नूतनवस्त्रधारणम् इव जन्म, जीर्णवस्त्रत्यागः इव मरणम्। एतज्ज्ञानेन मृत्युभयं नश्यति। ज्ञानिनः जन्ममरणरहस्यं विदन्ति; त्वं तु स्वबुद्धिम् एव विश्वसत्यम् इति भ्रान्त्या वदसि। कृष्णः अत्र लौकिकप्रश्नान् त्यक्त्वा अर्जुनाय सत्यसाक्षात्कारं करोति — मरणं न भयावहम्, आत्मा तु अनादिनित्यः, देहनाशः तु अनिवार्यः एव।",
  "2.12": "न त्वेवाहं जातु नासं न त्वं नेमे जनाधिपाः ।\nन चैव न भविष्यामः सर्वे वयमतः परम् ॥\n\nअहं त्वं च इमे नृपाः च पूर्वम् आस्म, सम्प्रति स्मः, भविष्ये अपि भविष्यामः। देहनाशेऽपि जीवः न नश्यति। यथा अहम् अनादिनित्यः तथा प्रत्येकं जीवम् अपि अनादिनित्यम्, आत्मा हन्तुम् अशक्यः। जीवः बीजम् इव, भगवान् उद्यानपाल इव — सः जगदुद्यानं सृष्ट्वा तत्र जीवं रोपयित्वा तस्मै अस्तित्वं ददाति। प्रत्येकं जीवः स्वस्वभावानुसारं वर्धते; एतत्कारणात् एव जगत् एतावद्विचित्रम्।",
  "2.13": "देहिनोऽस्मिन् यथा देहे कौमारं यौवनं जरा ।\nतथा देहान्तरप्राप्तिर्धीरस्तत्र न मुह्यति ॥\n\nयथा एकस्मिन्नेव देहे बाल्यं यौवनं जरा च भवन्ति, तथैव देहान्तरप्राप्तिः। धीरः अत्र न विमुह्यति। देहनाशः स्वरूपनाशः न भवति — देहः प्रतिक्षणं परिवर्तते, बाल्यदेहः यौवने नास्ति, यौवनदेहः जरायां नास्ति। मरणानन्तरं पुनर्जन्मना नूतनदेहः प्राप्यते। नाशरहितं चैतन्यम् एव जीवः। यः धीरः — ज्ञानानन्दानुभवी — सः नश्वरदेहविषये कदापि न शोचति; यत्र ज्ञानं तत्र दुःखं नास्ति।",
  "2.14": "मात्रास्पर्शास्तु कौन्तेय शीतोष्णसुखदुःखदाः ।\nआगमापायिनोऽनित्यास्तांस्तितिक्षस्व भारत ॥\n\nहे कौन्तेय, इन्द्रियविषयसम्पर्काः एव शीतोष्णयोः सुखदुःखयोश्च अनुभवं ददति। एते आगच्छन्ति गच्छन्ति च, न नित्याः। हे भारत, तान् सहस्व। सुखदुःखयोः मूलं मात्रास्पर्श एव — शब्दस्पर्शरूपरसगन्धाः पञ्च मात्राः। सुखदुःखयोः न कोऽपि नियमः; एकस्य सुखं परस्य दुःखं भवितुम् अर्हति। ममत्वबुद्धिः एव दुःखस्य मूलम्; निद्रायां ममत्वं नास्ति, अतः निद्रायां दुःखं नास्ति। एतत्सुखदुःखं स्वमानसकल्पनाफलम् एव — यत् आगतं तत् स्वीकर्तुं शिक्षितव्यम्।",
  "2.15": "यं हि न व्यथयन्त्येते पुरुषं पुरुषर्षभ ।\nसमदुःखसुखं धीरं सोऽमृतत्वाय कल्पते ॥\n\nयं पुरुषं मात्रास्पर्शाः न व्यथयन्ति, यः सुखदुःखे समः, सः धीरः अमृतत्वाय कल्पते। पुरुषशब्दस्य अर्थः पुरे — पूर्णदेहे — वसन् जीवः, न केवलं पुमान्। साधकजीवः एव पुरुषः इत्यर्थः। सुखदुःखयोः कारणज्ञानेन मनुष्यः न हृष्यति न विषीदति च; सुखदुःखे कर्मफले एव, भगवता एव दत्ते — माता यथा उद्धारार्थं शासनं करोति तथा भगवान् अपि दुःखं ददाति, इदं शिक्षणम् एव न शिक्षा। यः एकस्मिन् जन्मनि एव समत्वं धैर्यं च लभते, सः पुनः संसारे न जायते; एतादृशमानससमत्वेन भगवन्तं ज्ञात्वा मोक्षं प्राप्नोति।",
  "2.16": "नासतो विद्यते भावो नाभावो विद्यते सतः ।\nउभयोरपि दृष्टोऽन्तस्त्वनयोस्तत्त्वदर्शिभिः ॥\n\nप्रकृतेः अपि नाशः नास्ति, भगवतः अपि नाशः नास्ति — असत्कर्मणा सुखं न भवति, सत्कर्मणा दुःखं न भवति। कदाचित् दुष्कर्मिणः सुखिनः इव भासन्ते, तत् तु क्षणिकम् एव। अधर्मपथगामी कदापि यशः न लभते। महाभारतयुद्धस्य कारणं पाण्डवाः न — ते धर्मरक्षणदायित्वेन युद्धाय सज्जाः। धर्मरक्षणपथे ममत्वबुद्धिः न शोभते — इदमेव तत्त्वदर्शिभिः ज्ञातं चरमं सत्यम्।\n\nअन्यदपि दर्शनम् — असत् इति सूक्ष्मा मूलप्रकृतिः, सा अनादिनित्या। तां सृष्टवान् भगवान् (पुरुषः) अपि अनादिनित्यः। प्रकृतिपुरुषाभ्यां अधीनः जीवः अपि अनादिनित्यः। पाञ्चभौतिकदेहप्राप्तेः पूर्वमपि जीवः आसीत्, अग्रेऽपि भविष्यति। देहे जीवः अतिथिः एव — अतः देहाभिमानः न युज्यते।",
  "2.17": "अविनाशि तु तद्विद्धि येन सर्वमिदं ततम् ।\nविनाशमव्ययस्यास्य न कश्चित्कर्तुमर्हति ॥\n\nयत् सर्वत्र व्याप्तं तस्य नाशः नास्ति। रूपात्मकजगत् इव नामात्मकं जगत् अपि अस्ति, तत् नित्यम्। नामात्मकम् इति अक्षरम् — अकारात् क्षकारं यावत् एकपञ्चाशत् वर्णाः, त एव समग्रशब्दप्रपञ्चस्य मूलम्, अविनाशितत्त्वम्। अतः भगवत्प्रकृतिजीवादितत्त्वप्रतिपादकः शब्दः [वेदः] अनादिनित्यः, केनापि न नाश्यते। नामात्मकजगति वेदस्वरूपः भगवान् अविनाशी — स्वरूपनाशः देहनाशः दुःखप्राप्तिः अपूर्णत्वं वा तस्य नास्ति। सः कालतः देशतः गुणतः च व्याप्तः अनन्तस्वरूपः, अव्ययः, अविकार्यः, अनादिनित्यः।",
  "2.18": "अन्तवन्त इमे देहा नित्यस्योक्ताः शरीरिणः ।\nअनाशिनोऽप्रमेयस्य तस्माद्युध्यस्व भारत ॥\n\nभौतिकशरीरम् अन्तवत् — नश्वरम् एव; चक्षुर्गोचरः स्थूलदेहः एव नश्यति, नात्मा। जीवः हि भगवतः प्रतिबिम्बम्, सर्वव्यापिनः भगवतः पडिच्छायाम् इव — अतः नित्यः। अत्र कृष्णः अर्जुनं वदति — साम्राज्यस्वार्थेन दुर्योधनद्वेषेन वा न, अपि तु 'अन्यायविरुद्धयुद्धं भगवत्पूजा' इति भावेन युध्यस्व इति।\n\nअस्माकं दैनन्दिनकर्म अपि एवमेव भगवदर्पणरूपं भवेत्। देहः भगवता एव दत्तः, अतः तन्नाशे शोकः न आवश्यकः। स्वकर्तव्यं भगवत्पूजारूपेण कुर्वन् मृत्युभयरहितः जीवन् एव जीवितं सार्थकं करोति।",
  "2.19": "य एनं वेत्ति हन्तारं यश्चैनं मन्यते हतम् ।\nउभौ तौ न विजानीतो नायं हन्ति न हन्यते ॥\n\nयः जीवं हन्तारं मन्यते, यः च हतम् इति मन्यते, तौ उभौ अज्ञौ एव — जीवः न हन्ति, न हन्यते च। आत्मनाशः असम्भवः एव। मरणं मृतत्वं वा भौतिकशरीरे एव दृश्यते, न जीवे। देहद्वारापि जीवस्य हन्तुं हन्तुं वा स्वातन्त्र्यं नास्ति। 'कौरवाः मम हस्तेन मरिष्यन्ति' इति अर्जुनस्य भ्रान्तिः एव। सृष्टिसंहारकर्तुः भगवतः इच्छाम् विना किमपि न भवति; तदिच्छाविरुद्धं वयं किमपि कर्तुं न शक्नुमः।",
  "2.20": "न जायते म्रियते वा कदाचिन् नायं भूत्वा भविता वा न भूयः ।\nअजो नित्यः शाश्वतोऽयं पुराणो न हन्यते हन्यमाने शरीरे ॥\n\nअयं जीवः न जायते, न म्रियते च। भगवतः स्वरूपवत् अजः नित्यः शाश्वतः पुराणः — देहात् देहं भ्रमन्नपि देहनाशेऽपि स्वयं न नश्यति। अत्र कृष्णः जीवस्वरूपं व्याचष्टे — जीवः स्वरूपतः न जायते, न नश्यति च; सदैव एकरूपः, भगवत्प्रतिबिम्बत्वात्। भगवान् अजः नित्यः शाश्वतः च। जीवः देहात् देहं सञ्चरति (पुर-अण), परन्तु देहपरिवर्तनेऽपि जीवस्वरूपं न परिवर्तते। शरीरस्य जरा भवति, जीवस्वरूपस्य जरा न भवति — तत् सदैव एकरूपम् एव। परन्तु प्रभावजनितः विश्वासः परिवर्तेत — यथा एकजन्मनि नास्तिकः अन्यजन्मनि आस्तिकः स्यात्। स्वभावविशिष्टः जीवः तु सदैव अपरिवर्तितः अविनष्टः तिष्ठति।",
  "2.21": "वेदाविनाशिनं नित्यं य एनमजमव्ययम् ।\nकथं स पुरुषः पार्थ कं घातयति हन्ति कम् ॥\n\nयः जीवस्वरूपं दोषरहितं नित्यम् अपरिवर्तनीयं वेत्ति, सः कथं कञ्चित् हन्यात् हन्तुं वा कारयेत्? जीवः स्वरूपतः अविनाशी, स्थूलजगति जन्ममरणम् अपि भगवदिच्छया एव प्रवर्तते इति ज्ञाते सति, कः कं हन्ति हन्तुं वा कारयति? जन्ममरणयोः पृष्ठतः स्थितां भगवच्छक्तिम् एव वयं ज्ञातव्याः।\n\nजीवः अविनाशी, तस्य जन्ममरणे न स्तः। तर्हि लौकिकं जन्ममरणं कथं बोध्यम्? एतत्प्रश्नस्य उत्तरं कृष्णः अग्रिमश्लोके ददाति।",
  "2.22": "वासांसि जीर्णानि यथा विहाय नवानि गृह्णाति नरोऽपराणि ।\nतथा शरीराणि विहाय जीर्णान्यन्यानि संयाति नवानि देही ॥\n\nयथा मनुष्यः जीर्णवस्त्राणि त्यक्त्वा नूतनानि गृह्णाति, तथैव जीवः एकं देहं त्यक्त्वा अन्यं नूतनं देहं प्राप्नोति। जीवस्य स्वयं देहपरिवर्तने स्वातन्त्र्यं नास्ति — भगवान् एव मातेव शिशोः वस्त्रं परिवर्तयति। आत्मसाक्षात्कारयोगिनः तु भगवदनुग्रहेण स्वेच्छया देहं परिवर्तयितुं शक्नुवन्ति। तादृशान् महायोगिनः विहाय अन्येषां देहपरिवर्तने स्वातन्त्र्यं नास्ति। अतः भौतिकं जन्ममरणं जीर्णवस्त्रत्यागनूतनवस्त्रधारणवत् एव — जीवस्य मूलस्वभावः देहपरिवर्तनेऽपि न परिवर्तते।\n\nतर्हि आत्मा नाशयितुं शक्यते वा? कदापि न इति कृष्णः अग्रिमश्लोके वदति।",
  "2.23": "नैनं छिन्दन्ति शस्त्राणि नैनं दहति पावकः ।\nन चैनं क्लेदयन्त्यापो न शोषयति मारुतः ॥\n\nवस्तुनाशाय चत्वारि मुख्यसाधनानि — पृथ्वी, जलम्, अग्निः, वायुः च। जीवः सूक्ष्मात् सूक्ष्मतरः, अश्वपुच्छैककेशाग्रस्य दशसहस्रांशमानः इति शास्त्रकाराः वदन्ति। तादृशं जीवं कोऽपि शस्त्रः छेत्तुं न शक्नोति, अग्निः दग्धुं न शक्नोति, जलं क्लेदयितुं न शक्नोति, वायुः शोषयितुं न शक्नोति।\n\nअत्र प्रश्नः उदेति — यः अद्य नाशयितुम् अशक्यः सः जीवः किं सर्वदा एव अविनाशी? आम् इति कृष्णः अग्रिमश्लोके वदति।",
  "2.24": "अच्छेद्योऽयमदाह्योऽयमक्लेद्योऽशोष्य एव च ।\nनित्यः सर्वगतस्थाणुरचलोऽयं सनातनः ॥\n\nअयं जीवः अच्छेद्यः, अदाह्यः, अक्लेद्यः, अशोष्यः च — नित्यः सर्वगतः स्थाणुः अचलः सनातनः च, पुराणपुरुषस्य प्रतिबिम्बः। एषः स्वगुणधर्मेण कदापि अपरिवर्तनीयः, सर्वगतः, अविचलः — भगवतः पडिच्छाया एव। सः सनातनः — वेदनादसहितः, समस्तवेदप्रतिपाद्यस्य भगवतः शरणे वेदविधिनिषेधैः बद्धः, सर्वगतं भगवन्तम् आश्रितः महान् अणुः।",
  "2.25": "अव्यक्तोऽयमचिन्त्योऽयमविकार्योऽयमुच्यते ।\nतस्मादेवं विदित्वैनं नानुशोचितुमर्हसि ॥\n\nभगवान् अव्यक्तः, चिन्तनागोचरः, अविकार्यः च — इति वेदः घोषयति। तस्य प्रतिबिम्बः जीवः अपि स्थूलदेहे स्थितः सन् अव्यक्तः एव। अतः भगवज्जीवस्वरूपे अस्माकं चिन्तनं न प्रविशति। कोऽहम्? कुतः आगतः? किमहम्? इत्यपि न जानीमः। एतत् कठोरं सत्यं ज्ञात्वा जीवनाशचिन्तया शोकः न कर्तव्यः।",
  "2.26": "अथ चैनं नित्यजातं नित्यं वा मन्यसे मृतम् ।\nतथापि त्वं महाबाहो नैनं शोचितुमर्हसि ॥\n\nयदि त्वं जीवं देहद्वारा सदा जायमानं म्रियमाणं च मन्यसे, तथापि हे महाबाहो त्वं तस्मै न शोचितुम् अर्हसि। वेदान्तं त्यक्त्वा लौकिकदृष्ट्या पश्यामः चेत्, आत्मा देहेन व्यक्तः भवति, मरणेन अव्यक्तः। जन्ममरणातीतत्वं कदापि न सम्भवति; अतः मृत्युविषये शोकः न आवश्यकः। 'त्वं महाबलिष्ठः पूर्वं कति युद्धानि कृतवान्? तदा असती समस्या अद्य कुतः? त्वं स्वकर्तव्यम् एव करोषि' इति कृष्णः अर्जुनं बोधयति।",
  "2.27": "जातस्य हि ध्रुवो मृत्युर्ध्रुवं जन्म मृतस्य च ।\nतस्मादपरिहार्येऽर्थे न त्वं शोचितुमर्हसि ॥\n\nजन्ममरणे सुखदुःखे च एकस्यैव मुद्रायाः द्वे पार्श्वे इव। रात्रिं विना दिवा नास्ति। जातस्य मृत्युः बद्धा एव। अपरिहार्यम् अस्माभिः जीवने समायोजनीयम्; तत् विहाय कष्टागमे शोकः न युज्यते। अपरिहार्यकर्तव्यपालने वयं कदापि न शोचेम।",
  "2.28": "अव्यक्तादीनि भूतानि व्यक्तमध्यानि भारत ।\nअव्यक्तनिधनान्येव तत्र का परिदेवना ॥\n\nभूतानां जन्ममूलं न दृश्यते, मध्यम् एव दृश्यते, अन्तः अपि न दृश्यते — तत् किमर्थं विलपनम्? एतावत्पर्यन्तं जीवस्य जन्ममरणादीनां विश्लेषणं कृतम्; परन्तु अर्जुनस्य मूलसमस्या 'मम गुरुः, मम पितामहः' इति सम्बन्धाकर्षणम् एव। कृष्णः अत्र तत् समाधत्ते।\n\nव्यक्तिः जन्मानन्तरम् एव अस्माकं सम्बन्धी भवति; जन्मात् पूर्वं सः कः आसीत्, मरणात् परं कुत्र गच्छति, न जानीमः। जन्ममरणयोः पूर्वापरे अस्माकं तेन जीवेन सम्बन्धः नास्ति। एषः सम्बन्धः जीवस्य निरन्तरसत्तायाः सरलरेखायां एकः बिन्दुः मात्रम् — तदेव व्यक्तम्, शेषम् अव्यक्तम्। अतः एकस्मिन् बिन्दौ स्थित्वा शोकः न युज्यते। जीवितकाले परस्परं स्निह्येम, परन्तु विरहे भगवता आकारितम् इति निश्चिन्ताः तिष्ठेम — इति कृष्णस्य सन्देशः।",
  "2.29": "आश्चर्यवत्पश्यति कश्चिदेनमाश्चर्यवद्वदति तथैव चान्यः ।\nआश्चर्यवच्चैनमन्यः शृणोति श्रुत्वाप्येनं वेद न चैव कश्चित् ॥\n\nकश्चित् एनं जीवं भगवन्तं वा आश्चर्येण पश्यति, अन्यः आश्चर्येण वदति, अन्यः आश्चर्येण शृणोति — श्रुत्वापि कोऽपि सम्यक् न जानाति। भगवद्दर्शिनः विरलाः; महता साधनेन दृष्टेऽपि तेषाम् उद्गारः केवलम् आश्चर्यम् एव, यतः विश्वमेव अद्भुतम्, तत्स्रष्टा कियान् अद्भुतः स्यात्? जीवोऽपि तथैव — आत्मसाक्षात्कारे केवलं विस्मयः, वर्णनम् अशक्यम्। जीवः तेजःपुञ्जः, सूर्यात् प्रखरः चन्द्रात् शीतलः — तद्विषये निश्चितं निर्णयं कर्तुम् अशक्यम्।",
  "2.30": "देही नित्यमवध्योऽयं देहे सर्वस्य भारत ।\nतस्मात्सर्वाणि भूतानि न त्वं शोचितुमर्हसि ॥\n\nसर्वेषां देहे स्थितः अयं जीवः कदापि हन्तुम् अशक्यः, यतः प्रत्येकस्मिन् देहे भगवान् जीवस्य रक्षकः तिष्ठति। अतः सर्वभूतार्थं शोकः न युज्यते। देहमरणं विधिनियमः एव, तत्कृते शोकः न आवश्यकः। स्वेच्छया देहत्यागः वा अत्यागः वा जीवस्य वशे नास्ति — अन्तर्यामिनि भगवति रक्षति, त्वं जन्ममरणयोः उत्तरदायी न भवसि, इति कृष्णः भारतकुलजातम् अर्जुनं बोधयति। जीवज्योतिः ज्ञाते सति जन्ममरणरहस्यं स्पष्टं भवति, मृत्युः आनन्दानुभवः भवति।\n\nएतत् श्रुत्वा मतं भवेत् — 'हननं न दोषः, यतः जीवः न म्रियते; सर्वं दैवेच्छया भवति, यः कञ्चित् हन्तुं शक्नोति' इति। परन्तु तत् न सम्यक्, यतः इदानीं दृष्टं तत्त्वं केवलं आन्तरिकं दर्शनम्। सामाजिकाः वयं तत् समाजविरुद्धं प्रयुञ्जीमहि चेत् अधर्मः एव भवेत्। शास्त्रानुगुणं समाजधर्मं प्रत्येकेन पालनीयम् — अग्रिमश्लोके कृष्णः एतत् अर्जुनद्वारा स्पष्टयति।",
  "2.31": "स्वधर्ममपि चावेक्ष्य न विकम्पितुमर्हसि ।\nधर्म्याद्धि युद्धाच्छ्रेयोऽन्यत्क्षत्रियस्य न विद्यते ॥\n\nस्वधर्मं दृष्ट्वापि त्वं विकम्पितुं नार्हसि — क्षत्रियस्य न्यायप्राप्तयुद्धात् श्रेयस्करं किमपि नास्ति। अत्र अर्जुनस्य सनातनधर्मः अन्यायविरोधः; समाजधर्मः अधर्मविरोधेन समाजरक्षणम्, अत्र ममत्वबुद्धिः न कार्या; क्षत्रियजातेः स्वधर्मः अपि अन्यायविरोधः एव — व्यक्तिधर्मः समाजधर्मः सनातनधर्मः च अत्र एकीभूताः। अतः अन्यायविरोधः महापुण्यकर्म, समाजरक्षार्थं युद्धं क्षत्रियस्य महातपः।",
  "2.32": "यदृच्छया चोपपन्नं स्वर्गद्वारमपावृतम् ।\nसुखिनः क्षत्रियाः पार्थ लभन्ते युद्धमीदृशम् ॥\n\nस्वेच्छया युद्धान्वेषणं दोषः, परन्तु अत्र समष्टिरूपेण आगतयुद्धस्य दायित्वं पाण्डवानां न। स्वयमेव आगतम् इदं युद्धं दैवेच्छा एव। ईश्वरेच्छानुसारेण सर्वं भवति चेत्, यदागतं तत् स्वीकर्तव्यम्। अन्यायविरुद्धधर्मयुद्धकर्तुः स्वर्गद्वारं सदा उद्घाटितम् एव। तादृशयुद्धावसरः क्षत्रियस्य पुण्यफलम् एव — तादृशसमये नेत्रे निमील्य उपविशनं महापापम्।\n\nप्रत्येकः मानवः सनातनधर्मानुगुणं समाजधर्मं, समाजसनातनधर्मानुगुणं स्वधर्मं च पालयेत्। एतन्नेलेयां कृतं कर्म कदापि पापं न भवति। सनातनधर्मः समाजधर्मः स्वधर्मः च किम् इति प्रथमाध्याये (श्लोक ४०) विस्तरेण विश्लेषितम्।",
  "2.33": "अथ चेत्त्वं धर्म्यमिमं संग्रामं न करिष्यसि ।\nततः स्वधर्मं कीर्तिं च हित्वा पापमवाप्स्यसि ॥\n\nन्यायप्राप्तम् इदं युद्धं यदि त्वं न करोषि, तर्हि स्वधर्मं कीर्तिं च त्यक्त्वा पापम् एव प्राप्स्यसि। युद्धेन एव धर्मः रक्षितः भवति, स्वर्गद्वारं च उद्घाटितं भवति; अन्यथा नरकद्वारम् एव त्वां स्वागतयति।\n\nइदं धर्मसंग्रामम् एव। अर्जुनः धर्मपक्षे स्थितः महारथी; तादृशधर्मयुद्धे न योद्धुं स्वाभाविकधर्मविरुद्धं समाजधर्मत्यागश्च — महापापम् एव भवेत्। पापभयेन क्लिष्टं अर्जुनं कृष्णः वास्तविकपापस्वरूपं बोधयति।\n\nपापकृत्यनिर्णयः प्रसङ्गाधीनः — 'सत्यवचनं सदा पुण्यम्' इति न वक्तुं शक्यम्। तस्कररक्षार्थं गूढं जनं प्रति तस्करप्रश्ने सत्यवचनं पापम्, तद्रक्षार्थम् असत्यवचनं पुण्यम्। तथैव धर्मरक्षार्थं गुरुपितामहविरुद्धं युद्धम् एव महापुण्यम् इति कृष्णः बोधयति।",
  "2.34": "अकीर्तिं चापि भूतानि कथयिष्यन्ति तेऽव्ययाम् ।\nसंभावितस्य चाकीर्तिर्मरणादतिरिच्यते ॥\n\nक्षत्रियस्य कीर्तिनाशे सः अपमानम् अनुभवति, अस्तित्वमपि नश्येत्। महाधनुर्धरत्वेन विख्यातः अर्जुनः धर्मयुद्धे अभागी चेत्, जनाः तं कापुरुषम् इति निन्देयुः; इतिहासे तस्य कापुरुषत्वं भाविपीढ्या दुष्टान्तः भवेत्। 'बन्धुस्नेहेन युद्धात् निवृत्तः' इति न कोऽपि वदेत् — भीरुः इति एव निन्देयुः। मर्यादितस्य पुरुषस्य अकीर्तिः मरणात् अपि अधिका।",
  "2.35": "भयाद्रणादुपरतं मंस्यन्ते त्वां महारथाः ।\nयेषां च त्वं बहुमतो भूत्वा यास्यसि लाघवम् ॥\n\nयैः त्वं गौरवास्पदः आसीः, ते महारथाः त्वां भयेन युद्धात् निवृत्तम् इति मन्यमानाः त्वां लघुं करिष्यन्ति।",
  "2.36": "अवाच्यवादांश्च बहून्वदिष्यन्ति तवाहिताः ।\nनिन्दन्तस्तव सामर्थ्यं ततो दुःखतरं नु किम् ॥\n\nतव अहिताः तव सामर्थ्यं निन्दन्तः अवाच्यवचांसि वदिष्यन्ति — ततः अधिकं दुःखं किम्? यैः त्वं महावीरः इति सम्मानितः, ते त्वां तृणाधमं पश्येयुः; समाजे उन्नतः त्वं अपमानितः जीवितुम् अर्हसि। पूर्वसाधनम् अपि मिथ्या इति निन्द्येत।\n\nश्रेष्ठन्यायाधीशनामधारी कश्चित् स्वबन्धोः कृते दुष्टनिर्णयं ददाति चेत्, सः स्वव्यक्तित्वं सर्वथा नाशयति; पूर्वसाधनानि क्षणे धूलिसात् भवन्ति, दण्डिताः अपराधिनः अपि तं निन्दन्ति — इदम् एव सामाजिकं ज्ञानं कृष्णः अर्जुनाय ददाति।",
  "2.37": "हतो वा प्राप्स्यसि स्वर्गं जित्वा वा भोक्ष्यसे महीम् ।\nतस्मादुत्तिष्ठ कौन्तेय युद्धाय कृतनिश्चयः ॥\n\nयुद्धजयः निश्चितः न — धर्मयुद्धे मृत्यौ विजये वा मोक्षः एव। स्वार्थार्थं न इदं युद्धम्; अन्यायविरोधसंकल्पेन उत्थाय युध्यस्व इति कृष्णः वदति। स्वार्थरहितः धर्मपथानुगामी कदापि किमपि न बिभेति; धर्मपथगमने फलं यत् किमपि भवतु, तत् मोक्षसाधनम् एव भवति।",
  "2.38": "सुखदुःखे समे कृत्वा लाभालाभौ जयाजयौ ।\nततो युद्धाय युज्यस्व नैवं पापमवाप्स्यसि ॥\n\nसुखदुःखं जीवने अपरिहार्यम्। सुखदुःखलाभालाभजयाजयान् समान् पश्यतः पापं न स्पृशति। समदृष्ट्या सर्वं पश्यन् कर्तव्यबुद्ध्या एव युद्ध्यस्व — जयेच्छारहितः, द्वेषरहितः, सर्वं भगवत्प्रसादम् इति भावेन युध्यस्व इति कृष्णः वदति।\n\nएतद्वचनम् आचरन् मनुष्यः कदापि दुःखी न भवति। धर्मपथे अग्रसरस्य स्वर्गद्वारं सदा उद्घाटितम्; तस्य दुःखं दुःखवत् न भासते, पराजयः पराजयवत् न भासते — तस्य इहलोकः परलोकः च स्वर्गः एव।\n\nएतावत्पर्यन्तं कृष्णः आत्मतत्त्वविषये विस्तरेण अर्जुनाय उक्तवान् — जीवनम्, मरणम्, आत्मपरमात्मतत्त्वयोः रहस्यम् च; एतत् सर्वं अपरिवर्तनीयम् अनादिनित्यं च इति व्याख्याय युद्धावश्यकतां उक्तवान्। अतः परं कृष्णः सांख्यात् कर्मपक्षं प्रति वर्तते।\n\nवेदान्तं मनसि यावत् अपि दृढीकुर्मः, तात्कालिकमनुष्यस्य दुःखम् अदम्यम् एव इति गीता स्पष्टं दर्शयति। भगवतः साक्षात् गीतोपदेशं प्राप्तः अर्जुनः अपि पुत्रे अभिमन्यौ युद्धे मृते पुनः विचलितः भवति इति महाभारते दृश्यते। पूर्णात्मसाक्षात्कारः न सुलभः। आत्मा अजरामरः इति ज्ञानं पर्याप्तं न, पूर्णतया ज्ञातव्यम्। तादृश्यां स्थितौ सर्वं दुःखं विस्मर्तुं शक्यते।\n\nअतः कृष्णः अग्रे एतां उत्तमां मानसिकस्थितिं कथं प्राप्नुयात् इति विवृणोति।",
  "2.39": "एषा तेऽभिहिता सांख्ये बुद्धिर्योगे त्विमां शृणु ।\nबुद्ध्वा युक्तो यया पार्थ कर्मबन्धं प्रहास्यसि ॥\n\n'सांख्यविषये उक्तम्, अधुना योगविषये शृणु' इति कृष्णः वदति। अत्रोक्तं सांख्यं वैदिकसांख्यम्, कपिलवासुदेवेन प्रचारितम्। सांख्या इति सम्यक्ख्यातिः, आत्मज्ञानप्रदं मूलतत्त्वम्।\n\nअत्रोक्तः योगः न पातञ्जलयोगः, अपि तु वैदिकयोगः। सामान्ययोगे ईश्वरास्तित्वे दृढविश्वासः न आवश्यकः; मनःएकाग्रतया अनेकाः चमत्काराः साध्याः, परन्तु तत् न वास्तविकम् आत्मसाक्षात्कारम् — दशवर्षाणि योगसाधनां कृत्वा जलोपरि गन्तुं शिक्षितवतः कथा सर्वैः श्रुता एव। वैदिकयोगः तादृशचमत्कारप्रदर्शनं निषेधयति — काऽपि अन्तःशक्तिः प्राप्ता चेदपि सा न प्रदर्शनीया। जलोपरि गमनशिक्षणमात्रेण आत्मसाक्षात्कारः न भवति, एतादृशम् इन्द्रजालं कोऽपि साधयितुं शक्नोति। कृष्णः अत्र आत्मतत्त्वप्राप्त्यर्थं जीवने कर्तव्यसाधनं वदति।\n\nज्ञानमार्गे सिद्ध्यर्थम् उपायं (योगं) श्रुणु इति कृष्णः वदति। अध्यात्मसाधनं किम्, तत् जीवने कीदृशं भवेत्, कथं साध्यते — इति ज्ञातव्यम्। बहवः बाह्यरूपं वदन्ति, अन्तरङ्गं न कोऽपि वदति। जपतपोबाह्यवेषेण विना अन्तरङ्गसाधनं विना किमपि न साध्यते। योगसाधनं वस्त्रधारणं न, अन्तरङ्गाचरणम् एव — अन्तरङ्गबहिरङ्गयोः ऐक्यम्। आचारः विश्वासः प्रामाणिकता च एव नः वास्तविकः धर्मः।",
  "2.40": "नेहाभिक्रमनाशोऽस्ति प्रत्यवायो न विद्यते ।\nस्वल्पमप्यस्य धर्मस्य त्रायते महतो भयात् ॥\n\nजन्म, अध्ययनसाधने, मरणं, पुनर्जन्म, पुनः साधनं, पुनर्मरणम् — इति चक्रे किम् उपयोगः इति संशयः स्यात्। ब्रह्मसाक्षात्कारः एकजन्मनि न भवति चेत् साधनं व्यर्थं वा? न इति कृष्णः वदति। ऐहिकसम्पत्तिः मरणेन सह न गच्छति, परन्तु अध्यात्मसाधनं तथा न — एकजन्मकृतं साधनं कदापि न नश्यति। अस्मिन् जन्मनि एकं सोपानम् आरुह्य अग्रिमजन्मनि द्वितीयसोपाने एव जन्म भवति। पूर्वजन्मसाधनस्य अग्रे एव अस्मिन् जन्मनि साधनम् आरभ्यते।\n\nअध्यात्मसाधनतुडितिः यदि अस्मिन् जन्मनि अपूर्णा, अग्रिमजन्मनि विद्वत्सङ्गे साधनानुकूलवातावरणे जन्म भवति। एवं प्रत्येकं जन्म अध्यात्मशिक्षायां एकैका कक्षा इव। अतः अध्यात्मसाधनं कदापि व्यर्थं न। अद्यैव साधनम् आरभस्व — तत् मोक्षमार्गं प्रति नयति इति कटुसत्यम्। अध्यात्मं प्रदर्शनवस्तु न, अन्तरङ्गसाधनम् एव। स्वल्पमपि साधनं भयात् त्रायते।\n\nसाधकाः त्रिविधाः — उत्तमः, मध्यमः, अधमः। उत्तमसाधकः एकमेव देवं मन्यते, तस्य भगवति एकनिष्ठा; भगवन्नामानि सर्वाणि तमेव परशक्तिं निर्दिशन्ति इति सत्यं वेत्ति — एषः वास्तविकः साधकः। मध्यमसाधकाः प्रतिदेवतां पूजयित्वा अन्ते 'कृष्णार्पणमस्तु' इति समर्पयन्ति — त्रैविध्याः इति उच्यन्ते। अधमसाधकः शतशः देवान् मन्यमानः पूजयति, भगवतः सर्वान्तर्यामित्वं न वेत्ति — तस्य अध्यात्मे वास्तविककल्पना नास्ति।\n\nएकनिष्ठया कृतं साधनं कदापि व्यर्थं न भवति; प्रामाणिकनिष्ठा एव आवश्यकी। गणपतिं वायुं सूर्यं वा अल्लाहं यीशुं शिवं विष्णुं वा नाम्ना यत् किमपि पूजयन्तु, सर्वाणि नामानि तम् एव परशक्तिम् निर्दिशन्ति इति ज्ञात्वा एकनिष्ठया शुद्धप्रामाणिकचिन्तनेन साधनं कृतं चेत् तत् वास्तविकम् अध्यात्मसाधनं भवति, व्यर्थं न भूत्वा अस्माभिः सह गच्छति। तादृशसाधने द्वेषः स्वार्थः अहंकारः दुःखं वा कदापि न भवति; सर्वं भगवत्प्रसादम् इति भावना अस्मान् उच्चैः नयति।",
  "2.41": "व्यवसायात्मिका बुद्धिरेका इह कुरुनन्दन ।\nबहुशाखा ह्यनन्ताश्च बुद्धयोऽव्यवसायिनाम् ॥\n\nएकनिष्ठया कृतं साधनं व्यर्थं न इति ज्ञातम्; परन्तु सम्यक्-असम्यक् ज्ञानोपायः कः? सर्वकाले निर्णयात्मकं वचनम् एकरूपम् एव भवति। निर्णयरहितं वचनम् अनेकधा भिद्यते; अज्ञानोक्तं वचनं अनन्तशाखं भवति। ज्ञानिनां निर्णयात्मकं वचनं सदा एकम् एव — अतः सत्यज्ञानिनां मार्गदर्शनानुसारं चर इति कृष्णः वदति।",
  "2.42": "यामिमां पुष्टितां वाचं प्रवदन्त्यविपश्चितः ।\nवेदवादरतः पार्थ नान्यदस्तीति वादिनः ॥\n\nहे पार्थ, अर्धज्ञाः वदन्ति — इयं वेदवाणी स्वर्गपुष्पितलता, जन्मकर्मबन्धसंसारः एव अस्याः फलम्।",
  "2.43": "कामात्मानः स्वर्गपरा जन्मकर्मफलप्रदाम् ।\nक्रियाविशेषबहुलां भोगैश्वर्यगतिं प्रति ॥\n\nभोगैश्वर्यार्थं ते बहुविधक्रियाकलापेषु निरताः, वेदस्य बाह्यार्थे एव तिष्ठन्ति [वेदे विवादं वर्धयन्तः, अर्थम् अजानन्तः वा केवलं पठन्तः], ततः परं किमपि नास्ति इति मन्यमानाः, कामपूर्णचित्ताः स्वर्गस्वप्नदर्शिनः।",
  "2.44": "भोगैश्वर्यप्रसक्तानां तयापहृतचेतसाम् ।\nव्यवसायात्मिका बुद्धिः समाधौ न विधीयते ॥\n\nभोगे मग्नानां अर्धज्ञवचनमोहितानां एतादृशजनानां हृदये परिपक्वा बुद्धिः अपि मनसः समाधानाय न कल्पते। एतत्त्रयं श्लोकं अतीव महत्त्वपूर्णम्, अधिकांशैः अनवगतम् एव। वेदेषु श्रुतिषु च केवलाध्यात्मं न, लौकिकविषयाः अपि सन्ति इव भासन्ते। केवलं वेदपाठमात्रेण मां ज्ञातुं न शक्यते इति कृष्णः वदति। वेदवादिनः वेदस्य बाह्यार्थपुष्पं गृहीत्वा गभीरज्ञानसागरफलात् वञ्चिताः भवन्ति। ब्राह्मणशब्दः अत्र जातिवाचकः न — ब्रह्मतत्त्वज्ञः एव ब्राह्मणः। एतादृशं वेदरहस्यम् अज्ञात्वा बाह्यार्थं प्रचारयन् समाजं वञ्चयति सः अविपश्चित् — इति कृष्णेन उक्तम्। एतत् सर्वधर्मग्रन्थेषु दृश्यते — बाइबल्ग्रन्थे गूढार्थः, कुराने अपि एतादृशी चेतावनी वर्तते।\n\nप्राचीनग्रन्थेषु अनेकाः कथाः, ता बाह्यतः विनोदाः इव, परन्तु तत्त्वज्ञाने जीवनं सार्थकम्। गणपतिकथा एव उत्तमोदाहरणम् — पार्वती स्वमृत्तिकया गणपतिं निर्मितवती, शिवः तच्छिरः छिन्नवान्, पश्चात् उत्तराभिमुखगजशिरः योजितम्, मोदकभक्षकः गणेशः उदरे सर्पं वेष्टितवान्। अस्य गूढार्थः — गणपतिः आकाशदेवता, पञ्चभूतेषु आकाशं महत्तमम्; गणपतिस्थानम् एकविंशतितमम्, अतः एकविंशतिमोदकार्पणम् (पञ्च अन्तःकरणानि, पञ्च ज्ञानेन्द्रियाणि, पञ्च कर्मेन्द्रियाणि, पञ्च तन्मात्राणि — शब्दस्पर्शरूपरसगन्धाः, ततः आकाशवाय्वग्निजलपृथिव्यः — एवं आकाशम् एकविंशतितमं तत्त्वम्)। गणपतेः पूर्वस्तरे विंशतिः तत्त्वाभिमानिदेवताः — ब्रह्मा, वायुः, गरुडः, शेषः, रुद्रः, इन्द्रः, कामः, अहम्प्राणः, अनिरुद्धः, स्वायम्भुवमनुः, बृहस्पतिः, दक्षप्रजापतिः, प्रवहवायुः, चन्द्रः, सूर्यः, यमधर्मः, वरुणः, वह्निः, मित्रः, निर्ऋतिः च — गणपतिः एकविंशः। शिवः मनोऽभिमानी, पार्वती वाग्देवता — तयोः दाम्पत्यम् अन्योन्यम्। शब्दमूलशक्ती वायुः आकाशं च। अन्तर्वाङ्नादः पार्वती एव, तस्याः बहिःप्रकाशः वाक्। वाक् एव मनुष्यस्य महदापत्तिः — अध्यात्मसाधनाय वाचः अधिकं मौनम् अपेक्षितम्। अहंकारविरुद्धं वाक् वर्धमानं चेत् शिरश्छेदनं विना ज्ञानं न स्यात् — अतः सर्वश्रवणसमर्थं महाकर्णं, प्राणशक्तिनियामकं दीर्घनासं गजशिरः धृत्वा गणपतिः जातः। गणपतिदर्शनेन स्मर्तव्यं — वाचः अधिकं मननं कुरु, सम्यक् शृणु इति।\n\nउत्तराभिमुखशिरःस्थापनस्य कारणम् — उत्तरध्रुवशक्तिः उत्तरात् पूर्वं प्रवहति, दक्षिणध्रुवशक्तिः दक्षिणात् पश्चिमं प्रवहति; अस्मत्संचलनम् अपि तदनुगुणं भवेत्। उत्तरे शिरः निधाय शयनं दक्षिणाभिमुखत्वम् एव, तत् संसारावर्ते निपातयति; उत्तरशक्तिपातः तु ऊर्ध्वमुखः। उदरस्थसर्पः कुण्डलिनीशक्तेः प्रतीकः — जागरणे मूलाधारमणिपूरस्वाधिष्ठानेषु ऊर्ध्वं सञ्चरति, नाभ्यूर्ध्वकेन्द्रं ज्ञानद्वारम्, गणपतिः त्रयाणां शक्तिकेन्द्राणां नियन्ता ज्ञानद्वारोद्घाटकः च। एतावती गूढार्थपरम्परा एतस्यां लघुकथायाम्।\n\nवयं स्वशिरोगतं वेदे न मार्गयेम, अपि तु वेदस्थं स्वशिरसि पूरयेम। वेदस्य बाह्यार्थमात्रग्रहणेन जन्मकर्मचक्रे एव तिष्ठामः, अमृतत्वमार्गः न दृश्यते। प्राचीनग्रन्थाः किमर्थं गूढरूपेण लिखिताः इति प्रश्नः — तत्र मुख्यम् उत्तरम् एतद्ग्रन्थज्ञानाय योग्यता आवश्यकी। पुस्तकम् एकम्, परन्तु तत्र बहुस्तरीयं शिक्षणम्। एतद्वेदग्रन्थाः अयोग्येभ्यः कदापि न दृश्यन्ते — योग्याय एव उद्घाटन्ते। एकग्रन्थज्ञानाय बहुजन्मसाधनम् अपेक्ष्यते।",
  "2.45": "त्रैगुण्यविषया वेदा निस्त्रैगुण्यो भवार्जुन ।\nनिर्द्वन्द्वो नित्यसत्त्वस्थो निर्योगक्षेम आत्मवान् ॥\n\nवेदाः बाह्यतः त्रिगुणसम्बन्धं वर्णयन्ति [अन्तः त्रिगुणबन्धस्य विषं निवारयन्ति च]। हे अर्जुन, त्वं त्रिगुणातीतः भव, द्वन्द्वातीतः, सदा भगवति स्थितचित्तः, योगक्षेमभारं तस्मै समर्प्य तमेव स्वामिनं मत्वा चर।\n\nवेदः बाह्यतः सत्त्वरजस्तमोगुणसम्बद्धं लौकिकविषयं वदति इव भासते — रक्तचश्मधारिणे इव सर्वं रक्तवर्णं दृश्यते। सन्तानवृद्धिः, गोधनम्, धनम्, राजसूयाश्वमेधादयः — एतानि सर्वाणि लौकिकानि एव। परन्तु वेदार्थग्रहणाय प्रथमं लौकिकप्रभावातीतत्वम् आवश्यकम्। त्रिगुणप्रभावं तीर्त्वा स्वस्वरूपज्ञाने शुद्धं चिन्तनं सम्भवति। त्रिगुणातीतत्वं पूर्णतया दुर्लभम्, परन्तु सचेतनत्वेन साधनं सम्भवति। भगवन्नामस्मरणं, अन्तर्यामिभगवज्ज्ञानं च अस्मान् शुद्धीकरोति।\n\nध्याने मनः बहिर्मुखं न स्यात्। आत्मज्ञानरहितं होमहवनं निष्फलम्। निःस्वार्थं भगवज्ज्ञानेन साधनं कर्तव्यम्, कपटरहितं धर्माचरणम्। स्वार्थातीतत्वेन त्रिगुणातीतत्वेन च वेदस्य वास्तविकसन्देशः ज्ञायते। निर्योगक्षेमावस्थायाम् एव सत्यसाक्षात्कारः भवति — योगक्षेमभारः भगवत एव, सः सर्वान्तर्यामी सदा रक्षति इति विश्वासेन भगवच्चिन्तने निरतः भवेत्।\n\nअत्र प्रश्नः स्यात् — ज्ञानाय एव किमर्थम् एतावत् महत्त्वम्, कर्मयोगेन अपि स्वर्गप्राप्तिः स्यात् इति। कृष्णः उत्तरयति — वेदस्य एकमेव मुखम्, कर्मोपासने अपि ज्ञानाय एव; अतः सम्पूर्णः वेदः ज्ञानकाण्डः एव इति अग्रिमश्लोके कृष्णः दृढयति। अलब्धस्य लाभः योगः, लब्धस्य रक्षणं क्षेमः — लौकिके योगक्षेमे एव अस्माकं सम्पूर्णं जीवनम् अतिक्रामति। एतत् त्यक्त्वा भगवता यत् दत्तं तस्मिन् एव सन्तुष्टाः भवितुं शिक्षणीयम्।",
  "2.46": "यावानर्थ उदपाने सर्वतः सम्प्लुतोदके ।\nतावान्सर्वेषु वेदेषु ब्राह्मणस्य विजानतः ॥\n\nकूपस्य यत्फलं तत् सर्वं तडागस्य फले अन्तर्भूतम्; सर्ववेदफलं ब्रह्मविदः फले अन्तर्भूतम्। अयं श्लोकः गूढार्थकः — अहंकारं सर्वथा त्यक्त्वा शरणागत्या दृष्टे एव उद्घाटते।\n\nज्ञानरहितः कर्मकाण्डी कूपात् जलं कर्षति इव श्रमेण फलं लभते, अपरोक्षज्ञानी तु तडागतीरे तिष्ठन् इव सुलभफलः। 'ब्राह्मण' शब्दः जातिवाचकः न — 'ब्रह्म जानाति इति ब्राह्मणः', ब्रह्मतत्त्वज्ञः वेदवेद्यभगवत्साक्षात्कारी च।\n\n'सर्वतः सम्प्लुतोदक' इत्यस्य अर्थः प्रलयजलपूर्णावस्था। तत्र शयानः 'उदपानः' — उत्-अप-अन इति व्युत्पत्त्या उत्कृष्टः, सर्वपालकः सर्वोत्तमः सर्वनियन्ता च भगवान्। तस्मात् तत्त्वात् यत्किञ्चित् उपयोगः, तत् सर्वं वेदे वेदस्य प्रतिमन्त्रे प्रतिवाक्ये प्रत्यक्षरे भगवन्तं पश्यन् ब्रह्मज्ञानी लभते। बाह्यार्थमात्रपाठेन न किमपि उपयोगः।",
  "2.47": "कर्मण्येवाधिकारस्ते मा फलेषु कदाचन ।\nमा कर्मफलहेतुर्भूर्मा ते सङ्गोऽस्त्वकर्मणि ॥\n\nकर्मणि एव अधिकारः, न फले — फलहेतुत्वं स्वस्मिन् मा भ्रम, भगवान् एव फलहेतुः इति एतत् ज्ञानं ते अस्तु। इच्छा न निषिद्धा, परन्तु 'एवमेव भवतु' इति दुराग्रहः न युक्तः। कर्तव्यनिष्ठया भगवदर्पणभावेन कर्म कुर्वन् यत्फलं लभते तत् स्वीकुर्वन् दुःखरहितः भवति। अकर्मण्यता अपि न युक्ता — निरन्तरं कर्तव्यनिष्ठः भव।",
  "2.48": "योगस्थः कुरु कर्माणि सङ्गं त्यक्त्वा धनञ्जय ।\nसिद्ध्यसिद्ध्योः समो भूत्वा समत्वं योगः उच्यते ॥\n\nसंगत्यागेन योगस्थः सन् कर्म कुरु, सिद्ध्यसिद्ध्योः समभावः — एतत् एव 'योगः' नाम्ना उच्यते। यत् किमपि कर्म क्रियते, तत् केवलं कर्तव्यम् इति न — तस्य पृष्ठतः योगः अपेक्षितः। भगवान् एव फलदाता, मत्तः कर्म कारयिता च सः एव — कीदृशं फलं, कियत् फलं, कदा फलम् — सर्वम् एतत् तस्य अधीनम्। फलं लब्धे सन्तोषः, न लब्धे अपि सन्तोषः — एषा भौतिकी समता। एतादृश्या समतया कर्तव्यदृष्ट्या कर्म कर्तव्यम्। जीवनस्य सर्वस्मिन् कर्मणि इदम् अनुसन्धानं यदा वर्तते, तदा तत् भगवत्पूजा भवति — इदम् एव कर्मयोगः। सिद्ध्यसिद्ध्योः समभावदर्शनं मनसः योगः — इयं मानसिकी अवस्था। एतादृश्या योगभावनया कृतं कर्म — फलप्राप्तौ अहंकारः न भवति, अलाभे दुःखं न भवति। एवं सिद्ध्यसिद्ध्योः समत्वेन कृतं प्रत्येकं कर्तव्यम् अपि भगवत्पूजा भवति। एतादृशानुसन्धानं विना कृतः महायज्ञः अपि पूजा न भवति। 'भगवता मत्तः इदं कर्म कारितम्, एतत् तस्मै पूजारूपेण अर्प्यताम्' इति अनुसन्धानं यदा वर्तते, तदा एव कर्म योगः भवति — अस्मन्मनसः भगवति संयोगः एव योगः; अस्मै अनुसन्धानाय पूरकं तथा अनुसन्धानपूर्वकं च सर्वं कर्म कर्मयोगः।",
  "2.49": "दूरेण ह्यवरं कर्म बुद्धियोगाद्धनञ्जय ।\nबुद्धौ शरणमन्विच्छ कृपणाः फलहेतवः ॥\n\nहे धनञ्जय, बुद्धियोगात् कर्म अतिदूरम् अवरं, बुद्धौ एव शरणं गच्छ [बुद्धिप्राप्त्यनन्तरम् अपि हरये शरणागतिः]। फलमात्राश्रयिणः कृपणाः एव। जगति केचन कर्मयोगिनः, केचन ज्ञानयोगिनः — केषाञ्चित् मतेन कर्म श्रेष्ठम्, अन्येषां मतेन ज्ञानं श्रेष्ठम्, अपरे च कर्मज्ञाने 'द्वे चक्रे इव' समाने इति वदन्ति — एतेन बहवः विवादाः जायन्ते। किन्तु कृष्णः अत्र स्पष्टं वदति — ज्ञानात् कर्म अतिदूरं न्यूनम् इति। कर्म कुर्वतः ज्ञानम् एव अतिमुख्यम्, ज्ञानार्थम् एव कर्म वर्तते, न तत् ज्ञानेन समम्। अतः ज्ञाने शरणं गत्वा ज्ञानपूरकं कर्म कुर्यात्। ज्ञानं विना फलाकाङ्क्षया कर्म कुर्वतां स्थितिः शोचनीया — ते कर्मस्य रहस्यम् अजानन्तः कर्म कृत्वा क्लिश्यन्ति, अतः एव कृपणाः उक्ताः। ज्ञानमार्गे उत्कर्षाय कर्म कर्तव्यम् — तेन भगवत्साक्षात्कारः भवति। तस्यां अवस्थायाम् अहंकारं त्यक्त्वा 'भगवान् एव मम रक्षकः, सः एव मम आश्रयः' इति ज्ञात्वा तस्मिन् शरणं गन्तव्यम् — 'अहं स्वात्मानं भगवते अर्पितवान्, सः माम् अवश्यं रक्षति' इति दृढविश्वासः एव शरणागतिः। अस्मासु काचित् समस्या उपस्थिता चेत् भगवन्तम् एव प्रार्थयेम, नान्यान् — 'हे भगवन्, मां किमर्थम् एतस्यां समस्यायाम् अपातयः? अस्याः निवारणं दर्शय, हे तात' इति मनःपूर्वकं प्रार्थितं चेत् सः अस्मान् अवश्यं संकटात् उद्धरति। अत्रापि फले अधिकारं असाधयन्, भगवन्तम् एव विश्वस्य, सर्वासु समस्यासु निश्चिन्ततया जीवितुं शिक्षणीयम्। अत्र प्रयुक्तं 'धनञ्जयः' इति नाम द्विधा अर्थयति — लौकिकः अर्थः, अर्जुनः बहुत्र युद्धं कृत्वा राष्ट्रसीमां विस्तार्य राजकोशं वर्धितवान्, अतः सः धनञ्जयः; आध्यात्मिकः अर्थः, भगवदाराधना अध्यात्मज्ञानं च वास्तविकं धनम्, भगवज्ज्ञानं सर्वेभ्यः श्रेष्ठं धनम्, अर्जुनः तत्कालीनः अपरोक्षज्ञानी, स्वयं इन्द्रः, ज्ञानधनस्य पराकाष्ठा — 'एतादृशः ज्ञानी त्वं भगवते शरणं गत्वा बुद्धिपूर्वकं कर्म कुरु' इत्यर्थे कृष्णेन एतत् सम्बोधनं कृतम्।",
  "2.50": "बुद्धियुक्तो जहातीह उभे सुकृतदुष्कृते ।\nतस्माद्योगाय युज्यस्व योगः कर्मसु कौशलम् ॥\n\nभगवज्ज्ञानी अनावश्यके पुण्यपापे इहैव त्यजति। अनावश्यकं पुण्यम् इत्युक्ते यथा — कश्चन महात्मा स्वज्ञानकर्मभ्यां मोक्षं लभते, किन्तु तस्मिन् मार्गे वर्तमानः सः अन्यत् पुण्यम् अपि उपार्जयति। यदि सः चक्रवर्तित्वेन विराजमानस्य पुण्यम् अपि प्राप्नुयात्, तत् तस्मै अनावश्यकं पुण्यम् एव — यतः मोक्षात् परं तस्य पुण्यस्य अपेक्षा तस्मै नास्ति। सः एतत् पुण्यम् इहैव त्यजति — इदम् एव अत्र 'अनावश्यकं पुण्यम्' इति उक्तम्। ये एवं भगवत्प्रज्ञायां जीवन्ति, तेषां कृतं कर्म तेषां पापपुण्ययोः बन्धनाय न भवति। अतः ज्ञानयोगे स्थित्वा तदनुगुणं कर्म कुर्वन्तः पापपुण्यबन्धरहिताः भवन्ति — इदमेव कौशलम्।",
  "2.51": "कर्मजं बुद्धियुक्ता हि फलं त्यक्त्वा मनीषिणः ।\nजन्मबन्धविनिर्मुक्ताः पदं गच्छन्त्यनामयम् ॥\n\nजितेन्द्रियाः मनीषिणः कर्मफलमोहं त्यक्त्वा भगवते अर्पयन्ति। एवं यः कर्मफलं भगवदर्पणबुद्ध्या त्यक्त्वा निर्वञ्चनेन कर्म करोति, सः कर्मबन्धरहितः दोषरहितं मोक्षं प्राप्नोति। अतः कर्तव्यकर्म भगवदाराधनारूपेण कृत्वा मोक्षः प्राप्तव्यः। 'अहं ज्ञानी, किमपि न करोमि' इति धोरणं न युक्तम्।",
  "2.52": "यदा ते मोहकलिलं बुद्धिर्व्यतितरिष्यति ।\nतदा गन्तासि निर्वेदं श्रोतव्यस्य श्रुतस्य च ॥\n\nयदा तव बुद्धिः मोहमालिन्यं तरति, तदा श्रोतव्यस्य श्रुतस्य च पूर्णं फलं प्राप्स्यसि। बुद्धिः कतिपि श्रुत्वापि सन्दिग्धा चेत् श्रवणं निष्फलम् — पठनश्रवणाभ्यां मनोमालिन्यं क्षालनीयम्।",
  "2.53": "श्रुतिविप्रतिपन्ना ते यदा स्थास्यति निश्चला ।\nसमाधावचला बुद्धिस्तदा योगमवाप्स्यसि ॥\n\nआदौ श्रुतिभिः बुद्धिः विक्षुब्धा भवति, वेदार्थं प्रति मनः विरुद्धं चिन्तयति। परन्तु मनसि निर्मले सति त्रिगुणातीततत्त्वे बुद्धिः दृढा भवति। एकवारं मनः शुद्धं सति वेदेन सह श्रुतिगूढं (tune) भवति, वेदोक्तं स्वचिन्तनं च ऐक्यं गच्छति। ध्याने मनः भगवति स्थिरं भवति; अतः परं निश्चलसमाधौ स्वरूपचिन्तने भगवतः वास्तविकं रूपं साक्षात्क्रियते। तत्र मनः न कार्यं करोति, आत्मा एव कार्यं करोति — आत्मचक्षुषा भगवत्साक्षात्कारः एव साधनायाः पूर्णं फलम्।",
  "2.54": "अर्जुन उवाच —\nस्थितप्रज्ञस्य का भाषा समाधिस्थस्य केशव ।\nस्थितधीः किं प्रभाषेत किमासीत व्रजेत किम् ॥\n\nहे ब्रह्मरुद्रनियामक, समाधिम् आरोढुं समर्थं दृढबुद्धिं पुरुषं कथं परिचिनुयाम? सः किं वदति, कथम् आस्ते, कथं व्रजति?\n\nअत्र कृष्णः स्वोपदेशं विरम्य अर्जुनप्रश्नं शृणोति। मनुष्यस्य प्रज्ञा दृढा भवितुम् अर्हति; सत्यसाक्षात्कारेण स्थितप्रज्ञः भवितुं शक्यते। तादृशं स्थितप्रज्ञं कथं परिचिनुयाम इति अर्जुनस्य प्रश्नः — बाह्यवेषभूषणेन तत्परिचयः असाध्यः।\n\nअर्जुनः कृष्णं 'केशव' इति सम्बोधयति — केशव इति कह+ईश, ब्रह्मशक्तिः शिवशक्तिः च तयोः परशक्तिः केशवः। 'जगते प्रकाशं ददतः त्वत्तः इदं ज्ञातुम् उत्सुकः अस्मि' इत्यर्थेन एषा सम्बोधना।\n\nमनुष्यस्य दुःखमूलं क्षुद्रकामनाः एव। स्थितप्रज्ञः तु एतत् जञ्जालं न प्रविश्य स्वान्तरङ्गमहानन्दम् आस्वादयन् सदा प्रसन्नः तिष्ठति।\n\nअत्र कृष्णः अर्जुनं 'पार्थ' इति सम्बोधयति — सत्यसाधनासागरं तीर्णः इत्यर्थः। अग्रिमेषु त्रिषु श्लोकेषु कामनात्यागस्य स्वरूपं कृष्णः वर्णयति।",
  "2.55": "प्रजहाति यदा कामान्सर्वान्पार्थ मनोगतान् ।\nआत्मन्येवात्मना तुष्टः स्थितप्रज्ञस्तदोच्यते ॥\n\nमनोगतान् सर्वान् कामान् त्यक्त्वा परमात्मनि एव स्थितः, तत्प्रसादेन तुष्टः स्थितप्रज्ञः उच्यते। सः क्षुद्रकामनाः त्यक्त्वा स्वान्तः ज्ञानानन्दमयं भगवन्तं पश्यन् सदा सन्तुष्टः तिष्ठति।",
  "2.56": "दुःखेष्वनुद्विग्नमनाः सुखेषु विगतस्पृहः ।\nवीतरागभयक्रोधः स्थितधीर्मुनिरुच्यते ॥\n\nसुखदुःखे अहोरात्रवत् नित्ये, सर्वान् स्पृशतः। कदाचित् अनिच्छया अपि सुखम् आगच्छति, कदाचित् दुःखं मालावत् अनुगच्छति। धनेन दुःखं न निवार्यते, सुखं न क्रेतुं शक्यते। अनिवार्यार्थे रुदन् उपविष्टः किं लभेत? दुःखं 'सुखसिद्धता', सुखं 'दुःखसिद्धता' — इमौ जीवनस्य अनिवार्यौ द्वन्द्वौ। समत्वं मनसि अभ्यसनीयम्।\n\nदुःखे दृढमनाः भवेत् इति वक्तुं सुलभम्, आचरितुं दुष्करम्। महाभारते अभिमन्युमरणे अर्जुनस्य अश्रुपातः एव दृष्टान्तः — भगवत एव उपदेशं प्राप्तः, भगवत्सारथ्ये युद्धं प्रविष्टः स्थितप्रज्ञः अर्जुनः अपि पुत्रमरणे शोचति। दुःखं स्वीकर्तुं अभ्यासः आवश्यकः, अन्यथा जीवनं दुस्तरं भवति।\n\nरागभयक्रोधाः त्रयः मनसि न स्युः — दुःखपूर्वस्थितिः भयम्, भयोत्तरस्थितिः दुःखम्। अतिकामना रागः, अलाभे निराशा; दुर्बलेभ्यः लाभे क्रोधः, बलिष्ठेभ्यः लाभे भयम् — एतत् सर्वं मनसः चाञ्चल्यम्। व्यासोक्तिः — 'अस्मिन् जगति अनुचितं किमपि न अभूत्, न भविष्यति च'। भवितव्यं भवत्येव, तच्चिन्तया न फलम्। एतादृशचिन्तनशीलता स्थितप्रज्ञत्वम्।\n\n'मुनि' शब्दः कामक्रोधजयी इत्यर्थः — यत्किञ्चिदागतं भगवत्प्रसादमेव इति सुखदुःखे समदृष्टिः मुनिः। 'त्वमपि तादृशः मुनिः भव' इति सन्देशः।",
  "2.57": "यः सर्वत्रानभिस्नेहस्तत्तत्प्राप्य शुभाशुभम् ।\nनाभिनन्दति न द्वेष्टि तस्य प्रज्ञा प्रतिष्ठिता ॥\n\nदुःखागमे न कङ्गेदः, सुखागमे न गर्वः, निर्लिप्तताभ्यासः कर्तव्यः — अतिसक्तिः न कुत्रापि; मानससमत्वं साध्यम्, इति कृष्णः वदति। दुःखं कमपि न त्यजति — दैवांशसम्भूतानां पाण्डवानां कष्टं पश्यन्तः स्पष्टम् एतत्। ज्ञानिनः अज्ञानिनः वा सर्वेभ्यः कष्टम् आगच्छति; कष्टदर्शनमनःस्थितिः एव परिवर्तनीया। 'इच्छानिच्छातीतः अस्मि' इति सत्यज्ञानेन जीवनं सुगमं भवति।\n\nज्ञानिनाम् एषा मनःस्थितिः; सामान्यमनुष्याणां इन्द्रियनिग्रहः दुष्करः, न तु असाध्यः — निरन्तरसाधनेन साध्यते। कथं साधकः इन्द्रियनिग्रहेण साधनां कुर्यात् इति कृष्णः दृष्टान्तेन अग्रे वर्णयति।",
  "2.58": "यदा संहरते चायं कूर्मोऽङ्गानीव सर्वशः ।\nइन्द्रियाणीन्द्रियार्थेभ्यस्तस्य प्रज्ञा प्रतिष्ठिता ॥\n\nयथा कूर्मः स्वाङ्गानि पूर्णतः कर्परे संहरति, तथा इन्द्रियाणि विषयेभ्यः प्रत्याहरतः प्रज्ञा दृढा भवति। इन्द्रियाणि एव अस्मान् मार्गभ्रष्टान् कुर्वन्ति; अतः पञ्चेन्द्रियाणि दृढमनःकोट्टे संहृत्य अन्तर्मुखं कर्तव्यम् — अन्तरङ्गदृष्ट्या सर्वं विश्लिष्य तत्रस्थं शुभं गृहीत्वा तत्स्रष्टुः भगवतः महिमानुसन्धानं कार्यम्।\n\nभगवत्सृष्टम् इमं प्रपञ्चं पश्यन्तः तत्पृष्ठस्थां विश्वशक्तिं चिन्तयेम — इदम् एव अन्तर्मुखं दर्शनम्। सर्वत्र भगवत्सान्निध्यं, प्रतिविभूतौ भगवतः अंशः इति ज्ञाने सति किमपि मार्गभ्रंशं न करोति। प्रपञ्चं परिवर्तयितुं न शक्नुमः; तं यथावत् स्वीकृत्य जीवनम् एव समस्यारहितम्। एवम् इन्द्रियाणि अन्तर्मुखीकृतवतः प्रज्ञा दृढा भवति।",
  "2.59": "विषया विनिवर्तन्ते निराहारस्य देहिनः ।\nरसवर्जं रसोऽप्यस्य परं दृष्ट्वा निवर्तते ॥\n\nस्थितप्रज्ञत्वाय इन्द्रियाणि अन्तर्मुखीकरणीयानि, परन्तु तत् न सुलभम्। एकान्ताभ्यासेन दर्शनश्रवणेच्छाः निवर्तेरन्, परन्तु रसना-शृङ्गारेच्छे दुर्निवारे। अतः ब्रह्मचर्यपालनाय शृङ्गारभोगानुभवपूर्वं दाम्पत्यज्ञानेन ब्रह्मचर्ये पदं न्यसनं सुलभम्। नियमिताहारः उपवासः च अध्यात्मपूरकौ; अत्याहारः तामसराजसाहारश्च (यथा — अरहरदालि, पलाण्डु, लशुनं, शिग्रुफलं, अतिमसालायुक्तं मांसाहारश्च) अध्यात्मसाधनाय सर्वथा विरुद्धाः। सामान्यतः एकान्ताहारनियन्त्रणाभ्यां रसनाभोगचापल्ये पूर्णतया न निगृहीतेऽपि, भगवति सम्पूर्णशरणागत्या ते नश्यन्ति।",
  "2.60": "यततो ह्यपि कौन्तेय पुरुषस्य विपश्चितः ।\nइन्द्रियाणि प्रमाथीनि हरन्ति प्रसभं मनः ॥\n\nसाधकः यत्किञ्चित् जानन् यतमानोऽपि, इन्द्रियाणि बलात् मनः क्षोभयित्वा हरन्ति। अध्यात्मपथे मनः दृढं भवेत्, परन्तु मनसि दृढे इन्द्रियाणि शिथिलानि भवन्ति — रागद्वेषौ मा कुर्यात्, कामक्रोधौ मा वशयतु इति दृढसंकल्पेऽपि इन्द्रियाणि मनः विक्षोभयन्ति। शास्त्रज्ञमपि परोक्षतत्त्वदर्शिनमपि एषा समस्या न त्यजति। अतः पूर्वविश्वासस्य त्यागग्रहणयोः संशयः जायते — इदं प्रतिसाधकानुभवगम्यम्। गम्भीरा अपि इयं समस्या, तस्याः सरलं समाधानं कृष्णः अग्रिमश्लोके सूचयति।",
  "2.61": "तानि सर्वाणि संयम्य युक्त आसीत मत्परः ।\nवशे हि यस्येन्द्रियाणि तस्य प्रज्ञा प्रतिष्ठिता ॥\n\nइन्द्रियचाञ्चल्यं मनश्च्युतिः वा सर्वान् बाधते। एतन्निवारणाय इन्द्रियाश्वान् मनोरूपलगामेन नियम्य दृढं धारयेत्। एतत्कार्यसिद्ध्यर्थं प्रथमं भगवते शरणागतिः आवश्यकी — 'एतद्दायित्वं मह्यं समर्पय' इति कृष्णः वदति। स्वप्रयत्नमात्रेण किमपि साधयितुम् अशक्यम्; प्रयत्नः कर्तव्यः, भगवति प्रार्थ्य शरणागत्या यदा वयं तिष्ठामः तदा एकदा अनुभूत्यनुग्रहः भवति, सम्पूर्णेन्द्रियनिग्रहः च साध्यते। एतत् साधनं बहुजन्मसाध्यम्; निरन्तरसाधनेन एव यशः प्राप्यते।",
  "2.62": "अस्माकम् अधःपतनस्य कारणं कथं मनः भवति, इति कृष्णः अग्रयोः श्लोकयोः वर्णयति।\n\nध्यायतो विषयान्पुंसः सङ्गस्तेषूपजायते ।\nसङ्गात्सञ्जायते कामः कामात्क्रोधोऽभिजायते ॥\n\nविषयचिन्तनशीलस्य पुंसः तेषु सङ्गः वर्धते, सङ्गात् कामः, कामविघाते क्रोधः जायते।",
  "2.63": "क्रोधाद्भवति सम्मोहः सम्मोहात्स्मृतिविभ्रमः ।\nस्मृतिभ्रंशाद्बुद्धिनाशो बुद्धिनाशात्प्रणश्यति ॥\n\nक्रोधात् सम्मोहः — अकार्यकरणेच्छा; ततः विधिनिषेधविस्मरणम्, ततः बुद्धिभ्रंशः, ततः सर्वनाशः! वस्तुसम्पर्केण मोहः वर्धते — परिचयात् स्नेहः, स्नेहात् आसक्तिः, ततः ममत्वेच्छा, अपूर्तौ क्रोधः — क्रोधमूलं प्रेम एव! कामनात्यागेन एव क्रोधनिवृत्तिः। आसक्त्या इच्छावृद्धिः, अपूर्तौ क्रोधः, क्रोधात् सम्मोहः, ततः न्यायान्यायविवेकनाशः, प्रतीकारहठः, पूर्णबुद्धिनाशः, आत्मपतनम् — सर्वनाशः!\n\nबुद्धिनाशे मनः मृतवत्, जीवः नरकपथगामी भवति। उन्नत्यर्थं परमात्ममहत्त्वज्ञानेन तच्छरणागतिः आवश्यकी। सदाचिन्तनेन एव आत्मोन्नतिः सम्भवति — तदर्थं प्रथमम् आसक्तिः न्यूनीकरणीया। न स्नेहत्यागः अभिप्रेतः, अपि तु मोहरहितः स्नेहः — 'यदागतं तदागच्छतु' इति दृढनिश्चयः। अतिमोहः एव दुःखकारणम्; सर्वैः सह स्नेहं कुर्वन् अपि असक्तः तिष्ठन् — इदमेव साधनासुखयोः मूलमन्त्रम्।\n\nमनः सदा प्रसन्नं स्यात्; अप्रसन्नत्वे मानसदैहिकारोग्यहानिः। कस्मिन्नपि प्रसङ्गे अविचलितत्वं प्रसन्नता। तत्प्राप्त्युपायं अग्रिमश्लोकः वर्णयति।",
  "2.64": "रागद्वेषवियुक्तैस्तु विषयानिन्द्रियैश्चरन् ।\nआत्मवश्यैर्विधेयात्मा प्रसादमधिगच्छति ॥\n\nइन्द्रियनिग्रहः न भोगत्यागेन ऐहिकव्यवहारत्यागेन नेत्रनिमीलनेन वा — इन्द्रियेण विषयग्रहणं निरन्तरं भवतु, परन्तु तत्प्रभावितः तद्दासः मा भव इति कृष्णः वदति। विषयान् इन्द्रियैः अनुभव, परन्तु तत्र रागद्वेषौ मा आसञ्जय — यदागतं तथैव अनुभव। तादृशमनोवृत्त्या इन्द्रियं यत्किमपि गृह्णातु, न भयम्। तटस्थमनसा किमपि श्रवणदर्शने न अपायः — यथा मार्गे मित्रं मिलित्वा वयं संभाषामहे, परन्तु तस्य वस्त्रवर्णं न स्मरामः, यतः न आवश्यकम्। एवं तटस्थमनसा गृहीते किमपि विषये न अपायः। एतेन इन्द्रियाणि वशे तिष्ठन्ति, मनः विधेयं भवति। अन्तः निर्लिप्ततया सर्वैः सह अपि एकान्तत्वं साध्यते — अन्तरङ्गभेदः एव इयम् अवस्था। एवं जीवितुं शिक्ष्यमाणे मनः निर्मलं भवति, सन्तोषः सदा उच्छलति, साधनं सुगमं भवति।",
  "2.65": "प्रसादे सर्वदुःखानां हानिरस्योपजायते ।\nप्रसन्नचेतसो ह्याशु बुद्धिः पर्यवतिष्ठते ॥\n\nमनसि मलिने सति सर्वं मलिनम्; निर्मले सति सर्वं निर्मलम्। मनःस्वच्छताम् अनवधार्य सर्वं कार्यं व्यर्थम्। मनसि निर्मले सति सर्वं दुःखं स्वयमेव तिरोभवति — इयम् एव दुःखातीता आनन्दावस्था। निर्मलं मनः भगवज्ज्ञानसाहाय्यकं भवति; मलिनेन मनसा भगवच्चिन्तनम् असम्भवम्। भगवज्ज्ञानोत्तरं दुःखं नास्ति — बुद्धिः दृढा भगवदपरोक्षज्ञाने प्रतिष्ठिता भवति। कुत्रापि चिन्तने गते तत् भगवत्येव अवतिष्ठते; यत्किमपि श्रुतं दृष्टं वा तत्पृष्ठस्थजगन्मूलशक्तिचिन्तनम् एव मनसि उदेति। निर्मलं मनः भगवन्मयं भवति; भगवति मनसि पूर्णे सति सर्वम् आनन्दमयम् — अनन्तः अयम् आनन्दः।",
  "2.66": "नास्ति बुद्धिरयुक्तस्य न चायुक्तस्य भावना ।\nन चाभावयतः शान्तिरशान्तस्य कुतः सुखम् ॥\n\nअनियतमनसः निर्मला बुद्धिः नास्ति, ध्यानम् अपि नास्ति; अध्यानिनः मुक्तिः नास्ति [भगवति मनः न स्थिरं भवति]; अमुक्तस्य कुत्र सुखम्? सुखाय शान्तिः अपेक्ष्यते; अप्रसन्नं विक्षिप्तं मनः भगवन्तं न प्राप्नोति। यस्य मनः भगवति संयोगं न लभते तस्य अपरोक्षज्ञानं नास्ति, तन्मनः न निर्मलं भवति, एकाग्रचिन्तनम् असाध्यम्, अतः यथार्थज्ञानं नास्ति, ध्यानम् असाध्यम्। एकस्मिन् वस्तुनि एकाग्रचिन्तनम् एव ध्यानम् — तदर्थम् एकाग्रता आवश्यकी, इयमेव 'भावना'। एकाग्रे मनसि एव गभीरं चिन्तनं सम्भवति; तद्विना वैशाल्यज्ञानं न भवति, शान्तिः च न भवति। शान्तिशब्दस्य द्वौ अर्थौ — बाह्यतः आनन्दमयी स्थितिः, शास्त्रानुसारेण मोक्षः एव; अध्यानिनः मोक्षः नास्ति, तस्य सुखं नास्ति। अन्यः अर्थः — आनन्दस्य पराकाष्ठा; मनसि भगवति स्थिते शान्तिः लभ्यते। एवम् इन्द्रियसंयमेन मनःएकाग्रतया गभीरचिन्तनेन सत्यं ज्ञातव्यम् — बहिःप्रपञ्चं त्यक्त्वा अन्तःप्रपञ्चे गभीरतया निमग्नस्य एव सत्यसाक्षात्कारः, तद्विना सुखं नास्ति।",
  "2.67": "इन्द्रियाणां हि चरतां यन्मनोऽनुविधीयते ।\nतदस्य हरति प्रज्ञां वायुर्नावमिवाम्भसि ॥\n\nविषयगामीनि इन्द्रियाणि अनुसरत् मनः साधकस्य प्रज्ञां हरति — यथा वायुः जलधौ नावं दिशिभ्रष्टां करोति। मनसः स्वभावः एव अयम् — यत् अभ्यस्तं तदेव रोचते, नूतनं निराक्रियते, परिचितम् एव प्रियम्। अन्तःप्रपञ्चः मनसः अपरिचितः, अतः तत्र न प्रवहति। दृढोक्त्या मनः अन्तर्मुखं भवितुम् अर्हति, परन्तु तत्प्रयत्नं न कुर्मः — एतदेव अपायं कृष्णः वर्णयति।\n\nबाल्यात् यत् अभ्यासितं तदेव मनः अनुसरति — यथा बाल्यात् शाकाहारिणे मांसदर्शने घृणा, मांसविक्रेतुः तु तन्मध्ये स्थितः अपि न घृणां वहति। एतत् सर्वं मनसः प्रशिक्षणम् एव। इन्द्रियाणि नित्यं यद्दृश्यन्ते तदेव मनः अभ्यस्यति — अस्मात् मनसः स्वभावम् अज्ञात्वा जीवनं भयावहम्, प्रज्ञा अपहर्तुं शक्यते।\n\nवयं शिडोलपोतयाने नाविकाः इव; मनः तत्र बद्धं शिडम्। तन्नियन्त्रणकलां न जानीमः चेत् वायुदिशि एव गच्छामः, न गन्तव्यस्थानम्। मनोनियन्त्रणकलाम् अजानतः जीवनं छिन्नविच्छिन्नं भवति, वात्याहतपर्णवत्।",
  "2.68": "तस्माद्यस्य महाबाहो निगृहीतानि सर्वशः ।\nइन्द्रियाणीन्द्रियार्थेभ्यस्तस्य प्रज्ञा प्रतिष्ठिता ॥\n\nहे महाबाहो, यस्य इन्द्रियाणि सर्वथा विषयेभ्यः निगृहीतानि तस्य प्रज्ञा दृढा भवति। इन्द्रियनिग्रहं विना मनोनिग्रहः दुष्करः, अतः प्रथमम् इन्द्रियाणि प्रशिक्षणीयानि — बाल्यादेव उत्तमसंस्काराः आवश्यकाः, यतः बाल्याभ्यासस्य त्यागः दुष्करः। पूर्वं गृहे विद्यालये च संस्काराः दत्ताः, परन्तु अद्य तादृशमार्गदर्शनं विना युवपीढी वात्याहतनौकावत्। बाल्यात् इन्द्रियनिग्रहसंस्कारेण मनःदृढत्वम्, एकाग्रता, प्रज्ञादार्ढ्यं च साध्यते।\n\nएवं कृष्णः मनोनिग्रहस्य, तन्नियन्त्रितमनसः स्वभावस्य, ज्ञानिनां लक्षणस्य च विस्तृतं मनोविश्लेषणं कृतवान्। अर्जुनप्रश्नस्य उत्तरं कृष्णः अग्रिमश्लोके ददाति — स्थितप्रज्ञस्य स्वरूपं, वाणीं, आचरणं च।",
  "2.69": "या निशा सर्वभूतानां तस्यां जागर्ति संयमी ।\nयस्यां जाग्रति भूतानि सा निशा पश्यतो मुनेः ॥\n\nसामान्यमनुष्यस्य दिवा एव सत्यसाक्षात्कारिणः निशा; जगतः सर्वभूतानां निशा एव साधकस्य दिवा। साधकः लौकिकव्यवहारे प्रवृत्तिरहितः, अस्मान् बालवत् मुग्धवत् वा भासते, अज्ञैः उन्मत्तवत् अपि दृश्येत — यतः लौकिकप्रपञ्चे स्थितः अपि तेन न मिश्रितः स्वान्तरानन्दम् एव सदा आस्वादयति। भगवद्दर्शने ज्ञानिनः शेषं सर्वं तमः भासते; अद्भुतदर्शनविस्मये तदेकचित्तः तिष्ठति। भगवद्दर्शनाय शास्त्रश्रवणं नित्यं कर्तव्यम्, श्रवणमात्रं न पर्याप्तम् — मननं निदिध्यासनं च अत्यावश्यकम्, इदमेव 'आत्मा वा अरे द्रष्टव्यः श्रोतव्यः मन्तव्यः निदिध्यासितव्यः च' इति। मननशीलः 'मुनिः', सः एव 'पश्यः' भगवद्दर्शनसमर्थः वा दृष्टवान्।\n\nअद्य समाजे सत्यसाक्षात्कारिणं परिचेतुं दुष्करम्। सिद्धपुरुषाः सर्वे सत्यदर्शिनः न — चमत्कारकर्तारः भगवद्दर्शिनः इति न वक्तुं शक्यते, यतः सच्चा साधकः सामान्यतः चमत्कारं न करोति; अत्यावश्यके एव जगद्धिताय कुर्यात्। निरन्तरं सत्यान्वेषणेन सिद्धिं लब्ध्वा एव स्थितप्रज्ञत्वं साध्यते।",
  "2.70": "आपूर्यमाणमचलप्रतिष्ठं समुद्रमापः प्रविशन्ति यद्वत् ।\nतद्वत्कामा यं प्रविशन्ति सर्वे स शान्तिमाप्नोति न कामकामी ॥\n\nयथा सर्वाः नद्यः पूर्णं समुद्रं प्रविशन्तः अपि तम् न उत्प्लावयन्ति, तथा सर्वे विषयाः यं प्रविश्य अपि न विचालयन्ति सः एव शान्तिम् आप्नोति, न तु कामानुगामी। भगवद्दर्शिनः मनः सदा आनन्दमयम्, भगवति स्थितम्; सः क्षुद्रनदीवत् न, समुद्रवत् — सर्वभोगप्रवेशेऽपि अविचलितः सुखदुःखातीतः तिष्ठति, नित्यप्रसन्नमनाः भगवन्निष्ठया मोक्षं प्राप्नोति। कामानुगामी तु ततः अनिर्गच्छन् कदापि वास्तविकं सुखं न विन्दति।",
  "2.71": "विहाय कामान्यः सर्वान्पुमांश्चरति निःस्पृहः ।\nनिर्ममो निरहङ्कारः स शान्तिमधिगच्छति ॥\n\nयः भोगेच्छां त्यक्त्वा यदागतं तत् प्रसन्नतया अनुभवति सः सच्चा साधकः। नियताहारनिद्रामैथुनः, निर्भयः पूर्णभगवद्रक्षाज्ञानस्थः, कामाकाङ्क्षाभिः अपराजितः, उत्थानपतनयोः अविचलितः जीवन् सः वास्तविकः 'पुरुषः'। तस्य अहंममभावः कदापि न भवति, सः मुक्तिं प्राप्नोति।",
  "2.72": "एषा ब्राह्मी स्थितिः पार्थ नैनां प्राप्य विमुह्यति ।\nस्थित्वास्यामन्तकालेऽपि ब्रह्मनिर्वाणमृच्छति ॥\n\nहे पार्थ, इयं ब्रह्मज्ञानिनः लक्षणम् — प्राप्य पुनः न विमुह्यति। अन्तकालेऽपि अस्यां स्थितः देहेन अपि अमरं परतत्त्वं प्राप्नोति। भगवति स्थितस्य लक्षणं ब्राह्मी स्थितिः — इदानीं यत् उक्तं तत् ब्रह्मज्ञानिनः, ब्रह्मणि स्थितप्रज्ञस्य लक्षणम्। तादृशं ब्रह्मज्ञानिनं बाह्यक्रियया वेषभूषणेन वा न परिचेतुं शक्यते; तस्य मानसी स्थितिः एव तत्स्थानं सूचयति। मरणकाले अपि भगवत्प्रज्ञा जाग्रती चेत् सः पुनर्जन्मरहितं मोक्षं प्राप्नोति।\n\nइति द्वितीयोऽध्यायः समाप्तः।\n\nतृतीयोऽध्यायः\n\nद्वितीयाध्याये कृष्णः भगवज्ज्ञानं तत्प्राप्त्युपायं च वर्णितवान्। एकत्र ज्ञानं सर्वश्रेष्ठम्, ज्ञानात् कर्म तुच्छम् इति वदति; अन्यत्र अर्जुनं तामसं युद्धं कर्तुम् आदिशति! ज्ञानमेव श्रेष्ठं चेत् किमर्थम् इदं रागद्वेषयुक्तं तामसं युद्धम्? अनेन प्रश्नेन तृतीयोऽध्यायः आरभ्यते।\n\nअर्जुन उवाच —\nज्यायसी चेत्कर्मणस्ते मता बुद्धिर्जनार्दन ।\nतत्किं कर्मणि घोरे मां नियोजयसि केशव ॥\n\nहे जनार्दन, कर्मणः बुद्धिः श्रेयसी इति ते मतं चेत्, कथं मां घोरे कर्मणि नियोजयसि, हे केशव? कृष्णस्य ज्ञानकर्मविवरणेन अर्जुनः विभ्रान्तः — कदाचित् ज्ञानमार्गं श्रेष्ठं वदति, कदाचित् युद्धं कुर्विति। अत्र अर्जुनः पृच्छति — 'जनार्दन' 'केशव' इति द्वे विशेषनाम्नी सम्बोध्य। जन-अर्दनः दुर्जननाशकः; अत्र सम्मिलिताः सर्वे दुर्जनाः न, तर्हि हननं कथं श्रेष्ठम्? शेषतः 'केशव' सम्बोधनं शरणागतिं सूचयति — क+ईश+व, सृष्टिकारणं चतुर्मुखब्रह्मा, संहारकारणं शङ्करः, तयोः परशक्तिः केशवः।\n\nव्यामिश्रेणेव वाक्येन बुद्धिं मोहयसीव मे ।\nतदेकं वद निश्चित्य येन श्रेयोऽहमाप्नुयाम् ॥\n\n'व्यामिश्रेण' इति विरोधाभासेन मम निर्णयशक्तिः मुह्यति — अतः एकं निश्चित्य वद, येन अहं श्रेयः प्राप्नुयाम् इति अर्जुनः कृष्णं पृच्छति।",
  "3.1": "तृतीयोऽध्यायः\n\nद्वितीयाध्याये कृष्णः भगवज्ज्ञानं तत्प्राप्त्युपायं च वर्णितवान्। एकत्र ज्ञानं सर्वश्रेष्ठम्, ज्ञानात् कर्म तुच्छम् इति वदति; अन्यत्र अर्जुनं तामसं युद्धं कर्तुम् आदिशति! ज्ञानमेव श्रेष्ठं चेत् किमर्थम् इदं रागद्वेषयुक्तं तामसं युद्धम्? अनेन प्रश्नेन तृतीयोऽध्यायः आरभ्यते।\n\nअर्जुन उवाच —\nज्यायसी चेत्कर्मणस्ते मता बुद्धिर्जनार्दन ।\nतत्किं कर्मणि घोरे मां नियोजयसि केशव ॥\n\nहे जनार्दन, कर्मणः बुद्धिः श्रेयसी इति ते मतं चेत्, कथं मां घोरे कर्मणि नियोजयसि, हे केशव? कृष्णस्य ज्ञानकर्मविवरणेन अर्जुनः विभ्रान्तः — कदाचित् ज्ञानमार्गं श्रेष्ठं वदति, कदाचित् युद्धं कुर्विति। अत्र अर्जुनः पृच्छति — 'जनार्दन' 'केशव' इति द्वे विशेषनाम्नी सम्बोध्य। जन-अर्दनः दुर्जननाशकः; अत्र सम्मिलिताः सर्वे दुर्जनाः न, तर्हि हननं कथं श्रेष्ठम्? शेषतः 'केशव' सम्बोधनं शरणागतिं सूचयति — क+ईश+व, सृष्टिकारणं चतुर्मुखब्रह्मा, संहारकारणं शङ्करः, तयोः परशक्तिः केशवः।",
  "3.2": "व्यामिश्रेणेव वाक्येन बुद्धिं मोहयसीव मे ।\nतदेकं वद निश्चित्य येन श्रेयोऽहमाप्नुयाम् ॥\n\n'व्यामिश्रेण' इति विरोधाभासेन मम निर्णयशक्तिः मुह्यति — अतः एकं निश्चित्य वद, येन अहं श्रेयः प्राप्नुयाम् इति अर्जुनः कृष्णं पृच्छति।",
  "3.3": "भगवानुवाच —\nलोकेऽस्मिन्द्विविधा निष्ठा पुरा प्रोक्ता मयानघ ।\nज्ञानयोगेन साङ्ख्यानां कर्मयोगेन योगिनाम् ॥\n\nहे अनघ, अस्मिन् लोके द्विविधा निष्ठा (मोक्षमार्गः) मया पूर्वं उक्ता — ज्ञानप्रधानसाधनेन ज्ञानमार्गिणां साङ्ख्यानां; कर्मप्रधानसाधनेन कर्ममार्गिणां योगिनाम्। पूर्वं ज्ञानमार्गं कर्ममार्गं च उक्तवान् कृष्णः, अत्र कस्मिन् स्तरे किं प्रधानम् इति विवृणोति। इतः कर्मयोगस्य विशेषवर्णनम् आरभ्यते।\n\n'निष्ठा' इति जीवनगतिः अन्तिमा स्थितिः मोक्षः इत्यर्थः। साङ्ख्याः ज्ञानमार्गसाधकाः, योगिनः कर्मसाधकाः। उपरिदृष्ट्या इदं वदति इव — 'ज्ञानसाधकः ज्ञानमार्गेण, कर्मसाधकः कर्ममार्गेण गच्छतु' इति। अर्जुनः कर्मसाधकः इति कृष्णः युद्धम् आदिशति इव भाति, किन्तु न एषः वास्तवार्थः। अर्जुनः तत्कालमहाज्ञानिषु अन्यतमः; अतः उपरितलार्थः न ग्राह्यः, गम्भीरचिन्तनम् अपेक्षितम्।\n\nशास्त्राणि वदन्ति — ज्ञानेनैव मोक्षः, न अन्यथा; तथापि मोक्षसाधनाय ज्ञानं कर्म च उभयम् आवश्यकम्। ज्ञानाऽपूरकं कर्म न कर्म। छान्दोग्योपनिषदि उक्तम् — 'यदेव विद्यया करोति श्रद्धयोपनिषदा तदेव वीर्यवत्तरं भवति विज्ञानं यज्ञं तनुते' इति — ज्ञानपूर्वकं कृतं कर्म सफलम्, अन्यथा वृथा। कृष्णेन उक्तं — एकः कर्मप्रदः मार्गः (जनकादिवत्), अन्यः ज्ञानप्रदः मार्गः (सनकादिवत्)।",
  "3.4": "न कर्मणामनारम्भान्नैष्कर्म्यं पुरुषोऽश्नुते ।\nन च संन्यसनादेव सिद्धिं समधिगच्छति ॥\n\nकर्मणाम् अनारम्भात् साधकः कर्मबन्धनान्न मुच्यते; कर्मफलत्यागमात्रेण अपि सिद्धिः न लभ्यते।\n\nशास्त्रेषु उक्तं — कर्म बन्धनमार्गः, ज्ञानं मुक्तिमार्गः इति; किन्तु कृष्णः द्वौ मार्गौ मोक्षाय वदति — ज्ञानप्रदं कर्मप्रदं च। शरीरे स्थितस्य जीवस्य अकर्मणा स्थातुं न शक्यते; देहसत्तायां कर्मक्रिया अनिवार्या। कर्मत्यागमात्रेण मोक्षो न लभ्यते, कर्मत्यागः स्वयमेव असम्भवः। ज्ञानाऽपूरकं यान्त्रिकं कर्म बन्धकम्; ज्ञानपूरकं कर्म कदापि न बध्नाति। फलनैरपेक्ष्यमात्रेण अपि सिद्धिः न भवति; केवलकर्मत्यागेन सिद्धिः कदापि न लभ्यते।",
  "3.5": "न हि कश्चित्क्षणमपि जातु तिष्ठत्यकर्मकृत् ।\nकार्यते ह्यवशः कर्म सर्वः प्रकृतिजैर्गुणैः ॥\n\nकोऽपि क्षणमात्रम् अपि अकर्मकृत् स्थातुं न शक्नोति; प्रत्येकः प्रकृतिगुणैः अनभिज्ञतया (भगवदधीनतया) कर्म करोति एव।\n\nकर्मत्यागेन सिद्धिः न भवति, कर्मत्यागः स्वयमेव अशक्यश्च। अन्नमयः प्राणमयश्च कोशौ निरन्तरं कार्यरतौ; जीवितकाले निष्क्रियत्वम् असम्भवम्। देहस्थजीवः देहेन मनसा वाचा च कार्यते; तत् जीवस्वाधीनं न, भगवदधीनम्। विश्वम् प्रकृतितः सृष्टं, तस्याः मूलद्रव्यं सत्त्वरजस्तमांसि; जीवस्य स्वभावानुसारं गुणत्रयस्य प्रभावः भवति। अतः निष्क्रियता निरर्थिका; कर्तव्यशीलतया प्रवर्तितव्यम्, तथापि मनः ऐहिकातीतसत्यजागरूकं स्यात्।",
  "3.6": "कर्मेन्द्रियाणि संयम्य य आस्ते मनसा चरन् ।\nइन्द्रियार्थान्विमूढात्मा मिथ्याचारः स उच्यते ॥\n\nयः कर्मेन्द्रियाणि निगृह्य मनसैव इन्द्रियविषयान् चिन्तयति सः विमूढात्मा मिथ्याचारी उच्यते।\n\nबाह्यवेषे प्राधान्यं, अन्तः सर्वकामनासु आसक्तिः — इदं कपटधार्मिकत्वम्। अन्तःशुद्धिः बाह्याचारात् प्राक् आवश्यकी; अन्यथा उद्धारो नास्ति।",
  "3.7": "य इन्द्रियाणि मनसा नियम्यारभतेऽर्जुन ।\nकर्मेन्द्रियैः कर्मयोगमसक्तः स विशिष्यते ॥\n\nहे अर्जुन, यः मनोबलेन इन्द्रियाणि जित्वा फलासक्तिं त्यक्त्वा कर्मेन्द्रियैः साधनं करोति सः विशिष्यते।\n\nशुद्धचित्तः दृढेन्द्रियसंयमी कर्मयोगं साधयति — इयं शुद्धाध्यात्मसाधना। एतादृशसाधकः न बहिरन्तर्भिन्नः; मनोबलेन इन्द्रियाणि जित्वा फलासक्तिं त्यक्त्वा उन्नतिं गच्छति।",
  "3.8": "नियतं कुरु कर्म त्वं कर्म ज्यायो ह्यकर्मणः ।\nशरीरयात्रापि च ते न प्रसिध्येदकर्मणः ॥\n\nस्वस्वभावानुगुणं ज्ञानपूरकं नियतकर्म कुर्यात्; अकर्मणः कर्म श्रेष्ठम्, अकर्मणा शरीरयात्रा अपि न सिध्यति।\n\nअर्जुनस्य क्षात्रस्वभावः अन्यायविरोधी प्रजारक्षकश्च; तं त्यक्त्वा ज्ञानातिशयभ्रान्त्या तपश्चरणं न सद्योगः। \"मा भूः कदापि निष्क्रियः, स्वकर्म कुरु, भगवत्प्रज्ञया सह\" इति कृष्णवचनम्। भगवदर्पणबुद्ध्या कृतं कर्म न बध्नाति। देहसत्तापर्यन्तं कर्म अनिवार्यम्, अपरोक्षज्ञानेऽपि कर्म निरन्तरम्। कर्म बन्धकमिति शास्त्रवचनं सत्यम्, तथापि कर्म अनिवार्यमिति कृष्णोक्तिः — अग्रिमश्लोके तस्य समाधानम्।",
  "3.9": "यज्ञार्थात्कर्मणोऽन्यत्र लोकोऽयं कर्मबन्धनः ।\nतदर्थं कर्म कौन्तेय मुक्तसङ्गः समाचर ॥\n\nभगवत्पूजारूपकर्मणः अन्यत्र एव लोकः कर्मबन्धने पतति। हे कौन्तेय, फलासक्तिं त्यक्त्वा भगवत्पूजाबुद्ध्या कर्म कुरु।\n\nज्ञानपूर्वकं कर्म न बध्नाति; भगवत्प्रज्ञया कृतं प्रत्येकं कर्म यज्ञो भवति। श्वासप्रश्वासादिकं यथा अस्मदज्ञाततया एव भगवद्व्यवस्थया प्रवर्तते, तथैव सर्वकर्म भगवदधीनम् इति ज्ञात्वा कृतं कर्म कदापि न बध्नाति। 'यज्ञ' शब्दस्य अर्थः देवपूजा; दानं सङ्गतीकरणं च यज्ञान्तर्गतम्। स्वातिरिक्तवस्तुत्यागो न दानम्, अपितु स्वस्यापि अल्पे सति अन्यस्मै विभज्य भोजनं ददातीति सद्दानम्। ज्ञानार्जनार्थं सङ्गमनं सङ्गतीकरणम्, प्रवचनं तदेव।\n\nकुन्तीपुत्रत्वात् 'कौन्तेय' सम्बोधनम् — कुन्ती महाकुलजाता अपि भोगासक्ता न आसीत्, दुःखेऽपि कृष्णसान्निध्यमेव वव्रे; तादृशीमातुः पुत्रः त्वं कर्मयोगं जानासि एव इति ध्वनिः।",
  "3.10": "सह यज्ञाः प्रजाः सृष्ट्वा पुरोवाच प्रजापतिः ।\nअनेन प्रसविष्यध्वमेष वोऽस्त्विष्टकामधुक् ॥\n\nपुरा प्रजापतिः चिन्तनशीलान् मानवान् सृष्ट्वा तदाचरणीयं यज्ञं ससर्ज, उवाच च — 'अनेन इष्टं प्राप्नुत, अयं कामधुक् वोऽभीष्टं दास्यति' इति।\n\n'यज्ञ' अत्र देवोपासनाविधिः; दानं सङ्गतीकरणं च यज्ञमेव। दानस्य विशेषार्थः — स्वातिरिक्तत्यागो न, अपितु स्वस्याल्पेऽपि अन्यस्य दुःखे विभज्य दानमेव सद्दानम्। ज्ञानार्जनार्थं सम्मेलनं सङ्गतीकरणम्; प्रवचनं तदेकम्।",
  "3.11": "देवान्भावयतानेन ते देवा भावयन्तु वः ।\nपरस्परं भावयन्तः श्रेयः परमवाप्स्यथ ॥\n\nअनेन देवान् पोषय, ते देवाः वः पोषयन्तु; परस्परं पोषयन्तः परं श्रेयः प्राप्नुत।\n\nएवं यज्ञं सृष्ट्वा चतुर्मुखः उक्तवान् — 'यज्ञैः देवान् उपकुरुत, ते च वः अभीष्टं पूरयन्तु' इति। वयं स्वयमेव स्वाभीष्टं सृजाम इति भ्रमः; वस्तुतः प्रत्येककर्मणः पृष्ठे बहवः देवताशक्तयः कार्यं कुर्वन्ति। प्रत्यङ्गे अभिमानी देवता वर्तते; तेन विना किमपि कर्तुं न शक्यते। एवं जीवनं दृष्टिं श्रोत्रं सुबुद्धिं च दत्त्वा देवतासमूहः निरन्तरं कार्यं निर्वहति। अतः वयं तेभ्यः कृतज्ञाः स्याम। परस्परोपकारेणैव हितं लभ्यते।\n\nसामान्यतः अग्निमुखे कृता पूजा यज्ञ इत्युच्यते। अग्निः देवपूजायां प्रधानं प्रतीकम्, यतः सः अत्यन्तशुद्धः। अग्निः भगवत्प्रतीकः; भगवान् निराकारः तेजःपुञ्जः पवित्रश्च — इदमेव गुणं वयम् अग्नौ पश्यामः। अग्निमुखेनैव अग्निनारायणपूजा यज्ञः, न केवलं ज्वाला। एतदज्ञानेन यज्ञं कुर्वन् धूमेनैव म्रियेत! अस्माकं पूजा अग्निनारायणात् सूर्यनारायणं गत्वा पुनः नरनारायणं प्राप्नोति। अतः देवार्थं यज्ञः सदा दिवा एव भवति।",
  "3.12": "इष्टान्भोगान्हि वो देवा दास्यन्ते यज्ञभाविताः ।\nतैर्दत्तानप्रदायैभ्यो यो भुङ्क्ते स्तेन एव सः ॥\n\nयज्ञेन भावितां देवाः वः इष्टान् भोगान् दास्यन्ते; तैः दत्तं तेभ्यः अदत्त्वा यः भुङ्क्ते सः स्तेन एव।\n\nप्रकृतिः अस्मभ्यम् अपेक्षितं ददाति; अतः उपभोक्तृभिः अस्माभिः कृतज्ञतया वर्तितव्यम्। तत्त्यक्त्वा 'मम इदम्' इति अहङ्कारेण उद्धारो नास्ति। कृतज्ञतां विना प्रकृतिदत्तं गृह्णन् 'मम' इति वदन् स्तेन एव।",
  "3.13": "यज्ञशिष्टाशिनः सन्तो मुच्यन्ते सर्वकिल्बिषैः ।\nभुञ्जते ते त्वघं पापा ये पचन्त्यात्मकारणात् ॥\n\nदेवेभ्यः दत्त्वा शेषम् अश्नन्तः सन्तः सर्वपापेभ्यः मुच्यन्ते; ये तु स्वार्थं पचन्ति ते स्वपापमेव भुञ्जते।\n\nभगवदर्पितं प्रसादत्वेन स्वीकुर्वन्तः जीवनकालुष्यात् मुक्ताः शुद्धं जीवन्ति। यस्य गृहे स्वार्थमेव अन्नं पच्यते सः अन्नं न, पापमेव भुङ्क्ते। एतत् अन्नं भगवता दत्तम्; तस्मै प्रथमं कृतज्ञता देया। तत्त्यक्त्वा 'मम एव उपार्जनम्' इति भावेन पापभारः वर्धते।",
  "3.14": "अन्नाद्भवन्ति भूतानि पर्जन्यादन्नसम्भवः ।\nयज्ञाद्भवति पर्जन्यो यज्ञः कर्मसमुद्भवः ॥\n\nभूतानां जन्म अन्नात्; अन्नस्य सम्भवः पर्जन्यात् (सूर्यात्); पर्जन्यः यज्ञात्; यज्ञस्य निर्वहणं कर्मात्।",
  "3.15": "कर्म ब्रह्मोद्भवं विद्धि ब्रह्माक्षरसमुद्भवम् ।\nतस्मात्सर्वगतं ब्रह्म नित्यं यज्ञे प्रतिष्ठितम् ॥\n\nकर्मणः उद्भवः ब्रह्मणः (भगवतः); ब्रह्मणः अभिव्यक्तिः वेदाक्षरात्। अतः सर्वगतं ब्रह्म सदा यज्ञे प्रतिष्ठितम्।",
  "3.16": "एवं प्रवर्तितं चक्रं नानुवर्तयतीह यः ।\nअघायुरिन्द्रियारामो मोघं पार्थ स जीवति ॥\n\nएवं प्रवर्तितं चक्रं यः नानुवर्तयति सः पापायुः इन्द्रियसुखमग्नः; हे पार्थ, तस्य जीवनं मोघम्।\n\nजीवजातस्य जन्म अन्नात्, अन्नं विना जीवनं नास्ति। अन्नं सस्यात्, सस्यस्य मूलं सूर्यशक्तिः वृष्टिश्च। वृष्टिः यज्ञात् — अस्माकं प्रामाणिकजीवनात्, भगवदर्पणबुद्ध्याः। यज्ञनिर्वहणं कर्मात्, अस्मत्क्रियाशीलतायाः। कर्म इति कर्तव्यकर्म प्रामाणिकक्रिया च। एतादृशं कर्म भगवतः प्रवर्तते; भगवान् (ब्रह्म) वेदे (अक्षरे) निवसति; वेदः जीवजातेषु (मनुष्ये) वर्तते। अतः इदं चक्रम् — मनुष्यः अन्नं वृष्टिः यज्ञः भगवान् वेदः मनुष्यः। अत्र वेदः इति मन्त्रपाठमात्रं न, अपितु वैदिकवाङ्मयस्य प्रज्ञा। अस्मिन् चक्रे स्वकर्म त्यक्तुं न शक्यते; कर्म सदा यज्ञत्वेन भगवदर्पणत्वेन च कर्तव्यम्। एतत् चक्रं यः न अनुवर्तयति सः विश्वचक्रस्य गतिं भङ्क्त्वा, समाजस्य सहजगतिं स्तम्भयित्वा, केवलम् इन्द्रियसुखे मग्नः स्वजीवनं वृथा करोति।",
  "3.17": "यस्त्वात्मरतिरेव स्यादात्मतृप्तश्च मानवः ।\nआत्मन्येव च सन्तुष्टस्तस्य कार्यं न विद्यते ॥\n\nयः आत्मरतिः आत्मतृप्तः आत्मनि एव सन्तुष्टः, तस्य कर्तव्यं किमपि न विद्यते।\n\nअन्तरङ्गे भगवद्दर्शनजनितः आनन्दः 'आत्मरतिः'। एषा स्थितिः समाधौ प्राप्यते। सत्ये समाधौ इन्द्रियाणि मनश्च न कार्यं कुर्वन्ति; ज्ञानस्वरूपः जीवः साक्षात् भगवन्तं पश्यति। तादृशस्थितौ कर्मलेपः न भवति; लौकिकप्रपञ्चः तृप्त्या अनपेक्षितः भवति, केवलं भगवत्साक्षात्कारानन्दसागरे निमग्नः तिष्ठति।",
  "3.18": "नैव तस्य कृतेनार्थो नाकृतेनेह कश्चन ।\nन चास्य सर्वभूतेषु कश्चिदर्थव्यपाश्रयः ॥\n\nतस्य कृतेन विशेषलाभः नाकृतेन च हानिः; सर्वभूतेषु तस्य फलापेक्षा नास्ति।\n\nसमाधिस्थितौ क्षुधा तृषा च नास्ति; बाह्यप्रपञ्चस्य अवबोधः एव नास्ति। तादृक्स्थितौ अन्यसाधनेन उद्धारः, कर्तव्याकरणे दोषो वा नास्ति। पञ्चभूतपञ्चकोशाश्रयोऽपि तस्य नापेक्षितः। परिवारममकारोऽपि तत्र नास्ति; बाह्यप्रपञ्चस्य हङ्गः तस्य नास्ति।",
  "3.19": "तस्मादसक्तः सततं कार्यं कर्म समाचर ।\nअसक्तो ह्याचरन्कर्म परमाप्नोति पूरुषः ॥\n\nअतः फलासक्तिं त्यक्त्वा सततं कर्तव्यकर्म कुरु; असक्तः कर्म आचरन् पुरुषः परं प्राप्नोति।\n\n'सर्वं कुरु, किन्तु किमपि नासक्त्या कुरु। फलचिन्तां विना कर्तव्यं कुरु। एवं कृतं कर्म त्वां भगवदभिमुखं नयति, न पुनः कर्मबन्धने क्षिपति। एवमेव भगवत्प्राप्तिः, न कर्मत्यागेन' इति कृष्णः वदति। 'पूरुषः' इति पदेन पुरे (सम्पूर्णशरीरे) वर्तमानः, साधनाशरीरे साधनारतः जीवः उच्यते।",
  "3.20": "कर्मणैव हि संसिद्धिमास्थिता जनकादयः ।\nलोकसङ्ग्रहमेवापि सम्पश्यन्कर्तुमर्हसि ॥\n\nकर्मणैव सिद्धिं प्राप्य जनकादयः लक्ष्यं प्राप्ताः; लोकसंग्रहं दृष्ट्वा त्वमपि कर्तुम् अर्हसि।\n\nपूर्वे बहवः राजर्षयः एतेन मार्गेण मोक्षं प्राप्तवन्तः, न वनं गत्वा। जनकमहाराजः उत्तमोदाहरणम् — सः राज्यवैभवेन सह राज्यं चकार, तथापि तत्कालीनमहाज्ञानिषु अन्यतमः आसीत्। शुकाचार्याः वैराग्यविषये जनकं प्रत्यागच्छन्! एतदेव सत्यसाधकस्य जीवनम्। अतः कृष्णः जनकनाम अत्र उदाहरति — 'जनकादयः राजर्षयः कर्मयोगेनैव ज्ञानं प्राप्य उन्नताः, न कर्मत्यागेन' इति। एवं समाजमार्गदर्शकः त्वं समाजार्थं युद्धं कुरु इति कृष्णः वदति।",
  "3.21": "यद्यदाचरति श्रेष्ठस्तत्तदेवेतरो जनः ।\nस यत्प्रमाणं कुरुते लोकस्तदनुवर्तते ॥\n\nश्रेष्ठः यत् यत् आचरति तत् तत् एव इतरः जनः अनुसरति; सः यत् प्रमाणं करोति लोकः तदेव अनुवर्तते।\n\nसमाजे हिरण्यः (वयसा आचारेण ज्ञानेन च मार्गदर्शकः) यां दिशं गच्छति तां दिशम् इतरेऽपि अनुगच्छन्ति। सामान्यजनाः शास्त्रं न जानन्ति; ते केवलम् आदर्शपुरुषान् अनुसरन्ति। नायकस्य आचरणमेव जनप्रमाणं भवति। संस्थाप्रमुखस्य आचरणं विपथगामि चेत् संस्था अधोगतिं गच्छति। जनाः अजानन्तोऽपि नेतुः दुराचारमेव अनुसरन्ति — इदं सामाजिकं महद्भयम्।",
  "3.22": "न मे पार्थास्ति कर्तव्यं त्रिषु लोकेषु किञ्चन ।\nनानवाप्तमवाप्तव्यं वर्त एव च कर्मणि ॥\n\nहे पार्थ, त्रिषु लोकेषु मम कर्तव्यं किञ्चिदपि नास्ति, न वा अप्राप्तम् अवाप्तव्यम् अस्ति; तथापि कर्मणि वर्ते।",
  "3.23": "यदि ह्यहं न वर्तेय जातु कर्मण्यतन्द्रितः ।\nमम वर्त्मानुवर्तन्ते मनुष्याः पार्थ सर्वशः ॥\n\nहे पार्थ, यदि अहं कदाचित् अप्रमत्तः कर्मणि न वर्तेय, मनुष्याः सर्वथा मम मार्गम् एव अनुवर्तेरन्।",
  "3.24": "उत्सीदेयुरिमे लोका न कुर्यां कर्म चेदहम् ।\nसङ्करस्य च कर्ता स्यामुपहन्यामिमाः प्रजाः ॥\n\nयदि अहं कर्म न कुर्यां इमे लोकाः विनश्येयुः; धर्मसङ्करस्य कर्ता स्यां, इमाः प्रजाः स्वयमेव उपहन्यां।\n\nएतेषु त्रिषु श्लोकेषु कृष्णः स्वयमेव उदाहरणीभूय पूर्वोक्तं विवृणोति। सारथिरूपेण स्थितः कृष्णः वदति — 'मम कर्तव्यम् अकर्तव्यं वा किञ्चिदपि नास्ति, तथापि कर्तव्यकर्मणि स्थितः अस्मि' इति। त्रिषु लोकेषु सृष्टिस्थितिसंहारं नित्यकर्मत्वेन कुर्वन् भगवान् सर्वं स्वभक्तार्थं जीवजातार्थं च करोति, न स्वलाभाय। यदि कृष्णः नित्यकर्मणि न प्रवर्तेत सर्वे तम् एव प्रमाणीकृत्य तन्मार्गम् अनुवर्तेरन्। अतः अवतारकाले भगवान् साधारणमानववत् आचरन् नित्यकर्माणि निर्वहति। कृष्णावतारे सन्ध्यावन्दनादिकं कर्म अतप्तं कृतवान् — इदं स्वार्थाय न, अनुयायिनां मार्गदर्शनाय।",
  "3.25": "सक्ताः कर्मण्यविद्वांसो यथा कुर्वन्ति भारत ।\nकुर्याद्विद्वांस्तथासक्तश्चिकीर्षुर्लोकसङ्ग्रहम् ॥\n\nहे भारत, अविद्वांसः फलासक्त्या यथा कर्म कुर्वन्ति तथैव विद्वान् असक्तः लोकसंग्रहं चिकीर्षुः कर्म कुर्यात्।\n\nअज्ञाः फलेच्छया कर्म कुर्वन्ति; विद्वान् तु फलाधिकारं विना निष्कामकर्म कुर्यात्। 'अहं वर्धमानजनाङ्गाय मार्गदर्शकत्वेन भगवत्सेवां करोमि, यत् किञ्चित् भगवता दत्तं तेन सन्तुष्टः' इति सङ्कल्पेन कर्म कर्तव्यम्। एतदेव सत्यं कर्मयोगः।",
  "3.26": "न बुद्धिभेदं जनयेदज्ञानां कर्मसङ्गिनाम् ।\nजोषयेत्सर्वकर्माणि विद्वान्युक्तः समाचरन् ॥\n\nफलासक्त्या कर्म कुर्वतां अज्ञानां श्रद्धां न भेदयेत्; विद्वान् युक्तः स्वयं सर्वकर्माणि आचरन् तान् प्रोत्साहयेत्।\n\nसमाजे बहुविधाः जनाः सन्ति; न सर्वेषां ज्ञानम् अस्ति। ते स्वश्रद्धानुसारं वर्तन्ते। विदुषः दृष्ट्या तत् अन्धश्रद्धा इव भासेत, तथापि तान् सहसा उपहसितुं न योग्यम्। दृढश्रद्धया शरणागत्या सः रक्षितः भवति। तादृशाः जनाः श्रद्धानिष्ठया जीवने विश्वस्ताः; सर्वगतः सर्वशक्तः भगवान् पाषाणद्वारापि रक्षां कर्तुं शक्नोति। अतः तान् उपहस्य नैव, क्रमेण ज्ञानपरिधौ आनयनप्रयत्नः कार्यः। सामाजिकचिन्तया सर्वं कार्यम्, स्वयं तु निर्लिप्तः सन् अज्ञानिषु ज्ञानं पूरयेत्।",
  "3.27": "प्रकृतेः क्रियमाणानि गुणैः कर्माणि सर्वशः ।\nअहङ्कारविमूढात्मा कर्ताहमिति मन्यते ॥\n\nप्रकृतेः अङ्गभूतैः गुणैः (इन्द्रियादिभिः) सर्वाणि कर्माणि क्रियन्ते; अहङ्कारविमूढात्मा तु 'अहमेव कर्ता' इति मन्यते।\n\n'अहमेव कृतवान्' इति अहङ्कारः यथा मिथ्या तथा कृष्णः अत्र विवृणोति। पिण्डाण्डम् इदं शरीरं प्रकृतेः निर्माणम्; तस्याः गुणाः इन्द्रियाणि — शब्दस्पर्शरसरूपगन्धाः, श्रोत्रत्वक्जिह्वाचक्षुर्घ्राणानि, आकाशवायुजलाग्निपृथिव्यश्च तदनुरूपाः। एवं सति 'मयैव कृतम्' इति वचनम् अर्थशून्यम्। उदाहरणम् — 'चक्षुषा दृष्टवान्' इति, किन्तु चक्षुः कः ददौ? जात्यन्धाय चक्षुः दातुं शक्यते किम्? प्रकृतिः जडा, तस्याः इच्छा नास्ति; 'वयं कुर्मः' इति इच्छापूर्वकं कर्म। अस्माकम् इच्छा अस्ति, किन्तु इच्छास्वातन्त्र्यं नास्ति — तत् केवलं भगवति। तदनुगुणं सर्वकार्यनिर्वहणं भवति; अतः स्वभावनियन्ता जगन्मूलकर्ता भगवानेव। वयं विश्वकर्मचक्रस्य एकः घटकः मात्रम्; अतः 'अहमेव कृतवान्' इति अहङ्कारः निरर्थकः।",
  "3.28": "तत्त्ववित्तु महाबाहो गुणकर्मविभागयोः ।\nगुणा गुणेषु वर्तन्त इति मत्वा न सज्जते ॥\n\nहे महाबाहो, गुणकर्मविभागयोः तत्त्वं विदित्वा 'गुणाः गुणेषु एव वर्तन्ते' इति मत्वा तत्त्ववित् न सज्जते।\n\nइन्द्रियेषु सात्त्विकराजसतामसगुणत्रयेण कर्म प्रवर्तते; एतत् पूर्वासक्तेः प्रभावः स्यात्। स्वयं कृतां क्रियां स्वयमेव तटस्थतया विश्लेषणीया (Self Analysis) — इदं मनःशास्त्रविषयः। त्रैगुण्यप्रभावं ज्ञात्वा स्वस्वामित्वाभावः प्रतीयते। इन्द्रियाणि, तेषु प्रकृतित्रैगुण्यम्, तदुपरि जीवस्वभावः, तदुपरि भगवज्ज्ञानानन्दः — सर्वम् इन्द्रियद्वारा कर्मत्वेन अभिव्यज्यते। जडे केवलं कृतिः (Action), जीवे इच्छापूर्विका कृतिः (Intentional Action), भगवति स्वतन्त्रा इच्छाकृतिः (Independent Intentional Action) — एषः कर्मभेदः। एवं गुणभेदं कर्मभेदं च विदितवान् 'तत्त्ववित्'। एतद्विज्ञाने 'मया कृतम्' इति अहङ्कारः न बाधते। हे महाबाहो इति सम्बोधनं वीरत्वं सूचयति, तथा 'महत् वहतीति महाबाहुः' इति जगन्मूलसत्यधारकत्वमपि सूचयति।",
  "3.29": "प्रकृतेर्गुणसम्मूढाः सज्जन्ते गुणकर्मसु ।\nतानकृत्स्नविदो मन्दान्कृत्स्नविन्न विचालयेत् ॥\n\nप्रकृतेः गुणैः सम्मूढाः गुणकर्मसु सज्जन्ते; अपूर्णविदः तान् मन्दान् पूर्णवित् न विचालयेत्।\n\nप्रकृतिगुणजेन्द्रियसुखे निमग्नाः, त्रिगुणमोहेन सत्यम् अजानन्तः, स्वस्य भगवद्गुणाधीनत्वम् अविदन्तः — एतान् कृष्णः 'प्रकृतेर्गुणसम्मूढान्' वदति। एते भगवद्गुणकर्म स्वकीयत्वेन भ्रमन्तः 'अहमेव सर्वम्' इति जीवन्ति; एतेषां सत्यज्ञानयोग्यता नास्ति। 'कृत्स्नवित्' तान् न विचालयेत्; यदि तेषु योग्यता स्यात् स्वयमेव तस्याः स्थितेः बहिः आगच्छेयुः।",
  "3.30": "मयि सर्वाणि कर्माणि संन्यस्याध्यात्मचेतसा ।\nनिराशीर्निर्ममो भूत्वा युध्यस्व विगतज्वरः ॥\n\nमयि सर्वकर्माणि अर्पयित्वा, अध्यात्मचेतसा मयि मनः निधाय, आशां ममत्वं च त्यक्त्वा, ज्वररहितः युद्धं कुरु।\n\n'त्वया कृतं सर्वं मया एव कारितम्, यत् मत्कर्मद्वारा जातं तत् भगवत्पूजा' इति समर्पणभावः संन्यासः। 'नाहं कर्ता हरिः कर्ता; हरिः कर्ता हि केवलम्' इति भावेन युद्धेऽपि सर्वं भगवदर्पणम् इति चिन्तनं वर्धनीयम् इति कृष्णः वदति। इदं युद्धं समष्ट्या निश्चितम् — पूर्वं राजसूययागे शिशुपालवधे व्यासाः धर्मराजाय एतत् महायुद्धस्य पूर्वसूचनाम् उक्तवन्तः। अत्र अर्जुनः केवलम् उपकरणम् (Instrument) मात्रम्। अतः 'भगवति मनः निधाय ममत्वाशां त्यक्त्वा निश्चिन्ततया युध्यस्व' इति कृष्णः अर्जुनम् उपदिशति।",
  "3.31": "ये मे मतमिदं नित्यमनुतिष्ठन्ति मानवाः ।\nश्रद्धावन्तोऽनसूयन्तो मुच्यन्ते तेऽपि कर्मभिः ॥\n\nये मानवाः श्रद्धया अनसूयया च मम एतत् मतं नित्यम् अनुतिष्ठन्ति ते कर्मभ्यः अपि मुच्यन्ते।",
"3.32": "ये त्वेतदभ्यसूयन्तो नानुतिष्ठन्ति मे मतम् ।\nसर्वज्ञानविमूढांस्तान्विद्धि नष्टानचेतसः ॥\n\nये तु असूयया मम मतं न अनुतिष्ठन्ति तान् सर्वज्ञानविमूढान् नष्टान् अचेतसः विद्धि।\n\n'भगवान् एव मत्करणेन कारयति, यत् करोमि तत् तत्पूजा' इति भावः नित्याभ्यासः स्यात्। एवं जीवन्तः अश्रद्धाम् असूयां च त्यक्त्वा निष्कामकर्म कुर्वन्तः ज्ञानवृद्धिं प्राप्य कर्मबन्धनात् मुच्यन्ते। ये तु असूयया 'अहमेव स्वकार्यस्य उत्तरदायी, स्वार्थाय करोमि' इति अहङ्कारेण जीवन्ति तेषां ज्ञानद्वारं न उद्घाटते; ते विमूढाः अन्धकारात् अन्धकारं गच्छन्तः स्वास्तित्वं नाशयन्ति।",
"3.33": "सदृशं चेष्टते स्वस्याः प्रकृतेर्ज्ञानवानपि ।\nप्रकृतिं यान्ति भूतानि निग्रहः किं करिष्यति ॥\n\nज्ञानवानपि स्वप्रकृतेः अनुरूपम् एव चेष्टते; सर्वाणि भूतानि स्वप्रकृतिम् अनुयान्ति — निग्रहः किं करिष्यति?\n\nबहुशः उपदिष्टेऽपि सर्वे एकमार्गम् अनुसर्तुं न शक्नुवन्ति; कारणम् अस्माकं संस्कारः जीवस्वभावश्च। जन्मजन्मान्तरार्जितसंस्काराः सुप्रज्ञायां तिष्ठन्ति; एकजन्मन्यपि वातावरणप्रभावः सदा वर्तते। मरिचवृक्षः यथा मधुरफलं दातुम् असमर्थः तथा जीवस्वभावपरिवर्तनम् असाध्यम्। तथापि निरन्तरप्रयत्नेन संस्कारप्रभावात् बहिः आगन्तुं शक्यते; निरन्तरम् अध्यात्मसाधनं स्वभावाभिव्यक्तौ साहाय्यं करोति।",
      "3.34": "इन्द्रियस्येन्द्रियस्यार्थे रागद्वेषौ व्यवस्थितौ ।\nतयोर्न वशमागच्छेत्तौ ह्यस्य परिपन्थिनौ ॥\n\nप्रतीन्द्रियार्थे रागद्वेषौ स्थितौ; तयोः वशं न गच्छेत्, तावेव साधकस्य शत्रू।\n\nरागः (Attachment) कामश्च (Desire) — इष्टवस्तुनि रागः, ततः कामः; अनिष्टे द्वेषः, ततः क्रोधः। इष्टवस्तुनः अलाभे क्रोधः, अन्यस्मै लब्धे द्वेषः, लब्धेऽपि अनभीष्टरूपे क्रोधः। मूलदोषः इच्छैव; यत् यत् अधिकम् इच्छामः तत्तत् अधिकं दुःखं जनयति। इच्छानियमनं विना उन्नतिः असम्भवा। प्रतीन्द्रियं रागद्वेषकामक्रोधाः पूर्णाः; तथापि तेषां वशं न गन्तव्यम्। 'ममेदम्' इति अत्यनुरागः (Possessiveness) अधःपतनं नयति; एषः अहङ्कारः (Ego) प्रवृत्तेः मूलम्। 'कदापि एतयोः दासः मा भव, तौ साधनामार्गस्य अवरोधौ, तावेव तव सत्यशत्रू' इति कृष्णः वदति। स्वेन्द्रियाणि विश्लेष्य इच्छाशुद्धिः कर्तव्या — वेदोक्तं यथा 'सारणिघ्ना पिष्टं पृथक्करोति' तथा मनःसारणिघ्ना इच्छाशुद्धिः विधेया।",
  "3.35": "श्रेयान्स्वधर्मो विगुणः परधर्मात्स्वनुष्ठितात् ।\nस्वधर्मे निधनं श्रेयः परधर्मो भयावहः ॥\n\nविगुणोऽपि स्वधर्मः सुष्ठु अनुष्ठितात् परधर्मात् श्रेयान्; स्वधर्मे मरणमपि श्रेयः, परधर्मः भयावहः।\n\nप्रतिजीवस्य स्वकीयः स्वभावः वर्तते, तं परिवर्तयितुं न शक्यते। जीवस्वभावानुगुणं स्वधर्मः; अतः पितरौ स्वाभिरुचिं सन्तानेषु न आरोपयेयुः, अपितु तेषां स्वभावम् अभिज्ञाय भविष्यं रूपयेयुः। अर्जुनस्य स्वधर्मः युद्धम्; तं त्यक्त्वा वनगमनं परधर्मतुल्यं भवति। अतः 'स्वधर्मं पालय, रागद्वेषौ त्यक्त्वा युध्यस्व' इति कृष्णः वदति।",
  "3.36": "अर्जुन उवाच —\nअथ केन प्रयुक्तोऽयं पापं चरति पूरुषः ।\nअनिच्छन्नपि वार्ष्णेय बलादिव नियोजितः ॥\n\nहे वार्ष्णेय, अनिच्छन्नपि पूरुषः बलात् इव नियोजितः पापं करोति — केन प्रयुक्तः?\n\nकृष्णोपदेशश्रवणानन्तरं अर्जुनः सर्वसाधारणं प्रश्नं पृच्छति — पापपुण्यविज्ञानेऽपि मनुष्यः किमर्थं दुष्कर्म करोति?",
  "3.37": "भगवानुवाच —\nकामः एष क्रोध एष रजोगुणसमुद्भवः ।\nमहाशनो महापाप्मा विद्ध्येनमिह वैरिणम् ॥\n\nएषः कामः एव क्रोधः, रजोगुणसमुद्भवः, महाशनः महापाप्मा — एनम् एव अत्र वैरिणं विद्धि।\n\nअस्माकं वैरी कामः; तत एव क्रोधः। इच्छापूर्तिः दुष्कर्मणा साध्या इति प्रेरणा कालनेमिनामकात् दुष्टशक्तेः भवति। इच्छा अपूर्तौ क्रोधः; क्रोधमूलं कामः। रजोगुणः रागद्वेषौ पोषयति, तस्य तृप्तिः कदापि न भवति — यत् यत् लभ्यते तत् अधिकम् इच्छति। एवं 'महाशनः' भूत्वा असाध्यकार्यमपि कारयति; कुराने उक्तम् — \"Drive them out from where they drove you out\" इति। रागद्वेषौ आत्मानं त्यक्त्वा स्वयं वर्तस्व।",
  "3.38": "धूमेनाव्रियते वह्निर्यथादर्शो मलेन च ।\nयथोल्बेनावृतो गर्भस्तथा तेनेदमावृतम् ॥\n\nयथा धूमेन वह्निः, मलेन आदर्शः, उल्बेन गर्भः आवृतः, तथा कामेन इदं ज्ञानम् आवृतम्।\n\nभगवान् वह्निवत्, अस्माकं रजोगुणः धूमवत् — तयोः मध्ये रजोगुणपटलम् अग्निधूमवत्। राजसस्य दृष्टान्तः मषिलिप्तः आदर्शः — मनोरूपम् आदर्शं रजोगुणमषिः आवृणोति। तामसस्य दृष्टान्तः गर्भस्थभ्रूणः — सर्वं तमः, चक्षुषा अपि न पश्यति।",
  "3.39": "आवृतं ज्ञानमेतेन ज्ञानिनो नित्यवैरिणा ।\nकामरूपेण कौन्तेय दुष्पूरेणानलेन च ॥\n\nहे कौन्तेय, ज्ञानिनोऽपि ज्ञानम् एतेन नित्यवैरिणा कामरूपेण दुष्पूरेण अनलेन इव आवृतम्।\n\nएतत् रजोगुणपटलं ज्ञानिनः ज्ञानम् अनुपयुक्तं, अज्ञानिनः ज्ञानोदयम् अवरुद्धं करोति। रागद्वेषौ नित्यवैरी; तौ 'इच्छाग्निः' इव — यावद्दत्तम् अपि न तृप्येताम्। कुन्तीपुत्रस्त्वं कामाख्यं ज्ञानविरोधिशत्रुं जानीहि इति कृष्णः वदति।",
  "3.40": "इन्द्रियाणि मनो बुद्धिरस्याधिष्ठानमुच्यते ।\nएतैर्विमोहयत्येष ज्ञानमावृत्य देहिनम् ॥\n\nइन्द्रियाणि मनः बुद्धिः च अस्य अधिष्ठानानि; एभिः एषः ज्ञानम् आवृत्य देहिनं विमोहयति।\n\nअस्मत्कामाः प्रथमम् इन्द्रियेषु आसते; तत्र अनिगृहीताः मनः आक्रामन्ति, ततः बुद्धिम्। बुद्धिम् आक्रान्तां पश्चात् त्यक्तुं दुष्करम्; तदा कामः सिद्धान्ततया अस्मान् शासति, जीवनधर्म एव भवति। 'देहिनम्' इति पदेन देहः ज्ञानेन उन्नतिसाधनम्, किन्तु कामसङ्गेन अधःपातसाधनं भवति इति भावः।",
  "3.41": "तस्मात्त्वमिन्द्रियाण्यादौ नियम्य भरतर्षभ ।\nपाप्मानं प्रजहि ह्येनं ज्ञानविज्ञाननाशनम् ॥\n\nअतः, हे भरतर्षभ, आदौ इन्द्रियाणि नियम्य ज्ञानविज्ञाननाशनम् एनं पाप्मानं प्रजहि।\n\nएतादृशं महावैरिणं प्रथमप्रवेशद्वारे इन्द्रिये एव नियन्त्रणीयम्। श्रवणमननादिनाशकम् एनं महापापिनं निवारय इति कृष्णः वदति — किन्तु कथम्? इदं पुरतः श्रूयताम्।",
  "3.42": "इन्द्रियाणि पराण्याहुरिन्द्रियेभ्यः परं मनः ।\nमनसस्तु परा बुद्धिर्यो बुद्धेः परतस्तु सः ॥\n\nइन्द्रियाणि (देहात्) परतराणि; इन्द्रियेभ्यः परं मनः; मनसः परा बुद्धिः; बुद्धेः परतः तत् परतत्त्वम्।",
  "3.43": "एवं बुद्धेः परं बुद्ध्वा संस्तभ्यात्मानमात्मना ।\nजहि शत्रुं महाबाहो कामरूपं दुरासदम् ॥\n\nहे महाबाहो, एवं बुद्धेः परं तत्त्वं बुद्ध्वा आत्मानम् आत्मना संस्तभ्य कामरूपं दुरासदं शत्रुं जहि।\n\nयथा दुष्टशक्तयः तथा हितैषिण्यः देवताशक्तयोऽपि सन्ति। प्रतीन्द्रियम् अभिमानी देवः — चक्षुषि सूर्यः, श्रोत्रे चन्द्रः, मनसि रुद्रः, बुद्धौ सरस्वती। बुद्धेः परं आत्मा, सैव भगवतः स्थानम्। एतासां देवताशक्तीनां शरणं गत्वा ज्ञानं प्राप्य भगवन्तं द्रष्टुं शक्यते। एवं मनोऽश्वं बुद्धिरश्मिना नियम्य, तां रश्मिं भगवत्करे समर्प्य, सर्वदेवतासाहाय्येन कालनेमिनामकं राक्षसं क्रमशः जित्वा भगवन्तं प्राप्नुयात् इति कृष्णः वदति। एकेनैव प्रयत्नेन जयः असम्भवः; क्रमशः साधनीयः।\n\nइति तृतीयोऽध्यायः समाप्तः।",
  "4.1": "[चतुर्थाध्यायस्य बन्नञ्जे-पीठिका]\n\nपूर्वं द्वितीये अध्याये ज्ञानमार्गं कर्ममार्गं च प्रस्तुत्य, तृतीये अध्याये कर्मयोगस्य विस्तारं कृष्णः अवदत्। अस्मिन् चतुर्थे अध्याये भगवतः ज्ञानस्वरूपं कर्मप्रभेदान् च कृष्णः विवृणोति। पूर्वोक्तं ज्ञानयोगं कर्मयोगं च विस्तार्य, ज्ञानस्य महत्त्वं कर्मणः प्रभेदान् च, एताभ्यां मार्गाभ्यां प्राप्तव्यां भगवतः महिमानं च अत्र वर्णितम्। अयम् अध्यायः कृष्णस्य वचनेन आरभ्यते।\n\nभगवानुवाच —\nइमं विवस्वते योगं प्रोक्तवानहमव्ययम् ।\nविवस्वान्मनवे प्राह मनुरिक्ष्वाकवेऽब्रवीत् ॥\n\nइमं अव्ययं योगं विवस्वते अहं प्रोक्तवान्; विवस्वान् मनवे प्राह; मनुः इक्ष्वाकवे अब्रवीत्।",
  "4.2": "एवं परम्परा प्राप्तमिमं राजर्षयो विदुः ।\n\nस कालेनेह महता योगो नष्टः परन्तप — एवं परम्परया प्राप्तं इमं राजर्षयः विदुः; हे परन्तप, दीर्घकालेन एषः योगः इह नष्टः।",
  "4.3": "स एवायं मया तेऽद्य योगः प्रोक्तः पुरातनः ।\nभक्तोऽसि मे सखा चेति रहस्यं ह्येतदुत्तमम् ॥\n\nतमेव पुरातनं योगं तुभ्यम् अद्य मया उक्तम्, यतः त्वं मे भक्तः सखा च। इदम् उत्तमं रहस्यम्।\n\nएतेषु त्रिषु श्लोकेषु सृष्ट्यादितः ज्ञानपरम्परा कथं प्रवृत्ता इति कृष्णः चित्रितवान्। वस्तुतः ज्ञानस्य मूलं वेदाः; वेदसारसंग्रहरूपः ग्रन्थः पञ्चरात्रम् इति उच्यते — जीव जान्ज्ञानयोगकर्मयोगयोः समष्टिरूपः। भगवद्गीता तस्यैव सारसंग्रहः। सृष्ट्यादौ स्वायम्भुवमन्वन्तरे भगवान् पञ्चरात्रं चतुर्मुखाय उपदिष्टवान्; वैवस्वतमन्वन्तरे सूर्यः मनवे, मनुः इक्ष्वाकवे उक्तवान्। एतदेव कृष्णः अत्र अर्जुनाय विवृणोति।\n\nज्ञानम् अनादिनित्यम्, अक्षयविद्या। प्रतिसृष्ट्यादौ इयं विद्या भगवता उच्यते; ततः देवेभ्यः, देवेभ्यः राजर्षिभ्यः, ततः ऋषिभ्यः — एवं ज्ञानपरम्परा वर्धते। अद्य इयं विद्या विस्मृता भवति; महाज्ञानी अर्जुनोऽपि विस्मृतवान्। अत्र कृष्णः अर्जुनं 'परन्तप' इति सम्बोधयति — यः सदा ज्ञानदृष्ट्या भगवन्तं पश्यति सः। 'त्वम् अपरोक्षज्ञानी, त्वयि एव इयं परम्परा वर्तते, तथापि संशयः जातः' इति ध्वनिः।\n\nज्ञानं न नष्टम्, किन्तु मोहपटलेन आवृतम्। अतः पुनः तत् वदामि इति कृष्णः। अर्जुनस्य कृष्णे गौरवं भक्तिं सख्यं च ज्ञात्वा कृष्णः इदं दुर्लभं ज्ञानं स्मारयति। अर्जुनस्य भक्तिः नवविधभक्तिषु (श्रवण-कीर्तन-स्मरण-पादसेवन-अर्चन-वन्दन-दास्य-सख्य-आत्मनिवेदनेषु) सख्यम्। अतः 'त्वं मे भक्तः सखा' इति कृष्णोक्तिः।\n\n'रहस्यं ज्ञानं वदामि' इति कृष्णोक्तेः द्वे कारणे — दुरुपयोगः निरुपयोगश्च। अपात्रेभ्यः ज्ञानदानं व्यर्थम्; तेन परम्परा न प्रवहति। दुरुपयोगश्च — ज्ञानं स्वोद्धाराय परोद्धारमार्गदर्शनाय च, न वाणिज्यार्थम्। ज्ञानेन समाजवञ्चनमपि सम्भवति। अतः ज्ञानं रहस्यविषयः। योगसिद्ध्या तिरोहिता विद्या ज्ञानिभ्यः ज्ञाता आसीत्; तस्याः दुरुपयोगः सुलभः, अतः रहस्यत्वम्।",
  "4.4": "अर्जुन उवाच —\nअपरं भवतो जन्म परं जन्म विवस्वतः ।\nकथमेतद्विजानीयां त्वमादौ प्रोक्तवानिति ॥\n\nतव जन्म अर्वाचीनम्, सूर्यस्य जन्म पूर्वतरम्; त्वं आदौ प्रोक्तवान् इति कथं विजानीयाम्?\n\nज्ञानपरम्परां विवृण्वति कृष्णे अर्जुनः पृच्छति। वयसा कृष्णः अर्जुनात् षण्मासमात्रं ज्येष्ठः; कोटिवर्षपूर्वं सूर्याय उक्तवान् इति कथं ग्राह्यम्? इयं अर्जुनस्य जिज्ञासा — स्वयं सर्वज्ञानिनः प्रतिनिधिः भूत्वा अस्माकं सर्वेषां पक्षे एतत् पृच्छति।",
  "4.5": "भगवानुवाच —\nबहूनि मे व्यतीतानि जन्मानि तव चार्जुन ।\nतान्यहं वेद सर्वाणि न त्वं वेत्थ परन्तप ॥\n\nहे अर्जुन, मम तव च बहूनि जन्मानि व्यतीतानि; तानि अहं वेद, हे परन्तप, त्वं तु न वेत्थ।\n\nजन्म इति जननम्; असत् न जायते। सूक्ष्मशरीरस्य स्थूलशरीरे आविर्भावः जन्म; सूक्ष्मशरीरस्य स्थूलशरीरत्यागः मृत्युः। 'आवयोः बहूनि जन्मानि जातानि, अहं तानि वेद्मि, त्वं तु न वेत्थ' इति कृष्णोक्तिः।",
  "4.6": "अजोऽपि सन्नव्ययात्मा भूतानामीश्वरोऽपि सन् ।\nप्रकृतिं स्वामधिष्ठाय सम्भवाम्यात्ममायया ॥\n\nमम जन्म नास्ति, अव्ययः अहम्, सर्वेश्वरोऽपि सन्, स्वप्रकृतिम् अधिष्ठाय आत्मेच्छया एव सम्भवामि।\n\nसर्वजीवेश्वरः भगवान् बहुशः अवतरति; तस्य जन्म नास्ति, तथापि जायते इव। 'आत्ममायया' इत्यस्य बहवः अर्थाः — जीवावृतमोहपटलम्, भगवन्महिमा, स्वेच्छाज्ञानं च। भगवतः अवतारः स्वज्ञानमहिम्ना, न कस्याश्चित् मायायाः वशेन। भक्तानुग्रहाय स्वयंनिर्मितां प्रकृतिं माध्यमीकृत्य इच्छापूर्वकम् अवतरति — इयं तस्य महिमा। मोहावृताः वयं तत् सामान्यजन्म इव पश्यामः, यतः तस्य ज्ञानानन्दमयं शरीरं द्रष्टुं न शक्नुमः।",
  "4.7": "यदा यदा हि धर्मस्य ग्लानिर्भवति भारत ।\nअभ्युत्थानमधर्मस्य तदात्मानं सृजाम्यहम् ॥\n\nहे भारत, यदा यदा धर्मस्य ग्लानिः अधर्मस्य च अभ्युत्थानं भवति तदा अहम् आत्मानं सृजामि।\n\nयदा सम्पूर्णविश्वे धर्मः मलिनः भूत्वा अधर्मात् पराभूयते तदा भगवतः अवतारः भवति। दुष्टशक्तयः भूमौ प्राबल्यं प्राप्य सत्त्वगुणस्य उत्थानं निरुध्य यदा तिष्ठन्ति तदा भगवान् स्वयं सृज्यते। प्रादेशिकधर्महान्यां भगवान् स्वात्मीयान् (देवान्) भूमौ प्रेषयति; व्यवस्थायाः अपि विनाशे तामसशक्तिविजृम्भणे च अन्ततः भगवान् स्वयम् अवतरति। कृष्णावतारकाले जरासन्धादीनां अधर्मप्राबल्यं दृष्ट्वा एतत् स्पष्टं भवति।",
  "4.8": "परित्राणाय साधूनां विनाशाय च दुष्कृताम् ।\nधर्मसंस्थापनार्थाय सम्भवामि युगे युगे ॥\n\nसाधुपरित्राणाय दुष्कृतविनाशाय धर्मसंस्थापनार्थाय च युगे युगे सम्भवामि।\n\nसमाजस्य कण्टकभूतान् दुष्कृतः पूर्णं विनाश्य साधूनां जगतश्च रक्षार्थं धर्मबीजं वप्तुं भगवान् अवतरति। 'युगे युगे' इत्यस्य अर्थः प्रत्येकयुगे अवतारः इति न, अपितु उपर्युक्तसंदर्भे एव। एकस्मिन् युगे बहवः अवताराः, अन्यस्मिन् नैव — किन्तु भगवदाविर्भूताः महापुरुषाः युगे युगे आगच्छन्ति, तन्मुखेन धर्मरक्षणं निरन्तरम्।",
  "4.9": "जन्म कर्म च मे दिव्यमेवं यो वेत्ति तत्त्वतः ।\nत्यक्त्वा देहं पुनर्जन्म नैति मामेति सोऽर्जुन ॥\n\nएवं मम दिव्यं जन्म कर्म च यः तत्त्वतः वेत्ति सः देहत्यागानन्तरं पुनर्जन्म न प्राप्य माम् एव प्राप्नोति, हे अर्जुन।\n\nएवं भगवतः ज्ञानानन्दमयं दिव्यं लीलामयम् अवतारं यथावत् (तत्त्वतः) ज्ञातं चेत् तत् मोक्षमार्गं दर्शयति। इदं अपुनर्जन्ममोक्षाय अमूल्यं ज्ञानम्।",
  "4.10": "वीतरागभयक्रोधा मन्मया मामुपाश्रिताः ।\nबहवो ज्ञानतपसा पूता मद्भावमागताः ॥\n\nरागभयक्रोधरहिताः मन्मयाः मामेव उपाश्रिताः बहवः ज्ञानतपसा पूताः मद्भावम् आगताः।\n\nतृतीयाध्यायान्ते (श्लोक ३९) उक्तवत् रागद्वेषादयः परमशत्रवः। अस्मत्जीवनसमस्यामूलभूतं रागं(आसक्तिं) भयं क्रोधं च त्यक्त्वा यत् प्राप्तं तेन सन्तुष्टिः वर्धनीया, मन्मयत्वं च — जीवनस्य सर्वनडेषु भगवन्तं पूरयित्वा लौकिकप्रज्ञां न्यूनीकृत्य। एवं रागद्वेषकोषान्मुक्ताः मां प्राप्नुवन्ति इति कृष्णोक्तिः।",
  "4.11": "ये यथा मां प्रपद्यन्ते तांस्तथैव भजाम्यहम् ।\nमम वर्त्मानुवर्तन्ते मनुष्याः पार्थ सर्वशः ॥\n\nये यथा मां प्रपद्यन्ते तान् तथैव भजामि; हे पार्थ, मनुष्याः येन केन मार्गेण गच्छन्तु, अन्ततः मामेव प्राप्नुवन्ति।\n\nदेवोपासनायाः सम्यङ्मार्गः कः? एकैकः एकैकधा उपासते, ततः भ्रान्तिः। यथा यः उपासते तथैव भगवान् अनुगृह्णाति। यद्रूपेण उपास्यते तत् विश्वरूपं भगवन्तमेव प्राप्नोति। अतः तुलसी-अश्वत्थ-गोमातृ-आदिरूपेषु भगवद्विभूतिं ज्ञात्वा पूजा कार्या, न तान् एव भगवन्तं मत्वा।",
  "4.12": "काङ्क्षन्तः कर्मणां सिद्धिं यजन्त इह देवताः ।\nक्षिप्रं हि मानुषे लोके सिद्धिर्भवति कर्मजा ॥\n\nकर्मसिद्धिं काङ्क्षन्तः इह देवताः यजन्ते; मानुषलोके कर्मजा सिद्धिः क्षिप्रम् एव भवति।\n\nदेवभगवद्भेदम् अजानन्तः देवानेव भगवत्त्वेन पूजयन्ति — इयं भ्रान्तिः। ईश्वरः एकः, देवाः तु तदधीनाः बहवः। क्षिप्रफलेच्छया भगवन्तं विस्मृत्य देवसमूहपूजा प्रचलिता; तेन अल्पकालिकं फलं लभ्यते, न शाश्वतमोक्षः। सर्वान्तर्यामिनं भगवन्तं यत् रूपेण अपि पूजयन्तु, ऐहिकभोगेच्छया न, अपितु तत्प्राप्त्यनुसन्धानेन पूजा कार्या।",
  "4.13": "चातुर्वर्ण्यं मया सृष्टं गुणकर्मविभागशः ।\nतस्य कर्तारमपि मां विद्ध्यकर्तारमव्ययम् ॥\n\nगुणकर्मविभागशः चातुर्वर्ण्यं मया सृष्टम्; तस्य कर्तारम् अपि माम् अव्ययम् अकर्तारं विद्धि।\n\n'चातुर्वर्ण्यं मया सृष्टम्' इति कृष्णोक्तिः जातिविषये न, वर्णविषये। जातिः जन्मतः, वर्णः जीवस्वभावतः त्रैगुण्यानुसारेण। ब्राह्मणक्षत्रियवैश्यशूद्राः इति वर्णाः गुणकर्मानुगुणं विभक्ताः। पुरुषसूक्ते एतत् दैहिकाङ्गैः वर्णितम् — 'ब्राह्मणोऽस्य मुखमासीत्, बाहू राजन्यः कृतः, ऊरू तदस्य यद्वैश्यः, पद्भ्यां शूद्रोऽजायत' इति। जीवस्वभावः अनादिनित्यः; तदनुगुणं भगवान् देहशक्तिप्रपञ्चं निर्माय जीवाय अस्तित्वं ददाति। एवं भगवान् सर्वकर्ता, तस्य तु अन्यः कर्ता नास्ति — 'अहम् अपरिवर्तनीयः निर्माता, मां तु कोऽपि न निर्मितवान्' इति कृष्णोक्तिः।",
  "4.14": "न मां कर्माणि लिम्पन्ति न मे कर्मफले स्पृहा ।\nइति मां योऽभिजानाति कर्मभिर्न स बध्यते ॥\n\nमां कर्माणि न लिम्पन्ति, कर्मफले स्पृहा च नास्ति; एवं यः मां जानाति सः कर्मभिर्न बध्यते।\n\nस्वस्वभावानुरूपं गुणकर्मविभागशः विश्वोद्यानं निर्माय चतुर्वर्णान् मोक्षयोग्यान् मानवान् भगवान् असृजत्। 'ममेदम्', 'मया कृतम्' इति अभिमाने सति एव कर्म लिम्पति; भगवति तादृक् अभिमानः नास्ति। एतत् सत्यं विदन् स्वजीवने आचरन् कर्मबन्धने न पतति।",
  "4.15": "एवं ज्ञात्वा कृतं कर्म पूर्वैरपि मुमुक्षुभिः ।\nकुरु कर्मैव तस्मात्त्वं पूर्वैः पूर्वतरं कृतम् ॥\n\nपूर्वैः मुमुक्षुभिः अपि एवं ज्ञात्वा कर्म कृतम्; अतः त्वमपि पूर्वैः पूर्वतरं कृतं कर्मैव कुरु।\n\n'निष्क्रियता' कर्मबन्धनान्मुक्तेः सुलभोपायः इति के अपि मन्येरन्; कृष्णः तत् उग्रं निराकरोति। स्वजीवस्वभावानुगुणं ज्ञानपूर्वकं फलाभिमानरहितं कर्म कर्तव्यम्। 'तव पूर्वे राजर्षयः ऋषिमुनयश्च एतदेव अकुर्वन्; कर्मयोगज्ञानयोगोभयं विना भगवत्संयोगो नास्ति' इति कृष्णोक्तिः।",
  "4.16": "किं कर्म किमकर्मेति कवयोऽप्यत्र मोहिताः ।\nतत्ते कर्म प्रवक्ष्यामि यज्ज्ञात्वा मोक्ष्यसेऽशुभात् ॥\n\nकिं कर्म किम् अकर्म इति विद्वांसोऽपि अत्र मोहिताः; तत् कर्म तुभ्यं प्रवक्ष्यामि, यत् ज्ञात्वा अशुभात् मोक्ष्यसे।",
  "4.17": "कर्मणो ह्यपि बोद्धव्यं बोद्धव्यं च विकर्मणः ।\nअकर्मणश्च बोद्धव्यं गहना कर्मणो गतिः ॥\n\nकर्मणः बोद्धव्यम्, विकर्मणः अपि बोद्धव्यम्, अकर्मणः अपि बोद्धव्यम्; कर्मणः गतिः गहना।\n\nकिं कर्म किम् अकर्म इति ज्ञानिभ्योऽपि दुर्बोधम्। इतिहासे वेदव्यासादीनां दृष्टान्तेषु धर्माधर्मयोः निर्णयः दुष्करः प्रतीयते। अस्मत्कर्मणां अकर्मणां विकर्मणां च पृष्ठे अनन्ता भगवच्छक्तिः कार्यरता इति एतत् ज्ञानं विना कर्ममर्म न बुध्यते।",
  "4.18": "कर्मण्यकर्म यः पश्येदकर्मणि च कर्म यः ।\nस बुद्धिमान्मनुष्येषु स युक्तः कृत्स्नकर्मकृत् ॥\n\nयः कर्मणि अकर्म पश्येत्, अकर्मणि च कर्म पश्येत्, सः मनुष्येषु बुद्धिमान्, सः युक्तः, सः कृत्स्नकर्मकृत् च।\n\nकर्मस्वरूपविषये अतीव रोचकं रहस्यं कृष्णः अत्र वदति। 'यत्र कर्म तत्र अकर्म; यत्र अकर्म तत्र कर्म' इत्येतत् गूढार्थं ग्रहीतुं अध्यात्मानुभवः आवश्यकः। अस्मासु वर्तमानं कर्म भगवदधीनम्; सृष्टिचक्रे वयं किमपि अकुर्वन्तोऽपि क्रिया निरन्तरं प्रवर्तते। दृष्टान्तः — गजशिरसि पिपीलिका यद्यपि विपरीतदिशं गच्छति, तथापि गजः यत्र गच्छति तत्रैव सा उपनीयते। एवम् अस्माकं गतेः पृष्ठे महती चालनशक्तिः वर्तते — भगवान् एव। 'त्वत्कर्मणि अकर्म पश्य' इति कृष्णोक्तिः। 'युक्तः' इति सत्यम् अभिमुखीकृतमनाः। एवं सम्यग्ज्ञानवान् सर्वकर्मफलं पूर्णं प्राप्नोति, अहङ्काररहितः च भवति।",
  "4.19": "यस्य सर्वे समारम्भाः कामसङ्कल्पवर्जिताः ।\nज्ञानाग्निदग्धकर्माणं तमाहुः पण्डितं बुधाः ॥\n\nयस्य सर्वसमारम्भाः कामसङ्कल्पवर्जिताः, ज्ञानाग्निना दग्धकर्मा च, तं बुधाः पण्डितम् आहुः।\n\nअस्मत्प्रवृत्तेः पृष्ठे सदा काचित् कामना सङ्कल्पश्च वर्तते। यस्य प्रवृत्तौ कामनास्पर्शः नास्ति सः पण्डितः। पण्डितत्वं वचने न, आचरणे दृश्यम्। यत् प्राप्तं तस्मिन् सन्तोषं शिक्षस्व, अप्राप्तेः चिन्तां त्यज। एवं ज्ञानाग्निना शुद्धं कर्म एव पाण्डित्यस्य लक्षणम्।",
  "4.20": "त्यक्त्वा कर्मफलासङ्गं नित्यतृप्तो निराश्रयः ।\nकर्मण्यभिप्रवृत्तोऽपि नैव किञ्चित्करोति सः ॥\n\nकर्मफलासङ्गं त्यक्त्वा नित्यतृप्तः निराश्रयः कर्मणि अभिप्रवृत्तोऽपि सः किञ्चित् न करोति एव।\n\nकेचित् किमपि न इच्छन्ति, तथापि प्राप्ते सन्तुष्यन्ति। फलातिस्नेहः न शोभनः। भगवत्प्रेरितं यत् प्राप्तं तस्य सद्विनियोगश्चिन्तनीयः, न गर्वः। जीवः भगवत्प्रतिबिम्बः, तस्य स्वातन्त्र्यं नास्ति। भगवान् नित्यतृप्तः; तथैव वयमपि अतृप्तिरहिताः जीवितुं शिक्ष्याम। निराश्रयः भूत्वा भगवदाश्रयसत्यं ज्ञात्वा जीवन् मानवः कर्मणि प्रवृत्तोऽपि किमपि न करोति, यतः भगवान् सर्वोपरि इति मर्म सः जानाति।",
  "4.21": "निराशीर्यतचित्तात्मा त्यक्तसर्वपरिग्रहः ।\nशारीरं केवलं कर्म कुर्वन्नाप्नोति किल्बिषम् ॥\n\nनिराशीः यतचित्तात्मा त्यक्तसर्वपरिग्रहः शरीरधारणमात्रं कर्म कुर्वन्नपि किल्बिषं नाप्नोति।\n\nप्रथमं चित्तं मनश्च नियन्त्रणीयम्; ततः निराशित्वम्। परिग्रहत्यागः न गृहत्यागः, अपितु सर्वस्मिन् सत्यपि तदासक्तित्यागः (detached attachment)। पद्मपत्रं यथा जले स्थित्वापि जलम् न सङ्गच्छते तथा जीवेत्। एवं ज्ञानपूर्वककृतं कर्म कर्मलेपं न स्पृशति।",
  "4.22": "यदृच्छालाभसन्तुष्टो द्वन्द्वातीतो विमत्सरः ।\nसमः सिद्धावसिद्धौ च कृत्वापि न निबध्यते ॥\n\nयदृच्छालाभसन्तुष्टः द्वन्द्वातीतः विमत्सरः सिद्धौ असिद्धौ च समः कर्म कृत्वापि न निबध्यते।\n\nयत् प्राप्तं तस्मिन् एव सन्तुष्टिः, अपेक्षा न — सर्वं भगवदिच्छया प्राप्यते इति ज्ञानम्। द्वन्द्वातीतत्वं — लाभालाभसुखदुःखयोः समचित्तता। अन्यस्य उन्नतिं दृष्ट्वा मत्सरः न कर्तव्यः, यतः प्रत्येकस्य यथायोग्यं फलं भगवदनुग्रहेण एव लभ्यते। सिद्ध्यसिद्ध्योः समत्वं जीवने अतिमहत्त्वपूर्णम्।",
  "4.23": "गतसङ्गस्य मुक्तस्य ज्ञानावस्थितचेतसः ।\nयज्ञायाचरतः कर्म समग्रं प्रविलीयते ॥\n\nगतसङ्गस्य देहाभिमानमुक्तस्य ज्ञानस्थितचित्तस्य यज्ञार्थं कर्म आचरतः सर्वं कर्म प्रविलीयते।\n\nअत्र कृष्णः पूर्वोक्तं सर्वं उपसंहरति — फलासक्तिरहितः देहाभिमानरहितः ज्ञानस्वरूपे भगवति स्थितचेताः यत् कर्म करोति तत् यज्ञत्वेन भगवन्तं प्राप्नोति, ज्ञानाग्निना च कर्मकालुष्यं दह्यते।",
  "4.24": "ब्रह्मार्पणं ब्रह्म हविर्ब्रह्माग्नौ ब्रह्मणा हुतम् ।\nब्रह्मैव तेन गन्तव्यं ब्रह्मकर्मसमाधिना ॥\n\nअर्पणम् अपि ब्रह्म, हविरपि ब्रह्म, ब्रह्माधीने अग्नौ ब्रह्मणा हुतम्; ब्रह्मकर्मसमाधिना तेन ब्रह्मैव गन्तव्यम्।\n\nअभिमानत्यागेन ज्ञानस्थित्या कृतं कर्म कीदृशम् इत्यत्र उत्तरम् — दाता अपि भगवान्, ग्रहीतरि स्थित्वा स्वीकर्ता अपि सः एव। हविः दानवस्तु, अर्पणं दानक्रिया; सर्वं भगवदधीनम्। अग्निः जडमात्रं न, चेतनः अग्न्यभिमानी देवः, तस्मिन् तारकशक्त्या भगवान् अन्तर्हितः। एवं दानं दातव्यं दानक्रिया दानस्थानं च सर्वं भगवदधीनम्। ब्रह्मार्पणम् इत्यर्थः सर्वक्रिया भगवदर्थम्। यज्ञः केवलम् अग्निमुखक्रिया न, अपितु जीवनं भगवन्मयीकृतं सर्वनडः यज्ञ एव।\n\nसामान्यतः यज्ञद्वैविध्यम् — अन्तरङ्गबाह्यौ। अन्तरङ्गे भगवन्नित्यपूजा चित्तसङ्गतीकरणम् आत्मार्पणं च — इदं पूर्णं मानसयज्ञम्। अन्यथा ज्ञानप्रदयज्ञः कर्मप्रदयज्ञश्च।",
  "4.25": "दैवमेवापरे यज्ञं योगिनः पर्युपासते ।\nब्रह्माग्नावपरे यज्ञं यज्ञेनैवोपजुह्वति ॥\n\nकेचित् योगिनः दैवमेव यज्ञत्वेन उपासते; अपरे ब्रह्माग्नौ यज्ञेन एव यज्ञं जुह्वति।\n\nकेचित् अन्तरङ्गं भगवदुपासनामेव यज्ञत्वेन कुर्वन्ति — बाह्यसाधनरहितं ध्यानयज्ञम्, इदं श्रेष्ठतमम्। अपरे अग्निमुखे कर्मप्रधानं बाह्ययज्ञं कुर्वन्ति। अग्निः शुद्धिप्रतीकः, तस्मिन् अन्तर्हितः प्राणः, तस्मिन् भगवान् — एतद् अनुसन्धानेन ज्ञानभक्तिवैराग्ययुक्तया आराधना।",
  "4.26": "श्रोत्रादीनीन्द्रियाण्यन्ये संयमाग्निषु जुह्वति ।\nशब्दादीन्विषयानन्य इन्द्रियाग्निषु जुह्वति ॥\n\nअन्ये श्रोत्रादीनि इन्द्रियाणि संयमाग्निषु जुह्वति; अन्ये शब्दादीन् विषयान् इन्द्रियाग्निषु जुह्वति।\n\nइन्द्रियहविः 'निग्रह' नामाग्नौ आहुतिः एका यज्ञविधिः — दुष्टश्रवणदर्शनवचनवर्जनेन इन्द्रियचापल्यहोमः। श्रेयस्करविषयाणां इन्द्रियेषु ग्रहणमपि यज्ञः — श्रोत्राग्निकुण्डे भगवद्गुणगानहविः, चक्षुःकुण्डे भगवत्प्रतीकहविः इत्यादि। इन्द्रियनिग्रहवत् इन्द्रियग्रहणमपि साधनामार्गे प्रमुखं पदम्।",
  "4.27": "सर्वाणीन्द्रियकर्माणि प्राणकर्माणि चापरे ।\nआत्मसंयमयोगाग्नौ जुह्वति ज्ञानदीपिते ॥\n\nअपरे सर्वाणि इन्द्रियकर्माणि प्राणकर्माणि च ज्ञानदीपिते आत्मसंयमयोगाग्नौ जुह्वति।\n\nदेहे ज्ञानेन्द्रियकर्मेन्द्रियक्रियाभिः सह प्राणशक्तिजनिताः बहवः क्रियाः (श्वासादिकाः) भवन्ति। एतासां मनोनिग्रहाग्नौ होमः (नियन्त्रणम्) यज्ञः, न हठार्थम्, अपितु भगवत्पूजारूपेण भगवज्ज्ञानप्रवर्तितः संयमः इति।",
  "4.28": "द्रव्ययज्ञास्तपोयज्ञा योगयज्ञास्तथापरे ।\nस्वाध्यायज्ञानयज्ञाश्च यतयः संशितव्रताः ॥\n\nअपरे द्रव्ययज्ञाः, तपोयज्ञाः, योगयज्ञाः, स्वाध्यायज्ञानयज्ञाश्च यतयः संशितव्रताः।\n\nद्रव्ययज्ञः — द्रव्यदानेन (धनान्नकन्यादानादिना) योग्यकालयोग्यपात्राय दानम्। तपोयज्ञः — बाह्यम् अन्तरङ्गं च, ब्रह्मचर्यव्रतानुष्ठानादि। योगयज्ञः — बाह्यकर्मभिः भगवदाराधना (प्रदक्षिणार्चनादि), यमनियमपालनं च। स्वाध्यायज्ञानयज्ञः भगवत्प्रियतमः — स्वशाखावेदाध्ययनं, सर्वग्रन्थेषु भगवद्गुणान्वेषणं च। ज्ञातस्य अन्येभ्यः प्रदानेन वर्धमानः एकः सम्पत् ज्ञानमेव। यतित्वं (निरन्तरप्रयत्नशीलत्वम्) संशितव्रतत्वं (शुद्धप्रामाणिकजीवनम्) च आवश्यके।",
  "4.29": "अपाने जुह्वति प्राणं प्राणेऽपानं तथापरे ।\nप्राणापानगती रुद्ध्वा प्राणायामपरायणाः ॥\n\nअपरे प्राणायामपरायणाः प्राणापानगती रुद्ध्वा अपाने प्राणं प्राणे च अपानं जुह्वति।\n\nप्राणायामः योगे विशिष्टं साधनम्। प्राणापानौ यज्ञरूपेण भगवति अर्पयित्वा प्राणायामेन उपासना। रेचकपूरककुम्भकाः तत्राङ्गानि। एतेन एकाग्रता आरोग्यम् आयुश्च वर्धते; प्राणशक्तिवर्धनेन परचिकित्सापि (स्पर्शचिकित्सा) सम्भवति। मुख्यतया एतेन मनः भगवति स्थिरीभवति; कृष्णः एतत् यज्ञम् आह। [सूचना: गुरूपदेशं विना प्राणायामः न प्रयोक्तव्यः।]",
  "4.30": "अपरे नियताहाराः प्राणान्प्राणेषु जुह्वति ।\nसर्वेऽप्येते यज्ञविदो यज्ञक्षपितकल्मषाः ॥\n\nअपरे नियताहाराः प्राणान् प्राणेषु जुह्वति; सर्वे एते यज्ञविदः यज्ञेन क्षपितकल्मषाः च।\n\nआहारनियमनेन इन्द्रियचापल्यं न्यूनीक्रियते — इदमपि यज्ञः; अत एव पर्वदिनेषु एकादश्यां च उपवासप्रथा प्रचलिता। 'प्राणान् प्राणेषु जुह्वति' इत्यर्थः इन्द्रियाभिमानिदेवतातारतम्यचिन्तनम्, तन्मुखेन भगवच्चिन्तनं च — इदं तारतम्यज्ञानयज्ञः। सर्वेषु यज्ञेषु न उत्तमाधमभावः; यस्मै यत् रोचते तेन मार्गेण साधनां कुर्यात्।",
  "4.31": "यज्ञशिष्टामृतभुजो यान्ति ब्रह्म सनातनम् ।\nनायं लोकोऽस्त्ययज्ञस्य कुतोऽन्यः कुरुसत्तम ॥\n\nयज्ञशिष्टामृतभोक्तारः सनातनं ब्रह्म यान्ति; हे कुरुसत्तम, अयज्ञस्य अयं लोकोऽपि नास्ति, कुतः अन्यः।\n\nयज्ञे भगवदर्पणादवशिष्टं 'अमृतम्' उच्यते, तत् मृत्योः पारं नयति। एवं जीवन् क्रमेण सनातनं भगवन्तं प्राप्नोति। 'सनातन' इत्यत्र 'नातन-नादन' इति शब्दध्वनिः — सर्वशब्दवाच्यो वेदवेद्यो भगवान्। शास्त्रज्ञानपूर्वकयज्ञेनैव मोक्षः, अन्यथा निरुपयोगम्। यज्ञे प्रधानतया ज्ञानम् अनन्यभक्तिः शरणागतिश्च अपेक्ष्यते।",
  "4.32": "एवं बहुविधा यज्ञा वितता ब्रह्मणो मुखे ।\nकर्मजान्विद्धि तान्सर्वानेवं ज्ञात्वा विमोक्ष्यसे ॥\n\nएवं बहुविधाः यज्ञाः ब्रह्मणः मुखे वितताः; तान् सर्वान् कर्मजान् विद्धि; एवं ज्ञात्वा विमोक्ष्यसे।\n\nयज्ञस्य बहुमुखत्वम् — भगवत्प्रज्ञया कृतः कोऽपि नड्ः यज्ञो भवति। सर्वयज्ञानां नियामकः भगवानेकः, वैविध्यं तु अस्मदनुसन्धाने क्रियायां च।",
  "4.33": "श्रेयान्द्रव्यमयाद्यज्ञाज्ज्ञानयज्ञः परन्तप ।\nसर्वं कर्माखिलं पार्थ ज्ञाने परिसमाप्यते ॥\n\nहे परन्तप, द्रव्यमयाद्यज्ञात् ज्ञानयज्ञः श्रेयान्; हे पार्थ, सर्वं कर्म अखिलं ज्ञाने परिसमाप्यते।\n\nवस्तुतः केवलं बाह्यं वा केवलम् अन्तरङ्गं यज्ञं न पूर्णम्; बाह्ययज्ञपृष्ठे ज्ञानम्, अन्तरङ्गयज्ञे च आचरणम् अपेक्षितम्। तयोः अन्तरङ्गयज्ञः प्राधान्येन गृह्यते, यतः मानसध्यानेन बाह्यक्रियां विना विशेषशक्तिः निर्मीयते; अज्ञानपूर्वकं कर्म तु व्यर्थम्। अतः ज्ञानपूर्वकं कर्म कर्तव्यम्। 'सर्वं कर्म अखिलम्' इति पदच्छेदद्वयेन — पूर्णं सर्वकर्म, अथवा ज्ञानरहितं कर्म 'आखिलम्' (खण्डमात्रम्) इति। ज्ञानरहितानि सर्वाणि कर्माणि संयोज्य अपि ज्ञानपूर्णकर्मात् अत्यल्पानि। अस्मत्कर्म ज्ञानार्थं स्यात्, न कर्मार्थं कर्म।",
  "4.34": "तद्विद्धि प्रणिपातेन परिप्रश्नेन सेवया ।\nउपदेक्ष्यन्ति ते ज्ञानं ज्ञानिनस्तत्त्वदर्शिनः ॥\n\nतत् प्रणिपातेन परिप्रश्नेन सेवया च विद्धि; तत्त्वदर्शिनः ज्ञानिनः ते ज्ञानम् उपदेक्ष्यन्ति।\n\nज्ञानार्जनाय तत्त्वदर्शिनां सेवा अनुसरणं च आवश्यकम्। ज्ञानं ग्रन्थपाठमात्रेण न लभ्यते, साक्षात्कारः अपेक्षितः — \"Truth is an intuitional flash, it is not Intellectual\" इति।",
  "4.35": "यज्ज्ञात्वा न पुनर्मोहमेवं यास्यसि पाण्डव ।\nयेन भूतान्यशेषेण द्रक्ष्यस्यात्मन्यथो मयि ॥\n\nहे पाण्डव, यत् ज्ञात्वा पुनः एवं मोहं न यास्यसि, येन सर्वभूतानि अशेषेण आत्मनि मयि च द्रक्ष्यसि — तत् तत्त्वदर्शिनः तुभ्यम् उपदेक्ष्यन्ति।\n\nएकवारं तत्त्वदर्शिभ्यः ज्ञानं प्राप्तं चेत् पुनः मोहावकाशः नास्ति। अत्र कृष्णः अर्जुनं 'पाण्डव' इति सम्बोधयति — 'पण्डा' ज्ञानम्, पाण्डवः ज्ञानराशिप्राप्तः; 'पाण्डु' श्वेतवर्णः सात्त्विकतासङ्केतः। सत्यज्ञानोदये मोहपाशः विगलति; समस्तं जीवजातम् आत्मनि आश्रितम्, भगवान् नियामकशक्तिः इति प्रज्ञा जागरूका भवति। स्वार्थदुःखासूयादयः अपसरन्ति, स्थितप्रज्ञता उदेति। भगवति आत्मसमर्पितस्य जीवने कदापि भयं नास्ति।",
  "4.36": "अपि चेदसि पापेभ्यः सर्वेभ्यः पापकृत्तमः ।\nसर्वं ज्ञानप्लवेनैव वृजिनं सन्तरिष्यसि ॥\n\nअपि चेत् त्वं सर्वपापिभ्यः पापकृत्तमः असि, तथापि ज्ञानप्लवेन एव सर्वं वृजिनं सन्तरिष्यसि।\n\n'यद्यपि त्वं तत्कालस्य सर्वश्रेष्ठः पापी, एकवारं भगवज्ज्ञानोदये त्वं विजयी एव' इति कृष्णाश्वासः। ज्ञानं पापसागरे नौकावत्, तत् एव तारकम्।",
  "4.37": "यथैधांसि समिद्धोऽग्निर्भस्मसात्कुरुतेऽर्जुन ।\nज्ञानाग्निः सर्वकर्माणि भस्मसात्कुरुते तथा ॥\n\nहे अर्जुन, यथा समिद्धः अग्निः एधांसि भस्मसात् करोति तथा ज्ञानाग्निः सर्वकर्माणि भस्मसात् करोति।\n\nज्ञानं सदाप्रज्वलितः अग्निः, तस्मात् शक्तिशालितरः अन्यः नास्ति। यथा अग्निः काष्ठं दहति तथा ज्ञानाग्निः सर्वपापकर्म दहति। कृष्णः अत्र 'अर्जुन' इति सम्बोधयति — अर्जनवान्, ज्ञानाग्निमान्; एतेन तस्य ज्ञानावृतं मोहपटलं सारयति।",
  "4.38": "न हि ज्ञानेन सदृशं पवित्रमिह विद्यते ।\nतत्स्वयं योगसंसिद्धः कालेनात्मनि विन्दति ॥\n\nज्ञानेन सदृशं पवित्रं इह न विद्यते; योगसंसिद्धः स्वयं कालेन तत् आत्मनि विन्दति।\n\nज्ञानं महापवित्रम्, यतः ज्ञानम् एव भगवान्। 'ज्ञानमार्गं गृहाण, कालपरिपाके सिद्धिं प्राप्स्यसि एव' इति कृष्णाश्वासः।",
  "4.39": "श्रद्धावाँल्लभते ज्ञानं तत्परः संयतेन्द्रियः ।\nज्ञानं लब्ध्वा परां शान्तिमचिरेणाधिगच्छति ॥\n\nसंयतेन्द्रियः श्रद्धावान् तत्परः ज्ञानं लभते; ज्ञानं लब्ध्वा अचिरेण परां शान्तिम् अधिगच्छति।\n\nश्रद्धा विना ज्ञानोदयः न भवति। स्वाभिमानत्यागः, अज्ञातसत्यस्य सम्भावनायां श्रद्धा च आवश्यके। ज्ञानतृष्णया सह इन्द्रियसंयमः स्यात्; ततः मानसात्मसाक्षात्कारक्रमेण परमात्मसाक्षात्कारः, अपरोक्षज्ञानसिद्धिश्च।",
  "4.40": "अज्ञश्चाश्रद्दधानश्च संशयात्मा विनश्यति ।\nनायं लोकोऽस्ति न परो न सुखं संशयात्मनः ॥\n\nअज्ञः अश्रद्दधानः संशयात्मा च विनश्यति; संशयात्मनः न अयं लोकः, न परः, न सुखम्।\n\nज्ञानश्रद्धारहिताः अज्ञानिनः निरन्तरं संशये जीवन्ति। बुद्धिं प्राप्तः संशयः अपरिहार्यः, सः अधःपातं नयति।",
  "4.41": "योगसंन्यस्तकर्माणं ज्ञानसञ्छिन्नसंशयम् ।\nआत्मवन्तं न कर्माणि निबध्नन्ति धनञ्जय ॥\n\nहे धनञ्जय, योगेन संन्यस्तकर्माणं ज्ञानेन सञ्छिन्नसंशयम् आत्मवन्तं कर्माणि न निबध्नन्ति।\n\nकर्मसंन्यासः कर्मत्यागः न, अपितु 'इदं कर्म भगवते' इति अर्पणम्। फलाशांस्त्यक्त्वा समदृष्ट्या निर्विकारं निरन्तरं कर्म कुर्वन् आत्मवान् भवति; तस्य कर्म न बध्नाति।",
  "4.42": "तस्मादज्ञानसम्भूतं हृत्स्थं ज्ञानासिनात्मनः ।\nछित्त्वैनं संशयं योगमातिष्ठोत्तिष्ठ भारत ॥\n\nअतः, हे भारत, अज्ञानसम्भूतं हृत्स्थं संशयम् आत्मनः ज्ञानासिना छित्त्वा योगम् आतिष्ठ, उत्तिष्ठ।\n\n'उत्तिष्ठ, ज्ञानस्वरूपभगवद्भक्तिनिरतः भारतकुलोत्पन्नः ज्ञानी त्वं मनसि स्थितं संशयं भगवज्ज्ञानासिना छिन्धि। अन्यायविरुद्धयुद्धं भगवत्पूजेति दीक्षां गृहीत्वा सत्यप्रामाणिकजीवनाय पुण्यसाधनं कुरु' इति कृष्णोक्तिः।\n\nइति चतुर्थोऽध्यायः समाप्तः।",
  "5.1": "[पञ्चमाध्यायस्य बन्नञ्जे-पीठिका]\n\nचतुर्थे अध्याये कृष्णः कर्मयोगं वर्णितवान्, अन्ते कर्मसंन्यासं च उक्तवान्। अत्र किञ्चित् सन्देहः जायते। कर्मयोगः कर्मसंन्यासः च किम् इति ज्ञातव्यम्। उपरिदृष्ट्या कर्मसंन्यासः कर्मत्यागः इव भाति। परन्तु कृष्णः चतुर्थाध्यायान्ते \"उत्तिष्ठ, युध्यस्व\" इति अर्जुनं कर्मणे प्रेरितवान् इति दृष्टम्। अतः कर्मसंन्यासः कर्मत्यागः न भवति इति स्पष्टम्। शास्त्रीयदृष्ट्या कर्मसंन्यासः नाम द्वन्द्वातीतत्वेन फलेच्छारहितं कर्म करणम्; रागद्वेषयोः कामक्रोधयोः च अत्र अवकाशः नास्ति। अतः कर्मसंन्यासः कर्मत्यागः न, अपि तु कर्मणि कामक्रोधत्यागः। \"कामक्रोधौ अतीत्य युध्यस्व, ज्ञानयोगमार्गे च चर\" इति कृष्णस्य सन्देशः। किन्तु कामक्रोधातीतेन ज्ञानमार्गेण कथं युध्यते इति अस्माकं दुर्बोधम्। एतद्विषये अर्जुनः कृष्णं पृच्छति, अस्माकं सर्वेषां कृते — इत्यनेन पञ्चमः अध्यायः आरभ्यते। अस्मिन् अध्याये कर्मसंन्यासस्य विशेषविवरणं कृष्णः प्रस्तौति।\n\nअर्जुन उवाच —\nसंन्यासं कर्मणां कृष्ण पुनर्योगं च शंससि ।\nयच्छ्रेय एतयोरेकं तन्मे ब्रूहि सुनिश्चितम् ॥\n\nहे कृष्ण, त्वं कदाचित् कर्मसंन्यासं, कदाचित् कर्मयोगं च प्रशंससि। एतयोः यत् श्रेयः तत् मे सुनिश्चितं ब्रूहि।\n\n'कदाचित् युध्यस्व, कदाचित् कर्मसंन्यासं कुरु' इति विरोधाभासं दृष्ट्वा अर्जुनः पृच्छति। युद्धे द्वन्द्वं अपरिहार्यम्; द्वन्द्वत्यागेन युद्धं कथं सम्भवति? कर्मसंन्यासः कर्मयोगश्च उभौ कथं युगपत् स्याताम्?",
  "5.2": "भगवानुवाच —\nसंन्यासः कर्मयोगश्च निःश्रेयसकरावुभौ ।\nतयोस्तु कर्मसंन्यासात्कर्मयोगो विशिष्यते ॥\n\nसंन्यासः कर्मयोगश्च उभौ श्रेयस्करौ; तयोः कर्मयोगः कर्मसंन्यासात् विशिष्यते।",
  "5.3": "ज्ञेयः स नित्यसंन्यासी यो न द्वेष्टि न काङ्क्षति ।\nनिर्द्वंद्वो हि महाबाहो सुखं बंधात्प्रमुच्यते ॥\n\nयः न द्वेष्टि न काङ्क्षति सः नित्यसंन्यासी ज्ञेयः; हे महाबाहो, निर्द्वंद्वः सुखं कर्मबन्धनात् प्रमुच्यते।\n\nअत्र संन्यासः संन्यासाश्रमो न, अपितु रागद्वेषातीतत्वम्। स-अहं-न्यास-संन्यासः — 'स' इति सम्पूर्णो दोषरहितो गुणपूर्णो भगवान्, तस्मिन् स्वाहङ्कारस्य (रागद्वेषाहङ्कारस्य) न्यासः संन्यासः। 'कर्मयोगः कर्मसंन्यासात् विशिष्यते' इति कृष्णोक्तिः, यतः अर्जुनः 'मम कौरवेषु द्वेषो नास्ति, विजयेच्छापि नास्ति, फलेच्छापि नास्ति' इति मत्वा युद्धं विना निष्क्रियः तिष्ठेत् चेत् तत् कर्मसंन्यासो न भवति, अधर्मस्य जयश्च भवेत्। अतः कर्मसंन्यासः कर्मयोगश्च युगपत् स्यातां — कर्मयोगरहितः संन्यासः कदापि श्रेयः न आनयति इति कृष्णस्य उत्तरम्।\n\nसंन्यासः अर्थपूर्णः स्यात् चेत् कामक्रोधत्यागेन सह क्रिया अपेक्षिता। युध्यस्व — रागद्वेषेण न। क्रियां विना रागद्वेषत्यागः निरर्थकः। अतः द्वन्द्वातीतत्वेन कर्म कर्तव्यम् इति कृष्णसन्देशः।\n\nअत्र कृष्णः अर्जुनं 'महाबाहो' इति सम्बोधयति — 'महाबा' इति रागद्वेषकामनामहापूरमग्नः; तं त्यक्तवान् महाबाहुः। 'त्वयि कर्मसंन्यासः वर्तते, तेन सह कर्मयोगयोग्यः महावीरः त्वम्' इति ध्वनिः।",
  "5.4": "साङ्ख्ययोगौ पृथग्बालाः प्रवदन्ति न पण्डिताः ।\nएकमप्यास्थितः सम्यगुभयोर्विंदते फलम् ॥\n\n'ज्ञानमार्गः कर्ममार्गश्च पृथक्' इति वदन्तः बालाः, न पण्डिताः; एकम् अपि सम्यक् आस्थितः उभयोः फलं विन्दते।\n\nसाङ्ख्यम् (सम्यक् ख्याति) इति गणितं न, शुद्धम् आत्मतत्त्वज्ञानम्। यज्ज्ञानविहीनाः 'बालाः' इति कृष्णोक्तिः। 'एकमपि आस्थितः सम्यक् उभयोः फलं विन्दते' इत्यस्य अर्थः — ज्ञानपूर्वकं कर्म, कर्मपूर्वकं ज्ञानं च परस्परपूरकम्। एकः ज्ञानप्रधानः, अन्यः कर्मप्रधानः; एतत् विदितवन्तः पण्डिताः वास्तविकं फलं लभन्ते।",
  "5.5": "यत्सांख्यैः प्राप्यते स्थानं तद्योगैरपि गम्यते ।\nएकं सांख्यं च योगं च यः पश्यति स पश्यति ॥\n\nयत् स्थानं साङ्ख्यैः प्राप्यते तत् योगैः अपि गम्यते; साङ्ख्ययोगयोः एकत्वं यः पश्यति सः पश्यति।\n\nज्ञानिनः स्वार्थाय एव न, लोकमार्गदर्शनायापि कर्म कुर्युः, यतः समाजः तान् अनुसरति। ज्ञानप्रदः कर्मप्रदश्च मार्गः परस्परपूरकौ, गन्तव्यं च एकं भगवन्तमेव। अतः कर्मसंन्यासः कर्मयोगश्च भिन्नौ इति निरर्थकम्।",
  "5.6": "संन्यासस्तु महाबाहो दुःखमाप्तुमयोगतः ।\nयोगयुक्तो मुनिर्ब्रह्म न चिरेण अधिगच्छति ॥\n\nहे महाबाहो, कर्मयोगरहितः केवलः संन्यासः दुःखमेव आप्नोति; योगयुक्तः मुनिः ब्रह्म न चिरेण अधिगच्छति।\n\nकर्मयोगरहितः केवलद्वन्द्वत्यागः व्यर्थः। शास्त्रपाठमात्रेण 'ज्ञानं प्राप्तम्, अहं द्वन्द्वातीतः, कर्मं न आवश्यकम्' इति निष्क्रियः भवेत् चेत् सः अधोगतिं गच्छति। किन्तु द्वन्द्वातीतः कामक्रोधौ जित्वा ज्ञानपूर्वकं कर्म कुर्यात् चेत् मोक्षः निश्चितः।",
  "5.7": "योगयुक्तो विशुद्धात्मा विजितात्मा जितेन्द्रियः ।\nसर्वभूतात्मभूतात्मा कुर्वन्नपि न लिप्यते ॥\n\nयोगयुक्तः विशुद्धात्मा विजितात्मा जितेन्द्रियः सर्वभूतात्मभूतात्मा कुर्वन् अपि न लिप्यते।\n\nकर्मयोगयुक्तः मनोनिग्रहेण शुद्धमनसा शुद्धं कर्म कुर्यात्। मनोजयाय भगवत्कृपा अपेक्षिता; मनोजयी इन्द्रियजयी भवति, ततः आत्मशुद्धिः। सर्वभूतात्मभूतं भगवन्तं स्वात्मानं ज्ञात्वा तस्मिन् मनो निधाय कृतं कर्म न लिप्यते।",
  "5.8": "नैव किंचित्करोमीति युक्तो मन्येत तत्त्ववित् ।\nपश्यन्श्रृण्वन्स्पृशञ्जिघ्रन्नश्नन्गच्छन्स्वपञ्श्वसन् ॥८॥\n\n[एतयोः श्लोकयोः (५.८ तथा ५.९) पदच्छेदः अर्थः व्याख्या च एकत्र अग्रिमे श्लोके (५.९) दीयते।]",
  "5.9": "नैव किंचित्करोमीति युक्तो मन्येत तत्त्ववित् ।\nपश्यन्श्रृण्वन्स्पृशञ्जिघ्रन्नश्नन्गच्छन्स्वपञ्श्वसन् ॥\nप्रलपन्विसृजन्गृह्णन्नुन्मिषन्निमिषन्नपि ।\nइन्द्रियाणीन्द्रियार्थेषु वर्तंत इति धारयन् ॥\n\nतत्त्ववित् युक्तः 'नैव किञ्चित् करोमि' इति मन्येत — पश्यन् श्रृण्वन् स्पृशन् जिघ्रन् अश्नन् गच्छन् स्वपन् श्वसन् प्रलपन् विसृजन् गृह्णन् उन्मिषन् निमिषन् अपि, 'इन्द्रियाणि इन्द्रियार्थेषु वर्तन्ते' इति धारयन्।\n\nजीवने देवपूजामात्रं अनुष्ठानं न; प्रतिक्षणकर्म कर्मयोगः स्यात्। 'नाहं स्वयं किमपि करोमि, मम इच्छापूर्विका कृतिः, तत्रापि स्वातन्त्र्यं नास्ति' इति सत्यं ज्ञातव्यम्। यत् कर्तुम् इच्छामः तत् न शक्नुमः, यत् वाञ्छितं तत् न लभ्यते, फले स्वातन्त्र्यं नास्ति — इदं प्रत्येकानुभवगम्यम्। तथापि क्रिया अस्मन्मुखेन एव प्रवर्तते।\n\n'नाहं इच्छया अहङ्कारेण वा करोमि, मदन्तः भगवान् एव कारयति' इति तत्त्वज्ञानी जानाति। अतः 'अहं ममेति' अहङ्कारः तस्य नास्ति। सर्वं भगवदिच्छानुसारेण प्रवर्तते, न स्वातन्त्र्येण — इति सत्यं ज्ञात्वा सः स्वक्रियां करोति।\n\nदृष्टान्तः — पुष्पस्य सौन्दर्यं चक्षुषा भुञ्जीमहि, गन्धं घ्राणेन आस्वादयामः; तत् सृष्टवान् भगवान् एव, चक्षुरपि तेनैव दत्तम् (जात्यन्धाय एतद्योगं न)। एतदनुसन्धानेन दर्शनस्पर्शघ्राणादिक्रियासु 'ममेति' अहङ्कारावकाशः नास्ति।",
  "5.10": "ब्रह्मण्याधाय कर्माणि सङ्गं त्यक्त्वा करोति यः ।\nलिप्यते न स पापेन पद्मपत्रमिवाम्भसा ॥\n\nयः ब्रह्मणि कर्माणि आधाय सङ्गं त्यक्त्वा करोति सः पापेन न लिप्यते, यथा पद्मपत्रम् अम्भसा।\n\n'श्रीकृष्णार्पणमस्तु' इति पूजान्ते वदामः — 'एतत् कर्म भगवता एव मया कारितं, मदुद्धाराय' इति सङ्कल्पः अर्पणम्। एवं कृतं कर्म अस्मान् न लिम्पति; 'अहं ममेति' अहङ्कारः अपसरति। पद्मपत्रं जले स्थित्वापि जलासङ्गं न प्राप्नोति, तथैव कर्मणि स्थित्वा कर्म कुर्वन् अपि कर्मासङ्गः अनेन अनुसन्धानेन एव सम्भवति।",
  "5.11": "कायेन मनसा बुद्ध्या केवलैरिन्द्रियैरपि ।\nयोगिनः कर्म कुर्वन्ति सङ्गं त्यक्त्वात्मशुद्धये ॥\n\nयोगिनः सङ्गं त्यक्त्वा आत्मशुद्धये कायेन मनसा बुद्ध्या केवलैः इन्द्रियैः अपि कर्म कुर्वन्ति।\n\nद्वन्द्वातीताः फलकामनारहिताः 'मयि भगवान् स्वपूजां मदुद्धाराय कारयति' इति ज्ञात्वा कर्तव्यबुद्ध्या कर्म कुर्वन्ति। तेषु अहङ्कारमहत्त्वे नास्ति, ततः मनःशुद्धिः। शुद्धमनसा शास्त्रार्थः यथावत् गृह्यते।",
  "5.12": "युक्तः कर्मफलं त्यक्त्वा शान्तिमाप्नोति नैष्ठिकीम् ।\nअयुक्तः कामकारेण फले सक्तो निबध्यते ॥\n\nयुक्तः कर्मफलं त्यक्त्वा नैष्ठिकीं शान्तिम् आप्नोति; अयुक्तः तु कामकारेण फले सक्तः निबध्यते।\n\nकर्मयोगयुक्तः ज्ञानानन्दपराकाष्ठां मोक्षं प्राप्नोति। फलकामनया कृतं कर्म अपूर्णफलं ददाति; निष्कामकर्मणा सर्वम् अपेक्षितं लभ्यते। कर्मयोगं विना 'स्वार्थाय दुडिमि, ममैव सम्पत्' इति भावेन कृतं कर्म बन्धकं भवति। काकोऽपि लब्धमन्नं स्वजनैः सह भुङ्क्ते; व्याघ्रसिंहादयोऽपि तृप्त्यनन्तरं स्वार्थं न कुर्वन्ति। मानवाः तु स्वार्थपराः, यावत् लभन्ते तावत् अधिकम् इच्छन्ति — एवं संसारचक्रे पतित्वा अधोगतिं प्राप्नुवन्ति।",
  "5.13": "सर्वकर्माणि मनसा संन्यस्यास्ते सुखं वशी ।\nनवद्वारे पुरे देही नैव कुर्वन्न कारयन् ॥\n\nवशी देही सर्वकर्माणि मनसा संन्यस्य नवद्वारे पुरे सुखम् आस्ते, न कुर्वन् न कारयन्।\n\n'कर्मं मानसिकं त्यज' इति कृष्णोक्तिः — कर्मत्यागः न, अपितु फलासक्तिस्वातन्त्र्यभ्रमत्यागः। 'ममेति', 'मदर्थम्' इति मानसिकत्यागः। जीवस्य कदापि कर्तृत्वे स्वातन्त्र्यं नास्ति इति मध्वाचार्यैः पुनःपुनः उक्तम्। एतत् मानसिकम् अवलम्ब्य जीवनं नैव कर्तव्यकर्मत्यागः, अपितु सत्यं कर्मसंन्यासम्। भगवान् नवद्वारपुरे (सम्पूर्णमानवशरीरे) अस्मान् स्थापयित्वा स्वयमेव अस्माभिः कर्म कारयति — इति एचरः कर्मयोगः।\n\n'नैव कुर्वन् न कारयन्' इति — सामान्यतः 'मया कृतम्' इति सर्वत्र वदामः; ज्ञानिनः तु 'भगवता मत्करेण कारितम्' इति वदन्ति। एतत् ज्ञान्यज्ञानिनोः कर्मानुसन्धानभेदः।",
  "5.14": "न कर्तृत्वं न कर्माणि लोकस्य सृजति प्रभुः ।\nन कर्मफलसंयोगं स्वभावस्तु प्रवर्तते ॥\n\nप्रभुः लोकस्य कर्तृत्वं कर्माणि कर्मफलसंयोगं च न सृजति; स्वभावः तु प्रवर्तते।\n\nजीवः जडात् विशिष्टः इच्छापूर्वक्रियावान्, तथापि कर्तृत्वं तस्य नास्ति। त्रिविधं कर्तृत्वं जगति — केवलक्रिया (जडेऽपि, यथा कक्षतः क्षीरस्रवणम्), बुद्धिपूर्विका अस्वतन्त्रा क्रिया (जीवे), स्वतन्त्रा इच्छापूर्विका क्रिया (केवलं भगवति)। जीवस्य दत्तस्वातन्त्र्यमपि नास्ति; सः भगवत्पराधीनः, अतः न कर्ता।\n\nपालने-शिशोः दृष्टान्तः — बुद्धिः इच्छा च वर्तते, स्वातन्त्र्यं तु नास्ति; मातृदत्तमेव भुङ्क्ते। फलेऽपि तथैव — पितरौ नमस्कारं कारयतः, फलं तु शिशोरेव। तथैव जीवान्तर्हितः अदृश्यः भगवान् जीवनक्रियां नियन्त्रयति; कर्म भगवत्कारितमपि फलं जीवस्यैव, न भगवतः।\n\n'भगवान् किमर्थं दुष्कर्म कारयति' इति प्रश्नः — उपाध्यायदृष्टान्तेन उत्तरम्: उपाध्यायः सर्वान् समानं पाठयति, किन्तु शिष्यभेदेन ग्रहणभेदः — तत्र उपाध्यायः न कारणम्, शिष्यस्वभाव एव कारणम्। 'स्वभावस्तु प्रवर्तते' इति अपूर्वं वचनम्। जीवः अनादिनित्यः, तस्य स्वभावोऽपि अनादिनित्यः; तदनुसारं जीवः वर्तते।\n\nआम्रबीजं यथा आम्रफलमेव ददाति न पनसफलम्, तथा जीवः देहवृक्षस्य बीजं स्वस्वभावानुगुणमेव अभिव्यज्यते। सत्त्वरजस्तमोमिश्रितः स्वभावः जीवस्य अनादिनित्यः; यत्र यो गुणः प्रधानः सः तद्गणं याति। स्वतन्त्रः भगवान् सृष्ट्युद्यानं निर्माय जीवबीजं तोटगारवत् वपति पोषयति च; ततः देहवृक्षः वर्धते, स्वभावानुगुणं तिक्तम् अम्लं मधुरं वा फलम् अभिव्यज्यते। मरिचवृक्षाय तोटगारः कदापि तिक्तजलं न सिञ्चति, तथापि सः स्वभावतः तिक्तं फलं ददाति।\n\nकदाचित् वयं स्वचिन्तनविरुद्धं कर्म कुर्मः, यतः मनोबुद्ध्योः विचारसरणिः भिन्ना, कृतिः भिन्ना। दुर्योधनोऽपि 'जानामि धर्मं न च मे प्रवृत्तिः तत्र' इति उक्तवान्; तथापि स्वस्वभावानुसारं प्रावर्तत। अतः ज्ञानं भिन्नं, क्रिया भिन्ना — इदमेव 'स्वभावस्तु प्रवर्तते' इति कृष्णवचनम्। यस्य यः स्वभावः तस्य तथैव भवितव्यम्, न अन्यथा। एतत् श्लोकः सर्वसंशयोत्तररूपम्। बुद्धिगतः संशयः 'स्थिरसंशयः' दुर्निवारः। शास्त्रीयानुभावः प्रतिपदम् आवश्यकः — अहं कः, स्वभावः कः, तन्नियामकशक्तिः का, फलदाता कः — इति ज्ञाते अहङ्कारावकाशो नास्ति।\n\nभगवतः शिक्षा द्वेषान्न, अपितु अनन्तकारुण्यात् — यथा मातुः शिशुशिक्षा। दुःखतापेन जीवः पच्यते; कष्टं विना जीवः न वर्धते। पतनस्य पृष्ठे उद्धारबीजं, दुःखस्य पृष्ठे सुखबीजं वर्तते। एषा शास्त्रीया अन्तःप्रज्ञा अध्यात्ममार्गे निरन्तरं धार्या।",
  "5.15": "नादत्ते कस्यचित्पापं न चैव सुकृतं विभुः ।\nअज्ञानेनावृतं ज्ञानं तेन मुह्यन्ति जन्तवः ॥\n\nविभुः कस्यचित् पापं सुकृतं वा न आदत्ते; अज्ञानेन आवृतं ज्ञानं तेन जन्तवः मुह्यन्ति।\n\n'विभुः' इति जीवपक्षे विशिष्टत्वं वैविध्यं च सूचयति — जीवः जडात् विशिष्टः, एकजन्मन्यपि बहुविधतां अनुभवति (श्रीमन्तः दरिद्राः वा, विद्वांसः मूढाः वा)। 'अन्येन कृतपापेन अहं दुःखितः' इति भ्रान्तिः — वस्तुतः स्वकृतकर्मफलमेव भुज्यते, न अन्यस्य। वामाचारादयः तावत्पर्यन्तमेव अकिञ्चित्कराः यावत् स्वसुकृतफलं रक्षति। भक्तार्थं पुरोहितकृतकर्म भक्तमेव गच्छति; अन्यथा स्वकृतमेव फलं स्वयं भुङ्क्ते।\n\nअन्यार्थे 'विभुः' इति सर्वसमर्थः सर्वगतः भगवान्; तस्य कर्मलेपः नास्ति, जीवभेदानुगुणं वर्धनं ददाति, न पक्षपाती। एतत् कर्मसिद्धान्तं बहवः न जानन्ति, अतः भगवद्विषये गोन्दलः।",
  "5.16": "ज्ञानेन तु तदज्ञानं येषां नाशितमात्मनः ।\nतेषामादित्यवज्ज्ञानं प्रकाशयति तत्परम् ॥\n\nयेषाम् आत्मनः तत् अज्ञानं ज्ञानेन नाशितं तेषां ज्ञानम् आदित्यवत् तत् परं प्रकाशयति।\n\nअस्माकं समस्यासमाधानाय एकः एव मार्गः — ज्ञानमार्गसाधनया सत्यज्ञानम्। जीवस्वरूपे ज्ञानं वर्तते, अज्ञानपटलेन आवृतम्। 'ज्ञानम् अग्निवत्, अन्तःस्थां ज्ञानस्फुलिङ्गां निरन्तरम् अन्तर्मननेन प्रज्वालय, तेन अज्ञानपटलं दह्यते' इति कृष्णोपदेशः। एतत् ज्ञानाग्निः सूर्यप्रकाशादपि महत्तरम्; इदम् अपरोक्षज्ञानं भगवत्साक्षात्कारं जनयति।",
  "5.17": "तद्बुद्धयस्तदात्मानस्तन्निष्ठास्तत्परायणाः ।\nगच्छन्त्यपुनरावृत्तिं ज्ञाननिर्धूतकल्मषाः ॥\n\nये तद्बुद्धयः तदात्मानः तन्निष्ठाः तत्परायणाः ज्ञाननिर्धूतकल्मषाः ते अपुनरावृत्तिं गच्छन्ति।\n\nभगवति बुद्धिं स्थापय (तद्बुद्धयः); आत्मानं मनश्च तस्मै अर्पय (तदात्मानः); तस्मिन् निष्ठा (भक्तिः) अनिवार्या (तन्निष्ठाः); तत्परायणत्वेन संसारः सर्वस्वम् इति भ्रमः अपसरति। एवं जीवन् आत्मकालुष्यं धावित्वा ज्ञानप्रकाशेन भगवत्साक्षात्कारं प्राप्य अपुनरावृत्तिं मोक्षं लभते।",
  "5.18": "विद्याविनयसंपन्ने ब्राह्मणे गवि हस्तिनि ।\nशुनि चैव श्वपाके च पण्डिताः समदर्शिनः ॥\n\nविद्याविनयसंपन्ने ब्राह्मणे गवि हस्तिनि शुनि श्वपाके च पण्डिताः समदर्शिनः भवन्ति।\n\nएतत् गूढार्थं श्लोकम्। मानवेषु विद्याविनयसंपन्नः श्रेष्ठतमः, ततः ब्राह्मणवर्णः, अधमतमः श्वपाकः। पशुषु गौः श्रेष्ठा, हस्ती मध्यमः, श्वा अधमः। सत्त्वगुणपूर्णा गौः, तमोगुणप्रधानः श्वा। पण्डिताः सर्वत्र भगवतः विशिष्टाभिव्यक्तिं पश्यन्ति — सर्वान्तर्यामी भगवान् सर्वेषु वर्तते, अभिव्यक्तिः तु भिन्ना। प्रतिजीवं स्वकीयगुणधर्मेण अभिव्यज्यते — यथा स्पर्शमणिवृक्षे (Touch-me-not) औषधीयगुणः, मधुमक्षिकायां च मधुनिर्माणशक्तिः। एवं सर्वत्र भगवन्महिमानुसन्धानम् अपरोक्षज्ञानाय अपेक्षितं समदर्शनम्।",
  "5.19": "इहैव तैर्जितः सर्गो येषां साम्ये स्थितं मनः ।\nनिर्दोषं हि समं ब्रह्म तस्माद्ब्रह्मणि ते स्थिताः ॥\n\nयेषां मनः साम्ये स्थितं तैः इह एव सर्गः जितः; निर्दोषं समं ब्रह्म, तस्मात् ते ब्रह्मणि स्थिताः।\n\nसर्वगुणपूर्णः भगवान् सर्वत्र तुल्यरूपेण वर्तते इति अनुसन्धाने मनः स्थितं चेत् जन्ममृत्युपारमोक्षद्वारं उद्घाटितम्। यत्राधिष्ठाने भगवान् वर्तते तत्र दोषो नास्ति, सः निर्लिप्तः तत्र तुम्बति। एतज्ज्ञानिनां मनः भगवति स्थितं भवति, अतः ते पुनः बन्धनं न प्राप्य शाश्वतं मोक्षं लभन्ते।",
  "5.20": "न प्रहृष्येत्प्रियं प्राप्य नोद्विजेत्प्राप्य चाप्रियम् ।\nस्थिरबुद्धिरसंमूढो ब्रह्मविद्ब्रह्मणि स्थितः ॥\n\nप्रियं प्राप्य न प्रहृष्येत्, अप्रियं प्राप्य न उद्विजेत्; स्थिरबुद्धिः असंमूढः ब्रह्मवित् ब्रह्मणि स्थितः भवति।\n\nजीवनं सुखदुःखयोः चक्रभ्रमणम्। प्रियाप्रिययोः समदृष्टिः स्यात्। अनिवार्यं यत् तत् स्वाभाविकतया स्वीकर्तव्यम्; अन्यथा मनः विक्षिप्तं भवति। सुखे अतिहर्षो न, दुःखे अतिविषादो न — इदमेव जीवनस्य सफलसूत्रम्। आध्यात्मिकदृष्ट्या प्रियाप्रिये न वस्तुतः शुभाशुभे। कठोपनिषदि उक्तम् — 'प्रेयो मन्दो योगक्षेमाद्वृणीते' (१.२.२) — प्रेयः वृणीते यः सः मन्दः इति। भगवान् हितं जानाति इति ज्ञात्वा सुखदुःखयोः मनः न निधाय भगवत्येव मनः स्थापयेत्।",
  "5.21": "बाह्यस्पर्शेष्वसक्तात्मा विंदत्यात्मनि यत्सुखम् ।\nस ब्रह्मयोगयुक्तात्मा सुखमक्षयमश्नुते ॥\n\nबाह्यस्पर्शेषु असक्तात्मा आत्मनि यत् सुखं विन्दति; स ब्रह्मयोगयुक्तात्मा सुखम् अक्षयम् अश्नुते।\n\nरूपरसगन्धस्पर्शशब्दाः पञ्च सुखसाधनानि; तैः अनुभवः न दोषः, किन्तु त्यागे अधिकः आनन्दः। बाह्यसुखत्यागेन अन्तरात्मसुखानुभवः आरभ्यते। ब्रह्मयोगयुक्तः अन्तरङ्गे भगवत्स्पर्शेन अनन्तसुखं निरन्तरं सवीति।",
  "5.22": "ये हि संस्पर्शजा भोगा दुःखयोनय एव ते ।\nआद्यंतवंतः कौंतेय न तेषु रमते बुधः ॥\n\nसंस्पर्शजाः भोगाः दुःखयोनयः एव, आद्यन्तवन्तः; हे कौन्तेय, बुधः तेषु न रमते।\n\nविषयसंस्पर्शजसुखं अल्पम्, तदर्थं महद्दुःखं सह्यते। बाह्यसुखं क्षणिकं मिन्चवत्; तिळुवळिकावन्तः तस्मिन् न आसजन्ति।",
  "5.23": "शक्नोतीहैव यः सोढुं प्राक्शरीरविमोक्षणात् ।\nकामक्रोधोद्भवं वेगं स युक्तः स सुखी नरः ॥\n\nयः शरीरविमोक्षणात् प्राक् इह एव कामक्रोधोद्भवं वेगं सोढुं शक्नोति सः युक्तः सः सुखी नरः।\n\nदेहसत्तायाम् एव विषयासक्तिजयः सम्भवति। कामक्रोधवेगः विवेकं प्लावयति; तं देहपातात् प्राक् निरन्तरसाधनया निगृह्णीयात्। एतद्विजयी एव सुखी।",
  "5.24": "योऽन्तःसुखोऽन्तरारामस्तथान्तर्ज्योतिरेव यः ।\nस योगी ब्रह्मनिर्वाणं ब्रह्मभूतोऽधिगच्छति ॥\n\nयः अन्तः सुखः अन्तः आरामः अन्तः ज्योतिः च सः योगी ब्रह्मभूतः ब्रह्मनिर्वाणम् अधिगच्छति।\n\n'सुख' 'आराम' इति द्वयोः सूक्ष्मभेदः — इच्छापूर्तिजन्यम् आरामः, इच्छाराहित्यजन्यं सुखम्। अध्यात्मयोगसाधकः मानसिकतया भगवति स्थितः अन्तः आरामी सुखी च भवति, स्वान्तर्ज्योतिं दृष्ट्वा भगवत्येव स्थिरीभवति।",
  "5.25": "लभंते ब्रह्मनिर्वाणमृषयः क्षीणकल्मषाः ।\nछिन्नद्वैधा यतात्मानः सर्वभूतहिते रताः ॥\n\nक्षीणकल्मषाः छिन्नद्वैधाः यतात्मानः सर्वभूतहिते रताः ऋषयः ब्रह्मनिर्वाणं लभन्ते।\n\nस्वान्तः उद्भूतसंशयद्वन्द्वातीताः एव सत्यसाधकाः; ते अन्तः स्थिरमनसः, अन्तःसुखकाङ्क्षिणः, सर्वभूतहितैषिणः च नित्यं भगवन्तं प्राप्नुवन्ति।",
  "5.26": "कामक्रोधवियुक्तानां यतीनां यतचेतसाम् ।\nअभितो ब्रह्मनिर्वाणं वर्तते विदितात्मनाम् ॥\n\nकामक्रोधवियुक्तानां यतचेतसां विदितात्मनां यतीनाम् अभितः ब्रह्मनिर्वाणं वर्तते।\n\nकामक्रोधसम्पूर्णत्यागिनां पूर्णेन्द्रियनिग्रहिणां सर्वत्र सर्वजीवेषु भगवान् दृश्यते; तेषां ऐहिकक्लेशो नास्ति, मनसि सर्वान्तर्यामी भगवान् स्थिरः तिष्ठति।",
  "5.27": "स्पर्शान्कृत्वा बहिर्बाह्यांश्चक्षुश्चैवांतरे भ्रुवोः ।\nप्राणापानौ समौ कृत्वा नासाभ्यंतरचारिणौ ॥२७॥\n\nयतेन्द्रियमनोवृत्तिर्मुनिर्मोक्षपरायणः ।\nविगतेच्छाभयक्रोधो यः सदा मुक्त एव सः ॥२८॥\n\n[एतयोः श्लोकयोः (५.२७, ५.२८) पदच्छेदः अर्थः विवरणं च अग्रिमश्लोके (५.२८) एकत्र दीयते।]",
  "5.28": "स्पर्शान्कृत्वा बहिर्बाह्यांश्चक्षुश्चैवांतरे भ्रुवोः ।\nप्राणापानौ समौ कृत्वा नासाभ्यंतरचारिणौ ।\nयतेन्द्रियमनोवृत्तिर्मुनिर्मोक्षपरायणः ।\nविगतेच्छाभयक्रोधो यः सदा मुक्त एव सः ॥\n\nबाह्यस्पर्शान् बहिः कृत्वा, दृष्टिं भ्रुवोः मध्ये स्थापयित्वा, नासाभ्यन्तरचारिणौ प्राणापानौ समौ कृत्वा, इन्द्रियमनोवृत्तिं यतः, मोक्षपरायणः इच्छाभयक्रोधरहितः मुनिः सदा मुक्त एव।\n\nमनोनिग्रहाय प्रथमं बाह्येन्द्रियनिग्रहः आवश्यकः — रूपरसस्पर्शशब्दगन्धभ्रमः बहिः त्याज्यः। ध्यानकाले अनेके विचाराः उद्भवन्ति, तेषु भयं न कर्तव्यम्; निरन्तरसाधनया मनः निर्मलं भवति। देहस्थैर्यम् (अन्नमयकोशस्थिरीकरणम्) ऋजुकायेन उचितासनेन (Posture) साध्यम्; दृष्टिं भ्रुवोर्मध्ये (आज्ञाचक्रे) स्थापयेत्। ततः प्राणमयकोशस्थैर्यं कुम्भकेन — अन्तःकुम्भकः बाह्यकुम्भकश्च द्विविधः [गुरूपदेशं विना न कर्तव्यः]। ततः मनोमयविज्ञानमयकोशयोः स्थैर्यं दृढसङ्कल्पेन। एवं चित्तं भगवत्येकाग्रं भवति — इयं पाञ्चभौतिकस्थितिषु सर्वोत्कृष्टा स्थितिः, अत्रानन्दः अपरिमितः। एवं स्थितः साधकः सदा मुक्त एव।",
  "5.29": "भोक्तारं यज्ञतपसां सर्वलोकमहेश्वरम् ।\nसुहृदं सर्वभूतानां ज्ञात्वा मां शांतिमृच्छति ॥\n\nयः मां सर्वयज्ञतपसां भोक्तारं सर्वलोकमहेश्वरं सर्वभूतानां सुहृदं च ज्ञात्वा शान्तिम् ऋच्छति।\n\nभगवान् सर्वयज्ञभोक्ता (न केवलम् अग्निमुखयज्ञस्य, अपितु सर्वप्रकारयज्ञस्य)। देवतोद्दिष्टं हविरपि तदन्तर्यामिणे भगवते अर्पणीयम्; अन्यथा देवताः न स्वीकुर्वन्ति। सर्वक्रियासु भगवदनुसन्धानं ध्याने प्रमुखम्। दैहिकमानसिकवाचिकं अचलं व्रतं तपः।\n\nकेषाञ्चित् भगवान् भयहेतुः! अत्र कृष्णः 'सुहृदं सर्वभूतानाम्' इति वदति — भगवद्विषये भयं न कर्तव्यम्; तस्मात् आत्मीयतरः सखा नास्ति। प्रत्येकं स्वयोग्यतानुगुणं वर्धयन्, दोषे शिक्षां दत्त्वा मार्गं दर्शयन्, कारुण्येन उत्थापयन् सुहृत् सः भगवान्। एतज्ज्ञात्वा अनुसरन् ज्ञानानन्दपराकाष्ठां मोक्षं लभते।\n\nइति पञ्चमोऽध्यायः समाप्तः।",
  "6.1": "षष्ठोऽध्यायः\n\nपूर्वाध्याये कृष्णः भगवदुपासनासाधनं प्रधानतः वर्णितवान्; अधुना षष्ठे अध्याये ध्यानयोगं ध्यानसमाधिं च मूलतः वर्णयति।\n\nभगवानुवाच —\nअनाश्रितः कर्मफलं कार्यं कर्म करोति यः ।\nस संन्यासी च योगी च न निरग्निर्न चाक्रियः ॥१॥\n\nकर्मफलम् अनाश्रित्य यः कर्तव्यं कर्म करोति सः एव सत्यसंन्यासी सत्ययोगी च, न तु अग्निहोत्रत्यागी न वा कर्मत्यागी। वयं सामान्यतः कर्मयोगिनः संन्यासिनश्च पृथक् मन्यामहे; अत्र कृष्णः लोकसम्मताद् भिन्नं दर्शयति — सर्वं कर्म भगवते अर्पणमेव संन्यासः, न तु कर्मराहित्यम्। संन्यासः कुटुम्बत्यागेन वनगमनं न भवति; कर्मयोगः अवश्यं कर्तव्यः। यस्य यत् कार्यं तत् तेन कर्तव्यमेव — अतः संन्यासः कर्मयोगश्च सहचरौ; सत्यसंन्यासी कर्मयोगी भवति, सत्यकर्मयोगी च संन्यासी भवति। केवलम् अग्नित्यागिनः कर्मत्यागिनश्च न संन्यासिनः योगिनो वा।\n\nसंन्यासी कदापि निष्क्रियः न भवति; प्रत्येकस्य स्वकीयं कर्म वर्तते। ब्रह्मचारी अध्ययनगुरुकुलवासगुरुशुश्रूषादिकं करोति, गृहस्थः अतिथिसत्कारसंसारपालनादिकं करोति — एवं सर्वेषां कर्म विद्यते।",
  "6.2": "यत् संन्यासमिति कथ्यते तदेव योगमिति जानीहि पाण्डव। यः कामसंकल्पं न त्यजति सः मर्मज्ञः कर्मयोगी न भवति। संन्यासोऽपि योग एव; फलत्यागः कर्मयोगिनः योगस्य एकं मुखम्। सर्वं भगवते समर्प्य फलकामनारहितं भगवत्पूजाबुद्ध्या कृतं कर्म सात्त्विकानां साधनम्। संन्यासः कामसंकल्पयोः भगवति समर्पणम् — कामः 'कर्तव्यम्' इति इच्छा, संकल्पः 'करिष्ये' इति निश्चयः; कामसंकल्पवर्जनं संन्यासः। अत्र कृष्णः आश्रमविषयं न वदति, साधनाविषयमेव वदति — साधनामार्गे योगिनः संन्यासिनः भवेयुः, संन्यासिनश्च योगिनः भवेयुः इति कृष्णस्य सन्देशः।\n\nसाधनाकाले कर्म फलन्यासश्च उभावपि आवश्यकौ। सर्वेषां कर्तव्यं किं कर्म? साधकस्य सामाजिकं कर्तव्यं किम्? साधकः समाजेन सह कथं व्यवहरेत्? कर्मस्य अन्तः कदा? साधनया कर्मणा च सामरस्यं किम्? एतेभ्यः प्रश्नेभ्यः कृष्णः अग्रिमे श्लोके उत्तरं ददाति।\n\nआरुरुक्षोर्मुनेर्योगं कर्म कारणमुच्यते ।\nयोगारूढस्य तस्यैव शमः कारणमुच्यते ॥३॥",
  "6.3": "योगम् आरोढुम् इच्छतः मुनेः कर्मयोगः [बहुविधा लोकसेवा] गुरिं प्राप्तुं कारणम् उच्यते। योगारूढस्य तु भगवत्समाधिः [लोकसेवातः विरामः भगवति ध्याननिष्ठा च] सुखवृद्धेः कारणम्।\n\nअस्मिन् श्लोके द्वे आयामे स्तः — एकं साधकः स्वनित्यकर्म कियत्कालं कुर्यात् कदा वा त्यजेत् इति, अपरं साधकस्य सामाजिकं कर्तव्यं किम् इति।\n\nअद्यापि असिद्धः साधकः विहितं सर्वं कर्म करोत्येव, किमपि न त्यजेत्। सिद्धः तु समाधिस्थितौ अन्तः भगवन्तं पश्यति; तदा अन्तरङ्गे भगवद्दर्शनमेव मुख्यं कर्म भवति, न त्वन्यानि कर्माणि। अपरोक्षज्ञानी सदा समाधौ स्थातुं न शक्नोति; बहिः आगन्तव्यमेव। तदा तस्य मुख्यं कर्म शास्त्रश्रवणं मन्त्रजपः प्रवचनं च। अतः विहितकर्मणां विधिनिषेधबद्धता अपरोक्षज्ञानपर्यन्तमेव। यथा — अपरोक्षज्ञानी ध्याने उपविष्टः अन्तः भगवन्तं पश्यति, तदानन्दे मग्नः; तत् प्रातःकालः सन्ध्यावन्दनसमयश्च — तं तथा उत्थापयितुं न युज्यते, यतः सन्ध्यावन्दनं भगवद्दर्शनार्थमेव, स च तत् दर्शनं प्राप्नोत्येव। समाधितः निर्गतस्य तु कर्तव्यं भगवद्गुणगानं प्रवचनम् अध्ययनं जपश्च।\n\nअस्य श्लोकस्य अपरम् आयामं मध्वाचार्याः स्वगीतातात्पर्ये सुन्दरतया वर्णितवन्तः — साधकस्य सामाजिकाचरणं कीदृशं भवेत् इति। कर्मशब्दस्य अपूर्वं अर्थं आचार्याः प्रददुः — कर्म इति करमेव; करः कन्दायः [कर्तव्यम्]; यत् कन्दायत्वेन ज्ञात्वा कर्तव्यं तत् करकर्म। वयं भगवद्राज्यस्य प्रजाः; तदर्थं तस्मै दीयमानः करः एव कर्म। स्वेच्छया देवालये अर्पितं कानिकं न सत्यः करः, न च तं भगवान् इच्छति। भगवान् अस्मत्तः यं कर्म इच्छति सः दुःखितानां शुश्रूषा। साधकस्य अपरोक्षसाधनपर्यन्तं इदमेव मुख्यं साधनम्। सर्वजीवेषु अनुकम्पा सेवाभावश्च अतीव महत्त्वपूर्णौ। योगशास्त्रेऽपि इदमेव उक्तम् — मैत्रीकरुणामुदितोपेक्षाः चतस्रः वृत्तयः साधके स्युः। मैत्री सज्जनसहवासः, करुणा दुःखदर्शने सहायः, मुदिता परोत्कर्षे प्रसन्नता, उपेक्षा दुर्जनेभ्यः द्वेषरहितं दूरत्वम्। एतत् साधकजीवने महत् सामाजिकं कर्तव्यम्। योगारूढः तु सदा अन्तर्मुखः; तस्य सामाजिकबद्धता नास्ति (न वा सा तस्य सम्भवति)। तस्य आनन्दवृद्धेः कारणं शमः — भगवति सदा मनःस्थापनम्; ततः अन्यत् कर्म तस्य नास्ति।\n\nएवं लोकसेवा साधकस्य अविभाज्यं अङ्गं भवेत् इति कृष्णः अस्मिन् श्लोके स्पष्टं वदति। योगारूढस्य सामाजिकबद्धता नास्ति, सः अन्तः भगवन्तं पश्यति एव इति श्रुत्वा प्रश्नः उदेति — अपरोक्षज्ञानिनः कथं ज्ञायन्ते? अग्रिमः श्लोकः अस्य प्रश्नस्य उत्तरम्।\n\nयदा हि नेन्द्रियार्थेषु न कर्मस्वनुषज्जते ।\nसर्वसंकल्पसंन्यासी योगारूढस्तदोच्यते ॥४॥",
  "6.4": "यदा सर्वं कर्मभारं भगवते समर्प्य इन्द्रियार्थेषु कर्मसु च आसक्तिं त्यजति, तदा सः साधनागुरिं प्राप्तः उच्यते।\n\nअपरोक्षज्ञानिनः लक्षणं वदन् कृष्णः आह — सः शब्दरूपरसगन्धस्पर्शादिषु न आसज्यते; करोति एव कर्म, परन्तु तस्मिन् न लिप्यते। साधकः प्रयत्नेन इन्द्रियनिग्रहं करोति, अपरोक्षज्ञानिनस्तु इदं सहजधर्मः। ऋग्वेदे उक्तम् — \"जगन्नियामकः नरसिंहः; तस्य इच्छा एव मम इच्छा भवतु, तद्धृदि यत् वर्तते तदेव मम भावना भवतु, तद्विरुद्धः संकल्पः मा भूत्\" इति। एवमेव अपरोक्षज्ञानी इच्छति — सः इन्द्रियद्वारा किमपि अनुभवितुं न इच्छति, न परितप्यते, अनुभवेन प्रभावितः सन् न आसज्यते, सर्वं तटस्थतया पश्यति। यथा समुद्रतटे उपविष्टः तरङ्गान् पश्यन् आनन्दयति, तेषां नियन्त्रणं तु न अस्मत्करे — एवमेव जीवनसागरे सुखदुःखे तरङ्गवत् आगच्छतः गच्छतश्च तटस्थतया द्रष्टुं आनन्दितुं च एतदेव अपरोक्षज्ञानिनः लक्षणम्।\n\nअस्मिन् अध्याये कृष्णः ध्यानस्य सम्पूर्णां प्रक्रियां अग्रे वर्णयिष्यति; तदर्थं मनः कथं सज्जं कर्तव्यं, योगारूढत्वाय किं कर्तव्यम् इति अग्रिमः श्लोकः प्रस्तावयति।\n\nउद्धरेदात्मनात्मानं नात्मानमवसादयेत् ।\nआत्मैव ह्यात्मनो बन्धुरात्मैव रिपुरात्मनः ॥५॥",
  "6.5": "आत्मशब्दस्य बहवः अर्थाः — शरीरं मनः जीवः परमात्मा च। सर्वान् अर्थान् संयोज्य पश्यतः स्पष्टं भवति — अस्माकम् अधःपातस्य उद्धारस्य च कारणं मन एव; अतः मनसा जीवस्य उद्धारमार्गम् अन्विष्य मनः अधः न प्रेषयेत्, ऊर्ध्वं नयेत्। अधोगतं मनः पातालं नयति, ऊर्ध्वगतं तु ऊर्ध्वं नयति। मन एव जीवस्य बन्धुः, मन एव शत्रुः — अतः साधनार्थं मनः बन्धुत्वेन परिणमयेत्; बुद्धिबलेन मनः प्रशिक्ष्य जयेत् इति कृष्णसन्देशः। मनोजये सर्वं प्रशान्तं भवति — इयं ध्यानस्य पूर्वस्थितिः।\n\nपरन्तु भगवदनुग्रहं विना मनः स्वतन्त्रतया नियन्तुं न शक्यते इति प्रश्नः उदेति। सूक्ष्मार्थे आत्मशब्दः परमात्मानं बोधयति — तेन \"आत्मना आत्मानम् उद्धरेत्\" इत्यस्य अर्थः भगवतैव जीवस्य उद्धारः कर्तव्य इति। मनः अस्मद्वचनं न शृणोति; परन्तु बुद्ध्या भगवन्तं प्रति नित्यं प्रार्थयेत् — \"मह्यं सुमनः देहि, उद्धारमार्गे मां नय, साधनाय सद्बुद्धिं देहि\" इति। सः अस्माकं शाश्वतः निरपेक्षः बन्धुः, प्रार्थनां श्रुत्वा मनसि अध्यास्यति।\n\nभगवान् यथा दृश्यते तथैव व्यक्तः भवति — देवाः तं ज्ञानिनं दृष्ट्वा उद्धृताः, राक्षसाः तं शत्रुं मत्वा द्विष्टवन्तः तेषां शत्रुरिव आभासितः। अतः अहंकारेण पथभ्रष्टानां सः शत्रुवत् भासते इति अग्रिमः श्लोकः स्पष्टयति।\n\nबन्धुरात्मात्मनस्तस्य येनात्मैवात्मना जितः ।\nअनात्मनस्तु शत्रुत्वे वर्तेतात्मैव शत्रुवत् ॥६॥",
  "6.6": "येन जीवेन विवेकेन आत्मा [भक्त्या भगवान्] जितः, तस्य सः बन्धुः; येन न जितः तस्य सः शत्रुवत् एव।\n\nये भगवन्तं जितवन्तः, तस्य प्रेम्णे पात्रीभूताः, तेषां सः बन्धुः — तत्प्राप्तये तदनुग्रहः आवश्यकः। ये तु भगवन्तं पृष्ठतः कृत्वा अग्रे गच्छन्ति, ते सदा तस्मात् दूरं गच्छन्ति; द्विषतां सः शत्रुवत् भासते। अतः नित्यं प्रार्थयेत् — \"बन्धुत्वेन मयि आगत्य निवस, मां सुपथे नय, स्वं प्रति परिवर्त्य अग्रे नय\" इति। एषा प्रार्थना शरणागतिश्च मनः तस्मिन् स्थापयति — इयं ध्यानस्य प्रथमा सोपानम्। एवं मनोजयाय भगवदनुग्रहं प्राप्तुं यतमानस्य किं भवति इति अग्रिमेषु श्लोकेषु द्रक्ष्यामः।",
  "6.7": "जितात्मनः प्रशान्तस्य परमात्मा समाहितः ।\nशीतोष्णसुखदुःखेषु तथा मानापमानयोः ॥७॥\n\n[एतयोः श्लोकयोः (६.७, ६.८) पदच्छेदः अर्थः विवरणं च अग्रिमश्लोके (६.८) एकत्र दीयते।]",
  "6.8": "जितात्मनः प्रशान्तस्य परमात्मा समाहितः ।\nशीतोष्णसुखदुःखेषु तथा मानापमानयोः ।\nज्ञानविज्ञानतृप्तात्मा कूटस्थो विजितेन्द्रियः ।\nयुक्त इत्युच्यते योगी समलोष्टाश्मकाञ्चनः ॥\n\nभक्त्या जितात्मनः प्रशान्तस्य हृदये परमात्मा समाहितः तिष्ठति। शीतोष्णसुखदुःखमानापमानद्वन्द्वेषु सः निर्विकारः तिष्ठति; ज्ञानविज्ञानतृप्तः जितेन्द्रियः च। तस्मै मृत्तिका पाषाणः स्वर्णं च समम्। एतादृशः योगसाधकः लक्ष्यं प्राप्तः इति उच्यते।\n\nभक्त्या भगवदनुग्रहे प्राप्ते प्रथमं मनः तस्मिन् स्थिरीभवति; तत् कस्मिन्नपि प्रसङ्गे न उद्विजते। \"परमात्मा समाहितः\" — भगवान् तस्य हृदये आगत्य स्थिरीभवति। अस्माकम् इच्छायां तस्य अन्तर्दर्शनं सम्भवति।",
  "6.9": "सुहृन्मित्रार्युदासीनमध्यस्थद्वेष्यबन्धुषु ।\nसाधुष्वपि च पापेषु समबुद्धिर्विशिष्यते ॥\n\nसुहृत्-मित्र-अरि-उदासीन-मध्यस्थ-द्वेष्य-बन्धुषु साधुषु पापेषु च समबुद्धिः विशिष्यते।\n\nमनसः समत्वं विना ध्यानं न सम्भवति। संसारे बहुविधाः जनाः — सुहृदः, मित्राणि, अरयः, उदासीनाः, मध्यस्थाः, द्वेष्याः, बन्धवः, साधवः, पापिनः च। सर्वे मूलतः ज्ञानस्वरूपाः इति समभावेन पश्यन् एव मिगिलः। ध्याने भगवद्दर्शनाय प्रथमं एतेषु सर्वेषु अन्तरङ्गे समबुद्धिः वर्धनीया।",
  "6.10": "योगी युञ्जीत सततमात्मानं रहसि स्थितः ।\nएकाकी यतचित्तात्मा निराशीरपरिग्रहः ॥\n\nयोगी रहसि स्थितः एकाकी यतचित्तात्मा निराशीः अपरिग्रहः सततम् आत्मानं युञ्जीत।\n\nध्यानमार्गसाधकः मनः निरन्तरं ध्यानयोगे नियोजयितुं एकाग्रीकर्तुं च प्रयतेत। जनाकीर्णे स्थाने ध्यानाभ्यासः असाध्यः। अतः पूर्वजाः ब्रह्ममुहूर्ते ध्यानं कुर्वन्ति स्म — सूर्योदयात् प्रागेव षण्णवतिमिनिटानि, यत्र चतुर्मुखः अभिमानी देवता, सोऽयम् अस्माकं चित्ताभिमानी अपि। एकाकित्वं चित्तनियमनं च ध्यानाय आवश्यके।",
  "6.11": "शुचौ देशे प्रतिष्ठाप्य स्थिरमासनमात्मनः ।\nनात्युच्छ्रितं नातिनीचं चेलाजिनकुशोत्तरम् ॥११॥\n\n[एतयोः श्लोकयोः (६.११, ६.१२) पदच्छेदः अर्थः विवरणं च अग्रिमश्लोके (६.१२) एकत्र दीयते।]",
  "6.12": "शुचौ देशे प्रतिष्ठाप्य स्थिरमासनमात्मनः ।\nनात्युच्छ्रितं नातिनीचं चेलाजिनकुशोत्तरम् ।\nतत्रैकाग्रं मनः कृत्वा यतचित्तेन्द्रियक्रियः ।\nउपविश्यासने युञ्ज्याद्योगमात्मविशुद्धये ॥\n\nशुचौ देशे न अति उच्चं न अति नीचं कुश-अजिन-चेलोत्तरं स्थिरम् आसनं प्रतिष्ठाप्य, तत्र उपविश्य, एकाग्रं मनः कृत्वा इन्द्रियचित्तक्रियां यतः, आत्मविशुद्धये योगं युञ्ज्यात्।\n\nध्यानस्थलं सात्त्विककम्पनयुक्तं शुचि स्यात्। कुशचटिका, तदुपरि अजिनम्, तदुपरि वस्त्रं — इदम् आसनं धरण्याः दुष्टकम्पनान् निवारयति। मनः प्रथमम् एकाग्रं (एकः अग्रः — सृष्ट्यादिनियामके भगवति लक्ष्यं) कर्तव्यम्; ततः बाह्येन्द्रियक्रिया स्तब्धा कार्या; ततः चित्तनियमनम्। एतत् सर्वं जन्मजन्मान्तरसाधनापेक्षम्, निराशा न कर्तव्या।",
  "6.13": "समं कायशिरोग्रीवं धारयन्नचलं स्थिरः ।\nसम्प्रेक्ष्य नासिकाग्रं स्वं दिशश्चानवलोकयन् ॥१३॥\n\n[एतयोः श्लोकयोः (६.१३, ६.१४) पदच्छेदः अर्थः विवरणं च अग्रिमश्लोके (६.१४) एकत्र दीयते।]",
  "6.14": "समं कायशिरोग्रीवं धारयन्नचलं स्थिरः ।\nसम्प्रेक्ष्य नासिकाग्रं स्वं दिशश्चानवलोकयन् ।\nप्रशान्तात्मा विगतभीर्ब्रह्मचारिव्रते स्थितः ।\nमनः संयम्य मच्चित्तो युक्त आसीत मत्परः ॥\n\nकाय-शिरः-ग्रीवां समम् अचलं धारयन्, स्वनासिकाग्रं सम्प्रेक्ष्य, दिशः अनवलोकयन्, प्रशान्तात्मा विगतभीः ब्रह्मचारिव्रते स्थितः, मनः संयम्य मच्चित्तः मत्परः युक्तः आसीत।\n\nदेहः ऋजुः, दृष्टिः नासिकाग्रे स्थिरा, ब्रह्मचर्यव्रतम्, अचलभक्तिः च ध्यानाय आवश्यकानि। एवं समाधिं साधयेत्।\n\nधर्मयुद्धरङ्गे स्थितः अर्जुनः ध्यानविषये किमर्थं प्रश्नितः इति सामान्यप्रश्नः; उत्तरम् — गीतोपदेशः केवलम् अर्जुनार्थं न, सर्वसात्त्विकनरसमुदायार्थम्।",
  "6.15": "युञ्जन्नेवं सदात्मानं योगी नियतमानसः ।\nशान्तिं निर्वाणपरमां मत्संस्थामधिगच्छति ॥\n\nएवं सदा आत्मानं युञ्जन् नियतमानसः योगी मत्संस्थां निर्वाणपरमां शान्तिम् अधिगच्छति।\n\nअत्र यावत् उक्तं तत् मनसा कृतं ध्यानम्। ततः परं तुरीयावस्था — यत्र मनः सम्पूर्णं स्तब्धं भूत्वा जीवस्वरूपं साक्षात् भगवन्तं पश्यति। एतत् जीवस्य साधनापथे प्राप्तव्यः परमानन्दः — भगवत्साक्षात्कारः। तं प्राप्तः पुनः संसारबन्धने न पतति।",
  "6.16": "नात्यश्नतस्तु योगोऽस्ति न चैकान्तमनश्नतः ।\nन चातिस्वप्नशीलस्य जाग्रतो नैव चार्जुन ॥\n\nहे अर्जुन, अतिभोजिनः योगः नास्ति, अभोजिनः अपि नास्ति; अतिनिद्रालोः जागरूकस्य च नास्ति एव।\n\nअतिभोजनेन मनः निस्तेजं भवति; अभोजनेन देहः क्षीयते। भगवत्साक्षात्कारः देहद्वारैव, अतः नियताहारनिद्राभ्यासः आवश्यकः।",
  "6.17": "युक्ताहारविहारस्य युक्तचेष्टस्य कर्मसु ।\nयुक्तस्वप्नावबोधस्य योगो भवति दुःखहा ॥\n\nयुक्ताहारविहारस्य कर्मसु युक्तचेष्टस्य युक्तस्वप्नावबोधस्य योगः दुःखहा भवति।\n\nसात्त्विकाहारः ध्यानपूरकः; मनोविकारकाहारः (यथा लशुनपलाण्डु) त्याज्यः। कार्ये अनालस्यम्, विश्रामे च पूर्णविश्रान्तिः। एवं नियमितजीवनेन दुःखरहितम् आनन्दमयं जीवनं सम्भवति।",
  "6.18": "यदा विनियतं चित्तमात्मन्येवावतिष्ठते ।\nनिःस्पृहः सर्वकामेभ्यो युक्त इत्युच्यते तदा ॥\n\nयदा विनियतं चित्तम् आत्मनि एव अवतिष्ठते, सर्वकामेभ्यः निःस्पृहः भवति, तदा युक्तः इति उच्यते।\n\nयोगाभ्यासेन योगिनः सुप्तप्रज्ञा नियन्त्रिता भवति। पूर्वस्मृतयः त्यक्त्वा योगी अन्तरङ्गसिंहासने केवलं भगवन्तं स्थापयति। तदा बाह्यक्षुद्रकामनाः विलीयन्ते, सः 'ध्यानयोगी' उच्यते।",
  "6.19": "यथा दीपो निवातस्थो नेङ्गते सोपमा स्मृता ।\nयोगिनो यतचित्तस्य युञ्जतो योगमात्मनः ॥\n\nनिवातस्थः दीपः यथा न कम्पते तथा यतचित्तस्य योगिनः आत्मयोगः निश्चलः तिष्ठति।",
  "6.20": "यत्रोपरमते चित्तं निरुद्धं योगसेवया ।\nयत्र चैवात्मनात्मानं पश्यन्नात्मनि तुष्यति ॥२०॥\n\n[एतेषां चतुर्णां श्लोकानां (६.२०, ६.२१, ६.२२, ६.२३) पदच्छेदः अर्थः विवरणं च अग्रिमश्लोके (६.२३) एकत्र दीयते।]",
  "6.21": "सुखमात्यन्तिकं यत्तद्बुद्धिग्राह्यमतीन्द्रियम् ।\nवेत्ति यत्र न चैवायं स्थितश्चलति तत्त्वतः ॥२१॥\n\n[अस्य श्लोकस्य (६.२१) पदच्छेदः अर्थः विवरणं च ६.२०, ६.२२, ६.२३ श्लोकैः सह अग्रिमश्लोके (६.२३) एकत्र दीयते।]",
  "6.22": "यं लब्ध्वा चापरं लाभं मन्यते नाधिकं ततः ।\nयस्मिन्स्थितो न दुःखेन गुरुणापि विचाल्यते ॥२२॥\n\n[अस्य श्लोकस्य (६.२२) पदच्छेदः अर्थः विवरणं च ६.२०, ६.२१, ६.२३ श्लोकैः सह अग्रिमश्लोके (६.२३) एकत्र दीयते।]",
  "6.23": "यत्रोपरमते चित्तं निरुद्धं योगसेवया ।\nयत्र चैवात्मनात्मानं पश्यन्नात्मनि तुष्यति ॥२०॥\nसुखमात्यन्तिकं यत्तद्बुद्धिग्राह्यमतीन्द्रियम् ।\nवेत्ति यत्र न चैवायं स्थितश्चलति तत्त्वतः ॥२१॥\nयं लब्ध्वा चापरं लाभं मन्यते नाधिकं ततः ।\nयस्मिन्स्थितो न दुःखेन गुरुणापि विचाल्यते ॥२२॥\nतं विद्याद्दुःखसंयोगवियोगं योगसञ्ज्ञितम् ।\nस निश्चयेन योक्तव्यो योगोऽनिर्विण्णचेतसा ॥२३॥\n\nयोगसाधनया निरुद्धं चित्तं बाह्यविषयेभ्यः उपरमते; आत्मना एव भगवन्तं पश्यन् आत्मनि तुष्यति; इन्द्रियागोचरम् अतीन्द्रियं परमसुखं वेत्ति; तत्र स्थितः तत्त्वतः न चलति; लब्ध्वा च अपरं लाभं न मन्यते; गुरुणा दुःखेनापि न विचाल्यते। एतत् दुःखसंयोगवियोगं 'योग' इति विद्यात्; सः अनिर्विण्णचेतसा निश्चयेन योक्तव्यः।\n\nआत्मसाक्षात्कारे अपूर्वः आनन्दः जायते। भक्तस्य भगवद्भक्तिः भगवतः च भक्तवात्सल्यम् — एतयोः सङ्गमे 'निर्भयत्वम्'। एषा स्थितिः पूर्णतृप्तिप्रदा। इन्द्रियजन्यानन्दः सापेक्षः इति तत्र ज्ञायते। इदं शनैः शनैः साधनया एव प्राप्यम्, सहसा त्यागेन न।",
  "6.24": "सङ्कल्पप्रभवान्कामांस्त्यक्त्वा सर्वानशेषतः ।\nमनसैवेन्द्रियग्रामं विनियम्य समन्ततः ॥२४॥\n\n[एतयोः श्लोकयोः (६.२४, ६.२५) पदच्छेदः अर्थः विवरणं च अग्रिमश्लोके (६.२५) एकत्र दीयते।]",
  "6.25": "सङ्कल्पप्रभवान्कामांस्त्यक्त्वा सर्वानशेषतः ।\nमनसैवेन्द्रियग्रामं विनियम्य समन्ततः ।\nशनैः शनैरुपरमेद्बुद्ध्या धृतिगृहीतया ।\nआत्मसंस्थं मनः कृत्वा न किञ्चिदपि चिन्तयेत् ॥\n\nसङ्कल्पजान् सर्वान् कामान् अशेषतः त्यक्त्वा, मनसा एव इन्द्रियग्रामं समन्ततः विनियम्य, धृतिगृहीतया बुद्ध्या शनैः शनैः उपरमेत्, आत्मसंस्थं मनः कृत्वा न किञ्चित् अपि चिन्तयेत्।\n\nअस्मत्समस्यानां मूलं सङ्कल्पाः। कर्तव्यम् इति मानसनिर्णयः सङ्कल्पः; सहस्रसङ्कल्पात् सहस्रकामनाः। 'भगवत्सङ्कल्पः यथा तथा मम सङ्कल्पः' इति एकैव सङ्कल्पः धार्यः — यथा माध्वाचार्याः द्वादशस्तोत्रे — 'कुरु भुङ्क्ष्व च कर्म निजं नियतं हरिपादविनम्रधिया सततम्, हरिरेव परो हरिरेव गुरुः हरिरेव जगत्पितृमातृगतिः' इति। इन्द्रियसंयमेन सह धृत्या मनः क्रमेण भगवति स्थापनीयम्।",
  "6.26": "यतो यतो निश्चरति मनश्चञ्चलमस्थिरम् ।\nततस्ततो नियम्यैतदात्मन्येव वशं नयेत् ॥\n\nचञ्चलम् अस्थिरं मनः यतः यतः निश्चरति ततः ततः नियम्य एतत् आत्मनि एव वशं नयेत्।\n\nमनः अतिचञ्चलम्; यत्र यत्र स्खलति तत्र तत्र भगवन्तम् अवरोधं कृत्वा तत् भगवति स्थापनीयम्। अत्र निरन्तरप्रयत्नः अपेक्षितः।",
  "6.27": "प्रशान्तमनसं ह्येनं योगिनं सुखमुत्तमम् ।\nउपैति शान्तरजसं ब्रह्मभूतमकल्मषम् ॥\n\nप्रशान्तमनसं शान्तरजसं ब्रह्मभूतम् अकल्मषम् एनं योगिनम् उत्तमं सुखम् उपैति।\n\nमनसि भगवति स्थिते गोन्दलपूर्णं मनः प्रशान्तं भवति। एषा स्थितिः जीवने प्राप्तव्यं परमानन्दस्थानम्। मनःशुद्धिं विना बाह्यशुद्धिः निरुपयोगा; शुद्धमनसे किमपि अशुचि नास्ति।",
  "6.28": "युञ्जन्नेवं सदात्मानं योगी विगतकल्मषः ।\nसुखेन ब्रह्मसंस्पर्शमत्यन्तं सुखमश्नुते ॥\n\nएवं सदा आत्मानं युञ्जन् विगतकल्मषः योगी सुखेन ब्रह्मसंस्पर्शम् अत्यन्तं सुखम् अश्नुते।\n\n'विगतकल्मषः सन् आत्मानं युञ्जन्' तथा 'आत्मानं युञ्जन् सन् विगतकल्मषः' — द्वयोः अर्थयोः दृश्यते। भगवदनुभूत्यनन्तरम् अपि निरन्तरं तस्यां स्थातव्यम्; तेन साधकः अनायासेन भगवत्साक्षात्काररूपं सुखम् आप्नोति।",
  "6.29": "सर्वभूतस्थमात्मानं सर्वभूतानि चात्मनि ।\nईक्षते योगयुक्तात्मा सर्वत्र समदर्शनः ॥\n\nयोगयुक्तात्मा सर्वभूतस्थम् आत्मानं सर्वभूतानि च आत्मनि ईक्षते, सर्वत्र समदर्शनः।\n\n'सर्वभूतस्थम् आत्मानम्' इति सर्वजीवान्तः बिम्बरूपेण अन्तर्यामी भगवान्; 'सर्वभूतानि च आत्मनि' इति सर्वजीवाः भगवति स्थिताः। भगवान् अस्मान् अन्तः बहिः च पूरयति इति उपासनायां ज्ञातव्यम्। भगवतः अवतारः आवेशः सन्निधानं गुणः कृतिः रूपं च सर्वम् अखण्डम्, एकरूपम्।",
  "6.30": "यो मां पश्यति सर्वत्र सर्वं च मयि पश्यति ।\nतस्याहं न प्रणश्यामि स च मे न प्रणश्यति ॥\n\nयः मां सर्वत्र पश्यति सर्वं च मयि पश्यति तस्य अहं न प्रणश्यामि सः च मे न प्रणश्यति।\n\nएवं मां सर्वत्र सर्वान् मयि च पश्यति यः तस्मै अहं कदापि न इल्लवामि; तस्य योगक्षेमभारः मम एव। एषा भगवतः भक्तपराधीनता।",
  "6.31": "सर्वभूतस्थितं यो मां भजत्येकत्वमास्थितः ।\nसर्वथा वर्तमानोऽपि स योगी मयि वर्तते ॥\n\nएकत्वम् आस्थितः सर्वभूतस्थितं मां यः भजति सः योगी सर्वथा वर्तमानः अपि मयि वर्तते।\n\nसर्वगतं भगवन्तम् एकरूपेण अनुसन्धानं कुर्वन् निरन्तरभक्तः यः सः यत्रकुत्रापि तिष्ठतु, मामेव प्राप्नोति इति निश्चितम्।",
  "6.32": "आत्मौपम्येन सर्वत्र समं पश्यति योऽर्जुन ।\nसुखं वा यदि वा दुःखं स योगी परमो मतः ॥\n\nहे अर्जुन, यः आत्मौपम्येन सर्वत्र सुखं वा दुःखं वा समं पश्यति सः योगी परमः मतः।\n\nयोगिश्रेष्ठः अन्यम् आत्मवत् जानाति; स्वदुःखवत् परदुःखं सत्यं जानाति; परसुखे स्वयशोवत् प्रमोदते। भगवद्भक्तेषु भगवतः विशेषसन्निधानम्; तेषां सुखदुःखयोः स्पन्दनं तदन्तर्यामिनः पूजा भवति।",
  "6.33": "अर्जुन उवाच —\nयो$यं योगस्त्वया प्रोक्तः साम्येन मधुसूदन ।\nएतस्याहं न पश्यामि चञ्चलत्वात्स्थितिं स्थिराम् ॥\n\nहे मधुसूदन, त्वया प्रोक्तं समत्वयोगम् चञ्चलत्वात् मनसः स्थिरां स्थितिं न पश्यामि अहम्।",
  "6.34": "चञ्चलं हि मनः कृष्ण प्रमाथि बलवद्दृढम् ।\nतस्याहं निग्रहं मन्ये वायोरिव सुदुष्करम् ॥\n\nहे कृष्ण, मनः चञ्चलं प्रमाथि बलवत् दृढं च; तस्य निग्रहं वायोः इव सुदुष्करं मन्ये।\n\nमम मनः सदा मां मनयति, अहं तत् न मनये। एतत् प्रश्नं सर्वे पाठकाः स्वान्तः अनुभवन्ति।",
  "6.35": "भगवानुवाच —\nअसंशयं महाबाहो मनो दुर्निग्रहं चलम् ।\nअभ्यासेन तु कौन्तेय वैराग्येण च गृह्यते ॥\n\nहे महाबाहो, असंशयं मनः चलं दुर्निग्रहं च; हे कौन्तेय, अभ्यासेन वैराग्येण च तत् गृह्यते।\n\nवैराग्यम् अर्थात् यत् मनसे न पोषणीयं तत् दूरीकरणम्; अभ्यासः अर्थात् एकाग्रतार्थं निरन्तरप्रयत्नः। एताभ्यां मनोनिग्रहः निश्चितम्।\n\nदृष्टान्तार्थं ग्रीकदेशस्य सॉक्रेटीस-दार्शनिकस्य त्रिस्तरीयचालनी-कथा। कश्चित् परिचितः सॉक्रेटीसाय मित्रविषये अफवाहं वक्तुम् आगतः। सॉक्रेटीसः तं त्रीन् प्रश्नान् पृष्टवान् — किम् इदं सत्यम्, किम् इदं शुभम्, किम् इदम् उपयोगि? त्रिष्वपि उत्तरं 'न' इति आसीत्। तदा सॉक्रेटीसः तं निवारितवान् — असत्यम् अशुभम् अनुपयोगि च वचनं वक्तव्यम् एव न इति।\n\nएतत् शिक्षणीयम् — अनावश्यकविचारे मनः नियोजयितुं पूर्वं त्रिवारं सोसनीयम्। वैराग्येण अभ्यासेन च ध्यानयोगः सुसाध्यः भवति।",
  "6.36": "असंयतात्मना योगो दुष्प्राप इति मे मतिः ।\nवश्यात्मना तु यतता शक्योऽवाप्तुमुपायतः ॥\n\nअसंयतात्मना योगः दुष्प्रापः इति मे मतिः; वश्यात्मना तु यततया उपायतः शक्यः अवाप्तुम्।\n\nआलस्येन कुत्सिताभिलाषेण च यः न प्रयतते तस्मै समाधिः न दुष्यति। वैराग्याभ्यासाभ्यां मनः वशीकृत्य समाधिं साधयितुं शक्यम् इति कृष्णाश्वासः।",
  "6.37": "अर्जुन उवाच —\nअयतिः श्रद्धयोपेतो योगाच्चलितमानसः ।\nअप्राप्य योगसंसिद्धिं कां गतिं कृष्ण गच्छति ॥\n\nहे कृष्ण, श्रद्धायुक्तः अयतिः योगात् चलितमानसः योगसंसिद्धिम् अप्राप्य कां गतिं गच्छति?",
  "6.38": "कच्चिन्नोभयविभ्रष्टश्छिन्नाभ्रमिव नश्यति ।\nअप्रतिष्ठो महाबाहो विमूढो ब्रह्मणः पथि ॥\n\nहे महाबाहो, अप्रतिष्ठः ब्रह्मणः पथि विमूढः सः किं न उभयविभ्रष्टः छिन्नाभ्रम् इव नश्यति?",
  "6.39": "एतन्मे संशयं कृष्ण छेत्तुमर्हस्यशेषतः ।\nत्वदन्यः संशयस्यास्य छेत्ता न ह्युपपद्यते ॥\n\nहे कृष्ण, एतत् मे संशयं त्वम् अशेषतः छेत्तुम् अर्हसि; त्वत् अन्यः अस्य संशयस्य छेत्ता न हि उपपद्यते।\n\nअर्जुनस्य विनम्रा शरणागतिः — भगवान् एकः एव उत्तरं दातुं समर्थः इति।",
  "6.40": "भगवानुवाच —\nपार्थ नैवेह नामुत्र विनाशस्तस्य विद्यते ।\nन हि कल्याणकृत्कश्चिद्दुर्गतिं तात गच्छति ॥\n\nहे पार्थ, तस्य विनाशः न इह न अमुत्र विद्यते; हे तात, कल्याणकृत् कश्चित् दुर्गतिं न गच्छति।\n\nसाधनमार्गे गताः इह अमुत्र वा किमपि न नष्टयन्ति। शुभकृत् कदापि अशुभं न प्राप्नोति — इदं सार्वकालिकं सत्यम्।",
  "6.41": "प्राप्य पुण्यकृतां लोकानुषित्वा शाश्वतीः समाः ।\nशुचीनां श्रीमतां गेहे योगभ्रष्टोऽभिजायते ॥\n\nयोगभ्रष्टः पुण्यकृतां लोकान् प्राप्य शाश्वतीः समाः उषित्वा शुचीनां श्रीमतां गेहे अभिजायते।\n\nसाधनामार्गे मध्ये स्थगितस्यापि साधना कदापि व्यर्था न भवति; देहत्यागानन्तरं पुण्यलोकं प्राप्य, चिरकालं सुखम् अनुभूय, पुनः पृथिव्यां शुचि-श्रीमद्-वेदज्ञ-गृहे जायते।",
  "6.42": "अथवा योगिनामेव कुले भवति धीमताम् ।\nएतद्धि दुर्लभतरं लोके जन्म यदीदृशम् ॥\n\nअथवा धीमतां योगिनाम् एव कुले भवति; ईदृशं जन्म लोके दुर्लभतरम्।\n\nपूर्वजन्मसाधितं सोपानं सुलभं प्राप्य ततः अग्रे साधनां करोति। एतत् अध्यात्मसाधनायाः विशेषः — न किमपि साधनं व्यर्थम्।",
  "6.43": "तत्र तं बुद्धिसंयोगं लभते पौर्वदेहिकम् ।\nयतते च ततो भूयः संसिद्धौ कुरुनन्दन ॥\n\nहे कुरुनन्दन, तत्र पौर्वदेहिकं तं बुद्धिसंयोगं लभते, ततः भूयः संसिद्धौ यतते च।\n\nपूर्वजन्मसाधना सुप्तप्रज्ञायां हुदुगि तदनुगुणवातावरणे जागृता भवति। एतज्जन्मवृद्धिः पूर्वजन्मवृद्ध्याः उत्तरार्धं भवति।",
  "6.44": "पूर्वाभ्यासेन तेनैव ह्रियते ह्यवशोऽपि सः ।\nजिज्ञासुरपि योगस्य शब्दब्रह्मातिवर्तते ॥\n\nपूर्वाभ्यासेन तेन एव सः अवशः अपि ह्रियते; योगस्य जिज्ञासुः अपि शब्दब्रह्म अतिवर्तते।\n\nवेदज्ञगृहे अजातः अपि पूर्वजन्मसाधनाफलेन अनभिज्ञतया साधनां प्रति आकृष्यते। प्रह्लाद-पिङ्गलयोः कथा एतस्य उदाहरणम्।",
  "6.45": "प्रयत्नाद्यतमानस्तु योगी संशुद्धकिल्बिषः ।\nअनेकजन्मसंसिद्धस्ततो याति परां गतिम् ॥\n\nप्रयत्नात् यतमानः योगी संशुद्धकिल्बिषः अनेकजन्मसंसिद्धः ततः परां गतिं याति।\n\nअस्माकं साधना जन्मजन्मान्तरगता। इच्छा जायते, तत्पूर्तये वातावरणं भगवान् ददाति, तत्र प्रयत्नेन कालुष्यं धौतं भवति, ज्ञानं शुद्धं जायते। अनेन ज्ञानसाधनाभ्यां शब्दब्रह्मातीतं भगवन्तं द्रष्टुं शक्यते।",
  "6.46": "तपस्विभ्योऽधिको योगी ज्ञानिभ्योऽपि मतोऽधिकः ।\nकर्मिभ्यश्चाधिको योगी तस्माद्योगी भवार्जुन ॥\n\nतपस्विभ्यः अधिकः योगी, ज्ञानिभ्यः अपि अधिकः मतः, कर्मिभ्यः च अधिकः योगी; तस्मात्, हे अर्जुन, योगी भव।\n\nअन्तरङ्गे एकाग्रतया भगवन्तं ध्यातुं शक्नुवन् तपस्विनः महान्। शास्त्रज्ञमात्रात् ध्यायन् महान्। बाह्यकर्मठात् मानसपूजाकारी योगी महान्। \"There are nowadays professors of philosophy, but not philosophers\" इति थोरो-वचनं स्मर्तव्यम्। अतः जीवने ध्यानयोगी भव, अन्तरङ्गध्याने प्रवृद्ध्यस्व; युद्धमपि तदा भगवत्पूजा भवति इति कृष्णसन्देशः।",
  "6.47": "योगिनामपि सर्वेषां मद्गतेनान्तरात्मना ।\nश्रद्धावान्भजते यो मां स मे युक्ततमो मतः ॥\n\nयोगिनां सर्वेषां मध्ये मत्गतेन अन्तरात्मना श्रद्धावान् यः मां भजते सः मे युक्ततमः मतः।\n\nभगवत्येव मनः स्थापयित्वा ध्यायन् एव सर्वेषु योगिषु श्रेष्ठः। भगवन्तं विहाय अन्यत् ध्यायतः किमपि उपयोगि न। यत्रकुत्रापि प्रतीके भगवन्तम् एव पश्यन् जीवन् एव योगमयं जीवनं करोति।\n\nइति षष्ठोऽध्यायः समाप्तः।\n\nइयता भगवद्गीतायाः प्रथमः षट्कः (प्रथमाध्यायषट्कम्) समाप्तः। अत्र भगवदुपासनाज्ञानं साङ्ख्यं च कृष्णेन विवृतम्। अग्रे भगवदुपासनाविषयः तन्महिमा च वर्ण्यते।",
  "7.1": "[सप्तमाध्यायस्य बन्नञ्जे-पीठिका]\n\nपूर्वेषु षट्सु अध्यायेषु (प्रथमषट्के) कृष्णः साधकस्य साधनारम्भं, कर्मस्वरूपं, ध्यानस्वरूपं च, भगवज्ज्ञानसाधनविषये उक्तवान्। द्वितीयषट्कः (सप्तमात् द्वादशं यावत्) साधनया ज्ञातव्यं भगवतः स्वरूपं विभूतिं वैभवं महिमानं च वर्णयति। अस्मिन् अध्याये कृष्णः स्वबुद्धिसामर्थ्यपर्यन्तं भगवज्ज्ञानोपायं वर्णयति। यज्ज्ञानेन सर्वं ज्ञातं भवति तादृशं विज्ञानम् अत्र दर्शितम्। अष्टधा अक्षरप्रकृतेः सृष्टिः, नादसृष्टिः, सृष्टिक्रियायां चेतनप्रकृतिः श्रीतत्त्वं च तस्य महत्त्वं च कृष्णः अत्र वर्णयति। जले सूर्ये चन्द्रे आकाशे भूमौ अग्नौ आत्मबले वायौ तपसि च कथं भगवद्विभूतिः निहिता इति संक्षेपेण अत्र उक्तम् [विशेषतः दशमाध्याये भगवद्विभूतिः दृश्यते]। त्रिगुणात्मके प्रपञ्चे अस्माकं जीवनं, मायाप्रपञ्चः तस्मात् निर्गमनमार्गः च कृष्णः अत्र वर्णयति। दुष्कृतिनां सुकृतिनां च स्वभावः, तेषु तद्भक्तौ च का श्रेष्ठा, ज्ञानेन भक्त्या च कः मुक्तिं लभते इत्यादि अध्यात्मविज्ञानं अयम् अध्यायः वर्णयति। अयम् अध्यायः भगवतः अमृतवचनेन आरभ्यते।\nश्रीभगवानुवाच। हे पार्थ, मयि आसक्तमनाः सन् मदाश्रयः योगं युञ्जन् असंशयं समग्रं मां यथा ज्ञास्यसि तत् शृणु। मनः प्रथमं वशीकृत्य, दृढभक्त्या निरहङ्कारेण च सम्पूर्णशरणागत्या मयि आत्मानं समर्पयन् ध्यानयोगे प्रवृत्तः पूर्णज्ञानसामर्थ्येन मां जानीयात्।",
  "7.2": "यत् ज्ञानं सह विज्ञानेन अशेषतः ते वक्ष्यामि, यत् ज्ञात्वा अन्यत् किमपि जिज्ञास्यं न अवशिष्यते। यस्मिन् विज्ञाते सर्वम् इदं विज्ञातं भवति इति श्रुतिवचनम्। ज्ञानं यदा विज्ञानरूपं भवति तदैव तत् समग्रं भवति; विशिष्टतया वस्तुनः तलस्पर्शि ज्ञानं विज्ञानम् उच्यते।",
  "7.3": "सहस्रेषु मनुष्याणां कश्चित् एव सिद्ध्यर्थं यतते; यतमानानां सिद्धानाम् अपि कश्चित् एव मां तत्त्वतः वेत्ति। अपरोक्षज्ञानसम्पन्नानाम् अपि मध्ये भगवत्तत्त्वस्य यथार्थवेत्तारः अतीव विरलाः भवन्ति।",
  "7.4": "भूमिः आपः अनलः वायुः खं मनः बुद्धिः अहङ्कारः इति मे इयं जडप्रकृतिः अष्टधा भिन्ना। सृष्टेः पूर्वं सूक्ष्मरूपेण भगवदुदरे स्थितम् इदं जगत् पश्चात् व्यक्तरूपं प्राप्तम्। पञ्चभूतेभ्यः अन्नमयः प्राणमयः मनोमयः विज्ञानमयः च कोशाः क्रमेण उत्पन्नाः। एतत् अष्टविधं प्रकृतिं भगवान् अष्टाक्षरेण ओङ्कारेण च वाच्यः सन् व्याप्नोति।",
  "7.5": "इयं अपरा प्रकृतिः; इतः अन्यां जीवभूतां परां प्रकृतिं विद्धि, यया इदं जगत् धार्यते। जडप्रकृतिः उपादानकारणम्, चित्प्रकृतिः श्रीतत्त्वं च तस्याः सहकारिकारणम्; भगवान् एव उभयोः नियामकः निमित्तकारणं च। जडप्रकृतिः अक्षरा, चित्प्रकृतिः परमाक्षरा, भगवान् तु परतः परमाक्षरः इति त्रयाणां स्वरूपभेदः शाश्वतः।",
  "7.6": "एतयोः प्रकृत्योः योनितः सर्वाणि भूतानि जायन्ते; अहम् एव कृत्स्नस्य जगतः प्रभवः प्रलयः च। जडचित्प्रकृतिद्वारा जगतः उत्पत्तिविनाशयोः मूलकारणं भगवान् एव, न तु चित्प्रकृतिः स्वतन्त्रा।",
  "7.7": "हे धनञ्जय, मत्तः परतरं किञ्चित् अपि न अस्ति; सूत्रे मणिगणाः इव मयि इदं सर्वं प्रोतम्। चित्प्रकृतिः जडप्रकृतिः जीवाः ब्रह्माण्डं च सर्वम् एव भगवति ग्रथितम्।",
  "7.8": "हे कौन्तेय, अप्सु रसः अहम्, शशिसूर्ययोः प्रभा अहम्, सर्ववेदेषु प्रणवः अहम्, खे शब्दः, नृषु पौरुषम् च अहम्। जलस्य रसत्वेन, सूर्यचन्द्रयोः प्रभात्वेन, वेदानां सारभूतेन ओङ्कारेण च भगवान् विभूतिरूपेण प्रविश्य विशिष्टां शक्तिं ददाति। त्रिवेदसारः प्रणवः, प्रणवसारः व्याहृतयः, ताः च गायत्री, सा च ओङ्कारे पर्यवस्यति। ओङ्कारः अकारोकारमकाररूपेण सर्वज्ञत्वं सर्वसामर्थ्यं सर्वगतत्वं च भगवतः द्योतयति; 'नेति नेति' इति श्रुत्या भगवतः अगृह्यत्वम् अपि सूचयति।",
  "7.9": "पृथिव्यां पुण्यः गन्धः, विभावसौ तेजः, सर्वभूतेषु जीवनम्, तपस्विषु तपः च अहम् एव। भूमिदेवतायां गन्धरूपेण, अग्नौ तेजोरूपेण, प्राणे जीवनरूपेण, तपस्विनां मनसि तपःशक्तिरूपेण भगवान् विभूत्या विराजते। अन्नमयकोशात् आनन्दमयकोशं यावत् एतद्द्वयेन श्लोकेन भगवतः विभूतिविज्ञानं वर्णितम्।",
  "7.10": "हे पार्थ, सर्वभूतानां सनातनं बीजं मां विद्धि; बुद्धिमतां बुद्धिः, तेजस्विनां तेजः च अहम्। अव्यक्तस्य अस्य जगतः व्यक्तरूपप्रदाता बीजशब्देन उच्यते, स्वयं तु सर्वदा सनातनः अपरिवर्तितः च तिष्ठति। ज्ञानिनां ज्ञानशक्तिं, तेजस्विनां तेजःशक्तिं च भगवान् एव प्रयच्छति।",
  "7.11": "हे भरतर्षभ, बलवतां कामरागविवर्जितं बलम् अहम्, भूतेषु धर्माविरुद्धः कामः च अहम्। बलहीनेन आत्मा न लभ्यते इति मुण्डकवचनम्; इदं बलं न शारीरं, अपि तु भगवत्कृपासामर्थ्यं आत्मबलं च। धर्मानुकूलः कामः अपि भगवत्प्रसादः एव।",
  "7.12": "ये च सात्त्विकाः रजसाः तामसाः च भावाः, ते मत्तः एव इति विद्धि; न तु अहं तेषु, ते तु मयि। त्रिगुणात्मकम् इदं जगत् सत्त्वरजस्तमोमिश्रितम्; तेषां नियन्ता भगवान् स्वयं त्रिगुणातीतः तिष्ठति।",
  "7.13": "एभिः त्रिभिः गुणमयैः भावैः मोहितम् इदं सर्वं जगत् मां तेभ्यः परम् अव्ययं न अभिजानाति। त्रिगुणव्याप्तं मनः त्रिगुणातीतं ज्ञातुम् असमर्थम् भवति।",
  "7.14": "गुणमयी हि एषा मम दैवी माया दुरत्यया; ये मां एव प्रपद्यन्ते ते एतां मायां तरन्ति। श्रीभूदुर्गारूपा त्रिविधा माया भगवदधीना; तां शरणागत्या एव अतिक्रमितुं शक्यते, न स्वप्रयत्नेन।",
  "7.15": "मायया अपहृतज्ञानाः आसुरभावम् आश्रिताः दुष्कृतिनः नराधमाः मूढाः मां न प्रपद्यन्ते। स्वभावतः दुष्टाः (यथा दुर्योधनः) कदापि न सुधार्याः; प्रारब्धवशात् दुष्कृतिनः (यथा अजामिळः) तु पश्चात्तापेन शुध्यन्ति। भगवान् सर्वापराधसहिष्णुः करुणामूर्तिः।",
  "7.16": "हे अर्जुन, चतुर्विधाः सुकृतिनः जनाः मां भजन्ते -- आर्तः जिज्ञासुः अर्थार्थी ज्ञानी च। एकभक्तिः सर्वदेवतापरिवारसहितस्य भगवतः उपासना, न तु देवतानाम् उपेक्षा।",
  "7.17": "तेषु नित्ययुक्तः एकभक्तिः ज्ञानी विशिष्यते; जानिनः अहम् अत्यर्थं प्रियः, सः च मम प्रियः। निष्कामज्ञानपूर्वकभक्तिः सर्वोत्कृष्टा।",
  "7.18": "उदाराः सर्वे एव एते, ज्ञानी तु मम आत्मा एव इति मतम्; सः हि युक्तात्मा मां एव अनुत्तमां गतिम् आस्थितः। ज्ञानरहिता भक्तिः न पूर्णा भवति; प्रह्लादस्य उदाहरणेन ज्ञानी अर्थार्थी अपि भवितुम् अर्हति इति सूचितम्।",
  "7.19": "बहूनां जन्मनाम् अन्ते ज्ञानवान् मां प्रपद्यते; वासुदेवः सर्वम् इति सः महात्मा सुदुर्लभः। बहुजन्मार्जितं ज्ञानं कदापि न नश्यति; वासुशब्देन आवृतः, देवशब्देन प्रकटितः भगवान् वासुदेवः इति उच्यते।",
  "7.20": "कामैः तैः तैः हृतज्ञानाः स्वप्रकृतिनियताः जनाः तं तं नियमम् आस्थाय अन्यदेवताः प्रपद्यन्ते। जीवस्वभावः प्रकृत्या नियतः केनापि परिवर्तयितुं न शक्यते; अतः सर्वे भगवद्भक्ताः भवितुं न शक्नुवन्ति, तत् सात्त्विकचेतनस्य एव साध्यम्।",
  "7.21": "यः यः भक्तः यां यां तनुं श्रद्धया अर्चितुम् इच्छति, तस्य तस्य अचलां श्रद्धां तां एव विदधामि अहम्। एकशक्तिरूपं भगवन्तं देवतापरिवारसहितं विस्मृत्य केवलैकदेवतायां श्रद्धां दृढीकुर्वन् मनुष्यः तस्याः श्रद्धायाः वेष्टने बध्यते।",
  "7.22": "सः तया श्रद्धया युक्तः तस्याः आराधनम् ईहते, ततः च मया एव विहितान् कामान् लभते। यत् किमपि देवतां प्रति कृतं नमस्कारं केशवः एव प्रतिगच्छति; ज्ञानपूर्वकं कृतं शाश्वतं फलं ददाति, अज्ञानेन कृतं तु अल्पं क्षणिकं च।",
  "7.23": "अल्पचेतसां तत् फलम् अन्तवत् एव भवति; देवयजः देवान् यान्ति, मद्भक्ताः तु मां एव यान्ति। देवतां भजतां प्राप्तं फलं क्षणिकम्, न तु शाश्वतमोक्षप्रदम्। भगवान् स्तुतिं न इच्छति, सत्यज्ञानम् एव प्रीणाति।",
  "7.24": "अव्यक्तं मां व्यक्तिम् आपन्नम् इति अबुद्धयः मम परमम् अव्ययम् अनुत्तमं भावम् अजानन्तः मन्यन्ते। पञ्चभौतिकशरीररहितः नित्यम् अव्यक्तः भगवान् स्वेच्छया अवतारे व्यक्तरूपेण दृश्यते; तं शरीरबद्धं मन्यमानाः बुद्धिशून्याः एव।",
  "7.25": "योगमायासमावृतः अहं सर्वस्य न प्रकाशः; अजम् अव्ययं मां मूढः अयं लोकः न अभिजानाति। अनन्तगुणस्य भगवतः पूर्णचित्रं परिच्छिन्नबुद्धिः ग्रहीतुं न शक्नोति; अज्ञानमायापटलेन आवृतः जीवः तं न पश्यति।",
  "7.26": "हे अर्जुन, समतीतानि वर्तमानानि भविष्याणि च भूतानि अहं वेद; मां तु न कश्चन वेद। भूतशब्दः पञ्चभूतानि ब्रह्माण्डानि जीवजातानि च सर्वाणि व्याप्नोति; तेषां स्वामी भगवान् एकः एव पूर्णज्ञानी।",
  "7.27": "हे भारत परन्तप, इच्छाद्वेषसमुत्थेन द्वन्द्वमोहेन सर्वभूतानि सर्गे सम्मोहं यान्ति। जन्मत एव इच्छाद्वेषौ वर्धमानौ सत्यासत्यविवेकं नाशयतः; स्वबुद्धिम् एव श्रेष्ठाम् मन्यमानः जनः सम्मोहम् एव प्राप्नोति।",
  "7.28": "येषां पुण्यकर्मणां जनानाम् अन्तगतं पापं, ते द्वन्द्वमोहनिर्मुक्ताः दृढव्रताः मां भजन्ते। पश्चात्तापात् परं प्रायश्चित्तं न अस्ति; पापबोधेन उत्पन्नः पश्चात्तापः एव मनुष्यं पुनः सन्मार्गे स्थापयति।",
  "7.29": "जरामरणमोक्षाय मां आश्रित्य ये यतन्ते, ते कृत्स्नं तत् ब्रह्म अध्यात्मं कर्म च अखिलं विदुः। बलिचक्रवर्तिनः त्रिपादाख्यानेन उपासनायाः त्रयः क्रमाः सूचिताः -- मूर्तिपूजा, सर्वव्यापिशक्तिज्ञानम्, अन्तर्यामिस्वरूपे आत्मार्पणं च।",
  "7.30": "साधिभूताधिदैवं मां साधियज्ञं च ये विदुः, प्रयाणकाले अपि च मां ते विदुः युक्तचेतसः। अधिभूतम् अधिदैवम् अधियज्ञं ब्रह्मसाक्षात्कारं कर्मरहस्यं च इति षड्विधं ज्ञानं मरणकाले अपि दृढं तिष्ठेत्; तदेव अग्रिमजन्मनः निर्णायकम्। इति सप्तमोऽध्यायः।",
  "8.1": "[अष्टमाध्यायस्य बन्नञ्जे-पीठिका]\n\nसप्तमाध्यायान्ते कृष्णः संक्षेपेण उक्तवान् यत् मनुष्येण षट् महत्त्वपूर्णानि तत्त्वानि ज्ञातव्यानि इति। अधिभूतम्, अध्यात्मम्, अधिदैवम्, अधियज्ञः, ब्रह्म, कर्म च -- एतानि षट् तत्त्वानि ज्ञात्वा तस्मात् परं किमपि उन्नयनसोपानं न अवशिष्यते इति कृष्णस्य वचनम्।\nअधिभूतम् नाम भौतिकं जगत्; अध्यात्मम् नाम जडे अन्तर्हितं चेतनम्; अधिदैवम् नाम तत् चेतनं नियन्त्रयन्तः देवाः; अधियज्ञः नाम देवान् नियन्त्रयन् भगवान्। एषः अधियज्ञः सर्वस्मिन् जगति व्याप्तः -- इयमेव ब्रह्मकल्पना -- तेन एव सर्वाः क्रियाः प्रवर्तन्ते, सः एव सूत्रधारः। इयं जागृतिः मरणकाले अपि जागरूका भवेत्, तदा तत् मरणं मङ्गलं भवति। एतावत् पूर्वाध्याये दृष्टम्।\n\nसप्तमाध्यायस्य अन्तिमश्लोकद्वये सूक्ष्मदृष्ट्या पश्यामः चेत्, कृष्णः तत्र 'तद् ब्रह्म' इति, अन्ते च 'मां प्राप्नुवन्ति' इति उक्तवान्। अतः कृष्णः ब्रह्मतत्त्वं च भिन्नौ किम् इति सन्देहः जायते। अत्र कृष्णेन प्रयुक्तानि पदानि पश्यामः चेत् तेषु बहवः अर्थाः दृश्यन्ते -- यथा 'ब्रह्म' शब्दस्य संस्कृते अनेके अर्थाः सन्ति: जीवः, चतुर्मुखब्रह्मा, श्रीतत्त्वम्, भगवान्, वेदाः च। 'अध्यात्म' इत्यत्र 'आत्मन्' शब्दस्य शरीरं, मनः, जीवः, परमात्मा इत्यादयः अर्थाः। 'कर्म' इत्यत्र प्रारब्धकर्म कर्तव्यकर्म च द्वौ अर्थौ। 'अधिभूत' इत्यत्र 'भूत' शब्दस्य जडं चेतनं च द्वौ अर्थौ। तथैव 'अधिदैव' नाम देवेषु अधिकः, देवसम्बद्धं च। एवं षडपि शब्दाः भिन्नेषु सन्दर्भेषु भिन्नान् आयामान् उद्घाटयन्ति; अतः कृष्णोक्तानि एतानि षट् तत्त्वानि स्पष्टतया अवगन्तुं कठिनम्।\n\nअन्तिमश्लोके कृष्णः उक्तवान् -- 'जीवनयात्रायाः अन्त्यक्षणे इयं जागृतिः स्थिरा भवेत्' इति। तत् कथं शक्यम्? देहत्यागसमये मानसं चिन्तनं कीदृशं भवेत्? देहत्यागानन्तरं जीवः कं मार्गं गच्छति? इत्यादयः प्रश्नाः अस्मान् पीडयन्ति। अष्टमः अध्यायः अस्माकं सर्वेषां प्रतिनिधिः अर्जुनः इमम् एव प्रश्नं श्रीकृष्णं पृच्छता आरभ्यते।\n\nअर्जुनः उवाच। हे पुरुषोत्तम, तत् ब्रह्म किम्? अध्यात्मं किम्? कर्म च किम्? अधिभूतं कथम्, अधिदैवं च कथम् उच्यते? इति पृष्टवान् अर्जुनः। 'पुरुषोत्तम' इति सम्बोधनेन क्षराक्षरातीतं भगवन्तम् एव ज्ञातुम् इच्छति स्म अर्जुनः।",
  "8.2": "हे मधुसूदन, अस्मिन् देहे अधियज्ञः कः, कथं च? प्रयाणकाले नियतात्मभिः त्वं कथं ज्ञेयः? इति। 'मधुसूदन' इति सम्बोधनेन सत्पुरुषाणाम् आनन्दप्रदः, दुर्जनानां च आनन्दनाशकः भगवान् एव अधियज्ञ इति अर्जुनस्य भावः सूचितः। स्वजीवनयात्रायाः अन्त्यकाले देहनिर्गमनप्रकारं ज्ञातुम् अर्जुनः इच्छति।",
  "8.3": "श्रीभगवान् उवाच। परमम् अक्षरं ब्रह्म; जीवस्वरूपं तदीयं पिण्डाण्डं च अध्यात्मम् उच्यते; भूतभावोद्भवकारि सृष्टिव्यापारं कर्म इति संज्ञातम्। 'स्वभावः' इति जीवस्य निजस्वरूपम्; भगवज्ज्ञानात् पूर्वम् आत्मस्वरूपज्ञानम् आवश्यकम्। सूक्ष्मः जीवः हृत्कमलमध्ये अनाहतचक्रे वसति, दीपवत् अल्पोऽपि सर्वं देहं व्याप्नोति। जगतः सृष्टिकारणभूता भगवतः क्रिया एव यथार्थं कर्म; सर्वे वयं तस्य सूत्रधारस्य पुत्तलिकाः इव; अतः अहंकारः निरर्थकः। द्वितीयदृष्ट्या ब्रह्म-स्वभाव-कर्म त्रयम् अपि भगवत एव बोधकम्; तस्य स्वातन्त्र्यं निष्पक्षपातत्वं त्रिगुणातीतत्वं च एव अध्यात्मम्।",
  "8.4": "क्षरः भावः, देहभृतां समष्टिः, अधिभूतम् उच्यते; शरीरनियामकाः तत्त्वाभिमानिदेवताः, 'पुरुष' इत्याख्यं श्रीतत्त्वं च अधिदैवतम्। अस्मिन् देहे अहम् एव अधियज्ञः, यज्ञस्य भोक्ता कर्ता फलप्रदः च। शरीरपुरुषः छन्दःपुरुषः वेदपुरुषः संवत्सरपुरुषः च चत्वारः पुरुषाः देहे सन्ति, ये जीवस्य साधनामार्गे सहायकाः। द्वितीयदृष्ट्या ब्रह्मादिसमस्तदेवताः, चेतनाचेतनात्मकं जगत् च अधिभूतम्; ब्रह्मादीनां जननी श्रीशक्तिः अधिदैवम्; सर्वान्तर्यामी नियामकः भगवान् एव अधियज्ञः।",
  "8.5": "अन्तकाले मामेव स्मरन् यः देहं त्यक्त्वा प्रयाति, सः मद्भावम् एव याति, नात्र संशयः। ज्ञानानन्दस्वरूपः भूत्वा मयि एव निवसति, पुनः अज्ञानदुःखमये संसारे न पतति। 'अन्तकालः' इति देहत्यागस्य अन्तिमक्षणः, न जरा। तादृशः चेतनः महत् ज्योतिः पश्यन् मोक्षम् एव प्राप्नोति। [जीवस्य देहनिर्गमनानुभवं संगृह्य लिखितः 'Life After Life' इति ग्रन्थः अत्र प्रकाशं ददाति।]",
  "8.6": "यं यं भावं स्मरन् देहान्ते त्यजति, कौन्तेय, तम् एव भावं प्राप्नोति सदा तद्भावभावितः। अतः अन्त्यकाले या स्मृतिः उदेति सा एव अग्रिमजन्मनः निर्णायिका। भरतस्य कथा एतत् स्पष्टीकरोति -- मृगशावकासक्तत्वात् सः अन्त्यकाले मृगमेव स्मृत्वा मृगत्वेन जातः। भीष्माचार्यस्य अपि अन्त्यकाले स्वबाणविद्धः रुधिरस्रावी कृष्णः एव दृष्टः, न आनन्दस्वरूपः भगवान्। तस्मात् जीवनपर्यन्तं भगवद्भावनया चित्तं भावयितव्यम्, न कस्यापि द्वेषेण कलुषितम्; द्वेषः स्वयम् एव अधःपातकारी।",
  "8.7": "तस्मात् सर्वकालेषु माम् अनुस्मर युध्य च। मयि अर्पितमनोबुद्धिः त्वं निःसंशयं मामेव प्राप्स्यसि। सर्वकर्मसु \"भगवान् एव मया कारयति\" इति भावः युद्धमपि पूजारूपं करोति। भावशुद्धिः एव श्रेष्ठा -- धर्मव्याधस्य दृष्टान्तः एतत् सूचयति, यः मांसविक्रयेणापि शुद्धानुसन्धानात् ऋषितुल्यः अभवत्।",
  "8.8": "हे पार्थ, अभ्यासयोगयुक्तेन चेतसा अनन्यगामिना परमं दिव्यं पुरुषम् अनुचिन्तयन् याति। मनसः अभ्यासः एव चित्तवशीकरणस्य एकमात्रं साधनम्; निरन्तराभ्यासेन एव मनः भगवति स्थिरं भवति, अन्त्यकालेऽपि तम् एव पश्यति। इयम् अनुचिन्तना, न केवलं चिन्तनम्, श्रुत्यनुसारेण यथार्थभगवद्ध्यानम् इति उच्यते। 'दिव्य' इति शब्दस्य द्युतिः विजिगीषा कान्तिः स्तुतिः व्यवहारः क्रीडा गतिः इति सप्त अर्था वर्तन्ते, सर्वे अपि भगवत्येव सङ्गच्छन्ते।",
  "8.9": "कविं पुराणम् अनुशासितारम्, अणोः अणीयांसं सर्वस्य धातारम्, अचिन्त्यरूपम् आदित्यवर्णं तमसः परस्तात् यः अनुस्मरेत् सः तम् एव प्राप्नोति। 'कविः' इति सर्वज्ञत्वम्, 'पुराणः' इति सनातनत्वम्, 'अनुशासिता' इति सर्वनियन्ता इति भगवतः त्रीणि रूपाणि अत्र अनुसन्धेयानि। अणोः अणीयान् भगवान् जीवान्तरे अपि तिष्ठति, सर्वं धारयति पुष्णाति च। तस्य रूपं वाङ्मनसागोचरम्, उदयादित्यसदृशं त्रिगुणातीतम् अप्राकृतवर्णं च। एवं भगवन्तं ज्ञात्वा निरन्तरं ध्यायन् देहत्यागकाले तमेव स्मृत्वा तम् एव प्राप्नोति।",
  "8.10": "प्रयाणकाले अचलेन मनसा भक्त्या योगबलेन च युक्तः भ्रुवोः मध्ये प्राणम् सम्यक् आवेश्य सः तं परं दिव्यं पुरुषम् उपैति। एषः हठयोगमार्गः अतिकठिनः -- आसनप्राणायामाभ्यां स्थिरं देहं साधयित्वा प्रत्याहारेण दोषान् निरस्य एकाग्रतां प्राप्य हृत्कमलस्थं जीवं विशुद्धिचक्रद्वारा भ्रूमध्ये आजाचक्रे स्थापयितव्यम्। ततः सहस्रारद्वारेण ब्रह्मरन्ध्रमार्गेण निर्गतः जीवः भगवन्तं सीधम् एव प्राप्नोति। अस्मिन् मार्गे अनन्यभक्तिः अत्यावश्यका; उचितमार्गदर्शनं विना हठयोगाभ्यासः अपायकरः।",
  "8.11": "यत् अक्षरं वेदविदः वदन्ति, यत् वीतरागाः यतयः विशन्ति, यत् इच्छन्तः ब्रह्मचर्यं चरन्ति, तत् पदं संग्रहेण प्रवक्ष्ये। 'अक्षरम्' इति ओङ्कारप्रतिपाद्यं सर्वशब्दवाच्यं भगवत्तत्त्वम्। 'ब्रह्मचर्यम्' इति न दैहिकसंयमः, अपि तु 'ब्रह्मणि चरणम्' -- भगवति मनसः स्थिरनिवासः। एतत् मोक्षप्रापकं प्रक्रियां कृष्णः अग्रे विवृणोति।",
  "8.12": "सर्वद्वाराणि संयम्य मनो हृदि निरुध्य च। मूर्ध्न्याधायात्मनः प्राणम् आस्थितो योगधारणाम् ॥१२॥\n\n[एतयोः श्लोकयोः (८.१२ तथा ८.१३) पदच्छेदः अर्थः व्याख्या च एकत्र अग्रिमे श्लोके (८.१३) दीयते।]",
  "8.13": "ओमित्येकाक्षरं ब्रह्म व्याहरन् मामनुस्मरन् । यः प्रयाति त्यजन् देहं स याति परमां गतिम् -- सर्वाणि नाडीद्वाराणि संयम्य, मनः भगवत्येव निरुध्य, प्राणं मूर्ध्नि स्थापयित्वा, ओङ्कारवाच्यं परतत्त्वं कीर्तयन् मां स्मरन्, यः देहं त्यक्त्वा सहस्रारद्वारेण उत्क्रामति, सः पुनरावृत्तिरहितं मोक्षस्थानं याति। एषः साधनामार्गः केवलं हठयोगिनां साध्यः, अतिकठिनः च; अतः अग्रिमे श्लोके कृष्णः सुलभतरं मार्गं वदति।",
  "8.14": "हे पार्थ, यः अनन्यचेताः सततं नित्यशः मां स्मरति, तस्य नित्ययुक्तस्य योगिनः अहं सुलभः। निरन्तरसाधनया साधनान्तं प्राप्तः साधकः अनायासेन एव भगवन्तं प्राप्नोति।",
  "8.15": "माम् उपेत्य पुनर्जन्म दुःखालयम् अशाश्वतं महात्मानः संसिद्धिं परमां गताः न आप्नुवन्ति। साधनया सिद्धिं प्राप्य भगवन्तं गताः जीवाः पुनः अस्मिन् दुःखमये अशाश्वते संसारे न जायन्ते। भगवत्साक्षात्कार एव जीवनसाधनायाः सर्वश्रेष्ठा सिद्धिः।",
  "8.16": "हे अर्जुन, आब्रह्मभुवनात् लोकाः पुनरावर्तिनः; हे कौन्तेय, माम् उपेत्य तु पुनर्जन्म न विद्यते। ब्रह्मलोकादारभ्य सर्वेषां लोकानां नाशः एकदा भवति। चतुर्मुखब्रह्मणः आयुः ३१,१०४ सहस्रकोटिवर्षाणि, तदपि भगवतः एकदिनमात्रम्। भगवान् कालातीतः; अतः तम् एव प्राप्य पुनर्जन्म न विद्यते।",
  "8.17": "सहस्रयुगपर्यन्तम् अहः यत् ब्रह्मणः विदुः, रात्रिं युगसहस्रान्तां ते अहोरात्रविदः जनाः। भगवतः सृष्टिकालः 'अहः', प्रलयकालः 'रात्रिः' इति उच्यते। चतुर्युगं मिलित्वा एकं युगचक्रम् -- कलियुगं ४,३२,००० वर्षाणि, द्वापरं ८,६४,००० वर्षाणि, त्रेता १२,९६,००० वर्षाणि, कृतं १७,२८,००० वर्षाणि -- सर्वं मिलित्वा ४३,२०,००० वर्षाणि। सहस्रयुगचक्राणि ब्रह्मणः एकम् अहः, अर्थात् ४३२ कोटिवर्षाणि; अहोरात्रं ८६४ कोटिवर्षाणि। ब्रह्मणः आयुः शतवर्षम्, अर्थात् ३१,१०४ सहस्रकोटिवर्षाणि -- एषः सृष्टिकालः, ततः तावदेव महाप्रलयकालः। प्रलयाः त्रिविधाः -- मन्वन्तरप्रलयः, दिनप्रलयः, महाप्रलयः च।",
  "8.18": "अव्यक्तात् व्यक्तयः सर्वाः अहरागमे प्रभवन्ति, रात्र्यागमे तत्रैव अव्यक्तसंज्ञके प्रलीयन्ते। महाप्रलयकाले अव्यक्ते भगवति व्यक्तं जगत् परमाणुरूपेण लीयते; पुनः सृष्टिकाले सूक्ष्मरूपात् स्थूलरूपं प्राप्य व्यज्यते।",
  "8.19": "हे पार्थ, भूतग्रामः सः एव अयं भूत्वा भूत्वा प्रलीयते रात्र्यागमे अवशः, अहरागमे प्रभवति। सृष्टेः मूलद्रव्यं न कदापि परिवर्तते; तान्येव पञ्चभूतानि पुनः पुनः सृष्टिसंहारचक्रे भ्रमन्ति। मोक्षायोग्याः अनन्ताः जीवाः अस्मिन् चक्रे भ्रमन्ति; भगवत्प्राप्ताः तु अतीताः।",
  "8.20": "परः तस्मात् तु भावः अन्यः अव्यक्तः अव्यक्तात् सनातनः, यः सः सर्वेषु भूतेषु नश्यत्सु न विनश्यति। सर्वातीतः भगवान् एव विलक्षणः श्रेष्ठः सनातनः, सर्ववेदप्रतिपाद्यः, समस्तचराचरात्मकप्रपञ्चनाशेऽपि अविनाशी, सर्वं स्वस्मिन् लीनं कुर्वन् तिष्ठति।",
  "8.21": "अव्यक्तः अक्षरः इति उक्तः तम् आहुः परमां गतिम्, यं प्राप्य न निवर्तन्ते तद्धाम परमं मम। एतत् अव्यक्ततत्त्वम् एव सर्वेषां गन्तव्यं परमं स्थानम्, 'अक्षर' शब्दस्य मुख्यार्थः -- अविनाशी सर्वव्यापी सर्वेप्सितप्रदः सर्वसमर्थः इन्द्रियानुभवप्रदः सर्वशब्दवाच्यः भगवान्। तं प्राप्य पुनः संसारे न जायते।\n\nपुरुषः स परः पार्थ भक्त्या लभ्यस्त्वनन्यया --",
  "8.22": "यस्यान्तःस्थानि भूतानि येन सर्वमिदं ततम् -- हे पार्थ, यस्मिन् परमे पुरुषे सर्वाणि भूतानि निवसन्ति, येन च इदं सर्वं जगत् व्याप्तम्, सः परमः पुरुषः अनन्यया भक्त्या एव लभ्यते। 'अनन्यया भक्त्या' इति एषः एकः एव मार्गः। एतत् ध्यानयोगाध्यायस्य परमं निगमनम्।",
  "8.23": "हे भरतर्षभ, यत्र काले तु अनावृत्तिम् आवृत्तिं च एव योगिनः प्रयाताः यान्ति तं कालं वक्ष्यामि। शरीरं त्यक्त्वा गतस्य जीवस्य याः देवताः नियमनं कृत्वा पुरतः नयन्ति, याभिः मार्गैः गताः पुनः भूमौ जायन्ते, याभिः च साक्षात् मोक्षं प्राप्नुवन्ति, तत् वक्ष्यामि। अत्र 'कालः' इति शब्दः समयवाची न, अपि तु देहत्यक्तजीवनियामकदेवतागणवाची।",
  "8.24": "अग्निः ज्योतिः अहः शुक्लः षण्मासाः उत्तरायणम् -- एतत् मार्गेण गताः ब्रह्मविदः जनाः ब्रह्म गच्छन्ति, न निवर्तन्ते। वैश्वानरपुत्रौ अग्निज्योतिषौ प्रथमं जीवं स्वागतयतः, ततः अहर्मध्याह्नदेवते, ततः शुक्लपक्षपूर्णिमादेवते, ततः संक्रान्त्युत्तरायणषण्मासदेवताः जीवं भगवत्समीपं प्रापयन्ति।",
  "8.25": "धूमः रात्रिः तथा कृष्णः षण्मासा दक्षिणायनम् -- एतत् मार्गेण गतः योगी चान्द्रमसं ज्योतिः प्राप्य निवर्तते। मोक्षायोग्यः जीवः धूमान्धकारदेवताभ्यां स्वागतितः, ततः कृष्णपक्षदेवतया, ततः दक्षिणायनषण्मासदेवताभिः सोमलोकं प्राप्नोति। तत्र पुण्यक्षयपर्यन्तं सुखम् अनुभूय पुनः मेघं प्राप्य वृष्ट्या भूमिं प्राप्य पुरुषदेहद्वारा स्त्रीगर्भं प्रविश्य पुनः भूमौ जायते।",
  "8.26": "शुक्लकृष्णे गती हि एते जगतः शाश्वते मते। एकया याति अनावृत्तिम्, अन्यया आवर्तते पुनः। एषा शुक्ला ज्योतिर्मार्गः मोक्षप्रदा, कृष्णा अन्धकारमार्गः पुनरावृत्तिप्रदा च अनादिकालतः सर्वजीवेभ्यः समानरूपेण व्यवस्थिता।",
  "8.27": "हे पार्थ, न एते सृती जानन् योगी मुह्यति कश्चन। तस्मात् सर्वेषु कालेषु योगयुक्तः भव अर्जुन। उभयोः मार्गयोः यथार्थज्ञानेन स्वगन्तव्यमार्गं ज्ञात्वा तदभिमानिदेवताभिः सह गन्तव्यम्; अतः अन्त्यकाले मार्गाभिमानिदेवतानुसन्धानम् अत्यावश्यकम्।",
  "8.28": "वेदेषु यज्ञेषु तपःसु च एव दानेषु यत् पुण्यफलं प्रदिष्टम्, अत्येति तत् सर्वम् इदं विदित्वा योगी परं स्थानम् उपैति च आद्यम्। सर्वशास्त्रोक्तं यज्ञदानतपःपुण्यफलम् अतिक्रम्य अन्त्यकालरहस्यज्ञानम् एव सर्वश्रेष्ठम्; अतः जीवनात् अधिकं मरणस्य चिन्तनम् आवश्यकम्। मृत्युः न अमङ्गलम्, अपि तु स्थूलशरीरात् मुक्तिः -- पिञ्जरात् निर्गत्य आकाशे उड्डीयमानः पक्षी इव। अतः मृत्युभयं त्यक्त्वा अन्त्यक्षणे मङ्गलदेवतानुसन्धानं नित्यं जीवने स्थास्यताम्।\n\nइति अष्टमोऽध्यायः।",
  "9.1": "श्रीभगवान् उवाच। इदं तु ते गुह्यतमं ज्ञानं विज्ञानसहितं प्रवक्ष्यामि अनसूयवे, यत् ज्ञात्वा अशुभात् मोक्ष्यसे। एतत् अनन्यभक्तानाम् एव वाच्यम्, न सर्वेषाम्। अत्र 'अनसूया' इति अहङ्काररहितत्वम् अभिप्रेतम्; वेदान्ताध्ययनात् पूर्वं अहङ्कारः त्याज्यः, अन्यथा ज्ञानाहङ्कारः सर्वाहङ्कारेभ्यः अपायकरः। शुद्धचित्ते एव भगवद्दर्शनं भवति; लिङ्गसूक्ष्मस्थूलशरीरत्रयम् अपास्य स्वरूपभूतया स्थित्या भगवत्समीपे स्थानम् एव 'मोक्षः'।",
  "9.2": "राजविद्या राजगुह्यं पवित्रम् इदम् उत्तमम् । प्रत्यक्षावगमं धर्म्यं सुसुखं कर्तुम् अव्ययम् -- एषा विद्या सर्वविद्यासु प्रधाना, अतिरहस्या परमपवित्रा च। इन्द्रियनियामकं भगवन्तं साक्षात् विषयीकरोति; ज्ञानप्रियाय भगवते अन्यमार्गापेक्षया सुलभा; अतः इयं ज्ञानमार्गः कदापि निष्फला न भवति।",
  "9.3": "अश्रद्दधानाः पुरुषाः धर्मस्यास्य परन्तप । अप्राप्य मां निवर्तन्ते मृत्युसंसारवर्त्मनि -- यस्य श्रद्धा नास्ति तस्य उपदेशः निष्फलः। \"मया अज्ञातम् अपि किञ्चित् अस्ति\" इति ज्ञानं श्रद्धायाः प्रथमसोपानम्। भगवति अश्रद्दधानाः तमसि संसारचक्रे वा भ्रमन्ति। 'परन्तप' इति अन्तः अज्ञानकामक्रोधादिशत्रून् दहतीति साधकस्य आदर्शः।",
  "9.4": "मया ततम् इदं सर्वं जगत् अव्यक्तमूर्तिना । मत्स्थानि सर्वभूतानि न चाहं तेषु अवस्थितः -- अहम् अव्यक्तः आकाशवत् सर्वव्यापी, तथापि ज्ञानानन्दमयी मूर्तिः सर्वेषु पूर्णा। प्रतिवस्तु आधारभूतः अहम्, सर्वं मां आश्रित्य तिष्ठति, अहं तु निरालम्बः सर्वत्र व्याप्तः।",
  "9.5": "न च मत्स्थानि भूतानि पश्य मे योगम् ऐश्वरम् । भूतभृन्न च भूतस्थो मम आत्मा भूतभावनः -- सर्वं मयि, न च किमपि मयि -- इति अचिन्त्यशक्तेः अनुसन्धानम्। ममकाररहितत्वम् एव भगवतः निर्लिप्तता। भूतभृत् सन् अपि न भूतभृत्, भूतस्थः सन् अपि न भूतस्थः -- इति विरुद्धधर्माश्रयः भगवत्येव संगच्छते। सृष्टिस्थितिसंहारादि सर्वं भगवत एव, तस्य स्वरूपं क्रिया च अखण्डम्।",
  "9.6": "यथाकाशस्थितो नित्यं वायुः सर्वत्रगो महान् । तथा सर्वाणि भूतानि मत्स्थानीति उपधारय -- वायुः सर्वत्र अन्तः बहिः च वर्तते, अदृश्यः सन्नपि आकाशं व्याप्नोति। तथैव भगवान् अस्मासु अन्तः बहिः च पूर्णः, तथापि निर्लिप्तः। जगतः सर्वास्तित्वं भगवत्येव।",
  "9.7": "सर्वभूतानि कौन्तेय प्रकृतिं यान्ति मामिकाम् । कल्पक्षये पुनस्तानि कल्पादौ विसृजाम्यहम् -- सृष्ट्यनन्तरं ३१,१०४ सहस्रकोटिवर्षेषु महाप्रलयः, चतुर्मुखब्रह्मणः शतवर्षम् -- कल्पक्षयः। तत्र सत्यलोकादिकं सूक्ष्मरूपेण भगवदधीनां प्रकृतिं याति; पुनः तावन्त्येव वर्षाणि प्रलयकालः; ततः पुनः सूक्ष्मात् स्थूलं जायते।",
  "9.8": "प्रकृतिं स्वाम् अवष्टभ्य विसृजामि पुनःपुनः । भूतग्राममिमं कृत्स्नम् अवशं प्रकृतेर्वशात् -- प्रलये सूक्ष्मरूपेण मयि लीनं जडं जीवं च स्वाधीनया प्रकृत्या पुनः सृजामि। एषः सृष्टिसंहारचक्रः नित्यः, अनन्तब्रह्माण्डेषु अनवरतः। अतः भगवान् अनन्तकोटिब्रह्माण्डनायकः इत्युच्यते। एवं निरन्तरं सृजतः संहरतश्च भगवतः कर्म न लिप्यते इति अग्रे द्रष्टव्यम्।",
  "9.9": "न च मां तानि कर्माणि निबध्नन्ति धनञ्जय । उदासीनवदासीनम् असक्तं तेषु कर्मसु -- स्वतन्त्रं भगवन्तं कर्म न बध्नाति; \"न मया मत्कृते किमपि क्रियते\" इति स्पष्टं वदति कृष्णः। 'धनञ्जय' इति सत्पुरुषार्जितधनं प्रजाहितार्थं विनियोजयति यः सः; आध्यात्मिकदृष्ट्या भगवज्ज्ञानम् एव नित्यं धनम्, तत्प्राप्तः एव धनञ्जयः।",
  "9.10": "मयाध्यक्षेण प्रकृतिः सूयते सचराचरम् । हेतुनानेन कौन्तेय जगद्विपरिवर्तते -- जडप्रकृतिः सृष्टेः मूलद्रव्यम्, तस्यै आकारदात्री चेतनप्रकृतिः लक्ष्मीः। भगवान् सृष्टेः अध्यक्षः सन् जडचेतनप्रकृतिद्वारा एतत् सृजति। प्रतिवस्तु विशिष्टशक्त्या भगवान् एव पूर्णः।",
  "9.11": "अवजानन्ति मां मूढाः मानुषीं तनुम् आश्रितम् । परं भावमजानन्तो मम भूतमहेश्वरम् -- भगवतः पाञ्चभौतिकं शरीरं नास्ति; अवतारे मानुषदेहवत् दृश्यते इति मात्रम्। तं नश्वरशरीरं मन्यमानाः तामसाः भगवन्महिमानभिज्ञाः मूढाः। 'भूतमहेश्वरः' इति सर्वभूतेभ्यः महत्तमः, लक्ष्मीपतिः, कालदेशगुणपरिपूर्णः सर्वसमर्थः ईश्वरः इति बहुधा व्याख्येयम्।",
  "9.12": "मोघाशा मोघकर्माणो मोघज्ञाना विचेतसः । राक्षसीमासुरीं चैव प्रकृतिं मोहिनीं श्रिताः -- ये भगवन्तं नश्वरशरीरवन्तं मन्यन्ते ते तामसाः, तेषां सर्वाध्यात्मिकाशा निष्फला। रक्षोरूपाः स्वभावतः तामसाः, आसुराः राजसाः इन्द्रियभोगपरायणाः; उभयेऽपि चिन्तनाशक्तिरहिताः सत्याद्विमुखाः।",
  "9.13": "महात्मानस्तु मां पार्थ दैवीं प्रकृतिमाश्रिताः । भजन्त्यनन्यमनसो ज्ञात्वा भूतादिमव्ययम् -- दैवीस्वभावाः ज्ञानप्रकाशसत्यमार्गगामिनः भगवद्भाग्यभाजः महात्मानः इत्युच्यन्ते। ते अनन्यमनसा भजन्ते; भगवदतिरिक्तं सर्वं नश्वरम्, भगवान् तज्ज्ञानं च एव अव्ययम् इति जानन्ति। 'पार्थ' इति व्युत्पत्त्या 'प्रथ-विस्तारे' धातुजं सर्वगतत्वसूचकं, वेदार्थं सदा पिबन्तः पार्थाः इत्यर्थः।",
  "9.14": "सततं कीर्तयन्तो मां यतन्तश्च दृढव्रताः । नमस्यन्तश्च मां भक्त्या नित्ययुक्ता उपासते -- दैवीस्वभावाः सर्वकर्मसु भगवत्प्रज्ञां धारयन्तः, तन्त्रीं वादयन्तो नारदवत् गुणगानरताः, दृढव्रतेन अनन्यप्रेम्णा च आराधनां कुर्वन्ति।",
  "9.15": "ज्ञानयज्ञेन चाप्यन्ये यजन्तो मामुपासते । एकत्वेन पृथक्त्वेन बहुधा विश्वतोमुखम् -- केचित् ध्यानमग्नाः बहिर्जगदविज्ञानाः भगवन्तं ध्यानयज्ञेन उपासते। एकत्वेन इति भगवान् एकः इति उपासनम्; पृथक्त्वेन इति सर्वातिशायिनं तं नानारूपेण ध्याने दर्शनम्। एवं विश्वतोमुखं भगवन्तं एकत्वेन चतुर्मूर्त्या अनेकमूर्त्या अनेकवर्णेन च उपासते। अग्रे भगवतः विभूतीः पृथक्पृथक् प्रतीकेषु अनुसन्धेयाः कृष्णः वदति।",
  "9.16": "अहं क्रतुरहं यज्ञः स्वधाहमहमौषधम् । मन्त्रोऽहमहमेवाज्यमहमग्निरहं हुतम् -- मत्क्रिया मत्स्वरूपत्वात् अहं 'क्रतुः'; सर्वज्ञत्वात् 'यज्ञः'; पितॄणाम् अन्नं मत्तः, स्वाश्रयत्वात् 'स्वधा'; मनुष्याणाम् आहारः मत्तः, आर्तानाम् आश्रयत्वात् 'औषधम्'; ज्ञानरक्षकत्वात् 'मन्त्रः'; सर्वातिशायित्वात् 'आज्यम्'; अचलाय जगते गतिप्रदत्वात् 'अग्निः'; भक्तैः आहूतत्वात् 'हुतम्'।\n\nअग्निवायुआदित्यप्रतीकैः वेदे भगवदुपासना निर्दिष्टा। कर्मप्रधानाः जनाः ज्ञानं गौणीकुर्वन्ति -- इदं मानवदौर्बल्यम्। यज्ञे \"अग्नये स्वाहा इदं न मम\" इत्यादिना विभिन्नप्रतीकेषु आहुतिः दीयते, सा सर्वा अन्तर्यामिणं भगवन्तमेव प्राप्नोति; भगवान् एकः, शक्तयः बहुधा। यत् तत्त्वाभिमानिदेवताभ्यः पूजा सा 'यज्ञः'; यत् पितृदेवताभ्यः तत् 'श्राद्धम्' -- न मृतजीवाय, अपि तु पितृदेवतानां प्रसादेन जीवस्य मार्गप्रतिबन्धकनिवारणार्थम्। 'स्वधा' पितृदेवतासम्बोधनम्, 'स्वाहा' तत्त्वाभिमानिदेवतासम्बोधनम्।\n\nनरकुलस्य प्रधानम् अन्नम् औषधिः, फलं दत्त्वा म्रियमाणा वनस्पतिः; सा च भगवत एव। नानामन्त्रैः दत्तापि आहुतिः सर्वशब्दवाच्यं भगवन्तमेव प्राप्नोति -- नारिकेलदृष्टान्तेन इदं स्पष्टम् (छिल्केऽन्तः फलं, फलेऽन्तः सारः इव अग्नौ अन्तः अग्निदेवता, तस्यामन्तः भगवान्)।\n\nद्वितीयदृष्ट्या: क्रतुः (क्रियाज्ञानस्वरूपः, कर्मबन्धमोचकः), यज्ञः (सर्वज्ञः यज्ञान्तर्यामी), स्वधाः (स्वाश्रयः सर्वनियामकः), औषधः (संसारतप्तानां मोक्षप्रदः), मन्त्रः (ज्ञानपूर्वकानुसन्धानरक्षकः), आज्यः (सर्वोत्कृष्टः), अग्निः (अचलाय गतिप्रदः), हुतः (सर्वभक्तैराहूतः) -- इति प्रतिशब्दं भगवद्गुणानुसन्धानं द्रष्टव्यम्।",
  "9.17": "पिताहमस्य जगतो माता धाता पितामहः । वेद्यं पवित्रमोंकार ऋक्सामयजुरेव च -- पोषणात् 'पिता', जननात् 'माता', वर्धनात् 'धाता', पितुरपि ज्येष्ठत्वात् 'पितामहः' अहमेव। एकः पुमान् पिता वा माता वा भवति, न उभयम् -- भगवति एव उभयं सम्भवति; प्रतिपितरि पितृत्वं, प्रतिमातरि मातृत्वं जागरयन् सः एव तत्तत् रूपेण तिष्ठति। श्रुतौ \"यो नः पिता जनिता\" इति पितृजनकयोः पार्थक्येन सः एव उभयरूपः इत्युक्तम्। भगवान् स्त्रीपुंसकः बिम्बरूपेण, दोषातीतः लिङ्गातीतश्च। सः 'धाता' अनादिकालं जगत् धारयति पुष्णाति च, चतुर्मुखान्तर्गतः 'पितामहः'।\n\nप्रतिबन्धस्य पृष्ठतः भगवत्सम्बन्धः; तत्तज्जीवप्रारब्धानुसारेण स्नेहशत्रुत्वादि तस्यैव लीला। इदं ज्ञात्वा द्वेषे न कुण्ठा, प्रीतौ न उत्कर्षः -- वृत्रेन्द्रसंवादः (भागवते) अस्य दृष्टान्तः: \"मां जहि इन्द्र, नाट्येऽस्मिन् भगवता तुभ्यं हन्तृपात्रं मह्यं हन्तव्यपात्रं दत्तम्\" इति वृत्रवचनम्।\n\nवेद्यं पवित्रम् ओंकारः ऋक् साम यजुः च अहमेव। सर्वशब्दानां मूलम् ओंकारः, अतः भगवान् सर्वशब्दवाच्यः। ओंकारस्य अकार-उकार-मकार-नाद-बिन्दु-कला-शान्त-अतिशान्त इति अष्टवर्णेभ्यः नारायणाष्टाक्षरः \"ॐ नमो नारायणाय\" व्यज्यते। तेभ्यश्च वर्णमालायाः अष्टवर्गाः -- स्वराः, कवर्गादि षड्वर्गाः, अन्तस्थाः, ऊष्माणः -- मिलित्वा अकारात् क्षकारं यावत् एकपञ्चाशत् अक्षराणि (अतः 'अक्षरम्')। तैः वाच्यानि एकपञ्चाशत् भगवद्रूपाणि -- अज, आनन्द, इन्द्र, ईश, उग्र, ऊर्ज, ऋतम्भर इत्यादीनि, अन्ते नृसिंहपर्यन्तानि।\n\nओंकारस्य अ-उ-म इति त्रिवर्णाः पद्य-गद्य-गानरूपेण ऋक्-यजुः-सामवेदान् सूचयन्ति -- ऋग्वेदः 'अ'कारेण आरभ्य 'इ'कारे समाप्यते, यजुर्वेदः 'इ'कारादारभ्य 'उ'कारे, सामवेदः पुनः 'अ'कारादारभ्य 'उ'कारे नादरूपेण समाप्यते -- तत्र 'म'कारः नादात्मना अन्तर्भूतः। एवम् ओंकारः वेदस्य बीजाक्षरः संक्षेपरूपः, भगवतः प्रकृष्टतमं स्तोत्रनाम च। प्रणवात् व्याहृतयः, ततः गायत्री, ततः पुरुषसूक्तं, ततः समस्तवेदाः विस्तरन्ते -- सर्वत्र भगवान् नेलसति।\n\nभगवान् 'ऋक्' -- येन अर्च्यते सः; 'सामः' -- सर्वस्मिन् रूपे ज्ञानानन्दादिगुणैः समानः, यथायोग्यं जीवनप्रदः; 'यजुः' -- सर्वयागैः होमितः वेदेषु सन्निहितः सर्वशब्दवाच्यः।",
  "9.18": "गतिर्भर्ता प्रभुः साक्षी निवासः शरणं सुहृत् । प्रभवः प्रलयः स्थानं निधानं बीजमव्ययम् -- मोक्षार्थं ज्ञातव्यः, सर्वभारवाही, सर्वस्वामी, साक्षात्द्रष्टा, सर्वाश्रयः, मुक्तानामपि शरणम्, अनिमित्तबन्धुः, सृष्टिस्थितिप्रलयकारणम्, प्रलये गर्भधारकः पुनःसृष्ट्युत्पादकः, अव्ययश्च अहमेव। संसारे मोक्षे च आश्रयत्वात् 'गतिः' सद्गतिः दुर्गतिश्च; सर्वज्ञत्वात् 'साक्षी'। ईशावास्योपनिषद्वाक्येन \"ईशावास्यमिदं सर्वम्\" इति गृहवत् जगति निवासं कल्पयित्वा 'निवासः'; आपत्काले रक्षकः 'सुहृत्' सखा च हृदयस्पन्दनशीलः। सृष्ट्युत्पत्तिस्थितिनाशाः सर्वे मत्तः, न ब्रह्मविष्णुशिवेभ्यः पृथक्।",
  "9.19": "तपाम्यहमहं वर्षं निगृह्णाम्युत्सृजामि च । अमृतं चैव मृत्युश्च सदसच्चाहमर्जुन -- सूर्यान्तर्गतः सौरशक्तिं भूमये प्रयच्छामि; ऋतुकाले वर्षं करोमि, अकाले निगृह्णामि। जीवनप्रदम् अमृतम्, आयुःक्षये मृत्युश्च अहमेव। दृश्यम् (सत्) अदृश्यं (असत्) च सर्वं मया एव निर्वाह्यते -- इति भगवदनुसन्धानस्य समग्रचित्रणम्। अग्रे त्रैविद्यभागवतभक्तयोः भेदः वक्ष्यते।",
  "9.20": "त्रैविद्या मां सोमपाः पूतपापा यज्ञैरिष्ट्वा स्वर्गतिं प्रार्थयन्ते । ते पुण्यमासाद्य सुरेन्द्रलोकमश्नन्ति दिव्यान्दिवि देवभोगान् -- त्रैविद्याः त्रिपथगामिनः, स्वर्गलौकिकेच्छया भगवन्तं भजन्ते। कर्मकाण्डप्राधान्येन ज्योतिष्टोमादियागैः स्वर्गमेव कामयन्ते, न भगवन्तम्। ततः पुण्यफलेन इन्द्रलोकं प्राप्य भोगान् अनुभवन्ति।",
  "9.21": "ते तं भुक्त्वा स्वर्गलोकं विशालं क्षीणे पुण्ये मर्त्यलोकं विशन्ति । एवं त्रयीधर्ममनुप्रपन्नाः गतागतं कामकामा लभन्ते -- स्वर्गभोगं भुक्त्वा पुण्यक्षये पुनः मर्त्यलोके जायन्ते; अतः परमं मोक्षं भगवन्तं च न लभन्ते, कामानुसारेण गतागतचक्रे भ्रमन्ति। एतद्विपरीतः भागवतानां मार्गः।",
  "9.22": "अनन्याश्चिन्तयन्तो मां ये जनाः पर्युपासते । तेषां नित्याभियुक्तानां योगक्षेमं वहाम्यहम् -- भागवताः किमपि न इच्छन्ति, भगवच्चिन्तनम् एव अनन्यम् इच्छन्ति, न कामनाबद्धाः पूजां कुर्वन्ति, सर्वदेवतान्तः केवलं भगवन्तमेव पश्यन्ति -- इयम् एकभक्तिः मोक्षमार्गः। सङ्कल्पे ऐहिकं कामं न स्थापयेत्; केवलं ज्ञानभक्तिमोक्षमेव प्रार्थयेत्। कृष्णः स्वयमेव तेषां योगक्षेमभारं वहति इति आश्वासयति। दृढश्रद्धया समर्पितानां दुःखं न भवति, सर्वं भगवदिच्छारूपेण सन्तोषेण स्वीकर्तव्यम् -- इदमेव मोक्षद्वारम्।",
  "9.23": "येऽप्यन्यदेवताभक्ता यजन्ते श्रद्धयान्विताः । तेऽपि मामेव कौन्तेय यजन्त्यविधिपूर्वकम् -- अन्यदेवताभक्ताः अपि श्रद्धया यजमानाः अविधिपूर्वकं मामेव यजन्ति।",
  "9.24": "अहं हि सर्वयज्ञानां भोक्ता च प्रभुरेव च । न तु मामभिजानन्ति तत्त्वेन अतश्च्यवन्ति ते -- देवतान्तरं प्राधान्येन पूजयतां अपि सा पूजा अन्ततः भगवत्येव प्राप्नोति, यतः सर्वयज्ञभोक्ता प्रभुश्च अहमेव। किन्तु अनभिज्ञतया अपूर्णभक्तिः, परतत्त्वानुसन्धानरहिता पूजा उन्नतिं न ददाति, पुण्यकर्मणापि च्युताः भवन्ति। सर्वदेवतापरिवारसमेतं भगवन्तं पूजयतः एव भगवत्प्राप्तिः शास्त्रव्यवस्था।",
  "9.25": "यान्ति देवव्रता देवान्पितॄन्यान्ति पितृव्रताः । भूतानि यान्ति भूतेज्याः यान्ति मद्याजिनोऽपि माम् -- यं यं पूजयति तं तमेव प्राप्नोति -- देवव्रताः देवान्, पितृव्रताः पितॄन्, भूतेज्याः भूतप्रेतान्, मद्भक्ताः तु मामेव प्राप्नुवन्ति। देवतापूजया स्वर्गः, न पुनरावृत्तिरहितं मोक्षम्। परतत्त्वानुसन्धानरहिता पूजा मोक्षं न ददाति; सर्वदेवतापरिवारसमेतं भगवन्तं पूजयतः एव सा प्राप्तिः।\n\nअत्र स्पष्टव्यम्: गणहोमनवग्रहहोमादिषु प्रतीकपूजा न दोषः, दोषस्तु सङ्कल्पगतः। निष्कामसङ्कल्पेन नवग्रहान्तर्गतनारायणप्रीत्यर्थं कृतं होमं भागवतधर्मः; \"नवग्रहदोषनिवारणार्थं नारायणः प्रसीदतु\" इति सकामसङ्कल्पः त्रैविध्यधर्मः। भगवत्प्रीत्यर्थमेव सर्वकर्म कर्तव्यम्, दुःखनिवारणार्थं न पूजनीयः अपि तु प्रसादत्वेन सर्वं स्वीकार्यम्; मोक्षभगवद्भिन्ना कामना पूजासङ्कल्पे न स्थाप्या।",
  "9.26": "पत्रं पुष्पं फलं तोयं यो मे भक्त्या प्रयच्छति । तदहं भक्त्युपहृतमश्नामि प्रयतात्मनः -- भगवत्पूजायाः मूलं सम्पूर्णतल्लीनता भावशुद्धिश्च, न बाह्यवैभवम्। भक्त्या दत्तं पत्रपुष्पफलतोयमपि प्रीत्या स्वीकरोति भगवान्। शबरीकथा अस्य दृष्टान्तः।",
  "9.27": "यत्करोषि यदश्नासि यज्जुहोषि ददासि यत् । यत्तपस्यसि कौन्तेय तत्कुरुष्व मदर्पणम् -- स्वकर्तव्यमेव भगवदर्पणबुद्ध्या कुर्यात्, पृथक् विशिष्टपूजा अनावश्यका। धर्मव्याधकथा अस्य दृष्टान्तः -- वृत्त्या मांसविक्रयी अपि भगवदर्पणानुसन्धानेन महाज्ञानी अभवत्। भोजनं होमं दानं तपश्च सर्वं \"अग्न्यन्तर्गतनारायणाय इदं न मम\" इति भावेन भगवदर्पितं कुर्यात्। अत्र अर्जुनाय युद्धमपि भगवत्पूजारूपेण कर्तव्यम् इति सन्देशः।",
  "9.28": "शुभाशुभफलैरेवं मोक्ष्यसे कर्मबन्धनैः । संन्यासयोगयुक्तात्मा विमुक्तो मामुपैष्यसि -- फलकामनया अहङ्कारेण च कृतं कर्म बध्नाति; \"भगवतो बलेन\" इति सङ्कल्पेन \"मत्कर्म न मम, भगवत एव\" इति ज्ञानेन कर्म न बध्नाति। ब्रह्मसूत्रोक्तं यत् भगवज्ज्ञानाग्निः पूर्वपापं दहति -- कठोपनिषदि नचिकेतःकथा अस्य दृष्टान्तः। भगवदर्पणबुद्ध्या कृतं कर्म शुभाशुभबन्धनान् मोचयति; संन्यासः इति काम-सङ्कल्पयोः भगवदर्पणम्। एवं भागवतधर्मानुष्ठानेन सुलभं भगवत्प्राप्तिः।",
  "9.29": "समोऽहं सर्वभूतेषु न मे द्वेष्योऽस्ति न प्रियः । ये भजन्ति तु मां भक्त्या मयि ते तेषु चाप्यहम् -- भगवतः न कस्मिन्नपि द्वेषः प्रीतिर्वा; सः व्यक्तिगतं ज्ञानभक्ती एव प्रीणाति। अर्हाः भक्त्या भगवन्तं वशीकुर्वन्ति, तेषां भगवान् वशः।",
  "9.30": "अपि चेत्सुदुराचारो भजते मामनन्यभाक् । साधुरेव स मन्तव्यः सम्यग्व्यवसितो हि सः -- सद्भक्ताः प्रायेण न दुराचारिणः; कदाचित् प्रारब्धवशात् सात्त्विकोऽपि दुराचारी स्यात्, तथापि सः मूलतः उत्तमः, बहुजन्मार्जितसाधनावशात्। अतः कञ्चिदपि अवमन्तव्यम् न; उत्तमः सदा तत्पथे न तिष्ठति इति अग्रे।",
  "9.31": "क्षिप्रं भवति धर्मात्मा शश्वच्छान्तिं निगच्छति । कौन्तेय प्रतिजानीहि न मे भक्तः प्रणश्यति -- प्रारब्धवशात् मार्गभ्रष्टाः शीघ्रं स्वदोषम् अवगम्य सन्मार्गं गृह्णन्ति, अव्ययं मोक्षं प्राप्नुवन्ति। अजामिळकथा अस्य दृष्टान्तः। भगवान् स्वप्रतिज्ञां भक्तार्थं भङ्गं कुर्यात्, न तु भक्तप्रतिज्ञाम् -- भीष्मकृष्णचक्रकथा अस्य साक्षी।",
  "9.32": "मां हि पार्थ व्यपाश्रित्य येऽपि स्युः पापयोनयः । स्त्रियो वैश्यास्तथा शूद्रास्तेऽपि यान्ति परां गतिम् -- अत्र 'स्त्रीपापयोनिः' इति पूर्वजन्मपापशापेन स्त्रीत्वं प्राप्तः पुमान्, न स्त्रीजीवः स्वयम् -- मध्वाचार्यभाष्यानुसारेण एतत् स्पष्टम्। नरकासुरबद्धाः षोडशसहस्रशतकन्याः, नन्दगोपयशोदे (वैश्यजन्मानौ), विदुरः (दासीपुत्र इति शापेन उक्तः) -- एते सर्वे हीनयोनिजन्मनोऽपि भगवदाश्रयेण परां गतिं प्राप्ताः।",
  "9.33": "किं पुनर्ब्राह्मणाः पुण्या भक्ता राजर्षयस्तथा । अनित्यमसुखं लोकमिमं प्राप्य भजस्व माम् -- पुण्यजन्मनां राजर्षिब्राह्मणानां तु वक्तव्यमेव किम्? अनित्यम् असुखं च इदं जगत् इति ज्ञात्वा मामेव आश्रय; तव उद्धारभारः मम एव।",
  "9.34": "मन्मना भव मद्भक्तो मद्याजी मां नमस्कुरु । मामेवैष्यसि युक्त्वैवमात्मानं मत्परायणः -- सर्वपूजा भगवत्पूजा भवतु, सर्वप्रेम्णि भगवन्तं पश्य, सर्वनमस्कारः भगवन्नमस्कारः भवतु। एवं मनः भगवति स्थापयित्वा सम्पूर्णं जीवनं भगवन्मयं कुरु -- अवश्यं मां प्राप्स्यसि इति कृष्णः वदति। इति मोक्षसाधकोपासना निरूपिता।\n\nइति नवमोऽध्यायः।",
  "10.1": "दशमोऽध्यायः\n\nपूर्वाध्याये भगवदुपासनार्हं ज्ञानं विज्ञानं च अर्जुनाय वर्णितवान् कृष्णः; अधुना तस्मिन् प्रबुद्धां ज्ञानतृष्णां पूर्णनिष्ठां च दृष्ट्वा उपासनायां विशेषतः ग्राह्यं अनुसन्धानं भगवद्विभूतिं च वर्णयति।\n\nसामान्यतः गुरुः अमूल्यां विद्यां सहसा न प्रकाशयति; शिष्ये पूर्णनिष्ठां योग्यतां च दृष्ट्वैव तत् वक्तव्यम् इति शास्त्रमर्यादा। प्रश्नोपनिषदि पिप्पलादः षड्भ्यः महाविद्वद्भ्यः आह — \"भूय एव तपसा ब्रह्मचर्येण श्रद्धया संवत्सरं संवत्स्यथ; यथाकामं प्रश्नान् पृच्छत\" इति। अत्र गुरुशिष्ययोः परस्परपरीक्षा दृश्यते; किन्तु योग्यशिष्ये पूर्णनिष्ठां ज्ञात्वा गुरुः अपृष्टोऽपि सानन्दं ज्ञानं वितरति। अर्जुने कृष्णः एतादृशीं निष्ठाम् अद्राक्षीत्।\n\nश्रीभगवानुवाच — भूय एव महाबाहो शृणु मे परमं वचः, यत् ते प्रीयमाणाय हितकाम्यया वक्ष्यामि। इदं वचनं सर्वज्ञानोत्तमं, लोकोपकारकं, परतत्त्वबोधकं च। त्वं युद्धभूमौ स्थित्वा श्रवणे प्रमोदसे; अतः जगद्धितार्थम् एतत् वक्ष्यामि, शृणु इति भावः।",
  "10.2": "न मे विदुः सुरगणाः प्रभवं न महर्षयः, अहम् आदिः हि देवानां महर्षीणां च सर्वशः। अत्र 'प्रभव' शब्दः त्रिविधार्थे — मूलम्, सामर्थ्यम्, जगदुत्पत्तिश्च। मम मूलं महिमानं जगदुत्पत्तिं च साक्षात्कृतज्ञानिनोऽपि ब्रह्मादयोऽपि न विदुः।",
  "10.3": "यो मां अजम् अनादिं च वेत्ति लोकमहेश्वरम्, असम्मूढः सः मर्त्येषु सर्वपापैः प्रमुच्यते। भगवान् अजः जन्ममरणातीतः; अनादिः सृष्ट्युत्पादनात् पूर्वमपि प्रेरकः सृष्ट्युत्तरं च सर्वनियामकः। लोकेशानां सर्वेषां हि लोकमहेश्वरः लक्ष्म्याः अपि महान्। सृष्टिवृत्तान्तः चतुर्मुखजन्मादपि पूर्वः, अतः कस्यापि अगोचरः; ऋग्वेदे \"न ते विष्णो जायमानो न जातो देवो महिम्नः परमन्तमाप\" इति उक्तम्। एवं भगवतः अनन्तत्वं ज्ञात्वा उपासनैव मोक्षमार्गः; एतज्ज्ञः असम्मूढः सर्वपापमुक्तश्च भवति।",
  "10.4": "बुद्धिः ज्ञानम् असम्मोहः क्षमा सत्यं दमः शमः, सुखं दुःखं भवोऽभावो भयं चाभयमेव च — एतानि सर्वाणि मत्त एव भवन्ति। बुद्धिः कर्तव्याकर्तव्यविवेकः, ज्ञानं वस्तुबोधः; उभयसमन्वयेन एव पूर्णत्वम्। क्षमा — अनुचितनिन्दायां प्रतीकाररहितता। सत्यम् — प्रामाणिकता, यया विना आचारोऽपि निष्फलः। दमः — इन्द्रियनिग्रहः, यस्य एकः उपायः भगवच्छरणागतिः। शमः — मनसः प्रशान्तता, लौकिकचिन्तात्यागेन भगवत्संलग्नेन च साध्या। एतत्सर्वं मत्तः एव जायते इति भगवदुपासनायां ज्ञातव्यम्।",
  "10.5": "अहिंसा समता तुष्टिः तपः दानम् अदानं यशः अयशः — भूतानां भावाः मत्त एव पृथग्विधाः। अहिंसा — मनोवाक्कायैः अपीडनम्; कदाचित् हिंसैव अहिंसा, यथा महाहिंसानिवारणार्थं लघुहिंसा। समता — योग्यतानुसारं समदृष्टिः, न तु सर्वत्र ऐक्यबुद्धिः। तुष्टिः — यत् प्राप्तं तेन सन्तोषः, अतृप्तिः एव दुःखमूलम्। तपः — कायवाङ्मनोभिः त्रिविधम्, आहारनियमेन मनोनिग्रहः, सत्यहितवचनं, गम्भीरचिन्तनं च। दानम् — पापच्छेदकरं ददानं दानम्, पुण्यच्छेदकरं तु अदानम्; योग्यदेशकालपात्रे निष्कामं दानमेव सद्दानम्। यशः-अयशः — जीवनाचारानुसारमेव, अतः तत्र चित्तं न विक्षेप्यम्; शमन्तकमणिप्रसङ्गे कृष्णस्यैव आदर्शः। एतत्सर्वं जीवभावेषु मत्त एव उत्पद्यते, इति भगवत उपासनाविज्ञानम्।",
  "10.6": "महर्षयः सप्त पूर्वे चत्वारः मनवः तथा, मद्भावाः मानसाः जाताः येषां लोके इमाः प्रजाः। प्रथममन्वन्तरस्य सप्तर्षयः (मरीचि-अत्रि-अङ्गिरस्-पुलस्त्य-पुलह-क्रतु-वसिष्ठाः), आद्याः चत्वारः मनवः (स्वायम्भुव-स्वारोचिष-उत्तम-रैवताः), चतुर्मुखस्य मानसपुत्राश्च — सर्वे मत्त एव जाताः। विश्वस्य जनाः तेषामेव सन्ततिः। मनुशब्दः तत्त्वाभिमानिदेवतानामपि वाचकः, ये मनुष्यस्य ब्राह्म्य-क्षात्र-वैश्य-शौद्रस्वभावान् नियच्छन्ति।",
  "10.7": "एतां विभूतिं योगं च मम यः वेत्ति तत्त्वतः, सः अविकम्पेन योगेन युज्यते नात्र संशयः। भगवतो महिम्नः रूपाणां च याथात्म्यज्ञानेन सहजा शरणागतिः जायते; तादृशी श्रद्धाभक्तिपूर्णा बुद्धिः भगवति दृढं प्रतिष्ठते।",
  "10.8": "अहं सर्वस्य प्रभवः मत्तः सर्वं प्रवर्तते, इति मत्वा भजन्ते मां बुधाः भावसमन्विताः। सर्वनियामकः सर्वकारणं सर्वजन्मभूमिश्च अहम् इति ज्ञात्वा ज्ञानिनः अनन्यभक्त्या मां भजन्ते।",
  "10.9": "मच्चित्ताः मद्गतप्राणाः बोधयन्तः परस्परम्, कथयन्तश्च मां नित्यं तुष्यन्ति च रमन्ति च। एतादृशज्ञानभक्तानां चित्तं सदा भगवन्मयम्; ते सर्वत्र भगवन्तमेव पश्यन्ति, नित्यं तद्विषयं संलपन्तः आनन्दमग्नाः तिष्ठन्ति।",
  "10.10": "तेषां सततयुक्तानां भजतां प्रीतिपूर्वकम्, ददामि बुद्धियोगं तं येन मां उपयान्ति ते। भगवति शरणागतानां प्रीतिपूर्वं भजतां तां बुद्धिं स्वयमेव भगवान् ददाति, यया ते तमेव प्राप्नुवन्ति।",
  "10.11": "तेषामेव अनुकम्पार्थम् अहम् अज्ञानजं तमः, नाशयामि आत्मभावस्थः ज्ञानदीपेन भास्वता। भगवान् न स्वार्थेन अपि तु कारुण्येन एव भक्तम् उद्धरति; बुद्धिं दत्त्वा तमोऽपि अपनयति। त्रिगुणातीतः सः एव अज्ञानान्धकारं नाशयितुं समर्थः; अतः शरणागतिः एव यथार्थज्ञानस्य उपायः।",
  "10.12": "अर्जुन उवाच — परं ब्रह्म परं धाम पवित्रं परमं भवान्, पुरुषं शाश्वतं दिव्यम् आदिदेवम् अजं विभुम्। विभूतिश्रवणानन्तरम् अर्जुनस्य उद्गारः एषः। 'परंब्रह्म' परमसत्यम्, 'आदिदेव' देवानां देवः, 'अजः' अजन्मा, 'विभुः' सर्वव्यापी। माध्वमते 'परंब्रह्म' नारायणः इति।",
  "10.13": "आहुस्त्वां ऋषयः सर्वे देवर्षिर्नारदस्तथा, असितो देवलो व्यासः स्वयं चैव ब्रवीषि मे। अत्र अर्जुनः कृष्णं पुरुषोत्तमात्मकैः बहुविधैः विशेषणैः संबोधयति — भूतभावन, भूतेश, देवदेव, जगत्पते इति। भूतभावनः पञ्चभूतात्मकजगत्स्रष्टा जीवसृष्ट्यादिकारणं च; भूतेशः सर्वनियामकः स्वामी; देवदेवः सर्वदेवानाम् अपि देवः सूर्यादीनां प्रकाशदाता; जगत्पतिः जननमरणमोक्षप्रदः पालकः। पुरुषः-शाश्वतः-दिव्यः-आदिदेवः-अजः-विभुः इत्येतेषु शब्देषु भगवतः अनन्तगुणाः निहिताः, विष्णुसहस्रनाम्नि एतत्सर्वं दृश्यते। पुरुषः — पुरे वसतीति पुरुषः, पुरुषसूक्तोक्तः 'सहस्रशीर्षा पुरुषः'; सृष्टेः पूर्वं सन् सृष्टिकर्ता, प्रलये दग्धसर्वः, अनन्तकालसामर्थ्यगुणसंपन्नः, प्रतिपिण्डाण्डे बिम्बरूपेण स्थित्वा कार्यं साधयित्वा मोक्षप्रदः। शाश्वतः — अनादिनन्तकाले निर्विकारः आनन्दस्वरूपः। दिव्यः — 'दिवु' धातोः ध्युति-विजिगीष-कान्ति-स्तुति-व्यवहार-क्रीडा-गतिज्ञानाद्यर्थसप्तकयुक्तः। आदिदेवः — सृष्टिस्थितिसंहाराः यस्य लीलामात्रम्। अजः — न जायते इति अजः, अजादपि चतुर्मुखजनकः, स्वयम् अजन्मा सर्वस्रष्टा संहर्ता च; प्रतिगर्भं बिम्बरूपेण जायमानोऽपि अजः। विभुः — विविधरूपधारी सर्वसमर्थः। अर्जुनः नारद-असितदेवल-व्यासान् स्मरति, यतः तान् दृष्टवान् श्रुतवांश्च; नारदः चतुर्दशस्थाने देवतातारतम्ये, अन्तःप्रज्ञादेवता(intuition); असितदेवलौ मन्त्रदृष्टारौ; व्यासः वेदविभाजकः पुराणमहाभारतप्रदाता भगवदवतारः। \"एतैः यदुक्तं तदेव त्वं मह्यं कथयसि\" इति अर्जुनस्य निश्चयः।",
  "10.14": "सर्वमेतद् ऋतं मन्ये यन्मां वदसि केशव, न हि ते भगवन् व्यक्तिं विदुर्देवा न दानवाः। भगवतो गुणप्रमाणं देवाः मातुं न शक्नुवन्ति, दानवाः दोषान्वेषणे न सफलाः, यतः भगवान् अनन्तगुणपूर्णः निर्दोषश्च। तम् एकम् अवतारं वा तल्लीलामपि पूर्णतया अवगन्तुं दुष्करम्; प्रत्येकं तच्चेष्टितं संदेशयुक्तम्।",
  "10.15": "स्वयमेवात्मनात्मानं वेत्थ त्वं पुरुषोत्तम, भूतभावन भूतेश देवदेव जगत्पते। वक्तुमर्हस्यशेषेण दिव्या हि आत्मविभूतयः, याभिर्विभूतिभिर्लोकानिमांस्त्वं व्याप्य तिष्ठसि। त्वां क्षराक्षरातीतं पुरुषोत्तमम् एव त्वयैव वक्तव्यम्, न परेण; एतत् अर्जुनस्य भावः।",
  "10.16": "[बन्नञ्जेभाष्ये १०.१५-१०.१६ श्लोकौ संयुक्तं व्याख्यातौ। व्याख्या १०.१५-श्लोक एव अन्तर्भूता।]",
  "10.17": "कथं विद्यामहं योगिँस्त्वां सदा परिचिन्तयन्, केषु केषु च भावेषु चिन्त्योऽसि भगवन्मया। प्रत्येकवस्तुनि विशिष्टगुणस्य पृष्ठतः भगवद्विभूतिः निहिता; अर्जुनः प्रार्थयते — केषु वस्तुषु त्वदुपासनां कुर्यामिति ज्ञातव्यम्।",
  "10.18": "विस्तरेणात्मनो योगं विभूतिं च जनार्दन, भूयः कथय तृप्तिर्हि शृण्वतो नास्ति मेऽमृतम्। भगवद्विभूतिः चतुर्विधा — साक्षाद्विभूतिः(अवताराः), विजातीयश्रेष्ठप्रभा(चन्द्रः), स्वजातीयश्रेष्ठप्रभा(इन्द्रः सूर्यश्च), स्वजातीयैकदेशीयश्रेष्ठप्रभा(अर्जुनः पाण्डवेषु)। अर्जुनः आनन्दसागरे निमग्नः विभूतिविस्तारं प्रार्थयते।",
  "10.19": "श्रीभगवानुवाच — हन्त ते कथयिष्यामि दिव्या हि आत्मविभूतयः, प्राधान्यतः कुरुश्रेष्ठ नास्त्यन्तो विस्तरस्य मे। अर्जुनस्य कातरतां प्रशंसन् कृष्णः प्रमुखविभूतीः संक्षेपेण वक्तुम् उद्यच्छति; 'कुरुश्रेष्ठ' इति संबोधनं भगवदुपासनामार्गे तस्य उन्नतिं सूचयति।",
  "10.20": "अहमात्मा गुडाकेश सर्वभूताशयस्थितः, अहमादिश्च मध्यं च भूतानामन्त एव च। विभूतेः सारः — भगवान् सर्वान्तर्यामी इति। जीवात्मा-परमात्मा ऐक्यं नात्र उच्यते, अपि तु प्रतिजीवं बिम्बरूपेण अन्तर्यामित्वम्। 'गुडाकेश' निद्राजयी अर्जुनः, तत्रापि भगवान् एव जयशक्तिरूपेण स्थितः।",
  "10.21": "आदित्यानामहं विष्णुर्ज्योतिषां रविरंशुमान्, मरीचिर्मरुतामस्मि नक्षत्राणामहं शशी। द्वादशादित्येषु वामनरूपो विष्णुः साक्षाद्विभूतिः; अतः \"आदित्येषु विष्णुरहम्\" इति। विष्णुशब्दः त्रिधातुनिष्पन्नः — व्याप्तः, प्रवेशः, प्रजनन-गति-कान्ति-संहार-त्रिविक्रमगमनानि च; समष्टितः 'देवः' इत्यर्थः। रविः — रवशब्देन ज्ञेयः, गायत्रीप्रतिपाद्यः सूर्यसन्निहितः। मरीचिः — भूतवायुदेवताभिमानी, वर्षणशक्तिप्रदः। शशी — शशब्देन आनन्दस्वरूपः, चन्द्रे नक्षत्राधिपत्यप्रदाता।",
  "10.22": "वेदानां साम वेदोऽस्मि देवानामस्मि वासवः, इन्द्रियाणां मनश्चास्मि भूतानामस्मि चेतना। सामवेदस्य वैशिष्ट्यं नादः — शब्दस्य कीदृशोऽपि विभाजनेऽपि भगवन्नामधेयत्वं जायते इति अपूर्वगुणधर्मः(unique quality)। सामः सर्वत्र समः, वेदः ज्ञानस्वरूपः। वासवः — इन्द्रियनियामकेषु प्रधानः इन्द्रः, हस्तेन्द्रियविशिष्टः। चेतना — मनोगृहीतार्थस्य ग्रहणशक्तिः, चित्ताभिमानिशक्तिः।",
  "10.23": "रुद्राणां शङ्करश्चास्मि वित्तेशो यक्षरक्षसाम्, वसूनां पावकश्चास्मि मेरुः शिखरिणामहम्। एकादशरुद्रेषु शिवः शङ्करः प्रधानः — मनोऽभिमानी, शरीरपुरुषः, रोगहर्ता आनन्दप्रदः। \"भिषक्तमां त्वा भिषजम्\" इति ऋग्वेदे स्तुतः वैद्यनाथः। वित्तेशः — कुबेरे स्थितः, यक्षरक्षसां स्वामित्वप्रदः। पावकः — अष्टवसुषु अग्निः पावनशक्तिः। मेरुः — महालक्ष्म्या अपि प्रेरकः, स्वर्णाद्रौ संस्थितः।",
  "10.24": "पुरोधसां च मुख्यं मां विद्धि पार्थ बृहस्पतिम्, सेनानीनामहं स्कन्दः सरसामस्मि सागरः। षोडशपुरोहितेषु ब्रह्मादिसर्वदेवानां पुरोहितः बृहस्पतिः प्राणदेवाभिमानी, तत्र भगवत्सन्निधानम्। स्कन्दः — असुरापहृतं देवसंपत्तिं पुनः आनीतवान् सेनानीः, तारकासुरसंहारशक्तिप्रदः। सागरः — सारं लवणं गरति दधाति इति सागरः, समुद्रे विश्वसारप्रदः।",
  "10.25": "महर्षीणां भृगुरहं गिरामस्मि एकमक्षरम्, यज्ञानां जपयज्ञोऽस्मि स्थावराणां हिमालयः। भृगुः — भर्जनात् भृगुः, भक्तपापभर्जकः, दुष्टधर्मभर्जकः, नारायणसर्वश्रेष्ठत्वप्रकाशकः। ओंकारः — सर्वशब्देषु एकः अक्षरः, ऋषित्वप्राप्तिसाधनम्, सप्तमाध्याये विस्तृतम्। जपयज्ञः — जातस्य पालनात् जपः, सर्वपूजाग्रहणात् यज्ञः; मानसयज्ञः सर्वश्रेष्ठः। हिमालयः — ह्रीमा-आलयः, श्रीभूदेव्योः निवासः, अध्यात्मस्पन्दनप्रधानभूमिः।",
  "10.26": "अश्वत्थः सर्ववृक्षाणां देवर्षीणां च नारदः, गन्धर्वाणां चित्ररथः सिद्धानां कपिलो मुनिः। अश्वत्थः — हयग्रीवावताररूपेण वेदोपदेशकः, अत्यधिकाम्लजनकप्रदः यज्ञकाष्ठम्। नारदः — नरार्जितज्ञानप्रदः, अन्तःप्रज्ञादेवता(inner voice), आत्मस्वरध्वनिः। चित्ररथः — गन्धर्वराजः, गरुडवाहनसदृशं विचित्ररथयुक्तः। कपिलः — सांख्यप्रवर्तकः साक्षाद्भगवदवतारः, कपिलवासुदेवः देवहूतिकर्दमपुत्रः।",
  "10.27": "उच्चैःश्रवसमश्वानां विद्धि माममृतोद्भवम्, ऐरावतं गजेन्द्राणां नराणां च नराधिपम्। समुद्रमथनजातौ उच्चैःश्रवः-ऐरावतौ अश्वगजयोः श्रेष्ठौ, स्वामिनिष्ठापरिचायकौ। नराधिपः — धर्मनिष्ठजनपालकनृपेषु सन्निहितः, यथा धर्मराजपरीक्षितादयः।",
  "10.28": "आयुधानामहं वज्रं धेनूनामस्मि कामधुक्, प्रजनश्चास्मि कन्दर्पः सर्पाणामस्मि वासुकिः। वज्रः — दधीचितपःफलनिर्मितम् इन्द्रायुधम्, त्रैलोक्यनियामकम्, वर्जनात् वज्रः। कामधुक् — कामधेनौ इष्टप्रदा गोमहिमा, गोमयेऽपि लक्ष्मीसन्निधानम्। कन्दर्पः — प्रजननेच्छाप्रदाता, अनिवार्यशक्तिः। वासुकिः — सर्पराजे सर्वत्रवासिशक्तिः।",
  "10.29": "अनन्तश्चास्मि नागानां वरुणो यादसामहम्, पितॄणामर्यमा चास्मि यमः संयमतामहम्। शेषः — सङ्कर्षणः पृथ्वीगुरुत्वाकर्षण(Gravity)शक्तिः, अनन्तशयनः। वरुणः — जलचराधिपतिः महानन्दस्वरूपः। अर्यमा — पितृदेवतानां द्वादशादित्यान्तर्गतः नायकः। यमः — सांयमिकनियामकः, योगशास्त्रोक्तपञ्चयमप्रदाता — अहिंसा-सत्य-अस्तेय-अकाम-अपरिग्रहाः।",
  "10.30": "प्रह्लादश्चास्मि दैत्यानां कालः कलयतामहम्, मृगाणां च मृगेन्द्रोऽहं वैनतेयश्च पक्षिणाम्। प्रह्लादः — दैत्यकुलजातोऽपि भगवत्सन्निधानात् भिन्नस्वभावः, निष्कामभक्त्युपदेशकः। कालः — कलनात् सर्वगुणसङ्ग्राहकः, अहङ्कारसंहारकः; ज्ञानावताराभ्यां अज्ञाने कालः, बलावताराभ्यां अहङ्कारे कालः। मृगेन्द्रः — साधकमार्गदर्शकः सिंहे स्थितः। वैनतेयः — विनतापुत्रे गरुडे शरणागतरक्षकशक्तिः।",
  "10.31": "पवनः पवतामस्मि रामः शस्त्रभृतामहम्, रुषाणां मकरश्चास्मि स्रोतसामस्मि जाह्नवी। पवनः — पाति-वननीयत्वात् पवनः, सर्वदेहान्तर्यामी चलनप्रदः। रामः — रा-अमः, अपरिमितानन्दस्वरूपः रामावतारे विशेषतः प्रकाशितः, कैकेय्यामपि अक्रोधः पितृमातृभ्रातृदाम्पत्यादर्शप्रदर्शकः। मकरः — तिमिङ्गिले माकारप्रदः। जाह्नवी — जह्नु-त्यागात्, क्षुद्रकामनात्यागिनां रक्षिका, भगवतः स्त्रीरूपप्रतीकनाम।",
  "10.32": "सर्गाणामादिरन्तश्च मध्यं चैवाहमर्जुन, अध्यात्मविद्या विद्यानां वादः प्रवदतामहम्। तृणादिचतुर्मुखान्तं सर्वं भगवद्विभूतिः, प्रत्येकवस्तुनि अन्यत्र अलभ्यं विशिष्टगुणम्(Exclusive Quality) निहितम्। जीवोत्पत्तेः पूर्वं सन्, जीवस्थितिकारणं, अन्ततः संहारशक्तिश्च। अध्यात्मविद्या — जीवाधिकात्मत्वात् 'अध्यात्म', ज्ञानरूपत्वात् 'विद्या'। वादः — तत्त्वजिज्ञासार्थं शास्त्रचर्चा, सर्वनामवाच्यो भगवान् वादः।",
  "10.33": "अक्षराणामकारोऽस्मि द्वन्द्वः सामासिकस्य च, अहमेवाक्षयः कालो धाताहं विश्वतोमुखः। अकारः — सर्वगुणप्रकाशकं विशिष्टाक्षरम्, अन्यवस्तुभिन्नः निर्दोषः सर्वगुणपूर्णः। द्वन्द्वः — उभयपदप्रधानसमासे द्विरूपेण अन्तर्बहिःस्थितः। कालपुरुषः सर्वसंहारकः, धाता सर्वधारकपोषकः; विश्वतोमुखः सर्वत्रव्याप्तः।",
  "10.34": "मृत्युः सर्वहरश्चाहमुद्भवश्च भविष्यताम्, कीर्तिः श्रीर्वाक् च नारीणां स्मृतिर्मेधा धृतिः क्षमा। प्रलये सर्वहारी मृत्युदेवता, प्रलयोत्तरं पुनःसृष्टिकर्ता च भगवान्। स्त्रीरूपविभूतौ मुख्यतः लक्ष्मी-सरस्वती-भारतीषु कीर्ति-श्री-वाक्-स्मृति-मेधा-धृति-क्षमाभिमानिनीषु भगवान् स्थितः।",
  "10.35": "बृहत्साम तथा साम्नां गायत्री छन्दसामहम्, मासानां मार्गशीर्षोऽहमृतूनां कुसुमाकरः। बृहत्सामः — सप्तस्वरयुक्तसामगानेषु महत्, सारभूतम्, अपरिच्छिन्नम्। गायत्री — सप्तच्छन्दःसु प्रथमा, वेदमाता, अष्टाक्षरत्रिपदा सर्वस्य पञ्चांगभूता(Foundation), वैदिकच्छन्दोरूपेण विशिष्टतया(distinctly) प्रयुक्ता न तु लौकिकी। मार्गशीर्षः — मासानां प्रथमः, गीताजयन्तीमासः, साधनामार्गान्तः। कुसुमाकरः — वसन्तर्तौ कुदृष्ट्याः सुदृष्टिं प्रदाता।",
  "10.36": "द्यूतं छलयतामस्मि तेजस्तेजस्विनामहम्, जयोऽस्मि व्यवसायोऽस्मि सत्त्वं सत्त्ववतामहम्। द्यूतम् — कौरवपाण्डवयुद्धकारणं छलकलासु श्रेष्ठम्, दिवु-क्रीडार्थात् द्यूतशब्दवाच्यः सृष्टिस्थितिसंहारक्रीडारतो भगवान्। जयः — सर्वविजयप्रेरकः। व्यवसायः — उत्साहप्रेरकः। सत्त्वम् — बलनियामकः सद्गुणनिधिः।",
  "10.37": "वृष्णीनां वासुदेवोऽस्मि पाण्डवानां धनञ्जयः, मुनीनामपि अहं व्यासः कवीनामुशना कविः। वासुदेवः — सर्वत्रस्थितः अपरोक्षज्ञानप्रदः प्रत्यक्षीभवति। धनञ्जयः — अर्जुने एकदेशविभूतिः, ज्ञानरूपं शाश्वतं धनं प्रदाता। व्यासः — वेदं सप्तत्रिंशदधिकैकादशशतसंहिताभिः(1137=24+101+12+1000) विभज्य विस्तारकः, विश्वव्यापी ज्ञानसागरप्रदाता। उशना — इच्छामात्रेण सर्वकार्यसाधकः, दैत्यगुरौ शुक्रे स्थितः।",
  "10.38": "दण्डो दमयतामस्मि नीतिरस्मि जिगीषताम्, मौनं चैव अस्मि गुह्यानां ज्ञानं ज्ञानवतामहम्। दण्डः — अपराधिनां निर्दयशिक्षाप्रदाता(Punishment), देवराज्ये क्षमा नास्ति स्वकर्मभोगनियमात्। नीतिः — सर्वनियामिका विजयशक्तिः। मौनः — मननशक्तिरूपः। ज्ञानः — बुद्धिमतां तत्त्वबोधः। इत्यत्र विभूतिविस्तारः समाप्तः; अग्रे उपसंहारः।",
  "10.39": "यच्चापि सर्वभूतानां बीजं तदहमर्जुन, न तदस्ति विना यत्स्यान्मया भूतं चराचरम्। सर्ववस्तुनां (जड-चेतनयोः) अभिव्यञ्जकरूपशक्तिप्रदः बीजपुरुषो भगवान्, अदृश्यजीवाय दृश्यशरीरप्रदः। जीवः भगवत्प्रतिबिम्बः, न तु भगवत्तादात्म्यः; भगवद्विनाशेषा स्वतन्त्रसत्ता कस्यापि नास्ति।",
  "10.40": "नान्तोऽस्ति मम दिव्यानां विभूतीनां परन्तप, एष तूद्देशतः प्रोक्तो विभूतेर्विस्तरो मया। लोकविलक्षणस्य विभूतेः वर्णनं असमाप्यम्; अत्र नित्योपासनार्हं अनुसन्धेयं च संक्षेपेण उक्तम्।",
  "10.41": "यद्यद्विभूतिमत्सत्त्वं श्रीमदूर्जितमेव वा, तत्तदेवावगच्छ त्वं मम तेजोंऽशसम्भवम्। एकैकवस्तुनि अन्यत्र अलभ्यं विशिष्टगुणं भगवत्तेजसः एका स्फुलिङ्गमात्रम्।",
  "10.42": "अथवा बहुनैतेन किं ज्ञातेन तवार्जुन, विष्टभ्याहमिदं कृत्स्नमेकांशेन स्थितो जगत्। पुरुषसूक्तानुसारं भगवतः पादमात्रं जगति व्याप्तम्, त्रिपादमृतांशं दिव्यलोके स्थितम्; इति विभूतियोगाख्यः दशमोऽध्यायः समाप्तः।\n\nइति दशमोऽध्यायः।",
  "11.1": "अर्जुन उवाच-\n\nमदनुग्रहाय परमं गुह्यमध्यात्मसंज्ञितम्।\nयत्त्वयोक्तं वचस्तेन मोहोऽयं विगतो मम -- मत् अनुग्रहाय परमं गुह्यम् अध्यात्मसंज्ञितं यत् त्वया उक्तं वचः, तेन मम अयं मोहः विगतः।\n\nअर्जुनः आह-मत्-अनुग्रहेण अध्यात्मस्य परमगुह्यं विचारं मह्यम् उक्तवान् असि इति। अत्र 'अनुग्रहः' इति शब्देन-स्वस्मात् कनिष्ठान् सन्मार्गे आनीय, उन्नतिं नीत्वा उद्धरणीयाः इति ज्येष्ठानां या इच्छा, सा अभिप्रेता। \"मार्गभ्रष्टं भवन्तं मां सन्मार्गम् आनीय उद्धृतवान् असि\" इति भावम् अर्जुनः व्यक्तीकरोति। अत्र 'मत्' इति पदं प्रयुक्तम्। 'मत्' इति केवलं \"मम\" वा \"मह्यम्\" इत्येव अर्थः न। 'मत्' इति 'यत्' इव प्रयुज्यते। 'मातीति मत्'-इत्यनेन \"सर्वे ज्ञानिनः\" इति अर्थः लभ्यते। अतः 'मदनुग्रहः' इत्यस्य \"सर्वेषां ज्ञानिनाम् उद्धाराय\" इति अर्थः। भगवान् समस्तमानवजातये इदम् अपूर्वं सन्देशं प्रापयितुं गीतां अर्जुनाय उपदिश्य, तां स्वयं व्यासरूपेण निबध्य अस्मभ्यम् अदात्, न तु केवलम् अर्जुनार्थं उक्तवान्।\n\nअस्मिन् जगति अतिगोप्ये स्थापनीया विद्या-अध्यात्मविद्या। सर्वदा अपूर्वं विषयं गोप्यं कुर्वन्ति, यतः तस्य दुरुपयोगः न भवेत्, तन्महत्त्वम् अजानतां च न प्राप्नुयात् इति। अध्यात्मं मनोविज्ञानं, जीवविज्ञानं, परमात्मविज्ञानं च। एतादृशीम् अपूर्वां विद्यां कृष्णः अर्जुनस्य पुरतः उद्घाटितवान् इति कृत्वा अर्जुनः भगवन्तं स्तौति, आह च-\"अनेन मम सर्वं मानसं गोत्रं (सन्देहजालं) निवृत्तं, मोहः च विगतः\" इति।",
  "11.2": "भवाप्ययौ हि भूतानां श्रुतौ विस्तरशो मया।\nत्वत्तः कमलपत्राक्ष माहात्म्यमप्यव्ययम् -- भव अप्ययौ हि भूतानां श्रुतौ विस्तरशः मया, त्वत्तः कमलपत्राक्ष माहात्म्यम् अपि च अव्ययम्।\n\n\"जीवानां भवस्य अप्ययस्य च विस्तरं त्वत्तः श्रुतवान् अस्मि\" इति अर्जुनः आह। अत्र 'भव' 'अप्यय' इति पदाभ्यां जन्ममरणे सृष्टिसंहारौ वा केवलं अर्थः न, अपि तु अन्यः अतीव रोचकः अर्थः विद्यते। वेदकालिकाः ऋषयः इमौ शब्दौ नूतनार्थेन प्रायुञ्जत। \"प्रभवाप्ययौ भूतानाम्\" इति उपनिषदि पठ्यते। सुखप्राप्तिः 'भवः', दुःखनिवृत्तिः च 'अप्ययः'-इति प्राचीनानाम् ऋषीणाम् अयम् अर्थः। \"येन आचरणेन सुखं प्राप्यते, येन च आचरणेन अस्माकं जीवनदुःखात् पारं गम्यते, तं मूलमन्त्रं त्वं स्वमुखेनैव उक्तवान्, तं च मया कर्णाभ्यां श्रुतम्\" इति अर्जुनः आह।\n\nअत्र 'कमलपत्राक्ष' इति विशेषणं प्रयुक्तम्। अस्य प्रयोगे अर्जुनस्य विशेषः भावः वर्तते। \"त्वं मयि करुणारसधाराम् अवर्षयः, हे कृष्ण\" इति भावः अस्य विशेषणस्य पृष्ठभूमौ। \"तव माहात्म्यम् अव्ययम् अनन्तं धनम्। तत् महत् ज्ञानं मह्यं दत्तवान् असि। अतिदुर्लभं तव माहात्म्यं मह्यम् उक्तवान् असि\" इति अर्जुनः आह।",
  "11.3": "एवमेतद्यथात्थ त्वमात्मानं परमेश्वर।\nद्रष्टुमिच्छामि ते रूपमैश्वरं पुरुषोत्तम -- एवम् एतत् यथा आत्मा त्वम् आत्मानं वदसि हे परमेश्वर, द्रष्टुम् इच्छामि ते ऐश्वरं रूपं हे पुरुषोत्तम।\n\n\"त्वया यत् उक्तं तत्र मम कोऽपि संशयः नास्ति\" इति अर्जुनः आह। अत्र अर्जुनः कृष्णं 'परमेश्वरः' इति सम्बोधयति। 'ईश' इति समर्थः इत्यर्थः। अस्मान् नियन्त्रयन्तः देवताः 'ईशाः'। तान् नियन्त्रयन्तौ अन्तःकरणं जीवकलाभिमानिन्यौ देवते-गरुडः, शेषः, रुद्रः, ब्रह्मवायुः च-'ईश्वराः'। एतेषां तत्त्वाभिमानिनां देवतानां नियामकः, सर्वेभ्यः उच्चतरः, सर्वेषाम् अधिपतिः भगवान् 'परमेश्वरः'। \"त्वया उक्ते विचारे मम गोत्रं (सन्देहः) नास्ति, यतः त्वं परमेश्वरः असि। किन्तु मह्यं तव तेन सर्वसामर्थ्येन पूर्णं रूपं द्रष्टुं तीव्रा अभिलाषा जायते\" इति भगवतः अद्भुतं रूपं द्रष्टुम् इति स्वेच्छां अर्जुनः कृष्णस्य पुरतः स्थापयति।\n\nअत्र अर्जुनः भगवन्तं 'पुरुषोत्तमः' इति सम्बोधयति। अस्य पदस्य विशिष्टम् अर्थं कृष्णः पञ्चदशाध्याये (अ-१५, श्लो-१६-१८) विस्तरेण विवृणोति। लोके द्विविधाः पुरुषाः-क्षरपुरुषः अक्षरपुरुषः च। ब्रह्मादयः समस्ताः जीवाः क्षरपुरुषाः। एतत् चराचरसमूहं संयोज्य स्थापयन्ती चित्प्रकृतिः एव अक्षरपुरुषा कथ्यते (अ-१५, श्लो-१७)। अनयोः उभयोः अपि परः-सः पुरुषोत्तमः, तमेव परमात्मानं वदन्ति। सः अव्ययः परमेश्वरः त्रिषु लोकेषु अन्तर्गतः सन् पालयति (अ-१५, श्लो-१७)। क्षरम् अतीत्य स्थितः, अक्षरात् अपि ज्येष्ठः सः नारायणः 'पुरुषोत्तमः' (अ-१५, श्लो-१८)। \"तव पुरुषोत्तमत्वस्य रूपं मया द्रष्टव्यम्\" इति अभिलाषां अर्जुनः कृष्णस्य पुरतः स्थापयति।",
  "11.4": "मन्यसे यदि तच्छक्यं मया द्रष्टुमिति प्रभो।\nयोगेश्वर ततो मे त्वं दर्शयात्मानमव्ययम् -- यदि तत् मया द्रष्टुं शक्यम् इति मन्यसे हे प्रभो, ततः हे योगेश्वर, त्वम् अव्ययम् आत्मानं मे दर्शय।\n\nअर्जुनः अग्रे वदति-\"अहं तव तत् रूपं द्रष्टुं शक्नोमि इति यदि त्वं मन्यसे, तर्हि तव रूपं मह्यं दर्शय\" इति। अत्र अर्जुनः कृष्णं 'प्रभो' इति सम्बोधयति। 'प्रभुः' इति सामर्थ्यम् इत्यर्थः। \"द्रष्टुं सामर्थ्यं मयि न विद्यमानम् अपि, तत् सामर्थ्यं प्रसाद्य दर्शयितुं सामर्थ्यं तव विद्यते\" इति एतस्य सम्बोधनस्य पृष्ठभूमौ भावः। \"यतः त्वं योगेश्वरः असि\" इति अर्जुनः आह। 'योग' इति उपायः इत्यर्थः। \"मह्यं कथं तव रूपं दर्शनीयम् इति उपायः अपि तव ज्ञातः। त्वं सर्वेषाम् उपायानां (योगानां) स्वामी असि। अतः अव्ययं नित्यं तव तत् रूपं मह्यं दर्शय\" इति अर्जुनः कृष्णं प्रार्थयते।",
  "11.5": "श्रीभगवानुवाच-\n\nपश्य मे पार्थ रूपाणि शतशोऽथ सहस्रशः।\nनानाविधानि दिव्यानि नानावर्णाकृतीनि च -- पश्य मे रूपाणि हे पार्थ, शतशः अथ सहस्रशः, नानाविधानि दिव्यानि नानावर्णाकृतीनि च।\n\n\"तव रूपं दर्शय\" इति अर्जुनः एकवचनेन प्रार्थयते, कृष्णः तु बहुवचनेन वदति-\"पश्य मे रूपाणि\" इति। भगवतः सर्वाणि रूपाणि एकमेव। मूलरूपे अवताररूपे च भेदः नास्ति। \"त्वया पूर्वं कदापि अदृष्टानि, अत्यद्भुतानि मम शतशः सहस्रशः, नानाविधानि, दीप्यमानानि, नानावर्णाकृतीनि रूपाणि पश्य\" इति कृष्णः अर्जुनं वदति। अत्र कृष्णः अर्जुनं 'पार्थ' इति सम्बोधयति। सत्यं वेदार्थं ज्ञात्वा वेदार्थभूतस्य भगवतः प्रति यात्रां प्रस्थिताः 'पार्थाः' इति कथ्यन्ते।",
  "11.6": "पश्यादित्यान्वसून्रुद्रानश्विनौ मरुतस्तथा।\nबहून्यदृष्टपूर्वाणि पश्याश्चर्याणि भारत -- पश्य आदित्यान् वसून् रुद्रान् अश्विनौ मरुतः तथा, हे भारत, बहूनि अदृष्टपूर्वाणि आश्चर्याणि पश्य।\n\n\"जगति ये सर्वे आदित्याः (द्वादश आदित्याः), वसवः (अष्ट वसवः), रुद्राः (एकादश रुद्राः), अश्विनौ (द्वौ), मरुतः (एकोनपञ्चाशत्)-तान् सर्वान् पश्य। त्वया पूर्वं कदापि अदृष्टम् अश्रुतं च अत्यद्भुतम् आश्चर्यं पश्य\" इति कृष्णः आह। अत्र कृष्णः अर्जुनं 'भारत' इति सम्बोधयति। ऐतरेयब्राह्मणे \"वायुर्वाव भरतः\" इति वचनम् अस्ति। सदा भगवति निरतस्य वायुदेवस्य 'भरतः' इति नाम। अतः इह 'भारत' इत्यस्य \"भीमस्य (प्राणतत्त्वस्य) अनुजः\" इति अर्थः। [सदा भगवते अतिनिकटस्थस्य हनुमतः प्राणतत्त्वस्य वा उपासना भगवज्ज्ञानस्य सुलभं साधनम्।]",
  "11.7": "इहैकस्थं जगत्कृत्स्नं पश्याद्य सचराचरम्।\nमम देहे गुडाकेश यच्चान्यद्द्रष्टुमिच्छसि -- इह एकस्थं जगत् कृत्स्नं पश्य अद्य सचराचरम्, मम देहे हे गुडाकेश, यत् च अन्यत् द्रष्टुम् इच्छसि (तत् सर्वम्)।\n\n\"मम देहम् आश्रित्य स्थितं समस्तं विश्वं पश्य। ब्रह्माण्डस्य अन्तः यत्किञ्चित् विद्यते, तत् सर्वम् अत्र वर्तते। चेतनम्, अचेतनम्, चलत्, अचलत्, सर्वम्। तव मनः यत् द्रष्टुम् इच्छति, तत् पश्य\" इति कृष्णः आह। अत्र कृष्णः अर्जुनं 'गुडाकेश' इति सम्बोधयति। अज्ञानम् आलस्यं निद्रां च जितवान् 'गुडाकेशः' इति कथ्यते।\n\nअत्र प्रतिश्लोकं भिन्नं भिन्नं विशेषणं प्रयुक्तम्। एतेषां विशेषणानां पृष्ठभूमिं दृष्ट्वा ज्ञायते-अस्मभ्यं भगवज्ज्ञानाय वयम् अपि पार्थाः, भारताः, गुडाकेशाः च भवितव्याः इति। अर्थात्-वेदार्थं ज्ञात्वा वेदार्थभूतस्य प्रति यात्रा (पार्थत्वम्), प्राणतत्त्वस्य उपासना (भारतत्वम्), अज्ञानम् आलस्यं च जित्वा भगवच्चिन्तनम् (गुडाकेशत्वम्)-एतत् सर्वं यदा सम्पद्यते, तदा भगवतः तत् रूपम् अस्माभिः ज्ञायते।",
  "11.8": "न तु मां शक्यसे द्रष्टुमनेनैव स्वचक्षुषा।\nदिव्यं ददामि ते चक्षुः पश्य मे योगमैश्वरम् -- न तु माम् अनेन एव स्वचक्षुषा द्रष्टुं शक्यसे, दिव्यं चक्षुः ते ददामि, पश्य मे ऐश्वरं योगम्।\n\nभगवतः रूपम् अस्माभिः अनेन बाह्येन चक्षुषा द्रष्टुं न शक्यते। स्वरूपभूतः सः भगवान् अस्माभिः स्वस्वरूपभूतेन एव चक्षुषा द्रष्टुं शक्यते। अत्र कृष्णः अर्जुनाय तस्य स्वरूपभूतेन चक्षुषा सर्वसमर्थं भगवन्तं द्रष्टुं सौभाग्यं प्रयच्छति।",
  "11.9": "सञ्जय उवाच-\n\nएवमुक्त्वा ततो राजन्महायोगेश्वरो हरिः।\nदर्शयामास पार्थाय परमं रूपमैश्वरम् -- हे राजन्, एवम् उक्त्वा ततः महायोगेश्वरः हरिः पार्थाय परमम् ऐश्वरं रूपं दर्शयामास।\n\nव्यासात् दिव्यां दृष्टिं प्राप्य, रणभूमौ वर्तमानानां घटनानां वर्णनं धृतराष्ट्राय ददत् सञ्जयः अपि भगवतः विश्वरूपं पश्यति। सः धृतराष्ट्रं वदति-\"हे राजन्, एवम् उक्त्वा महायोगेश्वरः हरिः स्वकीयं परमं रूपं दर्शितवान्\" इति। अत्र प्रयुक्तः 'ततः' इति शब्दः अस्मिन् श्लोके विशेषम् अर्थं ददाति। अर्जुनः दिव्यदृष्ट्या सम्पन्नः आसीत् इति, दिव्यरूपदर्शनस्य अधिकारेण सम्पन्नः आसीत् इति च कारणेन, सर्वत्र व्याप्तः भगवान् स्वकीयं विश्वरूपं तस्मै दर्शितवान्-इति भावं एषः शब्दः ददाति। ब्रह्मादीनां सर्वदेवतानाम् अपि अधिपतिं भगवन्तम् अत्र सञ्जयः 'महायोगेश्वरः' इति सम्बोधयति। अत्र प्रयुक्तः 'हरिः' इति शब्दः भगवतः सर्वगतत्वं विवृणोति। यः यस्यां देवतायां मुखे आहुतिं यच्छति, तां प्रथमं ग्रहीता भगवान् 'हरिः'। अग्रिमे श्लोके सञ्जयः स्वयं दृष्टं भगवतः विश्वरूपं वर्णयति।",
  "11.10": "अनेकवक्त्रनयनमनेकाद्भुतदर्शनम्।\nअनेकदिव्याभरणं दिव्यानेकोद्यतायुधम् -- [एतयोः श्लोकयोः (११.१० तथा ११.११) पदच्छेदः, अर्थः, विवरणं च सह अग्रिमे श्लोके (११.११) दत्तम्।]",
  "11.11": "अनेकवक्त्रनयनमनेकाद्भुतदर्शनम्।\nअनेकदिव्याभरणं दिव्यानेकोद्यतायुधम्।\nदिव्यमाल्याम्बरधरं दिव्यगन्धानुलेपनम्।\nसर्वाश्चर्यमयं देवमनन्तं विश्वतोमुखम् -- अनेकवक्त्रनयनं, अनेकाद्भुतदर्शनं, अनेकदिव्याभरणं, दिव्यानेकोद्यतायुधं, दिव्यमाल्याम्बरधरं, दिव्यगन्धानुलेपनं, सर्वाश्चर्यमयं देवम् अनन्तं विश्वतोमुखं (रूपम्)।\n\nएणिकेयरहितानि आस्यानि, नयनानि च युक्तं रूपम्। एणिकेयरहितानि आश्चर्यदर्शनानि युक्तं रूपम्। एणिकेयरहितानि सुन्दराभरणानि युक्तं रूपम्। एणिकेयरहितानि दीप्यमानायुधानि ऊर्ध्वं धृतानि युक्तं रूपम्। दीप्यमानपुष्पमालाभिः युक्तानि वस्त्राणि धृतवत् रूपम्। दीप्यमानगन्धं लिप्तं रूपम्। सर्वाश्चर्याणां उत्सः। सर्वत्र पूर्णम्, अन्तरहितं रूपम्।\n\nकृष्णः अस्माकं सर्वेषाम् इव मनुष्याकारेण दृश्यमानः आसीत्। किन्तु अस्मिन् क्षणे यत्र यत्र दृश्यते तत्र कृष्णस्य मुखमेव, तत्र सम्मिलितस्य प्रतिजीवस्य अन्तः बहिः च सर्वत्र केवलं कृष्णस्य मुखम् एव दृश्यते स्म। सञ्जयाय तत्र गजाः, अश्वाः, सैनिकाः न दृष्टाः। तत्स्थाने सर्वत्र, सर्वेषाम् अन्तः व्याप्तः सः भगवान् एव दृष्टः। भगवतः इदं रूपं वर्णयितुम् असाध्यम्। इदं केवलं दृष्ट्वा अनुभवनीयम्। तत् एकम् आश्चर्यम्। सर्वाभरणैः शोभमानः, दिव्यानि आयुधानि धारयन्, पुष्पमालायुक्तानि वस्त्राणि परिधाय, दीप्यमानं गन्धं लिप्त्वा, सर्वाश्चर्यस्वरूपः, विस्मयमूर्तिः भगवान् रणभूमौ स्वकीयं विश्वरूपं दर्शितवान्।",
  "11.12": "दिवि सूर्यसहस्रस्य भवेद्युगपदुत्थिता।\nयदि भाः सदृशी सा स्याद्भासस्तस्य महात्मनः -- दिवि सूर्यसहस्रस्य युगपत् उत्थिता भा यदि भवेत्, सा भासः तस्य महात्मनः सदृशी स्यात्।\n\nसञ्जयः आह-\"सहस्रशः सूर्याः आकाशे युगपत् उदयेयुः यावत् प्रकाशमानाः स्युः, तादृशः प्रकाशमानः भगवान् दृष्टः\" इति। योगिभ्यः भगवान् अन्तश्चक्षुषा सहस्रसूर्याणाम् एककालम् उदये यावान् प्रखरः स्यात् तावान् प्रखरः दृश्यते। किन्तु 'चन्द्रांशुः' भगवान् तावान् एव शीतलः आह्लादकः च। भगवान् सूर्यवत् प्रखरः, चन्द्रवत् च शीतलः। एतावता प्रकाशमानस्य भगवतः रूपं कोऽपि कदापि स्वबाह्यचक्षुषा द्रष्टुं न शक्नोति।",
  "11.13": "तत्रैकस्थं जगत्कृत्स्नं प्रविभक्तमनेकधा।\nअपश्यद्देवदेवस्य शरीरे पाण्डवस्तदा -- तत्र अनेकधा प्रविभक्तं कृत्स्नं जगत् देवदेवस्य शरीरे एकस्थं पाण्डवः तदा अपश्यत्।\n\nभगवता अर्जुनाय रणभूमौ दर्शितं विश्वरूपं अतीव विशिष्टम्। मध्वाचार्याः यथा वदन्ति, अर्जुनाय विश्वरूपदर्शने जाते, जगति भगवतः विश्वरूपदर्शनम् अर्हद्भ्यः सर्वेभ्यः अपि तत् दर्शनम् अभवत्। [त्रिषु लोकेषु वर्तमानेभ्यः अर्हेभ्यः समस्तजीवेभ्यः अपि भगवतः इदं विशेषदर्शनम् अभवत् इति वचनम् अस्मिन्नेव अध्याये अग्रे आगमिष्यति।] अर्जुनाय अत्र दृष्टं केवलं सर्वत्र व्याप्तः भगवान् एव न, अपि तु तस्य अन्तः व्याप्तं जगदपि। [अत्र भगवतः अन्तः विश्वं दर्शनं नाम ध्याने परमात्मानं, तेन सृष्टां सृष्टिं च युगपत् दृष्टवत्। सत्त्वेन विशुद्धमनस्कः अर्जुनः (पाण्डवः) स्वदिव्यदृष्ट्या भगवति व्याप्तं सम्पूर्णं विश्वं स्पष्टतया अपश्यत्।]",
  "11.14": "ततः स विस्मयाविष्टो हृष्टरोमा धनञ्जयः।\nप्रणम्य शिरसा देवं कृताञ्जलिरभाषत -- ततः सः विस्मयाविष्टः हृष्टरोमा धनञ्जयः देवं शिरसा प्रणम्य कृताञ्जलिः अभाषत।\n\nभगवतः इदम् अद्भुतं रूपं दृष्ट्वा अर्जुनः आनन्देन आश्चर्येण दिग्भ्रमेण च रोमाञ्चितः सन् अतिष्ठत्। भगवतः अपूर्वम् एतादृशम् अद्भुतदर्शनसम्पदं (धनम्) प्राप्तवान् सः (धनञ्जयः), भक्तिपूर्वकम् उद्दण्डनमस्कारं कृत्वा, स्वयोः द्वयोः हस्तयोः अञ्जलिं बद्ध्वा तिष्ठन्, भगवन्तं स्तोतुम् आरब्धवान्।",
  "11.15": "अर्जुन उवाच-\n\nपश्यामि देवांस्तव देव देहे सर्वांस्तथा भूतविशेषसङ्घान्।\nब्रह्माणमीशं कमलासनस्थं ऋषींश्च सर्वानुरगांश्च दिव्यान् -- पश्यामि देवान् तव देव देहे सर्वान्, तथा भूतविशेषसङ्घान्, ब्रह्माणम् ईशं कमलासनस्थम्, ऋषीन् च सर्वान्, उरगान् च दिव्यान्।\n\nअर्जुनः कृष्णस्य अत्यद्भुतं रूपं पश्यति। तस्मै समस्ताः देवताः तस्मिन् भगवति दृश्यन्ते। देवताः, राक्षसाः, असुराः, गन्धर्वाः, अप्सरसः, यक्षाः, मनुष्याः, प्राणिनः-एवं सर्वे। मुख्यतया अर्जुनः भगवति चतुर्मुखं ब्रह्माणम्, तस्य ऊर्वोः उपविष्टं शिवम्, महर्षीन्, देवांशसम्भूतान् दिव्यान् उरगान् च तस्मिन् शेषशायिनि भगवति पश्यति।",
  "11.16": "अनेकबाहूदरवक्त्रनेत्रं पश्यामि त्वां सर्वतोऽनन्तरूपम्।\nनान्तं न मध्यं न पुनस्तवादिं पश्यामि विश्वेश्वर विश्वरूप -- अनेकबाहूदरवक्त्रनेत्रं त्वां सर्वतः अनन्तरूपं पश्यामि। हे विश्वेश्वर विश्वरूप, न अन्तं न मध्यं न पुनः तव आदिं पश्यामि।\n\nएणिकारहिताः बाहवः, उदराणि, वक्त्राणि, नयनानि च। सर्वत्र एणिकारहितरूपं त्वां पश्यामि। हे भूमेः स्वामिन्, हे विश्वरूप, तव अन्तः न दृश्यते; न मध्यम्; न आदिरपि।\n\nयत्र यत्र दृष्टं तत्र तत्र मुखम्, यत्र यत्र दृष्टं तत्र तत्र नयनम्, यत्र यत्र दृष्टं तत्र तत्र बाहुः, यत्र यत्र दृष्टं तत्र तत्र उदरम्। अयं श्लोकः पुरुषसूक्तस्य व्याख्यानरूपेण वर्तते। पुरुषसूक्ते यथोक्तम्-\"ॐ सहस्रशीर्षा पुरुषः। सहस्राक्षः सहस्रपात्\" इति-भगवतः सहस्राणि शिरांसि, सहस्राणि नयनानि, सहस्राणि पादाः। यत्र यत् द्रष्टुम् इच्छन् अर्जुनः दृष्टवान्, तत्र तत् एव तस्मै दृष्टम्। इदम् एकं विचित्रम् अनुभवम्। इदं विवरीतुम् असाध्यम्। केवलम् अनुभवनीयम्। अनन्तरूपिणः भगवतः रूपस्य न अन्तः न मूलम्। समस्तजगत्स्वामी भगवान् अणोः अपि अणुः, महतः अपि महत्तमः। भगवतः इदं रूपं ध्याने द्रष्टुं अतीव कष्टम्। शास्त्रकाराः यथा वदन्ति, ध्याने भगवतः पूर्णशरीरं द्रष्टव्यम् इति मत्वा उपविशन्तः किमपि न द्रक्ष्यन्ति इति सम्भवति। अतः वेणुं वादयतः तस्य कनिष्ठिकायाः अग्रे वा, तस्य करुणापूर्णे नेत्रदृष्टौ वा मनः केन्द्रीकृत्य ध्यानाभ्यासः करणीयः।",
  "11.17": "किरीटिनं गदिनं चक्रिणं च तेजोराशिं सर्वतो दीप्तिमन्तम्।\nपश्यामि त्वां दुर्निरीक्ष्यं समन्ताद्दीप्तानलार्कद्युतिमप्रमेयम् -- किरीटिनं गदिनं चक्रिणं च, सर्वतः दीप्तिमन्तं तेजोराशिं त्वां पश्यामि, समन्तात् दुर्निरीक्ष्यं दीप्तानलार्कद्युतिम् अप्रमेयम्।\n\nशिरसि किरीटम्। हस्तयोः गदा चक्रं च। तेजसः पिण्डवत् सर्वत्र देदीप्यमानं रूपम्। दहनशीलाग्निवत्, सूर्यवत् च प्रकाशयुक्तम्, अप्रमेयं रूपम्। चक्षुःपीडकं तव तत् रूपं समन्तात् एव पश्यामि।\n\nएकतः सर्वाभरणभूषितं मनोमोहकं रूपम्, अन्यतः चक्रगदाधरं शत्रुभयङ्करं रूपम्। एवं सर्वं तेजःपुञ्जवत् दृश्यते। अदृश्यं स्पष्टतया पश्यतः अनुभवः एषः। तत् दहनाग्निः वा उद्दीप्तसूर्यः वा इति न ज्ञायते। तत् अप्रमेयम् अज्ञेयम् अत्यद्भुतम् अपूर्वं रूपम्।",
  "11.18": "त्वमक्षरं परमं वेदितव्यं त्वमस्य विश्वस्य परं निधानम्।\nत्वमव्ययः शाश्वतधर्मगोप्ता सनातनस्त्वं पुरुषो मतो मे -- त्वम् अक्षरं परमं वेदितव्यम्, त्वम् अस्य विश्वस्य परं निधानम्, त्वम् अव्ययः शाश्वतधर्मगोप्ता, सनातनः त्वं पुरुषः मे मतः।\n\n\"त्वम् अक्षरं परमम्\" इति अर्जुनः आह। अत्र 'अक्षरम्' इति सर्वव्याप्तं, नाशरहितं तत्त्वम्, सर्वाभीष्टप्रदम्, सर्वशब्दवाच्यम् इत्यादि। अस्माभिः ज्ञातव्येषु सर्वश्रेष्ठं तत्-भगवान्। अर्जुनः आह-\"त्वं सम्पूर्णस्य जगतः स्रष्टा, आश्रयदाता। समस्तस्य जगतः मूलाश्रयः। अनादिअनन्तकाले शाश्वतं धर्मं रक्षसि त्वम्। समस्तवेदप्रतिपाद्यः त्वम् एव इति मह्यं मनोगतम् अभवत्\" इति। [अस्मिन् श्लोके आगतानां विशेषपदानाम् (अक्षरः, पुरुषः, अव्ययः, शाश्वतधर्मः इत्यादीनाम्) विशेषार्थः पूर्वाध्यायेषु विश्लेषितः, अतः इह पुनः तद्विवरणं न दत्तम्।]",
  "11.19": "अनादिमध्यान्तमनन्तवीर्यमनन्तबाहुं शशिसूर्यनेत्रम्।\nपश्यामि त्वां दीप्तहुताशवक्त्रं स्वतेजसा विश्वमिदं तपन्तम् -- अनादिमध्यान्तम् अनन्तवीर्यम् अनन्तबाहुं शशिसूर्यनेत्रं त्वां पश्यामि, दीप्तहुताशवक्त्रं स्वतेजसा इदं विश्वं तपन्तम्।\n\nगुणानां आदिः मध्यम् अन्तः च न विद्यते। त्वम् अनन्तवीर्यः। आदिअन्तरहितं पराक्रमं तव। नाशरहितानि अनन्तानि अवयवानि। तव नयनाभ्यां जातौ तौ सूर्यचन्द्रौ; तव वदने उद्गिरन्ती अग्निज्वाला। तव तेजसा सम्पूर्णं विश्वं दह्यमानम् इव प्रतिभाति।",
  "11.20": "द्यावापृथिव्योरिदमन्तरं हि व्याप्तं त्वयैकेन दिशश्च सर्वाः।\nदृष्ट्वाद्भुतं रूपमुग्रं तवेदं लोकत्रयं प्रव्यथितं महात्मन् -- द्यावापृथिव्योः इदम् अन्तरं हि त्वया एकेन व्याप्तम्, दिशः च सर्वाः, हे महात्मन्, तव इदम् अद्भुतम् उग्रं रूपं दृष्ट्वा लोकत्रयं प्रव्यथितम्।\n\nतव रूपं भूमिं आकाशं च व्याप्य स्थितम्। सर्वासु दिक्षु अनन्तं व्याप्तं तव रूपं पश्यामि। त्रिषु लोकेषु तव रूपं दृष्टवन्तः तव इदम् उग्रं रूपं दृष्ट्वा व्यथिताः भवन्ति। जगत् कम्पते-इति दिग्भ्रमेण अर्जुनः स्वानुभवं भगवति निवेदयति।",
  "11.21": "अमी हि त्वां सुरसङ्घा विशन्ति केचिद्भीताः प्राञ्जलयो गृणन्ति।\nस्वस्तीत्युक्त्वा महर्षिसिद्धसङ्घाः स्तुवन्ति त्वां स्तुतिभिः पुष्कलाभिः -- अमी हि सुरसङ्घाः त्वां विशन्ति, केचित् भीताः प्राञ्जलयः गृणन्ति। स्वस्ति इति उक्त्वा महर्षिसिद्धसङ्घाः पुष्कलाभिः स्तुतिभिः त्वां स्तुवन्ति।\n\nकेचित् त्वदन्तः प्रविशन्ति, अन्ये बहिः निर्गच्छन्ति। केचित् अञ्जलिं बद्ध्वा तव स्तोत्रं कुर्वन्ति। ज्ञानिनः तव इदम् अद्भुतं रूपं दृष्ट्वा \"जगते मङ्गलं भूयात्\" इति आशिषं ददति। ऋषिमुनयः नानाविधैः स्तोत्रैः त्वां समूहशः स्तुवन्ति।",
  "11.22": "रुद्रादित्या वसवो ये च साध्या विश्वेऽश्विनौ मरुतश्चोष्मपाश्च।\nगन्धर्वयक्षासुरसिद्धसङ्घा वीक्षन्ते त्वां विस्मिताश्चैव सर्वे -- रुद्राः आदित्याः वसवः ये च साध्याः विश्वेदेवाः अश्विनौ मरुतः च ऊष्मपाः च, गन्धर्वयक्षासुरसिद्धसङ्घाः च सर्वे विस्मिताः त्वां वीक्षन्ते।\n\nएकादश रुद्राः, द्वादश आदित्याः, अष्ट वसवः, साध्याः, विश्वेदेवाः, अश्विनौ, मरुतः, पितरः, गन्धर्वाः, देवगणप्रविष्टाः यक्षाः, असुराः, सिद्धाः-एते सर्वे निर्निमेषं त्वां पश्यन्ति इति अर्जुनः आह।",
  "11.23": "रूपं महत्ते बहुवक्त्रनेत्रं महाबाहो बहुबाहूरुपादम्।\nबहूदरं बहुदंष्ट्राकरालं दृष्ट्वा लोकाः प्रव्यथितास्तथाहम् -- हे महाबाहो, बहुवक्त्रनेत्रं, बहुबाहूरुपादं, बहूदरं, बहुदंष्ट्राकरालं ते महत् रूपं दृष्ट्वा लोकाः प्रव्यथिताः, तथा अहम्।\n\nभगवतः अङ्गाङ्गेषु सृष्टिक्रिया कथं प्रवर्तते इति अर्जुनः पश्यति। पुरुषसूक्ते यथोक्तम्-\"ब्राह्मणोऽस्य मुखमासीत्, बाहू राजन्यः कृतः, ऊरू तदस्य यद्वैश्यः, पद्भ्यां शूद्रो अजायत\" इति (१३)। अर्थात् भगवतः मुखात् ज्ञानिनां (Wisdom) सृष्टिः, बाहुभ्यां क्षत्रियाणां (Protection) सृष्टिः, कट्याः ऊरोः वा वैश्यानां (Production) सृष्टिः, पवित्रात् पादात् च शूद्राणां (Service) सृष्टिः। एतानि चत्वारि वर्गाणि अस्य समाजस्य चत्वारः आधारस्तम्भाः। अर्जुनाय एषा चतुर्विधवर्गसृष्टिः भगवतः देहे एव भवन्ती दृश्यते। तेन सह सः तत्र सर्वान् ग्रसमानं (संहारक्रियारूपम्) बहुदंष्ट्राभिः पूर्णं रूपं च पश्यति। भगवतः इदं रूपं दृष्ट्वा सर्वे विस्मिताः जाताः। \"अहम् अपि व्याकुलः अस्मि\" इति अर्जुनः आह।",
  "11.24": "नभःस्पृशं दीप्तमनेकवर्णं व्यात्ताननं दीप्तविशालनेत्रम्।\nदृष्ट्वा हि त्वां प्रव्यथितान्तरात्मा धृतिं न विन्दामि शमं च विष्णो -- नभःस्पृशं दीप्तम् अनेकवर्णं व्यात्ताननं दीप्तविशालनेत्रं त्वां दृष्ट्वा हि मम अन्तरात्मा प्रव्यथितः, धृतिं शमं च न विन्दामि, हे विष्णो।\n\nभूमौ आकाशे च व्याप्तं तव अनन्तं रूपम्-अन्धकारस्पर्शरहितः तेजःपुञ्जः। त्वदन्तः अनेके अनेकैः श्रुतिवचनैः वेदैः च त्वां वर्णयन्ति। तव अप्राकृतं वर्णं पश्यामि। तव अनुग्रहवर्षिणी, करुणया विकसिते नेत्रे अपि दृष्टे। सर्वं दृष्ट्वा मनः क्षुब्धं भवति। \"हे विष्णो, तव इदं विचित्रं रूपं बोद्धुं न शक्नोमि\" इति अर्जुनः आह। ['विष्णु' इति पदस्य विशिष्टः अर्थः पूर्वाध्याये अस्माभिः विश्लेषितः।]",
  "11.25": "दंष्ट्राकरालानि च ते मुखानि दृष्ट्वैव कालानलसन्निभानि।\nदिशो न जाने न लभे च शर्म प्रसीद देवेश जगन्निवास -- दंष्ट्राकरालानि च ते मुखानि कालानलसन्निभानि दृष्ट्वा एव दिशः न जाने, शर्म च न लभे। प्रसीद, हे देवेश जगन्निवास।\n\nसर्वेभ्यः अधिकं नरसिंहवत् दंष्ट्राभिः व्यात्तवदनं तव मुखं दृष्ट्वा दिक् न सूचिता। प्रलयकालाग्निवत् व्याप्तं त्वां दृष्ट्वा भीत्या आनन्दः अन्तर्हितः भवति। शान्तिं त्यजामि। हे सर्वदेवतानाम् अधिपते, जगतः आश्रयभूत, मयि दयां कुरु।",
  "11.26": "अमी च त्वां धृतराष्ट्रस्य पुत्राः सर्वे सहैवावनिपालसङ्घैः।\nभीष्मो द्रोणः सूतपुत्रस्तथासौ सहास्मदीयैरपि योधमुख्यैः -- [एतयोः श्लोकयोः (११.२६ तथा ११.२७) पदच्छेदः, अर्थः, विवरणं च सह अग्रिमे श्लोके (११.२७) दत्तम्।]",
  "11.27": "वक्त्राणि ते त्वरमाणा विशन्ति दंष्ट्राकरालानि भयानकानि।\nकेचिद्विलग्ना दशनान्तरेषु सन्दृश्यन्ते चूर्णितैरुत्तमाङ्गैः -- भीष्मः द्रोणः सूतपुत्रः तथा असौ अस्मदीयैः अपि योधमुख्यैः सह, ते दंष्ट्राकरालानि भयानकानि वक्त्राणि त्वरमाणाः विशन्ति। केचित् दशनान्तरेषु विलग्नाः चूर्णितैः उत्तमाङ्गैः सन्दृश्यन्ते।\n\nअर्जुनः भगवति भाविकाले घटिष्यमाणाः घटनाः पश्यति। जगति सर्वं पूर्वनिर्धारितम्। एतत् अर्जुनः स्वदिव्यदृष्ट्या केवलं पश्यति। भीष्मः द्रोणः कर्णः च सर्वे तव मुखम् एव प्रविशन्ति। सह अस्मदीयसैन्यस्य मुख्याः अपि। तत्र केचित् तव भयानकाभिः दंष्ट्राभिः निगृहीताः चूर्णिताः भवन्तः दृश्यन्ते।",
  "11.28": "यथा नदीनां बहवोऽम्बुवेगाः समुद्रमेवाभिमुखा द्रवन्ति।\nतथा तवामी नरलोकवीरा विशन्ति वक्त्राण्यभिविज्वलन्ति -- यथा नदीनां बहवः अम्बुवेगाः समुद्रम् एव अभिमुखाः द्रवन्ति, तथा तव अमी नरलोकवीराः अभिविज्वलन्ति वक्त्राणि विशन्ति।\n\nपुण्यजीवाः भगवतः मुखं कथं प्रविशन्ति इति अर्जुनः वर्णयति। यथा सर्वाः नदीनां जलधाराः समुद्रं प्रविशन्ति, तथैव इमे नरलोकस्य वीराः त्वां प्रविशन्ति इति अर्जुनः आह। एषः एकः माङ्गलिकः दृष्टान्तः। अत्र भयानकं दृश्यं नास्ति।",
  "11.29": "यथा प्रदीप्तं ज्वलनं पतङ्गा विशन्ति नाशाय समृद्धवेगाः।\nतथैव नाशाय विशन्ति लोकास्तवापि वक्त्राणि समृद्धवेगाः -- यथा पतङ्गाः समृद्धवेगाः नाशाय प्रदीप्तं ज्वलनं विशन्ति, तथा एव लोकाः समृद्धवेगाः तव अपि वक्त्राणि नाशाय विशन्ति।\n\nपापिनः कथं भगवतः मुखं प्रविशन्ति इति वर्णयन् अर्जुनः आह-\"यथा ज्वलत् अग्नौ पतङ्गाः पतित्वा नश्यन्ति, तथा त्वरमाणाः आगत्य पतित्वा नश्यन्ति\" इति।",
  "11.30": "लेलिह्यसे ग्रसमानः समन्ताल्लोकान्समग्रान्वदनैर्ज्वलद्भिः।\nतेजोभिरापूर्य जगत्समग्रं भासस्तवोग्राः प्रतपन्ति विष्णो -- हे विष्णो, ज्वलद्भिः वदनैः समन्तात् समग्रान् लोकान् ग्रसमानः लेलिह्यसे, तेजोभिः जगत् समग्रम् आपूर्य तव उग्राः भासः प्रतपन्ति।\n\nसर्वं तव जिह्वया लेह्यमानं ग्रस्यते, सर्वं तव उदरं प्रविशति। इदं जगत् एव तव एकः ग्रासः भवति। तव देहस्य तत् तेजः जगतः सर्वत्र व्याप्नोति। सर्वेषाम् अन्तः बहिः च व्याप्तः त्वं सर्वसंहारकः (विष्णुः) इव दृश्यसे।",
  "11.31": "आख्याहि मे कः भवानुग्ररूपो नमोऽस्तु ते देववर प्रसीद।\nविज्ञातुमिच्छामि भवन्तमाद्यं न हि प्रजानामि तव प्रवृत्तिम् -- आख्याहि मे कः भवान् उग्ररूपः, नमः अस्तु ते हे देववर, प्रसीद। विज्ञातुम् इच्छामि भवन्तम् आद्यम्, न हि प्रजानामि तव प्रवृत्तिम्।\n\nतव इदं भयङ्करं रूपं दृष्ट्वा मह्यं किमपि न अवगम्यते। तव माहात्म्यम् अज्ञातवान् अस्मि। त्वयि शरणम् आगतः अस्मि। माम् उद्धर। इदं भयङ्करं रूपं धृतवन्तं त्वां ज्ञातुम् इच्छामि-इति अर्जुनः कृष्णं याचमानः प्रार्थयते।",
  "11.32": "भगवानुवाच-\n\nकालोऽस्मि लोकक्षयकृत्प्रवृद्धो लोकान्समाहर्तुमिह प्रवृत्तः।\nऋतेऽपि त्वां न भविष्यन्ति सर्वे येऽवस्थिताः प्रत्यनीकेषु योधाः -- कालः अस्मि लोकक्षयकृत् प्रवृद्धः, लोकान् समाहर्तुम् इह प्रवृत्तः। ऋते अपि त्वां न भविष्यन्ति सर्वे ये अवस्थिताः प्रति-अनीकेषु योधाः।\n\nकृष्णः आह-\"अहं कालपुरुषः इति स्थितः अस्मि\" इति। 'कल्' धातुतः निष्पन्नः 'काल' इति शब्दः बहून् अर्थान् ददाति-सर्वसंहारकः, सर्वगुणपूर्णः, सर्वज्ञः इत्यादयः। अत्र विशेषतः कृष्णः संहारशक्तिरूपेण स्थितः। \"अहं तव सारथिः भूत्वा, भूमेः भारभूतान् एतान् समापयितुम् एव स्थितः अस्मि\" इति कृष्णः आह। महाभारतयुद्धं दृष्ट्वा, तत् एकं महायुद्धम् आसीत्। तत्र सुमारेण पञ्चाशल्लक्षजनाः मृताः। तदानीन्तनस्य देशस्य जनसङ्ख्यायाः विचारे तत् समग्रजनसङ्ख्यायाः सुमारेण दशमः भागः। भागवते यथोक्तम्-कालपुरुषरूपेण स्थितः कृष्णः किमपि आयुधं न गृहीत्वा सर्वेषाम् आयुः स्वचक्षुषा एव आकृष्टवान्। अतः कृष्णः अर्जुनं वदति-\"त्वयि न विद्यमानेऽपि एते सर्वे (उभयपक्षीयाः) मरिष्यन्ति। तेषां मृत्युः निश्चितः जातः\" इति।",
  "11.33": "तस्मात्त्वमुत्तिष्ठ यशो लभस्व जित्वा शत्रून्भुङ्क्ष्व राज्यं समृद्धम्।\nमयैवैते निहताः पूर्वमेव निमित्तमात्रं भव सव्यसाचिन् -- तस्मात् त्वम् उत्तिष्ठ, यशः लभस्व, शत्रून् जित्वा समृद्धं राज्यं भुङ्क्ष्व। मया एव एते पूर्वम् एव निहताः, हे सव्यसाचिन्, निमित्तमात्रं भव।\n\nअर्जुनम् कृष्णः उत्साहयति। उत्तिष्ठ, युद्धाय सज्जः भव। अस्मिन् युद्धे त्वं जेष्यसि। एतान् शत्रून् संहर, यतः मया एते पूर्वमेव हताः। अत्र त्वं केवलं निमित्तमात्रम्। स्वभागे आगतं कर्तव्यं निर्वहन्, स्वभागस्य प्रारब्धसुखम् अनुभव।",
  "11.34": "द्रोणं च भीष्मं च जयद्रथं च कर्णं तथान्यानपि योधवीरान्।\nमया हतांस्त्वं जहि मा व्यथिष्ठा युध्यस्व जेतासि रणे सपत्नान् -- द्रोणं च भीष्मं च जयद्रथं च कर्णं तथा अन्यान् अपि योधवीरान्, मया हतान् त्वं जहि, मा व्यथिष्ठाः, युध्यस्व, रणे सपत्नान् जेता असि।\n\nअत्र सम्मिलितानां द्रोणस्य भीष्मस्य जयद्रथस्य कर्णस्य च एतेषां सर्वेषाम् आयुः मया आकृष्टम्। अतः तेन कारणेन त्वं दुःखितः भवितुं न अर्हसि। एषा जीवनतरङ्गः अनिवार्यः। एतां केनापि निवारयितुं न शक्यते। अतः उत्थाय युध्यस्व। त्वम् अस्मिन् धर्मयुद्धे जेष्यसि। मम रक्षायाः पूर्णः प्रसादः तव सह वर्तते-इति कृष्णः आशीर्वदति।\n\nपूर्वं \"सेनयोरुभयोर्मध्ये रथं स्थापय मेऽच्युत\" इति अहङ्कारेण भाषितवान् अर्जुनः, पश्चात् स्वपुरतः स्थितान् गुरुजनान् दृष्ट्वा दीनः सन् युद्धं मा भूत् इति स्थितवान्। एते द्वे अपि अवस्थे कस्याश्चित् वस्तुस्थितेः अनवगमेन कृते निर्णये आस्ताम्। अस्मात् कारणात् कृष्णः एतेषु दशसु अध्यायेषु अर्जुनाय उपदिश्य, युद्धं नाम 'धर्मः' इति मनसि निश्चितवान्। इदानीं स्वकीयं विश्वरूपदर्शनं दत्त्वा-\"त्वं केवलं निमित्तमात्रम्\" इति उक्तवान्। कृष्णस्य तत् भयङ्करं रूपं, तस्य च वचनं श्रुत्वा अर्जुनः किं कृतवान् इति सञ्जयः अग्रिमे श्लोके वर्णयति।",
  "11.35": "सञ्जय उवाच-\n\nएतच्छ्रुत्वा वचनं केशवस्य कृताञ्जलिर्वेपमानः किरीटी।\nनमस्कृत्वा भूय एवाह कृष्णं सगद्गदं भीतभीतः प्रणम्य -- एतत् श्रुत्वा वचनं केशवस्य, कृताञ्जलिः वेपमानः किरीटी, नमस्कृत्वा भूयः एव आह कृष्णं सगद्गदं भीतभीतः प्रणम्य।\n\nकृष्णस्य वचनं श्रुत्वा अर्जुनः भक्त्या भगवते अञ्जलिं बद्ध्वान्। अस्यां अवस्थायां सः कम्पमानः वेपमानः च तिष्ठति। स्वसर्वाङ्गैः भगवते नमस्कृत्य, गद्गदः सन् भाषितवान्।\n\nअत्र सञ्जयः भगवन्तं 'केशव' 'कृष्ण' इति च सम्बोधयति। केशवः इति जगतः सृष्टिसंहारयोः मूले स्थिताः शक्तयः ब्रह्मरुद्रौ सृष्टिसंहारयोः नियोज्य नियन्त्रयन् इति अर्थः। समस्तजीवजातस्य अन्तः स्थित्वा तान् नियन्त्रयन् सर्वान्तर्यामी भगवान् केशवः। अपि च 'कृष्णः' इति भगवतः मूलनामापि। अस्माकम् अहङ्कारं, अज्ञानं च कर्षयन्, सम्पूर्णं लोकम् आकर्षयन्, संसारात् अस्मान् कर्षयन् भगवान् 'कृष्णः'।",
  "11.36": "अर्जुन उवाच-\n\nस्थाने हृषीकेश तव प्रकीर्त्या जगत्प्रहृष्यत्यनुरज्यते च।\nरक्षांसि भीतानि दिशो द्रवन्ति सर्वे नमस्यन्ति च सिद्धसङ्घाः -- स्थाने हे हृषीकेश, तव प्रकीर्त्या जगत् प्रहृष्यति अनुरज्यते च। रक्षांसि भीतानि दिशः द्रवन्ति, सिद्धसङ्घाः च सर्वे नमस्यन्ति।\n\nपूर्वं यथोक्तम्-अर्जुनाय विश्वरूपदर्शने जाते, सम्पूर्णे विश्वे अनेकेभ्यः ज्ञानिभ्यः देवेभ्यः अपि इदम् अपूर्वं भगवद्रूपदर्शनम् अभवत्। अर्जुनः स्वान्तरङ्गे स्वस्मै दृश्यमानं विचारं वदति। एतावता न, अपि तु बाह्या वस्तुस्थितिः अपि तस्मै भगवति दृश्यते। तत् अर्जुनः इह विवृणोति-\"ऋषयः ज्ञानिनः च तव गुणगानं कुर्वन्ति। त्वां सम्भाव्य रोमाञ्चिताः भवन्ति। दुष्टशक्तयः त्वां दृष्ट्वा भीताः द्रवन्ति। सात्त्विकाः सिद्धाः च नृत्यन्ति उत्पतन्ति च। एतत् सर्वं युक्तम् एव\" इति।",
  "11.37": "कस्माच्च ते न नमेरन्महात्मन्गरीयसे ब्रह्मणोऽप्यादिकर्त्रे।\nअनन्त देवेश जगन्निवास त्वमक्षरं सदसत्तत्परं यत् -- कस्मात् च ते न नमेरन् हे महात्मन्, गरीयसे ब्रह्मणः अपि आदिकर्त्रे। हे अनन्त देवेश जगन्निवास, त्वम् अक्षरं सत् असत् तत्परं यत्।\n\nत्वां ज्ञातवन्तः तुभ्यं नमस्कारं न कुर्युः इति असम्भवम्। त्वं परिपूर्णः आत्मा। अस्य जगतः पिता यः चतुर्मुखः, तस्य अपि पिता त्वम्। एतादृशाय तुभ्यं नमस्कारम् अकृत्वा स्थातुं न शक्यते। त्वं देशेन कालेन गुणैः च अनन्तः। त्वं सर्वेषाम् अन्तः बहिः च व्याप्तः जगन्निवासः। त्वं निर्धारितः... दोषरहितः च ज्ञानानन्दमूर्तिः (सत्)। अव्यक्तमूर्तिं त्वां (असत्) बहिश्चक्षुषा द्रष्टुं न शक्नुमः। त्वम् अक्षरः, त्वं देवेशः, त्वं कारणानाम् अपि कारणम्, त्वं जगतः आश्रयः।",
  "11.38": "त्वमादिदेवः पुरुषः पुराणस्त्वमस्य विश्वस्य परं निधानम्।\nवेत्तासि वेद्यं च परं च धाम त्वया ततं विश्वमनन्तरूप -- त्वम् आदिदेवः पुरुषः पुराणः, त्वम् अस्य विश्वस्य परं निधानम्। वेत्ता असि वेद्यं च परं च धाम, त्वया ततं विश्वम् अनन्तरूप।\n\nत्वम् आदिदेवः, त्वं पुराणपुरुषः, अस्मिन् जगति अन्तिमम् आश्रयः त्वम्। सर्वैः ज्ञातव्यः, स्वयं सर्वज्ञः त्वं सर्वातिशायि परंधाम। अनन्तरूपः त्वं सम्पूर्णं विश्वं व्याप्य स्थितः असि।",
  "11.39": "वायुर्यमोऽग्निर्वरुणः शशाङ्कः प्रजापतिस्त्वं प्रपितामहश्च।\nनमो नमस्तेऽस्तु सहस्रकृत्वः पुनश्च भूयोऽपि नमो नमस्ते -- वायुः यमः अग्निः वरुणः शशाङ्कः प्रजापतिः त्वं प्रपितामहः च। नमः नमः ते अस्तु सहस्रकृत्वः, पुनः च भूयः अपि नमः नमः ते।\n\n[व-इति बलरूपम्, आया-इति ज्ञानरूपम्। अतः 'वायुः'। सर्वं नियमयति इति 'यमः'। अग-इति निश्चलं विश्वम्, तस्मै चलनं ददाति इति 'अग्निः'। भक्तान् वरणं करोति इति 'वरुणः'। शश-इति अतिशयानन्दः, तेन अङ्कितः इति 'शशाङ्कः'। प्रजानां पतिः (पालकः) इति 'प्रजापतिः'।] त्वम् एव जगतः प्रपितामहः। सहस्रकृत्वः तुभ्यं नमोनमः। पुनः च भूयः अपि तुभ्यं वन्दनं वन्दनम्।",
  "11.40": "नमः पुरस्तादथ पृष्ठतस्ते नमोऽस्तु ते सर्वत एव सर्व।\nअनन्तवीर्यामितविक्रमस्त्वं सर्वं समाप्नोषि ततोऽसि सर्वः -- नमः पुरस्तात्, अथ पृष्ठतः ते नमः अस्तु, ते सर्वतः एव, हे सर्व। अनन्तवीर्य अमितविक्रमः त्वं सर्वं समाप्नोषि, ततः असि सर्वः।\n\nभगवतः विश्वरूपे तस्य पुरोभागः कः, पृष्ठभागः कः इति कथं ज्ञायताम्। इदम् असम्भवम्। अतः अर्जुनः आह-तुभ्यम् एदुरतः नमस्कारः, तव पृष्ठभागात् नमस्कारः, सर्वत्र व्याप्ताय तुभ्यं सर्वतः नमस्कारः। त्वम् अनन्तवीर्यः। त्वम् अमितविक्रमः। हे सर्व, तुभ्यं नमस्कारः। जगतः समस्तजीवजातस्य सृष्टेः कारणभूताय, सर्वत्र व्याप्ताय जगतः नियामकाय अस्मै अनन्तशक्तये नमस्कारः। सर्वं त्वम् एव।",
  "11.41": "सखेति मत्वा प्रसभं यदुक्तं हे कृष्ण हे यादव हे सखेति।\nअजानता महिमानं तवेदं मया प्रमादात्प्रणयेन वापि -- [एतयोः श्लोकयोः (११.४१ तथा ११.४२) पदच्छेदः, अर्थः, विवरणं च सह अग्रिमे श्लोके (११.४२) दत्तम्।]",
  "11.42": "सखेति मत्वा प्रसभं यदुक्तं हे कृष्ण हे यादव हे सखेति।\nअजानता महिमानं तवेदं मया प्रमादात्प्रणयेन वापि।\nयच्चावहासार्थमसत्कृतोऽसि विहारशय्यासनभोजनेषु।\nएकोऽथवाप्यच्युत तत्समक्षं तत्क्षामये त्वामहमप्रमेयम् -- तव महिमानम् अजानता, सखा इति मत्वा प्रसभं यत् उक्तम्-प्रमादात् वा सलिगेन वा \"अरे कृष्ण, अरे सखे\" इति। विहारे, शयने, आसने, भोजने-सर्वं कारयितारं त्वाम् अवहासार्थम् असत्कृतः। अतः हे अच्युत, ज्ञानातीत, अनुपम, तव पुरतः याचे-तत् सर्वं विस्मृत्य क्षन्तव्यम् इति।\n\nअर्जुनस्य स्वपूर्वाचरणे कृष्णेन सह पश्चात्तापः भवति। कृष्णः जगतः मूलशक्तिः इति कल्पनाम् अकृत्वा यथा आचरितवान्, तस्य कृते सः कृष्णं क्षमां याचते। ज्ञातम् वा अज्ञातम् वा, अनवधानतया वा प्रीत्या वा कृतान् दोषान् क्षमस्व इति सः भगवन्तं प्रार्थयते। अत्र प्रयुक्तस्य 'एक' इति पदस्य विशेषः अर्थः। एकः इति सर्वोत्तमः सर्वकर्ता च (एष एव करोति-एकः)। सर्वकर्तारं सर्वोत्तमं त्वां परिहास्येन सलिगेन भाषितवान्, त्वं अच्युतः। तव सामर्थ्ये गुणे देहे च च्युतिः नास्ति। च्युतया मम बुद्ध्या इदं न गृहीतम्। मया एवं न आचरणीयम् आसीत्। मया कृतस्य अपराधस्य कृते तव समीपे क्षमां याचे। त्वम् अप्रमेयः-कालदेशाभ्यां व्याप्तः त्वम् अस्माकं ज्ञानस्य अगोचरः। इदानीं मह्यं स्वदोषस्य बोधः जातः। अज्ञानेन दोषं करोमि इति ज्ञानम् आगतम्।",
  "11.43": "पितासि लोकस्य चराचरस्य त्वमस्य पूज्यश्च गुरुर्गरीयान्।\nन त्वत्समोऽस्त्यभ्यधिकः कुतोऽन्यो लोकत्रयेऽप्यप्रतिमप्रभाव -- पिता असि लोकस्य चराचरस्य, त्वम् अस्य पूज्यः च गुरुः गरीयान्। न त्वत्समः अस्ति, अभ्यधिकः कुतः अन्यः, लोकत्रये अपि हे अप्रतिमप्रभाव।\n\nसर्वान् सृष्टवान्, सर्वान् पालयन् त्वं जगतः पिता। जगतः गुरुं त्वां मया अतिसलिगेन दृष्टः। तव समः अन्यः कोऽपि नास्ति। त्वां तुलयितुं अन्यः दृष्टान्तः अपि नास्ति। सम्पूर्णे जगति त्वाम् अतिशयतः अन्या शक्तिः नास्ति। [अत्र लोकत्रयम् इति भूमेः अधः लोकानां समूहः, भूलोकः, भूमेः ऊर्ध्वं च लोकानां समूहः इति।] त्वं सर्वेषां कारणानां कारणम्। त्वत्तः अभ्यधिकं कुत्र?",
  "11.44": "तस्मात्प्रणम्य प्रणिधाय कायं प्रसादये त्वामहमीशमीड्यम्।\nपितेव पुत्रस्य सखेव सख्युः प्रियः प्रियायार्हसि देव सोढुम् -- तस्मात् प्रणम्य प्रणिधाय कायं प्रसादये त्वाम् अहम् ईशम् ईड्यम्। पिता इव पुत्रस्य, सखा इव सख्युः, प्रियः प्रियायाः, अर्हसि देव सोढुम्।\n\nसर्वैः स्तुतस्य, सर्वेषाम् अधिपतेः तव पुरतः देहं प्रसार्य, पादयोः पतित्वा प्रार्थये-हे देव, मम प्रियस्य कृते तव प्रियेण त्वया मम दोषाः क्षन्तव्याः, यथा पुत्रस्य दोषं पिता क्षमते, यथा सख्युः दोषं सखा क्षमते।\n\nतव पुरतः स्थातुं न शक्नोमि। देहं प्रसार्य भूमौ लुण्ठितुम् इच्छामि। सर्वैः स्तुतस्य तव समक्षे याचे। यथा पुत्रकृतं दोषं पिता क्षमते, यथा सख्युः दोषं सखा क्षमते, तथा जगतः पिता त्वम्, जगतः सर्वेषाम् अन्तःकरणस्य मित्रं त्वम्, मां क्षमस्व।",
  "11.45": "अदृष्टपूर्वं हृषितोऽस्मि दृष्ट्वा भयेन च प्रव्यथितं मनो मे।\nतदेव मे दर्शय देव रूपं प्रसीद देवेश जगन्निवास -- अदृष्टपूर्वं दृष्ट्वा हृषितः अस्मि, भयेन च मे मनः प्रव्यथितम्। तत् एव मे दर्शय देव रूपम्, प्रसीद हे देवेश जगन्निवास।\n\nकदापि अदृष्टं तव इदम् अद्भुतं रूपं दृष्ट्वा हृष्टः अस्मि। किन्तु सम्पूर्णं जगत् संहरन्तं तव उग्रं रूपं दृष्ट्वा भयम् उत्पद्यते। एकतः आनन्दः, अन्यतः त्रासः। अनेन अहं व्याकुलः जातः। अतः तत् तव 'कृष्ण' रूपं दर्शय।",
  "11.46": "किरीटिनं गदिनं चक्रहस्तमिच्छामि त्वां द्रष्टुमहं तथैव।\nतेनैव रूपेण चतुर्भुजेन सहस्रबाहो भव विश्वमूर्ते -- किरीटिनं गदिनं चक्रहस्तं त्वां द्रष्टुम् इच्छामि अहं तदा एव। तेन एव चतुर्भुजेन रूपेण, हे सहस्रबाहो विश्वमूर्ते, भव।\n\n\"त्वं पूर्वं यथा दृष्टवान् तथा चतुर्भुजः भूत्वा, किरीटं धृत्वा गदाचक्रधरं तव रूपं दर्शय\" इति अर्जुनः सहस्रबाहुं विश्वरूपिणं भगवन्तम् अञ्जलिं बद्ध्वा याचते। अत्र अर्जुनः कृष्णं वदति-\"तव चतुर्भुजं रूपं दर्शय\" इति। कृष्णः स्वान्तरङ्गेभ्यः भक्तेभ्यः स्वकीयं चतुर्भुजं रूपं पूर्वमपि दर्शितवान्। इदम् अर्जुनेन अपि दृष्टम्। भागवते-बालकः सन् कृष्णः स्वकीयं चतुर्भुजं रूपं दर्शितवान् इति एवम् उक्तम्-\n\n\"तम् अद्भुतं बालकम् अम्बुजेक्षणं चतुर्भुजं शङ्खगदाद्युदायुधम्, श्रीवत्सलक्ष्मं गलशोभिकौस्तुभं पीताम्बरं सान्द्रपयोदसौभगम्\" (१०.३.९)।\n\nसामान्यजनैः अदृष्टं भगवतः चतुर्भुजं रूपं कृष्णः केभ्यश्चित् दर्शितवान् इति एषः श्लोकः दृढीकरोति। अत्र अर्जुनः भगवन्तं तस्य विश्वरूपदर्शनं समाप्य स्वस्मै चतुर्भुजं रूपं दर्शयितुम् इति याचते।\n\nअत्र अस्माभिः ज्ञातव्यः मुख्यः विचारः अयम्-भगवतः विश्वरूपस्य उपासना सामान्येभ्यः अस्मभ्यम् असाध्या। तस्य विश्वरूपं महाज्ञानिना अर्जुनेन अपि दृष्ट्वा सोढुं न शक्यम् अभवत्। तर्हि वयं तत् स्वध्याने पचितुं शक्नुमः किम्? अस्मात् कारणात् ध्याने भगवतः विश्वरूपस्य उपासनायाः स्थाने, भगवतः विश्वशक्तेः स्मरणपूर्वकं तस्य अवताररूपेण उपासना श्रेयस्करी। अर्जुनस्य इमां प्रार्थनां कृष्णः कथं स्वीकृतवान् इति अग्रिमेषु श्लोकेषु पश्यामः।",
  "11.47": "श्रीभगवानुवाच-\n\nमया प्रसन्नेन तवार्जुनेदं रूपं परं दर्शितमात्मयोगात्।\nतेजोमयं विश्वमनन्तमाद्यं यन्मे त्वदन्येन न दृष्टपूर्वम् -- मया प्रसन्नेन तव हे अर्जुन इदं परं रूपं दर्शितम् आत्मयोगात्। तेजोमयं विश्वम् अनन्तम् आद्यम्, यत् मे त्वत् अन्येन न दृष्टपूर्वम्।\n\nभगवतः संहाररूपं दृष्ट्वा भयग्रस्तम् अर्जुनं कृष्णः सान्त्वयति। कृष्णः आह-\"अहं तुभ्यं विश्वरूपं दर्शितवान्, तव भक्त्या प्रसन्नः एव, न तु त्वां भाययितुम्\" इति। कृष्णः स्वावतारे बहुवारं स्वकीयं विश्वरूपदर्शनं दर्शितवान्। यशोदा-मृत्तिकां भक्षितवतः कृष्णस्य मुखम् उद्घाटयितुम् उक्तवत्याम्, तत्र तस्याः स्वमुखे विश्वरूपदर्शनं कारितम्। अन्यदा क्षीरं पीत्वा जृम्भमाणस्य बालकृष्णस्य मुखे यशोदा भगवतः विश्वरूपदर्शनं प्राप्तवती। सन्धानाय धृतराष्ट्रस्य सभां आगतं कृष्णं दुर्योधनः बद्धुं यतमानः आसीत् तदा, तत्र कृष्णः स्वकीयं विशेषं रूपं दर्शितवान्। एतावता न, गर्गाचार्याय, उदङ्कमुनये च कृष्णस्य विश्वरूपदर्शनम् अभवत्। किन्तु अत्र अर्जुनाय कृष्णेन दर्शितं विश्वरूपं सर्वेभ्यः अतिशयितम्। \"भूलोके कोऽपि इदं पूर्वं न दृष्टवान्\" इति कृष्णः आह। भगवतः विश्वरूपम्-तत् एकः तेजःपुञ्जः। तत् गुणानां सागरः। अनन्तम् इदं विश्वरूपदर्शनम् अर्जुनः प्राप्तवान्।",
  "11.48": "न वेदयज्ञाध्ययनैर्न दानैर्न च क्रियाभिर्न तपोभिरुग्रैः।\nएवंरूपः शक्य अहं नृलोके द्रष्टुं त्वदन्येन कुरुप्रवीर -- न वेदयज्ञाध्ययनैः न दानैः न च क्रियाभिः न उग्रैः तपोभिः, हे कुरुप्रवीर, एवंरूपः अहं नृलोके त्वदन्येन द्रष्टुं शक्यः।\n\nवेदेषु कर्मकाण्डम् अन्विष्यन्ती विद्या एतत् साधयितुं न शक्नोति। न दानैः। न नियमव्रतैः। न कठोरैः तपोभिः। भगवतः प्रीतिपात्रं न भूत्वा कोऽपि तस्य विश्वरूपदर्शनं प्राप्तुं न शक्नोति। वेदाध्ययनेन, यज्ञेन, दानेन, इत्यादिना कर्मणा सर्वोत्तमस्य सर्वविलक्षणस्य भगवतः विश्वरूपदर्शनं प्राप्तुं न शक्यते। \"एतादृशं मम रूपं कर्मनिष्ठः (कुरुप्रवीरः) त्वं दृष्टवान्\" इति कृष्णः आह।",
  "11.49": "मा ते व्यथा मा च विमूढभावो दृष्ट्वा रूपं घोरमीदृङ्ममेदम्।\nव्यपेतभीः प्रीतमनाः पुनस्त्वं तदेव मे रूपमिदं प्रपश्य -- मा ते व्यथा, मा च विमूढभावः, दृष्ट्वा घोरम् ईदृक् मम इदं रूपम्। व्यपेतभीः प्रीतमनाः पुनः त्वं तत् एव मे इदं रूपं प्रपश्य।\n\nकम्पयत् मम एतादृशं रूपं दृष्ट्वा मा व्याकुलः भव, मा भ्रान्तः भव। पुनः त्वं मम तत् आदिमं रूपम् एव पश्य-भयं त्यक्त्वा, हृदयं स्नेहेन पूरयित्वा।\n\nशत्रुसंहारकं मम इदं रूपं दृष्ट्वा मा भीतः भव। सर्वं भयं त्यक्त्वा पश्य मम प्रियं चतुर्भुजं रूपम् इति कृष्णः वदति।",
  "11.50": "सञ्जय उवाच-\n\nइत्यर्जुनं वासुदेवस्तथोक्त्वा स्वकं रूपं दर्शयामास भूयः।\nआश्वासयामास च भीतमेनं भूत्वा पुनः सौम्यवपुर्महात्मा -- इति अर्जुनं वासुदेवः तथा उक्त्वा स्वकं रूपं भूयः दर्शयामास। आश्वासयामास च भीतम् एनं भूत्वा पुनः सौम्यवपुः महात्मा।\n\nवासुदेवः एवं वदित्वा पुनः अर्जुनाय स्वकीयं कृष्णरूपं दर्शितवान्। महात्मा कृष्णः पुनः सौम्यं वपुः धारयित्वा भीतम् अर्जुनम् आश्वासितवान्।\n\nअस्मिन् श्लोके सञ्जयः भगवन्तं 'वासुदेव' इति सम्बोधयति। भगवतः अस्य नाम्नः अनेके अर्थाः सन्ति। वासु-देव-वासुदेवः। भगवान् 'वासु', अर्थात् स्वयं स्वात्मानं आच्छाद्य स्थितः। यदा वयं संसारबन्धनस्य पञ्चदश वेष्टनानि अतिक्रम्य, समाधिस्थितेः गभीरं गत्वा, षोडशं जीवस्वरूपं पश्यामः, तदा भगवतः साक्षात्कारः भवति। अस्यां अवस्थायां आच्छादितः भगवान् 'देवः' इति उद्घाटितः भवति। भगवन्तं द्रष्टुम् इच्छता प्रथमं स्वात्मा द्रष्टव्यः। स्वस्य अनवगमेन भगवन्तं द्रष्टुम् असम्भवम्। यदा वयं स्वकीयं जीवस्वरूपं पश्यामः, तदा तस्य अन्तः साक्षात्कारं गच्छन् भगवान् 'देवः'। अस्माकं पञ्चकोशेषु (अन्नमयकोशे, प्राणमयकोशे, विज्ञानमयकोशे, मनोमयकोशे, आनन्दमयकोशे च) पटले सति 'वासुः'; पटलात् बहिः आगत्य जीवस्वरूपं पश्यतां दर्शनं ददत् भगवान् 'देवः'-इति दर्शनं ददत् सः भगवान् 'वासुदेवः'।",
  "11.51": "अर्जुन उवाच-\n\nदृष्ट्वेदं मानुषं रूपं तव सौम्यं जनार्दन।\nइदानीमस्मि संवृत्तः सचेताः प्रकृतिं गतः -- दृष्ट्वा इदं मानुषं रूपं तव सौम्यं, हे जनार्दन, इदानीम् अस्मि संवृत्तः सचेताः प्रकृतिं गतः।\n\nअत्र अर्जुनः भगवन्तं 'जनार्दन' इति सम्बोधयति। जन-अर्दन-जनार्दनः। अत्र 'अर्दन' इति अन्तं कुर्वन् इति अर्थः ददाति। 'जन' इति पदस्य अनेके अर्थाः सन्ति। जनः इति दुर्जनः। जनार्दनः इति दुर्जननाशकः। जनः इति जन्मयुक्ताः। जनार्दनः इति जन्मात् मुक्तिं ददत्, अर्थात् मुक्तिप्रदायकः। \"दुर्जनसंहाराय स्थितं तव तत् रूपं दृष्ट्वा अहं भीतः अभवम्। भक्तानाम् आह्वानम् अङ्गीकृत्य, स्वभक्तेभ्यः मोक्षं ददत् तव इदं सौम्यं रूपं दृष्ट्वा अहं चेतनां प्राप्तवान्\" इति भावः अस्मिन् सम्बोधने वर्तते।",
  "11.52": "सुदुर्दर्शमिदं रूपं दृष्टवानसि यन्मम।\nदेवा अप्यस्य रूपस्य नित्यं दर्शनकाङ्क्षिणः -- [एतयोः श्लोकयोः (११.५२ तथा ११.५३) पदच्छेदः, अर्थः, विवरणं च सह अग्रिमे श्लोके (११.५३) दत्तम्।]",
  "11.53": "भगवानुवाच-\n\nसुदुर्दर्शमिदं रूपं दृष्टवानसि यन्मम।\nदेवा अप्यस्य रूपस्य नित्यं दर्शनकाङ्क्षिणः।\nनाहं वेदैर्न तपसा न दानेन न चेज्यया।\nशक्य एवंविधो द्रष्टुं दृष्टवानसि मां यथा -- सुदुर्दर्शम् इदं रूपं दृष्टवान् असि यत् मम, देवाः अपि अस्य रूपस्य नित्यं दर्शनकाङ्क्षिणः। न अहं वेदैः न तपसा न दानेन न च इज्यया शक्यः एवंविधः द्रष्टुम्, दृष्टवान् असि मां यथा।\n\nभगवता अर्जुनाय दर्शितं स्वकीयम् अपूर्वं रूपम् अतिदुर्लभम्। एतादृशम् अपूर्वं रूपं द्रष्टुं देवाः अपि आशया नित्यं प्रतीक्षमाणाः तिष्ठन्ति। कृष्णः अत्र पुनः बलं दत्त्वा पूर्वोक्तं विचारं पुनः वदति-\"स्वसामर्थ्येन (वेदाध्ययनेन, यज्ञेन, दानेन, तपसा इत्यादिना कर्मणा) मम इदं विशिष्टं रूपं द्रष्टुं न शक्यते\" इति कृष्णः आह।",
  "11.54": "भक्त्या त्वनन्यया शक्य अहमेवंविधोऽर्जुन।\nज्ञातुं द्रष्टुं च तत्त्वेन प्रवेष्टुं च परन्तप -- भक्त्या तु अनन्यया शक्यः अहम् एवंविधः, हे अर्जुन परन्तप, ज्ञातुं द्रष्टुं च तत्त्वेन प्रवेष्टुं च।\n\nभगवन्तं द्रष्टुं मूलमन्त्रः 'भक्तिः'। एकनिष्ठया भगवन्तम् अनन्यरूपेण भक्त्या तं प्राप्तुं शक्यते। सर्वेभ्यः अधिकः भगवान् भक्तपराधीनः।",
  "11.55": "मत्कर्मकृन्मत्परमो मद्भक्तः सङ्गवर्जितः।\nनिर्वैरः सर्वभूतेषु यः स मामेति पाण्डव -- मत्कर्मकृत् मत्परमः मद्भक्तः सङ्गवर्जितः, निर्वैरः सर्वभूतेषु यः, सः माम् एति, हे पाण्डव।\n\nभगवन्तं द्रष्टुं भक्त्या सह वर्तमानम् अतिमहत्त्वपूर्णम् अंशं कृष्णः अत्र विवृणोति। अस्माभिः क्रियमाणं कार्यम् \"मया कृतम्\" इति अहङ्कारं न धृत्वा, भगवता मम हस्ताभ्यां कारितम् इति अनुसन्धानम्; अर्पणभावः, फलापेक्षारहिता भक्तिः, द्वेषप्रतीकाररहितं भगवति शरणागतिः, निर्लिप्तभावेन भगवान् सर्वोत्तमः इति सत्यं ज्ञात्वा तं प्रीत्या भजनम्-अनेन भगवन्तं द्रष्टुं शक्यते।\n\nइति एकादशोऽध्यायः।",
  "12.1": "अर्जुनः उवाच\n\nएवं सतत युक्ताः ये भक्ताः त्वाम् पर्युपासते ।\nये च अपि अक्षरम् अव्यक्तम् तेषाम् के योगवित्तमाः ॥\n\nपूर्वाध्यायस्य अन्ते भगवता उक्तम् -- \"निष्कामभक्त्या एव मां द्रष्टुं शक्यते\" इति। एवम् उक्ते सति कथं भगवति भक्तिः कर्तव्या, का च सत्या भक्तिः, भक्ते के गुणाः स्युः इत्यादयः प्रश्नाः अस्माकं मनसि उदयन्ते। प्रश्नोपनिषदि उक्तम् --\n\n\"स प्राणम् असृजत, प्राणाच्छ्रद्धां खं वायुर्ज्योतिरापः पृथिवीन्द्रियं मनः।\nअन्नम् अन्नाद्वीर्यं तपो मन्त्राः कर्म लोका लोकेषु च नाम च॥\"\n\nभगवता इदं जगत् सृष्ट्वा, पञ्चदशवेष्टनयुक्ते अस्मिन् संसारे जीवः स्थापितः। तानि पञ्चदश वेष्टनानि एतानि --\n\n(१) श्रद्धावेष्टनम् -- अनपनेयं वेष्टनम्, जीवस्वभावजा श्रद्धा; अपनेयं च वेष्टनम्, कुलपरिवारवृद्धिस्थानप्रभावजा श्रद्धा।\n\n(२-६) पञ्चभूतवेष्टनम् -- पृथिवी-जलम् (अन्नमयकोशः), तेजो-वायु-आकाशम् (प्राणमयकोशः)।\n\n(७) इन्द्रियवेष्टनम् -- पञ्च ज्ञानेन्द्रियाणि, पञ्च कर्मेन्द्रियाणि।\n\n(८) अन्तःकरणवेष्टनम् -- दुश्चिन्तनशीलं मनः।\n\n(९) अन्नवेष्टनम् -- आहारः।\n\n(१०) वीर्यवेष्टनम् -- शक्तिः।\n\n(११) तपः -- \"एवं भवितव्यम्, तथा भवितव्यम्\" इति चिन्ता (उन्मत्तस्य स्वप्नवत्)।\n\n(१२) मन्त्रः -- स्वप्नं सत्यीकर्तुं यत् वाक्चातुर्यम्।\n\n(१३) कर्म -- स्वप्नसिद्ध्यर्थं यत् कर्म।\n\n(१४) लोकाः -- स्थिरचराः सम्पत्तयः (\"मया कृतम्, मम इदम्\" इति सम्पत्तयः)।\n\n(१५) नामवेष्टनम् -- कीर्तिः (Name and fame)।\n\nएतेषु पञ्चदशसु वेष्टनेषु निबद्धः षोडशः \"क्षरः\" जीवः; तस्मै एतत् वेष्टनरूपं वस्त्रं परिधाप्य संसारं प्रति प्रेषयन्ती सप्तदशी चित्प्रकृतिः लक्ष्मीः; सा अक्षरपुरुषा। क्षराक्षराभ्यां अतीतः अष्टादशः पुरुषः भगवान्, सः पुरुषोत्तमः। गीतायाम् इतःपर्यन्तं भगवता मुख्यतया एतदेव भारपूर्वकम् उक्तम् -- \"यः मां भक्त्या भजते सः अस्मात् संसारबन्धनात् मुक्तः मामेव प्राप्नोति\" इति। अत्र अस्माकं प्रश्नः उदेति -- किमर्थं भगवन्तं त्यक्त्वा सप्तदशीं श्रीतत्त्वं न पूजयेत्? पितुः अपि माता करुणामयी; या माता अस्मान् संसारबन्धने निक्षिप्तवती, तस्याः पूजनेन अस्माकं मोक्षप्राप्तिः सुलभा स्यात् किम्? कः पन्थाः अधिकतरः उचितः इति एषः सामान्यतः सर्वेषाम् एव प्रश्नः। श्रीतत्त्वस्य उपासनया मुक्तिः सम्भवति इति स्तुतौ उक्तम्। उदाहरणार्थं सर्वे देवपूजायां मङ्गलारत्यवसरे इमाः श्रीसूक्तपङ्क्तीः पठन्ति --\n\n\"श्रियै जातः श्रिय आ निर्याय श्रियं वयो जनितृभ्यो दधातु।\nश्रियं वसानाः अमृतत्वम् आयन् भजन्ति सद्यः स मिधा मितद्युन्॥\"\n\nअत्र उक्तम् -- \"श्रीतत्त्वस्य उपासनार्थम् एव वयं जाताः। श्रीतत्त्वं यः स्तौति तस्मै सा सम्पदं दीर्घायुष्यं च ददाति। श्रीतत्त्वोपासकाः अमृतत्वं प्राप्तवन्तः। दम्पती श्रीतत्त्वम् उपासमानौ स्वेष्टार्थसिद्धिं लभेते। सा मोक्षप्रदा\" इति। एवम् उक्तत्वात् श्रीतत्त्वोपासनयापि मोक्षः प्राप्यते इति स्पष्टम्। पुरुषोत्तमस्य भगवतः उपासना, श्रीतत्त्वस्य वा अक्षरायाः उपासना -- अनयोः कतरः पन्थाः अधिकतरः उचितः, इति अत्र अस्माकं सर्वेषां प्रश्नः। अस्मदीयः प्रतिनिधिः अर्जुनः इमम् एव अस्मदीयं प्रश्नं भगवतः पुरतः स्थापयन् अयम् अध्यायः आरभ्यते। द्वितीयषट्कस्य अन्तिमः अयम् अध्यायः विंशतिश्लोकात्मकः एव। लघुः अपि अयम् अध्यायः अपूर्वविषयसम्पन्नः। भगवता अत्र उक्तान् विचारान् वयं स्वजीवने आचरेम चेत् अस्माकं जीवनं सार्थकं भवेत्। आगच्छत, अस्मिन् अध्याये उक्तं गुणभक्तिसन्देशम् अवगच्छाम।\n\nअर्जुनः पृष्टवान् -- \"एवं सततयुक्ताः ये भक्ताः त्वां पर्युपासते, ये च अपि अक्षरम् अव्यक्तं तेषां के योगवित्तमाः\" इति। अनेन प्रश्नेन निरन्तरसाधनया त्वां सेवमानाः भक्ताः, अक्षरम् अव्यक्ततत्त्वं (श्रीतत्त्वम्) च उपासमानाः -- एतयोः के अधिकतराः इति अर्जुनः पृच्छति।\n\nएतत् श्लोकं वीक्ष्य प्रथमदृष्ट्या भगवतः विशिष्टरूपस्य उपासना, केनापि रूपेण अव्यक्तस्य निराकारभगवतः उपासना च -- अनयोः का उचिता इति पृष्टम् इव भासते। परं अत्र अर्जुनस्य मूलप्रश्नः भिन्नः एव। एतत् मध्वाचार्यैः विशिष्टतया व्याख्यातम्।\n\nभगवतः चिन्तनं कुर्वन्तः सर्वे भगवद्भक्ताः भवेयुः इति नियमः नास्ति। भगवच्चिन्तनाय आवश्यकं मूलद्रव्यं प्रीतिः। ज्ञानपूर्विका प्रीतिः एव भक्तिः। पूर्वकाले प्रतिगृहं देवतागृहे एकः विग्रहः आसीत् -- यस्य उपासना यस्मै इष्टा तस्य इष्टदेवतायाः विग्रहः। एतत् विश्लिष्य वीक्षितं चेत्, किमर्थम् एवं प्रतिमां स्थापयित्वा पूजितवन्तः इति ज्ञायते। अत्र प्रथमम् अस्मदीयं मनः कथं कार्यं करोति इति ज्ञातव्यम्। चक्षुषा अदृष्टं मनः न गृह्णाति। उदाहरणार्थं भगवन्तम् \"अतिसुन्दरः\" इति ज्ञात्वा वयं नेत्रे निमील्य ध्याने उपविशेम चेत्, अस्मदीयं मनः अस्माभिः दृष्टं कमपि सुन्दरं मनुष्यम् एव अस्मभ्यं दर्शयति! अतः पूर्वजैः भगवते अस्मद्वत् करचरणादीनि सन्ति, परं सः न कस्यापि मनुष्यस्य सदृशः इति दर्शयन् तस्य प्रतिमा निर्मिता। एतां प्रतिमां स्मृत्वा नेत्रे निमील्य भगवतः गुणानुसन्धानं कुर्मः चेत्, अस्मभ्यं सा मूर्तिः एव दृश्यते, न तु अस्मत्परिचितः कोऽपि व्यक्तिः। एतेन ध्यानं सुकरं भवति। मनः कमपि व्यक्तिं न चिन्तयत् प्रतिमारूपेण भगवन्तम् एव पश्यति। अस्मात् कारणात् भगवच्चिन्तनाय एकं रूपम् आवश्यकम्।\n\nअस्माकं ज्ञातं यत् मातरं श्रीलक्ष्मीं श्रीतत्त्वम्, अक्षरा, अव्यक्ता, प्रकृतिः, ह्रीः इत्यादिभिः अनेकनामभिः आह्वयन्ति। भगवद्गीतायाम् एव अनेकत्र एवंविधं सम्बोधनं दृश्यते। कठोपनिषदि उक्तम् -- \"महतः परम् अव्यक्तम्, अव्यक्तात् पुरुषः परः\" इति। अर्थात् महत्तत्त्वात् अव्यक्ततत्त्वं ज्येष्ठम्, अव्यक्ततत्त्वात् पुरुषः भगवान् ज्येष्ठः। अत्र स्पष्टं ज्ञायते -- अव्यक्ता, अक्षरा इति मातृश्रीलक्ष्मीः एव।\n\nनिरन्तरं मनसि त्वदुक्तगुणानाम् अनुसन्धानं कुर्वन्, शास्त्रैः तव महिमानं तव रूपविशेषान् च ज्ञात्वा, तत्र भक्तिं वर्धयित्वा तव उपासना करणीया, उत क्षरातीतायाः (अक्षरायाः) श्रीतत्त्वस्य उपासना करणीया? कः पन्थाः अधिकतरः उचितः -- इति अर्जुनस्य प्रश्नः।",
  "12.2": "भगवान् उवाच\n\nमयि आवेश्य मनः ये माम् नित्ययुक्ताः उपासते ।\nश्रद्धया परया उपेताः ते मे युक्ततमाः मताः ॥\n\nकृष्णः अर्जुनस्य प्रश्नस्य उत्तरं वदन् आह -- \"यः श्रद्धया मां उपासते सः भगवतः साधकेषु श्रेष्ठः\" इति। अत्र श्रद्धा इत्युक्ते नम्बिके (विश्वासः)। साधनायां श्रद्धा एव अतिमुख्या। श्रद्धां विना उपासनायाः फलं नास्ति। इदं मनःशास्त्रम्। अत्र लौकिकम् उदाहरणम् -- रोगी वैद्यश्च। यदि रोगिणः स्वं परीक्ष्य औषधं ददतः वैद्यस्य उपरि विश्वासः न स्यात्, तर्हि सेवितम् औषधं तस्मिन् न कार्यं करोति। दृढे विश्वासे सति वैद्यः यस्मै रोगाय यत् औषधं ददाति, तेन रोगः शाम्यति एव! एतत् वैज्ञानिकदृष्ट्यापि सिद्धम्। अतः केवलं नेत्रे निमील्य विश्वासं विना उपासनायाः उपयोगः नास्ति। दृढया श्रद्धया, ज्ञात्वा, भगवतः गुणरूपं ध्यायन्तः एव श्रेष्ठभक्तिं लभन्ते। पूर्णश्रद्धया केनापि रूपेण, केनापि नाम्ना च भगवान् उपास्यः। भगवतः रूपं न भवत् रूपं नास्ति, भगवतः नाम न भवत् नाम नास्ति। पूर्णायां श्रद्धायां सत्यां नामरूपे न समस्या भवतः। अत एव भगवान् वदति -- \"मम रूपं गुणविशेषं च ये श्रद्धया उपासते ते साधकेषु श्रेष्ठाः\" इति।",
  "12.3": "ये तु अक्षरम् अनिर्देश्यम् अव्यक्तं पर्युपासते ।\nसर्वत्रगम् अचिन्त्यं च कूटस्थम् अचलं ध्रुवम् ॥\n\n[एतयोः श्लोकयोः (१२.३ तथा १२.४) पदच्छेदः, अर्थः, विवरणं च सह अग्रिमे श्लोके (१२.४) दत्तम्।]",
  "12.4": "ये तु अक्षरम् अनिर्देश्यम् अव्यक्तं पर्युपासते ।\nसर्वत्रगम् अचिन्त्यं च कूटस्थम् अचलं ध्रुवम् ॥\n\nसन्नियम्येन्द्रियग्रामं सर्वत्र समबुद्धयः ।\nते प्राप्नुवन्ति मामेव सर्वभूतहिते रताः ॥\n\nअव्यक्तम्, अक्षयं तत्त्वम्, वाचाम् अगोचरम्, चिन्तनस्य अप्यगम्यं तत्त्वम्, आकाशे निवसत् सर्वत्र व्याप्तम्, अच्युतं निर्विकारं तत्त्वम् -- इन्द्रियसमूहं दृढं संयम्य सर्वत्र समदृष्ट्या सर्वप्राणिनां हितम् इच्छन्तः, एतादृशम् अव्यक्ततत्त्वं सेवमानाः अपि मामेव प्राप्नुवन्ति।\n\nअत्र कृष्णः अव्यक्ततत्त्वस्य लक्ष्म्याः उपासनाविषये विवृणोति। लोकनीतौ भगवदुपासनायां च भेदः अस्ति। लोके सामान्यतः माता सदा स्वसन्तानानां दोषान् क्षमते, पिता च दण्डयति। परं मातुः श्रीलक्ष्म्याः उपासनायां भगवदुपासनायां च इदं विपरीतम्। उपासनायां कश्चन दोषः लोपः वा भवेत् चेत्, माता न क्षमते, भगवान् तु क्षमते। अस्मात् कारणात् अव्यक्तायाः अक्षरायाः उपासना दुष्करा। अत्र मातरं लक्ष्मीम् उपासितुं ज्ञातव्यान् विशेषान् भगवान् वदति, अनेकैः विशेषणैः एतत् अस्मिन् श्लोके विवृतम्। अक्षयशरीरा सा अक्षरा; अस्मद्बुद्ध्या अगोचरा प्रकृतिः सा अनिर्देश्या; कदापि न व्यक्ता लक्ष्मीः सा अव्यक्ता। एते सर्वे गुणाः भगवत्यपि सन्ति।\n\nजगतः सृष्टेः मूलतत्त्वभूते आकाशे निवसन्ती, सम्पूर्णविश्वस्य विस्तारस्य कारणभूता लक्ष्मीः। स्थिरा शाश्वती च सा सदा भगवतः पादौ सेवते। एतादृशीं शक्तिदेवतां उपासितुं कठोरः इन्द्रियनिग्रहः आवश्यकः। सर्वं समबुद्ध्या पश्यन्, कयाचिदपि न्यूनतया विना उपासना अत्र अत्यावश्यकी। [उदाहरणार्थं ललितासहस्रनामपारायणे स्वल्पोऽपि लोपदोषः अनर्थाय भवति।] एवम् अत्यन्तनियमबद्धतया अव्यक्ततत्त्वस्य उपासनया भगवत्प्राप्तिः सम्भवति। परन्तु इयं न सुलभा पद्धतिः इति भगवान् वदति।",
  "12.5": "क्लेशः अधिकतरः तेषाम् अव्यक्तासक्तचेतसाम् ।\nअव्यक्ता हि गतिः दुःखं देहवद्भिः अवाप्यते ॥\n\nअव्यक्ततत्त्वस्य उपासनाम् एव वरीतॄणां क्लेशः अधिकः भवति। अव्यक्तेन मुक्तेः मार्गः साधकानां कृते दुष्करः बहुविधः मार्गः।\n\nशक्तिम् उपासमानान् सा प्रसन्ना भूत्वा मोक्षं ददाति। परं अव्यक्तस्य उपासकानाम् \"अधिकतरः क्लेशः\" -- उपासना अतीव दुष्करा। इदं सरलं मार्गं त्यक्त्वा वक्रमार्गेण भगवन्तं प्रति गमनम् इव। साधकैः इदं महता क्लेशेन साधनीयम्।\n\nअग्रिमेषु श्लोकेषु प्रत्यक्षभगवदुपासना कियती सुकरा इति कृष्णः विवृणोति। इयम् एव भगवता अस्मभ्यं दर्शिता सुकरा भक्तिमार्गः।",
  "12.6": "ये तु सर्वाणि कर्माणि मयि सन्न्यस्य मत्पराः ।\nअनन्येनैव योगेन मां ध्यायन्तः उपासते ॥\n\n[एतयोः श्लोकयोः (१२.६ तथा १२.७) पदच्छेदः, अर्थः, विवरणं च सह अग्रिमे श्लोके (१२.७) दत्तम्।]",
  "12.7": "ये तु सर्वाणि कर्माणि मयि सन्न्यस्य मत्पराः ।\nअनन्येनैव योगेन मां ध्यायन्तः उपासते ॥\n\nतेषाम् अहं समुद्धर्ता मृत्युसंसारसागरात् ।\nभवामि नचिरात् पार्थ मय्यावेशितचेतसाम् ॥\n\nकेचन सन्ति -- ये स्वकृतं सर्वं मयि अर्पयन्ति। ते मयि एव बद्धचित्ताः, तेषां साधनायाः लक्ष्यं न अहं विना अन्यत् किमपि। मामेव सततं स्मरन्तः सेवन्ते। हे पार्थ, मामेव आश्रितान् तान् अहं शीघ्रम् एव मृत्युसंसारसागरात् उद्धरामि।\n\nकृष्णः वदति -- \"मां प्राप्तुं सुकरं साधनम् इदम् -- जीवननिर्वाहाय यत् कर्म करोषि, तत् मयि अर्पय\" इति। अत्र कृष्णः वदति यत् अस्मदीयस्य प्रत्येकस्य कर्मणः पृष्ठे भवितव्यम् अनुसन्धानम् -- \"इदं कार्यं भगवता मम हस्ताभ्यां कारितम्, इदं तस्मै अर्पितं भवतु\" इति अनुसन्धानम्। एवं सति वयं भगवतः पूर्णानुग्रहस्य पात्राः भवामः। अत्र अस्माभिः धर्तव्यः अतिमुख्यः अंशः -- भगवन्तम् अनन्यभावेन एकनिष्ठया उपासितुम्। अस्मदीयायां साधनायां न्यूनता स्यात्, इन्द्रियनिग्रहः दुष्करः स्यात्, सर्वभूतहितचिन्तनं न सिध्येत्, चिन्तने दोषाः स्युः, एकाग्रता न आगच्छेत्। परं अत्र कृष्णस्य आश्वासनं यत् \"मयि शरणम् आगच्छ, त्वदीयं मनः मयि निदेहि -- अहं त्वाम् उद्धरिष्यामि\" इति। अस्मद्भिः स्वचित्ते भगवन्तं निवेश्य स्थापिते सति, भगवान् अस्मान् अस्मात् जन्ममृत्युमयात् संसारसागरात् पारं नेतुं दायित्वं वहति।",
  "12.8": "मयि एव मनः आधत्स्व मयि बुद्धिं निवेशय ।\nनिवसिष्यसि मयि एव अतः ऊर्ध्वं न संशयः ॥\n\nकृष्णः वदति -- मनः मयि आधेहि इति। \"आधानम्\" इत्युक्ते बीजवपनं किंवा स्फुलिङ्गप्रज्वालनम्। मनसि भगवद्भक्तेः स्फुलिङ्गं प्रज्वाल्य तत् दीप्तं कर्तव्यम्। भक्तेः बीजं वर्धमानं पोषणीयम्। निश्चयज्ञानेन बुद्धौ दृढीकर्तव्यम्। एवं सदा मनसि भगवन्तं स्थापयित्वा, केनापि क्लेशेन विना भगवन्तं प्राप्तुं शक्यते। इदं शक्त्युपासनातः भगवदुपासना कियती सुकरा इति विवरणम्। भगवदुपासनायां नियमाः निर्बन्धाः च अल्पतमाः। उदाहरणार्थं विष्णुसहस्रनामपारायणम्। विष्णुसहस्रनामचिन्तनाय कस्यापि निश्चितकालस्य निर्बन्धः नास्ति। यः कश्चित् यस्मिन् अपि काले विष्णुसहस्रनाम पठितुं शक्नोति। सर्वरोगाणां भेषजं विष्णुसहस्रनाम। भगवच्चिन्तने अज्ञानतः जातेषु लोपदोषेषु क्षमा अस्ति।\n\nनारायणस्य उपासना इत्युक्ते सा लक्ष्मीसमेतस्य नारायणस्य उपासना। नारायणम् उपासमानैः लक्ष्मीम् अन्यान् देवतांश्च पृथक् उपासितुं न आवश्यकम्। लक्ष्म्यै सर्वदेवताभ्यश्च अतिप्रियतमा भगवदुपासना एव। नारायणोपासकं साधकं सर्वे देवाः साहाय्येन स्वसाधनामार्गे उच्चैः नयन्ति। इदं ज्ञात्वा वयम् उपासनायां सुकरतया एकभक्तिं साधयितुं शक्नुमः। भक्तिमार्गे दृढतां प्राप्तुं शक्नुमः।",
  "12.9": "अथ चित्तं समाधातुं न शक्नोषि मयि स्थिरम् ।\nअभ्यासयोगेन ततः माम् इच्छा आप्तुं धनञ्जय ॥\n\nहे धनञ्जय, यदि मयि अन्तः बुद्धिं दृढीकर्तुं न शक्नोषि, तर्हि पुनः पुनः अभ्यासप्रयोगेन मां प्राप्तुम् इच्छां वर्धय।\n\nमनसि भगवति भक्तिः अस्ति, बुद्धौ ज्ञानपूर्णभक्तेः अङ्कुरः अस्ति। तथापि स्थिरा स्मृतिः न आगच्छति, मनः दृढतया न स्थिरीभवति -- तदा किं कर्तव्यम्? शास्त्रे उक्तम् --\n\n\"स्मर्तव्यः सततं विष्णुः विस्मर्तव्यो न जातुचित् ।\nसर्वे विधिनिषेधाः स्युः एतयोरेव किङ्कराः ॥\"\n\nअर्थात् \"वयं निरन्तरं भगवन्तं स्मरणे धारयेम, कदापि भगवन्तं न विस्मरेम\" इति। समस्तं विधिनिषेधकथनम् अपि एतदेव वदति। मनसि निरन्तरं भगवति अस्थिते सति इयम् अखण्डा स्मृतिः न साध्या। एतादृशे प्रसङ्गे किं करणीयम् इति कृष्णः विवृणोति -- \"मनः एकाग्रतां प्रति नेतुं शक्तिं देहि इति मां प्रार्थय। अध्यात्ममार्गे यत् किमपि इच्छसि, तत् पूरयितुं दायित्वं मम\" इति कृष्णस्य आश्वासनम्। अभ्यासेन इच्छया च एकाग्रता निश्चयेन साध्या। यथा वयं बालान् प्रशिक्ष्य अभ्यासं कारयित्वा शिक्षयामः, तथैव अस्मदीयं मनः रमयित्वा रमयित्वा बुद्धिवादेन अभ्यासं कारयितव्यम्। एवं कृते मनः तत् रूढं करोति। प्रथमं वयं लौकिकसम्पत्तेः पृष्ठलग्नत्वं त्यक्त्वा, भगवन्नामकम् अमूल्यं धनं जेतुं धनञ्जयाः भवेम।",
  "12.10": "अभ्यासे अपि असमर्थः असि मत्कर्मपरमः भव ।\nमदर्थम् अपि कर्माणि कुर्वन् सिद्धिम् अवाप्स्यसि ॥\n\nकेषाञ्चित् यावान् अपि अभ्यासः क्रियते तथापि एकभक्तिः न सिध्यति। अध्यात्ममार्गस्य साधनायां मनसे एकजन्मनः अभ्यासः न पर्याप्तः भवति। कदाचित् सम्पूर्णं जन्म अभ्यस्यतोऽपि एकाग्रता न आगच्छेत्। एतादृशेभ्यः कृपालुः कृष्णः वदति -- \"यत् कर्म करोषि तत् स्वार्थाय अकृत्वा, भगवत्पूजा इति अनुसन्धानेन कुरु\" इति। स्वकीयं दैनन्दिनं प्रत्येकं कर्म अर्पणभावेन भगवतः पूजा इति कृत्वा, अध्यात्ममार्गे सिद्धिं प्राप्तुं शक्यते।",
  "12.11": "अथ एतद् अपि आशक्तः असि कर्तुं मद्योगम् आश्रितः ।\nसर्वकर्मफलत्यागं ततः कुरु यतात्मवान् ॥\n\nयदि उपर्युक्तरीत्या सर्वं कर्म भगवति अर्पयितुं न शक्यते, सर्वं भगवतः पूजारूपेण कर्तुं न शक्यते, तर्हि यं कञ्चन उपास्व -- परं अन्ततः सर्वकर्म कर्मफलेच्छां विना भगवते अर्पय, इति कृष्णः वदति। अत्र कर्मफलस्य त्यागाय अर्पणाय च कृष्णेन भारः दत्तः।",
  "12.12": "श्रेयः हि ज्ञानम् अभ्यासात् ज्ञानात् ध्यानं विशिष्यते ।\nध्यानात् कर्मफलत्यागः त्यागात् शान्तिः अनन्तरम् ॥\n\nअज्ञानसहितात् अभ्यासात् ज्ञानं श्रेष्ठम्। केवलात् ज्ञानात् ज्ञात्वा ध्यानं श्रेष्ठतरम्। केवलात् ध्यानात् कर्मफलनिःसङ्गं ध्यानं श्रेष्ठतमम्। एतादृशस्य ध्यानस्य अग्रिमः सोपानः एव मुक्तिः।\n\nज्ञानरहितात् ध्यानात् ज्ञानं श्रेष्ठम्। अध्यात्मसाधनायां ज्ञानं मूलभूता आवश्यकता। ज्ञानं विना ध्यानं कर्म वा कृत्वा उपयोगः नास्ति। बोधरहिता श्रद्धा अन्धश्रद्धा भवति। तथैव विश्वासरहितः बोधः अहङ्कारः भवति। अतः ज्ञातव्यम्, ज्ञात्वा श्रद्धेयम्। केवलं बोधः पर्याप्तः न भवति। ज्ञानात् ज्ञानसहितं ध्यानम् उत्कृष्टम्। सर्वेभ्यः उत्कृष्टः कर्मफलत्यागः। अतः प्रथमं ज्ञातव्यम्, ज्ञात्वा अभ्यसनीयम्। परन्तु त्वदीयं ध्यानं कर्मफलरहितं ध्यानं भवतु। एतादृशेन जीवनशैल्या मोक्षप्राप्तिः सम्भवति।\n\nअत्र पर्यन्तं भगवतः उपासना कीदृशी भवेत् इति विवृतवान् कृष्णः, अग्रे वयं देवमान्यं जीवनं यापयितुं कीदृशं जीवनं रचयितव्यम्, अस्मदीयः जीवनक्रमः अनुष्ठानं च कीदृशं भवेत् इति विवृणोति।",
  "12.13": "अद्वेष्टा सर्वभूतानाम् मैत्रः करुणः एव च ।\nनिर्ममः निरहङ्कारः समदुःखसुखः क्षमी ॥\n\n[एतयोः श्लोकयोः (१२.१३ तथा १२.१४) पदच्छेदः, अर्थः, विवरणं च सह अग्रिमे श्लोके (१२.१४) दत्तम्।]",
  "12.14": "अद्वेष्टा सर्वभूतानाम् मैत्रः करुणः एव च ।\nनिर्ममः निरहङ्कारः समदुःखसुखः क्षमी ॥\n\nसन्तुष्टः सततं योगी यतात्मा दृढनिश्चयः ।\nमयि अर्पितमनोबुद्धिः यः मद्भक्तः सः मे प्रियः ॥\n\nभगवते प्रियं मानवव्यवहारं विवृण्वन् कृष्णः प्रथमं वदति -- \"अद्वेष्टा सर्वभूतानाम्\" इति। अर्थात् कमपि न द्विषेत्। इदं भगवद्भक्ते भवितव्यं प्रथमं लक्षणम्। द्वेषः द्विविधः -- एकः सज्जनान् (तेषाम् उन्नतिं दृष्ट्वा) द्विष्टि; अपरः दुर्जनान् (तेषां दुष्टतां दृष्ट्वा) द्विष्टि। द्वेषः असहनतायाः मात्सर्यात् च जायते। अन्यस्य उत्कर्षं दृष्ट्वा सन्तप्तः भवति इति द्वेषः। सज्जनः स्यात् दुर्जनः वा, मात्सर्यम् असहनता वा न स्यात्। यत्र साधुत्वम् अस्ति तत् प्रीणीहि, स्नेहं वर्धय। दुर्जनेभ्यः दूरं भव, साधुत्वं साधून् च प्रीणीहि। अन्यस्य दुःखं दृष्ट्वा द्रुत भव। \"अहम्, मम, मया कृतम्\" इति अहङ्कारं ममकारं च त्यज। \"ईशावास्यम् इदं सर्वम्\" -- सर्वस्य स्वामी सः भगवान् एव। तेन दत्तत्वात् इदम् अस्ति इति मनोभावः स्यात्। यथा अहङ्कारः न श्रेयस्करः, तथैव अतिशयितः ममकारः अपि न श्रेयस्करः। पुरन्दरदासवत् प्रीतौ निर्लिप्तता (Detached attachment) स्यात्। पुरन्दरदासस्य एकः पुत्रः आसीत्। तं ते प्रीत्या पालितवन्तः। एकदा प्रियः पुत्रः मृतः अभवत्। तदा ते \"शुकः पञ्जरे नास्ति, त्वया दत्तः शुकः त्वामेव प्राप्तः\" इति गीत्वा निर्लिप्ततया जीवितवन्तः। वयं दुःखसुखयोः सन्तुलनं साधयेम। सुखे प्राप्ते उत्प्लवः न स्यात्। दुःखे प्राप्ते अकुण्ठितः सन् आगतं सोढव्यम्। अन्येषु क्षमाभावः स्यात्, प्रतीकारः न स्यात्। [अपराधिनः न्यायाधीशाः अधिकारिणश्च दण्डयेयुः -- तत् तेषां कर्तव्यधर्मः, तत्र प्रतीकारः नास्ति।]\n\nअग्रे कृष्णः वदति -- \"सन्तुष्टः सततं योगी यतात्मा दृढनिश्चयः\" इति। सुखेन जीवितुम् इच्छता मनुष्येण धार्यव्या चित्तवृत्तिः -- 'असन्तोषरहितत्वम्'। जीवने अस्माकं सर्वेषां दुःखानां कारणम् असन्तोषः। यत् नास्ति तद्विषये असन्तुष्टः भवितुं बदले, यत् अस्ति तद्विषये सन्तुष्टः भव। यत् किमपि प्राप्तं तेन सन्तोषं प्राप्तुम् अभ्यसनीयम्। सदा योगी भव। अत्र \"योगी\" इत्यस्य अनेके अर्थाः सन्ति। विविधासनाभ्यासः योगः न भवति। मनसः एकाग्रीकरणाय करणीया प्रक्रिया योगः। वानरवत् धावमानं नः मनः धृत्वा स्थापयितुम् -- वायुं धृत्वा स्थापयितुमिव। तत् अतीव विचित्रम्। मनः स्खलितं भवति इति अस्माभिः ज्ञायते तस्य गतस्य अनन्तरमेव। एतादृशस्य मनसः धारणाय प्रथमं मेरुदण्डं सरलं कृत्वा स्थिरतया उपवेष्टुम् अभ्यासः करणीयः -- आसनम् (यत्किमपि आसनं भवतु)। ततः प्राणायामेन अन्तः चिन्तनं जागरयितुं यत्नः -- सः योगः। स्वच्छे मनसि भगवन्तम् उपवेशयितुं यः यत्नः सः योगः। जीवननिर्वाहाय प्राप्तं मार्गं श्रद्धया प्रामाणिकतया च आचरितुं यः यत्नः सः योगः। एवम् अभ्यासेन मनः अस्मदीये वशे स्थापनीयम्। किमपि दुष्टभावेन न पश्यन्तम् अभ्यसनीयम्। अध्यात्ममार्गे अचला निश्चयः स्यात्। यत् किमपि आगच्छतु, दृढनिश्चयेन अग्रे गन्तव्यम्। मनः भगवते लालायताम्। बुद्धिः भगवन्तं जानातु। \"एवं यः मां प्रीणाति (भक्तः) सः मे अतिप्रियः\" इति वदति कृष्णः।",
  "12.15": "यस्मात् न उद्विजते लोकः लोकात् न उद्विजते च यः ।\nहर्षामर्षभयोद्वेगैः मुक्तः यः सः च मे प्रियः ॥\n\nअस्मद्व्यवहारेण अन्ये न उद्विजेयुः, वयं च अन्यैः न उद्विजेम। कोऽपि अस्मान् दृष्ट्वा असहनताम् असन्तोषं वा न धरेत्, वयं च अन्यान् दृष्ट्वा असहनताम् न धरेम। जगत् निष्कपटं प्रेम्णा पश्यन्तः एव इदं साधयितुं शक्नुमः। भगवते प्रियं कर्म कुर्वतां भगवान् अस्मान् प्रीणाति। भगवता प्रीयमाणान् सम्पूर्णं जगत् एव प्रीणाति।\n\nवयं हर्षामर्षभयोद्वेगेभ्यः मुक्ताः भवेम। अकर्तव्यं कृत्वा उत्फुल्लता हर्षः; अन्यैः कर्तव्यं कृते तत् दृष्ट्वा मात्सर्यम् अमर्षः। साधकः हर्षामर्षाभ्यां मुक्तः स्यात्। भीतिजनकं कर्म मा कुरु, अपराधं विना भयं मा कुरु। अन्यान् संशयदृष्ट्या पश्यामः चेत्, तेऽपि अस्मान् संशयदृष्ट्या पश्यन्ति। अन्यान् न विश्वसामः चेत्, तेऽपि अस्मान् न विश्वसन्ति। अनेन उद्वेगः (Tension) जायते। उद्वेगेन बहुविधाः व्याधयः अस्मदीये देहे गृहं कुर्वन्ति। वयं भगवन्तं विश्वस्य निःस्वार्थतया निश्चिन्ततया च जीवितुं शिक्षणीयाः। \"जीवने सर्वान् प्रीणयन् साधकः, हर्षामर्षभयोद्वेगान् जितः साधकः मे प्रियः\" इति वदति कृष्णः।",
  "12.16": "अनपेक्षः शुचिः दक्षः उदासीनः गतव्यथः सर्वारम्भपरित्यागी यः मद्भक्तः सः मे प्रियः।\n\nअत्र कृष्णः स्वभक्ते भक्तिपोषकान् षड्गुणान् वर्णयति।\n\n(१) अनपेक्षः — \"इदमपि स्यात्, तदपि स्यात्\" इति इच्छाराहित्यम्। यत् क्षणिकसुखं ददाति तत् अननुधाव्य, नित्यमोक्षमार्गे एव गमनम्। यत् किमपि प्राप्तं तस्मिन्नेव सन्तोषः — एषः अनपेक्षः।\n\n(२) शुचिः — बाह्याभ्यन्तरशुद्धिः एव शौचम्। वाचि दुर्वचनम्, मनसि दुश्चिन्ता, शरीरे मलिनता — इदमेव अशौचम्। प्रथमं मनोमलं प्रक्षालनीयम्; तदनन्तरं बाह्यशुद्धिः तस्य पोषिका। अत एव शान्तिपाठे उच्यते — \"ॐ भद्रं कर्णेभिः शृणुयाम देवाः भद्रं पश्येमाक्षभिर्यजत्राः\" इति। शुभमेव पश्येम, शुभमेव वदेम, शुभमेव चिन्तयेम — इदमेव सत्यं शौचम्।\n\nशौचविषये प्रसिद्धे द्वे श्लोके स्तः —\n\nअपवित्रः पवित्रो वा सर्वावस्थां गतोऽपि वा।\nयः स्मरेत् पुण्डरीकाक्षं स बाह्याभ्यन्तरः शुचिः॥\n\nअतिनीलघनश्यामं नलिनायतलोचनम्।\nस्मरामि पुण्डरीकाक्षं तेन स्नातो भवाम्यहम्॥\n\nअत्र पुण्डरीकाक्षस्य स्मरणं कर्तव्यम् इति उक्तम्। एतत् भगवतः विशेषनाम। पुण्डरीकाक्षः इत्युक्ते रक्तकमलसदृशनेत्रयुक्तः इत्यर्थः। भगवतः नेत्रे सर्वदा रक्तकमलदलवत् विकसिते भासेते। सामान्यतः अस्माकं परमसन्तोषे एव नेत्रे विकसतः, किन्तु भगवान् नित्यमेव आनन्दस्य उत्सः। भगवान् प्रीत्या नेत्रे विकास्य मां पश्यति। तस्य नेत्राभ्यां प्रवहन्त्याम् अनुग्रहरसधारायाम् अहं मज्जामि। तस्य कृपादृष्टिः मयि प्रवृत्ता; \"अहं तस्यां स्नातः\" इति अनुसन्धानम् एव शुचिः। एवं भगवतः अनुग्रहेण वयम् अन्तर्बहिश्च शुद्धाः भवेम।\n\n(३) दक्षः — अस्माकं मनः भगवत्प्रति प्रवाहयितुं दक्षता भवितव्या। सः बाह्यप्रयत्नेन न वश्यः। अन्तरङ्गेणैव तं प्रति गन्तव्यम्। बाह्यक्रिया अन्तरङ्गसाधनस्य पोषिका मात्रम्। भगवन्तं कथं प्राप्नुयाम इति ज्ञानं चातुर्यं च अस्मासु भवेत्।\n\n(४) उदासीनः — अन्तर्यामित्वेन स्थितिः। बाह्यक्रियायाम् आग्रहः न कर्तव्यः। यथा — कुटुम्बे कश्चित् स्वस्य फलापेक्षां साधयितुं कञ्चन पूजां कारयति। तादृशे प्रसङ्गे \"फलापेक्षया भगवदाराधना दोषः\" इति विरुध्य स्थातुं न श्रेयः। यत्किमपि अस्तु, तत् भगवतः सेवैव; तत् भगवन्तमेव प्राप्नोतु इति प्रार्थनीयम्। सर्वैः सह आग्रहं विना जीवितुं शिक्षणीयम्।\n\n(५) गतव्यथः — यत्किमपि भवतु, खेदं विना सदा आनन्दस्थितिः।\n\n(६) सर्वारम्भपरित्यागी — भगवतः पारम्यविरुद्धं यत् किमपि आरम्भं न आरभेत। सर्वम् आरम्भं फलकामनया कर्तुं त्यजेत्। सर्वं \"कृष्णार्पणमस्तु\" इति भगवति समर्पणीयम्।\n\n\"एभिः गुणैः यः मां प्रीणाति सः भक्तः मे प्रियः\" इति कृष्णः वदति।",
  "12.17": "यः न हृष्यति न द्वेष्टि न शोचति न काङ्क्षति ।\nशुभाशुभपरित्यागी भक्तिमान् यः सः मे प्रियः ॥\n\nअत्र पूर्वोक्ताः केचन विचाराः पुनरुक्ताः। सामान्यतः विषयस्य अधिकस्पष्टीकरणाय, विचारस्य च अधिकभारदानाय पुनरुक्तिः क्रियते। अत्र कृष्णः वदति -- कमपि सत्कर्म कृत्वा मा हृष्य, अन्यान् दृष्ट्वा मा द्विष। किञ्चित् प्राप्तम् इति अतीव हर्षः, न प्राप्तम् इति दुःखं द्वेषो वा मा भूताम्। जीवने ज्ञानं भक्तिः वैराग्यं च शुभम्। अन्येषां सर्वेषां विषयाणां शुभाशुभविश्लेषणं मास्तु। अस्मिन् जगति किमपि आकस्मिकं नास्ति। अत्र घटमानस्य प्रत्येकस्य घटनायाः पृष्ठे अस्माभिः अज्ञातं कारणम् अस्ति एव। अतः तां शुभाशुभम् इति निश्चेतुं वयं समर्थाः न स्मः। एवं ज्ञात्वा जीवन् भक्तः मे प्रियः इति वदति कृष्णः।",
  "12.18": "समः शत्रौ च मित्रे च तथा मानापमानयोः ।\nशीतोष्णसुखदुःखेषु समः सङ्गविवर्जितः ॥\n\n[एतयोः श्लोकयोः (१२.१८ तथा १२.१९) पदच्छेदः, अर्थः, विवरणं च सह अग्रिमे श्लोके (१२.१९) दत्तम्।]",
  "12.19": "समः शत्रौ च मित्रे च तथा मानापमानयोः ।\nशीतोष्णसुखदुःखेषु समः सङ्गविवर्जितः ॥\n\nतुल्यनिन्दास्तुतिः मौनी सन्तुष्टः येन केनचित् ।\nअनिकेतः स्थिरमतिः भक्तिमान् मे प्रियः नरः ॥\n\nसामान्यतः वयं शत्रुः मित्रं वा इति भावं व्यावहारिकतया रोहयामः। यः अस्मान् प्रशंसति सः अस्माकं मित्रम्, यः अस्मदीयं दोषं निन्दति सः शत्रुः। इदम् अस्मदीयं अप्रौढं आचरणम्। स्नेहस्य पृष्ठे द्वेषः स्यात्, द्वेषस्य पृष्ठे स्नेहः स्यात्। पुरन्दरदासैः \"निन्दकाः स्युः\" इति गीतं स्मर्तव्यम् अत्र। निन्दकाः अस्मान् निन्दयित्वा अस्मासु विद्यमानानां निन्द्यानां दोषाणां फलं गृह्णन्ति। प्रशंसकाः प्रशंसया अस्मासु विद्यमानस्य साधुत्वस्य पुण्यफलस्य भागं लभन्ते। अतः साधनामार्गे प्रशंसकेभ्यः निन्दकाः साहाय्यकराः। अस्मात् कारणात् शत्रुमित्रविभागं कृत्वा कमपि निन्देत् द्वेषं वा न कुर्यात्। दुर्गुणात् दूरं भव, सद्गुणं प्रीणीहि। यत्र साधुत्वम् अस्ति तत्र मैत्री कुरु; दुःखं दृष्ट्वा द्रुत भव (करुणा); अन्यस्य सन्तोषं दृष्ट्वा सन्तुष्टः भव (मुदिता); दुष्टत्वात् दूरं भव (उपेक्षा)। मूलतः शत्रुमित्रविभागः न आवश्यकः। सर्वेषु भगवन्तं पश्य। लौकिकं शत्रुमित्रभावं त्यज।\n\nसन्मानं कृते सति मा उन्नम्यस्व, अपमानं कृते सति मा अवसीद। मानापमानौ जय। अन्यैः किम् उक्तम् इति न मुख्यम्; अस्मदीयम् अन्तरात्मा किम् इति मुख्यम्। अन्यैः प्रशंसिते सति अस्मासु अविद्यमानः गुणः अस्मान् आगत्य न मिलति। तथैव अन्यैः निन्दिते सति वयं अधः न गच्छामः। प्रशंसाविषये सावधानाः भवेम, यतः तया वयं मार्गभ्रष्टाः भवितुम् अर्हामः अधिकतया। अपमानेन वयं दुर्मार्गं त्यक्त्वा सन्मार्गे गत्वा उच्चैः आरोहितुं शक्नुमः।\n\nसुखदुःखे समानतया पश्य। काचिदपि वस्तुः अस्मभ्यं सुखदुःखं न ददाति; तां वस्तुं पश्यतः भावः एव अस्मभ्यं सुखदुःखं ददाति। अतः शीतोष्णवत् सुखदुःखे समानतां रोहयितुं अभ्यसनीयम्।\n\nअस्मभ्यं भासते इदं सर्वं मानवसहजप्रवृत्तिः (Instinct) इति। परन्तु इदं सहजधर्मः न भवति। आसक्त्या एव अस्मासु अनिष्टाः एते गुणाः पूर्यन्ते। अतः प्रशंसानिन्दयोः तत्क्षणं मा प्रतिक्रियस्व। मौनी भव। विषये मननं कुरु। मा त्वरस्व। यावत् अल्पं वक्तुं शक्यते तावदेव अल्पं वद। विचिन्त्य वद। यत् अस्ति तेन सन्तोषेण अनुभव। स्थिरचराणां वस्तूनां (Making own property) पृष्ठे मा गच्छ। भगवता दत्ते सन्तोषेण निश्चिन्ततया च जीव। भक्त्या भगवति शरणागतः सन् साधनामार्गे वयम् एतां उन्नतिम् आरोढुं शक्नुमः। \"एतादृशं गुणं धारयन् भक्तः मे प्रियः\" इति वदति कृष्णः।",
  "12.20": "ये तु धर्मामृतम् इदं यथोक्तं पर्युपासते ।\nश्रद्दधानाः मत्परमाः भक्ताः ते अतीव मे प्रियाः ॥\n\nधर्ममोक्षयोः साधनभूतम् इमं भक्तियोगम् अत्र उक्तेन प्रकारेण आचरन्तः, मम माहात्म्यं विश्वस्य तदनुसारं गच्छन्तः मयि च भक्तिं स्थापयन्तः -- एतादृशाः जनाः मे अतिप्रियाः भवन्ति।\n\nअस्मदीया भक्तिः कीदृशी भवेत्, भक्ते के गुणाः स्युः इति इमम् अमृत(मोक्ष)साधनधर्मम् विवृण्वन् कृष्णः, अत्र फलश्रुत्या वदति -- \"इह उक्तप्रकारेण उपासनां कुर्वन्तः, गुणधर्मं वर्धयन्तः, भक्त्या आचरणे आनयन्तः भक्ताः मे परमप्रियाः\" इति।\n\nइति द्वादशोऽध्यायः।",
  "13.1": "भगवान् उवाच\n\nइदं शरीरं कौन्तेय क्षेत्रम् इति अभिधीयते ।\nएतद् यः वेत्ति तं प्राहुः क्षेत्रज्ञः इति तद्विदः ॥\n\n\"क्षेत्र\" इति शब्दस्य निश्चितः एकः अर्थः नास्ति। अस्मिन् श्लोके क्षेत्रशब्दः कथं ग्रहीतव्यः इति सूचनां कृष्णः ददाति। क्षेत्रम् इत्युक्ते \"इदं शरीरम्\" इति कृष्णः वदति। अतः अत्र क्षेत्रम् इत्युक्ते जीवस्य निवासस्थानं, पिण्डाण्डात् ब्रह्माण्डपर्यन्तं सर्वम् एव। अस्मै ब्रह्माण्डाय \"क्षेत्रं शरीरं च\" इति नाम अन्वर्थम्। एतादृशं क्षेत्रं यः समग्रतया वेत्ति सः क्षेत्रज्ञः। कः एषः? अग्रिमे श्लोके पश्यामः।",
  "13.2": "क्षेत्रज्ञं च अपि मां विद्धि सर्वक्षेत्रेषु भारत ।\nक्षेत्रक्षेत्रज्ञयोः ज्ञानं यत् तत् ज्ञानं मतं मम ॥\n\nअन्तः बहिः च व्याप्तः, सर्वक्षेत्रेषु निवसन् भगवान् एव क्षेत्रज्ञः। जीवः केवलं क्षेत्रस्थः। सत्यं ज्ञानम् इत्युक्ते विश्वस्य अवबोधः; विश्वे व्याप्तस्य भगवतः अवबोधः। अस्मिन् विश्वे वयं कथं स्थिताः? इदं विश्वं अस्मभ्यं कथं बन्धकं जातम्? इमं बन्धं त्यक्त्वा तं विश्वात्मानं भगवन्तं वयं कथं प्राप्नुयाम? इदम् एव अवबोधः ज्ञानम्। पूर्वाध्याये उक्तं यत् वयं पञ्चदशवेष्टनानां कारागारे स्थिताः। परं इदं दण्डनं न भवति, शिक्षणम्। अस्मात् बन्धनात् मोक्षाय भवमोचकं क्षेत्रज्ञं ज्ञातव्यम्। एषा जागृतिः एव सत्यं ज्ञानम्।",
  "13.3": "तत् क्षेत्रं यत् च यादृक् च यत् विकारि यतः च यत् ।\nसः च यः यत् प्रभावः च तत् समासेन मे शृणु ॥\n\nप्रथमं क्षेत्रम् इत्युक्ते किम्? ब्रह्माण्डं पिण्डाण्डं च कथं केन च निर्मितम्? तस्य गुणधर्मः कः? तत् कीदृशैः प्रकारैः रूपान्तरं गच्छति? एते परिवर्तनाः कथं भवन्ति? केन भवन्ति? एतत् सर्वं सूत्ररूपेण संक्षेपेण, अल्पाक्षरेण मत्तः शृणु।",
  "13.4": "ऋषिभिः बहुधा गीतं छन्दोभिः विविधैः पृथक् ।\nब्रह्मसूत्रपदैः च एव हेतुमद्भिः विनिश्चितैः ॥\n\nनानाविधैः पृथक्भूतैः मन्त्रैः ऋषिभिः एतत् बहुधा गीतम्। युक्त्या निश्चयं कुर्वतः वेदान्तसूत्रस्य पदानि अपि एतदेव प्रतिपादयन्ति।",
  "13.5": "ज्ञानिनः अपि एतद्विषयम् एकैकशः भिन्नभिन्नप्रकारेण वदन्ति। तत् तेषां स्वानुभवपर्यन्तम् एव सीमितम्। ब्रह्मसूत्रे उक्तो विषयः सुखेन न बुध्यते। अतः क्षेत्रज्ञः स्वयम् अहम् एव सत्यं साक्षात् वदामि, शृणु।",
  "13.6": "महाभूतानि अहङ्कारः बुद्धिः अव्यक्तम् एव च ।\nइन्द्रियाणि दश एकं च पञ्च च इन्द्रियगोचराः ॥\n\nइच्छा द्वेषः सुखं दुःखं सङ्घातः चेतना धृतिः ।\nएतत् क्षेत्रं समासेन सविकारम् उदाहृतम् ॥\n\nपृथ्वी[पृथिवी], जलम्[वरुणः], अग्निः[अग्निः], वायुः[वायुपुत्रः मरीचिः], आकाशः[अवकाशदेवता विघ्ननाशकः विनायकः गणपतिः] इति पञ्च महाभूतानि। अहङ्कारतत्त्वम्[ब्रह्मा वायुः शिवः च], बुद्धितत्त्वम्[पार्वती], मूलप्रकृतिः[श्रीः], श्रोत्रम्[चन्द्रः], त्वक्[वायुपुत्रः मरुत्], चक्षुः[सूर्यः], जिह्वा[वरुणः], घ्राणम्[अश्विनौ], वाक्[अग्निः], पाणी[वायुपुत्रौ], पादौ[इन्द्रपुत्रौ यज्ञः शम्भुः च], पायुः[यमः], उपस्थः[लिङ्गदेवता शिवः पुरुषेषु, स्वायम्भुवमनुः स्त्रीषु] इति दश इन्द्रियाणि। एकादशं मनस्तत्त्वम्[इन्द्रः कामः अनिरुद्धः च], शब्दस्पर्शरूपरसगन्धाः इति पञ्च इन्द्रियविषयाः[रुद्रपुत्राः प्राणापानव्यानोदानसमानाः] -- एवं चतुर्विंशतिः संक्षेपेण क्षेत्रतत्त्वानि।\n\nइच्छा[श्रीः भारती च], द्वेषः[द्वापरः शकुनिः], सुखम्[मुख्यप्राणः वायुः भीमः], दुःखम्[कलिः दुर्योधनः], समष्टिशरीरम्[शरीरस्थः अभिमानी जीवः, सर्वे अभिमानिदेवताः], स्मृतिविस्तारः[श्रीः], धृतिः[सरस्वती भारती च] इति सप्त विकाराः। एवं विकारैः सह क्षेत्रं संक्षेपेण उक्तम्।\n\nअनयोः श्लोकयोः कृष्णः क्षेत्रं तस्य विकारं च विवृतवान्। क्षेत्रम् इति अखण्डघटकस्य अन्तः स्थितान् जगतः घटकांशान् कृष्णः अत्र सूत्ररूपेण संक्षेपेण विवृणोति। प्रथमं पञ्चमहाभूतानि। एतैः पञ्चभिः पिण्डाण्डं ब्रह्माण्डं च निर्मितम्। अस्मात् कारणात् ब्रह्माण्डं \"प्र-पञ्च\" इति उच्यते। एतानि पञ्च महाभूतानि एव प्रपञ्चस्य मूलद्रव्यम्। पिण्डाण्डे एतानि पञ्चमहाभूतानि अन्नमयम् प्राणमयम् च इति उच्यन्ते। दृश्यं स्थूलं शरीरं पृथिवीजलभागाभ्यां निर्मितम्। एतादृशस्य स्थूलशरीरस्य अन्तः अदृश्यं प्राणमयकोशम् अस्ति। देहस्य तापः(अग्निः), श्वासः(वायुः), अन्तः रक्तवायुसञ्चारावकाशः(आकाशः)। अस्मात् परं मनोबुद्धियुक्तं मनोमयकोशम्, ततः परं विज्ञानमयकोशः -- स्मरणशक्तिः। अतः बुद्धेः पूर्वं अहङ्कारः चित्तं च। अत्र अहङ्कारः इत्युक्ते \"मम अस्तित्वस्य अवबोधः\" (awareness of self)। एतत् अहङ्कारतत्त्वं पिण्डाण्डे चित्तम्, ब्रह्माण्डे महत्तत्त्वम्।\n\nव्यक्तस्य अस्य प्रपञ्चस्य मूलम् अव्यक्तम्। सृष्टेः मूलस्थितिः प्रलयसागरः, अर्थात् परमाणुरूपेण विकीर्णम् अव्यक्तं जगत्। एतादृशे जगति चतुर्मुखेन महत्तत्त्वं सृष्टम्। प्रलयसागरे स्वास्तित्वावबोधरहितानां जीवानां \"अहम्\" इति अवबोधः आगमनम् एव महत्तत्त्वस्य सृष्टिः। चित्तस्य व्याप्तिः चेतना। इयम् अस्मदीयस्य स्मरणस्य विस्तारः।\n\nअस्मिन् शरीरे पञ्च ज्ञानेन्द्रियाणि पञ्च कर्मेन्द्रियाणि च सन्ति। एकादशम् इन्द्रियं मनः। श्रोत्रेण शब्दग्रहणम्, चक्षुषा रूपग्रहणम्, घ्राणेन गन्धग्रहणम्, जिह्वया रसग्रहणम्, त्वचा स्पर्शग्रहणम्। तथैव वाक् वदितुम्, पाणिः कर्तुम्, पादः गन्तुम्। एतानि अष्टौ ग्रहाणि (sense organs) इति उच्यन्ते। ततः पायुः उपस्थः च (विसर्जनाङ्गं सन्तानवृद्ध्यङ्गं च)। एतत् सर्वं चिन्तनाधीनं कुर्वत् एकादशम् इन्द्रियं मनः। एतानि सर्वाणि क्षेत्रस्य घटकांशाः। समष्ट्या एतत् क्षेत्रम्। [अत्र उक्तस्य प्रत्येकस्य घटकस्य सह तस्य अभिमानिदेवता अपि सन्ति, तत् उपरि संक्षेपेण उक्तम्।]\n\nइदं जगत् सदा परिवर्तनशीलम्। अत एव जगत् \"अश्वत्थम्\" इति अपि उच्यते। अश्वः निरन्तरं चलनशीलः प्राणी, सः निश्चलः कदापि न भवति। इदं प्रपञ्चम् अपि तथैव सदा चलनशीलम् अतः प्राचीनैः अश्वत्थम् इति आहूतम्। अस्मदीयं शरीरं भौतिकः विकारः। तस्मिन् जायमानाः मानसप्रपञ्चस्य सर्वे तोलनाः मानसविकाराः। विशेषतः अस्मदीया इच्छा, (अ)द्वेषः, सुखदुःखे, अस्मदीया स्मृतिविस्तारः (चेतना), (अ)धृतिः। इदं कृष्णस्य क्षेत्रस्य तद्विकारस्य च सूत्ररूपं विवरणम्। एतद्विषयं यावद्विस्तारं वयं विश्लेषयितुं शक्नुमः। कृष्णः अत्र सर्वं संक्षेपेण विवृतवान्।\n\nज्ञानमार्गे गन्तुं अस्मदीये आचरणे पालनीयाः काश्चन नीतिसंहिताः सन्ति। ताः अस्माभिः अनुसर्तव्याः। अस्मदीये जीवने अनुसर्तव्यान् विंशतिगुणान् (twenty virtues) कृष्णः अग्रिमेषु पञ्चसु श्लोकेषु विवृणोति। एतेषु गुणेषु प्रत्येकं यावद्अधिकं वयं स्वजीवने आचरामः तावद् वयं ज्ञानमार्गे गन्तुं शक्नुमः। अन्यथा वयम् अज्ञानमार्गे गन्तव्यं भवति इति एतद् एचरिकाम् अपि कृष्णः अत्र दत्तवान्।",
  "13.7": "अमानित्वम् अदम्भित्वम् अहिंसा क्षान्तिः आर्जवम् ।\nआचार्योपासनम् शौचम् स्थैर्यम् आत्मविनिग्रहः ॥\n\nगर्वत्यागः, महत्त्वाडम्बरत्यागः, अपीडनम्, सहनशीलता, ऋजुः आचारः, गुरुसेवा, कायमनःशुद्धिः, अकम्पितः निश्चयः, चित्तस्य दृढता -- इत्यर्थेन एतत् वर्णितम्।\n\n(१) अमानित्वम् -- ज्ञानप्राप्त्यर्थं मानसम्मानयोः इच्छा त्याज्या। \"मह्यं सन्मानं स्यात्, पुरस्कारः स्यात्\" इति अपेक्षमाणेभ्यः ज्ञानं कदापि न सिध्यति। अतः प्रचारप्रियता प्रथमं त्याज्या। सर्वान् प्रचारान् तिलाञ्जलिं दत्त्वा ज्ञानस्य पृष्ठे लग्नः भव, तदा ज्ञानं दक्ष्यति। कश्चित् त्वां प्रशंसति चेत् तत् तस्य औदार्यम् -- तत्र नम्रः भव।\n\n(२) अदम्भित्वम् -- सर्वेषां पुरतः लघुतया जीवितुं शिक्ष। महत्त्वप्रदर्शनं मा कुरु। ज्ञानमार्गे कदापि प्रामाणिकतायाः न विचल। अविद्यमानं विद्यमानम् इति दर्शयितुं मा गच्छ।\n\n(३) अहिंसा -- कदापि अन्यं मा पीडय। अन्यस्य मनः घातयाम चेत् तत् पुनः स्वस्थं कर्तुं कोऽपि औषधः नास्ति। अतः कदापि अन्यस्य मुखभङ्गं (face-saving) मा कुरु। अन्येभ्यः पीडां अददत् एव अहिंसा।\n\n(४) क्षान्तिः -- अप्रतीकारः। कश्चित् अस्मभ्यं अनिष्टं कुर्यात् चेत् वयं तत्प्रतीकारं कर्तुं न गच्छेम। अपराधिनां दण्डाय एका व्यवस्था अस्ति। लौकिकदृष्ट्या कश्चित् अपराधं कुर्यात् चेत् तस्मै दण्डदानस्य दायित्वं आरक्षकन्यायव्यवस्थयोः एव, न अस्माकम्। यदि वयं अपराधिनं दण्डयितुं प्रवर्तेमहि, तत् कानूनं स्वहस्ते गृहीतम् अपराधः भवति। तथैव भगवतः राज्ये अपराधिनां दण्डाय पृथक् व्यवस्था अस्ति। अतः तुभ्यं प्रतीकारस्य वा शापदानस्य वा अधिकारः नास्ति।\n\nएतेषां गुणानाम् उत्तमे दृष्टान्ते जडभरतः रैक्वमुनिः च। तयोः जीवनचरित्रं पठितं चेत् तौ एतान् गुणान् स्वजीवने कथं पालितवन्तौ इति ज्ञायते।\n\n(५) आर्जवम् -- मुखवाटरहितं जीवनम्। ऋजुः आचारः वाक् च। अन्तः भिन्नं बहिः भिन्नं यत् नास्ति तादृशं प्रामाणिकं जीवनम् (honest life)।\n\n(६) आचार्योपासनम् -- आचार्यः इत्युक्ते किं सम्यक् किम् असम्यक् इति सम्यक् ज्ञात्वा तत् आचरणे आनयन्तः। स्वयं सत्यं दृष्ट्वा समाजस्य पुरतः तत् आचरित्वा दर्शयन्तः। तादृशानां सेवां कुरु। ज्ञानिनः सुलभं न लभ्यन्ते, ते सामान्यतः अपरीक्ष्य ज्ञानधारां न कुर्वन्ति। यत् किमपि भवतु, ज्ञानिनां पृष्ठं मा त्यज। त्वयि विद्यमाना ज्ञानतृष्णा गाढा चेत् ते निश्चयेन ज्ञानधारां कुर्वन्ति। ज्ञानम् अपेक्षसे चेत् ज्ञानिनः स्वयं उद्घाटयन्ति यावत् प्रतीक्षणीयम्। अत्र उत्तमे दृष्टान्ते श्वेतकेतोः प्रश्नोपनिषदि आगच्छतः पिप्पलादस्य च कथा।\n\n(७) शौचम् -- शौचम् इत्युक्ते शुचित्वम्। एतद्विषयं पूर्वाध्याये किञ्चित् दृष्टवन्तः। कायवाङ्मनःशुद्धिः शौचम्। स्नानं कृत्वा आर्द्रवस्त्रं धृत्वा कमपि अस्पृशत् चेदपि तेन शौचं न सिध्यति। शुचित्वं मूलतः मनःसम्बद्धम्, तस्य पोषकं देहशुद्धिः। प्रापञ्चिकं विचारं विस्मृत्य मनः भगवति स्थापयितुम् एव शौचम्। वयं कायेन वाचा मनसा च शुचयः भवितव्याः। अस्मासु दुष्टचिन्ता आगच्छति चेत्, दुष्टवचनं मुखे आगच्छति चेत् -- तदा वयं मलिनाः। सत्यं कायवाङ्मनसा शुचिः मलिनैः सह तिष्ठति चेदपि सहवासिनः सर्वे शुचयः भवितुम् अर्हन्ति। इदमेव पूर्वं \"पङ्क्तिपावनः\" इति उच्यते स्म। पूर्णशुचिः यस्यां पङ्क्तौ उपविष्टः सा पङ्क्तिः शुचिः। शास्त्रज्ञानरहितं शौचं शौचं न भवति। देवस्मरणं मनसि, देवनाम मुखे भवति यदा तदा वयं शुचयः।\n\nमनःशुद्ध्यर्थम् आचमनं प्राणायामश्च। \"हे भगवन्, त्वदीयया करुणाधारया मम सहस्रारात् अमृतम् अधः अवतारय, मम सर्वं देहं पावनं कुरु, मदन्तः सर्वाणि पापानि मलानि च दग्ध्वा प्रक्षाल्यताम्\" इति अनुसन्धानेन, ध्यानपूर्वकं पापपुरुषनिरसनं कर्तव्यम्। अत्र अस्मदीयात् शिरसः अमृतधारा अवतरन्ती वयम् अनुभवेम।\n\n(८) स्थैर्यम् -- मनसः स्थिरता (Steadfastness) स्थैर्यम्। अस्मभ्यं स्वकीयः स्वतन्त्रः निश्चयः आवश्यकः। केनापि उक्तमात्रेण वयं स्वनिश्चयं परिवर्तयन्तः न सन्देहमग्नाः भवेम। वयं स्वशिरसा एव चिन्तयितुं समर्थाः भवेम। यत्किञ्चित् प्रश्नः आगच्छति चेत् तस्य उत्तरं अन्वेष्टुं सामर्थ्यम् अस्मदीये शिरसि एव अस्ति। \"यत्र प्रश्नः तत्रैव उत्तरम् अपि अस्ति\"। शास्त्रं सम्यक् अधीत्य त्वं स्वयम् एव स्वसमस्यायाः उत्तरं ज्ञात्वा दृढतया कार्यं कुरु। येन केनचित् उक्तं श्रुत्वा सन्देहमग्नः अभूत्वा स्थैर्यं साधय।\n\n(९) आत्मविनिग्रहः -- इन्द्रियनियन्त्रणम् (self control)। अस्मदीयानि इन्द्रियाणि अस्मदीये वशे स्युः। इन्द्रियाणि वशे स्थातुं वयं स्वमनः वशे स्थापयेम। मनसः हस्ते त्वं वानरः मा भव, मनः त्वं नियन्त्रय। एतदर्थं स्वमनः देवे स्थापय। एवं मनोनिग्रहेण इन्द्रियनिग्रहं साधय।",
  "13.8": "इन्द्रिय अर्थेषु वैराग्यम् अनहङ्कारः एव च ।\nजन्म मृत्यु जरा व्याधि दुःख दोष अनुदर्शनम् ॥\n\nइन्द्रियविषयेषु अमोहः, गर्वरहितत्वम्, जन्ममृत्युजराव्याधिभिः दुःखपूर्णस्य जीवनस्य दोषाणां अवबोधः --\n\n(१०) इन्द्रियार्थेषु वैराग्यम् -- इन्द्रियाणि बहिःप्रपञ्चं प्रति प्रवहन्तः निरुध्य मनः भगवति स्थापनीयम्। एतत् शमदमौ इति उच्यते। इन्द्रियाणि लौकिकविषयं प्रति न प्रवहन्तु इति करणं दमः, तानि भगवन्तं प्रति प्रवाहयितुं करणं शमः। भगवन्तं ज्ञात्वा इन्द्रियं अन्यत्र न प्रवहति। प्रापञ्चिकेषु शब्दस्पर्शरूपरसगन्धेषु विरक्तिं धारय। उदाहरणार्थं जिह्वा चपला। अस्मासु केचन गृहे यथा कथाचिद् पाकं कृते सत्यपि \"इदं न सम्यक्, तद् न सम्यक्\" इति दोषम् आरोपयन्ति। एतादृशीं चपलतां त्यज। अत्र इष्टानिष्टयोः चयनं विना यत् किमपि प्राप्तं तत् भगवतः प्रसादम् इति स्वीकर्तुं शिक्षस्व। एवं शमदमौ साधय।\n\n(११) अनहङ्कारः -- इदं सर्वेषां गुणानां श्रेष्ठतमः गुणः। अस्मासु यः कोऽपि गुणः स्यात्, सः अस्मदीयस्य अहङ्कारस्य पुरतः व्यर्थः। अहङ्कारः (Attachment) अस्मदीयान् सर्वान् गुणान् नाशयति। अहङ्कारे सति शेषाणां गुणानाम् अस्तित्वम् एव नास्ति। अतः कृष्णः तं \"एव-च\" इति भारपूर्वकम् उक्तवान्। \"अहं विद्वान्, अहम् अनुष्ठानवान्, अहं शुचिः\" इति अहङ्कारः प्रत्येकं विचारे अस्मान् पीडयति। एवं वयम् अहङ्कारं धरेम चेत् अस्मदीयम् अनुष्ठानम् अनुष्ठानम् एव न भवति। यत्र अहङ्कारः पीडयति तत्र साधना व्यर्था भवति। यत्र अहङ्कारः तत्र देवः न वसति -- अर्थात् अहङ्कारेण वयं देवात् दूरं गच्छामः। अस्मात् कारणात् \"मया कृतम्, मया एव अभवत्\" इति स्फीतिं त्यज। भगवता मम हस्ताभ्यां कारितम् इति तस्मै कृतज्ञतां दर्शय।\n\n(१२) जन्ममृत्युजराव्याधिदुःखदोषानुदर्शनम् -- जीवनम् अन्तर्दृष्ट्या पश्य। इदं जीवनम् इत्युक्ते जन्ममृत्यू इति द्वयोः तटयोः मध्ये प्रवहन् एकः प्रवाहः। अस्मिन् प्रवाहे व्याधिः, जरा, दुःखं, शोकः इति तरङ्गाणां शृङ्खला। अस्मदीयस्य जीवनस्य उद्देश्यं किम्, भगवान् अस्मान् किमर्थं जनितवान्, मानवजन्म कथं सार्थकं कर्तव्यम् -- इति अनुदर्शनं कुरु। आहारः निद्रा भयं मैथुनम् इत्येतावता जीवनं न भवति। इदं पशवोऽपि अनुभवन्ति। अतः शास्त्रं पठित्वा सत्यानुगुणं यथार्थदर्शनं कुरु। केवलं लौकिकसुखस्य अपेक्षायां जीवनं त्यक्त्वा -- सत्यसाक्षात्काराय, भगवत्प्राप्त्यर्थं जीव। सर्वं लौकिकं सुखं सम्पत्तिः च निस्सारम्। अस्मात् परं सारभूतं भगवन्तं ज्ञात्वा तं प्रति पदं निधेहि।",
  "13.9": "असक्तिः अनभिष्वङ्गः पुत्र दार गृह आदिषु ।\nनित्यम् च समचित्तत्वम् इष्ट अनिष्ट उपपत्तिषु ॥\n\n[एतेषां त्रयाणां श्लोकानां (१३.९, १३.१० तथा १३.११) पदच्छेदः, अर्थः, विवरणं च सर्वं मिलित्वा अग्रिमे श्लोके (१३.११) दत्तम्।]",
  "13.10": "मयि च अनन्ययोगेन भक्तिः अव्यभिचारिणी ।\nविविक्त देश सेवित्वम् अरतिः जन संसदि ॥\n\n[एतेषां त्रयाणां श्लोकानां (१३.९, १३.१० तथा १३.११) पदच्छेदः, अर्थः, विवरणं च सर्वं मिलित्वा अग्रिमे श्लोके (१३.११) दत्तम्।]",
  "13.11": "असक्तिः अनभिष्वङ्गः पुत्र दार गृह आदिषु ।\nनित्यम् च समचित्तत्वम् इष्ट अनिष्ट उपपत्तिषु ॥\n\nमयि च अनन्ययोगेन भक्तिः अव्यभिचारिणी ।\nविविक्त देश सेवित्वम् अरतिः जन संसदि ॥\n\nअध्यात्म ज्ञान नित्यत्वम् तत्त्वज्ञान अर्थ दर्शनम् ।\nएतत् ज्ञानम् इति प्रोक्तम् अज्ञानम् यत् अतः अन्यथा ॥\n\nआसक्तिराहित्यम्, पुत्रदारगृहादिषु अत्यन्तम् न आसक्तिः, इष्टानिष्टयोः प्राप्तयोः सदा चित्तस्य अविचलनम्, अन्यत्र न चलित्वा मयि एव अचला भक्तिः, एकान्तवासः, जनजङ्गुल्यां न मिश्रणम्, अध्यात्मावबोधे एव निरन्तरा स्थितिः, अपरोक्षज्ञानाय शास्त्राध्ययनम् -- [तत्त्वज्ञानाय गोचरस्य भगवतः साक्षात्कारः] एतानि एव ज्ञानं ज्ञानसाधनानि च। अस्मात् अन्यत् यत् तत् अज्ञानं तस्य च मार्गः।\n\n(१३) असक्तिः -- \"सक्तिः\" इत्युक्ते हचिकोळ्ळुवुदु अथवा अंटिसिकोळ्ळुवुदु (आसक्तिः)। एतद्विषये वयं पूर्वं बहुवारं चर्चितवन्तः। अस्मदीयस्य सर्वस्य दुःखस्य मूलकारणम् आसक्तिः। अतः किमपि मा आसज्य। जन्मकाले मृत्युः किमपि न आनीतवान्, मरणकाले किमपि न नेष्यति। अतः लौकिकाद् अस्मात् आसक्तेः दूरं तिष्ठ। प्राप्तं भगवत्प्रसादम् इति स्वीकुरु, गतं भगवत इच्छा इति सन्तुष्टः भव।\n\n(१४) अनभिष्वङ्गः पुत्रदारगृहादिषु -- अभिष्वङ्गः इत्युक्ते अतिशयेन आसक्तिः (Over-attachment)। गृहं, पत्नी/पतिः, पुत्राः इत्यादीन् अतिशयेन मा आसज्य इति कृष्णः वदति। अत्र गृहसंसारम् आसक्त्या न त्यजतु इत्युक्ते सर्वं त्यक्त्वा वनं गन्तव्यम् इति न। \"एतद् विना अहं स्थातुं न शक्नोमि\" इति अभिष्वङ्गः त्याज्यः इत्येव। जीवने यत् किमपि आगच्छति तत् साक्षिभावेन पश्य। जीवनम् एव नाटकम्, तत्र त्वमेव पात्रधारी, त्वमेव प्रेक्षकः। भगवान् निर्देशकः। \"मम पुत्राः एव मम जीवनम्, मम पतिः/पत्नी मम जीवनम्, मम अर्जनम् एव मम जीवनम्, एतद्विना मम अस्तित्वं नास्ति\" इति अतिशयितः अभिष्वङ्गः न स्यात्। प्रीणीहि -- परं आसज्य मा कुण्ठस्व, मा निराशः भव। एवं जीवितुं शिक्षिते सति जीवनं सुन्दरं भवति। अस्मत्तः अस्मदीयाः पुत्राः दूराः भवेयुः, पत्नी/पतिः दूरः भवेत्, अस्मदीयां सम्पत्तिं (गृहं, धनं च) हरेम चेत्, तदापि दुःखं निराशा च न भवेत्। एवं जीविते सति जीवने यत् किमपि दुरन्तम् आगच्छतु, तत् अस्मदीयस्य पात्राभिनयस्य अंशः इति भावेन वयं तत् स्वीकर्तुं शक्नुमः -- आघातः न भवति।\n\n(१५) नित्यं च समचित्तत्वम् इष्टानिष्टोपपत्तिषु -- जीवने इष्टा घटना भवेत्, अनिष्टा घटना अपि भवेत्। इष्टानिष्टयोः उपस्थितौ मनसः सन्तुलनं अत्यक्त्वा सर्वदा समचित्ततया स्थातुं शिक्ष। वयम् अनिष्टम् इति मन्यमहे तत् अनिष्टम् एव भवितव्यम् इति नास्ति, अथवा वयम् इष्टं मन्यमहे तत् श्रेयस्करम् एव भवितव्यम् इति नास्ति। अतः इष्टानिष्टलेपं विना प्राप्तं \"नाहं कर्ता हरिः कर्ता\" इति स्वीकर्तुं शिक्ष। अस्मदीये जीवने घटमाना प्रत्येका घटना भगवता अस्मदीयप्रशिक्षणाय सृष्टं प्रायोगिकं (Practical) शिक्षणम्। भगवान् अस्मभ्यं दुःखं दत्त्वा अस्मान् चतुरान् करोति इति सत्यम् अवगत्य जीव।\n\n(१६) मयि च अनन्ययोगेन भक्तिः अव्यभिचारिणी -- भगवति निरन्तरा परिशुद्धा भक्तिः स्यात्। भगवान् एकः, तस्य नाम बहूनि। तस्मिन् अनन्यां भक्तिं धारय। अत्र एकभक्तिः अतिमुख्या। दिने दिने भिन्नं देवं पूजयितुम्, एकां देवतां पूजिते सति अपरा देवता कुप्येत् इति भयेन बहुदेवतार्चनं यदि क्रियते तत् व्यभिचारः भवति। अतः कृष्णः अत्र \"त्वदीया भक्तिः अनन्या अव्यभिचारिणी च स्यात्\" इति भारपूर्वकम् उक्तवान्। भगवान् सर्वसमर्थः, सर्वशक्तः, जगत्कारणम् इति निष्ठा त्वयि स्यात्। देवे विश्वासं विना कमपि शास्त्रं पठित्वा उपयोगः नास्ति। भगवति पूर्णविश्वासेन एव ज्ञानसाधना साध्या।\n\n(१७) विविक्तदेशसेवित्वम् -- यथाशक्ति अतिसात्त्विककम्पनयुक्ते स्थाने, सात्त्विकजनैः सह वस्तुं यत्नस्व। पूर्णप्रमाणेन अखण्डसात्त्विककम्पनयुक्तं स्थानं पुण्यक्षेत्रम् इति उच्यते। तादृशे स्थाने सद्वचनं वदतां सच्चिन्तनं कुर्वतां सज्जनानां सह वस। इदं न शक्यते चेत् यथाशक्ति एकान्तवासम् अभ्यस्य। चतुर्भिः जनैः सह मिलित्वा निरर्थकालापे स्वदुर्लभं जन्म मा व्यर्थीकुरु।\n\n(१८) अरतिः जनसंसदि -- यत्र अनावश्यकविचारार्थं जनजङ्गुल्यः सम्मिलन्ति, तादृशाभ्यः जनजङ्गुल्याभ्यः दूरं तिष्ठ।\n\n(१९) अध्यात्मज्ञाननित्यत्वम् -- अध्यात्मावबोधे निरन्तरः भव। प्रथमं पिण्डाण्डब्रह्माण्डे जानीहि, ततः एतत् जानतः अपूर्वस्य मनसः विस्मयं जानीहि, ततः \"अहम्\" इत्युक्ते किम् (awareness of self) इति जानीहि। इदं ज्ञात्वा एतम् आत्मानं नियन्त्रयन्तं परमात्मानं जानीहि। इदम् अध्यात्मज्ञानम्। त्वदीयस्य अध्ययनस्य लक्ष्यम् अध्यात्मज्ञानम् एव स्यात्।\n\n(२०) तत्त्वज्ञानार्थदर्शनम् -- जगतः मूलभूतं सत्यं ज्ञातुं त्वदीयम् अध्ययनं समर्पितं भवतु। उपर्युक्तैः सर्वैः गुणैः सर्वशास्त्रविषयभूतस्य, सर्वशास्त्रैः प्रतिपाद्यस्य भगवतः साक्षात्कारं प्राप्नुहि।\n\nअत्र उक्ताः गुणाः एव ज्ञानं ज्ञानसाधनानि च। अस्मात् भिन्नं यत् तत् अज्ञानं तस्य च लक्ष्यम्।\n\nज्ञानसाधनानि विवृत्य कृष्णः अग्रिमेषु षट्सु श्लोकेषु शब्दस्य सीमातः परस्थस्य भगवतः वर्णनम् अस्मत्पुरतः स्थापयति। देवः कीदृशः, तस्य रूपस्य अनुसन्धानं कथं कर्तव्यम् इति विषयं कृष्णः अत्र सुन्दरतया वर्णयति। एतेषु श्लोकेषु परस्परं व्यतिरिक्तानि (Contradicting) इव दृश्यमानानि अनेकानि विषयाणि वयं पश्यामः। उदाहरणार्थम् -- भगवान् निर्गुणः परं सः सर्वगुणपूर्णः; भगवान् अचलः परं सः चलति; भगवान् निराकारः परं सः साकारः; भगवन्तं ज्ञातुम् असाध्यं परं तं ज्ञातुं शक्यते; भगवते इन्द्रियाणि न सन्ति परं तस्य इन्द्रियाणि सन्ति; सः दूरे अस्ति परं समीपे अस्ति; इत्यादि। एतादृशं वर्णनं भगवते विना अन्यस्मै दातुं न शक्यते। एतत्सर्वस्य विवरणम् अग्रिमेषु श्लोकेषु द्रष्टुं शक्यते।",
  "13.12": "ज्ञेयम् यत् तत् प्रवक्ष्यामि यत् ज्ञात्वा अमृतम् अश्नुते ।\nअनादि मत्परम् ब्रह्म न सत् तत् न असत् उच्यते ॥\n\nयत् ज्ञात्वा अमृतत्वं प्राप्नोषि तत् ज्ञेयं वक्ष्यामि -- अनादिः, मत्परः, पञ्चभूतात्मकाकाररहितः, ज्ञानानन्दस्वरूपः ब्रह्म एव ज्ञेयः।\n\nअत्र कृष्णः ज्ञानसाधनैः ज्ञातव्यस्य ज्ञेयस्य विषये विवृण्वन् वदति -- \"यत् साक्षात् शब्दैः वक्तुं न शक्यते, यत् ज्ञानं ज्ञात्वा त्वम् अमृतत्वम् आस्वादयसि -- तत् अहं तुभ्यं वदामि\" इति। भगवान् अनादिमत्। तस्य नश्वरैः पञ्चभूतैः निर्मितः कोऽपि आकारः नास्ति। सः ज्ञानानन्दस्वरूपः। भगवतः गुणक्रिये सर्वे अनादिमन्तः। सद्गुणैः पूर्णः भगवान् अस्मभ्यं पूर्णत्वं ददाति। सः सर्वरक्षकः, तस्मात् श्रेष्ठतरं तत्त्वम् अन्यत् नास्ति। एतादृशं भगवन्तं वयं पूर्णतया ज्ञातुं न शक्नुमः। तत् अस्मदीयायाः बुद्धेः अगोचरम्। तथापि तं स्वसामर्थ्यानुगुणं यथार्थं ज्ञातुं शक्यते।",
  "13.13": "सर्वतःपाणिपादम् तत् सर्वतः अक्षि शिरः मुखम् ।\nसर्वतः श्रुतिमत् लोके सर्वम् आवृत्य तिष्ठति ॥\n\nभगवान् सर्वत्र पूर्णः, तस्य सर्वत्र हस्तपादाः, सर्वत्र श्रोत्रमुखनेत्राणि (संस्कृते \"मुख\" शब्दस्य अर्थः मुखं च वदनं च; एतस्य समृद्धस्य भाषायाः \"बाय्\" इति विशिष्टः पृथक् शब्दः नास्ति)। अतः भगवते अज्ञातं किमपि कार्यं कर्तुं वयं न शक्नुमः। सः सर्वज्ञः सर्वगतः सर्वसमर्थः। इदं सर्वं श्रुतिः प्रमाणयति। आदौ वेदम् उच्चारितवान् भगवान् एव। सः सर्वस्य अन्तः बहिः च आवृत्य तिष्ठति। अखण्डस्य भगवतः अन्तः तस्य अनन्तानि रूपाणि सन्ति। प्रतिरूपं ज्ञानानन्दमयानि, स्वरूपभूतानि इन्द्रियाणि सन्ति। अस्मदीये सर्वस्मिन् इन्द्रिये अपि सः व्याप्य नयति।",
  "13.14": "सर्वेंद्रिय गुण आभासं सर्वेंद्रिय विवर्जितम् ।\nअसक्तम् सर्वभृत् च एव निर्गुणम् गुणभोक्तृ च ॥\n\nभगवान् सर्वेषाम् इन्द्रियविषयग्रहणस्य कारणम्। तस्य तु पाञ्चभौतिकानि, नश्वराणि, अस्मद्वत् एकदा नङ्क्ष्यमाणानि, स्वस्वरूपात् भिन्नानि कानिचिद् इन्द्रियाणि न सन्ति। इदं जगत् धारयन् तातः सः भगवान् पुमान्; जगत् प्रसूता सा माता अपि सः एव। भौतिकदृष्ट्या सः न पुमान्, न स्त्री। सः स्वरूपभूतया पुमान् अपि, स्त्री अपि। भगवान् सर्वेषाम् अन्तः पूर्णः, परं सः किमपि न आसक्तः। सः सर्वं धारयति, परं तस्य बन्धस्य सम्बन्धः (bond) नास्ति। भगवान् त्रिगुणातीतः, तस्य त्रिगुणानां सम्बन्धः नास्ति। परं सः सद्गुणानां आश्रयः। सः निराकारः अपि, साकारः अपि।",
  "13.15": "बहिः अंतः च भूतानाम् आचरम् चरम् एव च ।\nसूक्ष्मत्वात् तत् अविज्ञेयम् दूरस्थम् च अंतिके च तत् ॥\n\nभूताः इत्युक्ते समस्तं ब्रह्माण्डं, समस्तं जीवजातं (पिण्डाण्डम्) च। भगवान् अस्य ब्रह्माण्डस्य अन्तः बहिः च व्याप्तः। नारायणोपनिषदि उक्तं यथा \"अन्तर्बहिश्च तत्सर्वं व्याप्य नारायणः स्थितः\" इति। अस्माकम् अन्तः बहिः च पूर्णः, सर्वं व्याप्य स्थितः भगवान् नारायणः। अतिक्षुद्रात् जीवात् आरभ्य चतुर्मुखब्रह्मपर्यन्तं सर्वेषाम् अन्तः बहिः च भगवान् व्याप्तः। अस्माकम् अन्तः अन्तर्यामितया बिम्बरूपेण स्थित्वा अस्मान् नयति, अस्माकं बहिः स्थित्वा अस्मान् धारयति। ज्ञानिभ्यः स्वान्तरङ्गे दर्शनं ददाति भगवान्, अज्ञानिभ्यः तु सः बहुदूरे। सर्वगतः भगवान् अचलः, परं तस्य अनन्तानि रूपाणि सदा चलन्ति। समस्तस्य चराचरात्मकस्य जीवस्य अन्तः भगवान् व्याप्य तिष्ठति। भगवान् अणोः अन्तः अणुरूपेण व्याप्तः। भगवान् ज्ञेयः, परं विज्ञेयः नास्ति। भगवतः विवरणं वयं किञ्चित् ज्ञातुं शक्नुमः, परं पूर्णतया अवगन्तुं न शक्नुमः। वयं समुद्रस्थस्य लघुमत्स्यस्य इव। सः यथा समुद्रस्य अगाधतां ज्ञातुं न शक्नोति, तथा जगतः कोऽपि जीवजातः भगवन्तं पूर्णतया ज्ञातुं न शक्नोति, यतः सः अस्मन्मनसा ग्रहीतुम् अशक्यः सूक्ष्मः च।",
  "13.16": "अविभक्तम् च भूतेषु विभक्तम् इव च स्थितम् ।\nभूतभर्तृ च तत् ज्ञेयम् ग्रसिष्णु प्रभविष्णु च ॥\n\nभगवान् अस्मिन् प्रपञ्चे प्रत्येकस्मिन् जीवे बिम्बरूपेण स्थितः। प्रत्येकस्मिन् जीवे सः अनेकरूपेण अस्ति। अत्र प्रत्येकः जीवः विभक्तः। परं भगवान् केवलम् अखण्डः (अविभक्तः)। सर्वत्र स्थितः भगवान् एकः, परं भिन्नः भिन्नः इव अस्मभ्यं दृश्यते इत्येव। अस्य उत्तमम् उदाहरणं भगवतः अवताराः -- परशुरामः, वेदव्यासः, श्रीकृष्णः च। अत्र भगवान् त्रिषु रूपेषु अस्मभ्यम् एककालम् एव दृष्टः। एकः अपि त्रिधा भूत्वा अस्माकं दृष्टिगोचरः अभवत्। सः समस्तस्य जीवस्य अन्तः वर्तते, परं समस्तं जीवं सः एव धारयति। सर्वेषां स्रष्टा भगवान्, स्वस्य सृष्टेः एकदा संहारं कुर्वन् अपि सः एव। संहारानन्तरं सृष्टेः पुनर्निर्माणं कुर्वन् अपि सः एव।",
  "13.17": "ज्योतिषाम् अपि तत् ज्योतिः तमसः परम् उच्यते ।\nज्ञानम् ज्ञेयम् ज्ञानगम्यम् हृदि सर्वस्य विष्ठितम् ॥\n\nअद्यपर्यन्तं कृष्णेन विवृतः विषयः अस्मदीये ध्याने द्रष्टुं दुष्करः। अतः अस्मिन् श्लोके कृष्णः स्वयम् आत्मानं भावनात्मकतया विवृणोति। भगवान् अन्धकाररहितं ज्योतिः। तस्य ज्योतिषः अवधिः नास्ति। तत् अनन्तम्। सर्वेभ्यः ज्योतिर्भ्यः ज्योतिः ददाति यः सः महाज्योतिः भगवान्। भगवन्तं ध्याने द्रष्टुम् इति नेत्रे निमील्य उपविष्टे सति अस्मभ्यं स्वेष्टवस्तु व्यक्तिः वा दृश्येत। तदा तस्मिन् व्यक्तौ/वस्तुनि वयं भगवन्तं द्रष्टुं यतितव्याः (यतः भगवान् सर्वान्तर्यामी -- सः सर्वस्य अन्तः बहिः च व्याप्य तिष्ठति)। ततः \"सूर्ये भगवान् वर्तते, सौरशक्तिः तस्य दानम्\" इति अनुसन्धानं कर्तव्यम्। ततः सौरमण्डलस्य मध्ये भगवतः पादं द्रष्टुं यत्नः कर्तव्यः। तस्य पादाङ्गुष्ठात् उद्भूतं ज्योतिः अस्मदीयं हृदयं प्रविश्य प्रकाशयत् इति ध्याने वयम् अनुभवेम। इयं क्रमेण भगवद्दर्शनस्य प्रक्रिया। भगवान् अस्य जगतः सर्वेभ्यः ज्योतिर्भ्यः ज्योतिः दत्तवान्। अस्मदीयम् अन्तरङ्गं प्रकाशयितुं सामर्थ्यं केवलं भगवते अस्ति। भगवन्नामकं ज्योतिः तमः अतिक्रान्तम्। तत् ज्ञानानन्दस्वरूपं ज्योतिः। भगवन्तं पूर्णतया ज्ञातवान् भगवान् एकः एव। वयं यथाशक्ति तं ज्ञातुं यत्नं कुर्याम। भगवान् अस्मदीये हृदये एव निवसति। सः सर्वस्मात् विलक्षणतया अस्मदीयस्य हृत्कमलस्य मध्ये सूक्ष्मात् सूक्ष्मतरः स्थितः। एतादृशं भगवन्तं वयं भक्तिपूर्वकज्ञानेन एव ज्ञातुं शक्नुमः।",
  "13.18": "इति क्षेत्रम् तथा ज्ञानम् ज्ञेयम् च उक्तम् समासतः ।\nमत् भक्तः एतत् विज्ञाय मत् भावाय उपद्यते ॥\n\nअस्मिन् श्लोके कृष्णः अद्यपर्यन्तम् उक्तस्य विषयस्य उपसंहारं कुर्वन् वदति -- \"अद्यपर्यन्तं क्षेत्रस्य विषये, ज्ञानसाधनानां विषये, एतैः ज्ञानसाधनैः ज्ञातव्यस्य भगवतः विषये संक्षेपेण (In a nutshell) उक्तं भवति। सृष्टिः, सृष्टः प्रपञ्चः, प्रपञ्चसृष्टेः प्रकारः, स्रष्टा भगवान् -- इदं ज्ञातं चेत् पुनः ज्ञातव्यं किमपि न अवशिष्यते। पूर्णविश्वासेन, भक्त्या इदं ज्ञातवान् भक्तः मां प्राप्नोति\" इति वदति कृष्णः। भगवद्विषयकं ज्ञानं भक्तिः च अस्मान् मोक्षं प्रति नेतुं समर्थे।\n\nअग्रिमे श्लोके कृष्णः मूलसृष्टेः कल्पनां तस्याः अनुसन्धानं च विवृणोति। एषः श्लोकः अध्यात्मप्रपञ्चे सृष्टेः विषये सर्वेभ्यः सन्देहेभ्यः कृष्णेन दत्तम् उत्तरम्। संक्षेपेण सर्वं कृष्णः अनेन श्लोकेन अस्मत्पुरतः स्थापितवान्।",
  "13.19": "प्रकृतिम् पुरुषम् च एव विद्धि अनादी उभौ अपि ।\nविकारान् च गुणान् च एव विद्धि प्रकृति सम्भवान् ॥\n\nभगवान् न कञ्चन जीवं न प्रकृतिं वा सृष्टवान्। जडप्रकृतिः, चेतनप्रकृतिः, परमपुरुषः (भगवान्), अवान्तरपुरुषाः (जीवाः) -- सर्वे अनादिनित्याः। प्रपञ्चः इत्युक्ते प्रकृतेः विकारः। एकं शिशु जातम् इत्युक्ते तत्र जीवस्य सृष्टिः न भवति। जीवस्य एकः आकारः सृज्यते। जीवः पितुः देहद्वारा मातुः गर्भं प्राप्य तत्र एकम् आकारं प्राप्नोति। एवं भगवान् जीवेभ्यः प्रकृतेः मुखेन एकम् आकारं सृजति। सृष्टेः मूले अपि लक्ष्मीनारायणौ मातापितरौ भूत्वा प्रपञ्चस्य सृष्टये चालनं दत्तवन्तौ। सृष्टेः आदौ जीवाः लक्ष्म्याः उदरे आसन्। लक्ष्मीः परमपुरुषस्य भगवतः उदरे आसीत्। सृष्टेः मूले लक्ष्म्याः शिरसः उद्भूय, भगवतः नाभेः मुखेन चतुर्मुखब्रह्मणः जननम् अभवत्। अस्मात् कारणात् चतुर्मुखब्रह्मा लक्ष्म्याः शिरसः भगवतः च नाभेः जातः इति उच्यते। संक्षेपेण -- \"जगतः कारणभूता जडप्रकृतिः नित्या; तया आकारं प्राप्य सृष्टः जीवः अपि नित्यः; अस्याः जडप्रकृतेः जीवस्य च कारणभूतौ पुरुषौ लक्ष्मीनारायणौ अपि नित्यौ; प्रपञ्चः इत्युक्ते प्रकृतेः विकारः\" इति। इदम् अत्र अस्माभिः ज्ञातव्यं मुख्यं विषयम्।\n\nसर्वप्रथमं सृष्टिविस्ताराय आवश्यकी शक्तिः सृष्टा। सा एव प्रकृतेः अतिसूक्ष्मः विकारः त्रिगुणाः। एतया शक्तिकम्पनेन सम्पूर्णं प्रपञ्चं निष्पन्नम्। आकारं दत्तवती माता लक्ष्मीः; आकारं प्राप्तवन्तः जीवाः; आकारं ददत् नारायणः। अस्मात् कारणात् चतुर्मुखब्रह्मणः आरभ्य समस्ताः देवाः जीवाः च लक्ष्मीनारायणयोः सन्तानाः।\n\nउपर्युक्ते श्लोके कृष्णः पुरुषं प्रकृतिं च वर्णितवान्। [पुरुषः इत्युक्ते जीवात्मा परमात्मा च। प्रकृतिः इत्युक्ते जडप्रकृतिः चेतनप्रकृतिः च।] सृष्टिप्रक्रियायाम् एतेषां चतुर्णां पात्राणां विवरणं कृष्णः अग्रिमेषु त्रिषु श्लोकेषु अस्मत्पुरतः स्थापयति।",
  "13.20": "कार्य कारण कर्तृत्वे हेतुः प्रकृतिः उच्यते ।\nपुरुषः सुखः दुःखानां भोक्पत्वे हेतुः उच्यते ॥\n\nअस्मिन् श्लोके कृष्णः द्वौ विषयौ विभज्य दर्शितवान्। अस्मभ्यम् एकं देहम् अस्ति। देहे सुखदुःखभोगाय पञ्च इन्द्रियाणि सन्ति। एवं शरीरं, शरीरे इन्द्रियाणि, इन्द्रियैः सुखदुःखभोगः -- इदं जीवनम्। जीवस्य पूर्वकृतकर्मानुगुणं कार्यकारणयोः कर्तृत्वम्। अर्थात् अस्मदीयकर्मानुगुणं भगवान् अस्मिन् जन्मनि एकं रूपं दत्तवान्। अस्मदीयस्य देहस्य रूपं ग्रहीतुं अधिष्ठानकारणं अस्मदीयौ मातापितरौ। अस्मदीयं देहं जडप्रकृत्या निर्मितम्। मातुः उदरे अस्मभ्यम् एतद् रूपं दत्तवती जगन्माता श्रीलक्ष्मीः। भगवते अङ्गभूता लक्ष्मीः देहरचनां करोति। एवं देहस्य अङ्गाङ्गानि इन्द्रियाणि च प्राप्तवान् जीवः, तेभ्यः सुखदुःखभोगम् अनुभवति। परमपुरुषः भगवान् जीवाय सुखदुःखानुभवं ददाति। एवं देहरचनायां चेतनजडप्रकृती अन्तर्भूते सत्यां, भगवान् जीवाय भोक्तृत्वस्य अनुभवं स्वयम् अन्तर्यामितया स्थित्वा ददाति।",
  "13.21": "पुरुषः प्रकृतिस्थः हि भुंक्ते प्रकृतिजान् गुणान् ।\nकारणम् गुणसंगः अस्य सत् असत् योनि जन्मसु ॥\n\nप्रकृतिनिर्मिते देहे भगवान् वर्तते, देवाः च सन्ति। परं देहे स्थित्वा सुखदुःखभोगम् अनुभवन् जीवः। देहः प्रकृतेः गुणेन निर्मितः भवति। जीवः स्वस्वभावानुगुणं, पूर्वजन्मनः कर्मफलानुगुणं च अस्मिन् जन्मनि देहं प्राप्नोति। पूर्वम् उक्तवत् जीवः स्वदेहं त्यक्त्वा बहिः निर्गच्छन् यत् गाढतया स्मरति, तदनुगुणम् अस्य अग्रिमं जन्म निर्धार्यते। उत्तमे वा हीने योनौ जन्मने जीवस्य त्रिगुणानां सङ्गः एव कारणम्।",
  "13.22": "उपद्रष्टा अनुमंता च भर्ता भोक्ता महेश्वरः ।\nपरमात्मा इति च अपि उक्तः देहे अस्मिन् पुरुषः परः ॥\n\nचित्प्रकृतिः जडप्रकृत्या देहं निर्मिमीते यदा, जीवः तत्र स्थित्वा इन्द्रियैः सुखदुःखं भुनक्ति यदा -- सर्वस्य प्रेरकः, सर्वेभ्यः उच्चैः स्थितः, सर्वं समीपात् साक्षात् पश्यन् भगवान् परमपुरुषः। सः अस्मदीयं कर्म वेत्ति। केन कर्मणा किं भवितव्यम् इति ज्ञातवान्। सः अन्तः उपविश्य प्रेरणां करोति इति एतद् देहं तिष्ठति। सः निर्गते देहः पतति। सः अस्मदन्तः स्थित्वा कस्यापि दुःखस्य स्पर्शं विना सदा आनन्देन तिष्ठन् आनन्दभोक्ता।",
  "13.23": "यः एवम् वेत्ति पुरुषम् प्रकृतिम् च गुणैः सह ।\nसर्वथा वर्तमानः अपि न सः भूयः अभिजायते ॥\n\nअनादिनित्यां प्रकृतिं (जडां चेतनां च), सर्वस्य कारणभूतं पुरुषं परमात्मानं, तदधीनं जीवजातं च गुणैः सह यः जानाति सः ज्ञानी। एतादृशः ज्ञानी बाह्यतः यथा कथाचित् दृश्येत, सत्यसाक्षात्कारेण सः मोक्षं प्राप्नोति। अत्र बाह्यसंस्कारात् ज्ञानं कियत् मुख्यम् इति कृष्णः भारपूर्वकम् उक्तवान्। मुखवाटयुक्तेन जीवनेन कोऽपि उपयोगः नास्ति। ततः अधिकं तत् सत्यसाक्षात्कारः। सत्यसाक्षात्कारे सति स्वयमेव लौकिकः प्रपञ्चः कियान् अर्थहीनः इति ज्ञायते। ज्ञानात् अधिकं पवित्रं साधनम् अन्यत् नास्ति। कर्मानुष्ठाने आकस्मात् च्युतिः अपि ज्ञानमार्गे गच्छतः बाधकं न भवति। ज्ञानं तं सन्मार्गे आनीय स्थापयति, सः मोक्षं प्राप्नोति।\n\nप्रकृतिं पुरुषं च गुणैः सह ज्ञातुम् एव मोक्षमार्गः इति कृष्णः उक्तवान्। तर्हि एतत् ज्ञातुं उपायः कः? इदं कृष्णः अग्रिमयोः द्वयोः श्लोकयोः विवृणोति। भगवन्तं प्राप्तुं अनेके उपायाः सन्ति। सर्वेभ्यः सर्वं न। यतः एकः यथा जानाति तथा अन्यः ज्ञातुं न शक्नोति। आगच्छत, अत्र कृष्णस्य विवरणं शृणुमः।",
  "13.24": "ध्यानेन आत्मनि पश्यंति केचित् आत्मानम् आत्मना ।\nअन्ये सांख्येन योगेन कर्मयोगेन च अपरे ॥\n\nसाधनार्थं प्रथमम् अस्मभ्यं साधनाशरीरम् आवश्यकम्। हीनयोनौ पूर्णतां अप्राप्ते शरीरे जातः चेत् साधना न सम्भवति। प्रथमं वयं मानवाः भवेम (पूर्णतां प्राप्तस्य शरीरस्य निवासिनः पुरुषाः भवेम)। अत एव दासाः गीतवन्तः -- \"मानवजन्म महत्, तत् मा नाशयत उन्मत्ताः!\" इति। साधनाय आवश्यकं साधनाशरीरं न स्यात् चेत् कापि साधना न सम्भवति।\n\nकेचित् स्वस्वरूपयोग्यतया भगवदनुग्रहेण च जन्मतः एव ज्ञानं प्राप्य जायन्ते। एतेषां ज्ञानं निश्चलम्। एतादृशाः स्वजीवयोग्यतया स्वजीवस्वरूपे बिम्बरूपिणं भगवन्तं पश्यन्ति। एतादृशाः कमपि अध्ययनं विना सदा भगवन्तम् अन्तरङ्गे पश्यन्तः भगवन्तं प्राप्नुवन्ति। ब्रह्मादयः सकलाः देवताः, देवांशसम्भूताः च एवं नेत्रे निमील्य भगवन्तं द्रष्टुं, दृष्ट्वा तं प्राप्तुं शक्नुवन्ति।\n\nकेचित् शुद्धात्मतत्त्वविज्ञानेन प्रथमं भगवन्तं जानन्ति। जीवं परमात्मानं च ज्ञातुं सांख्ययोगः इति उच्यते। एवं ज्ञानं गृहीत्वा, ज्ञानस्फुरणं प्राप्य, ध्यानेन एते भगवन्तं दृष्ट्वा भगवन्तं प्राप्नुवन्ति।\n\nअन्ये केचित् स्वनिरन्तरकर्मानुष्ठानेन देहशुद्धिं साध्य, तेन भगवतः प्रीतेः पात्रा भूत्वा, ज्ञानं गृहीत्वा, ध्याने भगवन्तं दृष्ट्वा भगवन्तं प्राप्नुवन्ति।",
  "13.25": "अन्ये तु एवं अजानंतः श्रुत्वा अन्येभ्यः उपासते ।\nते अपि च अतितरंति एव मृत्युम् श्रुतिपरायणाः ॥\n\nजनसामान्याः, उपर्युक्तेषु येन केनापि विधिना साधनां कर्तुम् अशक्ताः -- अन्यस्मात् श्रुत्वा ज्ञात्वा साधनायाः प्रथमं सोपानम् आरोढुं शक्नुवन्ति। इदं साधनामार्गे सर्वाधः स्थितं सोपानम् अपि स्यात् तथापि एते निरन्तरश्रवणमननिदिध्यासनैः, अहङ्कारं विना, ज्ञानं सम्पाद्य, तेन ज्ञानेन ध्याने भगवन्तं द्रष्टुं शक्नुवन्ति। इदं सामान्यमानवाय कृष्णेन दर्शितः मोक्षमार्गः। एवं एते श्रवणेन उपासनया च मृत्युं जित्वा भगवन्तं प्राप्तुं शक्नुवन्ति।",
  "13.26": "यावत् संजायते किंचित् सत्वम् स्थावर जंगमम् ।\nक्षेत्र क्षेत्रज्ञ संयोगात् तत् विद्धि भरतर्षभ ॥\n\nहे भरतर्षभ, स्थिरचरेषु जीवेषु यत् किमपि जायते, तत् क्षेत्रस्य (श्रीतत्त्वस्य) क्षेत्रज्ञस्य भगवतः च सहयोगेन एव इति जानीहि।\n\nअस्मिन् जगति यत् किमपि जायते, चलत्-अचलं समस्तं जीवं जडात्मकं प्रपञ्चं तस्य च अभिमानिनी प्रकृतिदेवी -- एतत् सर्वं सहितं क्षेत्रम् इति उच्यते। एतत् सर्वं जानाति यः सः क्षेत्रज्ञः भगवान्। अतः क्षेत्रम् इत्युक्ते भगवता निर्मितं समस्तं जीवजडात्मकं प्रपञ्चम्। समस्ता सृष्टिः लक्ष्मीनारायणयोः समागमेन निर्मिता। तौ एव अस्य प्रपञ्चस्य प्रथमौ दम्पती। अतः सर्वेषां मातापितरौ नारायणः श्रीलक्ष्मीः च। \"इदं ज्ञातवान् त्वं सत्यः भरतर्षभः भवसि\" इति वदति कृष्णः। भगवति रतः यः, भगवति पूर्णभक्तिः यस्य, सः भरतर्षभः।",
  "13.27": "समम् सर्वेषु भूतेषु तिष्ठंतम् परमेश्वरम् ।\nविनश्यत्सु अविनश्यंतम् यः पश्यति सः पश्यति ॥\n\nसर्वेषु जीवेषु एकरूपेण स्थितः सर्वशक्तः भगवान् परम-ईश-वरः। यस्य आज्ञां वयं पालयितुं न शक्नुमः, यत् पालनं अस्माकं कर्तव्यम्, अस्मदज्ञातेन अस्मदन्तः स्थित्वा यत् पालयति सा अज्ञातशक्तिः -- \"ईश-वरः\"। अर्थात् तत्त्वाभिमानिनः देवाः। एतादृशान् तत्त्वाभिमानिनः देवान् अपि नियन्त्रयन् भगवान् परमेश्वरः। एतादृशः भगवान् कुत्रापि उपविश्य अस्मान् न नियमयति। सः अस्मदन्तः स्थित्वा अस्मान् नियन्त्रयति। सः अस्मदन्तः स्वतन्त्रः सन् अस्मान् धृत्वा नयति। [पूर्वकालिकाः जनेभ्यः एतत् सन्देशं देवालये तट्टिरायस्य (द्वारपालमूर्तेः) मुखेन दत्तवन्तः।] भगवान् मुक्तामुक्तयोः नियामकः। सर्वान् सर्वस्मिन् काले तेषां तेषां योग्यतानुगुणं, तस्य तस्य वस्तुनः स्वभावानुगुणं च अन्तः स्थित्वा प्रेरयन् भगवान्। भगवतः शक्तौ उच्चनीचभावः नास्ति। गजे भगवान्, पिपीलिकायां भगवान् -- भिन्नौ न स्तः। परं तस्य सन्निधाने भेदः अस्ति अतः तस्य सन्निधानस्य अधिष्ठाने भेदः जायते। अस्मदीये देहे स्थितः बिम्बरूपी भगवान् अविनाशी। तस्य देहनाशः, स्वरूपनाशः नास्ति। दुःखप्राप्तिः नास्ति। सः अपूर्णः न भवति। एतत् सत्यं ज्ञातवान् यथार्थज्ञानवान्। अस्मिन् श्लोके उक्तं विषयं पुनः विशदीकृत्य कृष्णः अग्रिमे श्लोके विवृणोति --",
  "13.28": "समम् पश्यन् हि सर्वत्र समवस्थितम् ईश्वरम् ।\nन हिनस्ति आत्मना आत्मनम् ततः याति पराम् गतिम् ॥\n\nसर्वशक्तः भगवान् सर्वत्र न्यूनाधिक्यं विना एकरूपेण अस्ति इति ज्ञातवान् स्वोन्नतये स्वयमेव विघ्नं न करोति। सः अग्रे परमपदं प्राप्नोति।\n\nवयम् अस्मदीये देहे स्थिताः। परं भगवान् \"संस्थितः\"। अस्मिन् देहे स्थिताः वयम् अस्य देहस्य ज्ञानम् अपि न धरामः। किमर्थं स्थिताः इति अपि न जानीमः। वयम् अन्तः स्थित्वा आनन्ददुःखे अनुभवामः। परं भगवान् दुःखाज्ञानयोः स्पर्शरहितः आनन्दमूर्तिः। सः अस्मदन्तःस्थेभ्यः सर्वेभ्यः तत्त्वाभिमानिदेवेभ्यः समवस्थितः, उच्चैः च वर्तते। दुःखाज्ञानयोः स्पर्शरहितः भगवान् कमपि उच्चनीचभावेन न पश्यति। प्रत्येकं जनं तस्य तस्य कर्मणे जीवयोग्यतायै च अनुगुणं समानतया पश्यति। भगवान् समस्तस्य जडचेतनस्य अन्तः जगदीश्वरतया स्थित्वा, अस्मदीयजीवस्वभावानुगुणं, कर्मानुगुणं च अस्मान् नयति। इदं सत्यं ज्ञाते सति \"त्वं स्वयं स्वस्मै हिंसां न कुर्याः, जीवितुं शक्नोषि\" इति वदति कृष्णः। स्वस्य अज्ञानेन, भगवतः अज्ञानेन जीवनं जीवनम् एका आत्महिंसा एव। एकवारं \"अहम्\" इत्युक्ते किम्, ममान्तः स्थितः भगवान् इत्युक्ते किम् इति वस्तुस्थितिं ज्ञातवति हिंसा न भवति। तत् अज्ञात्वा जीवनं अज्ञानस्य दुःखस्य च जीवनम्। जीवने आगच्छन्तीं प्रत्येकां घटनां \"मया पूर्वं कृतस्य कर्मणः फलम्, तत् भगवता कारितम्\" इति ज्ञातवति दुःखं विना आनन्देन जीवितुं शक्यते। अस्मदीयं मनः एव अस्मभ्यं दुःखं ददाति। तदेव आनन्दं ददाति। अस्मभ्यं दुःखं भवति अस्मदीयात् बोधात् एव, नान्यस्मात् कुतश्चित्। उदाहरणार्थं कश्चन श्रीमन्तः केनापि कारणेन स्वकीयां सर्वां सम्पत्तिं हारयति। तदा सः \"मम पूर्वजन्मनः कर्मानुगुणम् एषा घटना अभवत्। सर्वं भगवतः लीला; दाता सः एव, ग्रहीता सः एव; पालकः सः एव; अतः अहं किमर्थं चिन्तयेयम्\" इति ज्ञात्वा आनन्देन स्थातुं शक्नोति। एतद् विहाय ब्रह्माण्डम् एव शिरसि पतितम् इव आचरति चेत् तत् वयं स्वयमेव आत्मानं हिंसामहे इति भवति। वयं सर्वं प्रेक्षकभावेन द्रष्टुम् अभ्यसेम। भगवतः अवबोधेन शान्तं तादृशं जीवनम् अस्मान् परमपदं मोक्षं प्रति नेतुं समर्थम्।\n\nभगवतः चिन्तनस्य अन्यत् अनुसन्धानं कृष्णः अग्रिमे श्लोके अस्मत्पुरतः स्थापयति। सावधानतया एतं श्लोकं वयं पश्येम चेत् अस्मभ्यं सत्यं ज्ञायते। अस्मासु सर्वेषु विद्यमानः एकः सन्देहः -- \"क्रियां किम् अहं करोमि, उत मत्तः भगवान् कारयति? भगवता कारिते सति किमर्थं मत्तः दुष्टं कर्म कार्यते?\" इति। एतस्मै प्रश्नाय कृष्णः अस्मिन् श्लोके संक्षेपेण उत्तरं दत्तवान्। अत्र पूर्वं कृष्णेन उक्तं विषयम् अवधानेन धृत्वा वयम् इमं श्लोकं पश्येम।",
  "13.29": "प्रकृत्या एव च कर्माणि क्रियमाणानि सर्वशः ।\nयः पश्यति तथा आत्मानम् अकर्तारम् सः पश्यति ॥\n\nकृष्णः वदति -- \"यस्मै 'अहं न करोमि' इति ज्ञातम् सः ज्ञानवान्\" इति। अतः प्रथमं वयं \"अहं करोमि\" इति अहङ्कारं त्यजेम। \"अहं करोमि\" इति एतद् केवलं व्यावहारिकं सत्यं, न पारमार्थिकं सत्यम्। उदाहरणार्थम् -- \"अहं वदामि\"। अत्र मया वक्तुं प्रथमं मया मूकेन न भवितव्यम्। तदर्थं युक्तानि अङ्गानि युक्तं मानवशरीरं च आवश्यकम्। वक्तुं मम मनः विषयान् समयानुगुणं चिन्तयित्वा सन्देशं प्रेषयेत्। अर्थात् एतदर्थं युक्ता मस्तिष्कशक्तिः मह्यम् आवश्यकी। वक्तुं धैर्यं मह्यम् आवश्यकम्। इदानीं वयं स्वयमेव स्वं पृच्छाम -- मह्यं वक्तुं समर्थं मानवशरीरं कः दत्तवान्? मह्यं चिन्तयितुं समर्थं मस्तिष्कं विन्यस्य कः अनुगृहीतवान्? समयानुगुणम् एतस्मात् मस्तिष्कात् सन्देशं कः प्रेषितवान्? वक्तुम् अद्भुतां कलां मह्यं कः दत्तवान्? एतैः सर्वैः प्रश्नैः अस्माकम् ज्ञायते -- \"मदन्तः स्थितः भगवान् वादयितवान्, अहं उक्तवान्\" इति सत्यम्। इदमेव अत्र भगवान् विवृण्वन् वदति \"प्रकृत्यैव च कर्माणि क्रियमाणानि सर्वशः\" इति। तेषां तेषां जीवप्रकृत्यनुगुणं, प्रकृतेः (त्रिगुणानां) प्रभावेण, प्रकृतिपुरुषौ (लक्ष्मीनारायणौ) अस्मत्तः कर्म कारयतः। अतः जीवाय अनादिनित्यतया प्राप्तस्य जीवस्वभावस्य अनुगुणं तस्य देहसृष्टिः; तदनुगुणं तस्योपरि वातावरणस्थानां त्रिगुणानां प्रभावः; त्रिगुणानां प्रभावानुगुणं तस्य सर्वविधं कर्म। एतत् सर्वं कारयन् सर्वदेवतानाम् अधिपतिः, लक्ष्मीसमेतः नारायणः।",
  "13.30": "यदा भूत पृथक् भावम् एकस्थम् अनुपश्यति ।\nततः एव च विस्तारं ब्रह्म सम्पद्यते तदा ॥\n\nजीवः अनादिनित्यः। सृष्टिः, संहारः च केवलं दृश्यं रूपम् एव। जीवजातानि प्रत्येकं पृथक्भावानि। कापि द्वे जीवजाती शतांशेन शतांशं सदृशे न स्तः। एषा अनेकजीवसमष्टिः एकस्मिन् भगवति स्थिता। सृष्टिकाले भगवतः उदरात् बहिः निर्गत्य आकारं प्राप्नुवन्ति जीवजातानि, प्रलयकाले पुनः सूक्ष्मरूपेण भगवतः उदरं प्रविशन्ति। इदं वयं वस्तुस्थित्यनुगुणं ग्रहीतव्यम्। यः इदं सत्यं ग्रहीतुं शक्नोति सः मोक्षं प्राप्तुं शक्नोति।",
  "13.31": "अनादित्वात् निर्गुणत्वात् परम आत्मा अयम् अव्ययः ।\nशरीरस्थः अपि कौंतेय न करोति न लिप्यते ॥\n\nनिर्विकारः एकः वस्तुः भगवान्। सः कदापि केनापि कारणविशेषेण न जातः। भगवान् त्रैगुण्यवर्जितः। अस्मात् सः कदापि परिवर्तनं विकारं वा न प्राप्नोति। सः सर्वजीवेषु बिम्बरूपेण स्थितः अपि तस्य देहबद्धता नास्ति। सः अस्मत्तः सर्वं कारयति परं किमपि न आसज्यते। सः निर्लिप्तः सन् सर्वं करोति परं तस्य कस्यापि लेपः नास्ति। इदं कीदृशम् इति अवगन्तुं कृष्णः एकम् उदाहरणं दत्त्वा अग्रिमे श्लोके विवृणोति।",
  "13.32": "यथा सर्वगतं सौक्ष्म्यात् आकाशं न उपलिप्यते ।\nसर्वत्र अवस्थितः देहे तथा आत्मा न उपलिष्यते ॥\n\nसर्वत्र आकाशम् अस्ति। तद्रहितं स्थानं नास्ति। एतादृशम् आकाशं सर्वत्र सत् अपि यथा किमपि न आसज्यते, तथा एव भगवान् सर्वेषु देहेषु स्थितः अपि किमपि न आसज्य निर्लिप्तः तिष्ठति।",
  "13.33": "यथा प्रकाशयति एकः कृत्स्नम् लोकम् इमम् रविः ।\nक्षेत्रम् क्षेत्री तथा कृत्स्नम् प्रकाशयति भारत ॥\n\nयथा एकः सूर्यः कृत्स्नं जगत् प्रकाशयति तथा क्षेत्रज्ञः भगवान् कृत्स्नं क्षेत्रं प्रकाशयति। प्रथमं वयं भगवतः प्रकाशं (ज्ञानम्) ज्ञातव्याः। तदा अस्मदन्तःस्थः प्रकाशः अस्माभिः अवगम्यते।",
  "13.34": "क्षेत्र क्षेत्रज्ञयोः एवम् अंतरम् ज्ञानो चक्षुषा ।\nभूत प्रकृति मोक्षम् च ये विदुः यांति ते परम् ॥\n\nक्षेत्रस्य क्षेत्रज्ञस्य च इदम् अन्तरं, पञ्चभूतेभ्यः प्रकृतेः च (जीवानां चेतनप्रकृतितः) मोक्षाय कारणभूतां ज्ञानदृष्टिं ये अवलम्ब्य गच्छन्ति, ते परमात्मानं प्राप्नुवन्ति।\n\nएषः श्लोकः अस्य अध्यायस्य उपसंहारः। क्षेत्रम् इत्युक्ते किम्, क्षेत्रज्ञः इत्युक्ते किम्, क्षेत्रक्षेत्रज्ञयोः अन्तरं किम्, जीवजातस्य जडात् मोचनाय आवश्यकाः मोक्षसाधकाः गुणाः च -- एतत् सर्वं ज्ञात्वा आचरणे आनीय जीवन्तः सर्वश्रेष्ठं भगवन्तं प्राप्नुवन्ति।\n\nइति त्रयोदशोऽध्यायः।",
  "13.35": "[बन्नञ्जेभाष्ये त्रयोदशोऽध्यायः चतुस्त्रिंशत्श्लोकैः समाप्यते। १३.३५ इति श्लोकः तेषां पाठे नास्ति; एतत् पूर्वश्लोके एव अन्तर्भूतम्।]",
  "14.1": "भगवान् उवाच\n\nपरम् भूयः प्रवक्ष्यामि ज्ञानानाम् ज्ञानम् उत्तमम् ।\nयत् ज्ञात्वा मुनयः सर्वे पराम् सिद्धिम् इतः गताः ॥\n\nकृष्णः वदति -- \"इन्नू हेळुत्तेने (अद्यापि वदामि)\" इति। इदं भारपूर्वकं वचनम्। सामान्यतः शिष्येण आग्रहं कृतेऽपि गुरवः न वदन्ति। गुरवे शिष्यस्य ज्ञानतृष्णां दृष्ट्वा वक्तुम् इच्छा जायेत, प्रसन्नतया च वदेत् -- तदा एव तत् विद्या शिष्याय फलति। एवं ज्ञानतृष्णां दृष्ट्वा प्रसन्नतया गुरुणा उक्तं ज्ञानं सत्यं ज्ञानम्। अत्र कृष्णः स्वयमेव अर्जुनाय अपूर्वं ज्ञानं वदति। कृष्णः वदति -- \"पूर्वोक्तं क्षेत्रं (प्रकृतिः लक्ष्मीः) क्षेत्रज्ञं (नारायणः) च विषयम् अद्यापि विवरणेन वक्ष्यामि। यतः तत् ज्ञातव्यविषयेषु अतिमुख्यः विषयः\" इति। अस्य जगतः सृष्टेः पृष्ठे मातापितरौ भूत्वा लक्ष्मीनारायणौ स्तः। अतः केवलं पितुः स्मरणं, अथवा केवलं मातुः स्मरणं कर्तुं बदले, मातापित्रोः स्मरणं ज्ञात्वा कर्तुं श्रेयः। कृष्णः वदति -- \"इमं विषयम् अद्यापि विस्तारेण तुभ्यं वक्ष्यामि, यतः इदं मोक्षसाधकेन ज्ञातव्यमेव विषयम्\" इति।\n\nसृष्टेः मूले लक्ष्मीनारायणौ अचिन्तयित्वा मोक्षसाधना असाध्या। \"अस्यां साधनाभूमौ जन्म प्राप्य ब्रह्मसाक्षात्कारं प्राप्ताः मुनयोऽपि, इदं ज्ञात्वैव जीवनस्य परमां सिद्धिं मोक्षं प्राप्तवन्तः\" इति वदति कृष्णः। इदमेव अग्रिमे श्लोके अतिस्पष्टतया विवृतम्।",
  "14.2": "इदम् ज्ञानम् अपाश्रित्य मम साधर्म्यम् आगताः ।\nसर्गे अपि न उपजायंते प्रळये न व्यथंति च ॥\n\nअस्मिन् श्लोके \"अपाश्रित्य\" इति पदं विशेषम् अर्थं ददाति। \"अन्यत् सर्वम् अपहाय आश्रयणम् -- अपाश्रयणः\" इति, \"अन्यः कोऽपि नास्ति, त्वमेव मह्यम् आश्रयः\" इति भगवति आश्रयं प्राप्तिं \"अपाश्रित्य\" इति उक्तम्। द्वादशस्तोत्रे उक्तं यथा --\n\n\"कुरु भुङ्क्ष्व च कर्म निजं नियतं हरिपादविनम्रधिया सततम् ।\nहरिरेव परो हरिरेव गुरुः हरिरेव जगत्पितृमातृगतिः ॥\"\n\nइदं \"अपाश्रित्य\" पदस्य मूलम् अर्थं वदति। अत्र कृष्णः वदति -- \"लक्ष्मीनारायणौ जगतः मातापितरौ\" इति ज्ञानेन मां उपासमानाः मत्सदृशं दिव्यस्वभावं प्राप्नुवन्ति\" इति। एतादृशाः सर्वदोषान् त्यक्त्वा, त्रिगुणातीतस्थितौ भगवन्तं प्राप्य भगवति निवसन्ति। एतत् जगत् लक्ष्मीनारायणाभ्यां सृज्यते, तयोरेव च प्रविशति। एतत् ज्ञातवान् जन्ममृत्युं तरति। सः पुनः कदापि अस्मिन् संसारबन्धने न शिष्यते। अत्र \"उपजायते\" इति पदं प्रयुक्तम्। संस्कृते \"उप\" इत्युक्ते \"उत्कृष्ट\"। अतः \"उपजायते\" इत्युक्ते उत्कृष्टं जननम्। भगवतः अवबोधाय एतत् देहधारणं कृत्वा जन्म एव उन्नतं जन्म। अध्यात्मसाधनया उन्नतिं प्रति गच्छत् जन्म \"उपजनन\"। स्वजीवमानकाले अस्याः सृष्टेः मूलज्ञानं गृहीतवान् पुनः न जन्म गृह्णाति। सः भगवति निरन्तरनिवासरूपं परमपदं प्राप्नोति।",
  "14.3": "मम योनिः महत् ब्रह्म तस्मिन् गर्भम् दधामि अहम् ।\nसंभवः सर्वभूतानाम् ततः भवति भारत ॥\n\nअत्र कृष्णः अतिविचित्रं विषयं वदति। एतत् श्लोकं अवगन्तुं वयं प्रथमं \"भा-रताः\" भवेम। \"रत\" इत्युक्ते तत्त्वरतिः। वयं भगवति रताः भवेम, ज्ञानमार्गे रताः भवेम, भक्त्या पूर्णाः पूर्णकुम्भवत् भवेम, विनीताः भवेम। तदा एव सृष्टेः इदं रहस्यम् अवगम्यते।\n\nयस्य कस्यापि वस्तुनः सृष्टये एकतः अधिकानि कारणानि अपेक्षितानि। जडाय द्वे कारणे अपेक्षिते, यथा घटस्य सृष्टये मूलद्रव्यम् (Raw material) कुम्भकारः च अपेक्षितौ। वनस्पतीनां सृष्टिः जडे भगवता जीवं प्रवेश्य भवति। परं गर्भेण जायमानायाः चेतनसृष्टेः कृते जडद्रव्येण सह सृष्टिं कर्तुं एकः पुमान् एका स्त्री च अपेक्षितौ। द्वयोः समागमेन तृतीयं सृज्यते।\n\nअस्मिन् श्लोके \"मम योनिः महत् ब्रह्म\" इति उक्तौ \"योनि\" \"ब्रह्म\" च इति पदे बहून् अर्थान् ददतः। योनिः -- कारणम्, उत्पत्तिस्थानम्, भार्या इत्यादि अर्थान् ददाति। तथैव ब्रह्म -- जीवः, चतुर्मुखः, लक्ष्मीः, भगवान् इत्यादि बहून् अर्थान् ददाति। अस्मिन् श्लोके योनिः इत्युक्ते भार्या; \"महत् ब्रह्म\" इत्युक्ते चतुर्मुखस्यापि माता श्रीलक्ष्मीः। कृष्णः वदति -- \"अहं स्वपत्न्यां चित्प्रकृतौ (लक्ष्म्याम्) गर्भदानं करोमि। सः गर्भः वर्धित्वा समस्तानि जीवजातानि सृज्यन्ते\" इति। इदम् अस्मभ्यं नूतनं विषयम्। यतः ऋग्वेदे चतुर्मुखस्य सृष्टेः विषये एवं उक्तम् --\n\n\"तम् इत् गर्भं प्रथमं दध्र आपः यत्र देवाः समगच्छन्त विश्वे।\nअजस्य नाभौ अध्येकम् अर्पितं यस्मिन् विश्वानि भुवनानि तस्थुः ॥ (१०.८२.६)\"\n\nअत्र \"भगवतः नाभिकमलात् ब्रह्मा बहिः आगतः\" इति उक्तम्। चतुर्मुखेन जीवसृष्टिः निर्मिता। अतः चतुर्मुखः जगतः पिता इति विचारः अपि अस्माकं ज्ञातः। वेदे अन्यत्र (अम्भृणीसूक्ते) एवम् उक्तम् --\n\n\"अहं सुवे पितरम् अस्य मूर्धन् मम योनिः अप्सु अन्तः समुद्रे ।\nततः वि तिष्ठे भुवनानु विश्वा उत अमूं द्यां वर्ष्मणा उप स्पृशामि ॥ (७)\"\n\nइयं लक्ष्म्याः वाणी -- \"अहम् एतस्य जगतः पितरं चतुर्मुखं मम मूर्धनः (शिरसः) जनयामि। मामपि कारणभूतः भगवान् समुद्रे वर्तते\" इति। समस्तस्य ब्रह्माण्डस्य सृष्टिः शिवेन अभवत् इति अन्यत्र वदन्ति। शास्त्रप्रक्रिया अज्ञाता चेत् एतत् सर्वं केवलं भ्रान्तिः। मोक्षसाधकैः एतत् सूक्ष्मतया विश्लेषणीयम् -- तदा सत्यसाक्षात्कारः भवति।\n\nजीवः प्रकृतिः भगवान् च अनादयः अनन्ताः। सृष्टेः पूर्वं समस्तः प्रपञ्चः सूक्ष्मरूपेण भगवतः उदरे आसीत्। इदं सूक्ष्मतया दृष्टं चेत् -- समस्तं विश्वं लक्ष्मीदेव्याः उदरे आसीत्, लक्ष्मीः भगवतः उदरे आसीत्। भगवान् लक्ष्म्याः उदरे समस्तानां जीवजातानां बीजक्षेपं कृतवान्। कमलरूपं सम्पूर्णं ब्रह्माण्डं लक्ष्म्याः मूर्धानात् भगवतः नाभेः बहिः उच्चचाल। तत्र चतुर्मुखः आसीत् सह अव्यक्तरूपेण समस्तदेवताः जीवजाताश्च जाताः। अस्मात् कारणात् लक्ष्मीनारायणौ समस्तस्य जगतः मातापितरौ। अत्र अस्माभिः अवगन्तव्यः एकः मुख्यः विषयः -- सृष्टिक्रिया हन्त हन्तवत् (क्रमेण) प्रवृत्ता क्रिया। लक्ष्मीनारायणयोः समागमेन निर्मितं केवलम् अव्यक्तं सृष्टिः। ततः चतुर्मुखः ब्रह्मा एतस्मै सूक्ष्मरूपिणे अव्यक्तप्रपञ्चाय (जीवजाताय) मूलं स्थूलरूपं दत्त्वा जगतः पितामहः अभवत्। तदनन्तरं शिवेन एषः प्रपञ्चः पूर्णं स्थूलरूपं प्राप्तवान्। एतां प्रक्रियां वयं अवगच्छाम चेत् अत्र कोऽपि सन्देहः नास्ति। चतुर्मुखः लक्ष्म्याः मूर्धनः जातः इति सत्यम्; सः भगवतः नाभेः जातः इति अपि सत्यम्; सः जगतः पिता इति सत्यम्; शिवेन एषः स्थूलप्रपञ्चः निर्मितः इति अपि सत्यम्; लक्ष्मीनारायणौ समस्तस्य जीवजातस्य मातापितरौ इति अपि सत्यम्। एतद्विषये विवरणं \"महाभारततात्पर्यनिर्णये\" स्पष्टतया विवृतम्।\n\nएकस्य चेतनस्य [भूतिः (उन्नतिः) युक्तस्य जीवस्य] सृष्टये एकस्य पुंसः एकस्याः स्त्रियाः च समागमः अपेक्षितः। इदं सृष्टेः आरम्भात् एव प्रवृत्तं सम्प्रदायम्। जगतः सर्वस्याः सृष्टेः पृष्ठे लक्ष्मीनारायणौ मातापितरौ स्तः। इमं विषयम् अद्यापि स्पष्टतया कृष्णः अग्रिमे श्लोके विवृणोति।",
  "14.4": "सर्वयोनिषु कौंतेय मूर्तयः संभवंति याः ।\nतासाम् ब्रह्म महत् योनिः अहम् बीजप्रदः पिता ॥\n\nहे कौन्तेय, येषु येषु गर्भेषु याः याः मूर्तयः रूपं गृह्णन्ति, तासां सर्वासां चेतनप्रकृतिः एव माता; अहमेव बीजं वपन् पिता।\n\nकेवलं देवाः मानवाः वा न, समस्तस्य जीवजातस्य जन्मनः पृष्ठे मातापितरौ भूत्वा लक्ष्मीनारायणौ स्तः। सर्वेषां माता चेतनप्रकृतिः लक्ष्मीः। बीजं वपन् पिता नारायणः। मुण्डकोपनिषदि उक्तं यथा --\n\n\"पुमान् रेतः सिञ्चति योषितायां बह्वीः प्रजाः पुरुषात् सम्प्रसूताः ॥ (२.२.५)\"\n\nअत्र \"पुमान्\" इत्युक्ते पुंसि विशेषेण सन्निहितः भगवान्, \"योषिता\" इत्युक्ते स्त्रियां विशेषेण सन्निहिता लक्ष्मीः। यथा क्षेत्रे बीजं वप्ते सति तत् तत्र यथार्थं रूपं गृह्णाति, तथैव भगवान् जडप्रकृतेः अभिमानिन्यां श्रीलक्ष्म्यां बीजप्रदः भवति। माता लक्ष्मीः तस्मै बीजाय एकम् आकारं ददाति। इदम् अनुसन्धानं कीदृशं भव्यम्! अस्मात् कारणात् पूर्वकालिकाः शास्त्रकाराः गर्भिण्याः स्त्रियाः देहं देवालयम् इति, तस्याः गर्भस्य स्थानं गर्भगुडिम् इति, तस्य गर्भस्य अन्तः सन्निहितः जीवं वर्धयन् सः भगवान् इति च गौरवं कृतवन्तः। इदम् अस्मदीयानां प्राचीनानां प्रत्येकस्यां क्रियायां भगवन्तम् अनुसन्धानं कुर्वतां भव्यता। स्त्री देवालयम् भवति सा गर्भिणी यदा। अतः स्त्रियाः सर्वश्रेष्ठा अभिलाषा स्वयं मातृत्वं प्राप्तुम्। तस्याः अभिलाषायाः अन्तिमः लक्ष्यः मातृत्वम्। लक्ष्मीः तस्यां पूर्णप्रमाणेन सन्निहिता भवति सा गर्भवती यदा। अस्मात् कारणात् दाम्पत्यम् इत्युक्ते लक्ष्मीनारायणयोः आराधना। दाम्पत्ये पुंस्त्रियोः समागमः इत्युक्ते लक्ष्मीनारायणयोः समागमः। अत्र अस्माकं भाग्यम् इत्युक्ते अस्मान् माध्यमं कृत्वा भगवान् सृष्टिं करोति। एवं सृज्यमाने अत्र अपेक्षितस्य मूलद्रव्यस्य विस्तारेण विवरणं कृष्णः अग्रिमेषु श्लोकेषु दत्तवान्।",
  "14.5": "सत्त्वम् रजः तमः इति गुणाः प्रकृति संभवाः ।\nनिबध्नति महाबाहो देहे देहिनम् अव्ययम् ॥\n\nहे महाबाहो, सत्त्वं रजः तमः इति एतानि जडप्रकृतितः उद्भूतानि गुणानि। अनश्वरं जीवं देहे एतानि बध्नन्ति।\n\nअस्य प्रपञ्चस्य, सर्वजीवजातस्य मातुः प्रकृतेः गुणत्रयाभिमानिनी। अतः प्रत्येकः जीवः जायमानोऽपि सत्त्वरजस्तमः इति त्रिभिः गुणैः सह जायते, एतेषां गुणानां प्रभावे वर्धते च। त्रयः गुणाः विना, शुद्धेन एकगुणेन कोऽपि जीवः न सृज्यते। जडेऽपि एतान् त्रीन् गुणान् पश्यामः। सदा ऊर्ध्वमुखं प्रकाशं ददत् अग्निः सत्त्वम्; अस्पष्टतायाः स्थानं जलं रजः; सदा अधोमुखं आकर्षत् मृत्तिका तमः। जगतः सर्वाणि वस्तूनि एतेषां त्रयाणां संयोगः (combination)। उदाहरणार्थं धान्यम्। तत् भूमौ [मृत्तिका-तमः] उप्तम्। तत्र जलं (जल-रजः) सिक्तम्, सूर्यप्रकाशं (सूर्य-सत्त्वम्) शोषयित्वा अङ्कुरितं वर्धितं च फलं दत्तम्। तत् फलं कृत्य्वा तण्डुलः कृतः। तण्डुले (तमः) जलं (रजः) योजयित्वा पाचनेन (तापः-सत्त्वम्) अन्नं कृतम्। तण्डुलः वा अन्नं वा, सर्वं मृत्तिका-जल-अग्नेः त्रयाणां संयोजनम्। एवं सत्त्वरजस्तमोगुणत्रयैः इयं समग्रा सृष्टिः निर्मिता। जायमानं प्रत्येकं जीवजातम् एते त्रयः गुणाः बध्नन्ति। प्रत्येकस्मिन् एतेषां त्रयाणां गुणानां प्रमाणं भिन्नं भवति। अत्यन्तसात्त्विके मोक्षयोग्ये जीवेऽपि एते त्रयः गुणाः सन्ति। शतांशेन शतांशं शुद्धं सत्त्वगुणं कस्यापि व्यक्तौ न भवति। जडे दृष्टे अग्निः सत्त्वम्, परं तेन सह धूमः रजः, काष्ठं तमः। सत्त्वगुणस्य साक्षात्कारः रजस्तमोभ्यां मध्येन एव। एवं गुणत्रयस्य बन्धनेन स्वरूपतः जन्ममृत्युरहितः जीवः स्थूलं देहं प्राप्य जायते, तं देहं त्यक्त्वा म्रियते। जन्ममृत्युरहितं मोक्षं प्राप्तुं वयं अस्माभिः सह स्थितान् एतान् त्रीन् अन्तःशत्रून् जेतव्याः।\n\nअत्र व्यासैः \"महाबाहो\" इति विशेषणं प्रयुक्तम्। \"त्वां बद्ध्वा स्वेच्छया नर्तयतः एतान् त्रिगुणान् जयितुं महाबाहुः भव; कुत्सितत्वं निराकृत्य अध्यात्मस्य शूरः भव\" इति ध्वनिः अस्य विशेषणस्य पृष्ठे अस्ति।\n\nसमस्तं विश्वम्, अस्माकम् इदं जीवनम्, सर्वं गुणत्रयस्य विकारः। अस्मदीयं मनः, अस्मदीयं चिन्तनम्, अस्मदीयः निर्णयः, अस्मदीयम् अध्ययनम्, अस्मदीयः विश्वासः -- सर्वं एतेषां गुणानां प्रभावेण। अस्मान् सन्मार्गे नयत् अपि त्रिगुणाः, अस्मान् मार्गभ्रष्टान् कुर्वत् अपि एतत् त्रिगुणाः। त्रिषु मार्गेषु कतरेण मार्गेण गन्तव्यं श्रेयस्करम् इति निर्णयं कृत्वा चयनं कर्तुं जागृतिः अस्मासु स्यात् चेत्, वयं कतरेण मार्गेण गच्छामः इति अवबोधः अस्मभ्यम् आवश्यकः। अस्मात् कारणात् त्रिगुणानाम् अवबोधः अस्मभ्यम् अतिमुख्यः।\n\nएकं व्यक्तिं नियन्त्रयन्ति चत्वारि सङ्गतयः। एकं अनादिकालात् जीवेन सह जीवस्वरूपे मिलितं \"स्वभावः\"। तेन सह सत्त्वं रजः तमः इति त्रीणि \"प्रभावानि\"। स्वभावः कदापि न परिवर्तते। वयम् अस्मदीयं स्वभावं ज्ञातव्याः। परं अस्मदीयः स्वभावः कः इति अस्मभ्यं ज्ञायत एव न! यतः अस्य स्वभावस्य उपरि आच्छादनरूपेण \"प्रभावः\" उपविष्टः। वयं सदा एतस्य आच्छादनस्य प्रभावम् एव अस्मदीयं स्वभावम् इति भ्राम्यामः। परं तत् अस्मदीयं यथार्थं स्वरूपस्वभावं न भवति -- तत् प्रभावः। सम्पूर्णं जीवमानपर्यन्तं अस्मदीयः स्वभावः कः इति अस्मभ्यं न ज्ञायेत। स्वभावः कः इति अज्ञात्वा वयम् अस्मिन् प्रभावे पतित्वा आन्दोलिताः भवामः। अस्मभ्यम् एतेषां त्रिगुणानां प्रभावः कथं कार्यं करोति इति अज्ञातं चेत् -- वयम् आत्मानं सुधारयितुं न शक्नुमः। अद्य वयम् अस्मदीयं स्वभावं सत्त्वगुणं च कोणे स्थापयित्वा, रजसः तमसः च नियन्त्रणे जीवामः।\n\nप्रथमं वयम् आत्मानं सुधारयेम -- न समाजम्। अस्मासु सत्त्वस्य अंशः कियान् अस्ति, रजसः अंशः कियान् अस्ति, तमसः अंशः कियान् अस्ति -- इति ज्ञात्वा, अस्मदीये आचरणे सत्त्वस्य अंशम् अधिकतया उपयुज्य, तस्य अंशं वर्धयितुं यतितव्यम्। पूर्वं घटितासु घटनासु वयं कुत्र रजसः तमसः च प्रभावेण स्खलिताः, इति आत्मचिन्तनं कृत्वा, अग्रे तथा न भवेत् इति सावधानाः भवेम। इमं विषयं ज्ञात्वा आचरेम चेत् वयम् आत्मानं नियन्त्र्य अतीव आनन्देन जीवितुं शक्नुमः।\n\nअग्रिमेषु श्लोकेषु कृष्णः सत्त्वस्य जीवनं कीदृशं, रजसः जीवनं कीदृशं, तमसः जीवनं कीदृशम् इति विवृणोति। त्रिगुणस्य बन्धने बद्धाः जीवाः, कस्य गुणस्य प्रभावेण कथं आचरन्ति इति ज्ञातं चेत्, सत्यस्य मार्गे गन्तुं यत्नः कर्तुं शक्यते। अस्मै अतीव सुन्दरं विश्लेषणं कृष्णः अग्रिमेषु श्लोकेषु दत्तवान्।",
  "14.6": "तत्र सत्त्वम् निर्मलत्वात् प्रकाशकम् अनामयम् ।\nसुख संगेन बध्नाति ज्ञान संगेन च अनघ ॥\n\nतेषु सत्त्वगुणः परिशुद्धः। अतः ज्ञानस्य प्रकाशं ददत्, व्याधीन् नाशयत् च। हे अनघ, तत् सुखस्य सम्बन्धेन ज्ञानस्य च सम्बन्धेन बध्नाति।\n\nनेत्रे निमील्य स्वान्तः स्वात्मानं पश्य। स्वान्तः प्रवर्तमानान् मानसविकासान्, चिन्तनानि, विचारान्, भावनाः च पश्य। सत्त्वगुणस्य प्रभावः त्वयि स्यात् चेत् -- त्वं स्वान्तः स्वच्छं निर्मलं निरालं प्रज्वलत् ज्योतिः पश्यसि। अस्मदीये अन्तरङ्गप्रपञ्चे पूर्णा विद्युत्संयोजना अस्ति, दीपः अस्ति, तं दीपं नियन्त्रयन्ति अनेकाः स्विच् अपि संयोजिताः। अत्र निरन्तरा विद्युत्आपूर्तिः अस्ति। परं अस्मभ्यम् इयं स्विच् कुत्र इति न ज्ञातम्। अतः सर्वं सत् अपि सदा अस्मदन्तः तमः आवृतं भवति। वयं तां न उपयुज्महे। अस्मासु सत्त्वगुणे जागृते सति अस्मभ्यम् इयं स्विच् प्राप्यते। तया कस्यापि दोषस्य रहितं ज्ञानस्य प्रकाशः अस्मदन्तः प्रकाशते।\n\nसत्त्वस्य गुणे जागृते सति अस्मासु अन्तरङ्गस्य आनन्दः पूर्णः उच्छलति। एषः अनुभवः बहुभ्यः जनेभ्यः जातः भवति। उदाहरणार्थम् -- कदाचित् वयं वदामः -- \"किमर्थमपि अद्य अतीव सन्तोषः जायते\" इति। तत्र कोऽपि विशेषः हेतुः न भवति। परं अन्तरङ्गस्य आनन्दस्य बहिः प्रसरणम् एव वयम् अनुभवामः इत्येव। इयं सत्त्वगुणस्य जागृतावस्था। ज्ञानात् आगच्छत् सुखं सर्वं सात्त्विकम्।\n\nअत्र एकां सावधानतां कृष्णः ददाति। सत्त्वगुणः अस्मासु जागृतः भवितुम् इच्छति चेत् वयम् \"अनघाः\" भवेम। पापस्पर्शः अस्मासु स्यात् चेत् -- सत्त्वगुणः न जागर्ति। अतः वयं पापात् दूराः भवेम। पापस्पर्शः यावान् अधिकः अभवत् -- तावत् सत्त्वं दूरं गच्छति।\n\nमोक्षसाधनायां सत्त्वगुणः साधनं स्यादपि, तथापि इदम् एकं त्रिगुणेषु। अतः सत्त्वगुणोऽपि बन्धकं भवितुम् अर्हति। इदं सुखस्य सम्बन्धेन ज्ञानस्य सम्बन्धेन च अस्मान् बद्धुम् अर्हति। उदाहरणार्थम् -- ज्ञानसाधना सात्त्विकः गुणः। अत्र भगवद्विषयं विना अन्यस्य ज्ञानस्य साधनायाः सम्बन्धे वयं पतेम चेत् -- तदा तत् बन्धकं भवति। वयं यत्किमपि अन्वेषणे, गवेषणायां वा निमग्नाः स्याम चेत्, तत् अस्मान् मोक्षं प्रति नेतुं न शक्नोति। वयं तस्याः गवेषणायाः फलितांशस्य सुखस्य सम्बन्धे लग्नाः भूत्वा सत्त्वगुणस्य बन्धने पतेम। मोक्षसाधनायां वयं सत्त्वमपि अतिक्रामेम। यतः मोक्षः त्रिगुणातीतः। कृष्णः अत्र सत्त्वगुणं \"बध्नाति\" इति उक्तवान्। यतः इदं बन्धनं सुलभेन विमोचनीयं बन्धनम्। तत् कदापि अस्मान् अधः न आकर्षति। [रजस्तमसी तु \"निबध्नाति\" इति कृष्णः अग्रिमेषु श्लोकेषु उल्लिखितवान्।] यत् सत्त्वं भगवन्तं प्रति न गच्छत् अस्मान् बन्धने भ्रामयति -- तस्मात् सत्त्वात् वयं मुक्ताः भवेम।",
  "14.7": "रजः रागात्मकम् विद्धि तृष्णा संग समुद्धवम् ।\nतत् निबध्नाति कौंतेय कर्मसंगेन देहिनम् ॥\n\nरजोगुणः रञ्जकः, आशाआसक्तीः जनयन्, इति जानीहि। हे कौन्तेय, तत् जीवं कर्मणः सम्बन्धेन बध्नाति।\n\nरजः इत्युक्ते \"रागः\"। एकां वस्तुं अतीव इष्टं मन्यमानता, इच्छानां शृङ्खला -- एवं समस्तानां पञ्चेन्द्रियाणाम् इच्छाः रजोगुणस्य प्रभावेण आगच्छन्ति। इदं तृष्णायाः सङ्गस्य च कारणम्। अत्र तृष्णा इत्युक्ते \"आवश्यकम्-आवश्यकम्\" इति दाहः। सङ्गः इत्युक्ते एकस्याः वस्तुनः निरन्तरः सम्पर्कः। रजोगुणः इच्छां जनयति। तया इच्छया सम्पर्कः, सम्पर्केण तत् आसक्तिं जनयति। एवं क्रमेण रजोगुणः अस्मान् अविमोचनीयेन बन्धनेन बध्नाति (निबध्नाति)। तस्य प्रभावेण वयं ज्ञानेच्छारहितं कर्मसङ्गं कर्तुम् आरभामहे। उदाहरणार्थम् -- धनार्थं संघर्षः, धनार्थम् एव सम्पूर्णं जीवनं समर्पणम्। धनम् एव प्रपञ्चः इति संघर्षः, इत्यादि। इदं रजसः गाढस्य बन्धनस्य प्रभावः।",
  "14.8": "तमः तु अज्ञानजम् विद्धि मोहनं सर्वदेहिनाम् ।\nप्रमाद आलस्य निद्राभिः तत् निबध्नाति भारत ॥\n\nसमस्तेभ्यः जीवेभ्यः अज्ञानं ददत्, मोहयत् -- तमोगुणः इति जानीहि। हे भारत, तत् प्रमादेन, आलस्येन, निद्रया च बध्नाति।\n\nकिमपि अज्ञातम् इति स्थितिः तमः। तमोगुणेन अज्ञानं जायते। तत् कियत् बलिष्ठं यत् -- तत् \"मयि ज्ञानं नास्ति, अहम् अज्ञानी\" इति ज्ञानम् अपि न आगच्छति तथा कर्तुं शक्नोति। इदम् अतीव भयानकम्। \"मह्यं किमपि न ज्ञातम्\" इति विषयोऽपि मह्यं न ज्ञातः भवति तमोगुणेन। इदं समस्तान् भ्रान्तौ निक्षिपत् गुणम्। तमः वयं विमोचयितुम् अशक्याभिः त्रिभिः बन्धैः अस्मान् बध्नाति। ताः सन्ति निद्रा, आलस्यं, प्रमादः च। जागरणेऽपि जागरणं विना जीवनं प्रमादः। दोषं कर्तुं दोषः न, परं दोषं कृत्वापि न सुधार्यते तत् प्रमादः। एतस्य सर्वस्य कारणम् अस्मासु विद्यमानः तमोगुणः।",
  "14.9": "सत्त्वं सुखे संजयति रजः कर्मणि भारत ।\nज्ञानम् आवृत्य तु तमः प्रमादे संजयति उत ॥\n\nसत्त्वगुणः सुखस्य सम्बन्धे भवति। हे भारत, रजोगुणः कर्मणः सम्बन्धे भवति। तमोगुणः अवबोधं आवृत्य मोहयत् एव तिष्ठति।\n\nअस्मिन् श्लोके कृष्णः त्रीन् गुणान् एकत्र संक्षिप्य वदति। सत्त्वस्य मूलगुणधर्मः किम् इति चेत् -- तेन अस्मत्तः एकः सहजः आनन्दः उच्छलति। रजोगुणः \"किमपि कर्तव्यम्, अन्यथा जीवने सुखं नास्ति\" इति, सदा धनार्थं संघर्षं कुर्वन्तः, स्वजीवनं क्षपयितुं कारयति। तमः अस्मासु विद्यमानं ज्ञानम् आवृणोति। उदाहरणार्थम् -- कष्टे स्थितेभ्यः साहाय्यं कर्तव्यम् इति साधुत्वम्, दाने आनन्दः -- सत्त्वगुणः। स्वयं सुखी भवितव्यम् इति सदा सुखस्य अन्वेषणे निरतः, अकर्तव्यं कर्म कुर्वन् जीवनम् -- रजोगुणः। आलस्यं, निद्रा, अज्ञानं, तेन प्रमादः -- एतत् सर्वं तमोगुणस्य प्रभावः। इदम् अस्मभ्यं कृष्णेन गीतायाः मुखेन उक्तम् अत्युत्कृष्टं मनःशास्त्रम्।\n\nएतत् गुणत्रयं कथम् अस्मान् नियन्त्रणं गृहीत्वा नर्तयति इति कृष्णेन निरूपितं वयं दृष्टवन्तः। अत्र अस्माकम् एकः सन्देहः जायेत। एते त्रयः गुणाः सह एककालम् एव कार्यं कुर्वन्ति, तर्हि केवलं सात्त्विकं चिन्तनम्, केवलं राजसं चिन्तनम्, केवलं तामसं चिन्तनं कथं सम्भवति? त्रयः गुणाः एकस्य देहे स्थिताः सत्सु यत् कोऽपि एकः गुणः कार्यं कर्तुं कथं शक्यम्? त्रयः गुणाः मिश्रिताः अस्मदन्तः स्थिताः सत्सु एकं पृथक् सात्त्विकं स्वभावम्, राजसं स्वभावम्, तामसं स्वभावं च अभिज्ञातुं कथम्? अस्य विवरणम् अग्रिमः श्लोकः।",
  "14.10": "रजः तमः च अभिभूय सत्त्वम् भवति भारत ।\nरजः सत्त्वम् तमः च एव तमः सत्त्वम् रजः तथा ॥\n\nहे भारत, रजस्तमसी अपसार्य सत्त्वगुणः बलं गृह्णाति; सत्त्वतमसी अपसार्य रजोगुणः; तथैव सत्त्वरजसी अपसार्य तमोगुणः।\n\nगुणत्रयाय एका विशिष्टा शक्तिः अस्ति। एतेषु त्रिषु यत् कोऽपि एकः अस्मदीयस्य मनसः नियन्त्रणं गृहीत्वा शेषौ द्वौ गुणौ आच्छादयति (suppresses)। त्रयाणां मध्ये एकः गुणः अस्मदीयं मनः स्वाधीनं करोति। तदा अस्मदीयं मनः तस्मै गुणाय अनुगुणं कार्यं कर्तुम् आरभते। त्रिगुणाभिमानिनी लक्ष्मीः। सा यस्मै कस्मैचित् गुणाय शेषौ द्वौ गुणौ अतिक्रम्य कार्यं कर्तुं शक्तिं ददाति। एवम् एकः गुणः शेषौ द्वौ गुणौ आच्छाद्य कार्यं कर्तुम् आरभते।\n\nअस्मासु कः गुणः जागृतः अस्ति इति वयम् अभिज्ञातव्याः। तदा तस्य गुणस्य प्रभावेण जायमानम् अनर्थं वयं परिहर्तुं शक्नुमः। एतत् अभिज्ञातुं विधानं कृष्णः अग्रिमेषु त्रिषु श्लोकेषु विवृणोति।",
  "14.11": "सर्वद्वारेषु देहे अस्मिन् प्रकाशः उपजायते ।\nज्ञानम् यदा तदा विद्यात् विवृद्धम् सत्त्वम् इति उत ॥\n\nअस्मिन् देहे सर्वेषु इन्द्रियेषु ज्ञानं प्रकाशरूपेण उदेति यदा, तदा सत्त्वगुणः बलं गृहीतवान् इति ज्ञातव्यम्।\n\nसत्त्वगुणे जागृते सति अस्मदन्तः ज्योतिः पूर्णं अनुभूयते। एतस्य ज्योतिषः सञ्चारः सर्वेषाम् इन्द्रियाणां मुखेन बहिः आगच्छति। सर्वेन्द्रियेषु ज्ञानस्य आनन्दः पूर्यते। सर्वेभ्यः अधिकं मुख्यतया अस्मदीये मनसि नूतनाः ज्ञानविचाराः (novel idea) स्फुरितुम् आरभन्ते। अनेन अपारः सन्तोषः जायते। इयं सत्त्वगुणस्य जागृतावस्था।",
  "14.12": "लोभः प्रवृत्तिः आरंभः कर्मणाम् अशमः स्पृहा ।\nरजसि एतानि जायंते विवृद्धे भरतर्षभ ॥\n\nहे भरतर्षभ, रजोगुणे बलं गृहीते सति दृश्यमानाः अंशाः इमे -- लोभः, उन्मत्तोत्साहः, कार्येषु प्रवृत्तिः, अशान्तिः, अतृप्ता स्पृहा च।\n\nरजोगुणे जागृते सति अस्मासु प्रथमं दृश्यते लोभः। कथं धनं कर्तव्यम् इति चिन्ता; अन्यस्मै एकमपि लघुधनं न ददत् कार्पण्यम्, इत्यादि। उदाहरणार्थं केचन स्वगृहसमारम्भाय लक्षशः व्ययं कुर्वन्ति। परं कश्चन उदरपूर्तिं विना आगत्य याचते चेत् तस्मै किमपि दानं न लभ्यते। इदं लोभित्वम्। एतादृशान् लोभिनः प्रति नीतिशतके भवभूतिः एवम् उक्तवान् --\n\n\"दानं भोगो नाशः तिस्रो भवन्ति गतयो वित्तस्य ।\nयः न ददाति न भुङ्क्ते तस्य तृतीया गतिः भवति ॥ (१५८)\"\n\nधनस्य त्रीणि रूपाणि विनियोगस्य -- दानं, भोगः, नाशः। लोभिनः स्वस्य धनं न अन्यस्मै ददति, न स्वयं भुञ्जते, अन्ततः तत् शृगालश्वपाल्यां नष्टं भवति। इदं रजोगुणस्य प्रभावेण जायमानं परिणाम। रजोगुणस्य प्रभावेण व्यक्तिः सदा यां कां चित् प्रवृत्तिं कर्तुम् इच्छति। धनार्जनाय बहुविधाः व्यवहाराः; यावत् संलग्नः स्यात् तथापि तत्र अतृप्तिः; स्वव्यवहारे भगवता उदरपूर्त्यर्थं पर्याप्तं दत्तेऽपि तत्र तृप्तिः न भवति; स्वागतवेतने सुखेन जीवितुं शक्यमपि, तत् समीपगृहस्थस्य वेतनात् न्यूनम् इति खिन्नता, इत्यादि। एतादृशानां नित्यमन्त्रः \"आवश्यकम्-आवश्यकम्\"। सत्त्वगुणं तुलित्वा रजोगुणः शिरः उत्थाप्य तिष्ठति यदा एतानि सर्वाणि लक्षणानि दृश्यन्ते।\n\nअत्र व्यासैः \"भरतर्षभ\" इति विशेषणं प्रयुक्तम्। रजोगुणात् पारं गन्तुं वयं भरतर्षभाः भवेम। ऐतरेयब्राह्मणे \"वायुर्वाव भरतः\" इति एका उक्तिः अस्ति। सदा भगवति निरतस्य वायुदेवस्य \"भरतः\" इति नाम। प्राणदेवे शरणागतिः अस्मान् रजोगुणात् पारं नेतुं शक्नोति।",
  "14.13": "अप्रकाशः अप्रवृत्तिः च प्रमादः मोहः एव च ।\nतमसि एतानि जायंते विवृद्धे कुरुनंदन ॥\n\nहे कुरुनन्दन, तमोगुणे बलं गृहीते सति दृश्यमानाः अंशाः इमे -- अन्धकारः, उत्साहराहित्यम्, जागृतिराहित्यम्, भ्रान्तिः च।\n\nतमोगुणे जागृते सति अन्तः बहिः च सर्वं तमः। सदा निद्रां कुर्वन्, दोषं कुर्वन्, अज्ञाने जीवन् -- तमोगुणस्य प्रभावेण। प्रातःकाले सूर्योदयात् पूर्वम् उत्थातुं तमोगुणः न ददाति। सदा निद्रां कुर्यात् इति एषः गुणः अस्मान् प्रेरयति। एषः गुणः सदा तमः इच्छन्तं करोति। अस्य प्रभावात् पारं गन्तुं वयं कुरुनन्दनाः भवेम। आत्मानं यस्मिन् कस्मिन् कर्मणि नियोज्य तत् अभ्यासं कर्तव्यम्। उदाहरणार्थम् -- प्रातः सूर्योदयात् पूर्वम् उत्थानस्य अभ्यासः। एवम् अभ्यासे कृते मनः तत् त्यक्तुं न इच्छति।\n\nअस्मासु केचन वदन्ति -- \"अध्यात्मचिन्तनाय मम समयः नास्ति\" इति। परं एवं वदतां बहवः स्वच्छन्ददिनेषु, अवकाशकाले प्रातःकालात् सायंकालपर्यन्तं आलस्येन निद्रां कुर्वन्तः कालं यापयन्ति! एवम् अस्मदज्ञाततया अस्मान् तमोगुणः आक्रम्य नियन्त्रयति। वयम् आलस्यरहिताः भूत्वा यस्मिन् कस्मिन् कर्तव्ये आत्मानं नियोजयेम चेत् तमोगुणस्य प्रभावात् पारं भवितुं शक्नुमः।",
  "14.14": "यदा सत्वे प्रवृद्धे तु प्रळयम् याति देहभृत् ।\nतदा उत्तमविदाम् लोकान् अमलान् प्रतिपद्यते ॥\n\nसत्त्वगुणे बलं गृहीते सति जीवः मरणं प्राप्नोति चेत् -- सः महत् तत्त्वं विदुषां कुले, निर्दोषं देहं प्राप्नोति।\n\nअस्माभिः ज्ञातं यत् जीवः देहं त्यक्त्वा बहिः गच्छन् अन्तिमः क्षणः तस्य जीवस्य अग्रिमां गतिं निर्धारयति। अन्त्यकाले सात्त्विकेन चिन्तनेन, सत्त्वस्य प्रभावे प्राणं त्यक्तुं शक्यते चेत्, अग्रिमे जन्मनि केनापि दोषेण रहिताः मनुष्याः भूत्वा ज्ञानिनां समुदाये जायामहे। तत्र ज्ञानिभिः सह स्थित्वा, ज्ञानं वर्धयित्वा पुनः ज्ञानमार्गे उच्चैः आरोढुं शक्यते। जीवमानकाले वयं सत्त्वाय बलं दत्त्वा जीवेम चेत् एव मरणकाले सत्त्वस्य अधिष्ठाने मर्तुं शक्यते भवेत्। एतद् विहाय \"मरणकाले सात्त्विकं चिन्तनं करिष्यामः\" इति जीवेम चेत्, सत्त्वस्य प्रभावे मरणम् असाध्यम्।",
  "14.15": "रजसि प्रळयम् गत्वा कर्म संगिषु जायते ।\nतथा प्रलीनः तमसि मूढ योनिषु जायते ॥\n\nरजोगुणे मरणं प्राप्नुवन् कर्मासक्तेषु जायते। तमोगुणे मृतः अज्ञातेषु हीनयोनिषु जायते।\n\nज्ञानस्य अपोषकं कर्मानुष्ठानं कुर्वन् रजोगुणस्य प्रभावे धनं धनम् इति जीवित्वा, तस्मिन्नेव प्रभावे म्रियते चेत् -- अग्रिमे जन्मनि कर्मणि आसक्तः भूत्वा जन्तव्यं भवति। इतः परं तमोगुणस्य प्रभावे जीवित्वा मृते हीनयोनौ जन्तव्यं भवति। अत्र \"हीनयोनिः\" इत्युक्ते मनुष्यः अपि भवितुम् अर्हति। यस्य कस्यापि संस्कारेण रहितः, स्वच्छतया रहितः, ज्ञानेन रहितः, केवलं मनुष्याकारं प्राप्य, मनुष्यत्वस्य लेशमपि विना मनुष्यरूपेण जीवनम् अपि हीनयोनिजन्म। अस्मात् पशुजन्म कियत् श्रेष्ठम्। इदं तमोगुणे मृतस्य परिणामः। [मरणस्य अन्तिमे क्षणे रजस्तमसोः प्रभावेण मृते सति, तत् अस्मदीयं अग्रिमं जन्म कथं प्रभावयति इति -- गजेन्द्ररूपेण जातस्य इन्द्रद्युम्नस्य, मृगरूपेण जातस्य भरतचक्रवर्तिनः च कथया वयं ज्ञातुं शक्नुमः।]",
  "14.16": "कर्मणः सुकृतस्य आहुः सात्त्विकम् निर्मलम् फलम् ।\nरजसः तु फलम् दुःखम् अज्ञानम् तमसः फलम् ॥\n\nसुकृतस्य कर्मणः दुःखरहितं सात्त्विकं फलम् इति विदुषः वदन्ति। राजसस्य कर्मणः फलं दुःखमिश्रितं सुखम्। अज्ञानम् एव तमोगुणस्य कर्मणः फलम्।\n\nजीवनपर्यन्तम् अन्यस्मै साहाय्यकरं कर्म कुर्यात् चेत् तत् सुकृतम्। अस्मासु सम्पत्तौ सत्यां तत् \"मम-मम\" इति लोभेन जीवेम चेत् तेन दुःखपूर्णं जीवनम् अस्मदीयं भवति। अस्माभिः अर्जितं यत् तत् अन्यस्य कष्टे विनियुज्यते यदा तत् अस्मान् सात्त्विकं फलं प्रति नयति। मध्वाचार्याः इमं विषयं भारपूर्वकं गृहीत्वा स्वकीये \"गीतातात्पर्ये\" एवम् उक्तवन्तः -- \"नाना जनस्य शुश्रूषा कर्तव्या करवत् मिते\" इति। कष्टे स्थितानां सेवा मोक्षसाधनायाः एकं मुखम्। अस्मासु केचन कष्टे स्थितान् दृष्ट्वा एवं वदन्ति -- \"तत् तस्य प्रारब्धकर्म, तत् सः अनुभवतु। तस्मै अहं किमर्थं चिन्तयेयम्\" इति। एवं उक्ते वयं तस्य कष्टे स्थितस्य व्यक्तेः अन्तः स्थितं भगवन्तं तिरस्कारं कृतवन्तः भवामः। एतादृशेभ्यः कदापि भगवतः साक्षात्कारः न भवति। अस्मदीयायाम् आध्यात्मिकसाधनायां जपतपसी एव न पर्याप्ते; अत्र कष्टे स्थितानां जनानां सेवा अपि एकः प्रधानः अंशः। साधकः स्वनित्यानुष्ठानैः सह एतत् सेवाकार्यम् आचरेत् इति गीतायाः आदेशः इति मध्वाचार्याः प्रतिपादितवन्तः। त्वद्गृहे पक्वम् अन्नं यावतां क्षुधार्तानां जनानां क्षुधां शमयति -- तावत् सुकृतम्। अस्मात् कारणात् पूर्वकाले एका सम्प्रदायः आसीत्। पाकं कृत्वा, देवाय तत् अर्प्य, प्रायः दश मिनिट् मुख्यद्वारे प्रतीक्ष्य, ततः भोजनं कर्तुम्। यतः अस्मिन् समये कोऽपि क्षुधार्तः गृहस्य वीथ्यां आगच्छेत् चेत् तस्मै प्रथमं भोजनं दत्त्वा, अनन्तरं गृहस्वामी भुञ्जीत -- इयं तदानीन्तनी पद्धतिः आसीत्। एतावता न, अस्मात् पूर्वम् अपि \"बलिहरणं\" कुर्वन्ति स्म। गृहस्य समीपस्थेभ्यः प्राणिपक्षिभ्यः आहारं दानं \"बलिहरणम्\"। एवं जीवनपर्यन्तम् उत्तमं कर्म कृतं चेत् तस्य फलं सात्त्विकं भवति। अनेन अस्मिन् जन्मनि ज्ञानं प्राप्तुं न शक्यते चेदपि, अग्रिमे जन्मनि सः अवकाशः उपलभ्यते। ज्ञानवानपि दुष्कृत्या जीवेत् चेत् पुनः हीनयोनौ जन्तव्यं भवति।\n\nहोमहवनं, दानदक्षिणा, ब्राह्मणाराधना -- सर्वं कृत्वा \"अहं सर्वेभ्यः महान्\" इति अहङ्कारः आगच्छेत् चेत् तत् रजसः कर्म भवति। तस्य फलं लोभः; दुःखमिश्रितं जीवनम्। अनेन पुण्यकर्म कृत्वापि दुःखम् अनुभवितव्यं भवति। अज्ञानेन, कस्यापि दबावेन कृतेन कर्मणा कदापि ज्ञानं न वर्धते। अज्ञानम् एव तमोगुणस्य कर्मफलम्।\n\nअस्मासु कः गुणः पूर्णतया जागृतः अस्ति इति कथं ज्ञायते, इति विवरणं कृष्णः अग्रिमे श्लोके उपसंहाररूपेण विवृणोति।",
  "14.17": "सत्त्वात् संजायते ज्ञानम् रजसः लोभः एव च ।\nप्रमाद मोहौ तमसः भवतः अज्ञानम् एव च ॥\n\nसत्त्वात् ज्ञानं जायते। रजसः लोभः एव जायते। तमसः प्रमादः मोहः च, अज्ञानम् एव च जायते।\n\n\"सत्त्वात् सञ्जायते ज्ञानम्\" -- गीतायाः इयं पङ्क्तिः अतिमुख्यं सन्देशं ददाति। यदा मनुष्याय शेषेभ्यः सर्वेभ्यः विषयेभ्यः ज्ञानं मुख्यम्, तदर्थम् अहं किमपि त्यक्तुं सिद्धः इति दृढः निश्चयः आगच्छति -- तदा वयं निःसंदेहं इदं सत्त्वगुणस्य पूर्णा जागृतावस्था इति ज्ञातुं शक्नुमः। अस्मै उत्तमम् उदाहरणं कठोपनिषदि आगच्छतां यमनचिकेतसोः संवादः --\n\n\"एतत् तुल्यं यदि मन्यसे वरं वृणीष्व वित्तं चिरजीविकां च ।\nमहाभूमौ नचिकेतः त्वम् एधि कामानां त्वा कामभाजं करोमि ॥ (१-२४)\nये ये कामाः दुर्लभाः मर्त्यलोके सर्वान् कामान् छन्दतः प्रार्थयस्व ।\nइमाः रामाः सरथाः सतूर्याः न हि ईदृशाः लम्भनीयाः मनुष्यैः ।\nआभिः मत्प्रत्ताभिः परिचारयस्व नचिकेतः मरणं मा अनुप्राक्षीः ॥ (१-२५)\"\n\nअत्र \"मह्यम् आत्मज्ञानं बोधय\" इति नचिकेतसा यमः पृष्टः सन् वदति -- \"त्वं अद्यापि लघुः, सा विद्या मा भव। तस्य बदले त्वां भूमण्डलस्य चक्रवर्तिनं करिष्यामि; त्वया इष्टं प्राप्नोतु; आयुष्यम् ऐश्वर्यं च दास्यामि\" इति यमः वदति। तदा नचिकेतः एवं वदति --\n\n\"श्वोभावाः मर्त्यस्य यत् अन्तकैतत् सर्वेन्द्रियाणां जरयन्ति तेजः ।\nअपि सर्वं जीवितं अल्पम् एव तव एव वाहाः तव नृत्यगीते ॥ (१-२६)\nन वित्तेन तर्पणीयः मनुष्यः लप्स्यामहे वित्तम् अद्राक्ष्म चेत् त्वा ।\nजीविष्यामः यावत् ईशिष्यसि त्वं वरः तु मे वरणीयः सः एव ॥ (१-२७)\nअजीर्यताम् अमृतानाम् उपेत्य जीर्यन् मर्त्यः क्वधःस्थः प्रजानन् ।\nअभिध्यायन् वर्णरतिप्रमोदान् अतिदीर्घे जीविते कः रमेत ॥ (१-२८)\nयस्मिन्निदं विचिकित्सन्ति मृत्यो यत् साम्पराये महति ब्रूहि नः तत् ।\nयः अयं वरः गूढम् अनुप्रविष्टः नान्यं तस्मात् नचिकेता वृणीते ॥ (१-२९)\"\n\n\"त्वं यावत् अपि ददासि तत् अल्पम्। यावत् अपि आयुः प्राप्नुयां वयम् एकदा मर्तव्याः। अतः इदं यत्किमपि मह्यं न आवश्यकम्। त्वं सम्पूर्णं जगत् मह्यं धारया ददासि चेदपि तत् मह्यं न आवश्यकम्। मह्यं ज्ञानम् आवश्यकम्। तत् आत्मज्ञानविद्याम् एव मह्यं बोधय\" इति। इयं कस्यापि प्रलोभनस्य वशं न गच्छन्ती यथार्था सत्त्वगुणस्य निष्ठा। ज्ञानसाधनायाः यथार्थक्षुधावन्तः सर्वं त्यक्तुं सिद्धाः भूत्वा कथं ज्ञानमार्गे गच्छन्ति इत्यस्य नूतनम् उत्तमम् उदाहरणं स्वामी रामः (१९२५-१९९६)। तस्य जीवनचरितं वयं ग्रन्थेषु पठित्वा ज्ञातुं शक्नुमः। शास्त्रं पठितेऽपि शास्त्रस्य यथार्थं ज्ञानम् आगन्तुं चेत् अस्मासु सात्त्विकता अपेक्षिता। अकारवाच्यस्य भगवतः ज्ञानम् आगच्छति सत्त्वगुणे सत्येव। सत्त्वगुणे पूर्णतया जागृते सति अस्मभ्यं यथार्थज्ञानं ज्ञायते, शेषाणि सर्वाणि प्रापञ्चिकानि विषयाणि ज्ञानस्य पुरतः शून्यानि इति सत्यं ज्ञायते।\n\n\"रजसः लोभः एव च\" -- लोभः इत्युक्ते रजसः एव मौलिकः गुणः (exclusive quality)। इदं सात्त्विकेषु द्रष्टुं न शक्यते। यस्याः कस्याश्चित् वस्तुनः विषये कामः, तस्याः अलाभे क्रोधः, लाभे लोभः। तत् न उपयुज्यते, न अन्यस्मै दीयते। दानम् इत्युक्ते एतेषाम् अतिदूरम्! वयम् अस्मत्समीपे यत् अस्ति तत् विभज्य जीवेम इति सत्त्वम्। इदम् ईशोपनिषदि अतीव सुन्दरतया उक्तम् --\n\n\"ईशावास्यम् इदं सर्वं यत् किंच जगत्यां जगत् ।\nतेन त्यक्तेन भुञ्जीथाः मा गृधः कस्यस्विद्धनम् ॥\"\n\nभगवान् सर्वस्य स्वामी। तेन दत्तं वयम् अनुभवेम। अविद्यमानायै सम्पत्तये आशां न कुर्याम। जगतः सर्वस्याः सम्पत्तेः स्वामी सः भगवान्। अतः तेन दत्तां सम्पत्तिं \"मम\" इति मत्वा लोभेन जीवनं न उचितम्। परं रजोगुणस्य अतिमुख्यः दोषः एषः लोभः। इदम् अन्यस्य विषये सहानुभूतिं विना, स्वार्जितं अन्यस्मै अददत्, कदाचित् स्वयमपि अभुञ्जत् आच्छाद्य स्थापयितुं कारयति। सामान्यतः पशुष्वपि अविद्यमानः दुष्टगुणः एषः लोभः। अस्मासु लोभस्य लक्षणं स्यात् चेत् तत् रजोगुणस्य जागृतावस्था इति वयम् अवगन्तव्याः।\n\n\"प्रमादमोहौ तमसः भवतः अज्ञानम् एव च\" -- यथा रजोगुणेन लोभः, तथा तमोगुणेन प्रमादः मोहः च, तेन अज्ञानम्। कञ्चन अतिशयेन आसज्य स्वीकृत्य, तेन तस्य कृतान् दोषान् क्षमित्वा, तेन उक्तानुसारं नृत्यन्तः, इत्यादि। इदं कियत् प्रभावशाली यत् -- इदम् अस्मदीयं ज्ञानमपि आच्छाद्य अस्मान् दुर्मार्गे नयति। अस्मै उत्तमम् उदाहरणं भागवतस्य षष्ठस्कन्धस्य प्रथमाध्याये आगच्छति अजामिळस्य कथा। एषः एकः सात्त्विकः ब्राह्मणः आसीत्। तस्य विवाहः अभवत्। एकदा पूजायै पुष्पतुलसी आनेतुं वनं गतः दृष्टं दृश्यं तस्य मनसि गाढं परिणामम् अकरोत्। स्वयं वने दृष्टां युवतीं सः मोहितुम् आरब्धवान्। तस्यै मद्यमांसाहारे प्रवृत्तः। तस्याः इच्छाः पूरयितुं चौर्यम् अकरोत्। सात्त्विकः विप्रः पूर्णतामसः अभवत्। इमां कथां मनःशास्त्रीयदृष्ट्या पश्यामः चेत् एवं घटनं किमर्थम् अभवत् इति ज्ञायते। अजामिळः विवाहितः आसीत्, परं तस्य गृहे शौचाशौचसम्बद्धानि अनेकानि कर्माचरणानि अभवन् यैः सः स्वान्तरङ्गस्य इच्छां बलात् निगृहीतवान्। वयम् अस्मदीयाम् इच्छां बलात् अवरुध्नीमः चेत् तत् एकदा न एकदा स्फोटं कृत्वा बहिः आगच्छति। अस्मात् कारणात् शास्त्रकाराः वदन्ति यथा \"अध्यात्मसाधनां कर्तुं पूर्वं तव सांसारिकसुखस्य मोहः स्यात् चेत् तम् अनुभव, तस्य निस्सारतां अवगच्छ, तदा साधना सुकरा\" इति। अजामिळः शास्त्रं पठितवान्, तथापि सः मोहाय बलिः अभवत्। तेन तस्य सर्वं ज्ञानम् अन्तर्हितम् अभवत्। तमोगुणः तस्मिन् अकर्तव्यं दोषं कारितवान्। इदं तमोगुणः अस्मासु प्रबलः भवति यदा अस्मासु जायमानः परिणामः।\n\nअस्मिन् श्लोके कृष्णः अस्मासु कः गुणः कार्यं करोति इति स्पष्टया रूपरेखया विवृतवान्। अस्य श्लोकस्य संग्रहसारांशः एतावान् -- ज्ञानस्य तृष्णा स्यात् चेत् तत् सात्त्विकः गुणः; \"मह्यमेव आवश्यकम्, अन्येभ्यः न स्यात्\" इति लोभः स्यात् चेत् तत् रजः; यस्याः कस्याश्चित् भौतिकाया वस्तुनः उपरि अतिशया ममता मोहः वर्धेत चेत् तत् तमसः कार्यम्।\n\nसत्त्वरजस्तमसाम् अन्यत् अपि एकं मुखम् अस्ति। पूजायां नवशक्तीः उक्त्वा भगवन्तम् अनुसन्धानं कर्तुं पूर्वं \"सं सत्त्वाय नमः, रं रजसे नमः, तं तमसे नमः\" इति एकः मन्त्रः उच्यते। एतं मन्त्रं केचन एवम् अपि वदन्ति -- \"सं सत्त्वाय श्रियः नमः, रं रजसे भुवे नमः, तं तमसे दुर्गायै नमः\" इति। [इदं मन्त्रः न, मूलरूपस्य मन्त्रस्य \"सं सत्त्वाय नमः, रं रजसे नमः, तं तमसे नमः\" इत्येव।] अत्र \"सं सत्त्वाय नमः\" इत्युक्ते सत्त्वगुणाय नमस्कारः न, सत्त्वाभिमानिन्यै श्रीदेव्यै नमस्कारः। \"रं रजसे नमः\" इत्युक्ते रजोऽभिमानिन्यै भूदेव्यै नमस्कारः। \"तं तमसे नमः\" इत्युक्ते तमोऽभिमानिन्यै दुर्गादेव्यै नमस्कारः। एताः लक्ष्म्याः तिस्रः रूपाणि। लक्ष्म्याः मूलरूपं \"महालक्ष्मीः\" इति उच्यते। अस्मात् मूलरूपात् त्रीणि आवेशरूपाणि।\n\nअत्र सत्त्वं जागरयन्ती श्रीदेवी; रजः जागरयन्ती भूदेवी; तमोगुणं जागरयन्ती तमोऽभिमानिनी दुर्गादेवी। \"सत्त्वात् सञ्जायते ज्ञानम्\" -- इत्युक्ते सत्त्वगुणस्य अभिमानिनी लक्ष्मीः ज्ञानप्रदा इत्यर्थः। नारायणस्य ज्ञानम् आगन्तुं श्रीदेव्याः अनुग्रहः अपेक्षितः। \"श्रीः\" सम्पत्तिं ददाति इति विषयः सर्वेभ्यः ज्ञातः। परं ज्ञानाख्यां महासम्पत्तिं ददाति श्रीदेवी इति विषयः बहुभ्यः अज्ञातः। धनं सम्पत्तिः सत्यम्, परं ज्ञानं महासम्पत्तिः -- तां ददाति \"श्री\"। अस्मदन्तः ज्ञानं जागृतं भवितुं चेत् प्रथमं मातुः \"श्री\" रूपम् उपासनीयम्। भगवतः ज्ञानं कृपया देहि इति ताम् एव प्रार्थनीयम्।\n\nशास्त्रकाराः वदन्ति यथा -- मनः भगवन्तं प्रति प्रवहितुं पूर्वं वयं मनोऽभिमानिनं प्रार्थयेम। शिवः मनोऽभिमानी देवता। ज्ञानम् इच्छतां मनसः तमोगुणं, तमः अपसार्य प्रकाशं पूरयन्तौ शिवपार्वती। अस्मात् कारणात् ज्ञानाय प्रथमं वयं प्रार्थनीयं शिवतत्त्वम्। शिवेन ज्ञाने दत्ते सति तत् चित्ते स्मरणशक्तित्वेन अवस्थातुं वयं प्रार्थनीया प्राणशक्तिम् (ब्रह्मवायुः, सरस्वतीभारती च)। अस्मभ्यम् आगतं ज्ञानं विस्मृतिं गच्छत् (स्थिरं भवत्) कारयन्ती मुख्या शक्तिः प्राणशक्तिः (आञ्जनेयः)। एवं स्थिरीभूतं पुनः उच्चैः गत्वा भगवन्तं स्पृशत् कारयन्ती -- सदा भगवता सह वर्तमाना लक्ष्मीदेवी। एतादृशी लक्ष्मीः स्वस्य सर्वस्मिन् रूपे अवबोधं न ददाति। सा स्वस्मिन् श्रीरूपे ज्ञानरूपां सम्पत्तिं करुणां करोति। \"श्री\" महालक्ष्म्याः अवतारेषु एकः। सत्त्वं नियमनं कृत्वा जगतः रक्षायै विष्णुना सह प्रतिज्ञां कृत्वा स्थितं रूपम् इदम्। अतः ज्ञानमार्गे गच्छतां मुख्यः लक्ष्म्याः \"श्री\" नामकः अनुग्रहः।\n\nअत्र शिवः, प्राणदेवः, श्रीदेवी च अनुग्रहेण ज्ञानमार्गे अग्रे गत्वा भगवन्तं प्राप्तुं शक्यते इति वयं विश्लेषितवन्तः। अग्रे भूततत्त्वस्य विषये विश्लेषणात् पूर्वं शान्तिमन्त्रस्य गणपतिप्रार्थनायाः च महत्त्वं संक्षेपेण अत्र विश्लेषयाम। यत्किमपि शास्त्रं पठितुं पूर्वं \"ॐ शान्तिः शान्तिः शान्तिः\" इति शान्तिमन्त्रं पठामः। \"ज्ञानानन्दयोः पराकाष्ठाभूत भगवन्, मां ज्ञानानन्दयोः (शान्तेः) मार्गे नय\" इति एतस्य शान्तिमन्त्रस्य अर्थः। एवमेव प्रत्येकस्यां पूजायां प्रथमं गणपतिप्रार्थनां कुर्मः। यतः शिवपार्वतीपुत्रः गणपतिः आकाशस्य देवता। एषः आकाशः भगवतः नाभेः सृष्टः। अतः गणपतिः अस्मदीयायाः नाभेः देवता।\n\n\"नाभ्या असीत् अन्तरिक्षं शीर्ष्णः द्यौः समवर्तत।\nपद्भ्यां भूमिः दिशः श्रोत्रात् तथा लोकाः अकल्पयन्॥\"\n\nअस्मदीयायाः नाभेः समीपे स्थितानि त्रीणि चक्राणि -- मूलाधारं, स्वाधिष्ठानं, मणिपूरं च। नाभेः ऊर्ध्वं हृत्कमले यथार्थसाधनायाः अनाहतचक्रम् अस्ति। मूलाधारं स्वाधिष्ठानं मणिपूरं च चक्राणि अतिक्रम्य हृदयं प्रवेष्टुं चेत् नाभेः द्वारं गणपतिना उद्घाटनीयम्। अतः वयं गणपतौ प्रथमतया प्रार्थनां कुर्मः। प्रत्येकस्य यज्ञस्य पूर्वं गणपतिमण्डलं लिखित्वा पूजयित्वा, अनन्तरं यज्ञम् आरभन्ते। गणपतिना नाभेः द्वारे उद्घाटिते सति हृत्कमलं स्वयमेव उद्घाट्यते। इयं स्थितिः \"वृषाहः\" इति उच्यते। भगवान् एतस्यां स्थितौ अस्मदीयां पूजां वृषाहीरूपेण स्वीकरोति। एतादृशः भगवान् \"वृषाही\" इति अपि उच्यते।\n\n\"रजसः लोभः एव च\" -- रजः इत्युक्ते रजोगुणस्य अभिमानिनी भूदेवी। अत्र भूदेवी इत्युक्ते भूमेः नियमनं कुर्वती अष्टादशकक्ष्यायां (कक्षास्तरे) स्थिता देवता न। तामपि नियमयन्ती लक्ष्म्याः आवेशरूपा \"भूः\"। सा सृष्टेः कारणभूता। रञ्जनम्, आकर्षणम्, सेलनम्, मोहः -- एतत् सर्वं रजोगुणस्य मुखानि। अतः एकं जनम् अन्यः जनः प्रीणाति तस्य मौलिकम् आवश्यकं रञ्जनम्। पुंस्त्रियोः आकर्षणम् एव सृष्टेः कारणम्। सृष्टये आवश्यकम् आकर्षणं दत्त्वा सृष्टिं कारयन्ती, तेनैव आकर्षणेन मार्गभ्रष्टं कारयन्ती अंशः रजोगुणे अस्ति। तादृशं रजोगुणस्य स्वभावं ददाति भूदेवी। \"मम सम्पत्तिः, मम गृहम्, मम अर्जनम्, मम धनम्\" इत्यादि मोहः रजोगुणात् आगच्छति।\n\n\"प्रमादमोहौ तमसः भवतः अज्ञानम् एव च\" -- भौतिकतया अस्मान् विनाशं प्रति नयन्ती संहारशक्तिः तमोगुणस्य अभिमानिनी दुर्गा। सा संहारं प्रति गच्छन्तीं बुद्धिं ददाति। दोषम् एव सम्यक् इति ज्ञात्वा दोषं कर्तुम्, तेन स्खलितुम्, विपरीतं ज्ञानम्, ज्ञानस्य अभावः, इत्यादि -- तमोगुणस्य प्रभावेण आगच्छन्तानि। एवं चित्प्रकृतेः त्रयाणाम् आवेशरूपाणां श्री-भू-दुर्गाणां, सत्त्वरजस्तमसाम् अभिमानिनीनां रूपेण, त्रिगुणानां मुखेन अस्मान् बध्नन्ति। अतः चित्प्रकृतेः चैतन्यस्य त्रीणि रूपाणि एव सत्त्वं रजः तमः च। [किमर्थम् अत्र इदम् अर्थं कर्तव्यम् इत्यस्य गीतायाम् एव सूचना अस्ति। तत् अग्रे अस्मिन्नेव अध्याये १९तमे श्लोके द्रष्टुं शक्यते। महालक्ष्म्याः श्री-भू-दुर्गारूपस्य विषये अधिकाः विवरणाः अपेक्षिताः चेत् महाभारततात्पर्यनिर्णयस्य \"सर्गानुसर्गलयप्रादुर्भावनिर्णयम्\" पठतु।]",
  "14.18": "ऊर्ध्वम् गच्छंति सत्त्वस्थाः मध्ये तिष्ठंति राजसाः ।\nजघन्यगुण वृत्तिस्थाः अधः गच्छंति तामसाः ॥\n\nसत्त्वे स्थिताः ऊर्ध्वं गच्छन्ति। राजसाः मध्ये तिष्ठन्ति। \"अन्त्यगुणस्य\" प्रभावम् आपन्नाः तामसाः अधः पतन्ति।\n\nत्रिगुणस्य स्वभावम् उक्त्वा कृष्णः तस्य परिणामस्य त्रीन् स्तरान् अस्मिन् श्लोके विवृणोति। सत्त्वे स्थिताः मानसिकतया ऊर्ध्वम् आरोहन्ति। रजोगुणिने कापि उन्नतिः नास्ति। तमसि स्थितः मानसिकतया अधःपातं प्राप्नोति। अत्र \"ऊर्ध्व\" इति पदाय विशिष्टः अर्थः अस्ति। कठोपनिषदि उक्तं यथा --\n\n\"ऊर्ध्वमूलः अवाक्शाखः एषः अश्वत्थः सनातनः ॥ (२-३-१)\"\n\nऊर्ध्वः इत्युक्ते सर्वेभ्यः उपरि स्थितः भगवान्। सत्त्वे स्थितः ऊर्ध्वं गच्छति इत्युक्ते -- भगवतः दिशं मुखं कृत्वा गमनम्। सः अग्रे गच्छन् भगवतः समीपं भवति। परं तमसि स्थितः भगवते पृष्ठं दत्त्वा गच्छति। राजसः तत्रैव अतन्त्रस्थितौ अग्रे गच्छति।\n\nदेवान् बन्धने स्थापयन्ती शक्तिः \"श्रीदेवी\"; मानवान् बन्धने स्थापयन्ती शक्तिः \"भूदेवी\" तथा राक्षसान् बन्धने स्थापयन्ती शक्तिः \"दुर्गादेवी\"। सात्त्विकाः सत्त्वाभिमानिन्याः श्रीदेव्याः कृपायाः पात्राः भूत्वा उपरितनं लोकं प्राप्नुवन्ति [भूमेः उपरि स्थिताः षट् सूक्ष्मलोकाः अन्ततः मोक्षः च]; राजसाः भूदेव्याः बन्धने एव अग्रे गच्छन्ति [भूमिः अन्तरिक्षं च]; तामसाः च दुर्गादेव्याः नियन्त्रणे स्थितं तामसलोकं [भूमेः अधः स्थिताः सप्त सूक्ष्मलोकाः] प्राप्नुवन्ति।",
  "14.19": "न अन्यम् गुणेभ्यः कर्तारम् यदा द्रष्टा अनुपश्यति ।\nगुणेभ्यः च परम् वेत्ति मत् भावम् सः अधिगच्छति ॥\n\nएतेभ्यः सर्वेभ्यः परिणामेभ्यः त्रिगुणान् विना अन्यत् कारणं नास्ति इति यः अवगच्छति [त्रिगुणेभ्यः भिन्नः भगवान् एव सर्वस्य मूलकारणम् इति यः जानाति], गुणेभ्यः अतीतं भगवन्तं यः जानाति [सः एव यथार्थः मनुष्यः], सः मयि एव निवसति।\n\nअस्मदीये जीवने यत्किमपि प्रवर्तते तत् सर्वं एतेषां त्रयाणां गुणानां प्रक्रिया। वयं स्वयं किमपि न कुर्मः। अपि तु सर्वं त्रिगुणानां प्रभावेण प्रवर्तते। प्रकृतितः आगत्य अस्मदीयं स्वरूपम् आच्छाद्य ते कार्यं कुर्वन्ति। अतः एकस्य व्यक्तेः बाह्यव्यवहारेण तस्य यथार्थस्वभावं ज्ञातुं न शक्यते। अस्मात् कारणात् वयं प्रपञ्चे प्रवर्तमानाः घटनाः निर्विकारतया द्रष्टुम् अभ्यसेम।\n\nसत्त्वेन युक्तं मनः सत्त्वस्य अनुगुणं विषयम् एव गृह्णाति। तादृशः व्यक्तिः कदापि \"अहं कृतवान्\" इति भ्रमं न करोति। अत्र गुणेभ्यः भिन्नः कर्ता नास्ति इत्युक्तम्। जडाय कदापि \"कर्ता\" इति न उच्यते। अतः गुणः इत्युक्ते केवलं जडं गुणं न। तस्मै अभिमानिनं चैतन्यम् अभिज्ञातुम् इति सन्देशः अस्मिन् श्लोके अस्ति। [एतद्विषये श्लोके १७ चर्चितवन्तः।] कर्तृत्वे अनेके विधाः। इच्छापूर्विका कृतिः यत्र अस्ति तत् कर्ता। इदम् अस्ति चेतने एव। परं यथार्थं कर्तृत्वं \"स्वतन्त्रा इच्छापूर्विका कृतिः\"। इदम् अस्ति केवलं भगवति। \"नाहं कर्ता हरिः कर्ता\" इति प्रसिद्धं वचनम् अस्माभिः ज्ञातमेव। इदं मोक्षधर्मपर्वणि एवम् उक्तम् --\n\n\"नाहं कर्ता न कर्ता त्वं कर्ता यः तु सदा प्रभुः।\nसः अयं पचति कालः मां वृक्षे फलम् इव आगतम् ॥ (१२-२२०-८४)\"\n\n\"न त्वया कृतम्, न मया कृतम् -- 'सः' अस्माभ्यां कारितवान्\"। एषा जागृतिः सत्यां वयं कर्तृत्वस्य अहङ्कारं कर्तुं न शक्नुमः। अनेन द्वेषः नास्ति, ममकारः नास्ति। \"अहं कृतवान्, मया अभवत्\" इति भ्रान्तिः एव। अस्मिन् जगति यत्किमपि प्रवर्तते तत् एतेषां त्रयाणां गुणानां प्रभावेण प्रवृत्तम्। तत् अतिक्रम्य स्वयं मया किमपि न कृतम्। इयं जागृतिः अस्मासु आगन्तव्या।\n\nत्रिगुणानां प्रभावः जडेऽपि अस्ति, चेतनेऽपि अस्ति। तस्य प्रभावेण क्रिया प्रवर्तते। कश्चन त्वां आक्रोशति चेत् -- तस्मिन् तस्मिन् क्षणे रजोगुणः जागृतः भूत्वा कार्यं करोति इत्यर्थः। वयं अनया जागृत्या तस्मिन् क्षणे वर्तितव्याः। इदं श्रीरामचन्द्रः स्वजीवने आचरित्वा दर्शितवान्। रामायणे वाल्मीकिः वदति --\n\n\"सः हि नित्यं प्रशान्तं मृदुपूर्वं च भाषते।\nउच्यमानः अपि परुषं न उत्तरं प्रतिपद्यते ॥ (अयोध्या-१.१५)\"\n\nरामे यः कोऽपि कलहाय स्थातुं यतते चेत् सः कदापि क्रुद्धः न भवति स्म। \"पुनः वदिष्यावः\" इति उक्त्वा प्रस्थितः भवति स्म। यतः एकस्मिन् व्यक्तौ रजोगुणः कार्यं कुर्वन् चेत्, तेन सह वयं रजोगुणेन वर्तितव्यः प्रसङ्गः आगच्छति। इदम् अतीव भयजनकम्। अतः रजोगुणाक्रान्तेन सह त्वं राजसः मा भव। तटस्थः दूरं तिष्ठ। तदा तस्य रजोगुणः स्वयमेव क्षीयते। कोपं कुर्वतां पुरतः मौनी भवेत् चेत् तेषां कोपः शीघ्रं विलीयते। एवं वयं एतेषां गुणानां प्रभावम् अभिज्ञाय सति अस्मदीयस्य जीवनस्य गतिः अपि अन्या भवति।\n\nउपर्युक्तं विषयं ज्ञात्वैव न पर्याप्तम्। एतान् त्रिगुणान् अतिक्रम्य स्थितः भगवान्। तं ज्ञातवति त्वं त्रिगुणान् अतिक्रम्य स्थातुं साहाय्यं भवति। तं भगवन्तं प्राप्तुम् अहम् एतेषां त्रिगुणानां प्रभावात् बहिः आगन्तव्यम् इति सत्यं वयम् अवगच्छेम। \"एतादृशस्य मनः मयि एव स्थिरीभवति, तेन अग्रे ते मामेव आगत्य मयि एव निवसन्ति\" इति वदति कृष्णः।\n\nअस्य श्लोकस्य अन्यत् अपि एकं मुखम् अस्ति। \"गुणेभ्यः अन्यं कर्तारं यदा द्रष्टा अनुपश्यति तदा सः 'नरः' भवति\"। अत्र \"गुणेभ्यः अन्यम्\" इत्युक्ते त्रिगुणाभिमानिनी, गुणशब्दवाच्या, श्री-भू-दुर्गानामिका महालक्ष्म्याः अपि अतीता एका शक्तिः। सः एव यथार्थः कर्ता। कः असौ? मुण्डकोपनिषदि उक्तं यथा --\n\n\"यदा पश्यः पश्यते रुक्मवर्णं कर्तारम् ईशं पुरुषं ब्रह्मयोनिम् ॥ (३-१-३)\"\n\nयः चतुर्मुखस्यापि पिता, यः चित्प्रकृतेः नियामकः, यः समस्तैः वेदैः वाच्यः -- सः एकः एव कर्ता। इदं ज्ञातवान् यथार्थः मानवः।\n\nसमस्ता आध्यात्मिकसाधना कर्तुं सौकर्ययुक्तं शरीरम् -- मनुष्यशरीरम् एव। तादृशं शरीरम् उपयुज्यमानः \"नरः\"। धर्मार्थकामेभ्यः विमोक्षणम् इत्युक्ते सत्त्वरजस्तमोगुणेभ्यः विमुच्य भगवन्तं प्राप्तुम्। इदं मनुष्यजीवनस्य लक्ष्यम्। \"एते त्रयः गुणाः मयि कार्यं प्रवर्तितवन्तः, अहम् अस्मात् प्रभावात् विमुच्य ऊर्ध्वम् आरोहेयम्\" इति जागृतिः विद्यते केवलं मनुष्ये। एतया जागृत्या \"मद्भावं सः अधिगच्छति\" -- तस्मिन् भक्तिज्ञाने मनसि पूरित्वा सः मोक्षं प्राप्नोति।",
  "14.20": "गुणान् एतान् अतीत्य त्रीन् देही देह समुद्धवान् ।\nजन्म मृत्यु जरा दुःखैः विमुक्तः अमृतम् अश्नुते ॥\n\nदेहे उद्भवत् एतान् त्रीन् गुणान् अतिक्रम्य सति जीवः जन्ममृत्युजरादुःखेभ्यः पारं गत्वा अमरः भवति।\n\nअस्मदीयं स्वरूपम् आच्छाद्य गाढं परिणामं ददन्तः एते त्रयः गुणाः वयम् अतिक्रमेम। [अत्र त्रिषु गुणेषु सत्त्वस्य अतिक्रमणम् इत्युक्ते स्थूलं सत्त्वम् अतिक्रम्य सूक्ष्मं सत्त्वं प्राप्तुम् इत्यर्थः।] एवं त्रीन् गुणान् अतिक्रम्य त्रिगुणातीतः भवति चेत्, तदा वयम् अस्य संसारस्य जन्ममृत्युरोगजरादुःखानि सर्वाणि अतिक्रम्य भगवन्तं प्राप्य अमराः भवितुं शक्नुमः। अनेन कदापि जन्ममृत्युरहितायाः आनन्दस्य स्थितेः मोक्षस्य प्राप्तिः सम्भवति।\n\nअत्र कृष्णः त्रिगुणम् अतिक्रान्ते सति मोक्षप्राप्तिः भवति इति उक्तवान्। एवम् उक्ते सति सहजतया अस्माकम् एकः प्रश्नः आगच्छति। तमेव प्रश्नम् अग्रिमे श्लोके अर्जुनः कृष्णस्य पुरतः स्थापयति।",
  "14.21": "अर्जुनः उवाच\n\nकैः लिंगैः त्रीन् गुणान् एतान् अतीतः भवति प्रभो ।\nकिम् आचारः कथम् च एतान् त्रीन् गुणान् अतिवर्तते ॥\n\nअस्माकं सर्वेषां कृते अर्जुनः कृष्णं पृच्छति -- \"हे प्रभो, त्रीन् गुणान् अतिक्रान्तः कश्चित् स्यात् चेत् तं कथम् अभिज्ञातव्यम्? तस्य लक्षणं किम्? तस्य आचरणं कीदृशं भवति? एतान् त्रीन् गुणान् सः कथम् अतिक्रामति?\" इति।\n\nअत्र अर्जुनः कृष्णं \"प्रभो\" इति सम्बोधितवान्। \"मम प्रश्नानाम् उत्तरं दातुं समर्थः त्वमेव\" इति ध्वनिः, पूर्णा शरणागतिः च अस्य सम्बोधनस्य पृष्ठे अस्ति। भगवान् अर्जुनस्य एतस्य प्रश्नाय अग्रिमेषु श्लोकेषु विस्तारेण उत्तरं दत्तवान्।",
  "14.22": "भगवान् उवाच\n\nप्रकाशम् च प्रवृत्तिम् च मोहम् एव च पांडव ।\nन द्वेष्टि संप्रवृत्तानि न निवृत्तानि कांक्षति ॥\n\nहे पाण्डव, लौकिकस्य ज्ञानस्य प्रकाशं वा, कर्मणः उत्साहं वा, भ्रान्तिं वा -- सत्सु द्वेष्टि न; असत्सु काङ्क्षति न।\n\nत्रिगुणान् अतिक्रान्तः यत् किमपि अनपेक्षितं आगच्छति चेत् तत् न द्वेष्टि; अपेक्षितं न आगच्छति चेत् तत् न अपेक्षते। \"किम् आवश्यकं किम् अनावश्यकम् इति मत्तः अधिकं भगवते ज्ञातम्। अतः अहं किमर्थं शिरः पीडयेयम्\" इति निर्लिप्तता तस्मिन् वर्तते। जीवने यत् आगतं तत् सः स्वागतं करोति। व्यासाः महाभारतस्य शान्तिपर्वणि एकां वाचम् उक्तवन्तः --\n\n\"एवम् अपि अशुभं कर्म न भूतं न भविष्यति ॥ (१२-३२-१८)\"\n\n\"अकर्तव्यं पूर्वं न अभवत्, अग्रे अपि न भविष्यति। यत् भवितव्यं तत् भवति एव। तत् 'न आवश्यकम्' इति द्विष्ट्वा किं फलम्?\" इति। अतः त्रिगुणम् अतिक्रान्तः आगते सति 'नावश्यकम्' इति न द्वेष्टि; अविद्यमानं न अपेक्षते। सर्वं निर्विकारतया पश्यन्, पूर्णः कुम्भः यथा न उच्छलति तथा जीवति।\n\nलोके केषाञ्चित् सत्त्वे आसक्तिः, अन्येषां केवलं प्रवृत्तिः। अन्येषां का अपि आसक्तिः न -- तमः तमः इति अज्ञात्वा तमस्येव जीवन्तः सन्ति। इदं सर्वसामान्यं दृश्यमानो विषयः। त्रिगुणम् अतिक्रम्य स्थिताः इदं दृष्ट्वा स्वमनः विकारं न कारयन्ति। \"तेषां तेषां गुणप्रभावानुगुणं सर्वं प्रवर्तते\" इति ज्ञात्वा तटस्थाः भूत्वा जीवन्ति। सत्यम् इति दृष्टं ते वदन्ति। परं कदापि वादविवादं न वर्धयन्ति। \"सर्वं भगवतः लीला, तेन कृता व्यवस्था\" इति सर्वं स्वीकुर्वन्ति। गीतायाः द्वादशाध्याये \"यथार्थभक्तः\" कीदृशः इति विवृण्वन् कृष्णः अस्मिन् श्लोके दत्तं विवरणम् एव दत्तवान्। अस्य अर्थः -- बाह्यगुणम् अतिक्रम्य स्थातुम् एव यथार्था भक्तिः।\n\nअत्र व्यासैः \"पाण्डव\" इति विशेषणं प्रयुक्तम्। पाण्डा इत्युक्ते ज्ञानी। पाण्डवः इत्युक्ते ज्ञानम् अभिज्ञाय नमन्तः। \"त्रिगुणातीतः भवितुं पूर्वं त्वं पाण्डवः भवेः\" इति सन्देशः अस्य विशेषणस्य पृष्ठे अस्ति।",
  "14.23": "उदासीनवत् आसीनः गुणैः यः न विचाल्यते ।\nगुणाः वर्तंत इति एवम् यः अवतिष्ठति न इंगते ॥\n\nउदासीनवत् आसीनः, गुणैः यः न विचाल्यते, \"गुणाः एव प्रवर्तन्ते\" इति ज्ञात्वा तूष्णीं तिष्ठति, तेषां तालेन न नर्तति।\n\nप्रापञ्चिकव्यवहारे एषः उदासीनवत् तिष्ठति। अस्मभ्यम् इष्टानिष्टे आगच्छतः त्रिगुणेभ्यः। त्रिगुणातीतः \"तथा भवतु-इदं भवतु\" इति न इच्छति। \"यथा भवितव्यं तथा भगवान् करोति\" इति विश्वासः तस्मिन् वर्तते। [अत्र एकं विषयं वयम् अवगन्तव्याः। जगति प्रवर्तमानाः घटनाः अस्मदधीनाः न। यत् वयं न भवितव्यम् इति मन्यामहे तत् भवेत्, यत् भवितव्यम् इति मन्यामहे तत् न भवेत्। एवं सति \"एवमेव भवितव्यम्\" इति व्यर्थं मनः उद्वेगे स्थापयितुं अर्थः नास्ति।] एवं जीवति सति -- अपेक्षितं न भवति चेत् क्रोधः नास्ति, भवति चेत् उत्प्लवः नास्ति। मनः प्रसन्नं भवति।\n\nइन्द्रियाणि गुणेषु वर्तन्ते, इन्द्रियाणां पृष्ठे गुणाः वर्तन्ते। परं त्रिगुणातीतः एतत् सर्वं ज्ञात्वा, शिरः अपीडयित्वा, यस्यां कस्यामपि क्रियायाम् अपि [तात्कालिकायामपि क्रियायाम्] चापल्यं विना जीवति।",
  "14.24": "सम दुःखसुखः स्वस्थः सम लोष्ट अश्म कांचनः ।\nतुल्य प्रिय अप्रियः धीरः तुल्य निंदात्म संस्तुतिः ॥\n\nसुखदुःखे समानतया पश्यति। स्वस्मिन्नेव स्वयं तिष्ठति। मृत्तिका, पाषाणः, कनकं च तस्य कृते समानानि। साधनया दृढीभूतस्य तस्य प्रियम् अपि एकम्, अप्रियम् अपि एकम्। निन्दा अपि एका, स्तुतिः अपि एका।\n\nत्रिगुणातीतः सर्वं सुखदुःखं समानतया पश्यति। यतः अस्मभ्यं उपरिदृष्ट्या सुखम् इति दृश्यमानं यथार्थतः सुखं भवितव्यम् इति नास्ति। तथैव दुःखमपि। इदं ज्ञातवति \"सर्वं भगवतः लीला\" इति भावना मनसि जायते। तदा सर्वं समानतया द्रष्टुं क्षमता अस्मासु वर्धते। वयं यथा नाटके प्रवर्तमानं दृश्यं प्रेक्षकवत् पश्यामः, तथा जगति प्रवर्तमानाः घटनाः प्रेक्षकवत् द्रष्टुम् अभ्यसनीयम्। तत् सुखमयं वा दुःखमयं वा भवतु -- वयं भगवतः प्रत्येकां क्रियाम् आस्वादयेम। जीवने आगच्छत् तात्कालिकं दुःखम् अस्मदीयस्य शाश्वतस्य सुखस्य कारणं भवति। परं तत् अस्मभ्यं ज्ञातं न भवति इत्येव। त्रिगुणातीताः इमं विषयम् अवगत्य सुखदुःखे समानतया पश्यन्तः आनन्देन जीवन्ति।\n\nपूर्वं स्थितप्रज्ञस्य भक्तानां च लक्षणं वदन् उक्ताः वाचः कृष्णः अत्र पुनः उच्चरति। त्रिगुणातीताय मृत्तिका, अमूल्यरत्नानि, कनकं -- सर्वं समानम्। तस्मै कनकं वा रत्नं वा अमूल्यम् इति न भासते। तस्मै अमूल्यं ज्ञानमेव। अस्मात् कारणात् सः धने, मुक्तारत्नेषु, कनके वा कस्यामपि अभिलाषां न दर्शयति। अतः सः सन्तोषेण जीवति। भागवतस्य तृतीयस्कन्धे आगच्छन् श्लोकः एवं वदति --\n\n\"यः च मूढतमः लोके यः च बुद्धेः परं गतः।\nतौ उभौ सुखम् एधेते क्लिश्यति अन्तरितः जनः ॥ (३-७-१७)\"\n\nएकः मूढः अन्यः ज्ञानी -- एतौ द्वौ लोके सुखेन जीवितुं शक्नुतः। यतः एतयोः धनस्य मोहः न भवति। परं एतयोः मध्ये स्थिताः -- जीवनस्य अर्थम् अज्ञात्वा मोहाय बलयः भूत्वा दुःखम् अनुभवन्ति।\n\nज्ञानिनः स्वजीवने इमं तत्त्वम् अवलम्ब्य कथं जीवन्ति इत्यस्य रामकृष्णपरमहंसानां जीवनचरितम् उत्तमं निदर्शनम्।\n\nअस्य श्लोकस्य अन्यमुखेन दृष्टे अस्मभ्यम् अन्यत् अपि विशिष्टं सन्देशं ज्ञायते। एकस्य यथार्थभक्तस्य (त्रिगुणातीतस्य) भगवद्भक्तिः तस्य जीवने आगच्छतां सुखदुःखानां प्रभावेण न परिवर्तते। दारिद्र्यं स्यात्, ऐश्वर्यं वा स्यात् -- एषः निरन्तरं भगवतः भक्तौ निरतः तिष्ठति। अस्य भक्तेः अन्येषां प्रीतिद्वेषौ कदापि मानदण्डः न। एवं त्रिगुणातीताः सर्वासु स्थितिषु समतया जीवन्ति।",
  "14.25": "मान अपमानयोः तुल्यः तुल्यः मित्र अरि पक्षयोः ।\nसर्वारंभ परित्यागी गुणातीतः सः उच्यते ॥\n\nसम्मानः अपमानः च तस्मै समानौ। मित्रबन्धुवर्गः शत्रुबन्धुवर्गः च समानौ। सः एतादृशेषु लौकिकेषु न प्रवर्तते। एतादृशः \"गुणातीतः\" इति उच्यते।\n\nत्रिगुणातीतान् एकः \"महान् ज्ञानी\" इति सम्मान्य वदेत्, अन्यः तं \"अर्धोन्मत्तः\" इति निन्देत्। परं एतयोः कस्यापि तेषु परिणामः न भवति। एतेषां न मित्राणि इति मोहः, न शत्रवः इति द्वेषः वा अस्ति। एते सर्वान् तेषां तेषां योग्यतानुगुणं पश्यन्तः, भगवद्भक्तेः विरुद्धायां कस्यामपि चलनक्रियायाम् अप्रवृत्ताः जीवन्ति। एते दीर्घकालस्य कस्यामपि योजनायां स्वात्मानं न नियोजयन्ति।\n\nएवं उपर्युक्तेषु चतुर्षु श्लोकेषु गुणातीतानां स्वभावस्य पूर्णं चित्रं कृष्णः सुन्दरतया वर्णितवान्। एतत्स्वभाववतः वयं गुणातीतान् इति अभिज्ञातुं शक्नुमः।\n\nअद्यपर्यन्तं त्रिगुणानां विषये त्रिगुणातीतानां स्वभावस्य विषये च विवृतवान् कृष्णः, अन्तिमयोः द्वयोः श्लोकयोः वयं त्रिगुणातीताः भवामः कथम् इति विवृणोति। अस्मदीया समस्ता प्रवृत्तिः एतेषां त्रयाणां गुणानां परिमितौ वर्तते सति त्रिगुणम् अतिक्रम्य स्थातुम् अस्मभ्यं कल्पनातीतम्। अतः अत्र कृष्णः त्रिगुणातीतान् भवितुम् अस्मभ्यं विद्यमानम् एकमात्रं मार्गं विवृणोति।",
  "14.26": "माम् च यः अव्यभिचारेण भक्तियोगेन सेवते ।\nसः गुणान् समतीत्य एतान् ब्रह्मभूयाय कल्पते ॥\n\nयः माम् अविच्छिन्नतया भक्त्या आराधयति, सः एतेषां गुणानां बन्धनं छित्त्वा, चेतनप्रकृतिवत् भगवतः भक्तेः पात्रं भवति[चेतनप्रकृतिं प्राप्नोति]।\n\nवयं स्वयं त्रिगुणातीताः भवेम इति यतेम चेत् तस्मिन् यत्ने वयं यशः द्रष्टुं न शक्नुमः। यतः अस्मदीयं सर्वं चिन्तनं त्रिगुणे एव भ्रमति। इदम् एकं चक्रभ्रमणम्। अस्मात् चक्रभ्रमणात् पारं कर्तुं सः चक्रधारी एव आगन्तव्यः। द्वादशस्तोत्रे उक्तं यथा -- \"त्रिगुणातीतविधारक परितः देहि सुभक्तिम्\" इति। त्रिगुणातीतान् धारणं कुर्वन् सः भगवान्। अतः त्रिगुणातीताः भवितुम् एकः एव मार्गः -- तस्मिन् भगवति शरणागतिः। लक्ष्मीसमेते तस्मिन् भगवति एकनिष्ठया अनन्यभक्तिं कुर्वतः -- लक्ष्म्याः पञ्चदशबन्धनरूपं वेष्टनं धारयित्वा प्रपञ्चं प्राप्तः जीवः, एतत् सर्वं बन्धनं त्यक्त्वा पुनः मातुः उत्सङ्गं प्राप्तुं शक्नोति।",
  "14.27": "ब्रह्मणः हि प्रतिष्ठा अहम् अमृतस्य अव्ययस्य च ।\nशाश्वतस्य च धर्मस्य सुखस्य ऐकांतिकस्य च ॥\n\nअक्षय्यायाः अपरिवर्तनीयायाः चित्प्रकृतेः अपि अहमेव आश्रयः आधारः च। सनातनाय धर्माय, केवलसुखमयाय मोक्षाय च तथैव।\n\nत्रीन् गुणान् अतिक्रम्य स्थिते सति जीवस्य सहजशाश्वतः धर्मः अभिव्यक्तः भवति। एतस्यां स्थितौ ब्रह्मतत्त्वस्य चित्प्रकृतेः उल्लेखं कुर्वन्ति। यतः एतेषु श्लोकेषु एव आचार्याणां सर्वस्य सिद्धान्तस्य सारः निहितः।\n\nपूर्वकाले एका सम्प्रदायः आसीत्। भोजनाय उपविष्टे सति, भोजनम् आरभ्य पूर्वं अस्य अध्यायस्य श्लोकम् उक्त्वा ततः भोजनं कर्तुम्। \"भोजनपत्रस्य पुरतः सम्पूर्णशास्त्रस्य सारं वयम् अनुसन्धानं कृतवन्तः\" इति भवति -- इदं तस्याः सम्प्रदायायाः पृष्ठे कारणम्। त्रयोदशाध्याये क्षेत्रस्य क्षेत्रज्ञस्य च विषये कृष्णः विवृतवान्। विश्वस्य विश्वस्य नियामकस्य भगवतः विषयम् एव अद्यापि स्पष्टतया, अन्येन मुखेन अस्मिन् अध्याये कृष्णः विवृणोति। प्रकृतिः प्राकृतं विश्वं, तत् विश्वम् अतिक्रमणस्य प्रकारः, अन्ततः च सम्पूर्णस्य तत्त्वज्ञानस्य संग्रहः अस्मिन् अध्याये अस्ति। अस्माभिः ज्ञातव्यं विशिष्टम् अवबोधसन्देशं कृष्णः अनेन अध्यायेन दत्तवान्।\n\nचेतनाचेतनं विश्वं \"क्षरम्\"। तस्मात् परस्तात् चित्प्रकृतिः \"अक्षरा\"। तस्मात् परस्तात् सर्वनियामकः भगवान् \"पुरुषोत्तमः\"। द्वादशाध्यायस्य आरम्भे विवृतवत् -- पञ्चदशभिः वेष्टनैः आवृतः षोडशः जीवः। एतानि पञ्चदश षोडशस्य परितः बध्नन्ती सप्तदशी श्रीलक्ष्मीः। अस्मात् वेष्टनात् विमोच्य अस्मभ्यं मोक्षं ददाति अष्टादशः पुरुषोत्तमः। [एतेषां पञ्चदशवेष्टनानां विस्तारेण ज्ञातुं प्रश्नोपनिषदः षष्ठं प्रश्नं पश्यतु। \"श्रद्धां खं वायुः ज्योतिः आपः पृथिवी इन्द्रियं मनः। अन्नम् अन्नादि वीर्यं तपः मन्त्राः कर्म लोकाः लोकेषु च नाम च ॥ (६-४)\" इति एतानि एव तानि पञ्चदश वेष्टनानि।]\n\n\"अष्टादश\" इति तत्त्वशास्त्रस्य समष्टिं अस्मत्पुरतः स्थापयत् एका संख्या। अस्मिन् अध्याये अष्टादशभिः श्लोकैः कृष्णः समस्तस्य शास्त्रस्य सारम् अस्मत्पुरतः उद्घाटितवान्। आगच्छत, इमम् अपूर्वम् अध्यायं कृष्णात् श्रुत्वा अवगच्छाम।",
  "15.1": "भगवान् उवाच\n\nऊर्ध्वमूलम् अधः शाखम् अश्वत्थम् प्राहुः अव्ययम् ।\nछंदांसि यस्य पर्णानि यस्तं वेद सः वेदवित् ॥\n\nउपरि स्थितः भगवान् प्रकृतिः च विश्वस्य मूलम्। अधः स्थितानि जीवजडानि तस्य शाखाप्रशाखाः। इदं सदा विद्यमानम्, [अश्वत्थम् -- अद्य यथा स्थितं श्वः न स्थास्यत्], [अश्वत्थः -- अश्ववत् निरन्तरं चलनशीलम्] अश्वत्थवृक्षः। वेदाः तस्य पर्णानि। एतत् यः जानाति सः वेदज्ञः।\n\nउपनिषदः सारः एव भगवद्गीता इति अस्य श्लोकस्य एव साक्ष्यम्। कठोपनिषदि एवम् उक्तम् -- \"ऊर्ध्वमूलः अवाक्शाखः एषः अश्वत्थः सनातनः\" इति। अत्र तत् \"ऊर्ध्वमूलम् अधःशाखम् अश्वत्थं प्राहुः अव्ययम्\" इति उक्तम्। इयं विषयगर्भिता पङ्क्तिः। अत्र एकैकस्मिन् पदे तत्त्वशास्त्रस्य अनेके विषयाः निहिताः।\n\nसरलतया इमां पङ्क्तिं भाषान्तरितं चेत् \"इदं विश्वम् एव एकः अश्वत्थवृक्षः। तस्य मूलम् अस्ति ऊर्ध्वम्, शाखाप्रशाखाः सन्ति अधः\" इति भवति। प्रथमदृष्ट्या इमां पङ्क्तिं दृष्ट्वा अस्मभ्यं किमपि न अवगम्यते। \"शीर्षासनं कुर्वन् अश्वत्थवृक्षः\" -- किमेतत्? तत्रापि अश्वत्थवृक्षम् एव कृष्णः किमर्थम् उक्तवान्? फलम् अपि न ददत्, पुष्पम् अपि न विसृजत्, गृहनिर्माणायापि असहायकस्य अस्य वृक्षस्य प्रस्तावः किमर्थम्? इदम् अवगन्तुं वयम् \"अश्वत्थ\" पदस्य पृष्ठे विद्यमानम् अर्थम् अन्वेष्टव्याः। उपरिदृष्ट्या अर्थात् एकैकशः तन्तुशः अन्तः प्रवेष्टव्यम्।\n\n(१) अश्वत्थम् इत्युक्ते स्थूलः अर्थः अश्वत्थवृक्षः। प्रपञ्चे विद्यमानेभ्यः सर्वेभ्यः वृक्षेभ्यः अयं वृक्षः भिन्नः। वायोः सूक्ष्मसञ्चारमपि विना सर्वे वृक्षाः स्तब्धाः सन्ति यदा, लघुः वायोः तन्तुः आगच्छति चेत् कोऽपि वृक्षः न चलति। परं अश्वत्थवृक्षस्य पर्णानि गिलि-गिलि इति चलितुम् आरभन्ते। अश्वत्थाय संस्कृते \"चलदलः\" इति अपि आह्वयन्ति। अर्थात् सदा चलनशीलैः पर्णैः युक्तः वृक्षः इत्यर्थः। इदमेव प्रपञ्चस्य अश्वत्थवृक्षस्य च साम्यम्। प्रपञ्चः अपि सदा चलनशीलः। सः सदा चलन् परिवर्तमानः च तिष्ठति।\n\n(२) अश्वत्थः -- अत्र अश्वः इत्युक्ते तुरगः। प्रपञ्चः अश्ववत् वर्तमानः। तुरगं निरीक्ष्य अस्मभ्यम् अयम् अर्थः ज्ञायते। अन्येभ्यः प्राणिभ्यः अश्वाय च एकः भेदः अस्ति। सर्वे प्राणिनः विश्रामकाले निश्चलाः स्थातुं शक्नुवन्ति। परं अश्वः एकम् अपि क्षणं निश्चलः न तिष्ठति। इदं जगदपि अश्ववत्। इदं कदापि स्थिरतया न तिष्ठति।\n\n(३) अ-श्वः-त्थ -- अत्र \"श्वः\" इत्युक्ते श्वः, \"त्थ\" इत्युक्ते विद्यमानम्। अश्वत्थम् इत्युक्ते \"न श्वः तिष्ठति\"। अद्य अस्ति परं श्वः स्थास्यति इति निश्चयः नास्ति। अर्थात् इदं प्रपञ्चं क्षणिकम्। कठोपनिषदि यमनचिकेतसोः \"यत् इच्छसि तत् सुखभोगं ददामि\" इति उक्ते सति, नचिकेतः वदति -- \"श्वोभावाः मर्त्यस्य यदन्तकैतत्... सर्वेन्द्रियाणां जरयन्ति तेजः\" इति (१-२६)। \"सदा परिवर्तमाने क्षणिके अस्मिन् प्रपञ्चे, अस्मान् भक्षयत् भोगं मह्यं न आवश्यकम्, तस्य बदले ज्ञानं देहि\" इति नचिकेतः याचते। परिवर्तनम् एव जगतः नियमः।\n\n(४) अश्वत्थस्य शास्त्रीयं निर्वचनार्थं (etymological meaning) पश्येम चेत् -- अशु-वा-त-थ। अत्र अशु-वा इत्युक्ते सर्वेभ्यः वेगेन गच्छत् -- सः भगवान्। अस्मात् कारणात् भगवन्तम् \"अश्वः\" इति अपि आह्वयन्ति। अश्वमुखेन हयग्रीवरूपेण भगवान् समस्तां वेदविद्यां प्रपञ्चाय दत्तवान्। सर्वं सर्वेभ्यः पूर्वं ज्ञातवान् भगवान् अस्मिन् जगति, अस्य अन्तः बहिः च नियमनाय \"अश्व\" नामकः भूत्वा उपविष्टः (त्थ)। एषः सम्पूर्णे प्रपञ्चे \"तत\" (पूर्णः) च अन्ततः सम्पूर्णं जगत् तस्मै \"थम्\" (थं आहारः -- सम्पूर्णं जगत् ग्रसितुं शक्तिः, इदं प्रलयस्य विवरणम्)।\n\nएतानि वयम् \"अश्वत्थ\" इति पदे द्रष्टुं शक्याः अर्थाः। एवं एकस्मिन् पदे अनेकान् विषयान् पूरयितुम् अन्यस्यां कस्यामपि भाषायां न शक्यम्। अस्मात् कारणात् संस्कृतं गर्भिणी (अर्थगर्भिता) भाषा इति वदन्ति। अत्र उक्तस्य वृक्षस्य कल्पना विवरणं च बाइबल्ग्रन्थेऽपि दृश्यते। तत्र ते वृक्षाय \"The Garden of Eden\" इति उक्तवन्तः। तत्र वदन्ति -- \"but of the tree of the knowledge of good and evil, you shall not eat of it; for in the day that you eat of it you will surely die\" इति। अर्थात् \"एषः वृक्षः फलं ददाति; एतत् फलं भक्षयेः चेत् त्वं मरिष्यसि\" इति। अत्र फलम् इत्युक्ते तत् कर्मफलम्। कर्मफलेच्छां (desire for fruit) कुर्वन् मृत्युरहितं मोक्षं न प्राप्नोति। सः निरन्तरं जन्ममृत्युचक्रे भ्रमति इति अस्याः पङ्क्त्याः अन्तरार्थः।\n\n\"प्राहुः अव्ययम्\" इत्यत्र \"प्राहुः\" इत्युक्ते ज्ञात्वा वदनम्। \"वेदकालीनाः ऋषयः इदं प्रपञ्चम् एकम् अश्वत्थम् इति ज्ञात्वा उक्तवन्तः\" इति वदति कृष्णः। \"इदं प्रपञ्चं नश्वरम्, एकदा नाशं गमिष्यत्\" इति उक्त्वा, तत्क्षणम् एव कृष्णः वदति -- \"इदम् अव्ययम्\" इति! अर्थात् नाशरहितम्! इदम् अवगन्तुं वयं समुद्रतीरं गत्वा उपविश्य तत्र आगच्छतीः तरङ्गान् निरीक्षेम। प्रत्येका तरङ्गा अपि अब्बरेण (घोषेण) आगच्छति। तत्र कापि तरङ्गा शाश्वती न। सर्वा तरङ्गा क्षणिका। परं समुद्रे तरङ्गारहितः क्षणः नास्ति। तत् अव्ययम्। तथैव एकः प्रपञ्चः नाशं गच्छति, अन्यः प्रपञ्चः जायते। प्रपञ्चः नाशं गच्छेत्, परं प्रपञ्चस्य प्रवाहः निरन्तरः। एकस्मात् प्रलयात् अनन्तरम् अन्या सृष्टिः; सृष्टेः अनन्तरं प्रलयः -- इदं निरन्तरम्। अतः प्रपञ्चः अव्ययः; जीवः अनादिः अनन्तः; जन्ममृत्यू निरन्तरे। जीवजडयोः समागमः जननम्; तयोः वियोगः मरणम्। अत्र सर्वं निरन्तरं परिवर्तनं पश्यति। समग्रतया इदं जगत् अक्षय्यः अश्वत्थः।\n\nअत्र \"अस्य वृक्षस्य मूलम् उपरि अस्ति (ऊर्ध्वमूलम्)\" इति उक्तम्। उपरि इत्युक्ते सर्वेभ्यः श्रेष्ठः भगवान्। अस्मै प्रपञ्चनामकाय वृक्षाय मूलं सः भगवान्। प्रपञ्चस्य मूले सर्वेभ्यः उच्चैः मातापितरौ भूत्वा लक्ष्मीनारायणौ स्तः। जडप्रकृतितः अयं वृक्षः विकसति। भगवतः चतुर्मुखब्रह्मा (महत्तत्त्वम्), वायुः, गरुडशेषरुद्राः (अहङ्कारतत्त्वम्), इन्द्रादयः देवताः, अवान्तरदेवताः, गन्धर्वाः, मनुष्याः, प्राणिनः, पक्षिणः -- एवम् एकस्य अनन्तरम् एका शाखाः सृष्टाः। एतत् सर्वं मिलित्वा एकः वृक्षः अभवत्। अत्र \"अधःशाखम्\" इत्युक्ते उपरितः अधः वर्धनम्। इदं देवतातारतम्यं सूचयति।\n\nवृक्षस्य शाखाप्रशाखानाम् अनन्तरं तस्य पर्णानि। \"अस्य वृक्षस्य पर्णानि एव वेदाः\" इति वदति कृष्णः। अस्माकं ज्ञातं यत् प्रपञ्चस्य द्वे मुखे। एकं नामात्मकं प्रपञ्चं, अन्यत् रूपात्मकं प्रपञ्चम्। अत्र रूपात्मकः प्रपञ्चः शाखाप्रशाखाः, नामात्मकः प्रपञ्चः वृक्षस्य पर्णानि। सर्वप्रथमं नामात्मके प्रपञ्चे सृष्टाः वेदाः। वस्तुनः एकं नाम दत्तवन्तः वेदे विद्यमानाः वैदिकशब्दाः।\n\n\"सर्वेषां त सः नामानि कर्माणि च पृथक् पृथक्।\nवेदशब्देभ्यः एव आदौ पृथक् संस्थाः च निर्ममे॥ (मनुस्मृतिः १-२१)\"\n\nवेदे यानि शब्दानि सन्ति तानि मूलतः भगवतः नामानि। तानि एव लोकाय उपयुक्तानि। एवं शब्दानां सृष्टिः अभवत्। तदेव छन्दः। वेदमन्त्राः वेदवाङ्मयानि एव अस्य वृक्षस्य पर्णानि।\n\nकिमर्थं वेदं पर्णाय समीकृतवन्तः इति चेत् -- एकः वृक्षः पुष्पफले दातुं तत्र फलप्रदत्वम् अस्ति पर्णे। तथैव अस्मभ्यम् अध्यात्मसाधनायाः फलं ददतां वेदाः। अस्मात् कारणात् वृक्षं विश्वेन समीकृतवान्, वृक्षस्य पर्णं वेदैः समीकृतवान् कृष्णः। प्रलयकाले वृक्षः नाशं गच्छति। परं वृक्षस्य पर्णं नाशं न गच्छति। अतः \"प्रलयकाले भगवान् वटपत्रस्य उपरि शयितः तिष्ठति\" इति वदन्ति। वेदः नित्यः, तस्य नाशः नास्ति। पत्रस्य उपरि भगवान् शयितः इत्युक्ते वेदवाच्यः शयितः इत्यर्थः। प्रलयकाले वेदाः आसन् इति एतेन ज्ञायते। अत्र अस्माकम् एकः प्रश्नः आगच्छेत्। यत्र किमपि वस्तु न आसीत् तत्र वेदाः आसन् इत्युक्ते किम् अर्थः? \"अग्निं मीळे पुरोहितम्...\" इत्यत्र अग्निः अपि नास्ति, पुरोहितः अपि नास्ति। एवं स्थिते कः वेदं वदति, वेदाः च प्रलयकाले कं वदन्ति?\n\nप्रलयकाले वेदेभ्यः भगवान् एकः एव अर्थः। अन्यः कोऽपि अर्थः नास्ति। अतः वेदे सर्वः शब्दः भगवन्तं वदति। \"नामानि सर्वाणि यम् आ विशन्ति तं वै विष्णुं परमम् उदाहरन्ति\" -- यस्मिन् सर्वाणि शब्दानि प्रवेशं कुर्वन्ति -- सः विष्णुः। सः सर्वशब्दवाच्यः। विष्णुः इत्युक्ते \"विशन्ति सर्वाणि नामानि अत्र\"। ऐतरेयारण्यके उक्तं यथा -- \"सर्वे घोषाः सर्वे वेदाः सर्वाः रचः एकैव व्याहृतिः...\" इति। प्रकृतौ सर्वाणि शब्दानि, सर्वे नादाः भगवन्तं वदन्ति। अतः प्रलयकाले वेदाभिमानिनी लक्ष्मीः वेदं गायति (श्रुतिगीतम्) भगवान् च शृणोति। इयं नामात्मकस्य प्रपञ्चस्य परिकल्पना।\n\nकृष्णः वदति -- \"अत्र उक्तं विषयं यः जानाति सः समस्तं वेदं ज्ञातवान्\" इति।",
  "15.2": "अधः च ऊर्ध्वं प्रसृताः तस्य शाखाः गुण प्रवृद्धाः विषय प्रवालाः ।\nअधः च मूलानि अनुसंततानि कर्म अनुबंधीनि मनुष्यलोके ॥\n\nत्रिगुणैः पुष्टाः अस्य शाखाः अधः ऊर्ध्वं च व्याप्य प्रसृताः। इन्द्रियविषयाः एव तासां नूतनपल्लवाः। तस्य मूलानि जीवानां कर्मानुगुणं मनुष्यलोकेऽपि अधः च व्याप्तानि।\n\nवृक्षस्य वर्णनम् अत्र अद्यापि विवृतम्। अस्य वृक्षस्य मूलानि अधोमुखं ऊर्ध्वमुखं च व्याप्तानि इत्युक्ते वटवृक्षस्य वर्णनम् उत्थितं दृश्यते। पञ्चमहाभूतरूपाः शाखाप्रशाखाः उपरितः अधःपर्यन्तं व्याप्ताः। अस्मदीयं शरीरं दृष्ट्वा -- अस्मदीये सहस्रारे भगवान् उपविष्टः। उपरितः अधःपर्यन्तं पञ्चमहाभूतानि, सत्त्वरजस्तमांसि इति त्रिगुणाः शाखाभूताः तिष्ठन्ति। अत्र शब्दः, स्पर्शः, रूपम्, रसः, गन्धः इति नूतनपल्लवाः इव। अर्थात् पाञ्चभौतिकाः विषयाः एव अस्य वृक्षस्य नूतनपल्लवाः। एते पल्लवाः अस्मभ्यं सर्वदा आकर्षणाः। भगवतः अनन्तं रूपम् उपरितः अधःपर्यन्तम् अस्मदीयेषु अङ्गाङ्गेषु पूर्णम्। तत्र अस्मदीयं कर्म अवलम्ब्य तस्य क्रिया। भगवतः मूलम् उपरि, परं सः उपरितः अधःपर्यन्तं व्याप्तः। एवं सः सर्वत्र व्याप्य तिष्ठति।",
  "15.3": "न रूपम् अस्य इह तथा उपलभ्यते न अंतः न च आदिः न च संप्रतिष्ठा ।\nअश्वत्थम् एनम् सु विरूढ मूलम् असंगशस्त्रेण दृढेन छित्त्वा ॥\n\n[एतयोः द्वयोः श्लोकयोः (१५.३ तथा १५.४) पदच्छेदः, अर्थः, विवरणं च सह अग्रिमे श्लोके (१५.४) दत्तम्।]",
  "15.4": "न रूपम् अस्य इह तथा उपलभ्यते न अंतः न च आदिः न च संप्रतिष्ठा ।\nअश्वत्थम् एनम् सु विरूढ मूलम् असंगशस्त्रेण दृढेन छित्त्वा ॥\n\nततः पदं तत् परिमार्गितव्यम् यस्मिन् गताः न निवर्तंति भूयः ।\nतम् एव च आद्यम् पुरुषम् प्रपद्ये यतः प्रवृत्तिः प्रसृता पुराणी ॥\n\nअनन्तरं तत् परतत्त्वम् अन्वेष्टव्यम्। तं प्राप्ताः पुनः न निवर्तन्ते। तेनैव एषा पुरातनी यात्रा आरब्धा। सर्वेषां पूर्वस्थं तं परमपुरुषं शरणं गन्तव्यम्।\n\nविश्वं यत्र इतः स्पष्टतया वर्णितम्, अन्यत्र तथा न वर्णितम्। अन्यत्र किञ्चित् किञ्चित् विवरणं द्रष्टुं शक्यते। परं कृष्णः अत्र पूर्णं विवरणं दत्तवान्। एतावत् विवृत्य कृष्णः एकां सावधानतां ददाति। कृष्णः वदति -- \"अस्मिन्नेव प्रपञ्चे स्थित्वा प्रपञ्चं पश्येम चेत् मया वर्णितम् अखण्डं दर्शनं न सम्भवति\" इति। अस्मभ्यं याम् अपि वस्तुं पूर्णतया समग्रतया ज्ञातुं न शक्यते एव। यतः सम्पूर्णं विश्वं अज्ञात्वा विश्वस्य एकः लघुः कणः न अवगम्यते। समुद्रतीरस्थः कश्चन दर्दुरः यथा समुद्रस्य गहनतां विस्तारम् अगाधतां च ज्ञातुं न शक्नोति, तथैव वयम् इदं प्रपञ्चं पूर्णतया ज्ञातुं न शक्नुमः।\n\nइदं प्रपञ्चं कथं सृष्टम्? तत् प्रलयकाले नाशं गत्वा कुत्र गच्छति? अस्मिन् आकाशे सर्वे ग्रहगोलाः निराधारतया कथं तिष्ठन्ति? वयम् एवं प्रश्नान् प्रस्थापयन्तः गच्छेम चेत् अस्मास्येतस्मै उत्तरं नास्ति। विज्ञानेऽपि अस्मै प्रश्नाय स्पष्टम् उत्तरं नास्ति। यतः विज्ञानं तिष्ठति केवलं कल्पनायाः गोपुरे।\n\nऋग्वेदे प्रलयकालस्य स्थितिं वर्णयन्तः वदन्ति -- \"नासदासीत् नो असदासीत् तदानीं नासीत् रजः नो व्योमा... (१०.१२९-१)\" इति। अर्थात् नेत्राभ्यां दृश्यमानम् अपि नास्ति; अदृश्यमपि नास्ति; इमे लोकाः एव प्रलयकाले न सन्ति इति। तर्हि किमपि विना इदं प्रपञ्चं सृष्टम्? छान्दोग्योपनिषदि \"किमपि विना सर्वं जातम्\" इति खण्डनं कुर्वन्तः वदन्ति -- \"कथम् असतः सत् जायेत... (६.२.२)\" इति। प्रलयकाले भगवान् प्रलयसमुद्रे शयितः तिष्ठति इति वयं सर्वे श्रुतवन्तः। इमे लोकाः एव न सन्ति यदा, कः समुद्रः? किं जलम्? इदं सर्वम् अवगन्तुं कथम्?\n\nसंक्षेपेण वक्तव्यं चेत् -- प्रलयकाले सर्वं भिद्यते परमाणुरूपं प्राप्नोति। एषः एव प्रलयसमुद्रः। अस्मिन् काले सर्वाणि जीवजातानि स्वस्थूलशरीरं त्यक्त्वा सूक्ष्मशरीरे स्वास्तित्वस्य अवबोधमपि विना भगवतः उदरे भवन्ति। सृष्टिकाले क्रमेण इदं प्रपञ्चं रूपं गृह्णाति। एतत् सर्वं कुर्वन् सः भगवान्। एतादृशं प्रपञ्चम् आदिमध्यान्तं किमपि अज्ञातं यावत् गभीरम्। अस्मात् वयं यत् ज्ञात्वा सर्वं ज्ञातुं शक्नुयाम तत् प्रथमं ज्ञातव्यम्। छान्दोग्योपनिषदि उद्दालकः गुरुकुले द्वादश वर्षाणि विद्याभ्यासं समाप्य आगत्य, स्वपुरतः अहङ्कारेण उपविष्टं पुत्रं श्वेतकेतुम् उद्दिश्य पृच्छति -- \"उत तम् आदेष्टं अप्राक्षीः; येन अश्रुतं श्रुतं भवति, अमतं मतं अविज्ञातं विज्ञातं... (६.१.३)\" इति। \"यत् ज्ञात्वा सर्वं ज्ञायते, तत् ज्ञातम्?\" इति। अत्र कृष्णः वदति -- \"यत् ज्ञात्वा सर्वं ज्ञायते तत् ज्ञातुं तस्यां परशक्तौ शरणं गच्छ\" इति। उपनिषदपि इदमेव वदति -- \"यस्मिन् विज्ञाते सर्वम् इदं विज्ञातं भवति। (शाण्डिल्य-२.२; मुण्डक १.१.३)\" इति।\n\nभगवन्तं ज्ञातवति सर्वं ज्ञातवत् इति सम्यक्, परं तम् अवगन्तुं क्रमः कः? अखण्डतया मूलितम् एतस्य वृक्षस्य मूलं प्राप्तुं कथम्? अस्मै कृष्णः वदति -- \"ज्ञानाख्यं खड्गं अनासक्त्या (detachment) उपासनया च सन्नयन्त्रे (शाणे) तीक्ष्णं कृत्वा, गभीरतया मूलितं वृक्षं छित्त्वा, परतत्त्वम् अन्विष्य\" इति। वयं यत्र गत्वा पुनः इह न आगन्तव्यं तत् अन्वेष्टव्यम्। भगवतः इतिमितिराहित्यम् अवगन्तुं ज्ञानम् एव अस्मै कुठारः। अत्रापि वयं स्वयं स्वप्रयत्नेन मूलं प्राप्तुं न शक्नुमः। सा शक्तिः अस्मासु नास्ति। अस्मात् कारणात् एकमेव मार्गः तस्यां परशक्तौ शरणागतिः। तस्य अनुग्रहेण एव वयं तं पुरुषोत्तमं प्राप्तुं शक्नुमः।",
  "15.5": "निर्मानमोहाः जित संग दोषाः अध्यात्म नित्याः विनिवृत्तकामाः ।\nद्वंद्वैः विमुक्ताः सुख दुःख संज्ञैः गच्छंति अमूढाः पदम् अव्ययम् तत् ॥\n\nअभिमानरहिताः, मोहरहिताः, इच्छाः त्यक्तवन्तः, सुखदुःखनामकस्य द्वन्द्वस्य सङ्कोचं पारं गताः -- एतादृशाः जाणाः (विदुषः) एतत् नाशरहितं स्थानं प्राप्नुवन्ति।\n\nकृष्णः अस्मिन् श्लोके उक्तः विचारः पूर्वेषु अनेकेषु अध्यायेषु तत्र तत्र आगतः, आगते सति वयं तद्विषये विशेषतया विश्लेषितवन्तः। सर्वं समष्ट्या अत्र कृष्णः उक्तवान्। भगवति शरणागतिं याचित्वा गच्छतः अस्मदीयस्य जीवनस्य आचरणं कीदृशं भवेत् इति अस्मिन् श्लोके विवृतम्। \"सर्वेभ्यः पूर्वं मानमोहौ त्यक्तव्यौ\" इति वदति कृष्णः। अर्थात् \"अहम्\" इति अहङ्कारं \"मम\" इति ममकारं च वयं प्रथमं त्यजेम। अस्मिन् प्रपञ्चम् आगच्छतोऽपि वयं नग्नाः, गच्छतोऽपि नग्नाः। एवं सति अत्र \"अहम्\", \"मम\" इति अहङ्कारे ममकारे च पतितुं कोऽपि अर्थः नास्ति। सङ्गदोषः अस्मासु अनेकं दुष्परिणामं जनयति। अतः वयं सङ्गदोषं जयेम। एकस्याः वस्तुनः अतिशयितः सम्पर्कः, तस्याम् अतिशयितः ममकारः कदापि न श्रेयस्करः। एवं निर्लिप्ततया जीवितुं चेत् प्रथमं वयम् आत्मानम् अध्यात्मचिन्तने नियोजयेम। इच्छाः त्यक्त्वा, सुखे प्राप्ते उत्प्लवं विना, दुःखे प्राप्ते अकुण्ठितं द्वन्द्वातीताः भूत्वा जीवितुं वयं शिक्षेम। पराजयः एव विजयस्य सोपानम्, दुःखसुखयोः सोपानम्। दिनरात्रौ स्वीकुर्वद्वत् कष्टसुखे वयं समानतया स्वीकुर्याम। लौकिकी अपेक्षा एव निराशायाः मूलम्। अस्याः पृष्ठं गताः जनाः अज्ञाः। ते स्वयमेव स्वजीवने समस्यां आनयन्ति। परं इदं रहस्यम् अवगतेभ्यः ज्ञानिभ्यः भगवतः लोकं निरायासेन प्राप्नुवन्ति -- इदं निश्चितम्।\n\nदेवस्य विषये देवं विश्वसतामपि अनेके अभिप्रायभेदाः सन्ति। प्रत्येकं स्वस्य विचारधारा एव सम्यक् इति भावना भवति। अस्मात् कारणात् अग्रिमेषु श्लोकेषु कृष्णः अस्मिन् विषये विवरणं ददाति। अत्र प्रस्तुतेषु श्लोकेषु विद्यमानः विचारः अस्मभ्यम् ईषत् अस्पष्टः इव भासेत। अस्मदीयायाः साधनायाः योग्यतायाश्च अनुगुणम् एते श्लोकाः उद्घाट्यन्ते। अत्र कृष्णः जीवजगद्भगवतां त्रिपुटीनां कल्पनां अतीव रोचकतया विवृतवान्।\n\nभगवतः चिन्तने सावधानता यस्य अस्ति तस्मै अस्य अध्यायस्य अग्रिमः भागः अतिमुख्यः भवति। अस्मदीये जीवने वयं कथं साधनां कुर्याम, कथं भगवतः चिन्तनं कुर्याम इत्यस्य समस्तं सारं कृष्णः अत्र विवृतवान्।",
  "15.6": "न तत् भासयते सूर्यः न शशांकः न पावकः ।\nयत् गत्वा न निवर्तंते तत् धाम परमम् मम ॥\n\nतत् सूर्यः प्रकाशयितुं न शक्नोति; चन्द्रः न शक्नोति; अग्निः अपि न शक्नोति। तत्र गताः पुनः न निवर्तन्ते। तत् मम श्रेष्ठं धाम।\n\nएतादृशमेव विवरणं कठोपनिषदि आगच्छति। तस्य सारम् अत्र कृष्णः उक्तवान्। कठोपनिषदि उक्तं यथा --\n\n\"न तत्र सूर्यः भाति न चन्द्रतारकं नेमा विद्युतः भान्ति कुतः अयम् अग्निः।\nतम् एव भान्तम् अनुभाति सर्वं तस्य भासा सर्वम् इदं विभाति॥ (१५)\"\n\n\"भगवन्तं सूर्यः न प्रकाशयति, चन्द्रिका वा अग्निप्रकाशः वा तं प्रकाशयितुं न शक्नोति\" इति वदति कृष्णः। अत्र वयम् उपासनां कुर्वतः भगवतः प्रतीकं कृष्णः उदाहरणतया गृहीतवान्। वयं सूर्ये गायत्रीम् उपासनां कुर्मः; चन्द्रमण्डलमध्यस्थं भगवन्तं धन्वन्तरौ पूजयामः; भूलोके भगवतः आराधनम् अग्निमुखेन। अत्र कृष्णः ददत् सावधानता -- एतत् सर्वं प्रकाशस्य प्रतीकम् एव। एतानि साक्षात् अस्मभ्यं भगवन्तं दर्शयितुं न शक्नुवन्ति। भगवन्तं द्रष्टुं वयम् अस्मदन्तः स्वरूपभूताम् अन्तर्ज्योतिं उपयोक्तव्याः। बृहदारण्यकोपनिषदि (४-०४) जनकयाज्ञवल्क्ययोः मध्ये संवादे इदं स्पष्टतया उद्घाटितम् --\n\n\"याज्ञवल्क्य, किं ज्योतिः अयं पुरुषः इति। आदित्यज्योतिः, सम्राट्... (४-२)\" -- अत्र जनकः याज्ञवल्क्यं पृच्छति -- \"अस्मिन् प्रपञ्चे जीवाः स्वकार्यनिर्वहणाय साहाय्यभूतं ज्योतिः किम्\" इति। अस्मै साक्षात् याज्ञवल्क्यः उत्तरति -- \"सूर्यस्य प्रकाशः\" इति।\n\n\"अस्तमिते आदित्ये याज्ञवल्क्य, किं ज्योतिः एव अयं पुरुषः इति। चन्द्रमा एव अस्य ज्योतिः भवति... (४-३)\" -- सूर्यप्रकाशे अविद्यमाने जीवाः केन प्रकाशेन स्वकार्यनिर्वहणं कुर्वन्ति इति पृष्टे -- याज्ञवल्क्यः वदति \"चन्द्रस्य प्रकाशेन\" इति।\n\n\"अस्तमिते आदित्ये, याज्ञवल्क्य, चन्द्रमसि अस्तमिते, किं ज्योतिः एव अयं पुरुष इति। अग्निः एव अस्य ज्योतिः भवति... (४-४)\"। सूर्यचन्द्रयोः अभावे कः प्रकाशः इति प्रश्नाय याज्ञवल्क्यः उत्तरति -- \"अग्नेः प्रकाशेन\" इति।\n\n\"अस्तमिते आदित्ये, याज्ञवल्क्य, चन्द्रमसि अस्तमिते, शान्ते अग्नौ किं ज्योतिः एव अयं पुरुष इति। वाक् एव अस्य ज्योतिः भवति... (४-५)\" -- सूर्यः, चन्द्रः, अग्निः, नक्षत्रम् -- यत् किमपि ज्योतिः अविद्यमाने जनाः कथं व्यवहरन्ति इति पृष्टे याज्ञवल्क्यः उत्तरति -- \"अन्योन्यं भाषमाणाः\" इति।\n\n\"अस्तमिते आदित्ये, याज्ञवल्क्य, चन्द्रमसि अस्तमिते, शान्ते अग्नौ, शान्तायां वाचि, किं ज्योतिः एव अयं पुरुष इति। आत्मा एव अस्य ज्योतिः भवति... (४-६)\" -- सर्वस्मिन् प्रकाशे अविद्यमाने, केनापि सह अविद्यमाने कः प्रकाशः अस्मभ्यं शक्तिः इति प्रश्नाय याज्ञवल्क्यः उत्तरति \"आत्मज्योतिः\" इति।\n\nउपरिदृष्ट्या एतं संवादं पश्येम चेत् अस्मभ्यं किमपि न ज्ञायते। परं अत्र प्राचीनैः कियान् विचारः पूरितः। वयम् अस्मदीयस्य अन्तरङ्गस्य आत्मज्योतिषः परिचयं विना केवलं बहिःप्रपञ्चे भौतिकप्रकाशे भगवन्तम् अन्विष्यन्तः तं न लभेमहि। तं कोऽपि भौतिकः प्रकाशः प्रकाशयितुं न शक्नोति। सः प्रकाशानां प्रकाशः। तं द्रष्टुं वयम् अस्मदीये स्वरूपे स्थितम् आत्मज्योतिः उपयोक्तव्याः। सूर्यं चन्द्रम् अग्निं च भगवतः प्रतीकतया उपयुज्य अस्मदीयम् अन्तरङ्गस्य ज्योतिः वयं जागरयेम।\n\nयस्मिन् स्थाने भगवान् सदा ज्ञानिभ्यः गोचरः भवति तत् \"परमधाम\" तदेव मोक्षः। तत्र सूर्यः वा चन्द्रः वा अग्निः वा प्रकाशः न। अस्मात् परमधामात् एव सूर्यचन्द्राग्नयः प्रकाशं प्राप्नुवन्ति। आत्मज्योतिः अभिज्ञाय, आत्मनि परमात्मानं दृष्ट्वा सः कदापि न निवर्तमानं परमधाम प्राप्नोति।",
  "15.7": "मम एव अंशः जीवलोके जीवभूतः सनातनः ।\nमनः षष्ठानि इंद्रियाणि प्रकृति स्थानि कर्षति ॥\n\nअस्मिन् देहे विद्यमानः नाशरहितः जीवः मम एव अंशः इव [मम भिन्नांशः; मम प्रतिबिम्बः]। सः शरीरे विद्यमानानि पञ्च ज्ञानेन्द्रियाणि षष्ठेन मनसा सह विषयान् प्रति प्रवाहयति।\n\nजीवः भगवतः सनातनः अंशः। अत्र \"अंशः\" इति द्विविधः -- स्वरूपांशः (ज्ञानानन्दस्वभावं विभजमानानि मत्स्यादीनि रूपाणि) भिन्नांशः च (प्रतिबिम्बभूतः जीवः)।\n\nजीवः प्रकृतौ विद्यमानं मनः पञ्च इन्द्रियाणि च स्वां दिशं कर्षति। भगवता सह जीवस्य सम्बन्धः शाश्वतः।",
  "15.8": "शरीरम् यत् अवाप्नोति यत् च अपि उत्कामति ईश्वरः ।\nगृहीत्वा एतानि संयाति वायुः गंधान् इव आशयात् ॥\n\nवास्तवतः जीवः इदं शरीरं प्रविशति त्यजति च यदा, सर्वशक्तः भगवान् एव एतानि इन्द्रियाणि नियन्त्रयन् सह आगच्छति; यथा वायुः पुष्पस्य गन्धं वहन् आगच्छति। [भगवान् एतस्य जीवस्य शरीरं प्रविशति निर्गच्छति च यदा, पञ्च ज्ञानेन्द्रियाणि षष्ठेन मनसा सह स्वाधीने स्थापयति। जीवाय विषयानुभवं ददत् एतानि सह नयति -- वायुः पुष्पात् गन्धं सह नयति यथा।]\n\nएषः श्लोकः भगवन्तं जीवं च द्वयमपि विवृण्वन् श्लोकः। अत्र अस्मभ्यम् ईषत् संदेहजनकां वाचं कृष्णः वदति। इमां वाचं भिन्नैः मुखैः स्पष्टतया अवगन्तुं चेत् सर्वं अस्पष्टम् इव भासते। उपरिदृष्ट्या पश्येम चेत् कृष्णः वदति -- \"सर्वे जीवाः मम एव अंशः\" इति। अत्र अंशः इत्युक्ते द्वे मुखे। एकं स्वरूपभूतः अंशः, अन्यत् भिन्नांशः। भगवान् ज्ञानस्वरूपः, अयं जीवः अपि ज्ञानस्वरूपः। भगवान् महाज्योतिः, जीवः ज्योतिषः स्फुलिङ्गः। भगवान् बिम्बः, जीवः प्रतिबिम्बः। इदं सनातनम् -- अनादि अनन्तं च वर्तमानम्। जीवः भगवतः प्रतिबिम्बः इत्युक्ते सः भगवतः भिन्नांशः। अस्मिन् जीवे \"जीवः\" इति धारणं कृत्वा श्वासयन् बिम्बरूपी भगवान्। तत् भगवतः स्वरूपांशः। एवं जीवः बहिः पञ्चभूतम् अनुभवत् पञ्च इन्द्रियम्, तस्य अनुभवम् अन्तरस्थाय जीवाय स्पर्शयत् षष्ठं मनः च, बिम्बरूपिणः भगवतः धारणे, मातुः गर्भे रूपायमानं स्थूलं शरीरं प्रविशति (भगवान् प्रवेशं कारयति)। एवं प्रविष्टाय जीवाय बिम्बरूपी भगवान् सर्वेन्द्रियेषु स्थित्वा इन्द्रियाभिमानिदेवतानां मुखेन अनुभवं ददाति। जीवः भगवतः अनुग्रहेण विषयान् अनुभवितुम् आरभते।\n\nएकस्य जीवस्य कृते समग्रतया त्रीणि शरीराणि सन्ति। एकं दृश्यं स्थूलं शरीरम्, तस्यान्तः सूक्ष्मं शरीरम् (अनिरुद्धशरीरम्) तस्यान्तः लिङ्गशरीरम्। एतत् स्थूलं शरीरं प्रविशत् सूक्ष्मशरीरिणे जीवाय सर्वाणि इन्द्रियाणि सन्ति। अतः अयं जीवः स्वपूर्वजन्मनः स्मृतिम् अन्तरङ्गे धृत्वा गर्भं प्रविशति। पूर्वजन्मनः अध्यात्मसाधना अस्मिन् सूक्ष्मे जीवस्य मनसि पूर्णतया अवशिष्यते। अस्मात् कारणात् \"अध्यात्मसाधना कदापि व्यर्था न भवति, सा सदा अस्माभिः सह मरणेऽपि सह आगच्छति\" इति उच्यते। यतः मरणं केवलं स्थूलशरीरस्य, न सूक्ष्मशरीरस्य। सम्मोहननिद्रायां (hypnosis) जीवस्य पूर्वजन्मनः विषयं ज्ञातुं शक्यं भवति अस्मात् कारणात्। अस्मभ्यं कदाचित् कमपि दृष्ट्वा पूर्वं अतीव परिचितः अस्माभिः सह स्थितः इव दृश्येत -- तस्मै पूर्वजन्मनः स्मृतिः अपि एकं कारणं स्यात्। इयं स्मृतिः अन्तः स्थिते सूक्ष्मशरीरे एव जागृता तिष्ठति, परं स्थूलेन्द्रिये इयं जागृता न भवति। एवं जीवः स्थूलं शरीरं प्रविशन् इन्द्रियाणि आकर्ष्य आगच्छति, गच्छन् अपि आकर्ष्य गच्छति। अस्यां क्रियायां जीवः स्वतन्त्रः न। एतत् कारयन् \"ईश्वरः\"। अत्र ईश्वरः इत्युक्ते सर्वसमर्थः भगवान् इत्यर्थः। शङ्कराचार्याः स्वभाष्ये \"ईश्वरः ईशनशीलः नारायणः\" इति उक्तवन्तः। अत्र \"ईशनशीलः\" इत्युक्ते सर्वसमर्थः इत्यर्थः।\n\nअस्मिन् श्लोके शब्दानां चमत्कारः अस्ति। \"अवाप्नोति\" इत्यत्र \"अव\" इति उपसर्गः। पञ्चदशभिः वेष्टनैः सह जीवः देहं प्रविशति इति जीवस्य बन्धनम्। इदम् एकविधम् \"अधःपातम्\"। परं इदम् ऊर्ध्वगमनाय पूर्वं जीवस्य अधःपातः। यतः जीवः मोक्षं प्राप्तुं इयं साधनाशरीरम् आवश्यकमेव। एतेनैव प्रकारेण जीवः देहं त्यक्त्वा बहिः गमनं \"उत्क्रामति\" इति उक्तम्। मृत्युः इत्युक्ते जीवं भगवान् स्थूलशरीरात् बहिः नयति। इदम् अमङ्गलं न। अस्मात् कारणात् अत्र \"उत्\" इति उपसर्गः प्रयुक्तः। इतः परं भगवान् जीवं नयत् एतत् \"संयाति\" इति उक्तम्। सम्- इत्युक्ते स्वयम्, स्वेच्छया, स्वातन्त्र्येण। सर्वं भगवतः अधीनम्, जीवः स्वतन्त्रः न, केवलं भगवान् स्वतन्त्रः इति इदं सूचयति। जीवाय जन्मनेऽपि, मरणायापि स्वातन्त्र्यं नास्ति। सर्वं भगवतः नियमनेन एव प्रवर्तते।\n\nजीवः स्वेन्द्रियैः सह भगवता सह अन्तः आगच्छति बहिः च गच्छति इति पुष्पसुगन्धस्य दृष्टान्तेन कृष्णः विवृतवान्। विकसितस्य पुष्पस्य सुगन्धः यथा अस्मदीयां नासिकां प्रविशति, तथा अस्य जीवस्य गतिः। तत् न दृश्यते। पुष्पसुगन्धस्य सूक्ष्माणवः अस्मदीयां नासिकां प्रविशन्ति इति अस्मभ्यं ज्ञायते केवलं सुवासनया, न भौतिकतया। जीवस्य एषा सर्वा गतिः अपि तथैव। सा न दृश्यते। इदमेव अद्यापि स्पष्टतया कृष्णः अग्रिमेषु त्रिषु श्लोकेषु विवृणोति।",
  "15.9": "श्रोत्रम् चक्षुः स्पर्शनम् च रसनम् घ्राणम् एव च ।\nअधिष्ठाय मनः च अयम् विषयान् उपसेवते ॥\n\nश्रोत्रे, चक्षुषि, त्वचि, जिह्वायाम्, घ्राणे, मनसि च स्थित्वा \"एषः\" विषयान् आस्वादयति।\n\nभगवान् अस्मदीये प्रत्येकस्मिन् इन्द्रिये नियामकः भूत्वा तत्तद्रूपेण स्थित्वा, विषयान् दुःखलेपं विना गृह्णाति, अस्मभ्यं च विषयस्य अनुभवं ददाति। एषः श्लोकः भगवन्तं वदन् अत्र \"उप-सेवते\" \"अधिष्ठाय\" इति द्वे विशिष्टे पदे प्रयुक्ते। उप इत्युक्ते उपरि-उच्चैः। वयं सुखदुःखे निमग्नाः विषयं भुञ्जीमहि, भगवान् तु सर्वम् अतिक्रम्य स्थित्वा दुःखलेपं विना सर्वम् अनुभवति।\n\nभगवान् तत्तद् इन्द्रिये विशेषरूपेण सन्निहितः भूत्वा नियमयति इति अत्र \"अधिष्ठाय\" इति पदं प्रयुक्तम्। एव च इत्येतौ द्वौ अस्मिन् श्लोके सह प्रयुक्तौ। इदं भगवतः विशिष्टं गुणं बिम्बयति। अ+ऊ+व+च = एवच (set of abbreviations, संक्षेपपदम्) -- अर्थात् केनापि दोषेण रहितः, सर्वगुणैः समुच्चितः ज्ञानानन्दमयः भगवान्।",
  "15.10": "उत् क्रामंतम् स्थितम् वा अपि भुंजानम् वा गुण अन्वितम् ।\nविमूढाः न अनुपश्यंति पश्यंति ज्ञान चक्षुषः ॥\n\nदेहं त्यक्त्वा गच्छन्तं, देहे स्थितं, वा शुभस्य सारम् आस्वादयन्तम् एनम् अज्ञाः ज्ञातुं न शक्नुवन्ति। ज्ञानचक्षुः उद्घाटितवन्तः ज्ञातुं शक्नुवन्ति।\n\nअस्मिन् श्लोके प्रयुक्तं \"गुणान्वितम्\" इति पदं स्पष्टतया अस्मभ्यं सूचयति -- इदं भगवन्तं वदत् श्लोकः इति। जीवं देहं प्रति आनयत्, जागरणस्वप्ननिद्रा इति त्रिषु अवस्थासु जीवाय विषयभोगं ददत् भगवान् -- स्वयं सदा शुभं भोगम् अश्नुवन्। देहात् बहिः गच्छन्, देहे स्थितः च -- सर्वं कारयन् सः भगवान्। सः अस्मदन्तः स्थितः अपि विमूढेभ्यः इदं न ज्ञायते। ज्ञानस्य नेत्रे उद्घाटितवन्तः एव इदं ज्ञातुं शक्नुवन्ति। अत्र कृष्णः \"विमूढाः\" \"ज्ञानचक्षुषः\" इति द्वे विशिष्टे पदे प्रयुक्तवान्। \"मूढाः\" इत्युक्ते सत्यं विपरीततया ज्ञातवन्तः। एते यथार्थज्ञानं विस्मृत्य विपरीतज्ञाने एव जीवन्ति। \"विमूढाः\" इत्युक्ते कदापि स्वदोषं न ज्ञात्वा, दोषम् एव सम्यक् इति सदा विपरीतज्ञाने जीवन्तः। एतेभ्यः भगवन्तं कदापि ज्ञातुं न शक्यते। भगवन्तं द्रष्टुं क्षमतां धारयन्तः ज्ञानचक्षुषः। अर्थात् शास्त्रं पठित्वा तेन अवबोधस्य अन्तर्नेत्रम् उद्घाटितवन्तः। एते भगवन्तं ज्ञातुं शक्नुवन्ति, स्वस्वरूपभूतेन नेत्रेण भगवन्तं द्रष्टुं च शक्नुवन्ति।",
  "15.11": "यतंतः योगिनः च एनम् पश्यंति आत्मनि अवस्थितम् ।\nयतंतः अपि अकृत आत्मानः न एनम् पश्यंति अचेतसः ॥\n\nप्रयत्नशीलाः साधकाः स्वान्तः स्थितम् \"एनम्\" पश्यन्ति। शुद्धिं अप्राप्ताः अज्ञाः प्रयतमानाः अपि एनं द्रष्टुं न शक्नुवन्ति।\n\nभगवन्तं द्रष्टुं केवलं शास्त्राभ्यासः न पर्याप्तः। ज्ञानं प्राप्य ज्ञानेन निरन्तरा साधना अपेक्षिता। ध्यानयोगेन निरन्तरं भगवन्तं द्रष्टुं यत्ने कृते -- आत्मसाक्षात्कारः भवति [ध्यानविषये षष्ठाध्याये वयं पर्याप्तं चर्चितवन्तः]। भगवन्तं द्रष्टुम् अस्मदीयेन प्रयत्नेन सह तस्य अनुग्रहः अपि आवश्यकः। अन्यथा येन केनापि महाप्रयत्नेन भगवन्तं द्रष्टुं न शक्यते। उदाहरणार्थं वयं क्षेत्रं सम्यक् कृष्ट्वा, संस्कृत्य, खादं दत्त्वा उत्तमश्रेणिकं बीजं वपेम, परं वृष्टिः सम्यक् न आगच्छेत् चेत्? अतिवृष्टिः आगत्य क्षेत्रं प्रवाहितं गच्छेत् चेत्? एतत् सर्वं दैवानुग्रहः। अस्मात् कारणात् निरन्तरप्रयत्नेन सह भगवति शरणागतिः अतिमुख्या। \"मम मनः स्वच्छं कुरु, स्वच्छे मनसि त्वं आगत्य निवस\" इति तं भगवन्तं प्रार्थनीयम्। शुद्धाय सात्त्विकाय मनसे \"वसुदेवः\" इति आह्वयन्ति। तस्मै वसुदेवाय दृश्यमानः भगवान् वासुदेवः। समस्तं शास्त्रं पठित्वापि अशुद्धमनस्कः स्यात् चेत् (अकृतात्मकः = अशुद्धबुद्धयः) -- यावान् अपि प्रयत्नः कृतः चेत् अपि भगवान् न प्रसीदति। एतदेव \"मडि\" इति उच्यते। मानसिकतया मडि (शुचिः) भूत्वा वयं प्रयत्नं कुर्याम। \"निरन्तरं ज्ञानपूर्वकप्रयत्नेन तव अत्यन्तसमीपस्थं, तव अन्तरङ्गे तव जीवस्वरूपे विद्यमानं भगवन्तं पश्य\" इति वदति कृष्णः। पूर्वस्मिन् श्लोके \"अयम् असौ\" (पुरतः स्थितः) इति उक्तवान् कृष्णः अत्र \"एनम्\" (तव अत्यन्तसमीपस्थम्) इति उक्तवान्। वयं भगवन्तं कुत्रापि अन्वेष्टुं न आवश्यकम्। सः अस्मदीये जीवस्वरूपे एव बिम्बरूपेण स्थितः। तस्य स्थानभूतम् अस्मदीयं जीवस्वरूपं ज्ञातवति सः अस्मभ्यं दृश्यते।",
  "15.12": "यत् आदित्यगतम् तेजः जगत् भासयते अखिलम् ।\nयत् चंद्रमसि यत् च अग्नौ तत् तेजः विद्धि मामकम् ॥\n\nसूर्ये स्थित्वा विश्वम् एव भासयत् प्रकाशः, चन्द्रे, अग्नौ च -- तत् मम एव प्रकाशः इति जानीहि।\n\nपूर्वं \"सूर्यः वा चन्द्रः वा अग्निः वा मां न प्रकाशयति\" इति उक्तवान् कृष्णः, अत्र \"सूर्यस्य प्रकाशनम्, चन्द्रस्य प्रकाशनम्, अग्नेः प्रकाशनम् -- सर्वं मत्तः\" इति वदति। सर्वेषां प्रकाशानां मूलं प्रकाशः भगवान्। प्रकाशस्य मूलानि -- सूर्यः, चन्द्रः, नक्षत्राणि, विद्युत्, तडित् च अग्निः। एतेभ्यः सर्वेभ्यः प्रकाशपुञ्जेभ्यः प्रकाशं ददत् सः भगवान्। अर्थात् \"सूर्यात् आरभ्य, चन्द्रतारकाणि, आकाशे प्रकाशमाना विद्युत्, वा प्रज्वलन् अग्निः वा -- एते सर्वे प्रकाशपुञ्जाः प्रकाशन्ते भगवन्नामकात् मूलप्रकाशात्। यत् प्रकाशः अस्मदीये स्वरूपे अणोरणीयतया स्थित्वा अस्मान् नयति, स एव प्रकाशः महतोमहीयतया सम्पूर्णं ब्रह्माण्डं प्रकाशयति। संक्षेपेण सर्वेषां प्रकाशानां मूलं तेजः सः भगवान्। उपनिषत्कारः एतादृशस्य महाप्रकाशस्य विषये विवृण्वन्तः वदन्ति -- \"...यदेतत् विद्युतः व्यद्युतत् आ इति\" इति (केन-४.४)। ते अत्र एतं प्रकाशं \"आ-इति\" इति वदन्ति। अर्थात् इदम् एकं \"विस्मयम्\" इत्यर्थः। ज्ञातुं यावत् आश्चर्यम्, ज्ञातस्य अनन्तरम् आनन्दः।\n\nउपासनादृष्ट्या एतं श्लोकं पश्येम चेत् -- सूर्ये विद्यमानं तेजः नारायणस्य तेजः, चन्द्रे विद्यमानं तेजः धन्वन्तरेः तेजः, अग्नौ विद्यमानं तेजः परशुरामस्य तेजः। एवं प्रत्येकस्य प्रकाशस्य मूलं प्रकाशः भगवान् इति वयम् अनेन श्लोकेन उपासनां कर्तुं शक्नुमः।",
  "15.13": "गाम् आविश्य च भूतानि धारयामि अहम् ओजसा ।\nपुष्णामि च ओषधीः सर्वाः सोमः भूत्वा रसात्मकः ॥\n\nभूमिम् अन्तः प्रविश्य जीवान् अहम् एव स्वसामर्थ्येन धारयामि। अमृतरसमयः चन्द्रः भूत्वा [सौम्यरूपत्वात् \"सोम\" नामकः भूत्वा चन्द्रे स्थित्वा] सर्वाणि ओषधीः वर्धयामि।\n\nअत्र गाम् इत्युक्ते \"पृथिवी\"। इयं भूमिः आकाशे निरालम्बा स्थातुं संकर्षणशक्तिरूपेण (शेषशक्तिः, आकर्षणशक्तिः, Gravitational force) भूमिं धारयन् भगवान्। इदं भगवतः वराहावतारं विवृणोति। अधः पतित्वा नाशं गन्तुम् उद्यताम् इमां भूमिं भगवान् वराहरूपेण उत्थाप्य धृतवान् -- इयं कथा। अत्र भूमेः अधःपतनम् इत्युक्ते तस्याः स्वकक्षायाः च्युतिः। भूमिः कक्षां त्यजेत् चेत् सा क्षणार्धेन नाशं गच्छेत्। तामसलोकस्य दैत्यः हिरण्याक्षः भूमिं कक्षातः विचालितवान्। \"मह्यं स्थातुं स्थानं दण्डं च दत्ते सति अहं भूमिं कक्षातः विचालयितुं शक्नोमि\" इति न्यूटन् उक्तवान् इति वयम् अत्र स्मरेम। एवं तामसलोकस्य दैत्येन भूमिं कक्षातः विचालिते सति, भगवान् तां पुनः कक्षायां स्थापयित्वा रक्षितवान्। वेदकालिकेभ्यः ऋषिभ्यः \"भूमिं धारयन् भगवान् वराहरूपेण दृष्टः\"। अस्मात् कारणात् भूमिं धारयतः भगवतः रूपं वराहरूपेण वयं पश्यामः। वरश्रेष्ठः। गायत्र्यां \"वरेण्यम्\" इत्यत्र भूमिं धारयतः भगवतः वराहरूपस्य चिन्तनम् अस्ति। रूसी वैज्ञानिकः वेलिकोव्स्की (Velikovsky) स्वस्मिन् \"Worlds in Collision\" इति ग्रन्थे वदति -- \"वैज्ञानिकदृष्ट्या द्विवारं भूमिः स्वकक्षातः च्युता इति सत्यम्, परं अस्मभ्यम् इदं किमर्थम् इति न ज्ञातम्\" इति। सः तत्र भागवतम् उल्लिख्य वदति -- \"भारतस्य ऋषयः इमं विषयं ज्ञातवन्तः, एका दुष्टशक्तिः भूमिं कक्षातः विचालितवती, अन्या दैवीशक्तिः तां पुनः कक्षायाम् अस्थापयत्\" इति। इदमेव अस्मिन् श्लोके कृष्णः \"गां धारयामि\" इति उक्तवान्। भूमिं धारयन् भगवान् भूमेः अन्तः स्थित्वा, प्रत्येकं जीवजातस्य अन्तः स्थित्वा अस्मान् रक्षति। उपनिषदि उक्तं यथा -- \"यः पृथिवीम् अन्तरः यमयति एषः तव आत्मा अन्तर्यामी अमृतः\" इति। अर्थात् \"पृथिव्याः अन्तः स्थित्वा भगवान् अस्मान् रक्षति अपि, तत् अस्मभ्यं न ज्ञातम्\" इति। एवं भूमिं धारयित्वा रक्षन्तं भगवतः शक्तिं अत्र \"ओजः\" इति उक्तम्। अर्थात् सर्वाणि विघ्नानि निगृह्णती शक्तिः।\n\nअस्मासु सन्ध्यावन्दनं कुर्वतां \"मनसः स्नानम्\" इति एका क्रमः अस्ति। अस्मदीये सहस्रारे चन्द्रमण्डले उपविष्टस्य धन्वन्तरेः हस्ते विद्यमानात् अमृतकलशात् अमृतधारा अधः प्रवहन्ती -- वयं मानसिकतया अनुभूय स्नानं कुर्मः। अत्र चतुर्विंशतिवारं \"ॐ-वं\" इति उक्त्वा तस्मात् चन्द्रमण्डलात् अमृतद्रवः प्रवहित्वा वयम् अन्तः शुद्धाः भवामः। इदं भगवति मनः एकाग्रीकृत्य, मानसिकतया अनुभूय कृतं चेत् मनः शुद्धं भवति। अस्मासु विद्यमानः सर्वेभ्यः महान् मलः अस्मन्मनसि विद्यमानः पापपुरुषः। दुष्टभावना, दुष्टचिन्ता, ईर्ष्या -- एवं सर्वं पूरितम् अस्मन्मनसि। तत् गन्तव्यं चेत् एतस्मात् चन्द्रमण्डलस्य अमृतकलशात् आगच्छता अमृतद्रवेण स्नानं कर्तव्यम्। इदमेव कृष्णः अत्र \"सोमः भूत्वा रसात्मकः\" इति उक्तवान्। भगवान् सोमरूपेण चन्द्रे पूर्णः। सः जलस्य नियामकः चन्द्रे सोमः भूत्वा, वनस्पतिषु जीवरसं पूरितवान्। वयं यत् भक्षयित्वा जीवामः, तं वृक्षं रक्षित्वा वर्धयन्ती -- चन्द्रे पूर्णा सोमरूपिणी भगवत्शक्तिः।",
  "15.14": "अहम् वैश्वानरः भूत्वा प्राणिनाम् देहम् अश्रितः ।\nप्राण अपान समायुक्तः पचामि अन्नम् चतुर्विधम् ॥\n\nअहं \"वैश्वानरः\" भूत्वा जीवानां देहान्तः स्थित्वा प्राणापानाभ्यां सह [भक्षणीयं, चोष्यं, लेह्यं, पेयं] चतुर्विधम् आहारं पाचयामि।\n\nअत्र \"पचामि अन्नं चतुर्विधम्\" इत्युक्ते चतुर्विधम् अन्नं पाचयामि इत्यर्थः। अन्नम् इत्युक्ते सर्वप्रकारः आहारः। \"प्राणिनां देहम् आश्रितः\" इत्युक्ते प्राणिभिः भक्षणीयः आहारः इत्यर्थः। प्राणिनाम् आहारं चतुर्धा विभक्तुं शक्यते -- भक्ष्यं, भोज्यं, लेह्यं, चोष्यं च। भक्ष्यम् इत्युक्ते चर्वयित्वा भक्षणीयम्; भोज्यम् इत्युक्ते अचर्व्य निगीर्य भक्षणीयम्। लेह्यम् इत्युक्ते लिह्य भक्षणीयम्; चोष्यम् इत्युक्ते पानयोग्यम्। एतत् चतुर्विधम् \"अन्नं\" सेवमानानां सर्वेषां जीवानां जठरे अग्निरूपेण स्थित्वा, चतुर्विधम् अन्नं त्रिविधतया (सूक्ष्ममध्यस्थूलतया) विभज्य, देहाय पोषणं दत्त्वा अस्मभ्यं जीवितुं व्यवस्थां कारयन् वैश्वानररूपी भगवान्।\n\nवयं सेवमानः आहारः मृत्तिकाजलाग्नीनां मिश्रणम्। आहारे विद्यमानायाः मृत्तिकायाः सूक्ष्मः भागः मस्तिष्काय, मध्यमः भागः मांसत्वचे, स्थूलः भागः मलतया विसृज्यते। तथैव जलस्य सूक्ष्मः भागः श्वासरूपेण, मध्यमः भागः रुधिररूपेण, स्थूलः भागः मूत्रतया विनियुज्यते। अग्नेः सूक्ष्मः भागः वाक्शक्तितया, मध्यमः भागः अस्थिमज्जातया, स्थूलः भागः दन्तास्थितया विनियुज्यते। एवं कनकखनितः कनकं पृथक्करणात् कठिनतरं कार्यम् अस्मदन्तः स्थित्वा व्यवस्थितरीत्या कृत्वा, अस्मभ्यं जीवनं ददत् सः भगवान्। भगवतः अस्य कार्याय सेवकौ प्राणापाननामकौ प्राणदेवस्य द्वे रूपे। कठोपनिषदि उक्तं यथा --\n\n\"ऊर्ध्वं प्राणम् उन्नयति अपानं प्रत्यगस्यति।\nमध्ये वामनम् आसीनं विश्वे देवाः उपासते ॥ (२-२-३)\"\n\nअत्र प्राणापाननामकौ प्राणदेवस्य द्वे रूपे, मध्ये (हृदये) भगवतः वामनरूपम्। इदं पञ्चरूपिणः भगवतः उपासनातः भिन्ना उपासना। हृदयस्य मध्ये स्थित्वा, वयम् उक्तम् आहारं जीर्ण्य जीवनं ददत् वामनरूपी भगवान्। अस्मिन् मन्वन्तरे वामनः देवेन्द्रस्य रक्षकः \"उपेन्द्रः\"। अतः अस्मदीये हृदये विद्यमानस्य वामनरूपिणः भगवतः उपासना अस्मिन् मन्वन्तरे अतिमुख्या भवति। अस्मदन्तः वामनरूपी एषः भगवान् एव त्रिविक्रमः भूत्वा भूमिव्योम्नोः पूर्णः तिष्ठति।",
  "15.15": "सर्वस्य च अहम् हृदि सन्निविष्टः मत्तः स्मृतिः ज्ञानम् अपोहनम् च ।\nवेदैः च सर्वैः अहम् एव वेद्यः वेदांतकृत् वेदवित् एव च अहम् ॥\n\nसर्वस्य हृदये अहं स्थितः। स्मृतिः, ज्ञानम्, विस्मृतिः च सर्वं मम दानम्। सर्वैः वेदैः ज्ञातव्यः अहमेव। वेदान्तसूत्राणां रचयिता, वेदानां मर्म ज्ञातवान् अहमेव।\n\n\"सर्वस्य च अहं हृदि\" -- भगवान् अहंशब्दवाच्यः भूत्वा अस्मदन्तः पूर्णः। अस्मदीये बहिः स्थितस्य भगवतः रूपाय \"अहः\" इति, अस्मदन्तः तस्य रूपाय \"अहम्\" इति उच्यते। अस्मदन्तः स्थितः भगवान् सदा अस्माभिः सह स्थित्वा अस्मान् रक्षति। मरणे स्थूलं शरीरं त्यक्त्वा बहिः गच्छतोऽपि भगवान् अस्माभिः सह भवति। सः अस्मान् एकम् अपि क्षणं न त्यजति। तस्य स्थानम् अस्मदीये लिङ्गशरीरे विद्यमानः स्वरूपभूतः आत्मा। एषः आत्मा एव \"अहम्\"। एतादृशस्य भगवतः प्रज्ञा अस्मासु स्यात् चेत् \"अहं कृतवान्\" इति अहङ्कारः अस्मान् न पीडयति।\n\nकठोपनिषदि उक्तं यथा -- \"अङ्गुष्ठमात्रः पुरुषः अन्तरात्मा सदा जनानां हृदये सन्निविष्टः...\" (२-३-७)। सर्वेषां जीवानाम् अन्तः अङ्गुष्ठमात्रः भूत्वा सदैव दुःखलेपं विना निर्लिप्तः भगवान् पूर्णः। मध्वाचार्याः कठोपनिषदे भाष्यं लिखन्तः वदन्ति --\n\n\"नमः भगवते तस्मै सर्वतः परमाय ते।\nसर्वप्राणिहृदिस्थाय वामनाय नमः नमः ॥ (सर्वमूलम्)\"\n\nअत्र सर्वेषां हृदयान्तर्यामी भगवतः रूपं \"वामन\" रूपम् इति सूचना अस्मभ्यं लभ्यते। अतः उपासनायां वयम् अस्मदीयम् अन्तर्गतं भगवन्तं वामनरूपेण उपासनां कुर्याम।\n\n\"मत्तः स्मृतिः ज्ञानम् अपोहनम्\" -- अस्मभ्यं स्मरणशक्तिं ददत् सः भगवान्। ज्ञानम् आगच्छत् अपि भगवतः, आगतं ज्ञानं स्मृतौ तिष्ठत् अपि भगवतः। केनोपनिषदि उक्तं यथा -- \"अथाध्यात्मं यत् इदं गच्छतीव च मनः अनेन च एतत् उपस्मरति अभीक्ष्णं संकल्पः\" (४-५)। अस्मभ्यं स्मृतेः शक्तिं ददतः भगवतः अनिरुद्धरूपस्य उपासना इयम्। यथा स्मृतेः शक्तिं ददाति तथा विस्मरणं कारयन् अपि सः एव! कदाचित् अपरोक्षज्ञानिनोऽपि भगवन्तं विस्मरन्ति (भगवान् विस्मारयति)। अस्मै दृष्टान्तः भागवते आगच्छन्ती गर्गाचार्यस्य कथा। भगवते \"कृष्णः\" इति नामकरणं कृत्वा, कृष्णस्य भक्ताः स्थिताः गर्गाचार्याः, केनापि दुःसन्दर्भे सर्वं विस्मृत्य \"कृष्णं घातयन् पुत्रः जायताम्\" इति तपः कुर्वन्ति! कीदृशः विपर्यासः। परं एतत् सर्वं तस्य भगवतः लीला। तस्य लीलायाः पृष्ठे विद्यमानं द्वेषः न, केवलं कारुण्यम्।\n\nकृष्णः वदति -- \"समस्तवेदैः ज्ञातव्यः अहम्\" इति। वेदस्य प्रत्येकं पदं भगवत्परम् इति ब्रह्मसूत्रं स्पष्टतया वदति। वेदान्तम् इत्युक्ते उपनिषद् इति केचन वदन्ति। परं वेदान्तम् इत्युक्ते \"वेदस्य निर्णयः\" -- सः एव ब्रह्मसूत्रम्। इदं समस्तं वेदं समन्वयं कृत्वा वदत् ग्रन्थम्। वेदः अनादिनित्यः, वेदस्य मर्म पूर्णतया ज्ञातवान् सः भगवान् एकः एव।\n\n\"वेदैः च सर्वैः अहम् एव वेद्यः\" इत्यत्र च-कारं एव-कारं च प्रयुक्तम्। अत्र च-कारेण इयं पङ्क्तिः द्वे सन्देशे ददाति। एकं मुख्यार्थः अन्यत् अमुख्यार्थः। \"भगवान् वेदैरेव वेद्यः\" इति मुख्यार्थः। पञ्चमवेदनामकानि पुराणग्रन्थानि, वेदान्तः, महाभारतम्, रामायणम् इत्यादिभिः अपि भगवान् वेद्यः -- इति अमुख्यार्थः। इतोऽपि स्मृतयः सन्ति, परं ताः प्रमाणम् इति स्वीकर्तुं न शक्यते। यतः स्मृतयः तत्तत्कालिकैः राजभिः स्वविद्वद्भिः तत्तत्कालानुगुणं लेखिताः, ताः संविधानवत्। तत्र तत्तत्कालिकः समाजधर्मः सह आगतत्वात् ता सार्वकालिकं सत्यम् एव इति नास्ति। सार्वकालिकं सनातनं सत्यं वेदः एव।\n\n\"अहम् एव वेदः\" इत्यत्र वेदैः ज्ञायमानः अहम् एकः एव इति मुख्यार्थः। अमुख्यतया इदं भगवतः पारम्याय पोषकान् विषयानपि वदति। अत्र \"वेदैः ज्ञायमानः अहम् एकः एव\" इति उक्त्वा \"बहुदेवतावादं\" कृष्णः त्यक्तवान्। भगवान् एकः एव इति वेदः सारं वदति। अस्मै अन्यत् प्रमाणं न आवश्यकम्।\n\n\"वेदान्तकृत् वेदवित् एव च अहम्\" इत्यत्र कृष्णः \"वेदस्य पूर्णः अर्थः ज्ञातः मह्यम् एव\" इति उक्तवान्। भागवते आगच्छन्त्यां उद्धवगीतायां कृष्णः वदति --\n\n\"किं विधत्ते किम् आचष्टे किम् अनूद्य विकल्पयेत्।\nइति अस्याः हृदयं लोके न अन्यः मत्वेद कश्चन ॥ (११-२१-४२)\nमां विधत्ते अभिधत्ते मां विकल्प्य अपोह्यते तु अहम्।\nएतावान् सर्ववेदार्थः शब्दः आस्थाय माम् भिदाम्।\nमायामात्रम् अनूद्य अन्ते प्रतिषिध्य प्रसीदति ॥ (११-२१-४३)\"\n\nवेदस्य प्रत्येकं शब्दः भगवन्तं वदति इति अत्र कृष्णः स्पष्टतया विवृतवान्। परं वयं वेदम् उपरिदृष्ट्या पश्येम चेत् -- वेदः \"कर्मबोधकः\", प्रत्येकं पदं \"कर्मवाचकं\" पदम् इति भासते। परं तथा ज्ञातुं भ्रान्तिः। क्रियां कृत्वा मनः स्वच्छं भवति, शुद्धाय मनसे ज्ञानं शीघ्रं प्राप्यते। अनेन भगवन्तं ज्ञातुं शक्यं भवति। अतः वेदे आगच्छत् प्रत्येका क्रिया वदति भगवन्तम् एव। वेदः एकत्र इमां क्रियां कुरु इति, अन्यत्र इमां क्रियां मा कुरु इति वदति। उदाहरणार्थं \"सोमपानं कुरु, सुरापानं मा कुरु\" इति वेदः वदति। अस्य अर्थः -- सोमपानम् अध्यात्मचिन्तनाय मनः सज्जीकरोति, तेन भगवन्तं ज्ञातुं शक्यते; सुरापानं कृतं चेत् तेन बुद्धिः नश्यति, तत् भगवतः दूरं करोति। एवं वेदे उक्ता प्रत्येका क्रिया अन्ततः भगवन्तम् एव वदति। केषुचित् स्थानेषु वेदः सृष्टिसंहारयोः विषये वदति; सृष्टेः क्रमं वदति। इदं \"भगवान् एवं सृष्टिक्रियां करोति\" इति भगवन्तमेव वदन्त्यः पङ्क्तयः।\n\nवेदसूक्तानि क्वचित् क्वचित् भिन्नानां देवतानां नामानि वदन्ति। क्वचित् अग्निः, अन्यत्र इन्द्रः, अपरत्र सरस्वती, इत्येवम्। अत्र अस्मभ्यम् इदं बहुदेवतावादम् इव भासेत। परं कृष्णः उक्तवान् \"अभिधत्ते माम्\" इति। उदाहरणार्थं \"आत्मनः आकाशः सम्भूतः\"। अहङ्कारतत्त्वात् आकाशदेवता -- गणपतिः जातः। आकाशसृष्टिः इत्युक्ते विद्यमाने अन्तरिक्षे एकम् आवरणं (वातावरणम्) सृष्टिः। तस्याः अभिमानी देवता भूत्वा गणपतिः जातः। गणपतेः अन्तः आकाशे पूर्णः भगवान् -- आकाशनामकः अवतीर्णः। एवं प्रत्येकं वेदश्लोकम् अपि अन्ततः वदति भगवन्तम्।\n\nवेदे आगच्छन्ति प्रत्येकानि शब्दानि भगवन्तं कथं वदन्ति इत्यस्य उदाहरणम् अत्र द्रष्टुं शक्यते। उदाहरणम् -- 'अग्निः'। अ-ग-नि = अग्निः। चलनरहितस्य वस्तुनः (अग) चलनं ददत् -- अग-नि। भगवान् सम्पूर्णाय विश्वाय चलनं ददाति अतः सः अग्निः।\n\nवेदे विद्यमानम् एकैकम् अक्षरम् अपि भगवतः नाम। उदाहरणार्थं 'अ'। अ -- अजः (जन्मरहितः); अ -- अनन्तः (मृत्युरहितः)। तथा 'आ'। आ -- आदिः (सर्वेभ्यः पूर्वः); आ -- आनन्दः; इत्यादि। वराहपुराणे वेदव्यासाः वदन्ति -- \"यावन्ति पदानि तावन्ति हरिनामानि पदानि नासंशयः\" इति। ऋग्वेदे चतुर्लक्षद्वात्रिंशत्सहस्रम् अक्षराणि सन्ति। अतः प्राचीनानाम् अनुसारं एकवारम् ऋग्वेदं पठिते सति चतुर्लक्षद्वात्रिंशत्सहस्रं भगवतः नाम उक्तं भवति। संक्षेपेण वेदस्य अक्षरेण भगवन्तं दर्शनम्; पदेन भगवन्तं दर्शनम्; वाक्येन भगवन्तं दर्शनम्; प्रकरणे च भगवन्तं दर्शनम्। एवं वेदं विश्लिष्य पश्येम एव अस्मभ्यं तत्र विद्यमानः सन्देशः ज्ञायते। अन्यथा सर्वं लौकिकतया दृश्यते। परं सर्वं वयं ज्ञातुं न शक्नुमः (नान्यः मद्वेद कश्चन)। तत् पूर्णतया ज्ञातवान् सः भगवान् एकः एव।\n\nअग्रिमाः त्रयः श्लोकाः भारतीयतत्त्वशास्त्रस्य चिन्तनाक्रमस्य सारः। एते विश्वस्य विश्वात्मनः अनुसन्धानं विवृण्वन्तः श्लोकाः।",
  "15.16": "द्वाविमौ पुरुषौ लोके क्षरः च अक्षरः एव च ।\nक्षरः सर्वाणि भूतानि कूटस्थः अक्षरः उच्यते ॥\n\nलोके एतौ द्वौ प्रकारौ पुरुषौ -- क्षरपुरुषः अक्षरपुरुषः च। ब्रह्मादयः समस्ताः जीवाः क्षरपुरुषाः। अस्य चराचरस्य कूटं (सङ्घातं) सङ्गमय्य स्थापितां चित्प्रकृतिः एव अक्षरपुरुषा इति उच्यते।\n\nअस्मिन् चेतनप्रपञ्चे द्वौ प्रकारौ पुरुषौ। एकः क्षरपुरुषः, अन्यः अक्षरपुरुषः। [अत्र पुरुषः इत्युक्ते पुमान् इत्यर्थः न। अस्य विषये पूर्वं बहुवारं विशेषतया चर्चितवन्तः।] एकदा पतिष्यत् शरीरं धारयन्तः क्षरपुरुषाः। ब्रह्मादयः समस्ताः जीवाः अपि क्षरपुरुषाः। ब्रह्मादयः समस्ताः देवताः अपि मोक्षं प्राप्नुवन्तः स्वशरीरसमेताः गन्तुं न शक्नुवन्ति। चतुर्मुखब्रह्मणः आयुः एकं कल्पम् (३१,१०४ सहस्रकोटि मानवसंवत्सराः)। ततः अनन्तरं तस्य शरीरम् अपि भस्मीभवति। इदम् ईशोपनिषदि एवं विवृतम् -- \"वायुः अनिलम् अमृतम् अथ इदं भस्मान्तं शरीरम्॥ (१७)\"। \"भगवते अधिष्ठानतया स्थितः प्राणदेवः अमृतः। तथापि, एकदा तस्य देहः भस्मीभवितव्यः एव\" इति। एवं समस्ताः देवताः जीवजातानि च क्षरपुरुषाः।\n\nनाशरहितं ज्ञानानन्दमयं स्वरूपभूतं देहं धारयन्ती श्रीलक्ष्मीः अक्षरपुरुषा। समस्ताः क्षरपुरुषाः मोक्षे अक्षराः भवन्ति। परं लक्ष्मीः सदा अक्षरा। अत्र लक्ष्मीं \"कूटस्था\" इति वर्णितम्। कूटम् इत्युक्ते सङ्गमः। जीवस्य शरीरस्य च सङ्गमाय कारणभूता माता श्रीलक्ष्मीः। सदा निर्लिप्ता, केनापि लेपेन विना, प्रपञ्चं व्यवस्थां कारयन्ती शक्तिः -- जगन्माता श्रीलक्ष्मीः। इयम् अक्षरपुरुषा।",
  "15.17": "उत्तमः पुरुषः तु अन्यः परम आत्मा इति उदाहृतः ।\nयः लोकत्रयम् आविश्य बिभर्ति अव्ययः ईश्वरः ॥\n\nअनयोः द्वयोः अपि श्रेष्ठः पुरुषोत्तमः। तमेव परमात्मा इति वदन्ति। नाशरहितः सः परमेश्वरः त्रीन् लोकान् प्रविश्य पालयति।\n\nक्षराक्षरे अतिक्रम्य स्थितः परमपुरुषः सः भगवान्। तमेव \"परमात्मा\" इति आह्वयन्ति। यः इमान् त्रीन् लोकान् (भूः भुवः स्वः, अथवा सम्पूर्णं ब्रह्माण्डम् -- एतत् सप्त वा चतुर्दश लोकान् इति विभज्यापि वदन्ति) पूर्णं धारयित्वा रक्षति सः सर्वशक्तः (ईश्वरः) भगवान्।",
  "15.18": "यस्मात् क्षरम् अतीतः अहम् अक्षरात् अपि च उत्तमः ।\nअतः अस्मि लोके वेदे च प्रथितः पुरुष उत्तमः ॥\n\nअहं क्षरम् अतिक्रम्य स्थितः। अक्षरात् अपि श्रेष्ठः। अस्मात् कारणात् लोकेऽपि वेदेऽपि \"पुरुषोत्तमः\" इति एव प्रथितः अस्मि।\n\nपूर्वस्मिन् श्लोके \"यः क्षराक्षराभ्याम् अतीतः सः पुरुषोत्तमः\" इति उक्तवान् कृष्णः, अत्र साक्षात् \"सः भिन्नः पुरुषोत्तमः अहमेव\" इति स्पष्टतया वदति। मध्वाचार्याः विष्णुतत्त्वनिर्णयस्य मङ्गलाचरणे वदन्ति -- \"सदागमैकविज्ञेयं, समतीतक्षराक्षरं, नारायणं सदा वन्दे, निर्दोषाशेषसद्गुणं\" इति। अत्र क्षराक्षराभ्याम् अतीतं भगवन्तं ते \"समतीतक्षराक्षरम्\" इति आह्वयन्ति। अस्मिन् श्लोके क्षरात् अतीतः, अक्षरात् उत्तमः इति उक्तम्। अत्र अतीतः इत्युक्ते उत्तमः। तथापि अतीतः उत्तमः च इति द्वे पदे प्रयुक्ते। इदम् एकं विशिष्टम् अर्थं ददाति। क्षरपुरुषस्य अस्तित्वस्य व्याप्तिः अस्य ब्रह्माण्डस्यान्तः। परं लक्ष्मीनारायणौ अस्य ब्रह्माण्डस्य अतीतौ स्थितौ। इदम् \"अतीत\" पदं विवृणोति। भगवान् अक्षरायाः लक्ष्म्याः अपि उत्तमः। अस्मिन् श्लोके \"अपि\" \"च-कारं\" च सह प्रयुक्तम्। इदं भगवतः सर्वश्रेष्ठत्वं वदति। तस्मात् श्रेष्ठं तत्त्वम् अन्यत् नास्ति।\n\nपुरुषोत्तमपदस्य सर्वेषां मुखानाम् अर्थः केवलं भगवति एव अन्वेति। कृष्णः वदति -- \"लोके वेदे च पुरुषोत्तमः इति आह्वयन्ति मामेव\" इति। अत्र लोकः इत्युक्ते पौरुषेयानि पुराणग्रन्थानि। उदाहरणार्थं रामायणं, महाभारतं, पञ्चरात्रं, पुराणम् इत्यादि। एवं \"पुरुषोत्तमः\" इति परममुख्यतया केवलं भगवति एव अन्वेति।",
  "15.19": "यः माम् एवम् असम्मूढः जानाति पुरुषोत्तमम् ।\nसः सर्ववित् भजति माम् सर्वभावेन भारत ॥\n\nहे भारत, भ्रान्तिं त्यक्त्वा माम् एवं पुरुषोत्तमम् इति यः जानाति सः सर्वं ज्ञातवान्। सः सर्वभावेन माम् एव आराधयति।\n\nअत्र उक्तान् विचारान् ज्ञात्वा अस्मभ्यं किं लाभः इति प्रश्नं कुर्वतां कृते कृष्णस्य उत्तरम् अस्मिन् श्लोके अस्ति। कृष्णः वदति -- \"मां पुरुषोत्तमम् इति अहङ्कारं विना, स्वच्छेन मनसा, क्रोधं जित्वा, मोहं त्यक्त्वा यः जानाति सः सर्वं ज्ञातवान्\" इति। अस्मभ्यं भगवतः अस्तित्वम् अवगन्तुं प्रथमं जडात् भिन्नं \"अहम्\" इति चेतनम् अस्मिन् देहे अस्ति इति अवगन्तव्यम् (by awareness of self)। एवम् आत्मसाक्षात्कारे सति भगवतः बिम्बसाक्षात्कारः भवति। यः भगवन्तं जानाति सः सर्वं ज्ञातुं शक्नोति। एवं वयं प्राणिभ्यः भिन्नाः ज्ञानिनः भूत्वा जीवेम। एवं जीविते सति अस्माकं देवोपरि अचला भक्तिः दृढा भवति। ज्ञानी इति उक्तः जनः स्वसर्वस्वं हारयेत् चेदपि \"तत् भगवतः करुणा\" इति स्वीकरोति। अज्ञानिनि इयं दृढा भक्तिः न भवति। एवं दृढा भक्तिः उदेतुं वयं \"भारताः\" भवेम। निरन्तरा ज्ञानतृष्णा, ज्ञानिषु भक्तिः, भगवद्भक्तेषु ज्येष्ठे प्राणदेवे भक्तिः -- वयम् एव भारतान् कर्तुं शक्नोति।",
  "15.20": "इति गुह्यतमम् शास्त्रम् इदम् उक्तम् मया अनघ ।\nएतत् बुद्ध्वा बुद्धिमान् स्यात् कृतकृत्यश्च भारत ॥\n\nहे अनघ, अतीव गोपनीयां वाचं तव पुरतः उद्घाटितवान् अहम्। इदं यः अवगच्छति सः भगवन्तं वेत्ति। तस्मै पुनः कर्तव्यं किमपि न अवशिष्यते।\n\nइदम् अध्यात्मजिज्ञासुभ्यः वक्तव्येषु रहस्येषु सर्वश्रेष्ठं रहस्यम्। अध्यात्मे आसक्तिं धारयद्भ्यः तेषाम् आसक्तेः गभीरतां ज्ञात्वा वक्तव्यम्। शास्त्रस्य प्रमेयं कदापि वीथ्यां न उद्घाटनीयम्। यतः तत् व्यर्थं न भवेत्, अनर्थं वा न भवेत्। यस्मै ग्रहणस्य योग्यता अस्ति, यस्मै आसक्तिः श्रद्धा भक्तिः च अस्ति, तस्मै एव वक्तव्यम्। इदं रहस्येषु अतिगोप्यम्। क्षरपुरुषाणां ज्ञानम्, अक्षरपुरुषायाः ज्ञानम्, पुरुषोत्तमस्य च ज्ञानं यः जानाति सः शास्त्रज्ञः। शास्त्रम् इत्युक्ते ज्ञातवद्भिः अज्ञातेभ्यः ज्ञातव्यं वस्तु। \"अतीव रहस्यतया, यत्नेन रक्षणीयम् उपदेशार्हं विषयम् इदम्। अस्मात् श्रेष्ठतरः उपदेशः अन्यः नास्ति। एतादृशं गोप्यं विषयं तुभ्यम् उक्तवान् -- यतः त्वम् 'अनघः' अतः\" इति वदति कृष्णः। \"अनघः\" इत्युक्ते यस्य कोऽपि दोषः नास्ति सः। वयं ज्ञानाय बाधकेभ्यः दुरितेभ्यः दोषेभ्यः च प्रथमं मुक्ताः भवेम। अस्मदीयं मनः दुष्टविचारेण कलुषितं भवेत् चेत् तदा अस्मभ्यं गीता न अवगम्यते। केनापि पूर्वाग्रहेण आवेशेन विना पूर्णतया भगवति शरणागते सति मनः पापरहितं भवितुम् अर्हति।\n\nकृष्णः वदति -- \"इदं सर्वासां ज्ञानसंहतीनां मूलम्। इदं यः जानाति सः कृतकृत्यः\" इति। जीवने भगवन्तं ज्ञातवान् सार्थकं जीवनं जीवितुं शक्नोति। भगवतः अवबोधेन सह जीवनम् एव जीवनस्य सार्थक्यम्।\n\nइति पञ्चदशोऽध्यायः।",
  "16.1": "अहिंसा सत्यमक्रोधस्त्यागः शान्तिरपैशुनम् ।\nदया भूतेष्वलोलुत्वं मार्दवं ह्रीरचापलम् ॥\n\n[एतेषां त्रयाणां श्लोकानाम् (१६.१, १६.२ तथा १६.३) पदच्छेदः, अर्थः, विवरणं च सर्वं मिलित्वा अग्रिमे श्लोके (१६.३) दत्तम्।]",
  "16.2": "तेजः क्षमा धृतिः शौचमद्रोहो नातिमानिता ।\nभवन्ति सम्पदं दैवीमभिजातस्य भारत ॥\n\n[एतेषां त्रयाणां श्लोकानाम् (१६.१, १६.२ तथा १६.३) पदच्छेदः, अर्थः, विवरणं च सर्वं मिलित्वा अग्रिमे श्लोके (१६.३) दत्तम्।]",
  "16.3": "भगवान् उवाच\n\nअभयं सत्त्वसंशुद्धिः ज्ञानयोग व्यवस्थिति: ।\nदानम् दमः च यज्ञच स्वाध्यायः तपः आर्जवम् ।\nअहिंसा सत्यम् अक्रोधः त्यागः शांतिः अपैशुनम् ।\nदया भूतेषु अलोलुत्वं मार्दवं श्रीः अचापलम् ॥\nतेजः क्षमा धृतिः शौचम् अद्रोहः न अतिमानिता ।\nभवंति संपदं दैवीम् अभिजातस्य भारत ॥\n\nहे भारत, दैवीसम्पत्तिं [सद्वृत्तिं] धृत्वा जातस्य एते गुणाः भवन्ति -- निर्भयत्वम्, चित्तस्य निर्मलता, ज्ञानमार्गे स्थिरता, दानशीलता, इन्द्रियनिग्रहः, देवताराधनम्, वेदाध्ययनम्, व्रतनिष्ठा, ऋजुता, अहिंसा, सत्यवचनम्, अलोभः, औदार्यम्, भगवति मनःसंलग्नता, चुगल्यराहित्यम्, प्राणिषु करुणा, अत्यासक्तिराहित्यम्, नम्रता, ह्रीः, दृढता, अशैथिल्यम्, अपराधक्षमा, तेजः, अन्तर्बाह्यशुद्धिः, कापट्यराहित्यम्, अतिगर्वराहित्यम् च।\n\nअध्यात्मसाधनायां भवितव्यान् षड्विंशतिं सद्गुणान् कृष्णः अत्र विवृणोति। एतान् षड्विंशतिं गुणान् अनुसृत्य, अस्मासु विद्यमानं गुणम् अभिज्ञाय, तं वयं वर्धयेम, अविद्यमानं गुणं च वर्धयेम।\n\n(१) अभयम् (निर्भयत्वम्) -- इदम् अध्यात्ममार्गे गन्तॄणां सर्वप्रथमः गुणः। अध्यात्मं भीरुभ्यः न उक्तम्। हनुमन्तं विषये अयं श्लोकः वदति यथा --\n\n\"बुद्धिः बलं यशः धैर्यं निर्भयत्वं अरोगता।\nअजाड्यं वाक् पटुत्वं च हनुमत् स्मरणात् भवेत् ॥\"\n\nअस्मासु निर्भयत्वम् आगन्तुं मृत्युञ्जयस्य प्राणदेवस्य उपासना कर्तव्या। धैर्यं विना वेदान्तं पठेत् चेत् दृढा श्रद्धा न आगच्छति। वयम् उपासनां कुर्मः यदा कोऽपि आगत्य किमपि वदति। तदा अस्मदीयं मनः दृढतया देवे न तिष्ठति। यः यत् वदतु, \"अहं गृहीतं मार्गं न त्यजामि, देवः मां रक्षति\" इति दृढा श्रद्धा स्यात् तदैव वयं यशः द्रष्टुं शक्नुमः।\n\nअद्यतनेषु दिनेषु \"एवं कृते अनर्थः, तथा कृते अनर्थः\" इति भीषयन्तः जनाः एव अधिकाः। एवं वदन्तः जनाः शास्त्रस्य गन्धवायुमपि न जानन्ति। एते हिरण्यकशिपोः आवेशयुक्ताः जनाः। उदाहरणार्थं केचन \"विष्णुसहस्रनामं स्त्रीभिः न वक्तव्यम्\" इति भीषयन्ति। परं विपर्यासः यत् देवस्य नाम एव अस्मदीयस्य अभयाय। इदम् अज्ञात्वा भयेन दूरं सरेत् चेत् तेन अस्मभ्यमेव नष्टम्। देवः कदापि भयानकः न भवति। सः भयानकः भवति केवलं हिरण्यकशिपोः आवेशयुक्तेभ्यः, न प्रह्लादस्य आवेशयुक्तेभ्यः। वयं प्रह्लादवत् भूत्वा, अस्मान् भीषयतां हिरण्यकशिपूनां भयं विना, अभयप्रदं भगवन्तं स्तुयाम।\n\nअध्यात्मसाधकः कदापि भीरुः न भवति। यतः तस्मै एकः विषयः निश्चयेन ज्ञातः भवति। \"मया भेतुं कोऽपि अर्थः नास्ति, यतः भगवान् रक्षति यावत् मां सम्पूर्णं जगत् किमपि कर्तुं न शक्नोति; भगवता त्यक्ते सति कोऽपि मां रक्षितुं न शक्नोति\"। एवं निश्चितः अभिप्रायः अस्मासु वर्धेत।\n\n\"रक्षतीत्येव विश्वासः\" -- भगवान् स्वभक्तान् कदापि न त्यजति। अतः \"अभयम्\" अस्मासु भवितव्या प्रथमा योग्यता। एषः विश्वासः अस्मासु यावान् दृढः भवति तावत् रक्षणं भगवतः भक्ताय लभ्यते।\n\n(२) सत्त्वसंशुद्धिः -- अस्मदीया मनःशुद्धिः अध्यात्मसाधनायाम् अतिमुख्या। सामान्यतः अस्मदीयं मनः वंशपारम्पर्येण कारणेन, अथवा परिसरस्य प्रभावेण शुद्धं न भवति। त्रयोदशशतके एव आचार्याः \"दौर्लभ्यात् शुद्धबुद्धीनाम्\" इति उक्तवन्तः, इदं वयम् अत्र अवधानेन गृह्णीयाम। शुद्धमनस्काः समाजे अतीव दुर्लभाः।\n\nअत्र कृष्णः केवलं सत्त्वशुद्धिः इति अनुक्त्वा \"सत्त्वसंशुद्धिः\" इति उक्तवान्। अस्मदीयं मनः कदाचित् शुद्धं भवति, निद्रायां सर्वेषां मनः शुद्धम्। परं अत्र कृष्णः वदति सदा शुद्धं जागृतमनः। इदं भागवते \"सत्त्वं विशुद्धं वसुदेवशब्दितम्\" (४-३०-२३) इति उक्तम्। अर्थात् \"सदा शुद्धाय मनसे वासुदेवः गोचरः भवति\" इत्यर्थः। अतः अध्यात्मसाधनाय केनापि मलेन रहितं, केनापि पूर्वाग्रहेण रहितं मनः अतिमुख्यम्।\n\n(३) ज्ञानयोगव्यवस्थितिः (निरन्तरं ज्ञानयोगे मनसः स्थापनम्) -- उपासनायोगः अतिप्रमुखः योगः। भक्तिः, ज्ञानं, कर्मयोगः च अस्य त्रीणि मुखानि। एतानि परस्परं त्यक्त्वा स्थातुं न शक्नुवन्ति। ज्ञानयोगम् इत्युक्ते भगवतः महिमानं ज्ञात्वा, तस्य पूजारूपेण कर्म कृत्वा, तस्मिन् भक्तिं कृत्वा। \"व्यवस्थितिः\" इत्युक्ते अचला स्थितिः। भगवद्विषये अचलं मनः स्थापयित्वा, निरन्तरं भगवतः चिन्तने मनः स्थापनम्। अनेन मनः स्वच्छं भवति।\n\n(४) दानम् (अस्मदीयं वस्तु अन्यस्मै दानम्) -- अस्मदीये विद्यमानं वस्तु अन्यस्मिन् अविद्यमानं भवति यदा, तस्मै तत् अतीव आवश्यकं भवति यदा, तत् वस्तु अस्मभ्यम् अग्रे आवश्यकं भवेत् चेदपि, तद्विषये अचिन्तयित्वा, अर्पणभावेन दानं दानम्। एतद् विहाय गृहे अनावश्यकं वस्तु निःसारयितुं दत्तं, उत्तमश्रेणिकं गृहे स्थापयित्वा हीनश्रेणिकं दत्तं -- दानं न भवति। ददत् मनसि दीयमानस्य वस्तुनः उपरि कोऽपि ममकारः न स्यात्; \"ददामि, दत्तवान्\" इति अहङ्कारः न स्यात्। पूर्णार्पणभावेन दातव्यम्। दीयमानं वस्तु ज्ञानं वा स्यात्, धान्यं वा स्यात्, अभयं वा स्यात् (अन्यस्मै धैर्यदानम्), एवं यत्किमपि कार्यं स्यात्। तत्र कार्यात् अधिकं मुख्यं तस्य कार्यस्य पृष्ठे अस्मदीया भावना।\n\n(५) दमः (६) यज्ञः -- अत्र इमे द्वे क्रिये कृष्णः \"च\"-कारं प्रयुज्य (दमः च, यज्ञः च) उक्तवान्। इदम् अन्याभिः सर्वाभिः आचरणैः सह अतिमुख्यम् आचरणम् इति दर्शयितुम् अत्र च-कारः प्रयुक्तः। \"दमः\" इत्युक्ते दुष्टं कर्तुं त्यागः; अस्मदीयानि इन्द्रियाणि दुष्टं न कुर्वन्तु इति नियन्त्रणम्। यज्ञः इत्युक्ते कुर्वत् सर्वं कर्म भगवदर्पणं कृत्वा करणम्। वयम् एते द्वे आचरणे निरन्तरम् अस्मदीये जीवने पालयेम। एते द्वे आचरणे विना अन्यानि आचरणानि साधयितुं न शक्यते।\n\n(७) स्वाध्यायः -- त्रिधा स्वाध्यायः अस्ति। स्वतन्त्रस्य भगवतः विषये विद्यमाना समग्रा वेदाध्ययनं स्वाध्यायः; इदम् असाध्यं चेत् तत्तत्शाखायाः (स्वस्य) वेदाध्ययनम्। इदमपि स्वाध्यायः इति वदन्ति। इतः तृतीयं वयं गुरुभ्यः श्रुतम् अध्यात्मविचारं मनयित्वा, स्वप्रवचनं कृत्वा, अस्मदीयायै आत्मने तं विचारं ज्ञात्वा अनन्तरम् अन्यस्मै वदनम्। परं अद्य इदं स्वाध्यायं तिरोहितं भवति। पतञ्जलिः वदति -- \"वेदं अधीत्य त्वरितं वक्तारः भवन्ति\" इति। अद्य विद्यार्थी, श्वः अध्यापकः (वक्ता)। मध्ये स्वाध्यायः इति विचारः अद्य नास्ति। \"त्वरितम् अधीत्य\" -- सर्वं त्वरितम्!\n\n(८) तपः -- कृष्णेन अत्र उक्तं तपः पूर्वोक्तं तपः न। अस्मदीयं मनः मार्गभ्रष्टं न भवेत् इति नियन्त्रणं \"दमः\"; तेन शास्त्रस्य निरन्तरम् अध्ययनं \"स्वाध्यायः\"। अनयोः द्वयोः अस्मभ्यं बाधाकरौ द्वौ अंशौ स्तः। तौ जिह्वाचापल्यं लैङ्गिकी आसक्तिः च। एतौ अध्ययनस्य मूलशत्रू। एतयोः नियन्त्रणं तपः। अस्मात् कारणात् पूर्वं पुण्यक्षेत्रं गते सति स्वस्य कस्यचित् भक्ष्यचापल्यस्य त्यागं तत्र कुर्वन्ति स्म। येन केनापि निमित्तेन स्वचापल्यस्य त्यागः इदम् एतस्य पृष्ठे कारणम्।\n\n(९) आर्जवम् (प्रामाणिकता) -- ऋजुः आचारः वाक् च। वदनं किमपि, करणं किमपि इति अकृत्वा, प्रामाणिकतया स्थातुम्।\n\n(१०) अहिंसा -- अत्र अस्य विषयस्य दशमाध्याये (श्लोक-५) किञ्चित् विश्लेषितवन्तः। द्वेषेण, असहनतया, ईर्ष्यया अन्यस्मै पीडां जनयनम् हिंसा। आहाराय अन्यं जीवम् अनिवार्यतया मारणं हिंसा न (उदा. वनस्पतीनां सेवनम्, क्षत्रियाणां मांसभक्षणम् इत्यादि); गच्छन्, श्वसन्, अज्ञातेन सूक्ष्माः जीवाः म्रियेरन् चेत् तत् हिंसा न; देशं रक्षन् सैनिकः स्वधर्मपालनाय शत्रुसैनिकं हन्यात् चेत् तत् हिंसा न; अग्रे भाविनीं महतीं हिंसां निवारयितुम् अनिवार्यतया प्रवृत्तं युद्धं हिंसा न (उदा. महाभारतयुद्धम्); सहस्रशः जनान् रक्षितुं एकं हन्तुं तत् हिंसा न (उदा. दिने दश सहस्राणि सैनिकान् घातयितुं प्रतिज्ञां कृत्वा अहर्निशं युध्यमानं द्रोणाचार्यं कृष्णेन घातितम्); वैद्यः रोगिणं जीवयितुं कुर्वत् क्रिया हिंसा न; एवं समग्रतया द्वेषम्, असहनताम्, ईर्ष्याम्, स्वार्थं विना प्रवर्तमाना अनिवार्या हिंसा अहिंसा इव भवति।\n\nअन्यस्मै कष्टं न जनयत् जीवनम् अहिंसा। वयम् अन्यस्य मनः घातयेम चेत् तत् पुनः स्वस्थं कर्तुं कोऽपि औषधः नास्ति। अतः कदापि अन्यं मुखभङ्गं मा कुरु। उदाहरणार्थम् -- कञ्चन तीक्ष्णवचनेन उपहासं करणम्, मानसिकतया अन्यं निन्दनम् अथवा शापदानम्। वयं वाचा, कृत्या, मनसा च अन्यस्मै हिंसा न भवेत् इति आचरेम।\n\n(११) सत्यम् -- इदं प्रामाणिकतायाः अन्यत् मुखम्। अत्र सत्यम् इत्युक्ते यत् अस्ति तत् तथा वदनं न। समाजे साधुसज्जनेभ्यः हितकरं वचनं सत्यम्। कदाचित् लोकहिताय वयं वदत् असत्यमपि सत्यं भवति; लोकाय अन्यायकरं सत्यमपि असत्यं भवति। महाभारते कृष्णः इमं सन्देशं क्रान्तिकारकरूपेण कृत्वा दर्शितवान्। अयं विषयः महाभारते विशेषतया प्रस्तावितः। तत्र उक्तं यथा --\n\n\"न नर्मयुक्तं वचनं हिनस्ति न स्त्रीषु राजन् न विवाहकाले।\nप्राणात्यये सर्वधनापहारे पञ्च अनृतानि आहुः अपातकानि ॥ (१-७७-१६)\"\n\nकस्यचित् विवाहम् ईर्ष्यया असत्यं वदित्वा भङ्गं करणम्, निश्चितं विवाहं भङ्गं करणम् इत्यादि शास्त्रं खण्डयति। प्राणापाये जीवरक्षायै वदत् असत्यम् असत्यं न।\n\n(१२) अक्रोधः -- यस्मिन् कस्मिन्नपि काले अन्यस्य उपरि क्रोधं न कुर्यात्। अप्रिया घटना जायते यदा क्रोधः आगच्छेत्। परं स्वयं क्रोधस्य हस्ते कदापि मा ददस्व। क्रोधे आगते -- क्रोधस्य अवरोहणपर्यन्तं मौनम् आचरेत् चेत् तेन जायमानम् अनर्थं टलति। काम-क्रोधयोः विषये कृष्णः गीतायाम् अनेकवारम् अस्मान् सावधानान् करोति। नैर्मल्ययुक्तस्य जीवनस्य कृते एतौ मारकौ। शान्तत्वं वयं कथं शिक्षेम इत्यस्य श्रीरामचन्द्रस्य जीवनम् एव उत्तमम् उदाहरणम्। रामायणे वाल्मीकिः वदति -- \"उच्यमानः अपि परुषं न उत्तरं प्रतिपद्यते\" इति (अयोध्या-१.१५)। रामे यः कोऽपि कलहाय स्थातुं यतते चेत् सः कदापि क्रुद्धः न भवति स्म।\n\n(१३) त्यागः -- उपरिदृष्ट्या दानं त्यागं च एकम् इव भासते। परं त्यागः इत्युक्ते अस्मदीयं वस्तु अपि \"मम न, भगवतः\" इति भावनया जीवनम्। त्यागे अनेके विधाः। अभिमानत्यागः, फलत्यागः, अहङ्कारममकारत्यागः इत्यादि। प्रीतिः अस्तु, परं \"मम\" इति भावनातः दूरं तिष्ठ। प्राप्ते सति सन्तोषेण स्वीकुरु, गते सति निर्लिप्तः तिष्ठ। अस्मिन् जीवनयात्रायां किमपि शाश्वतं न। भगवान् एकः एव नित्यः इति ज्ञात्वा तम् एव लक्ष्यीकृत्य यात्रां कुरु।\n\n(१४) शान्तिः -- त्यागात् सर्वप्रथमं लभ्यते नैर्मल्यम्। स्वल्पमपि उद्वेगं विना, प्रत्येकं स्वीकुर्वति सर्वं शान्तम्। मनः भगवति स्थापिते सत्येव एतादृशी शान्तिः आगन्तुं शक्या। क्षुद्रे लौकिके विचारे शिरः निधाय -- स्पर्धा, कलहः, विरसता -- एतैः जीवनं यापयितुम् अपेक्षया भगवति मनः स्थापयित्वा शान्तिं प्राप्तुं श्रेयः।\n\n(१५) अपैशुनम् -- \"पैशुनम्\" इत्युक्ते चुगल्यं वदित्वा विरसं जनयनम्। इदम् अत्यन्तं निकृष्टं गुणम्। स्वार्थाय महद्भ्यः चुगल्यं वदित्वा समाजस्वास्थ्यं नाशयनं महापापम्। अतः त्वम् अपैशुनः भव इति वदति कृष्णः। चुगल्यं मा वद, चुगल्ये कर्णं मा देहि।\n\n(१६) दया भूतेषु -- चैतन्ययुक्तानि प्रत्येकानि जीवानि प्रति अनुकम्पा भवतु। सा वनस्पतिः स्यात्, प्राणी स्यात्, पक्षी स्यात्, मनुष्यः स्यात्। सर्वेषु दया भवतु। इदं पूर्वकाले विशिष्टरीत्या अनुसृत्य आयातम्। प्रातः उत्थाय तुलस्यै जलदानम्, गोशालां गत्वा गोभ्यः आहारदानम्, गृहे विद्यमानाय श्वभ्यः वयं भोजनात् पूर्वम् आहारदानम्, गृहसमीपस्थेभ्यः पक्षिभ्यः आहारदानम्, क्षुधार्तस्य आगतस्य व्यक्तेः उदरे विद्यमानं वैश्वानरं शमयनम् इत्यादि। एतद्विहाय अन्यः कष्टे स्थितः यदा, सः मित्रः शत्रुः इति भेदम् अगणयित्वा तस्मिन् दयां दर्शनं अतिमहत् गुणम्। इमं गुणं मुख्यतया महाभारते धर्मराये पश्यामः।\n\n(१७) अलोलुत्वम्/अलोलत्वम् -- एकां वस्तुम् अतिशयेन आसक्तिः लोलत्वम्। कस्यामपि वस्तुनि अतिशयितः मोहः न भवतु। आसक्तिः दुःखस्य कारणम्।\n\n(१८) मार्दवम् (Gentle) -- सौजन्यम्, मृदुस्वभावम् अत्र मार्दवम् इति उक्तम्। अस्मासु केचन स्वकर्मकरान्, अथवा स्वाधीनतया कार्यं कुर्वतः सहोद्योगिनः गौरवं विना सम्भाषन्ते। ते \"मम सेवकाः\" इति अहङ्कारेण तैः सह व्यवहरन्ति। इदम् अत्यन्तं नीचं गुणम्। एतेन वयं तस्य व्यक्तेः मनः पीडयामः इत्येव न, तस्यान्तः स्थितं भगवन्तम् अपि तिरस्कृतवन्तः भवामः। इदम् अहङ्कारस्य अन्यत् मुखम्। अस्मात् कृष्णः उक्तवान् -- \"युष्माकं आचरणे नयविनयौ स्तः, सौजन्यं स्यात्\" इति।\n\n(१९) ह्रीः -- दोषं कृते सति लज्जा। इदम् अतीव महत् गुणम्। तैत्तिरीयोपनिषदि उक्तं यथा -- \"श्रिया देयम्। ह्रिया देयम्। भिया देयम्। संविदा देयम्॥ (११-०३)\"। अन्ये टीकां कुर्युः इति ह्रिया अपि दानं कुरु इति शास्त्रं वदति।\n\n(२०) अचापलम् -- स्वनिश्चयं ग्रहीतुं स्थैर्यम्। विषयं विश्लिष्य किं सम्यक्, किम् असम्यक् इति ज्ञात्वा, \"मम मार्गः किम्\" इति दृढतया स्थातुम् अचापलम्।\n\n(२१) तेजः (तेजस्सु) -- इदं शास्त्रकाराः \"ब्रह्मवर्चसम्\" इति वदन्ति। मुखे कान्तिः पूर्णा भवनम्। नेत्रे तेजः। स्वच्छे मनसि साधनामार्गे गच्छतां ज्ञानिषु एव इदं गुणं भवति।\n\n(२२) क्षमा (Forgiveness) -- दोषं कृतवतः उपरि अपि प्रतीकारभावनां न वर्धयितुम्। अस्मदीये मनसि कदापि प्रतीकारभावना न जायेत। शास्त्रे उक्तं यथा -- \"अन्यैः अपकारं कृतेऽपि तान् क्षमस्व\" इति। \"हे देव, तेभ्यः सद्बुद्धिं देहि\" इति प्रार्थय -- परं प्रतीकारभावना मा भव। अस्मासु \"सर्वे मां प्रशंसेयुः\" इति अहङ्कारः न स्यात् चेदेव क्षमा साध्या।\n\n(२३) धृतिः (यत्किमपि भवतु जीवने अकुण्ठितत्वम्) -- आत्मविश्वासे सत्यां अस्मान् कोऽपि किमपि कर्तुं न शक्नोति। यथार्थः ज्ञानी कदापि भीरुः भूत्वा धृतिं न त्यजति। \"अग्रे एवं भवेत्\" इति मनसि चिन्तयित्वा खिन्नता जीवनं न, अपि तु यत्किमपि आगच्छतु तत् प्रतिकर्तुं शक्तिं भगवान् मह्यं ददाति इति दृढा आत्मशक्तिः धृतिः। विषमां परिस्थितिं प्रतीकृत्य जीवनम् एव जीवनम्। अनपेक्षितः आपत् जीवने सामान्यम्। तत् ज्ञात्वा आत्मविश्वासेन जीव। अकर्तव्यं जगति कदापि न भवति, भवत् केनापि निवारयितुं न शक्यते। अस्मदीयायाः रक्षायाः भारः सर्वनियामकस्य भगवतः। एवं सति भयं किमर्थम्?\n\n(२४) शौचम् -- अस्य विषयस्य पूर्वेषु अध्यायेषु अनेकवारं चर्चितवन्तः। शौचम् इत्युक्ते अन्तः बहिः च स्वच्छता। समाजे अस्मत्तः अन्येभ्यः कष्टं न भवेत्। अस्मदीयं देहं मनः च स्वच्छं भवेत् इति वयं दृष्ट्वा गृह्णीयाम। अस्मत्तः अन्यः \"अय्यो\" इति नासिकां न मोटयेत् तथा वयं स्थातव्याः। अस्मदीयं मनः स्वच्छं भवेत्। सुवस्त्रं धृत्वा, मनसि कश्मलं पूरितं स्यात् चेत् वयम् अज्ञाततया अस्मदीयं समीपस्थं वातावरणं दूषयामः। अस्मात् अन्तः बहिः च स्वच्छं भवितव्यम्।\n\n(२५) अद्रोहः -- अन्यस्य विषये द्रोहचिन्तनं न कर्तुम्। अन्यस्मै द्विधा मा चिन्तय। अन्यस्य अनिष्टं स्वप्नेऽपि मा इच्छ।\n\n(२६) नातिमानिता -- \"अतिमानः\" इत्युक्ते स्वस्य विषये अतिशयितां श्लाघां कल्पयित्वा गर्वः। कृष्णः वदति -- \"स्वस्य विषये त्वं कदापि अतिशयितम् अहङ्कारं मा धर\" इति। अस्मै गुणाय श्रीरामचन्द्रस्य जीवनम् उत्तमं दृष्टान्तम्। वाल्मीकिरामायणे उक्तं यथा -- \"वीर्यवान् न च वीर्येण महता स्वेन विस्मितः॥ (२-१-१३)\" इति। असाधारणपौरुषेयः रामः कदापि \"अहं महावीरः\" इति अहङ्कारं न धृत्वा, सामान्यमानववत् जीवित्वा दर्शितवान्। इदं बृहत् गुणम्।\n\nएवं वयं जीवने अवलम्बनीयान् षड्विंशतिं गुणान् उक्त्वा कृष्णः वदति -- \"भवन्ति सम्पदं दैवीम् अभिजातस्य भारत\" इति। अत्र \"अभि\" इत्युक्ते \"अभिलष्य\" इति अर्थं ददाति। \"दैवीं सम्पत्तिम् अभिलष्य जातस्य एते गुणाः भवन्ति। अर्थात् ये जन्मकालादेव सात्त्विकतायाः अभिलाषां धृत्वा जायन्ते तेषां स्वाभाविकतया एते गुणाः भवन्ति। एताः दैवीः सम्पत्तयः। मानवेन वर्धनीया मानसिकी सम्पत्तिः।",
  "16.4": "डंभः दर्पः अभिमानः च क्रोधः पारुष्यम् एवच ।\nअज्ञानम् च अभिजातस्य पार्थ संपदम् आसुरीम् ॥\n\nहे पार्थ, आसुरीं सम्पत्तिं [दुष्टवृत्तिं] धृत्वा जातस्य एते गुणाः भवन्ति -- ढोंगित्वम्, दर्पः, गर्वः, क्रोधः, कठोरता, अज्ञानं च।\n\nउपर्युक्तान् षड्विंशतिं दैवीगुणान् विपरीततया षड् आसुरीगुणान् कृष्णः अस्मिन् श्लोके उक्तवान् --\n\n(१) डम्भः (अविद्यमानं विद्यमानम् इति दर्शनम्) -- अन्तः यत् नास्ति तत् अस्ति इति सुभगत्वस्य प्रदर्शनम्; अन्तर्गतां दुष्टतां गूहित्वा अतीव साधुवत् प्रदर्शनम्, इत्यादि डम्भः इत्युच्यते। इदम् उपर्युक्तस्य आर्जवस्य विरुद्धगुणम्।\n\n(२) दर्पः -- किमपि दोषं कर्तुम् अनुत्सुका मनोवृत्तिः। इदं ह्रीः इति सद्गुणस्य विरुद्धगुणम्।\n\n(३) अतिमानः -- स्वस्य विषये अतिरेकस्य कल्पना; \"अहमेव महान् मनुष्यः\" इति भ्रमित्वा अन्यस्मै अगौरवं दर्शनम्; सर्वे मम पादौ स्पृशेयुः इति अपेक्षणम् -- एतानि अतिमानम् इति उच्यन्ते।\n\n(४) क्रोधः -- मनुष्यः त्यक्तुम् इच्छन्नपि त्यक्तुम् अशक्यः दुष्टगुणः क्रोधः। इदम् अस्मदज्ञाततया अस्मान् मार्गभ्रष्टान् कारयत् दुर्गुणम्।\n\n(५) पारुष्यम् -- उग्रं, अरुचिकरं वचनम्; अन्यं तात्सारेण भाषणम्, इत्यादि पारुष्यस्य उदाहरणम्।\n\n(६) अज्ञानम् -- उपर्युक्तानां सर्वेषां दुर्गुणानां चक्रवर्ती अयम् अज्ञानम्। यथार्थः ज्ञानी कदापि एतेषां दुर्गुणानां दासः न भवति।\n\nएते सर्वे आसुराः गुणाः अस्मासु गृहं कृत्वा अस्मानेव बहिः क्षेपयन्ति। अतः एतान् दुर्गुणान् वयं प्रथमं बहिः क्षेपयेम। कुराने इदं सुन्दरतया उक्तम् -- \"Drive them out from where you have been driven out\" इति। त्वां बहिः क्षेप्य, त्वदन्तः उपविश्य त्वां नाशयतः एतान् दुर्गुणान् प्रथमं बहिः क्षेपय इति वदन्ति। इदमेव वेदे एवम् उक्तम् -- \"यः अस्मान् द्वेष्टि यम् वयं द्विष्मः\" इति (अथर्व ३-२७-२)। अर्थात् \"यः अस्मान् द्वेष्टि, यं वयं द्विष्मः तादृशं शत्रुं दूरं धावय\" इत्यर्थः। अत्र शत्रुः इत्युक्ते अस्मदीयाः अन्तःशत्रवः एते दुर्गुणाः।\n\nअस्मिन् श्लोके \"पार्थ\" इति विशेषणं प्रयुक्तम्। \"वयं दुर्गुणेभ्यः दूरं गत्वा, ज्ञानमार्गे गत्वा, यथार्थं जीवनं जीवन्तः पार्थाः भवेम\" इति सन्देशः अस्य विशेषणस्य पृष्ठे अस्ति।",
  "16.5": "दैवी संपत् विमोक्षाय निबंधाय आसुरी मता ।\nमा शुचः संपदम् दैवीम् अभिजातः असि पांडवा ॥\n\nदैवी सम्पत्तिः मोक्षाय, आसुरी सम्पत्तिः बन्धनाय भवति। हे पाण्डव, मा शोचय, त्वं दैवीं सम्पत्तिं धृत्वा एव जातः असि।\n\nकिमर्थं वयं दैवीं सम्पत्तिं वर्धयेम इति कृष्णः विवृण्वन् वदति -- \"दैवी सम्पत्तिः विमोक्षाय कारणं भवति, आसुरी स्वभावः निबन्धाय कारणं भवति\" इति। अत्र कृष्णः \"वि-मोक्षः\" \"नि-बन्धः\" इति विशिष्टतया उक्तवान्। वि-मोक्षः इत्युक्ते तस्य तस्य साधनानुगुणं विविधस्तरे व्यक्तित्वविकासः मोक्षश्च। \"नि-बन्धः\" इत्युक्ते संसारबन्धः न। इदं नीचं बन्धम्। अस्मान् तमसः अन्धकारं प्रति क्षिपत् बन्धम्।\n\nकृष्णः अर्जुनं प्रति वदति -- \"त्वं दैवीसम्पत्तेः पूर्णप्रमाणस्य आविष्कारः। अस्मात् दैवीसम्पत्तेः गृहम् अन्विष्य जातः असि। तव स्वभावः, त्वं जातस्य कुलस्य प्रभावः च परस्परं पोषकौ। अस्मात् कारणात् मा चिन्तय\" इति।",
  "16.6": "द्वौ भूतसर्गौ लोकेऽस्मिन् दैव आसुर एव च ।\nदैवो विस्तरशः प्रोक्त आसुरं पार्थ मे शृणु ॥\n\nअस्मिन् विश्वे द्वे प्रकारे जीवसृष्टी स्तः -- दैवी [सदाचरणयुक्ता] च आसुरी [दुष्टाचरणयुक्ता] च। दैवीप्रकारः विस्तारेण उक्तः, हे पार्थ, आसुरीप्रकारं मत्तः शृणु।\n\nअस्मिन् विश्वे मूलतः द्वे प्रकारे मानवाः सन्ति -- भगवतः दिशं मुखं कृत्वा गच्छन्तः दैवीचरणयुक्ताः च भगवते पृष्ठं दत्त्वा गच्छन्तः आसुरीचरणयुक्ताः च। अनयोः द्वयोः विभागयोः इतः पर्यन्तं दैवीस्वभावस्य विषये विस्तारेण दृष्टवन्तः। अस्मदीयस्य अन्तरङ्गस्य सामाजिकस्य च आचरणस्य विषये विस्तारं चित्रणं दत्त्वा अनन्तरं कृष्णः, अत्र आसुरस्वभावानां चरितविषये विवृणोति। अनेन वयं \"कीदृशाः न स्यामः\" इति कृष्णः अस्मभ्यं ज्ञापयति।",
  "16.7": "प्रवृत्तिम् च निवृत्तिम् च जनाः न विदुः आसुराः ।\nन शौचम् न अपि च आचारः न सत्यम् तेषु विद्यते ॥\n\nदुष्टाचरणयुक्ताः जनाः किं कर्तव्यं किं त्याज्यम् इति न जानन्ति। शौचं नास्ति; सदाचारः नास्ति; तेषु सत्यमपि न विद्यते।\n\nआसुरस्वभावानां सामाजिकम् आचरणं कृष्णः अत्र विवृणोति। आसुरस्वभावेभ्यः किं कर्तव्यं, किं न कर्तव्यम् इति जागृतिः न भवति। अनेन ते अकर्तव्यमेव कुर्वन्ति। एतेभ्यः न्यायः अन्यायः च किमपि मुख्यं न। धनार्जनं गण्यव्यक्तित्वं च प्राप्तव्यम् इति एतेषां मूलभूता इच्छा। अस्मात् धनार्जने न्यायस्य मुखं भवेत् इति जागृतिः एतेषु न भवति।\n\nमूलतः आसुरस्वभावेषु नैर्मल्यं न भवति। सद्वचनम्, सच्चिन्तनम्, स्वच्छं शरीरं च एतेषु न भवति। एते बाह्यतः अतीव शुद्धाः इव नाटकं कृत्वा जीवन्ति। एते कदापि प्रामाणिकाः न भवन्ति। यत्किमपि कुर्वन्ति तत् प्रदर्शनार्थम्। अस्मभ्यं कृष्णेन गीतायाम् उक्तं प्रत्येकं गुणलक्षणस्य उदाहरणं महाभारते एव लभ्यते। अस्मात् गीतां महाभारतस्य सारम् इति वदन्ति। आसुरस्वभावाय अत्युत्तमम् उदाहरणं \"दुर्योधनः\"।\n\nएते आसुरस्वभावाः कथं समाजकण्टकाः भवन्ति, तेषाम् अवबोधः कः इति अस्य अध्यायस्य अग्रिमे भागे कृष्णः विस्तारेण विवृणोति।",
  "16.8": "असत्यम् अप्रतिष्ठम् ते जगत् आहुः अनीश्वरम् ।\nअपरस्पर संभूतं किम् अन्यत् कामहैतुकम् ॥\n\nते वदन्ति -- इदं विश्वं सत्यस्वरूपस्य भगवतः दानं न [इदम् असत्यस्य पुञ्जः]। इदं भगवति न स्थितम् [अस्मै आधारः एव नास्ति]। इदं नियमयन् सर्वशक्तः कोऽपि नास्ति। एकस्मात् अन्यत् क्रमेण जातम् इति अपि न स्वीकुर्वन्ति। किम् अन्यत्? तेषां दृष्ट्या इदम् अन्यप्रकारम्। इदं कामस्य शिशुः -- मायासृष्टिः।\n\nआसुरेषु द्वे विधे। जगते अन्यत् सत्यं नास्ति, जगते अन्या प्रतिष्ठा नास्ति, जगते अन्यः ईश्वरः नास्ति इति नास्तिकं ज्ञानम् एतेषु भवति। जगत् सृष्टिस्थितिसंहारेषु नियोजयन्ती शक्तिः (सत्यम्) नास्ति इति एते ज्ञातवन्तः भवन्ति। एतेषां मते अस्य जगतः आधारभूतः एकः देवः नास्ति, अतः इदं जगत् नियन्त्रयन् स्वामी नास्ति, सर्वं भ्रान्तिः इति वदन्ति। सृष्टिचक्रम् एकः मूर्खत्वस्य सिद्धान्तः इति एतेषां विश्वासः।\n\nअन्यविधाः आसुराः अस्मिन् जगति अस्मभ्यं यत् दृश्यते तत् केवलम् अस्मदीया भ्रान्तिः इति शून्यवादं कुर्वन्तः। एते इदं प्रपञ्चम् अस्मदीयाभिः इच्छाभिः वर्धमानम् एव, न अन्यया शक्त्या इति विश्वसन्ति।",
  "16.9": "एतां दृष्टिमवष्टभ्य नष्टात्मानोऽल्पबुद्धयः ।\nप्रभवंत्युग्रकर्माणः क्षयाय जगतोऽहिताः ॥\n\nएतां दृष्टिम् अवष्टभ्य विवेकं हारितवन्तः अवबोधरहिताः -- जनाङ्गस्य कण्टकाः। उग्राचरणयुक्ताः एते जगतः नाशाय कारणं भवन्ति।\n\nआसुरं मनोवृत्तिं वर्धयन्तः जनाः स्वजीवनाय अनर्थम् आनीय स्वनाशाय स्वयमेव कारणं भवन्ति। एते स्वविश्वास एव तान् नाशयति, स्वयं तमसः मार्गे गच्छन्तः इति जागृतिमपि विना उग्रकर्माणः (उग्रकर्माणः) भवन्ति। अस्य परिणामः एते लोकशत्रवः भूत्वा, लोकनाशाय कारणं भवन्ति। एतादृशी मनोवृत्तिः धृत्वा अस्माकं मध्ये विद्यमानाः जनाः एव आसुराः।",
  "16.10": "कामम् आश्रित्य दुष्पूरं डंभ मान मद अन्विताः।\nमोहात् गृहीत्वा असत् ग्राहान् प्रवर्तंते अशुचि व्रताः ॥\n\nअतृप्तायाः इच्छायाः पृष्ठं गत्वा ढोंगित्वं, दर्पं, गर्वं च प्राप्ताः। मलिनाचरणस्य एते जनाः मोहेन विपरीतग्रहणान् कृत्वा जीवन्ति।\n\nआसुरस्वभावानाम् इच्छायाः अन्तः नास्ति। यावत् अपि प्राप्तं तथापि अधिका आशा। उदाहरणार्थं कर्म एव न भवति यदा एकस्य कर्मणः आशा, कर्म लब्धे सति अधिकवेतनस्य आशा, वेतने प्राप्ते सति तत् वेतनं स्वसमीपगृहस्थात् न्यूनम् इति अस्मात् अधिकतरस्य वेतनस्य आशा, महत् पदस्य आशा -- एवं यावत् अपि प्राप्तं तृप्तिः नास्ति। एनं दाहं पूरयितुं न शक्यमेव। पुराणे उक्तं यथा पातालं मृत्तिकया आच्छाद्य पूरयितुं न शक्यते, तथैव मनुष्यस्य इच्छां पूरयितुं न शक्यते। अस्मभ्यं यावत् अपि धनं प्राप्तं, तस्य दक्षिणतः एकं शून्यं योजयित्वा न्यूनम् अभवत् इति खिन्नाः भवामः, सन्तोषं विस्मरामः। कठोपनिषदि \"तुभ्यं यावत् आवश्यकं तावत् धनं ददामि\" इति यमेन उक्ते, नचिकेतः वदति -- \"न वित्तेन तर्पणीयः मनुष्यः\" इति। अर्थात् \"मनुष्यस्य धनेच्छां पूरयितुं केनापि न शक्यते\" इति। \"पर्याप्तम्\" इति दैवीस्वभावः, \"आवश्यकम्\" इति आसुरस्वभावः। एवम् आसुरस्वभावाः इच्छानां पृष्ठं गत्वा, तां अतृप्तां इच्छां पूरयितुम् अकर्तव्यं कुर्वन्ति। एतेषां जीवनम् एव डम्भाचारः। कठोरता, दुरहङ्कारः, नाटकीयेन जीवनेन अन्यस्य वञ्चनम्। एवम् आचारे वाचि च स्वच्छतारहितं मलिनं जीवनम् एतेषाम्।",
  "16.11": "चिंतां अपरिमेयां च प्रळयांतां उपाश्रिताः ।\nकाम उपभोग परमाः एतावत् इति निश्चिताः ॥\n\nमृत्युना सह नाशं गच्छन्तीं, अपरिमितां चिन्तां आश्रिताः। कामतृष्णा एव जीवनस्य सर्वस्वं येषाम्। जीवनम् इत्युक्ते एतावत् एव इति विश्वसन्तः।\n\nएतेषां खिन्नतायाः अन्तः नास्ति। एते स्वसम्पूर्णं जीवनम् अविद्यमानस्य प्राप्तये खिन्नतायां व्ययन्ति। एते चिन्तायाः दासाः भवन्ति। एतेषां चिन्ता \"प्रलयान्तिका\" -- मरणपर्यन्तम् अपि तेषां पृष्ठं न त्यजन्ती पीडयति। एते भोगजीवनस्य दासाः भूत्वा, तत् त्यक्तुम् अशक्यायां पराधीनतायां, \"जीवनम् इत्युक्ते एतावदेव\" इति ज्ञात्वा जीवन्ति।",
  "16.12": "आशापाश शतैः बद्धाः कामक्रोधपरायणाः।\nईहंते कामभोगार्थ अन्यायेन अर्थसंचयान् ॥\n\nशतशः आशानां पाशेन बद्धाः। कामक्रोधयोः वशं गताः। कामभोगार्थं अन्यायेन धनसञ्चयं कर्तुम् इच्छन्ति।\n\nएते भोगेच्छायै स्वयमेव इच्छानां पाशे बद्धाः भूत्वा, दिग्बन्धनेन जीवन्ति। कामक्रोधयोः वशं गत्वा, कामक्रोधपरायणाः भूत्वा जीवन्ति। अस्मै उत्तमं दृष्टान्तं पौण्ड्रकवासुदेवः। तस्य \"स्वयमेव देवः भवितव्यम्\" इति कामः। अनेन कामेन तत् असम्यक् इति ज्ञापयतां तत्त्वज्ञानां उपरि क्रोधः।\n\nएते स्वसुखभोगं पूरयितुम् अन्यायमार्गेण धनसङ्ग्रहं कर्तुं यतन्ते। शास्त्रे लिखितान् विषयान् स्वेच्छानुगुणं वक्रीकृत्य, स्वेष्टसिद्धिसाधनायां प्रवर्तन्ते।",
  "16.13": "इदमद्य मया लब्धमिमं प्राप्स्ये मनोरथम् ।\nइदमस्तीदमपि मे भविष्यति पुनर्धनम् ॥\n\n[एतेषां त्रयाणां श्लोकानाम् (१६.१३, १६.१४ तथा १६.१५) पदच्छेदः, अर्थः, विवरणं च सर्वं मिलित्वा अग्रिमे श्लोके (१६.१५) दत्तम्।]",
  "16.14": "असौ मया हतः शत्रुर्हनिष्ये चापरानपि ।\nईश्वरोऽहमहं भोगी सिद्धोऽहं बलवान् सुखी‌ ॥\n\n[एतेषां त्रयाणां श्लोकानाम् (१६.१३, १६.१४ तथा १६.१५) पदच्छेदः, अर्थः, विवरणं च सर्वं मिलित्वा अग्रिमे श्लोके (१६.१५) दत्तम्।]",
  "16.15": "इदमद्य मया लब्धमिमं प्राप्स्ये मनोरथम् ।\nइदमस्तीदमपि मे भविष्यति पुनर्धनम् ॥\n\nअसौ मया हतः शत्रुर्हनिष्ये चापरानपि ।\nईश्वरोऽहमहं भोगी सिद्धोऽहं बलवान् सुखी ॥\n\nआढ्यो अभिजनवान् अस्मि कः अन्यः अस्ति सदृशः मया ।\nयक्ष्ये दास्यामि मोदिष्ये इति अज्ञान विमोहिताः ॥\n\nते अज्ञानतया एवं प्रलपन्ति -- \"इदम् अद्य मया लब्धम्, इमं मनोरथं प्राप्स्ये। इदम् अस्ति, इदमपि मे धनं पुनः भविष्यति। असौ शत्रुः मया हतः, अपरान् अपि हनिष्ये। अहमेव ईश्वरः, अहं भोगी, अहं सिद्धः, अहं बलवान्, अहं सुखी। अहम् आढ्यः, अभिजनवान्। मया सदृशः अन्यः कः अस्ति? अहं यजिष्ये, दास्यामि, मोदिष्ये\" इति।\n\nआसुरस्वभावानां चिन्तनानि कीदृशानि भवन्ति इति कृष्णः एतेषु त्रिषु श्लोकेषु विवृतवान्। एतेभ्यः सदा धनसङ्ग्रहं कर्तव्यम् इति चिन्तनम्। प्राप्ते सति \"अद्य इयत् प्राप्तम्, श्वः इयत् अर्जयिष्यामि\" इति चापल्यम्। धनसङ्ग्रहः एतेषां व्यसनम्। \"स्वस्य अप्रियं नाशितवान्, इतोऽपि अप्रियान् नाशयिष्यामि\" इति चिन्तनम्। \"अहमेव सर्वसमर्थः, मया अशक्यं किमपि अस्मिन् जगति नास्ति? अहं सुखं भोक्तुं जातः -- न दुःखं भोक्तुम्; मम सुखाय यत्किमपि करिष्यामि; तत्र विघ्नं कुर्वतः नाशयिष्यामि; अहमेव सिद्धपुरुषः; मम सिद्ध्यै अहमेव उत्तरदायी; अहं सुखं भोक्तुं जातः, तदर्थम् आवश्यकाः जनः धनम् अधिकारः च मयि सन्ति; स्वेच्छानुगुणम् अहं वर्तिष्ये; धनेन किमपि क्रेतुं शक्नोमि; मया सदृशः अस्मिन् जगति कः अस्ति?\" -- इत्यादीनि एतेषां चिन्तनानि। प्रदर्शनार्थं यज्ञयागादीन् करणम्, दानं दानम् इति एतेषां निरन्तरा क्रियाशीलता। इदम् अज्ञानस्य नाट्यम्। इदं तेषां सर्वनाशस्य महाद्वारम् इति अवबोधः एतेषां न भवति। तदेव महत्त्वम्, तदेव सुभगत्वम् इति भ्रमे एते जीवन्ति।",
  "16.16": "अनेक चित्त विभ्रांताः मोहजाल समावृताः ।\nप्रसक्ताः कामभोगेषु पतंति नरके अशुचौ ॥\n\nबहुविधैः चिन्तनैः विभ्रान्ताः, मोहस्य जाले आवृताः, कामभोगेषु आसक्ताः -- ते अशुचौ नरके पतन्ति।\n\nएते स्वजीवने पूर्वं घटितानि घटनानि सदा स्मृत्वा विभ्रान्ताः भवन्ति। एते कदापि स्वदोषाय पश्चात्तापं न कुर्वन्ति। सात्त्विकाः पश्चात्तापं कृत्वा दोषं सुधारयन्ति, परं एते सदा भयानकस्य अज्ञानस्य ममकाराख्यस्य मोहस्य जाले निबद्धाः भूत्वा अधिकतरं विभ्रान्ताः भवन्ति -- न सुधार्यन्ते। स्वेप्सितं वस्तु भुञ्जानाः तत्रापि अतृप्ताः पुनः सङ्ग्रहं कृत्वा संरक्ष्य स्थातुं प्रवृत्ताः भवन्ति। एते अग्रे अशुचौ नरके पतित्वा आन्दोलितव्याः भवन्ति।",
  "16.17": "आत्मसंभाविताः स्तब्धाः धन मानम् मद अन्विताः ।\nयजंते नामयज्ञैः ते डंभेन अविधि पूर्वकम् ॥\n\nस्वं स्वयं महात्म्ये स्थापयन्तः, अनम्राः, धनसम्मानयोः मदेन युक्ताः। एते नाममात्रैः यज्ञैः, डम्भेन, शास्त्रविधिं विना यजन्ते।\n\nएतेषां स्वस्य विषये स्वयमेव श्लाघा। \"अविद्यायाम् अन्तरे वर्तमानाः स्वयं धीराः पण्डितं अन्यमानाः\" इति यथोक्तम्, अन्येभ्यः स्वस्य उपरि गौरवम् अस्ति नास्ति इति न ज्ञातम्, परं स्वस्य विषये स्वयमेव महत्त्वज्ञानं वर्धयित्वा तेन स्तब्धतया स्फीयन्ते। एतेषाम् अस्य स्तब्धत्वस्य कारणं ज्ञानं न, अपि तु हस्ते विद्यमानस्य धनस्य मदः; तस्य धनस्य कृते जनैः दत्तं सम्मानम्। एते डम्भाय, महत्त्वस्य प्रदर्शनाय यज्ञयागादीन् कारयन्ति। तत्र शास्त्रस्य सावधानता न भवति; भगवान् प्रीणीयात् इति उद्देशेन रहितां, अन्तर्यामिणं भगवन्तं विस्मृत्य कृतां पूजा सा भवति।",
  "16.18": "अहंकारं बलं दर्पं कामं क्रोधं च संश्रिताः ।\nमाम् आत्म परदेहेषु प्रद्विषंतः अभ्यसूयकाः ॥\n\nअहङ्कारं, बलस्य दर्पं, कामं क्रोधं च आश्रिताः। स्वस्य परस्य च देहेषु विद्यमानं मां अश्रद्दधानाः निराकुर्वन्तः। अन्यस्य उन्नतौ ईर्ष्यां कुर्वन्तः।\n\nएतेषां मूला सम्पत्तिः -- अहङ्कारः, दर्पः, कामः क्रोधश्च। \"मां अतिक्रमन्तः के सन्ति? अहमेव महान् मनुष्यः\" इति अहङ्कारः। तस्मै बलं धनं अधिकारबलं च आश्रयः। अनेन अन्यान् तिरस्कारेण पश्यन् दर्पः। अतृप्ताः इच्छाः, ताः न पूर्येरन् इति क्रोधः -- इदमेव एतेषाम् अस्तित्वम्। कृष्णः वदति -- \"सर्वेषाम् अन्तः स्थितं 'माम्' अश्रद्दधानाः निराकुर्वन्ति\" इति। इदं केनापि कारणनिमित्तेन तात्कालिकतया भगवन्तं निराकरणं न, अपि तु स्वरूपतः भगवन्तं निराकरणम्। एतादृशाः अन्यस्य ज्ञानं धनसम्पत्तिं च दृष्ट्वा सदा ईर्ष्यां कुर्वन्ति।",
  "16.19": "तान् अहं द्विषतः क्रूरान् संसारेषु नर अधमान् ।\nक्षिपामि अजस्रम् अशुभान् आसुरीषु एव योनिषु ॥\n\nपरतत्त्वं द्विषतः, क्रूरान्, नराधमान्, अशुभान् तान् अहं निरन्तरं संसारे, आसुरीषु एव योनिषु क्षिपामि।\n\nभगवान् जीवं न सृजति; मूलतः जीवः जीवस्वभावश्च अनादिनित्यौ इति वयं पूर्वं ज्ञातवन्तः। आसुरस्वभावः इत्युक्ते मूलतः जीवस्वभावः। यथा करेलफलं तिक्तम्, तथा एतेषाम् आसुराणां जीवस्वभावः तामसः। तं भगवान् न परिवर्तयति। अपि तु तस्य जीवस्य स्वभावानुगुणं जीवस्य गतिः निर्मीयते। भगवन्तं द्विषतः, मनुकुलं द्विषतः, प्रपञ्चमेव द्विषतः एतान् क्रूरान् भगवान् निरन्तरं संसारसागरे क्षिपति। अनेन ते पुनः पुनः हीनकुले जन्तव्याः भवन्ति।",
  "16.20": "आसुरीं योनिम् आपन्नाः मूढाः जन्मनिजन्मनि ।\nमाम् अप्राप्य एव कौंतेय ततः यांति अधमां गतिम् ॥\n\nहे कौन्तेय, आसुरीं योनिं प्राप्ताः ते मूढाः जन्मनि जन्मनि माम् अप्राप्यैव, ततः अधमां गतिं यान्ति।\n\nएवं हीनकुले पुनः पुनः जन्तव्याः एते दुष्टाः प्रत्येकं जन्मनि मूढतराः भवन्ति गच्छन्ति। प्रत्येकं जन्मनि एतेषां भगवति द्वेषः पराकाष्ठां गच्छति। अहङ्कारः, मदः, दर्पः, कामक्रोधौ अतिशयं गत्वा एते स्वयमेव अधःपातं प्राप्नुवन्ति। एते कदापि भगवन्तं न प्राप्नुवन्ति। एते स्वजीवस्वभावस्य गत्यनुगुणं तामसलोकं प्राप्नुवन्ति।\n\nआसुराणां जीवस्वभावं, तेषाम् आचरणवाक्चिन्तनकृत्यानां विषयं सुन्दरतया कृष्णः विवृतवान्। अनेन अस्मभ्यं लोके लोककण्टकाः किमर्थं सन्ति, ते अग्रे कां गतिं प्राप्नुवन्ति इति विषयः ज्ञायते। अस्मदज्ञाततया अस्मान् आसुरगुणः पीडयति यदा वयं ज्ञानस्य अवबोधेन भगवति शरणं गत्वा, तस्मात् मुक्तिम् इच्छितुम् अयम् अध्यायः साहाय्यं करोति। जीवस्य स्वभावः कदापि न परिवर्तते। जीवाय स्वतन्त्रं कर्तृत्वं नास्ति। परं जीवाय इच्छापूर्विका कृतिः अस्ति। अस्यानुगुणं निरन्तरं दैवीस्वभावं वर्धयित्वा भगवन्तं प्राप्तुं यत्नं वयं कुर्याम। तस्य फलं लभ्यते वा न लभ्यते वा तत् भगवतः इच्छा -- अस्मात् वयं शिरः न पीडयेम। शुभम् इच्छ, सज्जनः भूत्वा यत् प्राप्तं तेन सन्तुष्टः जीव। तव रक्षायाः भारः भगवतः, सः त्वां रक्षति एव रक्षति।",
  "16.21": "त्रिविधं नरकस्य इदं द्वारं नाशनम् आत्मनः ।\nकामः क्रोधः तथा लोभः तस्मात् एतत् त्रयम् त्यजेत् ॥\n\nएतानि त्रीणि आत्मनाशस्य मार्गाणि, नरकस्य द्वाराणि -- कामः, क्रोधः, लोभः। अतः एतानि त्रीणि दूरे स्थापनीयानि।\n\nएषः श्लोकः अतिमुख्यं सन्देशं ददत् श्लोकः। विदुरनीत्यामपि एषः श्लोकः आगच्छति। सामाजिकतया आध्यात्मिकतया च महाभारतम् इदम् उल्लिखति। अत्र कृष्णः आत्मनाशाय कारणभूतान् त्रीन् अंशान् विवृतवान्। ते सन्ति काम-क्रोध-लोभाः। एते \"मानवस्य नरकद्वाराणि\" इति वदति कृष्णः। क्रोधः इत्युक्ते कामस्य शिशुः। अस्मासु क्रोधः आगच्छति इत्युक्ते अस्मदन्तः बहवः इच्छाः निहिताः इत्यर्थः। सा न सिध्येत् यदा अस्मभ्यं कोपः। महाभारतस्य अनुशासनपर्वणि एका कथा अस्ति। एका ब्राह्मणी स्त्री, तस्याः नाम गौतमी। तस्याः एकः एव पुत्रः। एकदा सर्पदष्टः सन् सः म्रियते। इदं दृष्ट्वा कश्चित् सर्पग्राही, तत्क्षणम् एव तं सर्पं गृहीत्वा तस्याः पुरतः आनीय -- \"वद, तव पुत्रं दष्ट्वा घातयत् इमं सर्पं केन प्रकारेण त्वं हन्तुम् इच्छसि\" इति पृच्छति। तदा सा वदति -- \"न ब्राह्मणानां कोपः असति कृतः कोपात् च यातना... (१३-०१-२०)\"। \"वयं ब्राह्मणाः, ब्राह्मणाय कोपः न आगच्छति, आगच्छेत् चेत् सः ब्राह्मणः एव न\" इति। सर्पं घातयित्वा मृतः पुत्रः पुनः न जीवति। मम पुत्रः तस्य कर्मानुगुणं मृतः। अतः कोपः दुःखं वा उचितं न, त्यज तं सर्पम्\" इति सा वदति स्म। यस्मै अवबोधः अस्ति, इच्छाः न सन्ति -- तादृशेभ्यः कोपः न आगच्छति। ते यथार्थाः ब्राह्मणाः इति उच्यन्ते। \"काम-क्रोध-लोभाः अस्मान् अधःपातं प्रति क्षिपन्ति त्रीणि नरकद्वाराणि, तेभ्यः दूरं तिष्ठ\" इति कृष्णः अत्र अस्मान् सावधानान् करोति। एतानि अस्मदीयं व्यक्तित्वं नाशयन्तः मूलशत्रवः। अन्ये सर्वे दुर्गुणाः एतेषाम् एव शिशवः। मनुष्यः एतैः त्रिभिः दुर्गुणैः स्वनरकं स्वयमेव सृजति। एतानि त्रीणि त्यक्ते सति इहापि सुखम्, परत्रापि सुखम्।",
  "16.22": "एतैः विमुक्तः कौंतेय तमः द्वारैः त्रिबिः नरः ।\nआचरति आत्मनः श्रेयः ततः याति परां गतिम् ॥\n\nहे कौन्तेय, नरकस्य एतेभ्यः त्रिभ्यः द्वारेभ्यः पारं गतः नरः स्वस्मै श्रेयस्करं कर्तुं शक्नोति। तेन उत्तमां गतिं प्राप्नोति।\n\nनरकस्य एतेभ्यः त्रिभ्यः द्वारेभ्यः पारं गतः मानवः पुण्यात्मा। तस्मै मोक्षमार्गः सुगमः भवति। सः उत्तमां गतिं प्राप्नोति। अत्र कृष्णः \"विमुक्तः\" इति पदं प्रयुक्तवान्। अस्य अर्थः सर्वाः इच्छाः त्यागः न, अस्मदीयं जीवनं बाधकाः राजसाः तामसाः च इच्छाः त्यागः इत्यर्थः। उदाहरणार्थं भगवन्तं प्राप्तव्यम् इति अपि एका इच्छा। इयं नरकद्वारं न। इयं त्याज्या नास्ति। इच्छां विना जीवनं नास्ति। अतः अत्र वयं त्याज्या केवलं राजसं तामसं च अंशम्। इदं सूचयितुम् अत्र \"मुक्तः\" इति अनुक्त्वा \"वि-मुक्तः\" इति उक्तम्।\n\nअत्र \"कौन्तेय\" इति विशेषणं प्रयुक्तम्। \"वयं ज्ञानमार्गे गन्तुं चेत् कुत्सितान् एतान् काम-क्रोध-लोभान् तिरस्कारं कुर्वतः कौन्तेयाः भवेम\" इति सन्देशः अस्य विशेषणस्य पृष्ठे ध्वनिः।\n\nअस्मासु केषुचित् शास्त्रस्य विधिविधानं किमर्थम् आवश्यकम्, आत्मसाक्षिणा जीवितं चेत् न पर्याप्तं किम् इति प्रश्नः अस्ति। कृष्णः अग्रिमे श्लोके शास्त्रस्य विधिविधानपालनस्य महत्त्वं विवृणोति।",
  "16.23": "यः शास्त्रविधिम् उत्सृज्य वर्तते कामकारतः ।\nन सः सिद्धिम् अवाप्नोति न सुखं न परां गतिम् ॥\n\nशास्त्रस्य नियमम् अतिक्रम्य स्वेच्छानुगुणं वर्तमानः सिद्धिं न प्राप्नोति। तस्मै सुखं नास्ति, परमा गतिः अपि नास्ति।\n\nवयं शास्त्रस्य नियमं त्यक्त्वा स्वयमेव प्रामाणिकतया जीवितुं न शक्नुमः। यतः अस्मभ्यं किं सम्यक्, किम् असम्यक् इति परिज्ञानं न भवति। अस्मभ्यम् इष्टं यत् तत् सम्यक् इति वयं ज्ञातुम् अर्हामः। अस्मभ्यं परिज्ञानं ददति ते शास्त्राणि। जगतः अनेकान् विषयान् अस्मदीये अनुष्ठाने अवलम्बयितुं केवलम् आत्मशक्तिः प्रामाणिकता च न पर्याप्ते। इदं सम्यक्, इदम् असम्यक् इति निर्णेतुं शास्त्राणि अपेक्षितानि एव। वयम् अस्मदीयेन अनुभवेन सम्पूर्णं जगत् ग्रहीतुं न शक्नुमः। अस्मदीया बुद्धिः सीमिता, अस्मदीयः तर्कः सीमितः, अस्मदीया आत्मसाक्षिता सीमिता, अस्मदीया प्रामाणिकता सीमिता। एवं सति सीमितेन अनुभवेन वयं सम्पूर्णस्य विश्वस्य सत्यं ज्ञातुं न शक्नुमः। अस्मात् कारणात् भगवान्, तेन जगते दत्तानि वेदादिशास्त्राणि, तानि शास्त्राणि अवगत्य अस्मभ्यं ज्ञापितवन्तः देवज्ञाः ज्ञानिनः -- एतेभ्यः वयं सत्यम् अवगच्छेम। अन्यथा सिद्धिः असाध्या।",
  "16.24": "तस्मात् शास्त्रम् प्रमाणं ते कार्य अकार्य व्यवस्थितौ ।\nज्ञात्वा शास्त्र विधान उक्तम् कर्म कर्तुम् इह अर्हसि ॥\n\nअतः कार्यम् अकार्यं च निर्णेतुं तव प्रमाणं शास्त्रमेव। शास्त्रस्य विधानम् अवगत्य इह कर्म कर्तुम् अर्हसि।\n\nसमस्तेभ्यः आवश्यकानावश्येभ्यः शास्त्रमेव प्रमाणम्। अतः वयं शास्त्रे उक्तं प्रथमं विश्वसेम। तदा तत् अवगन्तुं शक्यं भवति। शास्त्रे \"एवं कुरु, एवं मा कुरु\" इति उक्तवन्तः -- तेन जायमानं परिणामं साक्षात्कृतवन्तः ज्ञानिनः। अतः कर्मणः नियमम् अवगत्य कर्म कुरु इति वदति कृष्णः।\n\nअत्र शास्त्रम् इत्युक्ते चत्वारः वेदाः तस्मै पोषकाणि पञ्चरात्रम्, महाभारतम्, मूलरामायणम्, अष्टादश पुराणानि च। एतद् विहाय अन्यत् किमपि पूर्णतया प्रमाणतया स्थापयितुं न शक्यम्।\n\nइति षोडशोऽध्यायः।",
  "17.1": "अर्जुनः उवाच\n\nये शास्त्रविधिम् उत्सज्य यजंते श्रद्धया अन्विताः ।\nतेषां निष्ठा तु का कृष्ण सत्त्रम् आहो रजः तमः ॥\n\nकेचन शास्त्रस्य नियमम् अज्ञात्वापि श्रद्धया आचरन्ति। तेषां निष्ठा कीदृशी, हे कृष्ण? सा सात्त्विकी, राजसी, उत तामसी?\n\nवयं वेदाध्ययनं न कृतवन्तः, अस्मभ्यं शास्त्रस्य विधिः न ज्ञातः, परं शास्त्रम् अज्ञातत्वात् पश्चात्तापः अस्ति; शास्त्रे श्रद्धा अस्ति, तदनुगुणं जीवितुम् इच्छा अस्ति। ज्ञातारः वदन्ति -- \"यत् एव विद्यया करोति श्रद्धया...\" इति। अर्थात् \"यत् किमपि करोषि तत् ज्ञात्वा कुरु। ज्ञानपूर्वकं कृतं कर्म सफलम्। अन्यथा तत् व्यर्थम्\" इति। एवं सति श्रद्धया कृतं कर्म व्यर्थं किम्? इदम् अर्जुनस्य प्रश्नः।\n\nअत्र \"श्रद्धा\" इत्युक्ते अतीन्द्रियायाः, अस्मान् नियन्त्रयन्त्याः अगोचरायाः शक्तेः विषये अस्मासु विद्यमानः विश्वासः। अर्थात् भगवति विश्वासः, शास्त्रे विश्वासः, पापपुण्ययोः विश्वासः, सर्वं नियन्त्रयन्ती परा शक्तिः अस्ति इति विश्वासः। महाभारते उक्तं यथा -- \"कर्मणे फलम् अस्ति\" इति विश्वास एव मनुष्यस्य जीवनस्य आधारस्तम्भः। एवं सति विश्वासेन सह श्रद्धा अस्ति, शास्त्रज्ञानं नास्ति चेत् तेषां निष्ठा का? \"सर्वान् कर्षणं कुर्वन् (कृष्णः) त्वं एतादृशान् कुत्र कर्षणं करोषि? तेषां निष्ठा सात्त्विकी, राजसी, उत तामसी?\" इति अस्मदीयं सर्वेषां विद्यमानं विभ्रान्तिं प्रश्नं अर्जुनः कृष्णं पृच्छति।",
  "17.2": "भगवान् उवाच\n\nत्रिविधा भवति श्रद्धा देहिनां सा स्वभावजा ।\nसात्विकी राजसी च एव तामसी च इति तां शृणु ॥\n\nदेहधारिणां जन्मस्वभावादेव उद्भवन्ती इयं श्रद्धा त्रिविधा -- सात्त्विकी, राजसी, तामसी च। तस्याः प्रकारं शृणु।\n\nसाधनाशरीरे विद्यमानाः जीवाः मूलतः त्रिविधाः भवन्ति। ते सात्त्विकाः, राजसाः, तामसाश्च। अनेन परिसरस्य कुलस्य च प्रभावेण मानसिकतया वयं पुनः त्रिविधां श्रद्धां वर्धयामः। अतः स्वरूपतः सात्त्विकः अपि सन् सः मानसिकतया राजसः स्यात्, अथवा तामसः स्यात्। उदाहरणार्थं स्वरूपतः सात्त्विकाः गर्गाचार्याः तामसप्रभावम् आपन्नाः कृष्णं पराजयितुं पुत्रं जनयितुं तपः आचरितवन्तः इति कथां पूर्वं दृष्टवन्तः। मानसिकतया आगच्छन्ती इयं बाह्या श्रद्धा जन्मजन्मान्तरस्य न। परं स्वरूपश्रद्धा प्रत्येकं जन्मनि सदा जीवेन सह भवति। इदं स्पष्टीकर्तुम् अस्मिन् श्लोके \"एव\" \"च\"-कारं च सह प्रयुक्तम्। जीवस्वरूपम् -- सात्त्विकैव, राजस्येव, अथवा तामस्येव -- तत् न परिवर्तते। अस्य स्वरूपस्य उपरि विद्यमाना बाह्या श्रद्धा -- सात्त्विके च, राजसे च, तामसे च -- प्रभावेण आगच्छन्ती, गरिष्ठं एकं जन्मपर्यन्तं मिश्रिता भवति। \"एतत् त्रिविधां श्रद्धायाः प्रकारं शृणु\" इति कृष्णः अर्जुनं वदति।",
  "17.3": "सत्व अनुरूपा सर्वस्य श्रद्धा भवति भारत ।\nश्रद्धा मयः अयम् पुरुषः यः यत् श्रद्ध सः एव सः ॥\n\nहे भारत, स्वभावानुगुणम् एव सर्वेषां श्रद्धा भवति। अयं जीवः श्रद्धास्वरूपः एव। यस्य या श्रद्धा, सः तादृशः।\n\nजीवस्य स्वरूपानुगुणम् एव मूला श्रद्धा भवति। परं कदाचित् सा अव्यक्ता भवितुम् अर्हति। सा अव्यक्ता भवति यदा, मनसि या बाह्या प्रभावश्रद्धा अस्ति सैव तस्य निष्ठा भवति। मनुष्यः श्रद्धायाः क्रीडापुत्रिका इव। यस्य स्वरूपश्रद्धा सात्त्विकी सः सात्त्विकः; यस्य स्वरूपश्रद्धा राजसी सः राजसः; यस्य स्वरूपश्रद्धा तामसी सः तामसः। एवं जीवेषु त्रिविधाः -- सात्त्विकी श्रद्धा यस्मिन् जीवे सः सात्त्विकः जीवः; राजसी श्रद्धा यस्मिन् सः राजसः जीवः; तामसी श्रद्धा यस्मिन् सः तामसः जीवः। वयं ध्यानेन मनः स्तब्धं कृत्वा तुरीयां स्थितिं प्राप्नुमः यदा बाह्या श्रद्धा अन्तर्हिता भूत्वा केवला स्वरूपश्रद्धा व्यक्ता भवति।",
  "17.4": "यजंते सात्विकाः देवान् यक्षरक्षांसि राजसाः ।\nप्रेतान् भूतगणान् च अन्ये यजंते तामसाः जनाः ॥\n\nसात्त्विकानां पूजा देवताभ्यः प्राप्नोति। राजसानां सा यक्षराक्षसेभ्यः। तामसानां पूजा प्रेतेभ्यः भूतगणेभ्यश्च प्राप्नोति।\n\nएतं श्लोकं उपरिदृष्ट्या पश्येम चेत् किमपि न अवगम्यते। उपरिदृष्ट्या \"सात्त्विकाः देवताः पूजयन्ति, राजसाः यक्षराक्षसान्, तामसाः च भूतप्रेतान् पूजयन्ति\" इति उक्तम् इव भासते। परं अत्र निहितः मूलः अर्थः भिन्नः एव। अस्माभिः ज्ञातं यत् सात्त्विकाः वा राजसाः वा तामसाः वा -- ते पूजां कुर्वन्ति भगवन्तं वा देवताः वा। वामाचारं (Witchcraft) कुर्वतः विहाय अन्ये कोऽपि प्रेतपिशाचराक्षसान् न पूजयन्ति। अतः अत्र उक्तं मूलं सन्देशम् अवगन्तुं वयम् इमं श्लोकं गभीरतया विश्लेषयेम। अत्र \"देवान्\" इत्युक्ते भगवतः अनेकानि रूपाणि, भगवतः परिवारदेवताश्च इत्यर्थः। \"यजन्ते सात्त्विकाः देवान्\" इत्युक्ते -- सात्त्विकाः भगवतः अनुसन्धानेन कुर्वती पूजा देवताः प्राप्नोति इत्यर्थः। तथैव \"यक्षरक्षांसि राजसाः\" इत्युक्ते -- राजसाः कुर्वती पूजा यक्षराक्षसान् प्राप्नोति इत्यर्थः। राजसाः सामान्यतः भगवतः पारम्यस्य अवबोधं विना, भयेन, देवताः अस्मान् कष्टं न ददतु इति मन्नतस्वीकरणभावनया पूजां कुर्वन्ति। एवं पूजायां कृतायां वयं भगवते अर्पयितुं कृतां पूजां देवतानाम्नः यक्षराक्षसाः आगत्य स्वीकुर्वन्ति। इतः तृतीयः वर्गः तामसः। एते पूजां कुर्वन्ति स्वस्य अन्तस्तं (स्तरं) दर्शयितुम्। उदाहरणार्थं दुर्योधनः पाण्डवैः कृतम् अश्वमेधयागं अतिक्रमितुं पौण्ड्रिकयागं कारितवान् इव। एवं दुरुद्देशेन तामसैः कृतां पूजां आगत्य स्वीकुर्वन्तः देवतानाम्नः भूतप्रेताः।\n\nपूजायां केवलं श्रद्धा मुख्या न, अपि तु सा कीदृशी श्रद्धा इति मुख्यम्। शास्त्रं अज्ञातमपि सत्त्वा, सात्त्विकया श्रद्धया -- \"भगवन्, मह्यं किमपि न ज्ञातम्, अहं भक्त्या त्वाम् आराधनां करोमि, मम दोषं क्षमस्व\" इति शरणागत्या याचिते सति तां पूजां स्वयं भगवान् एव आगत्य स्वीकरोति। परं स्वार्थेन, अहङ्कारेण, डम्भेन च कृतां राजसीं वा तामसीं वा पूजां भगवान् वा तस्य परिवारदेवताः वा न स्वीकुर्वन्ति।\n\nअस्मदीयं कर्म काम-रहितं (निष्काम) भवेत्। अत्र कामः इत्युक्ते दुष्टा इच्छा। इच्छायां कदापि स्वार्थः न स्यात्। \"केवलं मह्यं शुभं भवतु\" इति सङ्कुचितां भावनां वयं त्यजेम।\n\nपूजापुनस्कारं कुर्वन्तः वयं कयाचित् सङ्कुचितया इच्छया पूजां न कुर्याम। उदाहरणार्थम् -- \"मम व्यवहारे उन्नतिः भवतु\" इति यज्ञं करणम्; \"पुत्र्यै उत्तमः वरः लभताम्\" इति फलापेक्षया पूजां करणम् इत्यादि। वयं भगवति एवं स्वेच्छानां सूचीं न दद्याम। किं भवितव्यम् इति भगवते ज्ञातम्। किं शुभं किं दुष्टं इति सः एव जानाति। तत् सः ददाति एव। एवं सति वयम् एतादृशीं सङ्कुचितां कामसूचीं धृत्वा कर्म कुर्मः चेत् जायमानं अनर्थं घोरम्। वयं भगवति कांचन इच्छां स्थापयित्वा पूजां कारयामः। तस्यै पूजायै धनव्ययं कुर्मः। परं सा इच्छा न सिध्यति। तदा अस्मभ्यं देवस्य उपरि द्वेषः, धनं व्यर्थम् अभवत् इति असन्तोषः। एवं भवति अस्मदीया पूजा व्यापारः भूत्वा भूतप्रेतान् प्राप्नोति। देवस्य पूजा व्यापारः न।",
  "17.5": "अशास्त्रविहितं घोरं तप्यंते ये तपो जनाः ।\nडंभाहंकारसंयुक्ताः कामरागबलान्विताः ॥\n\n[एतयोः द्वयोः श्लोकयोः (१७.५ तथा १७.६) पदच्छेदः, अर्थः, विवरणं च सह अग्रिमे श्लोके (१७.६) दत्तम्।]",
  "17.6": "अशास्त्र विहितं घोरं तप्यंते ये तपः जनाः ।\nडंभ अहंकार संयुक्ताः काम राग बल अन्विताः ॥\n\nकर्शयंतः शरीरस्थं भूतग्रामम् अचेतसः ।\nमां च एव अंतः शरीरस्थं तान् विद्धि आसुरनिश्चयान् ॥\n\nकेचन जनाः शास्त्रस्य नियमम् अतिक्रम्य दुष्टं तपः आचरन्ति। ढोंगित्वेन गर्वेण च। इच्छाआसक्ती एव तेषां साधनायाः बलम्। एतादृशाः अज्ञानाः स्वदेहे विद्यमानं भूतसमूहं [देहनियामकं देवतागणम्] उपेक्षन्ते। देहान्तः स्थितं मम माहात्म्यं निराकुर्वन्ति। एतादृशाः तामसस्वभावाः इति जानीहि।\n\nश्रद्धासु अपि सर्वनिकृष्टा तामसी श्रद्धा कीदृशी इति कृष्णः अत्र विवृणोति। केचन शास्त्रस्य नियमम् अतिक्रम्य तपः आचरन्ति। तस्य तपसः पृष्ठे विद्यमानम् उद्देश्यं घोरम्। अत्र तपः इत्युक्ते केवलं ऋषिमुनिभिः कृतं तपः न। श्रद्धया कृता या काचित् क्रिया तपः भवितुम् अर्हति। [अस्य विषयस्य अधिकं विवरणं अस्य अध्यायस्य अग्रिमे भागे (श्लोक १४-१९) द्रष्टुं शक्यते।] तपः कुर्वन्तः वयं \"मह्यं शुभं भवतु\" इति तपः कर्तुं शक्नुमः, अथवा \"लोकाय शुभं भवतु\" इति तपः कर्तुं शक्नुमः। उदाहरणार्थं गायत्री। अत्र \"धियो यो नः प्रचोदयात्\" इत्यत्र \"अस्मभ्यं सर्वेभ्यः सद्बुद्धिं देहि देव\" इति सात्त्विकी श्रद्धा अस्ति। लोके सर्वेभ्यः शुभं भवतु इति कृतं तपः सात्त्विकं तपः। एतद् विहाय \"मह्यमेव शुभं देहि\" इति कृता पूजा राजसी। \"अन्ये नाशं गच्छेयुः, अहमेव शुभं गच्छेयम्\" इति कृता पूजा तामसी। इमाः लोककण्टकाः घोराः श्रद्धाः।\n\nशास्त्रविहितं तपः इत्युक्ते -- भगवतः पारम्यम् अवगत्य, अन्यस्य विषये दुष्टं चिन्तनं अकृत्वा, लोके सर्वेभ्यः शुभं भवतु इति कृतं तपः। \"सर्वोत्कर्षे देव देवस्य विष्णोः महातात्पर्यम्\" -- समस्तशास्त्राणां तात्पर्यम् -- \"भगवान् सर्वोत्तमः\" इति। इदम् अस्वीकृत्य स्थातुम् एव शास्त्रविरुद्धम्। इदम् अङ्गीकृत्यापि लोकाय दुष्टं भवतु इति भावना मनसि उदेति चेत् तदपि अशास्त्रविहितं भवति। यत् शास्त्रविहितं न भवति तत् भगवते न प्रियम्। अन्यस्य विषये दुष्टम् इच्छित्वा, स्वार्थेन कृतं कर्म \"घोरा क्रिया\" इति भवति -- इदं सावधानतां कृष्णः अत्र ददाति। एतादृश्याः क्रियायाः पृष्ठे डम्भाचारः अहङ्कारश्च भवतः। इदं देवताः कदापि न स्वीकुर्वन्ति।\n\nकेचन स्वदैहिकबलेन अन्यान् वशीकर्तव्यम् इति दुष्टम् उद्देश्यं धृत्वा तपः आचरन्ति। ये तेषाम् इच्छाभ्यः विघ्नं कुर्वन्ति, तेषाम् इष्टानिष्टाभ्यां न स्पन्दन्ते, तादृशान् नाशयितव्यम् इति दुष्टं चिन्तनम् एतेषां मनसि वर्तते। एवं डम्भेन, अहङ्कारेण, सङ्कुचितेन कामेन, स्वार्थेन, बलेन कर्म कुर्वन्तः अज्ञानाः। एते स्वदेहं दण्डयित्वा तपः आचरन्ति, परं तेभ्यः स्वदेहे विद्यमानस्य भूतग्रामस्य (देवतासमूहस्य) जागृतिः न भवति। समस्तं देवतागणं निर्लक्ष्यं कृत्वा, देवतानाम् अन्तः स्थितं भगवन्तमपि निर्लक्ष्यं कृत्वा, देहदण्डनां कृत्वा अनुष्ठानं कुर्वन्तः एते आसुराः इति उच्यन्ते। एते \"इन्द्रियकर्म एव सर्वस्वम्, ततः परम् किमपि नास्ति\" इति ज्ञातवन्तः भवन्ति।\n\nकृष्णस्य एतत् विवरणं दृष्ट्वा अस्मासु विद्यमानः आसुरः (प्रभावेण वर्धितः) अन्धश्रद्धा कियती भयानका इति अंशः अस्मभ्यं ज्ञायते। इदं वयम् अस्मदीयायां प्रत्येकायां क्रियायाम् अभिज्ञाय सुधारयेम। अस्मात् कृष्णः अग्रिमेषु श्लोकेषु आहारे, तपसि, दाने इत्यादिषु सात्त्विकं राजसं तामसं च प्रभेदं कीदृशम् इति विवृणोति।",
  "17.7": "आहारः तु अपि सर्वस्य त्रिविधः भवति प्रियः ।\nयज्ञः तपः तथा दानं तेषां भेदम् इमम् शृणु ॥\n\nसर्वेषां प्रियः आहारः अपि त्रिविधः भवति। तथैव यज्ञः, तपः, दानम् अपि। तेषां भेदम् एनं शृणु।\n\nअस्माभिः भुज्यमानः आहारः अपि त्रिविधः भवति -- सात्त्विकः, राजसः, तामसः च। \"अन्नम् अशितं त्रेधा विधीयते\" (छान्दोग्योपनिषत् ५-१) इति यथोक्तम्, अस्माभिः सेव्यमानम् आहारम् अस्मदन्तःस्थौ प्राणः वैश्वानरश्च त्रिधा (सूक्ष्मं, मध्यमं, स्थूलं च) विभज्य देहस्य विविधेभ्यः भागेभ्यः आपूर्तिं कुरुतः। अस्मदीयस्य आहारस्य मनसश्च सम्बन्धः प्रत्यक्षः। इदम् अस्मदीयाः प्राचीनाः ज्ञातवन्तः। अतः मनसः उपरि प्रभावं कुर्वन्तम् आहारं ते निषिद्धवन्तः। उदाहरणार्थं लशुनम्। इदम् औषधीयं वस्तु। परं इदं नित्याहारे उपयोक्तुं निषिद्धम्। यतः इदम् अस्मदीयायाः बुद्धेः वृद्ध्यै पोषकं न। तथैव शोभाञ्जनं, कुन्दुरुफलं च। अध्ययनं कुर्वद्भ्यः इदं निषिद्धम् (औषधतया उपयोक्तुं शक्यते)। एवं मनुष्यस्य बुद्धये कीदृशः आहारः उचितः इति सर्वप्रथमवारं कृष्णः जगते दत्तवान्।\n\nआहारेण सह वयं कुर्वती देवपूजा, तपः, अस्मदीयः चिन्तनक्रमः, दानम्, जीवनस्य आचरणम्, वाणी -- एतत् सर्वं त्रिविधं द्रष्टुं शक्यते। अग्रिमेषु श्लोकेषु कृष्णः आहारे, यज्ञे, तपसि, दाने च इमं त्रिविधं प्रकारं कथम् अभिज्ञातव्यम् इति विवृणोति।",
  "17.8": "आयुः सत्व बल आरोग्य सुख प्रीति विवर्धनाः ।\nरस्याः स्निग्धाः स्थिरा हृद्याः आहाराः सात्विक प्रियाः ॥\n\nआयुष्यं, सत्त्वगुणं, बलम्, आरोग्यं, सुखं, प्रीतिं च वर्धयन्तः; रसयुक्ताः, स्निग्धाः, स्थिराः, हृदयङ्गमाः आहाराः सात्त्विकेभ्यः प्रियाः।\n\nअस्मिन् श्लोके कृष्णः सात्त्विकाहारस्य विषये विवृतवान्। यः आहारः अस्मदीयस्य आयुषः वृद्ध्यै पोषकः; यः आहारः अस्मभ्यं सौम्यस्वभावं ददाति; यः आहारः देहाय पौष्टिकांशं ददाति; यः आहारः आरोग्यं ददाति -- तादृशः आहारः सात्त्विकः आहारः। एतम् आहारं दृष्ट्वा अस्मभ्यं दुष्टभावना न जायते। सः रसयुक्तः भवति, रुचिकरः भवति। एतत् भक्षिते सति अस्मदीयम् उदरं पूर्यते, तत्क्षणं क्षुधा न भवति। द्रष्टुं हृदयङ्गमः भवति, भक्षितस्य स्मृतिः अवशिष्यति एवम्भूतः भवति।\n\nयथार्थाः सात्त्विकाः यत् भक्षयन्ति तत् सात्त्विकः आहारः। प्रकृतिसहजाः, रसयुक्ताः, रुचिकराः फलानि, कन्दमूलानि, धान्यानि, कन्दाः -- सामान्यतः सात्त्विकः आहारः भवन्ति। आयुष्यं वर्धयत् शुद्धं घृतम् (मितं प्रयुक्तं) सात्त्विकः आहारः।",
  "17.9": "कट्वम्ल लवणात्युष्ट तीक्षरूक्ष विदाहिनः ।\nआहारा राजसस्येष्टा दुःखशोकामयप्रदाः ॥\n\nतीक्ष्णाः, अम्लाः, लवणयुक्ताः, अतिशयेन उष्णाः, तीक्ष्णाः, रूक्षाः, दाहजनकाः आहाराः राजसेभ्यः इष्टाः। एते दुःखं, शोकं, रोगं च ददति।\n\nअत्र राजसाहारस्य विवरणं कृष्णः दत्तवान्। अतिशयेन तीक्ष्णं, अतिशयेन अम्लं, अतिशयेन लवणयुक्तं -- राजसः आहारः इति उच्यते। अतिशयेन उष्णं पानम्; रूक्षं निःसारम् आहारम् आस्वादनम्; हृदयदाहकम् आहारसेवनम् -- एतानि राजसानां लक्षणानि। एतस्य आहारस्य सेवनेन मानसिकं शारीरिकं च दुःखं वर्धते। इदं रोगं जनयितुं शक्तः आहारः।\n\nहरितमरिचस्य फलं साक्षात् भक्षणम्, तिन्तिडीफलम् अतिशयेन भक्षणम्, सदा अधिकं लवणं प्रयोगः, कण्ठदाहकं कफी पानम्, अतिशयेन सर्षपं मसालां च प्रयोगः, रसरहितम् आहारसेवनम् -- इत्यादीनि राजसानाम् आहारक्रमस्य केचन उदाहरणानि। [यदि अत्र उक्तम् इदम् आहारं रोगनिवारणाय वैद्यैः सूचितं भवति, तत् रोगिणे सात्त्विकः आहारः इति भवति।]",
  "17.10": "यातयामं गतरसं पूति पर्युषितं च यत् ।\nउच्छिष्टम् अपि च अमेध्यं भोजनं तामस प्रियम् ॥\n\nपक्वस्य दीर्घकालानन्तरं भुज्यमानम्, रसरहितम्, दुर्गन्धियुक्तम्, पर्युषितं, उच्छिष्टं, अमेध्यं च भोजनं तामसेभ्यः प्रियम्।\n\nतामसेभ्यः जीवने अतिमहत् विषयः भोजनम्। एते आहारं भगवते अर्पयित्वा न सेवन्ते। निःसारं, पर्युषितं, दुर्गन्धियुक्तं, रुचिरहितम् आहारं तामसेभ्यः इष्टम्। एते उच्छिष्टं भोजनम् इष्टं मन्यन्ते। [उदाहरणार्थम् एकस्मिन्नेव पात्रे बहवः जनाः उच्छिष्टं विभज्य भक्षणम्।]\n\nएवम् आहारेण व्यक्तिं कथम् अभिज्ञातुं शक्यते इति विवृत्य कृष्णः, अग्रे अस्मदीयेन आचारेण (यज्ञेन, तपसा, दानेन) व्यक्तेः स्वभावम् अवगन्तुं विधानं विवृणोति।",
  "17.11": "अफल आकांक्षिभिः यज्ञः विधिदृष्टो योयः इज्यते ।\nयष्टव्यम् एव इति मनः समाधाय सः सात्विक; ॥\n\nशास्त्रस्य नियमानुगुणं, फलेच्छां विना, कर्तव्यम् इति भावनया मनः निधाय कृतः यज्ञः सात्त्विकः यज्ञः।\n\nसर्वे यज्ञं कुर्वन्तः सात्त्विकाः न। यज्ञेऽपि सात्त्विकः राजसः तामसश्च इति त्रयः प्रभेदाः सन्ति। अस्मिन् श्लोके कृष्णः सात्त्विकयज्ञस्य स्वरूपं विवृतवान्। यज्ञः इत्युक्ते केवलम् अग्निकुण्डे कृता पूजा न। पीठे भगवत्पूजनम् अपि यज्ञः, मानसिकतया भगवद्ध्यानम् अपि यज्ञः। यत्किमपि फलकामनां विना, \"देवः प्रसन्नः भवतु, तस्य कृपादृष्टिः मयि भवतु\" इति विधिपूर्वकं कृता पूजा सात्त्विकः यज्ञः इति उच्यते। यान्त्रिकतया, मन्त्रस्य अर्थम् अज्ञात्वा, कयाचित् सङ्कुचितया फलापेक्षया कृता पूजा सात्त्विकः यज्ञः न भवति।\n\nअत्र \"विधिपूर्वकम्\" इति उक्तम्। इदम् अतिमुख्यं विषयम्। उदाहरणार्थं वयं पूजां कुर्वन्तः घण्टानादं कुर्मः, शङ्खनादं कुर्मः। एतादृशी काचित् पूजाविधिः स्यात् चेदपि, तां कर्तुं पूर्वं \"किमर्थं कुर्मः\" इति अवबोधः अस्मभ्यम् आवश्यकः। घण्टां कर्कशतया न वादयेत्। घण्टानादे ॐकारनादः निर्गच्छेत्। एवं ॐकारनादे निर्गते सति -- सः नादः श्रूयमाणे प्रदेशे विद्यमानाः समस्ताः दुष्टशक्तयः ततः पलायन्ते, इदं नादं देवताशक्तीः आकर्षति। अनेन पूजायै आवश्यकं शुद्धं वातावरणं निर्मीयते। अत्र मनःपूर्वकं दुष्टशक्तयः गच्छन्तु, देवताशक्तयः आगच्छन्तु इति प्रार्थ्य घण्टातः ॐकारनादः निष्कासनीयः। घण्टातः कदापि अपस्वरः न आगच्छेत्। घण्टानादाय एका श्रुतिः अस्ति। सप्तस्वरेभ्यः सप्तस्वरघण्टाः सन्ति। ताः श्रुतिबद्धतया वादनीयाः। इदम् ॐकारेण वातावरणशुद्धिं कुर्वती अद्भुता प्रक्रिया। इदं केवलम् एकम् उदाहरणम्। एवं वयम् अस्मदीयां प्रत्येकां क्रियां ज्ञात्वा मनःपूर्वकं कुर्याम; कुर्वत्यां क्रियायाम् अस्मभ्यम् आनन्दः स्यात्। एवं कृते एव सा सात्त्विकः यज्ञः इति भवति।",
  "17.12": "अभिसंधाय तु फलम् डंभ अर्थम् अपि च एव यत् ।\nइज्यते भरतश्रेष्ठ तम् यज्ञं विद्धि राजसम् ॥\n\nहे भरतश्रेष्ठ, फलेच्छया वा डम्भार्थं वा कृतः यज्ञः राजसः इति जानीहि।\n\nस्वार्थेन विशेषं फलम् इच्छित्वा, डम्भाचारेण कृतः यज्ञः राजसः यज्ञः इति भवति। यः कोऽपि यज्ञः भगवन्तं प्राप्तुं चेत् सः भक्त्या करणीयः। भगवति रतेषु वयं श्रेष्ठाः (भरतश्रेष्ठाः) भूत्वा क्रियां कुर्याम। इदं विना केवलं प्रचारार्थं कृतः यज्ञः राजसः यज्ञः भवति।",
  "17.13": "विधिहीनम् असृष्ट अन्नम् मंत्र हीनम् अदक्षिणम्।\nश्रद्धा विरहितं यज्ञं तामसं परिचक्षते ॥\n\nशास्त्रानुगुणं न, अन्नदानरहितम्, मन्त्ररहितम्, दक्षिणारहितम्; श्रद्धारहितं यज्ञं तामसम् इति वदन्ति।\n\nमन्त्रं सम्यक् अनुक्त्वा, मन्त्रं क्रमभ्रष्टतया उक्त्वा, पदोच्चारणं सम्यक् अकृत्वा -- एतत् सर्वं विधिहीनम्। एवं कृतः यज्ञः तामसः यज्ञः। यस्मिन्नपि यज्ञे यथा प्रतिमामुखेन अग्निमुखेन च आराधना भवति, तथैव चरमूर्तीनाम् आराधना अतिमुख्या। अन्नदानेन प्रत्येकस्मिन् विद्यमानस्य भगवतः आराधना एषा चरमूर्त्याराधना। एवम् अन्नदानं विना, दक्षिणां (वैदिकेभ्यः तेषां जीविकानिर्वाहाय वयं समर्पितां सेवाम्) विना कृतः यज्ञः तामसः यज्ञः। एतेभ्यः सर्वेभ्यः मुख्या श्रद्धा। भगवति अचला श्रेष्ठा श्रद्धा विना कृतः यत्कोऽपि यज्ञः स्यात् -- सः सर्वत्र तामसः यज्ञः भवति।\n\nआहारस्य यज्ञस्य च अनन्तरं कृष्णः अग्रिमेषु श्लोकेषु त्रिविधस्य तपसः विषये विवृणोति। मूलतः तपसि त्रयः विधाः। अस्मदीये आचरणे नियमबद्धता आनयनं तपः; गभीरं चिन्तनं तपः; मनःशुद्ध्यर्थं कृता देहदण्डना अपि तपः। तपः कर्तुं वनं गन्तव्यं नास्ति। गृहे स्थित्वैव तपः कर्तुं शक्यते। सात्त्विकं राजसं तामसं च तपः विवृण्वन् पूर्वं कृष्णः अत्र शरीरं, वाचम्, मनश्च इति मूलभूतं त्रिविधं तपसः विवरणम् अग्रिमेषु त्रिषु श्लोकेषु ददाति।",
  "17.14": "देव द्विज गुरु प्राज्ञ पूजनं शौचम् आर्जवम् ।\nब्रह्मचर्यम् अहिंसा च शारीरं तपः उच्यते ॥\n\nदेवताः, ज्ञानेन द्विजत्वं प्राप्तान्, गुरून्, प्राज्ञान् च पूजनम्; शुचित्वम्, ऋजुता, ब्रह्मचर्यम्, अहिंसा च -- एतत् शारीरं तपः इति उच्यते।\n\nदेवस्य प्रतीकं यत्र दृष्टं तत्र शिरः नमनम्; ज्ञानिभ्यः गौरवदानम्; गुरवे शिरोनमनम्; भगवद्भूत्या भगवन्तम् अनुभूतवद्भ्यः अनुभाविभ्यः प्राज्ञेभ्यः गौरवदानम् -- एतत् सर्वं शारीरं तपः इति भवति। इदं विहाय शुचित्वस्य पालनं जीवनम्, ऋजुः आचारः वाक् च, ब्रह्मचर्यपालनम्, अन्यस्मै अस्मत्तः कष्टं न भवेत् इति जीवनम् -- शरीरस्य तपः। [अस्मिन् श्लोके उक्तानां शौचम्, आर्जवम्, अहिंसा च इति गुणानां पूर्णं विवरणं षोडशाध्यायस्य प्रारम्भिकश्लोके विवृतम्।] अत्र \"ब्रह्मचर्यपालनम्\" इत्युक्ते मनः भगवति स्थापयितुम्; तस्मै पोषकतया वेदाध्ययनं करणम्; अध्ययनाय पोषकतया दैहिकं ब्रह्मचर्यपालनम्। दैहिकतया पूर्णं ब्रह्मचर्यं केवलं सन्न्यासिभ्यः ब्रह्मचारिभ्यश्च अन्वयति। गृहस्थाः एवं जीवितुं न शक्नुवन्ति। अतः गृहस्थेषु ब्रह्मचर्यपालनम् इत्युक्ते -- ते स्वच्छन्दकामिनः अभूत्वा, गृहस्थधर्मस्य आवरणे जीवनम् इत्यर्थः। एवं भगवति शरणागतिः; ज्ञानिभ्यः, गुरुभ्यः, प्राज्ञेभ्यः गौरवदानम्, शुचित्वस्य पालनम्, ऋजुः आचारः वाक्च, ब्रह्मचर्यपालनम् अहिंसया च जीवनम् -- शारीरिकं तपः। वयं सामाजिकतया सभ्याः भूत्वा जीवितुं इदं तपः आवश्यकमेव। मनुष्येण अनुसर्तव्याः दैहिकाः नीतयः इमाः।",
  "17.15": "अनुद्वेग करं वाक्यं सत्यं प्रिय हितं च यत् ।\nस्वाध्याय अभ्यसनं च एव वाज्मयं तपः उच्यते ॥\n\nअनुद्वेगजनकं, सत्यं, प्रियं हितं च यत् वचनम्, स्वाध्यायाभ्यासः च -- वाचिकं तपः इति उच्यते।\n\nपूर्वाध्याये विश्लेषितवद्वत् यत् अस्ति तत् तथा वदनं सत्यं न। सत्यम् इत्युक्ते किम् इति विवरणं कृष्णः अनेन श्लोकेन अस्मभ्यं ददाति। यत्र यथार्था सज्जनता अस्ति -- तां प्रीत्वा, तत्पोषकतया, अन्यम् अपीड्य, तस्मै हितकरतया भाषणं वाचिकं तपः। अन्यस्मै प्रियं हितं च वचनं वदनम् अतीव दुष्करम्। यतः बहुशः प्रियं यत् तत् हितं न भवति। एतादृशे प्रसङ्गे मौनं श्रेयः। कृष्णस्य कथां पठतां अस्मभ्यं बहुत्र कृष्णः असत्यं वदन्, वञ्चनां कुर्वन् इव दृश्यते। परं तस्याः क्रियायाः पृष्ठे विद्यमानां करुणां, हितचिन्तनं च अवलोक्य अस्मभ्यं तत् असत्यं न इति ज्ञायते। दैनन्दिने जीवने वदतां वयम् अस्मिन् श्लोके कृष्णेन उक्तस्य सन्देशस्य जागृतिं धरेम। अभाषमाणाः मौनाः भवेम, सम्यक्; परं किमपि भाषित्वा अनन्तरं पश्चात्तापं कृतवद्भ्यः उपयोगः नास्ति। \"उक्तं वचनं पुनः ग्रहीतुं न शक्यते; घातितं मनः वासयितुं औषधम् अस्मासु नास्ति\"। अतः अन्यं पीडयत् वचनं कदापि मा वद। व्यर्थगोष्ठ्यां दिनं यापयित्वा, वेदस्य अर्थचिन्तनं, गीताचिन्तनं, विष्णुसहस्रनामपठनम् इत्यादिषु स्वाध्याये निरतः भवनं वाचिकं तपः।",
  "17.16": "मनः प्रसादः सौम्यत्वं मौनम् आत्मविनिग्रहः ।\nभावसंशुद्दिः इति एतत् तपः मानसम् उच्यते ॥\n\nचित्तस्य प्रसन्नता, सौम्यता, मननम्, आत्मनियन्त्रणम्, भावशुद्धिः च -- इदं मानसं तपः इति उच्यते।\n\nउपर्युक्ताभ्यां द्वाभ्यां तपोभ्यां श्रेष्ठं महत् तपः मानसं तपः। शारीरिकं वाचिकं च तपः मानसतपसः पोषके। अस्मदीयं मनः सदा प्रसन्नं भवेत्। तत्र दुष्टविचारः पूर्णः न स्यात्, कलुषितं न स्यात्। तत् सौम्यं स्यात्, तत्र क्रौर्यं न स्यात्। कस्यापि विषयस्य उपरि निर्णयं कर्तुं पूर्वं गभीरं चिन्तनं करणीयम्। कस्मिन्नपि विषये, कस्मिन्नपि व्यक्तौ त्वरितया प्रतिक्रिया न कर्तव्या। मनयस्व, मनयित्वा वद। एवं मननं कर्तुं वयम् आत्मविनिग्रहं साधयेम [अधिकविवरणाय अध्याय-१३, श्लोक-७ पश्यतु]। स्वच्छाय क्रौर्यरहिताय मनसे इन्द्रियाणां नियन्त्रणम् अस्ति। तादृशं मनः दुष्टभावनां न स्फुरति। कश्चित् अस्मान् दुष्टतया वदेत् चेदपि अस्मभ्यं तस्य उपरि द्वेषः क्रोधः वा न आगच्छति। एवं मनसः नियन्त्रणं करणं मानसं तपः।\n\nअत्र उक्तस्य त्रिविधस्य तपसः प्रत्येकस्मिन् पुनः त्रिविधाः प्रकाराः -- सात्त्विकः, राजसः, तामसः च। एतस्य विवरणम् अग्रिमेषु त्रिषु श्लोकेषु अस्ति।",
  "17.17": "श्रद्धया परया तप्पं तपः तत् त्रिविधं नरैः ।\nअफल आकांक्षिभिः युक्तेः सात्विकं परिचक्षते ॥\n\nएतत् त्रिविधं तपः श्रेष्ठया श्रद्धया, फलेच्छां विना, भगवदर्पणभावेन आचरितं चेत् तत् सात्त्विकं तपः इति वदन्ति।\n\nतपसः पृष्ठे श्रेष्ठा श्रद्धा प्रामाणिकता च स्यात् चेत् तत् सात्त्विकं तपः भवति। भगवतः पारम्यस्य जागृत्या, भगवान् प्रीणीयात् इति अनुसन्धानेन कृता प्रत्येका क्रिया सात्त्विकी क्रिया इति भवति। उदाहरणार्थं गुरवे नमस्कुर्वन् -- \"तस्य गुरोः अन्तर्गतं भगवन्तं नमस्करोमि\" इति अनुसन्धानम्। एवम् अस्मदीयायाः प्रत्येकस्याः क्रियायाः पृष्ठे भगवदर्पणबुद्धिः स्यात्। मन्त्राः अपि इदमेव वदन्ति। \"अनेन भगवान् गोपालकृष्णः प्रीयताम् -- श्रीकृष्णार्पणमस्तु\" इति उक्ते सति अस्मासु अपि पूर्णा अर्पणभावना पूर्णा स्यात्। एतादृशं तपः सात्त्विकं तपः इति भवति।",
  "17.18": "सत् कार मान पूजा अर्थं तपः डंभेन च एव यत् ।\nक्रियते तत् इह प्रोक्तम् राजसं चलम् अध्रुवम् ॥\n\nसत्कारार्थं, सम्मानार्थं, पूजार्थं च डम्भेन कृतं तपः राजसम् इति उक्तम्, तत् चलम् अध्रुवं च।\n\nभगवतः अनुसन्धानं विना, \"जनाः मां सत्कारं कुर्वन्तु\" इति सम्मानेच्छया कृतं सर्वं तपः राजसं तपः। एवं डम्भाचारेण कृतं तपः परलोकं न प्राप्नोति। चापल्येन कृतस्य एतादृशस्य कार्यस्य फलम् इहापि शाश्वतं न।\n\nअस्मिन् श्लोके \"एव\" \"च\"-कारं च सह आगतम्। इदम् अस्मभ्यं विशिष्टं सन्देशं ददाति। सत्काराय, सम्मानाय, डम्भाय च कृता क्रिया राजसा भवति; परं भगवदर्पणबुद्ध्या कृत्वा अनिच्छन् सत्कारः आगच्छेत् चेत्, चतुर्भ्यः जनेभ्यः ज्ञानं भवतु इति ज्ञानदानभावनया प्रचारः क्रियते चेत् -- तत् राजसं न भवति। इदं ज्ञापयितुम् अत्र च-कारः एवकारश्च प्रयुक्तौ।",
  "17.19": "मूढग्राहेणात्मनो यत् पीडया क्रियते तपः ।\nपरस्योत्सादनार्थं वा तत् तामसमुदाहृतम् ॥\n\nदुराग्रहेण स्वदेहं पीडयित्वा, अथवा अन्यं नाशयितुं कृतं तपः तामसं तपः इति उच्यते।\n\nमिथ्याज्ञानेन, भ्रान्त्या, परमात्मनः अनुसन्धानं विना, अन्यः नाशं गच्छतु इति दुष्टभावनया, स्वदेहान्तः स्थितस्य भगवतः जागृतिं विना, देहदण्डनां कृत्वा कृतं तपः तामसं तपः।",
  "17.20": "दातव्यम् इति यत् दानम् दीयते अनुपकारिणे ।\nदेशे काले च पात्रे च तत् दानम् सात्विकं स्मृतम् ॥\n\n\"दातव्यम्\" इति भावनया, प्रत्युपकारं विना, योग्ये देशे काले पात्रे च दत्तं दानं सात्त्विकम् इति स्मृतम्।\n\nकस्यापि प्रत्युपकारस्य अपेक्षां विना, आत्मसन्तोषेण, मनःपूर्वकं, प्रीत्या, योग्याय व्यक्तये, योग्ये काले, योग्ये स्थाने दानं दानम्; \"मम कर्तव्यम्\" इति दृष्ट्या दत्तं दानं सात्त्विकं दानम् [अधिकविवरणाय अध्याय-१६ प्रारम्भिकश्लोकं पश्यतु]।",
  "17.21": "यत् तु प्रत्युपकारार्थं फलम् उद्दिश्य वा पुनः।\nदीयते च परिक्षिष्टं तत् राजसम् उदाहृतम् ॥\n\nप्रत्युपकारार्थं वा फलेच्छया वा, दातव्यम् इति दुःखेन दत्तं दानं राजसम् इति उच्यते।\n\nअन्ये अस्मभ्यम् अग्रे उपकारं कुर्युः इति, अथवा पूर्वं कृतस्य उपकारस्य प्रत्युपकारेण, \"दातव्यमेव\" इति दुःखेन दानम्। दाने फलेच्छया दत्तं दानं राजसं दानम्।",
  "17.22": "अदेश काले यत् दानम् अपात्रेभ्यः च दीयते ।\nअसत् कृतम् अवज्ञातम् तत् तामसम् उदाहृतम् ॥\n\nअयोग्ये देशे काले, अयोग्येभ्यः, अनादरेण, अवज्ञाय दत्तं दानं तामसम् इति उच्यते।\n\nअस्मभ्यम् अनावश्यकं वस्तु अन्यस्मै निःसारयितुं दत्तम्; अयोग्येभ्यः निन्दित्वा, तिरस्कृत्य, अवमानं कृत्वा दत्तम् -- तामसं दानम्।\n\nअद्यपर्यन्तं कृष्णेन उक्तस्य सात्त्विककर्मणः महत्त्वं वदत् \"अर्थवादः\" अस्य अध्यायस्य अग्रिमः भागः। \"अर्थवादः\" इत्युक्ते सात्त्विककर्मणः महत्त्वं वदत् निरूपणम्।",
  "17.23": "ओं तत् सत् इति निर्देशः ब्रह्मणः त्रिविधः स्मृतः ।\nब्राह्मणाः तेन वेदाः च यज्ञाः च विहिताः पुरा ॥\n\n\"ॐ\" [जगतः धारकः, जगति च पूर्णः], \"तत्\" [वेदैः, परोक्षतया एव ज्ञातुं शक्यः], \"सत्\" [सर्वशुभगुणैः पूर्णः] -- एतानि भगवतः त्रीणि नामानि। तेन भगवता एव वेदाः, वेदज्ञाः, यज्ञाश्च पूर्वं निर्मिताः।\n\nॐ, तत्, सत् -- एतानि भगवतः त्रीणि नामानि। भगवतः स्मरणाय, भगवन्तम् आह्वातुं ज्ञानिभिः एतादृशम् अनुसन्धानम् उपयोगे आनीतम्। भगवतः नाम अस्मदीयनामवत् न। तस्य नाम तस्य गुणवाचकानि पदानि। \"ॐ\" भगवते एव विशिष्टं नाम। इदं मनुष्यस्य सम्पूर्णजीवनस्य सर्वं मुखं त्रिभिः अक्षरैः (अ, उ, म्) वदति। समग्रं जगत् यस्मिन् ओतं, समग्रं जगत् येन ग्रथितम् -- सः \"ॐ\"। अस्माभिः कृतं समस्तं कर्म तस्मिन् अर्पितम् इति वदितुम् ॐकारः उपयुज्यते। \"हरिः ॐ\" इति आरम्भे उक्ते -- \"मया अग्रे कर्तव्यं समस्तं भगवते अर्पितम्\" इति उक्तमिव भवति। [ॐकारस्य विषये अधिकविवरणाय अध्याय-७, श्लोक ८-९ पश्यतु।]\n\n\"तत्\" इत्युक्ते पूर्णः। भगवान् समस्तगुणानाम् आश्रयः। गुणपरिपूर्णः सः समस्ते वेदे पूर्णः। अतः सः \"तत्\"। \"सत्\" इत्युक्ते यस्य कोऽपि दोषः नास्ति सः। एवम् ॐ-तत्-सत् इति वेदकालस्य नामत्रयम्। अद्य वयं वदामः अच्युतायनमः, अनन्तायनमः, गोविन्दायनमः -- एतदपि इदमेव अर्थं ददाति। अ-च्युत इत्युक्ते केनापि गुणेन च्युतः न भवति इत्यर्थः। तस्मात् च्युतं भूत्वा अस्मिन् जगति अस्तित्वं नास्ति। सः सर्वजगतः आधारः। इतः द्वितीयं नाम -- अनन्तः। अन्तराहितं यत् तत् अनन्तम्। यस्य गुणेभ्यः अन्तः नास्ति सः अनन्तः। तृतीयं नाम गोविन्दः। गो-इत्युक्ते वेदाः। समस्तवेदैः प्रतिपाद्यः भगवान् -- गोविन्दः। समग्रतया संक्षेपेण अत्र -- ॐ तत् सत् इत्युक्ते \"जगदाधारः, समस्तगुणपूर्णः, समस्तवेदप्रतिपाद्यः, समस्तदोषदूरः च भगवान्\" इत्यर्थः। एतादृशः भगवान् वेदं सृष्टवान्, तेन \"ज्ञानिनः भवत\" इति वेदज्ञान् (ज्ञानिनः) सृष्टवान्, ज्ञानपूर्वकं कर्म कुरुत इति यज्ञं सृष्टवान्।\n\nअस्मासु केचन वेदः \"पौरुषेयः\" इति, अन्ये च वेदः \"अपौरुषेयः\" इति वदन्तः सन्ति। सृष्टेः पूर्वं परमपुरुषेण उच्चारितः वेदः पौरुषेयः; इदम् अनादिअनन्तकाले प्रतिकल्पं भगवता उच्चार्यमाणत्वात् अपौरुषेयः अपि भवति। अतः अस्मिन् विषये कृतः वादः व्यर्थः।",
  "17.24": "तस्मादोमित्युदाहृत्य यज्ञदानतपःक्रियाः ।\nप्रवर्तंते विधानोक्ताः सततं ब्रह्मवादिनाम् ॥\n\n[एतयोः द्वयोः श्लोकयोः (१७.२४ तथा १७.२५) पदच्छेदः, अर्थः, विवरणं च सह अग्रिमे श्लोके (१७.२५) दत्तम्।]",
  "17.25": "तस्मात् ओम् इति उदाहृत्य यज्ञ दान तपः क्रियाः ।\nप्रवर्तंते विधान उक्ताः सततम् ब्रह्मवादिनाम् ॥\n\nतत् इति अनभिसंधाय फलं यज्ञ तपः क्रियाः ।\nदान क्रियाः च विविधाः क्रियंते मोक्षकांक्षिभिः ॥\n\nअतः शास्त्रानुगुणाः, ब्रह्मचिन्तकानां यज्ञदानतपःक्रियाः सदा \"ॐ\" इति भगवन्नामस्मरणेन सह आरभ्यन्ते। मोक्षम् इच्छन्तः सज्जनाः फलम् अनिच्छन्तः, \"तत्\" इति भगवते बहुविधान् यज्ञदानतपःक्रियान् आचरन्ति।\n\nकर्मणि ॐकारप्रयोगस्य महत्त्वं कृष्णः अत्र विवृतवान्। अस्माभिः ज्ञातं यत् एकः वेदज्ञः भवितुं चेत् तस्मै ॐकारस्य उपदेशः भवितव्यः; यज्ञस्य आदावन्ते ॐकारः वक्तव्यः; वेदपठनस्य आदावन्ते ॐकारः स्यात्। एतत् सर्वं पूर्वं आगतम् आचरणम्। वयं कुर्वत् यत्किमपि कार्यं भवतु, तत् आरभमाणे \"इदं भगवतः पूजारूपेण करोमि\" इति सङ्कल्पं कृत्वा करणम्, अन्ते च \"मया कृतं भगवान् स्वीकरोतु\" इति वदनम् -- अस्य मूलम् उद्देश्यम्। एवं ॐकारम् उक्त्वैव कर्म कर्तव्यम् इति आचरणं पूर्वात् वर्धितम्। अनेन अनुसन्धानेन वयं यत्किमपि पारायणं, होमं, हवनं, यज्ञं, तपः, दानं वा कुर्मः तत् सात्त्विकं कर्म भवति।\n\n\"तत्\" इत्युक्ते समस्तवेदवाच्यं भगवन्तं वदति इति पूर्वं दृष्टवन्तः। अत्र -- अस्मदीये कर्मणि \"तत्\" किं वदति इति कृष्णः विवृतवान्। \"तत्\" इत्युक्ते वेदमातुः गायत्र्याः संक्षिप्तपदम् (Abbreviation; प्रथमम् अन्तिमं च अक्षरम्)। अतः इदं गायत्रीवाच्यस्य भगवतः मुख्यं नामधेयम्। \"तत्\" इत्युक्ते कर्मणि भगवता दीयमानं फलं वदति। \"तत्\" इत्युक्ते कस्यापि ऐहिकफलस्य इच्छां विना, भवबन्धनात् मोचयित्वा मोक्षं ददतः भगवतः प्रीत्यर्थं कृतं कर्म। तत् यज्ञः स्यात्, तपः स्यात्, अथवा दानं स्यात्। ज्ञानिनः दानं कुर्वन्तः अपि कस्यापि ऐहिकफलस्य अपेक्षां विना दानं कुर्वन्ति। उदाहरणार्थम् अन्नदानम् -- अन्नस्य अभिमानिनी लक्ष्मीः; अन्नदानम् इत्युक्ते दानं स्वीकुर्वतः अन्तः स्थितस्य वैश्वानररूपिणः नारायणस्य लक्ष्म्याः समर्पणम्। एवमेव कन्यादानम् -- कन्यादानं कुर्वन्तः कन्यापितरः वरस्य सम्पत्तिं, पदवीं, वेतनं वा दृष्ट्वा दानं न कुर्वन्ति। अपि तु कन्यायाः अन्तःस्थां लक्ष्मीं वरस्य अन्तःस्थाय नारायणाय अर्पितं भवतु इति अनुसन्धानेन ददति। एवं मोक्षकाङ्क्षिणः \"सर्वं कारयन् सः भगवान् -- तस्य प्रीत्यर्थम् इयं पूजा\" इति यत्किमपि लौकिकं फलापेक्षां विना क्रियां कुर्वन्ति। इदम् एव \"तत्\"।",
  "17.26": "सत् भावे साधुभावे च सत् इति एतत् प्रयुज्यते ।\nप्रशस्ते कर्मणि तथा सत् शब्दः पार्थ युज्यते ॥\n\nहे पार्थ, \"भावः\" \"साधुत्वम्\" इति अर्थयोः \"सत्\" इति शब्दः प्रयुज्यते। \"प्रशस्तं कर्म\" इत्यर्थेऽपि \"सत्\" शब्दः उपयुज्यते।\n\n\"सत्\" इत्यस्य एकः अर्थः -- भावः। सत्-भावः इत्युक्ते साधुत्वेन स्थितिः। इदं लोके व्यक्तये प्रयुक्तं पदप्रयोगम्। इदं कर्मणि प्रयुक्ते सति सत्-कर्म भवति। ॐकारवाच्याय भगवते अर्पणभावेन, कस्यापि फलापेक्षां विना (तत्) कृतं कर्म \"सत्\"-कर्म। यत्कर्म वयं भगवद्विषयकतया कुर्मः, तत् कर्म प्रशस्तं भवेत्। अर्थात् स्वार्थाय कृतं चेत् तत् जनाः न मन्यन्ते। अपि तु त्यागेन कृतं कर्म प्रशस्तं कर्म इति भवति। वयम् एवं प्रत्येकस्य शब्दस्य अर्थं ज्ञात्वा, पालनं कुर्वन्तः पार्थाः भवेम इति कृष्णस्य सन्देशः। \"सत्\" पदस्य अर्थम् अद्यापि विस्तारेण कृष्णः अग्रिमे श्लोके विवृणोति।",
  "17.27": "यज्ञे तपसि दाने च स्थितिः सत् इति च उच्यते ।\nकर्म च एव तत् अर्थीयं सत् इति एव अभिधीयते ॥\n\nयज्ञे, तपसि, दाने च निष्ठाम् अपि \"सत्\" इति वदन्ति। भगवदर्थं कृतं कर्म अपि \"सत्\" इति एव अभिधीयते।\n\n\"सत्\" इत्युक्ते \"सत्\" शब्दवाच्यं भगवन्तं यज्ञेन, दानेन, तपसा च आराधनम्। एवं भगवान् अपि \"सत्\"; तद्विषयकं कर्म अपि \"सत्\" (सत्कर्म); तद्विषयकं कर्म कुर्वन् अपि \"सत्\" (सज्जनः)। वयं भगवतः जागृत्या, फलापेक्षां विना, भगवदर्पणभावेन, भगवान् प्रीणीयात् इति कृत्वा कुर्वत् समस्तं कर्म सत्-कर्म।",
  "17.28": "अश्रद्धया हुतम् दत्तम् तपः तप्तम् कृतं च यत् ।\nअसत् इति उच्यते पार्थ न च तत् प्रेत्य नो इह ॥\n\nअश्रद्धया हुतं, दत्तं, तप्तं, कृतं च यत् -- हे पार्थ, तत् \"असत्\" इति उच्यते। तत् नो इह, नो प्रेत्य फलं ददाति।\n\nकुर्वति कर्मणि श्रद्धा विना, भगवति श्रद्धा विना, कस्यचित् आग्रहेण वा भयेन वा, पूर्णविश्वासं विना कृता क्रिया व्यर्था। श्रद्धां विना कृतं तादृशं दानम्, तपः, यज्ञः, अथवा अन्यत् यत्किमपि कर्म -- तस्मै इहापि फलं नास्ति, परत्रापि फलं नास्ति।\n\nइति सप्तदशोऽध्यायः।",
  "18.1": "अर्जुनः उवाच\n\nसंन्यासस्य महाबाहो तत्वम् इच्छामि वेदितुम् ।\nत्यागस्य च हृषीकेश पृथक् केशिनिसूदन ॥\n\nहे महाबाहो, संन्यासस्य तत्त्वं ज्ञातुम् इच्छामि। हे हृषीकेश, त्यागस्य च। हे केशिनिसूदन, अनयोः पार्थक्यं मह्यं ज्ञापय।\n\nकृष्णः पूर्वं संन्यासस्य विषये उक्तवान्; अनन्तरं पूर्वाध्याये यज्ञं दानं तपः इति कर्माणि उक्तवान्। अत्र अस्मभ्यं किञ्चित् भ्रान्तिः जायते। अतः अर्जुनः कृष्णं पृच्छति -- कर्मत्यागस्य कर्मसंन्यासस्य च मध्ये अन्तरं किम् इति। त्यागः संन्यासः इति द्वे पदे उपरिदृष्ट्या एकम् अर्थं ददति इव भासेत अपि, ते भिन्ने एव। संन्यासस्य त्यागस्य च मूलः अर्थः कः? ते पृथक्तया अर्थयितुं कथम् -- इति अर्जुनस्य प्रश्नः।\n\nअत्र अर्जुनः कृष्णं \"महाबाहो\" \"हृषीकेश\" \"केशिनिसूदन\" इति त्रिभिः दिव्यनामभिः सम्बोधितवान्। इदं तस्मिन् विद्यमानां गुरुभक्तिं सूचयति, कृष्णः केवलं वसुदेवस्य पुत्रः न, \"भगवान्\" इति अर्थं ज्ञात्वा एतत् प्रश्नं पृष्टवान् इति अत्र स्पष्टतया ज्ञायते। \"महाबाहुः\" इत्युक्ते शत्रून् प्रतिरुध्य दीर्घे दृढे बाहू धारयन् इति उपरिदृष्टिः अर्थः। दुष्टनिग्रहं कृत्वा शिष्टरक्षणं कुर्वन्, सर्वेषाम् अज्ञानं निवारयन्, लोकरक्षकौ बाहू धारयन् -- एषः अस्य दिव्यनाम्नः मूलः अर्थः। \"हृषीक\" इत्युक्ते इन्द्रियाणि। पिण्डाण्डान्तः स्थित्वा सर्वाणि इन्द्रियाणि नियन्त्रयन् भगवान् हृषीकेशः। \"केशी\" इत्युक्ते सूर्यकिरणः, वायुदेवः (ऋग्वेद १०.१२१.३ इति सन्दर्भः)। सौरमण्डले स्थित्वा, स्वान्तरङ्गभक्तं प्राणदेवं आश्रित्य, अस्माकम् अभीष्टं पूरयन्, अस्मभ्यं शक्तिं पूरयन् भगवान् \"केशिनिसूदनः\"। सः ब्रह्माण्डपिण्डाण्डयोः अन्तः स्थित्वा सम्पूर्णं विश्वं नियन्त्रयन् महाशक्तिः। [बहुत्र \"केशिनिषूदन\" इति पदं प्रयोगे अस्ति, परं सम्यक् पदं केशिनिसूदनः।]",
  "18.2": "भगवान् उवाच\n\nकाम्यानाम् कर्मणाम् न्यासम् संन्यासं कवयः विदुः ।\nसर्वकर्मफल त्यागम् प्राहुः त्यागं विचक्षणाः ॥\n\nकाम्यकर्मणां त्यागं ज्ञानिनः \"संन्यासः\" इति जानन्ति। समस्तस्य कर्मफलस्य त्यागं विदुषः \"त्यागः\" इति वदन्ति।\n\nअत्र उक्तः संन्यासः गृहस्थान् अपि अन्तर्भाव्य सर्वान् साधकान् प्रति अन्वयति। संन्यासे द्वे विधे। एका कर्मणः फलं त्यक्तुम्, अन्या इच्छाप्रेरितं कर्मैव त्यक्तुम्। अत्र त्यागः इत्युक्ते कर्मत्यागः न, अपि तु यत्किमपि कर्म भवतु, तत् कृत्वा तस्य फलम् अनिच्छनम्। अतः कर्मत्यागः इत्युक्ते वेदाध्ययनत्यागः, सन्ध्यावन्दनत्यागः, व्रतानुष्ठानादित्यागः इत्यर्थः न। अपि तु सत्कर्म कृत्वा तस्य फलम् अनिच्छनम् इत्यर्थः। यत्किमपि कर्म भवतु तत् भगवत्प्रीत्यर्थं कुरु -- फलेच्छया न।\n\nअत्र \"कवयः\" \"विचक्षणाः\" इति द्वे विशिष्टे पदे प्रयुक्ते। शब्दार्थयोः सम्बन्धं ज्ञातवन्तः कवयः; शब्दार्थं ज्ञात्वा तम् अनुभूय आचरन्तः विचक्षणाः। \"कवयः विचक्षणाः च संन्यासाय त्यागाय च एतत् विवरणं ददति\" इति कृष्णः उक्तवान्।",
  "18.3": "त्याज्यं दोषवत् इति एके कर्म प्राहुः मनीषिणः ।\nयज्ञदानतपःकर्म न त्याज्यम् इति च अपरे ॥\n\nदोषयुक्तं कर्म त्याज्यम् इति केचन विद्वांसः वदन्ति। यज्ञदानतपोनामकं कर्म न त्याज्यम् इति अन्ये वदन्ति।",
  "18.4": "निश्चयम् शृणु मे तत्र त्यागे भरतसत्तम ।\nत्यागः हि पुरुषव्याघ्र त्रिविधः संप्रकीर्तितः ॥\n\nहे भरतसत्तम, तत्र त्यागस्य विषये मम निश्चितम् अभिप्रायं शृणु। हे पुरुषव्याघ्र, त्यागः त्रिविधः इति उक्तः।\n\n\"त्यागस्य विषये निश्चितम् अभिप्रायं तुभ्यं वदामि\" इति कृष्णः वदति। यथा यज्ञदानतपांसि त्रिविधानि, तथा त्यागोऽपि त्रिविधः। तत् कृष्णः अर्जुनाय विवृणोति। अत्र कृष्णः अर्जुनं \"भरतसत्तम\" \"पुरुषव्याघ्र\" इति सम्बोधितवान्। भरतवंशस्य राजमालिकायां गण्यत्वात् अर्जुनः भरतसत्तमः -- इदम् उपरिदृष्टिः अर्थः। भगवति ज्ञाने च रतः, भक्तियुक्तः भरतसत्तमः इति अस्य सम्बोधनस्य अन्तरङ्गः अर्थः। तथैव पुरुषव्याघ्रः इत्युक्ते पुरुषश्रेष्ठः इत्यर्थः। भगवतः दिशं स्वमनः प्रवाहयन्तः पुरुषाः। तेषु श्रेष्ठः -- पुरुषश्रेष्ठः। अर्थात् ज्ञानिषु श्रेष्ठः इत्यर्थः। वयमपि स्वजीवने भरतसत्तमाः, पुरुषव्याघ्राः भवेम। तदा भगवतः सन्देशः अस्मान् प्राप्नोति।",
  "18.5": "यज्ञदानतपःकर्म न त्याज्यं कार्यमेव तत् ।\nयज्ञो दानं तपश्चैव पावनानि मनीषिणाम् ॥\n\nयज्ञदानतपोनामकं कर्म न त्याज्यम्, तत् कर्तव्यमेव। यज्ञः दानं तपः च ज्ञानिनां पावनानि।\n\nभगवतः आराधनारूपं यज्ञं दानं तपः च कदापि न त्याज्यम्। तत् कर्तव्यमेव। अस्मात् मङ्गलं वस्तु अन्यत् नास्ति। एतानि त्रीणि अपि अस्मदीयं जीवनं पवित्रं कुर्वत्यः क्रियाः। अस्मात् अधिकं पवित्रा क्रिया अन्यत्र जगति नास्ति। अन्याः सर्वाः क्रियाः एतासु तिसृषु क्रियासु अन्तर्भूताः भवन्ति। अतः अस्मदीयस्य जीवनस्य प्रत्येका क्रिया अपि यज्ञदानतपांसि भवेत्।",
  "18.6": "एतानि अपि तु कर्माणि संगम् त्यक्त्वा फलानि च ।\nकर्तव्यानि इति मे पार्थ निश्चितम् मतम् उत्तमम् ॥\n\nपरं हे पार्थ, एतानि कर्माणि ममतां फलेच्छां च त्यक्त्वा कर्तव्यानि इति मम निश्चितं श्रेष्ठम् आशयम्।\n\nकर्म कुर्वति जायमानः मूलः दोषः \"अहं कृतवान्, मया अभवत्\" इति अहङ्कारः। तेन सह भगवतः पुरतः अस्मदीयां फलकामनासूचीं दत्त्वा फलापेक्षया कर्म करणम्। एतौ कर्मणि महान्तौ दोषौ। अहङ्कारेण कर्म कृतं चेत् तत् व्यर्थम् -- यतः अहङ्कारे स्थाने भगवान् न आगच्छति। अद्यापि वयं फलेच्छया कर्म कुर्मः। फलेच्छया कर्म कृत्वा यदि अस्मदीयं इष्टं फलं न सिध्येत्, तदा अस्मभ्यं तस्मिन् कर्मणि आसक्तिः दूरं गच्छति, देवस्य विषये वैरत्वम् उत्पद्यते। इदं फलापेक्षया कर्म कुर्वतां जायमानम् अनर्थम्। \"इदं मम निश्चितम् अभिप्रायम्। त्वया त्याज्यं कर्म न, अपि तु कर्मफलं, 'मया कृतम्' इति आसक्तिः अहङ्कारश्च\" इति वदति कृष्णः। इदं कर्मसिद्धान्तस्य अत्युत्कृष्टं तात्पर्यम्। अहङ्कारं, काम्यकर्म (केवलं फलार्थम् एव कर्म करणम्), कर्मणि फलेच्छां च त्यागः एव यथार्थः त्यागः, न नियतकर्मस्य त्यागः। इदं निश्चितं सिद्धान्तम्।",
  "18.7": "नियतस्य तु संन्यासः कर्मणः न उपपद्यते ।\nमोहात् तस्य परित्यागः तामसः परिकीर्तितः ॥\n\nनियतस्य कर्मणः संन्यासः उचितः न। मोहेन तस्य त्यागः तामसः त्यागः इति उक्तः।\n\nकदापि वयम् अस्मदीयं नियतकर्म न त्यजेम। यदि भ्रान्त्या नियतं कर्म त्यजेत् तदा तत् तामसः त्यागः इति भवति। अत्र \"नियतकर्म\" इत्युक्ते अस्मदीयायाः जीवयोग्यतायै यत् नियतं तत् कर्म। अस्माभिः ज्ञातं यत् समस्तं कर्म सर्वैः कर्तुं न शक्यते। उदाहरणार्थं यज्ञः -- यतयः अग्निमुखे आहुतिं दातुं न शक्नुवन्ति; ब्रह्मचारिणः पूर्णप्रमाणस्य अग्निहोत्रं कर्तुं न शक्नुवन्ति। परं यतयः ज्ञानयज्ञं कर्तुं शक्नुवन्ति, तत् तेषां नियतकर्म। सर्वकालेषु सर्वैः कर्तुं शक्यः यज्ञः \"नामयज्ञः\"। अर्थात् भगवतः नामस्मरणम्। इदं यज्ञेषु सर्वेभ्यः अन्वयत् नियतकर्म। इतः दानम् -- ब्रह्मचारिणः कन्यादानं कर्तुं न शक्नुवन्ति, तत् गृहस्थेन करणीयम्। गृहस्थाय कन्यादानं नियतकर्म। सर्वैः कर्तुं शक्यं दानम् -- अभयदानं ज्ञानदानं च। तृतीयं तपः -- कञ्चन तपः सर्वैः कर्तुं न शक्यते। तस्मै वेददीक्षा अपेक्षिता स्यात्। परं सर्वैः कर्तुं शक्यं तपः इत्युक्ते उपवासादिव्रतानुष्ठानानि। इदं तपः मनुष्यमात्रैः कर्तुं शक्यते। एवं यस्मै यत् कर्म नियतं तत् कर्म करणीयम्। नियतकर्मणि फलापेक्षायाः प्रश्नः एव नास्ति। भ्रान्त्या नियतकर्मं त्यक्तं चेत् तत् तामसः त्यागः इति भवति इति सावधानतां कृष्णः अनेन श्लोकेन दत्तवान्।",
  "18.8": "दुःखम् इति एव यत् कर्म काय क्लेश भयात् त्यजेत् ।\nसः कृत्वा राजसम् त्यागम् न एव त्याग फलम् लभेत् ॥\n\nदेहाय क्लेशः भवति इति भयेन कर्म त्यजेत् चेत् -- सः राजसं त्यागं कृत्वापि त्यागस्य फलं न लभते।\n\nअस्मभ्यं ज्ञातमेव यत् नियतकर्म करणीयम् इति, तथापि मनसे देहाय च पीडा भवति इति कारणेन कर्म अकृत्वा त्यजनं राजसः त्यागः इति भवति। उदाहरणार्थं कस्याश्चित् दूरदर्शनश्रृङ्खलायाः द्रष्टव्यम् इति उत्कटायाः इच्छायाः वशेन कर्मत्यागः, शैत्यं भवति इति सन्ध्यावन्दनस्य अकरणम्, इत्यादि राजसः त्यागः। एतादृशं राजसं त्यागं कृते सति यथार्थस्य त्यागस्य फलं न प्राप्यते।",
  "18.9": "कार्यम् इति एव यत् कर्म नियतम् क्रियते अर्जुन ।\nसंगं त्यक्त्वा फलं च एव सः त्यागः सात्र्विकः मतः ॥\n\nहे अर्जुन, \"कर्तव्यम्\" इति भावेन नियतं कर्म कुर्वन्, ममतां फलेच्छां च त्यजन् -- सः त्यागः सात्त्विकः इति मतः।\n\nनियतकर्मं कर्तुम् अशक्यम् इति स्थितिं प्रति अस्मदीयं मनः प्राप्नुयात्। एवं सत्त्वगुणे मनसि पूर्णे सति (अर्जुनाः भवामः यदा) कमपि कर्म त्यक्तुं वयं मनः न कुर्मः। तत्र फलेच्छा एव न भवति। सदा भगवदर्पणभावेन आनन्देन कर्म करणम्; कमपि अहङ्कारं विना स्थातुम्; समस्तस्य कर्मणः महत्त्वं ज्ञात्वा नियतरूपेण कर्म करणम् -- सात्त्विकः त्यागः। अत्र त्यागः क्रियते कर्म न, अपि तु कर्मफलम्।\n\nएवं अस्मासु विद्यमानायै विभ्रान्तये कृष्णः अतिसरलम् उत्तरं दत्तवान्। संक्षेपेण वक्तव्यं चेत् -- फलापेक्षां विना, अहङ्कारं त्यक्त्वा, नियतकर्मं करणं सात्त्विकः त्यागः; आलस्येन क्लेशः भवति इति नियतकर्मं त्यजनं राजसः त्यागः; भ्रान्त्या \"सर्वं मूढविश्वासः\" इति नियतकर्मं अकृत्वा त्यजनं तामसः त्यागः।",
  "18.10": "न द्वेष्टि अकुशलम् कर्म कुशले न अनुषज्जते ।\nत्यागी सत्त्वसमाविष्टः मेधावी छिन्नसंशयः ॥\n\nआनन्दरहितं कर्म न द्वेष्टि, आनन्दप्रदं कर्म अतिशयेन न आसज्यते। एतादृशः त्यागी सात्त्विकः। सः विदुषः, सन्देहरहितः च।\n\nएषः श्लोकः सात्त्विकः त्यागी स्वकर्माणि कथं पश्यति इति वदति। अस्माभिः कृतं पूर्वं कञ्चन कर्म आश्रित्य अद्य दुष्परिणामः जायेत, अथवा पूर्वं कृतेन कर्मणा शुभं जायेत -- सात्त्विकः त्यागी तद्विषये शिरः न पीडयति। सः शुभम् अभवत् इति उत्प्लवं न करोति, दुष्टम् अभवत् इति अवसीदति न। एषः दुःखकारकं कर्म द्वेष्टि अपि न। यथा औषधं तिक्तं भवति, तथा सत्कर्म किञ्चित् दुःखकरं भवति चेत् तद्विषये सः चिन्तां न करोति।\n\nसात्त्विकस्य त्यागिनः मनः सत्त्वगुणेन पूर्णं भवति। तस्मै तामसराजसौ चिन्ते न आगच्छतः। बलज्ञानाभ्यां परिपूर्णे भगवति सर्वं समर्प्य सः कर्म करोति। अनेन तस्य मनः पूर्णतया भगवति समाविष्टं भवति। मेधावी अस्ति सः स्वजीवनस्य प्रत्येकां गतिं जागृत्या पश्यति। भगवति स्थितानाम् एतेषां मनसि कदापि का अपि विभ्रान्तिः न प्रविशति। एतादृशानां जीवनस्य गतिः द्रष्टुं सामान्या भवति, परं तेषां क्रियायाः पृष्ठे विद्यमानम् अनुसन्धानं भिन्नमेव भवति। एते \"भगवन्, त्वं कारयसि -- अहं करोमि\" इति अनुसन्धानेन स्वकर्म कुर्वन्ति।",
  "18.11": "नहि देहभृता शक्यं त्यक्तुं कर्माणि अशेषतः ।\nयः तु कर्म फल त्यागी सः त्यागी इति अभिधीयते ॥\n\nदेहधारिणा सर्वाणि कर्माणि पूर्णतया त्यक्तुं न शक्यम्। कर्मफलं त्यक्तवान् एव त्यागी इति उच्यते।\n\nमनुष्यरूपेण जातस्य, जन्मतः मरणपर्यन्तं वयं कर्म कर्तव्यमेव। कर्मं त्यक्त्वा जीवितुं न शक्यते। वयं त्याज्यं कर्म न, अपि तु कर्मफलम्। एवं कर्म कृत्वा कर्मफलं त्यक्तवान् कर्मत्यागी इति भवति।",
  "18.12": "अनिष्टम् इष्टं मिश्रं च त्रिविधं कर्मणः फलम् ।\nभवति अत्यागिनां प्रेत्य नतु संन्यासिनां क्वचित् ॥\n\nकर्मणः फलं त्रिविधम् -- इष्टम्, अनिष्टम्, मिश्रं च। फलत्यागं अकृतवद्भ्यः इदं मरणानन्तरं भवति। फलासक्तिं त्यक्तवद्भ्यः इदं कदापि न स्पृशति।\n\nकर्म कृतवद्भ्यः सुखं वा दुःखं वा, सुखदुःखयोः मिश्रं फलं वा प्राप्येत। कर्मफलत्यागं अकृत्वा कर्म कुर्वद्भ्यः इदं मरणानन्तरं प्राप्नोति। एते कर्मणः कर्मफलस्य च चक्रे निबद्धाः पुनः संसारबन्धने पतन्ति। परं कर्मफलेच्छारहितेभ्यः इदं कदापि न स्पृशति। तेभ्यः यत् किमपि आगच्छति तत् भगवतः प्रसादः। तत्र इष्टानिष्टयोः भेदः नास्ति। एषः मोक्षमार्गः। उदाहरणार्थं राज्यस्य अधिकारस्य आशया, भगवन्तं विस्मृत्य युद्धं कुर्वन् -- युद्धे प्रवर्तमानायाः प्राणहानेः कारणं भवति। सः इमं पापभारं मरणानन्तरं वहितव्यः भवति। परं कर्तव्यकारणेन कमपि स्वार्थं विना सर्वं भगवते अर्पयित्वा युद्धं कुर्वते कोऽपि पापलेपः न स्पृशति।",
  "18.13": "पंच एतानि महाबाहो कारणानि निबोध मे ।\nसांख्ये कृत अंते प्रोक्तानि सिद्धये सर्व कर्मणाम् ॥\n\nसमस्तानां कार्याणां सिद्ध्यर्थम् इमानि पञ्च कारणानि। हे महाबाहो, वैदिकसाङ्ख्यसिद्धान्ते उक्तानि तानि मत्तः ज्ञातुं शक्नोषि।\n\nअस्मासु बहवः एकं प्रश्नं धरन्ति -- \"अस्माभिः कृतं कार्यं 'मया कृतम्' इति वदने कः दोषः\" इति। अस्मै प्रश्नाय उत्तरं प्राप्तुं चेत्, एका क्रिया प्रवर्तितुं तस्याः पृष्ठे विद्यमानानि पञ्च कारणानि ज्ञातव्यानि। वैदिकसाङ्ख्यशास्त्रे, ज्ञानसिद्धान्ते उक्तानि एतानि पञ्च कारणानि कृष्णः अर्जुनाय विवृणोति।\n\nअत्र कृष्णः अर्जुनं \"महाबाहो\" इति सम्बोधितवान्। \"महा-बा\" इत्युक्ते महत्यः इच्छाः। ताः त्यक्तवान् महाबाहुः। वयं सर्वे स्वजीवने कर्मफलत्यागं कृत्वा, केवलं भगवदर्पणभावेन कर्म कर्तुं शिक्षित्वा महाबाहवः भवेम इति अस्य सम्बोधनस्य पृष्ठे ध्वनिः।",
  "18.14": "अधिष्ठानं तथा कर्ता करणं च पृथग् विधम् ।\nविविधाः च पृथक् चेष्टाः दैवं च एव अत्र पंचमम् ॥\n\nक्रियायाः स्थानम्, कर्ता [जीवः], भिन्नानि उपकरणानि, विविधाः पृथक् पूरकक्रियाः, पञ्चमं च दैवम् [भगवान्]।\n\nप्रत्येका क्रिया प्रवर्तितुं पञ्च कारणानि --\n\n(१) अधिष्ठानम् -- अत्र अधिष्ठानम् इत्युक्ते आश्रयः। अस्मदीयं शरीरम् एव अस्मदीयम् अधिष्ठानम्। इदं साधनाशरीरं विना कापि क्रिया न प्रवर्तते। तुभ्यं प्राप्तं साधनाशरीरं तस्य भगवतः प्रसादः।\n\n(२) कर्ता -- शरीरे उपविष्टः अस्मदीयाः क्रियाः नियन्त्रयन् भगवान् कर्ता। सः स्वतन्त्रः। तस्मै अधीनः जीवः स्वतन्त्रः न। परं जीवाय इच्छापूर्विका कृतिः अस्ति।\n\n(३) करणानि -- अस्मदीयानि इन्द्रियाणि। अस्मदीयानि इन्द्रियाणि देवताः नियन्त्रयन्ति। इन्द्रियाणाम् अधिपतिः भगवान् (हृषीकेशः)। इन्द्रियाणि अस्मभ्यं भगवतः महाप्रसादः।\n\n(४) विविधाः पूरकसाधनानि -- एका क्रिया भवितुं तस्यै पूरकानि अनेकानि साधनानि अपेक्षितानि।\n\n(५) दैवम् -- अस्मदीया प्रत्येका क्रिया भगवतः सङ्कल्पम् आश्रिता। इदं भाग्यम्, ललाटलेखनम् इति अपि आह्वातुं शक्यते।\n\nउपर्युक्तं विषयम् उदाहरणेन पश्येम चेत् -- एकः अत्युत्तमः वक्ता। सः अतीव रोचकतया, विषयगर्भितया वदति। सः एवं वक्तुं सः मूकः न स्यात्, मुखं भवेत्, अलम्; मुखे शब्दः आगच्छेत्। केवलं शब्दः न -- यद्वक्तव्यं तदनुगुणः शब्दः आगच्छेत्। सः शब्दः आगन्तुं वाचि एका भावना अपेक्षिता। भावना नाम मनसि स्फुरेत्, स्फुरितायै भावनायै अनुगुणः शब्दः आगच्छेत्, सः शब्दः मुखे स्पष्टतया बहिः निर्गच्छेत्। भावनातः शब्दस्य जन्माय आकाशवायू माध्यमे। एतत् सर्वं क्रमेण प्रवर्तते चेत् एव सः सम्यक् वक्तुं शक्नोति। मनसि भावनां शब्दं च स्फुरयन् कः? यदि वक्तव्याय विषयाय अनुगुणः शब्दः न स्फुरेत्? अस्मदीये मस्तिष्के कापि एका स्विच् तस्मिन् क्षणे कार्यं न कुर्यात् चेत्? जन्मत एव मूकः जातः चेत्? ज्ञानपरम्परा एव न विद्यमाने कुले जातः चेत्? अत्र अस्मदीयः कः हस्तक्षेपः? इदम् अवगते सति \"अहं कृतवान्\" इति अहङ्कारः न आगच्छेत्। एषा जागृतिः सत्यां सर्वैः सह सर्ववत् स्थित्वा अनासक्ततया स्थातुं शक्यते।",
  "18.15": "शरीर वाक् मनोभिः यश् कर्म प्रारभते नरः ।\nन्याय्यं वा विपरीतं वा पंच एते तस्य हेतवः ॥\n\nशरीरेण वाचा मनसा च मनुष्यः यत्किमपि कर्म आरभते -- तत् सम्यक् भवतु वा विपरीतं भवतु -- एतानि पञ्च तस्य कारणानि।\n\nशरीरेण वाचा मनसा च वयं यत्किमपि क्रियां कुर्मः तस्याः पृष्ठे उपर्युक्तानि पञ्च कारणानि सन्ति। सा क्रिया शुभा वा अशुभा वा भवतु, क्रिया केवलं एतैः पञ्चभिः कारणैः एव प्रवर्तते।",
  "18.16": "तत्र एवं सति कर्तारम् आत्मानं केवलं तु यः।\nपश्यति अकृत बुद्धित्वात् न सः पश्यति दुर्मतिः ॥\n\nएवं स्थिते सति, किमपि अकुर्वन्तं स्वात्मानं \"कर्ता\" इति यः पश्यति सः दुर्बुद्धिः। सः दुर्मतिः किमपि न जानाति।\n\nएवं पञ्च कारणानि अस्मदीयायां क्रियायां पात्रधारिणः सन्ति सत्सु, तत् अज्ञात्वा \"अहं कृतवान्\" इति अहङ्कारं धरणम् अर्थशून्यम्। एवं ज्ञातवन्तः दुर्बुद्धयः। एतादृशाः दुर्मतयः किमपि न ज्ञातवन्तः।",
  "18.17": "यस्य न अहंकृतः भावः बुद्धिः यस्य न लिप्यते ।\nहत्वा अपि स इमान् लोकान् न हंति. न निबध्यते ॥\n\nयस्य \"अहं कृतवान्\" इति भावः नास्ति, यस्य बुद्धिः लिप्यते न -- सः एतान् समस्तान् जनान् हत्वा अपि कमपि न हन्ति, कर्मबन्धनं तं न स्पृशति।\n\nकर्मफलस्य त्यागं कृतवान् यत्किमपि कर्म कुर्यात् तत् तस्मै बाधकं न भवति। वयं \"मया कृतम्\" इति आसक्तिं विना, फलेच्छां विना कर्म कुर्मः चेत् तस्य कर्मणः फलं कदापि अस्मान् न बाधते। महाभारतयुद्धस्य सन्दर्भं पश्येम चेत् -- पाण्डवेभ्यः युद्धम् अनिवार्यतया उपस्थितम्। ते कदापि युद्धं भवतु इति न इष्टवन्तः; युद्धे विजित्य अधिकारं प्राप्नुयाम इति अपि न चिन्तितवन्तः। परं तेभ्यः अनिवार्यतया युद्धस्य प्रसङ्गः पुरतः स्थितः अभवत्। तत् \"इदं दैवेच्छा\" इति ज्ञात्वा, युद्धस्य परिणामं अचिन्तयित्वा भगवदर्पणभावेन कृतवन्तः। एवम् उपस्थिते युद्धे तैः अनेकान् योधान् हन्तव्यम् अभवत्। परं ते स्वं कर्तव्यकर्म फलापेक्षां अहङ्कारं विना कृतवन्तः। एवं \"निर्लिप्तेन मनसा युद्धभूमौ अनेकान् जनान् हन्तुं प्रसङ्गः आगच्छेत् चेदपि, तत् हतपापं हन्तारं न स्पृशति\" इति वदति कृष्णः। परं अत्र अतिमुख्यः विचारः -- मानसिकतया एकम् अपि क्षणं भगवति अविश्वासः न आगच्छेत्; पूर्णार्पणभावेन, निश्चितेन अभिप्रायेण अस्मदीयभागे उपस्थितं कर्म फलापेक्षां विना कर्तव्यम्। \"भगवतः हस्ते अहम् एकं साधनम्\" इति जागृत्या सर्वं भगवतः चरणयोः अर्प्य कर्म कृते सति कर्मबन्धनम् अस्मान् न स्पृशति। जीवाय कर्मफलस्य स्पर्शः भवति सः \"अहं कृतवान्\" इति ज्ञात्वा एव।\n\nअत्र अस्माकम् एकः प्रश्नः उदेत्। जीवाय स्वतन्त्रं कर्तृत्वं नास्ति, कर्म भगवदिच्छानुगुणं प्रवर्तते। एवं सति जीवाय विधिनिषेधः किमर्थम्? शास्त्रं किमर्थं \"इदं कुरु, इदं मा कुरु\" इति वदति? अस्मै प्रश्नाय कृष्णः अग्रिमे श्लोके उत्तरति।",
  "18.18": "ज्ञानं ज्ञेयं परिज्ञाता त्रिविधा कर्म चोदना ।\nकरणं कर्म कर्ता इति त्रिविधः कर्मसंग्रहः ॥\n\nकर्मणः प्रेरणा त्रिविधा -- ज्ञानम्, ज्ञेयम्, ज्ञाता च। [कर्मणे कारणभूता भगवतः प्रेरणा तस्य स्वरूपमेव। अतः सा मुख्यतया ज्ञानरूपा, सर्वैः ज्ञातव्या, सर्वज्ञा च।] कर्मणः कारणम् अपि संक्षेपेण त्रिविधम् -- उपकरणम्, क्रिया, कर्ता च।\n\nविधिनिषेधः अस्ति अस्मदीयस्य ज्ञानाय। \"भगवन्तम् 'अहम्' ज्ञातव्यम्\" इत्यर्थं कर्मणः विधिनिषेधः। कर्म करणं कर्मार्थं न -- ज्ञानार्थम्। कर्मविधानस्य पृष्ठे करुणा। ज्ञानरहिताय लोकाय भगवतः ज्ञानम्, तस्मै ज्ञानाय पूरकतया कर्म। कर्मणः पृष्ठे प्रेरणा त्रिविधा -- ज्ञानम्, ज्ञेयं ज्ञाता च। एकां क्रियां कर्तव्यम् इति अवबोधः; तां क्रियां कर्तुं ज्ञातव्यं कर्म; कर्म ज्ञात्वा कर्म कुर्वन् च। भगवन्तं ज्ञातव्यम् इति कर्मणः पृष्ठे मूला प्रेरणा। कर्म कुर्वन्तः वयं अस्मदीयं अज्ञानं त्यक्त्वा ज्ञानं प्राप्तुम्; अस्मदीयम् अवबोधं वर्धयितुम्; तस्य अवबोधस्य भगवन्मुखता भवितुम्। वयम् अवबोधवन्तः भवितुमेव कर्मविधिनिषेधः शास्त्रकारेभ्यः आगतः।\n\nजीवाय कर्म कर्तव्यम् इति प्रेरणां कुर्वन् भगवान्। तदनुगुणम् एव जीवः कर्म करोति। यः जीवः किं भवितव्यम् इति जीवस्य स्वरूपसम्बद्धः विचारः। परं स्वयं जीवाय तत् अभिव्यक्तं कर्तुं शक्तिः नास्ति। भगवान् तस्य जीवस्वरूपस्य योग्यतानुगुणं तस्मिन् प्रेरणां करोति। भगवतः प्रेरणया जीवयोग्यता व्यक्ता भवति, तदनुगुणं जीवः कर्मणि प्रवर्तते। अत्र सर्वं मूलतः भगवत्स्वरूपम्। भगवतः ज्ञानम् -- भगवत्स्वरूपम्, भगवतः क्रिया -- भगवत्स्वरूपम्, भगवतः प्रेरणा -- भगवत्स्वरूपम्। भगवतः स्वरूपं साक्षात् कार्यं कुर्वत् तिष्ठति। सः एव ज्ञानम्, सः एव ज्ञेयम्, सः एव ज्ञाता। अतः तस्य प्रेरणा ज्ञानस्वरूपम्; तस्य प्रेरणा ज्ञातृस्वरूपम्; तस्य प्रेरणा ज्ञेयम्। एवं ज्ञानस्वरूपस्य भगवतः प्रेरणया जीवः कर्म करोति, सर्वं तस्य अधीनं भवति।\n\nसमग्रतया कर्मणः कारणानि संक्षेपेण त्रिविधानि -- देहेन्द्रियादीनि उपकरणानि, कर्म च कर्ता (जीवः, भगवान्, दैवं च)।\n\nत्रिगुणस्य विषये पूर्वं पर्याप्तं विवृत्य कृष्णः, अत्र जीवनाय अतिमुख्यां त्रैगुण्यविद्यां विवृतवान्।",
  "18.19": "ज्ञानं कर्म च कर्ता च त्रिधा एव गुणभेदतः ।\nप्रोच्यते गुणसंख्याने यथावत् शृणु तानि अपि ॥\n\nज्ञानम्, कर्म, कर्ता च गुणभेदेन त्रिधा एव इति गुणसङ्ख्याने [वैदिकसाङ्ख्यशास्त्रे] उक्तम्। तानि यथावत् शृणु।\n\nप्रत्येकस्य जीवनस्य त्रीणि मुख्यानि घटकानि -- ज्ञानम्, कर्म, कर्ता च। यत्किमपि कुर्वन्तः वयं ज्ञानेन कुर्मः -- तत् ज्ञानम्; तेन ज्ञानेन \"करणम्\" कर्म; ज्ञानस्य कर्मणश्च आश्रितः कर्ता। एतानि त्रीणि अपि त्रिगुणविभागं प्राप्य प्रत्येकं पुनः त्रिविधानि भवन्ति। शास्त्रे यत्र गुणानां विचारः क्रियते तत्र इदम् उक्तम्, तथा भगवता कपिलवासुदेवरूपेण जगते दत्ते \"परमसाङ्ख्ये\" इदम् उक्तम्। इदं कपिलवासुदेवेन सर्वप्रथमम् उक्तं, पुरातनकालात् विद्यमानं, जगते वक्तव्येषु विषयेषु अत्यन्तं प्रकृष्टं विषयम्। त्रैगुण्यं विना जीवनमेव नास्ति। अस्मदीयस्य जीवनस्य सर्वस्मिन् मुखे व्याप्तम् इदं त्रैगुण्यम् अवगत्य चेदेव वयम् अस्मदीयं जीवनं सुधारयितुं शक्नुमः, त्रिगुणातीतस्य भगवतः दिशम् अग्रे गन्तुं शक्नुमः। \"अतिपुरातनम् इमं मूलभूतं सत्यं तुभ्यं यथार्थतया वदामि -- तत् अवधानेन शृणु\" इति कृष्णः अर्जुनम् वदति।",
  "18.20": "सर्वभूतेषु येन एकं भावं अव्ययम् ईक्षते ।\nअविभक्तं विभक्तेषु तत् ज्ञानं विद्धि सात्त्विकम् ॥\n\nसमस्तेषु जीवेषु अपरिवर्तनीयम् एकं परतत्त्वं, विविधेषु वस्तुषु एकमेव अखण्डं भगवन्तं पश्यत् ज्ञानं सात्त्विकम् इति जानीहि।\n\nबृहदारण्यकोपनिषदि (४-५-११) उक्तं यथा -- \"अस्य महतः भूतस्य निःश्वसितम्\" इति। अर्थात् \"सम्पूर्णं जगत् तस्य महाभूतस्य श्वासस्य उद्गारः\" इति। विष्णुसहस्रनामे उक्तं यथा -- \"एको विष्णुर्महद्भूतं पृथग्भूतान्येकशः\" इति। अर्थात् एकः एव विष्णुः महच्चेतनम् (महाभूतम्); अल्पचेतनानि (भूतानि) अनेकानि इति। गीतायाः अस्मिन् श्लोके सात्त्विकम् अवबोधं वदन् कृष्णः वदति -- \"परस्परं भिन्ने, एकम् इवान्यत् नास्तीति विलक्षणे जीवप्रपञ्चे (सर्वभूतेषु) कमपि भेदं विना, पूर्णगुणक्रियायाम् अखण्डं सत्यं भूत्वा एकं तत्त्वं स्थितम्। अनन्ते एकः स्थितः, त्रैगुण्यवर्जितः भगवान् इति एतत् तत्त्वं यस्मै अवबोधाय गोचरं भवति सः अवबोधः सात्त्विकः\" इति।",
  "18.21": "पृथक् त्वेन तु यत् ज्ञानं नानाभावान् प्रथग् विधान् ।\nवेत्ति सर्वेषु भूतेषु तत् ज्ञानं विद्धि राजसम् ॥\n\nसमस्तेषु जीवेषु विद्यमानान् विविधान् भावान् पृथक्तया, भिन्नतया ज्ञातृ ज्ञानं राजसम् इति जानीहि। [समस्तजीवेषु भेदम् एव अभिज्ञातृ, एकम् इव अन्यत् नास्ति इति ज्ञातृ, परं भगवत्प्रज्ञया रहितं केवलं भौतिकं यथार्थावबोधम्।]\n\nएकभक्तिं विना अनेकदेवतावादे विश्वासः राजसम् अवबोधम्। एतेभ्यः अखण्डस्य परतत्त्वस्य जागृतिः न भवति। एते भिन्नेषु सन्दर्भेषु भिन्नाः देवताः पूजयन्ति। अद्यतनं ज्योतिष्यमपि जनान् एतस्मिन् मिथ्यामार्गे गन्तुं प्रेरयति। अखण्डस्य भगवतः जागृतिं विना एकैकस्मै ग्रहचारे एकैकां देवतां पूजयनम् राजसम् अवबोधम्। यत्किमपि पूजनं भवतु तत् सर्वनियामकस्य भगवतः जागृत्या कृतं चेत् तत् पूजनं सात्त्विकं भवति। अस्मात् भिन्नतया नानादेवताः पृथक्तया पूजिताः चेत् तदेव पूजनं राजसं भवति।",
  "18.22": "यत् तु कृत्स्नवत् एकस्मिन् कार्ये सक्तम् अहैतुकम् ।\nअतत्त्व अर्थवत् अल्बं च तत् तामसम् उदाहृतम् ॥\n\nयत् किञ्चित् क्षुद्रं कार्यम् एव सर्वस्वम् इति [अपरिवर्तनीयं जीवं परिवर्तनीयं भगवन्तम् इति, सम्पूर्णं विश्वं एकस्य जीवस्य कल्पनाविलासः इति] विश्वसत्, अकारणम्, अयथार्थम् [विश्वं यथार्थं न इति ग्रहीतृ] क्षुद्रम् अवबोधं तामसम् इति भवति।\n\nतामसस्वभावाय अनेकानि मुखानि। दृश्यमानं बहु, वस्तुतः एकम् इति ज्ञातृ; जीवात् भिन्नं भगवन्तम् अस्वीकुर्वत्; अस्मिन् जगति यथार्थवस्तुनः अस्तित्वमेव नास्ति इति ज्ञातृ; अज्ञानम्, तस्मात् विपरीतज्ञानम्; अवबोधरहितोऽपि आत्मानं महाज्ञानी इति भ्राम्यत्; कमपि एकं विषयं ज्ञात्वा \"अहं सर्वं ज्ञातवान्\" इति मन्यमानम् -- इत्यादि तामसम् अवबोधम् इति भवति। वयम् अस्मदीयस्य ज्ञानस्य इतिमितिं ज्ञात्वा प्रतिक्षणं तस्मात् अधिकं सत्यं ज्ञातुं निरन्तरं यतितव्याः -- अन्यथा वयं तामसाः भवामः। द्वैतसिद्धान्तः वयं सम्यक् अवगन्तुं चेत् अद्वैतं विशिष्टाद्वैतं च पठितव्यम्। हिन्दुत्वम् अवगन्तुं चेत् मुस्लिम् क्रैस्तधर्मौ किं वदतः इति अवबोधः अस्मासु स्यात्। इदं विहाय \"मया विश्वस्तम् एव सत्यम्, शेषं सर्वं मिथ्या\" इति ग्रहीतुः मूढम् अवबोधं तामसं भवति। सदा सत्यस्य अन्वेषणम्, ज्ञानस्य दाहः -- अस्मान् सात्त्विकतां प्रति नयितुं समर्थम्। ज्ञानं स्वस्य लौकिकव्यावहारिकजीवने सीमितं कृत्वा, अन्यस्मिन् विद्यमानं सात्त्विकं ज्ञानम् अभिज्ञाय, परमात्मनः प्रज्ञां विना अनुष्ठाने जीवितुं कारयत् मूढम् अवबोधं तामसम्।",
  "18.23": "नियतम् संगरहितम् आराग द्वेषतः कृतम् ।\nअफलप्रेप्सुना कर्म यत् तत् सात्त्विकम् उच्यते ॥\n\nआसक्तिं विना, रागद्वेषौ विना, फलेच्छां विना कृतं नियतं कर्म सात्त्विकम् इति उच्यते।\n\nअस्मभ्यं प्राप्तं विहितकर्म भगवतः पूजारूपेण कृतं चेत् तत् सात्त्विकं कर्म भवति। अस्मिन् कर्मणि कोऽपि रागद्वेषः न, फलापेक्षा न, कापि आसक्तिः न। श्रद्धाभक्तिभ्यां, निर्लिप्ततया, कर्तव्यं निर्वञ्चनया भगवदर्पणभावेन कृतं कर्म सात्त्विकं कर्म।",
  "18.24": "यत् तु काम ईप्सुना कर्म सअहंकारेण वा पुनः ।\nक्रियते बहुल आयासम् तत् राजसम् उदाहृतम् ॥\n\nफलेच्छया वा अहङ्कारेण वा, देहं क्लेशं नीत्वा, दण्डयित्वा कृतं कर्म राजसम् इति उच्यते।\n\nकृतं कर्म शुभमेव, परं तस्य पृष्ठे अनेकाः इच्छाः, \"मया कृतम्\" इति अहङ्कारः च मिलिते सति तत् राजसं कर्म भवति। अस्मदीयायाः समस्यायाः निवारणाय कर्म करणम्, कर्म कुर्वति बहुविधाः फलेच्छाः धृत्वा करणम्, कृतानन्तरं \"मया कृतम्\" इति अहङ्कारं धरणम् -- राजसकर्मणः लक्षणम्। जीवनपर्यन्तं यां कां चित् इच्छां अनुधावन्, श्वः सुखम् इच्छन्, अद्यतनं सुखं विस्मृत्य देहं क्लेशं नीत्वा कृतं कर्म राजसं कर्म।",
  "18.25": "अनुबंधं क्षयं हिंसाम् अनपेक्ष्य च पौरुषम् ।\nमोहात् आरभ्यते कर्म यत् तत् तामसम् उच्यते ॥\n\nपरिणामं, नाशं, हिंसां च अगणयित्वा, स्वयोग्यताम् अतिक्रम्य मोहेन आरब्धं कर्म तामसम् इति उच्यते।\n\nस्वयोग्यतां ज्ञात्वा विना, अग्रे किं भविष्यति इति चिन्तनम् अपि अकृत्वा, फलापेक्षया, त्वरया, अहङ्कारेण द्वेषेण च, भगवन्तं विस्मृत्य कृतं समाजविनाशकं कर्म तामसं कर्म। अस्मै उत्तमः दृष्टान्तः दुर्योधनस्य कर्माणि। अग्रे भाविनः दुरन्तस्य विषये अचिन्तयित्वा, अन्यस्य अनिष्टं भवतु इति अनिष्टचिन्तनेन कृतं कर्म तामसम्। शुभं कर्मापि दुष्टेन उद्देशेन कृतं तामसं भवति।",
  "18.26": "मुक्त संगः अनहंवादी धृति उत्साह समन्वितः ।\nसिद्धि असिध्योः निर्विकारः कर्ता सात्त्विकः उच्यते ॥\n\nआसक्तिरहितः, \"मया कृतम्\" इति अवदन्, धृत्युत्साहाभ्यां युक्तः, सिद्ध्यसिद्ध्योः निर्विकारः -- एतादृशः कर्ता सात्त्विकः इति उच्यते।\n\nसात्त्विकः कर्ता किमपि न आसजति। यथा कस्याश्चित् पूजायाः अन्ते \"श्रीकृष्णार्पणमस्तु\" इति अर्पणस्य परिपाटी अस्ति, तथैव सात्त्विकः स्वजीवने स्वकृतं सर्वं कर्म भगवद्भक्त्या भगवदर्पणभावेन करोति। तस्मै \"मया कृतम्\" इति अहङ्कारः एव नास्ति। यत्किमपि कार्यं भवतु सः तत् अत्युत्साहेन करोति। कृतं कार्यं न सिध्येत् सति सः न अवसीदति, यशस्वी भवति सति उत्प्लवं न करोति। सर्वं निर्विकारेण करोति। इदमेव द्वादशस्तोत्रे आचार्यैः सुन्दरतया उक्तम् -- \"कुरु भुङ्क्ष्व च कर्म निजं नियतं हरिपादविनम्रधिया सततम्। हरिरेव परो हरिरेव गुरुः हरिरेव जगत्पितृमातृगतिः॥\" इति। \"तव भागस्य कर्म त्वं कुरु, प्राप्तम् अश्नुहि। हरिपादयोः स्मृतिः न त्रुट्येत्\" -- इदं सात्त्विकस्य जीवनस्य मूलमन्त्रम्।",
  "18.27": "रागी कर्मफल प्रेप्सु लुब्धः हिंसा आत्मकः अशुचिः ।\nहर्ष शोक अन्वितः कर्ता राजसः परिकीर्तितः ॥\n\nआसक्तः, कर्मफलेच्छुः, लुब्धः, हिंसात्मकः, अशुचिः, हर्षशोकयुक्तः -- एतादृशः कर्ता राजसः इति उक्तः।\n\nराजसः शुभं कर्म करोति, परं तस्मिन् \"हर्षशोकौ\" पूर्णौ भवतः। सः स्वकर्मणि यशस्वी भवति सति आकाशम् आरोहति, कर्म न सिध्येत् सति पातालं गच्छति। अस्य मूलं कारणं -- राजसः प्रत्येकं कर्म फलेच्छया एव करोति। सः कर्म आसज्य, कर्मफलस्य अपेक्षायां कर्तव्यं निर्वहति। कुर्वति कार्ये लोभः, श्रद्धां विना करणम्, कर्म कुर्वति मानसी अस्वच्छता -- राजसस्य स्वभावः।",
  "18.28": "अयुक्तः प्राकृतः स्वब्धः शठः नैकृतिकः अलसः ।\nविषादी दीर्फ्थसूत्री च कर्ता तामसः उच्यते ॥\n\nअनियन्त्रितः, प्राकृतः [भगवद्भक्तिरहितः], उद्धतः, हठी, कपटी, आलस्ययुक्तः, खिन्नः, कार्यविलम्बकः च -- एतादृशः कर्ता तामसः इति उच्यते।\n\nतामसेषु बहुविधाः --\n\n(१) अयुक्तः -- कुर्वति कर्मणि श्रद्धाविश्वासयोः अभावः। कर्म कुर्वति कर्मनियामके भगवति मनोयोगस्य अभावः।\n\n(२) प्राकृतः -- देवे विश्वासरहिताः। केवलं प्राकृते प्रपञ्चे आसक्तिं धरन्तः।\n\n(३) स्तब्धः -- स्वकृते कर्मणि दोषः स्यात् चेदपि तं न सुधार्यन्, अवबोधरहिताः, मिथ्याविश्वासम् एव आचरन्तः गच्छन्तः।\n\n(४) शठः -- दोषः इति ज्ञातेऽपि सुधारयितुम् इच्छारहिताः। \"अहं किमर्थं शिरः नमयेयम्\" इति मनोवृत्तिः धरन्तः।\n\n(५) नैकृतिकः -- साधुत्वस्य वेषं धृत्वा, बुद्धिपूर्वकम् अन्यस्मै वञ्चनां कृत्वा लाभं गृह्णन्तः।\n\n(६) अलसः -- किं शुभम् इति ज्ञातम्, परं कर्तुम् आलस्यं धरन्तः।\n\n(७) विषादी -- एकां क्रियां \"अहो कर्तव्यम्\" इति खेदेन कुर्वन्तः। कृतस्यानन्तरम् अपि पुनः खेदं व्यक्तं कुर्वन्तः।\n\n(८) दीर्घसूत्री -- \"पुनः करिष्यामि\" इति दीर्घकालं कार्यं विलम्बयन्तः। अन्यस्य सद्गुणं अदृष्ट्वा तस्य कञ्चन पुरातनं दोषम् उद्धृत्य वदन्तः।\n\nअत्र उक्तेषु यः कोऽपि एकः गुणः स्यात् चेदपि सः तामसः इति भवति। उदाहरणार्थम् एतान् सर्वान् गुणान् धृतवान् व्यक्तिः महाभारते दुर्योधनः।",
  "18.29": "बुद्धेः भेदम् धृतेः च एव गुणतः त्रिविधम् शृणु ।\nप्रोच्यमानम् अशेषेण पृथक् त्वेन धनंजय ॥\n\nहे धनञ्जय, बुद्धेः धृतेः च गुणानुगुणं त्रिविधं भेदम् पूर्णतया पृथक्तया वदिष्यमाणं शृणु।\n\nदेहेन्द्रियाणि पूर्णप्रमाणेन विकासं प्राप्तानि मानवेषु। अतः मानवशरीरं \"पुरम्\" इति उच्यते। अस्मिन् देहे विद्यमानाय जीवाय (पुरुषाय) बुद्धिः धृतिः च अतिमुख्यौ अंशौ। वयम् अस्मदीये जीवने कापुरुषाः न भूत्वा बुद्धिमन्तः भूत्वा जीवेम। अस्यां बुद्धौ धृतौ च त्रिविधाः -- सात्त्विकाः, राजसाः, तामसाश्च। वयम् अस्मदीये जीवने राजसं तामसं च नानुसरेम। अतः किं राजसं किं तामसम् इति विचारः अस्माभिः ज्ञातव्यः। \"बुद्धिधृत्योः त्रिविधं प्रकारं पूर्णतया, पृथक्तया वदामि -- अवधानेन शृणु\" इति कृष्णः अर्जुनं वदति। वयं सात्त्विकां धृतिं जित्वा धनञ्जयाः भवेम इति कृष्णस्य अस्य सन्देशस्य मूलम् उद्देश्यम्।",
  "18.30": "प्रवृत्तिम् च निवृत्तिम् च कार्य अकार्ये भय अभये ।\nबंधं मोक्षम् च या वेत्रि बुद्धिः सा पार्थ सात्त्विकी ॥\n\nप्रवृत्तिं निवृत्तिं, कार्यम् अकार्यं, भयम् अभयम्, बन्धं मोक्षं च या जानाति -- हे पार्थ, सा बुद्धिः सात्त्विकी।\n\nअस्मदीये जीवने मुख्यतया उदयमानः प्रश्नः -- \"एकं कार्यं कर्तव्यं वा न वा\" इति भ्रान्तिः। किं ग्रहीतव्यम्, किं त्याज्यम्; किं शुभं कर्म, किम् अशुभं कर्म इति निर्णयः; मम कर्तव्यं किम् इति अवबोधः; धर्माधर्मौ; पापपुण्ये; भयाभये; बन्धमोक्षयोः मार्गः -- एतत् सर्वं विषये निश्चितः निर्णयः सात्त्विके मनसि भवति। इदं स्वार्थस्य लेशं विना (अपार्थं) प्रज्ञानम्; ज्ञानस्य गभीरतां प्राप्ते सति आगच्छत् प्रज्ञानम्; बुद्धेः विस्तारे (पार्थे) सति आगच्छत् प्रज्ञानम्। विश्लेष्य वयं सन्मार्गे गन्तुं निर्णयं कर्तुं शक्नुमः तादृशी विवेकप्रज्ञा। अस्मदीयम् आत्मसाक्षिणं कदापि वयं वञ्चयितुं न शक्नुमः। प्रत्येकस्य आत्मसाक्षी ददत् निर्णयः निश्चितः निर्णयः भवति, सः सात्त्विकः।",
  "18.31": "यया धर्मम् अधर्मम् च कार्यम् च अकार्यम् एव च ।\nअयथावत् प्रजानाति बुद्धिः सा पार्थ राजसी ॥\n\nधर्मम् अधर्मं, कार्यम् अकार्यं च यथार्थतया न जानाति या बुद्धिः -- हे पार्थ, सा राजसी।\n\nकदाचित् धर्मम् एव अधर्मम् इति ज्ञातृ, अथवा अधर्मम् एव धर्मम् इति ज्ञातृ; कदाचित् किं सम्यक् किम् असम्यक् इति भ्रान्तौ पतत् -- राजसी बुद्धिः। जीवने उपयोगाय न आगच्छत् एतादृशी बुद्धिः किं कर्तव्यम् किं न कर्तव्यम् इति सम्यक् निश्चेतुं न शक्नोति।",
  "18.32": "अधर्मम् धर्मम् इति या मन्यते तमसा आवृता ।\nसर्व अर्थान् विपरीतान् च बुद्धिः सा पार्थ तामसी ॥\n\nहे पार्थ, अधर्मम् एव धर्मम् इति गृह्णती, तमसा आवृता, सर्वान् अर्थान् विपरीततया गृह्णती बुद्धिः तामसी।\n\nविद्यमानं विषयं यथार्थतया न गृह्णती, विपरीततया एव गृह्णती बुद्धिः तामसी। एते दुःखं दुःखम् इति न गृहीत्वा सुखम् इति गृह्णन्ति। उदाहरणार्थं मद्यपानं करणम् आनन्दम् इति भ्रान्त्वा मद्यव्यसनिनः भवनम्। ज्ञानम् एव अज्ञानम् इति ज्ञात्वा, स्वस्य विपरीतज्ञानम् एव सर्वस्वम् इति स्थापयित्वा, अन्यस्य वचनाय कर्णं यत् न ददाति तादृशी बुद्धिः तामसी बुद्धिः।\n\nयस्मै शुभा बुद्धिः अस्ति तस्मै धृतिः भवति। अज्ञानात् भयम्, अवबोधात् अभयम्। वेदान्तस्य अस्तित्वमेव अभयार्थम्, मनसि धैर्यं पूरयित्वा मनुष्यं निर्भयं कर्तुम्।\n\n\"धृति\" इत्यस्य उपरिदृष्टिः अर्थः -- धैर्यम्, आत्मविश्वासः, हृदयबलम् इत्यादि। अस्य पूर्णप्रमाणस्य अर्थः अद्यापि विशालः। अष्टाङ्गयोगे (यम, नियम, आसन, प्राणायाम, प्रत्याहार, ध्यान, धारण, समाधिः) उक्तं \"धारणम्\" एव धृतिः। विषयं गृहीत्वा तं मनसि धारयितुम् धृतिः। एतादृश्यां धृतौ अपि त्रिविधाः -- सात्त्विकी, राजसी, तामसी च। अस्याः सुन्दरं विवरणम् अग्रिमेषु त्रिषु श्लोकेषु द्रष्टुं शक्यते।",
  "18.33": "धृत्या यया धारयते मनः प्राण इंद्रिय क्रियाः ।\nयोगेन अव्यभिचारिण्या धृतिः सा पार्थ सात्त्विकी ॥\n\nहे पार्थ, भक्तियोगेन अविच्छिन्नतया मनसः प्राणस्य इन्द्रियाणां च क्रियाः दृढतया मार्गभ्रष्टं विना धारयति या धृतिः -- सा सात्त्विकी।\n\nयया धृत्या मनः देहः इन्द्रियाणि च मार्गभ्रष्टं विना, परस्परं पूरकतया भक्तियोगे कार्यं कुर्वन्ति -- सा धृतिः सात्त्विकी। मनः यथार्थं गृह्णाति, इन्द्रियाणि देहश्च तस्मै पूरकतया भक्त्या कार्यं कुर्वन्ति। अत्र योगः इत्युक्ते भगवद्भक्तये पूरकतया वास्तवं ग्रहीतुम् उपायः -- सः एव अस्मदीयः आत्मविश्वासः। अस्मिन् अनेकानि मुखानि सन्ति। उदाहरणार्थं \"दोषं दोषः इति वदितुं धैर्यम्\"। सामान्यतः दोषं दोषः इति वदितुं अनेकानि विघ्नानि भवन्ति। अस्मै प्रथमं विघ्नं दाक्षिण्यम्। भगवद्भक्तये पोषकं वयं निर्दयतया वदेम। धैर्येण दोषं प्रतिभटयेम। विपरीतग्रहणम् अकृत्वा, दुर्मार्गे अगत्वा, भगवद्भक्तेः विरुद्धं आचरणं अकृत्वा, सत्यं निष्ठुरतया वदनं सात्त्विकी धृतिः। मनः दुष्टं न चिन्तयति, देहः दुष्टं प्रति न चलति, इन्द्रियाणि दुष्टं न गृह्णन्ति -- एवं भगवद्भक्तये पोषकं सर्वं सात्त्विकी धृतिः।\n\nसामान्यतः वयम् अस्मदीयं देहम् इन्द्रियाणि च नियन्त्रयितुं शक्नुमः, परं मनः दुष्टं न चिन्तयेत् इति नियन्त्रणं कर्तुं अतीव दुष्करं कार्यम्। इदं साधयितुं दीर्घकालस्य साधना अपेक्षिता। एतत् सर्वं विषयं ज्ञातवति वयं सात्त्विकाया धृतेः कियत् दूरे स्थिताः इति ज्ञायते, अस्मान् सुधारयित्वा सात्त्विकां धृतिं प्रति गन्तुं साहाय्यं भवति।",
  "18.34": "यया तु धर्म काम अर्थान् धृत्या धारयते अर्जुन ।\nप्रसंगेन फल आकांक्षी धृतिः सा पार्थ राजसी ॥\n\nहे अर्जुन, धर्मकामार्थान् अतिशयेन आसज्य फलाकाङ्क्षी या धृत्या धारयते -- हे पार्थ, सा धृतिः राजसी।\n\nमाता स्वशिशुं निःस्वार्थतया प्रीणाति यथा, तथा भगवन्तं प्रीणनं भक्तिः। अस्यां प्रीतौ फलापेक्षा मिश्रिता चेत् सा भक्तिः इति न, स्वार्थः इति भवति। राजसः स्वेष्टार्थसिद्ध्यर्थं यावत् शक्यं धर्मस्य आवरणे एव कार्यं निर्वहति। परं सः धनार्जनार्थं वा अतिशयेन मोहेन फलाशां धृत्वा दृढतां स्वायत्तां करोति। इयं राजसी धृतिः। वयं राजसगुणस्य स्पर्शं विना शुभ्रा (अर्जुनाः) शुद्धसात्त्विकाः भवेम इति कृष्णस्य सन्देशः।",
  "18.35": "यया स्वप्नं भयं शोकं विषादं मदम् एव च ।\nन विमुंचति दुर्मेधा धृतिः सा पार्थ तामसी ॥\n\nहे पार्थ, निद्रां भयं शोकं विषादं मदं च त्यक्तुं न शक्नोति दुर्बुद्धिः यया धृत्या -- सा तामसी।\n\nग्रहणे तामसप्रवृत्तिं धारयन् दुर्बुद्धिः अविवेकी। सः शुभेभ्यः ग्रहणेभ्यः कदापि न गच्छति। शुभस्य विषयस्य चर्चायां सः निद्रां करोति। तस्मै सर्वदा भयम्। [उदाहरणार्थं लञ्चग्रहणं, तेन जीवनपर्यन्तं भयेन जीवनम्।] तस्य जीवने चेतनता, उत्साहः, विजयः च न भवति। \"अहमेव श्रेष्ठः, शेषाः कनिष्ठाः\" इति अशास्त्रीयः सङ्कल्पः तामसी धृतिः।",
  "18.36": "सुखं त्विदानीं त्रिविधं शृणु मे भरतर्षभ ।\nअभ्यासाद् रमते यत्र दुःखांतं च निगच्छति ॥\n\n[एतयोः द्वयोः श्लोकयोः (१८.३६ तथा १८.३७) पदच्छेदः, अर्थः, विवरणं च सह अग्रिमे श्लोके (१८.३७) दत्तम्।]",
  "18.37": "सुखम् तु इदानीम् त्रिविधम् शृणु मे भरतर्षभ ।\nअभ्यासात् रमते यत्र दुःखांतम् च निगच्छति ।\n\nयत् तत् अग्रे विषम् इव परिणामे अमृत उपमम् ।\nतत् सुखम् सात्विकम् प्रोक्तम् आत्म बुद्धि प्रसादजम् ॥\n\nहे भरतर्षभ, अधुना त्रिविधं सुखं मत्तः शृणु -- अभ्यासेन आनन्दं ददत्, दुःखस्य अन्तं नयत्, आरम्भे विषवत् परिणामे अमृतोपमम् इदं सुखं सात्त्विकम् इति उक्तम्। इदम् आत्मनः बुद्धेः प्रसन्नतायाः जनितम्।\n\nमनुष्यः समष्ट्या जीवने इच्छति सुखम् एव। तस्य जीवनस्य अन्तिमं लक्ष्यं सुखम्। परं यथार्थं सुखं किम्? सुखेऽपि त्रिविधम् -- सात्त्विकं, राजसं, तामसं च। \"त्रैविद्यस्य विवरणस्य अन्ते सुखस्य त्रिविधं विवरणं शृणु\" इति कृष्णः वदति। अत्र प्रयुक्तं \"भरतर्षभ\" इति विशेषणस्य पृष्ठे व्यासैः अस्मभ्यं अनेकं सन्देशं दत्तम् इति वयं गमनयेम। भगवतः भक्तौ रतः (श्रेष्ठः) भूत्वा; भरतवत् लौकिकसुखस्य इच्छां विना पूर्णप्रमाणेन श्रीरामचन्द्रं प्रीणयन्; भगवद्भक्तौ निरतेषु श्रेष्ठे वायौ (हनुमति) गुरुभक्तिं धृत्वा, भगवदर्पणभावेन अस्मदीयं कर्म निर्वहन् -- वयं भरतर्षभाः भवितुं शक्नुमः। भरतर्षभः भूत्वा यथार्थं सुखं किम् इति ज्ञात्वा तत् अनुभवितुं शक्यते।\n\nयत्किमपि एकं विषयं प्रारम्भादेव सुखम् इति दृश्यते चेत् तत् सात्त्विकं सुखं न। कष्टं विना अनायासेन प्राप्तं मोहस्य सुखम्। सात्त्विकं सुखं प्रथमं कष्टरूपेण भवति। अस्मै उत्तमः दृष्टान्तः समुद्रमन्थनम्। तत्र प्रथमम् आगतं वस्तु अमृतं न, अपि तु विषम्। यथार्थम् अमृतं प्राप्तं अन्ते। \"हस्तौ कर्दमीभूतौ भवतः चेत् मुखे दधि\" -- कष्टपटित्वा सुखम्। वयं पिबामः औषधं विषवत् तिक्तम्, परं तस्मात् आगच्छत् आरोग्यम् अमृतवत् मधुरम्।\n\nअत्र कृष्णः \"आत्मबुद्धिप्रसादजम्\" इति एकम् अपूर्वं विशेषणं प्रयुक्तवान्। आत्मप्रसादः इत्युक्ते देवस्य अनुग्रहः। सात्त्विकं सुखं वयम् आवश्यकम् इति इच्छितमात्रेण न लभ्यते। तत् भगवतः अनुग्रहेण लभ्यते। तत् प्राप्तुं अस्मभ्यं पारदर्शकं शुद्धं मनः आवश्यकम्। तत् बहिः आगच्छत् न, अपि तु अन्तः उच्छलत्। एवं भगवतः अनुग्रहः मनसः प्रसन्नता च सत्यां अन्तरस्य स्वरूपानन्दस्य सुखम् अनुभवितुं शक्यते।",
  "18.38": "विषय इंद्रिय संयोगात् यत् तत् अग्रे अमृत उपमम् ।\nपरिणामे विषम् इव तत् सुखम् राजसम् स्मृतम् ॥\n\nविषयेन्द्रिययोः सम्पर्केण जातम्, आरम्भे अमृतोपमं, परिणामे विषवत् -- तत् सुखं राजसं स्मृतम्।\n\nयत् प्रथमम् अनुभवति सति अतीव सुखं ददाति, अनन्तरं परिणामः दुःखकरः भवति -- तत् राजसं सुखम्। इदं बाह्यसुखम्। इदं बहिःस्थैः विषयैः अस्मदीयैः इन्द्रियैश्च सम्पर्केण तात्कालिकतया लभ्यते सुखम्। अद्य वयं पश्यामः अधिकाः अपराधवार्ताः एतादृशस्य क्षणिकसुखस्य पृष्ठं गत्वा जायमानः परिणामः। विषयसुखम् अनुभवनं दोषः न, परं तत् अनुभूय तम् अतिक्रम्य स्थातुम् अतिमुख्यम्। पूर्वजाः मुख्यतया द्वे जेतव्ये इति उक्तवन्तः। एका आहारस्य व्यसनम्, अपरा लैङ्गिकी चापल्यम्। समग्रतया क्षणिकम् इन्द्रियसुखं जेतुम् अतिमुख्यम्।",
  "18.39": "यत् अग्रे च अनुबंधे च सुखं मोहनम् आत्मनः ।\nनिद्रा आलस्य प्रमाद उत्सं तत् तामसम् उदाहृतम् ॥\n\nआदौ अन्ते च आत्मानं मोहयत् सुखम्, निद्रा-आलस्य-प्रमादेभ्यः जातं सुखं तामसम् इति उक्तम्।\n\nमनुष्यं यथार्थप्रपञ्चात् भ्रान्तिं प्रति क्षिप्त्वा, मोहजाले पातयित्वा, दुर्बुद्धिं कारयित्वा, सन्तोषस्य भ्रान्तिं जनयत् सुखं तामसम्। अस्मिन् आदौ अपि सुखं नास्ति, अन्ते अपि सुखं नास्ति। उदाहरणार्थं मद्यपानं धूमपानं च इत्यादीनि सर्वाणि दुर्व्यसनानि। आलस्यात् आगच्छत् सुखम्, निद्रातः आगच्छत् सुखम्, अज्ञानतः आगच्छत् सुखम् -- एतानि अन्तरङ्गं मनः घातयित्वा प्राप्तं बाह्यं सुखम् -- इदं तामसम्। उदाहरणार्थं निद्रा। मनुष्यः शिशुः यदा तस्मै विंशतिघण्टाः निद्रा चतुर्घण्टाश्च जागरणम् आवश्यकम्। परं प्रबुद्धाय चतुर्घण्टानिद्रा पर्याप्ता। सः अभ्यासं कुर्यात् चेत् विंशतिघण्टाः जागरूकः स्थातुं शक्नोति। परं तामसं सुखं दिनं पूर्णं निद्रां करणम् एव परमं सुखम् इति भ्रान्तिं जनयित्वा मनुष्यं मार्गभ्रष्टं करोति।",
  "18.40": "न तत् अस्ति पृथिव्यां वादिवि देवेषु वा पुनः ।\nसत्त्वं प्रकृतिजैः मुक्तं यत् एभिः स्यात् त्रिभिः गुणैः ॥\n\nभूमौ, देवलोकेषु देवेषु वा -- प्रकृतितः जातेभ्यः एतेभ्यः त्रिभ्यः गुणेभ्यः मुक्तं जीवजातं नास्ति।\n\nत्रैगुण्यस्य विस्तृतं चित्रणं दत्त्वा कृष्णः जीवस्वभावस्य विवरणं ददाति। अस्यां भूमौ, सत्यलोकपर्यन्तं यत्किमपि देवतालोकं भवतु, समस्तानि जीवजातानि अस्याः प्रकृतेः निर्मितानां त्रिगुणानाम् अधीनानि। प्रत्येकं जीवम् अपि एतेषु त्रिषु स्वभावेषु अन्तर्भूतम्, प्रत्येकं जीवम् अपि एतेषां त्रयाणां गुणानां मिश्रणम्। शतांशेन शतांशं सात्त्विकः/राजसः/तामसः कोऽपि नास्ति। सम्पूर्णं जगत् त्रयाणां मिश्रणम्।\n\nजीवस्वभावं साक्षात् सात्त्विकः-राजसः-तामसः इति त्रिधा विभक्तुं न शक्यते। अतः कृष्णः इदं चातुर्वर्ण्यरूपेण विभज्य उक्तवान्। पूर्वं विवृतवद्वत् चातुर्वर्ण्यं \"जातिविभागः\" न। इदं वर्णविभागः। भगवद्गीता वा वेदः वा जातिविभागं भारं दत्त्वा न वदति। जातिविभागः केषुचित् धर्मशास्त्रेषु आगतम् एव, न तु वेदे भगवद्गीतायां वा। जातिः इत्युक्ते समाजव्यवस्थायै कृतं विभागम्। परं वर्णः मनःशास्त्रीयतया जीवस्वभावम् अवगत्य उक्तम्।\n\nस्थूलतया वक्तव्यं चेत् -- देवाः सात्त्विकाः, मानवाः राजसाः, दैत्याः तामसाः। परं इदं विभागम् अत्रैव न समाप्यते। एतेषु प्रत्येकस्मिन् वर्गे पुनः त्रयः विभागाः सन्ति। उदाहरणार्थं तामससात्त्विकाः -- मनुष्येषु नराधमाः तामससात्त्विकाः। दैत्यपरिवारजाः तामसराजसाः; तान् नियन्त्रयन्तः कालनेमिवत् दैत्याः तामसतामसाः।\n\nमानवेषु राजसतामसाः नराधमाः। राजसराजसाः इत्युक्ते नित्यसंसारिणः। ते कदापि तमः प्रति वा मोक्षं प्रति वा न गच्छन्ति। सदा अस्मिन् संसारचक्रे भ्रमन्ति। इतः तृतीयाः राजसात्त्विकाः मोक्षयोग्याः। चातुर्वर्ण्यम् इत्युक्ते एतस्मै तृतीयाय समूहाय एव सीमितम्। अतः मोक्षयोग्येषु राजसात्त्विकेषु चत्वारः विधाः -- मोक्षयोग्यः ब्राह्मणः, मोक्षयोग्यः क्षत्रियः, मोक्षयोग्यः वैश्यः, मोक्षयोग्यः शूद्रः च। इदं जीवस्वभावस्य उपरि विद्यमानः चतुर्विधः विभागः। अत्र उच्चनीचभेदः नास्ति। सर्वे मोक्षयोग्याः। सत्त्वरजस्तमसां प्रमाणानुगुणं पुनः अनेकविधाः चातुर्वर्ण्ये द्रष्टुं शक्याः।\n\n(१) परमहंसाः (९० अंशाः सात्त्विकाः) -- एते स्वात्मानं पूर्णतया भगवति स्थापितवन्तः। एतेषु राजसतामसयोः अंशः केवलं दश।\n\n(२) हंसाः (८५ अंशाः सात्त्विकाः) -- हंसाः परमहंसेभ्यः अनन्तरम्। एतेषु राजसतामसयोः प्रमाणं पञ्चदश अंशाः।\n\n(३) बहूदकाः (८० अंशाः सात्त्विकाः) -- एतेभ्यः स्थिरं स्थानं नास्ति। दिने दिने भिन्नस्थाने एतेषां वासः। एतेषु सात्त्विकः अंशः अशीतिः, राजसतामसौ अंशौ विंशतिः।\n\n(४) कुटीचकाः (७५ अंशाः सात्त्विकाः) -- एते बहूदकवत्, परं एकस्मिन् स्थाने एकस्मिन् गृहे वसन्तः। एतेषु राजसतामसयोः अंशः पञ्चविंशतिः।\n\n(५) वानप्रस्थाः (७० अंशाः सात्त्विकाः) -- गृहे गृहस्थाः भूत्वा, अनन्तरं स्वपुत्रेषु प्रायप्रबुद्धेषु सत्सु वनं गत्वा साधनां कुर्वन्तः। एतेषु त्रिंशत् अंशः राजसतामसौ, शेषाः सप्ततिः अंशः सात्त्विकः। एतेषां अग्निकर्म अस्ति, स्त्रीसङ्गः नास्ति।\n\n(६) ब्रह्मचारिणः (६५ अंशाः सात्त्विकाः) -- एतेषु पञ्चत्रिंशत् अंशः राजसतामसौ। एतेषां स्त्रीसङ्गः निषिद्धः।\n\n(७) गृहस्थाः -- एतेषु सात्त्विकः अंशः षष्टिः, शेषाः चत्वारिंशत् राजसतामसौ अंशौ। एते सांसारिकं जीवनं निर्वहितुं शक्नुवन्ति।\n\nएते सप्त विधाः ब्राह्मणवर्गसम्बद्धाः। समग्रतया वक्तव्यं चेत् न्यूनतमं षष्टिप्रमाणं सात्त्विकं अंशं धरन् मोक्षयोग्यः मानवः ब्राह्मणः इति भवति।\n\n(८) क्षत्रियाः (५५:३५:१०) -- एतेषु सात्त्विकः अंशः पञ्चपञ्चाशत्, राजसः अंशः पञ्चत्रिंशत्। एतेभ्यः आधिपत्ये आसक्तिः। स्वबाहुबलेन समाजस्य रक्षां करणं एतेषां कर्तव्यम्।\n\n(९) वैश्याः (४०:४०:२०) -- एतेषु सात्त्विकः राजसश्च अंशौ समानौ (चत्वारिंशत्)। एतेभ्यः कृषौ, गोरक्षायां, वाणिज्ये आसक्तिः।\n\n(१०) शूद्राः (३५:३५:३०) -- एते समग्रस्य समाजस्य आधारः। एतेषु सेवामनोवृत्तिः वर्तते।",
  "18.41": "ब्राह्मण क्षत्रिय विशाम् शूद्राणाम् च परंतप ।\nकर्माणि प्रविभक्तानि स्वभाव प्रभवैः गुणैः ॥\n\nहे परन्तप, स्वभावतः जातैः गुणैः अनुगुणं ब्राह्मणक्षत्रियवैश्यशूद्राणां कर्माणि पृथक्तया विभक्तानि सन्ति।\n\nजीवस्वभावानुगुणं मोक्षयोग्ये मानवे चतुर्विधाः वर्णाः सन्ति। स्वभावानुगुणं प्रत्येकस्य आचारः विचारः च। स्वभावभेदेन गुणकर्मणोः भेदः। इदं पूर्णतया जीवस्वभावसम्बद्धं विचारं भवति अतः अस्य जात्या सह कापि सम्बन्धः नास्ति। जातिः देहसम्बद्धा, वर्णः जीवस्वरूपसम्बद्धः। [चातुर्वर्ण्यस्य विषये अधिकं विवरणं अध्याय-४, श्लोक-१३ इत्यत्र विवृतम्।] एतेषां चतुर्णां वर्णानां सहजकर्मणः विवरणम् कृष्णः अग्रिमेषु श्लोकेषु विवृणोति।",
  "18.42": "शमः दमः तपः शौचं क्षांति आर्जवम् एव च ।\nज्ञानं विज्ञानम् आस्तिक्यं ब्रह्मकर्म स्वभावजम् ॥\n\nमनसः शमः, इन्द्रियाणां दमः, तपः, शुचित्वम्, क्षान्तिः, ऋजुता, ज्ञानम्, विज्ञानम्, आस्तिक्यं च -- ब्राह्मणस्वभावस्य सहजानि कर्माणि।\n\nजीवस्वभावः \"ब्राह्मणः\" चेत् तेषां सहजानि कर्माणि कीदृशानि इति कृष्णः अस्मिन् श्लोके विवृतवान्। अस्य वर्णस्य स्वभावाः इमे --\n\n(१) शमः -- मनसः भगवति स्थापनम्।\n\n(२) दमः -- इन्द्रियाणां नियन्त्रणम्।\n\n(३) तपः -- मानसिकतया विषयस्य गभीरं चिन्तनम्, मनसः शुभचिन्तनाय पोषकतया व्रतानुष्ठानम्, निरन्तरं शास्त्रचिन्तनम्।\n\n(४) शौचम् -- मनसः शुद्धिः, तत्पोषकतया बाह्या शुद्धिः।\n\n(५) क्षान्तिः -- दोषं कृतवद्भ्यः अपि क्षमां कुर्वत्, क्रोधरहितं मनः।\n\n(६) आर्जवम् -- स्वच्छं निरालं मनः, ऋजुः आचारः वाक् च।\n\n(७) ज्ञानम् -- भगवद्विषयकं ज्ञानम्।\n\n(८) विज्ञानम् -- भगवतः विषये गभीरः अवबोधः, भगवतः गुणानां विशिष्टं ज्ञानम्।\n\n(९) आस्तिक्यम् -- पूर्णतया भगवतः अस्तित्वे विश्वासं धृत्वा अग्रे गमनम्।\n\nएते सर्वे गुणाः सर्वेषु वर्णेषु भवितव्याः। परं अधिकप्रमाणेन विद्यमानाः ब्राह्मणवर्णे। एतेषु एकस्यापि गुणस्य प्रमाणं न्यूनं स्यात् चेदपि सः ब्राह्मणः इति न भवति। यदि क्षत्रियेषु एतेषां गुणानां प्रमाणं ब्राह्मणेभ्यः अधिकं दृश्येत चेत् सः राजर्षिः इति भवति। [उदाहरणार्थं जनकमहाराजः।]",
  "18.43": "शौर्यं तेजः धृतिः दाक्ष्यम् युद्धे च अपि अपलायनम् ।\nदानम् ईश्वर भावः च क्षात्रम् कर्म स्वभावजम् ॥\n\nशौर्यम्, तेजः, धृतिः, दाक्ष्यम्, युद्धे अपलायनम्, दानम्, ईश्वरभावः च क्षत्रियस्वभावस्य सहजानि कर्माणि।\n\nक्षत्रियस्य सहजानि कर्माणि अत्र कृष्णः विवृतवान्।\n\n(१) शौर्यम् -- प्रतियोधान् वशीकर्तुं शक्तिः।\n\n(२) तेजः -- प्रतियोधाः दृष्ट्वैव शिरः नमयेयुः तादृशं तेजः।\n\n(३) धृतिः -- प्राणापाये अपि अकुण्ठितः अग्रे गच्छत् साहसप्रवृत्तिः।\n\n(४) दाक्ष्यम् -- शत्रून् वशीकर्तुं चातुर्यम्, तन्त्रकौशलम्।\n\n(५) युद्धे अपलायनम् -- युद्धभूमौ पृष्ठं अदत्त्वा, पलायनम् अकृत्वा युध्यमानं धैर्यम्।\n\n(६) दानम् -- दानधर्मस्य करणम्।\n\nएते षड् गुणाः क्षत्रिये अधिकप्रमाणेन भवन्ति। अन्येषु वर्णेषु इदं न्यूनप्रमाणेन। इतः क्षत्रियेभ्य एव विशिष्टः एकः गुणः (७) -- ईश्वरभावः -- अपराधिने योग्यं दण्डं दातुं अधिकारः। अन्येषां वर्णानां कृते इदम् अधिकारः नास्ति।",
  "18.44": "कृषि गोरक्ष्यवाणिज्यं वै श्यकर्म स्वभावजम् ।\nपरिचर्यात्मकं कर्म शूद्रस्य अपि स्वभावजम् ॥\n\nकृषिः, गोरक्षणम्, वाणिज्यं च वैश्यस्य स्वभावसहजं कर्म। सेवारूपं कर्म शूद्रस्वभावाय सहजम्।\n\nवैश्यस्य स्वभावसहजं कर्म कृषिः, गोरक्षा वाणिज्यं च। भीष्माचार्याः धर्मरायाय राजधर्मम् उपदिशन्तः वदन्ति -- \"यस्मिन् देशे कृषकाः वाणिज्योद्यमिनश्च करभारं सोढुम् अशक्ताः अन्यं देशं गच्छन्ति, सः देशः न उद्धृतः भवति\" इति। कृषिः वाणिज्यं गोपालनं च देशस्य पृष्ठास्थि। इदं कार्यं वैश्यस्य स्वभावसहजं कर्म।\n\nशूद्रेषु अन्यस्य सेवां कुर्वती सेवागुणः महत्त्वपूर्णः। इदं गुणं रहितः मनुष्यः एव न। कोऽपि एकवर्णः न। सर्वेषु सर्वे स्वभावाः सन्ति। यः स्वभावः अस्मासु अधिकः अस्ति (majority) तस्मिन् वर्णे वयं अन्तर्भवामः। शूद्रस्वभावः कियान् मुख्यः यत् -- अस्य स्वभावं विना अन्यस्य स्वभावस्य मूल्यं नास्ति। सदा वयं कुर्वत् कर्म सेवामनोवृत्त्या कुर्याम। उदाहरणार्थं ब्राह्मणः समाजसेवाभावेन ज्ञानदानं कुर्यात्। अन्यथा तत् ज्ञानदानम् इति न भवति।\n\nवर्णस्य विषये कृष्णः अतीव रोचकं विवरणं दत्तवान्। समाजे केषुचित् प्राचीनेषु ग्रन्थेषु च वर्णं जातिः इति शब्देन, जातिं च वर्णः इति शब्देन उपयुक्तं दृश्यते। एतादृशे सन्दर्भे वयं विभ्रान्तिं विना, तत्र यस्मिन् अर्थे उक्तं तत् ज्ञात्वा अवगन्तव्यम्। उदाहरणार्थं \"वर्णपद्धतिं मम राज्ये कथं पालयेयम्\" इति पृष्टाय धर्मरायाय भीष्माचार्याः वदन्ति -- \"वर्णविभागः एव नास्ति, सर्वे देवस्य सन्तानाः, राज्ञे वर्णभेदं कर्तुम् अधिकारः नास्ति\" इति। अत्र वर्णः इत्युक्ते जातिः इति अर्थे प्रयुक्तम्।\n\nसामान्यतः समाजे मातापित्रोः स्वभावः यः तमेव स्वभावं सन्तानाः अनुसरन्ति। उदाहरणार्थं ब्राह्मणस्य पुत्रः, तस्मै ब्राह्मणस्वभावम् अनुसर्तुं सुकरं भवति। सः तमेव अनुसृत्य वर्धते। एवं सति यथार्थं वर्णम् अभिज्ञातुं दुष्करं भवति। एवं वर्णम् अभिज्ञातुं दुष्करे सति आगता पद्धतिः जातिपद्धतिः। जातिः भिन्ना वर्णः भिन्नः इत्यस्य उत्तमम् उदाहरणं -- मत्स्यगन्धिकन्यायां जातः वेदव्यासः। ते महाब्राह्मणाः इति समग्रं जगत् स्वीकृतवत्।\n\nअद्य समाजे जीवस्वभावम् अभिज्ञाय तदनुगुणं कर्म कर्तुं पद्धतिः न विद्यते। इदम् अतिक्रम्य मातापितरौ स्वेच्छां स्वसन्तानेषु आरोपयन्ति। इदम् अत्यन्तम् अवैज्ञानिकं पद्धतिः। बालेषु निहितां यथार्थां प्रतिभां न अभिज्ञाय, \"स्वैः उक्तं विषयं बालाः शिक्षेरन्\" इति वर्णपद्धतेः विरुद्धः सम्प्रदायः। तस्य तस्य जीवस्वभावः यः तदनुगुणं तेन शिक्षणीयम्। तदा सः तस्मिन् विषये पारङ्गतः भवति, समाजाय तेन उपयोगः भवति।",
  "18.45": "स्वे स्वे कर्मणि अभिरतः संसिद्धिं लभते नरः ।\nस्वकर्मनिरतः सिद्धिं यथा विंदति तत् शृणु ॥\n\nस्वस्वकर्मणि निरतः मनुष्यः सिद्धिं लभते। स्वस्वभावसहजे कर्मणि निरतः कथं सिद्धिं लभते तत् शृणु।\n\nस्वस्वभावानुगुणं कर्म कृष्णः \"स्वकर्म\" इति आह्वयति। \"स्वकर्म कुरु\" इत्युक्ते स्वस्वभावानुगुणं कर्म कुरु इत्यर्थः। प्रामाणिकतायाः स्वकर्मनिष्ठायाश्च अधिकः धर्मः अन्यः नास्ति। स्वस्वभावसहजं कर्म भगवदर्पणबुद्ध्या कृत्वा प्रामाणिकतया जीवनम् एव सर्वेभ्यः श्रेष्ठः धर्मः।\n\nअस्मासु केचन पृच्छेयुः -- \"यत्किमपि कार्यं भवतु, यस्मात् अधिकं धनार्जनं शक्यं तत् कार्यं कर्तुं कः दोषः\" इति। अत्र कृष्णः तत् दोषः इति उक्तवान्। कञ्चन एकं कार्यं करणं जीवनं न, तत् यातना। स्वस्वभावसहजे कर्मणि त्वं जीवसि चेत् तत् जीवनम्। तदेव मोक्षमार्गः। तव स्वभावानुगुणं तव शिक्षणम्; तव शिक्षणानुगुणं तव कर्म। एवं कृते सति कर्मणि अभिरतिः (पूर्णा तृप्तिः सन्तोषश्च) भवति। एवम् आनन्देन भगवदर्पणभावेन कर्म कृते सति, जीवनस्य अन्तिमां सिद्धिं मोक्षं प्राप्तुं शक्यते। स्वभावसहजेन कर्मणा कथं सिद्धिः भवति इति कृष्णः अग्रिमेषु श्लोकेषु विवृतवान्।",
  "18.46": "यतः प्रवृत्तिर्भूतानां येन सर्वमिदं ततम् ।\nस्वकर्मणा तमभ्यर्च्य सिद्धिं विन्दति मानवः ॥४६॥ यतः भूतानां प्रवृत्तिः, येन सर्वं व्याप्तम्, तं भगवन्तं स्वकर्मणा अभ्यर्च्य मानवः सिद्धिं विन्दति। इदम् अर्चनं न पौरोहित्यमन्त्रार्चनम्, अपि तु इन्द्रियनिग्रह-शमदमादियुक्तं स्वयंकृतम् अर्चनम्। एवं स्वभावसहजकर्म भगवत्पूजा भवति।",
  "18.47": "श्रेयान्स्वधर्मो विगुणः परधर्मात्स्वनुष्ठितात् ।\nस्वभावनियतं कर्म कुर्वन्नाप्नोति किल्बिषम् ॥४७॥ सुष्ठु अनुष्ठितात् परधर्मात् विगुणः अपि स्वधर्मः श्रेयान्; स्वभावनियतं कर्म कुर्वन् किल्बिषं न प्राप्नोति। वेदव्यासाः धर्मराजं वनगमनेच्छायां निवारयन्तः उक्तवन्तः—\"त्वं स्वधर्मं त्यक्त्वा वनं गच्छसि यथा असङ्गतम्, तथैव अहम् तपः त्यक्त्वा राज्यं कुर्याम्\" इति। दोषयुक्तमपि स्वकर्म परधर्मात् श्रेष्ठम्।",
  "18.48": "सहजं कर्म कौंतेय सदोषम् अपि न त्यजेत् ।\nसर्वारंभाः हि दोषेण धूमेन अग्निः इव आवृताः ॥\n\nहे कौन्तेय, सहजं कर्म दोषयुक्तम् अपि न त्यजेत्। समस्तानि कर्माणि दोषेण आवृतानि -- अग्निः धूमेन इव।\n\nवयम् अस्मदीयस्वभावाय परिस्थितये च सहजे कर्मणि यावानपि दोषः स्यात् तथापि तत् कर्म न त्यजेम। अत्र पाण्डवानां सहजधर्मः अन्यायस्य विरुद्धं संघर्षः। एवं संघर्षे मृत्युः पीडा च जायेत। परं तत् पापं न। अस्मिन् जगति दोषरहितं कर्म एकमपि नास्ति। अग्निः यत्र तत्र धूमः भवत्येव। कर्मणि हिंसा स्यात्, परं तत् सहजधर्मः यदा तत् त्यक्तुं न शक्यते। सहजधर्मे हिंसा अनिवार्या यदा तद्विषये चिन्तां न कुर्यात्। अस्मदीयभागे उपस्थितं कर्म भगवदर्पणबुद्ध्या निष्कामतया करणं धर्मः। अनेन पापं न अङ्गति।\n\nकेवलं स्वभावानुगुणं व्यवहृतमात्रेण मुक्तिः न लभ्यते। तस्य पृष्ठे काश्चन साधनाः अपेक्षिताः। कानिचन अनुसन्धानानि अपेक्षितानि। तस्य विवरणं कृष्णः अग्रिमेषु श्लोकेषु विवृतवान्।",
  "18.49": "असक्तबुद्धिः सर्वत्र जितात्मा विगतस्पृहः ।\nनैष्कर्म्यसिद्धिं परमां संन्यासेन अधिगच्छति ॥\n\nसर्वत्र आसक्तिरहितबुद्धिः, जितमनाः, इच्छारहितः -- एतादृशः \"संन्यासेन\" मोक्षप्रदां श्रेष्ठां योगसिद्धिं [अनिष्टकर्मणां नाशरूपां सिद्धिम्] प्राप्नोति।\n\nमोक्षसाधनभूतां सिद्धिं (पापकर्मरहितां स्थितिम्) प्राप्तुं केवलं स्वकर्मणि निरतत्वं न पर्याप्तम्, अपि तु वयम् अस्मदीयं मनः नियन्त्र्य, फलापेक्षां विना, \"मया अभवत्\" इति अहङ्कारं त्यक्त्वा भगवदर्पणभावेन कर्म कर्तव्यम्। अहङ्कारः अध्यात्मस्य महान् शत्रुः। अस्य जागृतिः अस्मासु स्यात्। संक्षेपेण वक्तव्यं चेत् सर्वत्र \"मया अभवत्\" इति अहङ्कारं त्यक्त्वा, मनः जित्वा, बुद्ध्या फलकामनां त्यक्त्वा, इच्छानां न्यासं कृत्वा, सर्वं भगवति अर्प्य स्वकर्म कृते सति -- मोक्षं प्राप्तुम् अपेक्षिता सिद्धिः प्राप्ता भवति।",
  "18.50": "सिद्धिं प्राप्तः यथा ब्रह्म तथा आप्नोति निबोध मे ।\nसमासेन एव कौंतेय निष्ठा ज्ञानस्य या परा ॥\n\nहे कौन्तेय, यां सिद्धिं प्राप्तः ब्रह्मतत्त्वं [श्रीतत्त्वं] प्राप्नोति तत् संक्षेपेण मत्तः शृणु। इयं सिद्धिः ज्ञानस्य अन्तिमः सोपानः।\n\nयेन केनापि पातकेन अकलुषितं जीवनाचरणं (नैष्कर्म्यसिद्धिः) रूपितं भवति तदा अस्मदीये मनसि भगवान् आगत्य निवसति। अनेन मातरं श्रीलक्ष्मीं प्राप्य अन्ततः भगवन्तं प्राप्तुं शक्यते। कथं ब्रह्मतत्त्वं प्राप्नुयात् इति संक्षेपेण कृष्णः अग्रे वदति। नैष्कर्म्यसिद्धिः इत्युक्ते मनुष्यस्य ज्ञानसाधनायाः अन्तिमः सोपानः। एतं सोपानं प्राप्तुं वयम् अध्यात्मे कुन्त्यां इव दृढाभिप्रायाः कौन्तेयाः भवेम।",
  "18.51": "बुद्ध्या विशुद्धया युक्तः धृत्यात्मानं नियम्य च ।\nशब्द आदीन् विषयान् त्यक्त्वा रागद्वेषौ व्युदस्य च ॥\n\nविशुद्धया बुद्ध्या युक्तः, धृत्या स्वात्मानं नियम्य, शब्दादीन् विषयान् त्यक्त्वा, रागद्वेषौ त्यक्त्वा --\n\nअध्यात्मसाधनायां वयम् अस्मदीयं मनः कदापि दुष्टं न चिन्तयेम। शुद्धा बुद्धिः अस्मदीया भवेत्। मनः अतीव धैर्येण नियन्त्र्य, असाधारणसाहसेन सर्वं दुष्टविचारं मनसः अपसारयेम। इन्द्रियाणि मनः कलुषयितुं साधनानि। अतः श्रवणस्पर्शनदर्शनघ्राणभक्षणानां चापल्यं प्रथमं त्याज्यम्। शिशुवत् रागद्वेषरहितेन निर्मलेन मनसा स्थातव्यम्।",
  "18.52": "विविक्तसेवी लघ आशी यत वाक् काय मानसः ।\nध्यान योग परः नित्यं वैराग्यं समपाश्रितः ॥\n\nएकान्तनिवासी, मिताहारी, वाक्कायमनोभिः नियन्त्रितः, ध्यानयोगे निरतः, निरन्तरं वैराग्यम् आश्रितः --\n\nनिरर्थकालापयुक्तेषु जनसमूहेषु न मिश्रित्वा, यथाशक्ति एकान्ते स्थातुम् अभ्यसनीयम्। अध्यात्मसाधनायां यथाशक्ति पवित्रं स्थानं चित्वा अभ्यासः करणीयः। अतिशयेन भुक्ते सति मनः कार्यं न करोति। अतः नियतकाले नियतम् आहारं सेवनीयम्। वाचि नियन्त्रणम्, देहस्य क्रियायाम् नियन्त्रणम्, मनसः चिन्तने नियन्त्रणं धृत्वा ध्यानं कर्तव्यम्। जीवने सर्वं प्रीणयन् किमपि अनासज्य जीवितव्यम्।",
  "18.53": "अहंकारं बलं दर्पं कामं क्रोधं परिग्रहम् ।\nविमुच्य निर्ममः शांतः ब्रह्मभूयाय कल्पते ॥\n\nअहङ्कारं, बलात्कारं, दर्पं, कामं, क्रोधं, परिग्रहबुद्धिं च त्यक्त्वा, ममतारहितः शान्तः भूत्वा -- सः ब्रह्मभूतत्वं प्राप्तुं योग्यः भवति। [तस्य मनः भगवति स्थिरीभवति; सः चतुर्मुखस्य उपदेशं प्राप्य मातरं लक्ष्मीं प्राप्नोति।]\n\n\"मया कृतम्\" इति अहङ्कारः, अन्यस्य उपरि स्वाभिप्रायम् आरोपणम्, स्वस्थितेः विषये दर्पः, कामक्रोधौ, अन्यस्य पुरतः याचनाबुद्धिः च -- एतत् सर्वं भगवच्चिन्तनस्य विरुद्धम्। एतत् त्यक्त्वा, \"अहम्-मम\" इति ममकारं त्यक्त्वा भगवति मनः एकाग्रीकृत्य ब्रह्मतत्त्वं प्राप्तुं शक्यते।",
  "18.54": "ब्रह्मभूतः प्रसन्नात्मा न शोचति न कांक्षति ।\nसमः सर्वेषु भूतेषु मत् भक्तिं लभते पराम् ॥\n\nब्रह्मभूतः [श्रीतत्त्वे स्थितः], प्रसन्नमनाः न शोचति, न काङ्क्षति। सर्वेषु जीवेषु समभावं धृत्वा मयि परां भक्तिं लभते।\n\nभगवति स्थिरीभूतमनसे इष्टानिष्टे न स्तः। तस्य मनः स्वच्छं भवति। एतस्यां स्थितौ सर्वोत्कृष्टा भक्तिः वर्धते। गुणपूर्णं भगवन्तं सः जगतः प्रत्येकस्मिन् वस्तुनि पश्यति। अनेन तस्मिन् कापि तारतम्यता द्वेषः वा न भवति।",
  "18.55": "भक्त्या माम अभिजानाति यावान् यश्चास्मि तत्त्वतः ।\nततो मां तत्त्वतो ज्ञात्वा विशते तदनंतरम् ॥\n\nभक्त्या माम् अभिजानाति यावान् यः च अस्मि तत्त्वतः ।\nततः मां तत्त्वतः ज्ञात्वा विशते तत् अनंतरम् -- भक्त्या \"अहम्\" कीदृशः इति यथार्थतया ज्ञातुं शक्नोति। एतादृश्या पराभक्त्या मां यथार्थतया ज्ञात्वा अनन्तरं मामेव प्रविशति।\n\nएतादृश्याः भक्तेः उत्कृष्टायां स्थितौ स्थितस्य कापि विपरीता ज्ञप्तिः न भवति। लक्ष्म्याः सन्निधानेन भगवान् इत्युक्ते किम्, तस्य महिमा कः, तस्य शक्तिः का, तस्य अनन्तगुणानां विस्तारः कः -- इति यथार्थतया जीवयोग्यतायाः पूर्णप्रमाणेन अवगच्छति। \"एवं तत्त्वतः भगवन्तं यथार्थतया ज्ञातवति अतिपरिशुद्धेन ज्ञानेन भक्त्या च मामेव आगत्य प्राप्नोति\" इति वदति कृष्णः।",
  "18.56": "सर्व कर्माणि अपि सदा कुर्वाणः मत् व्यपाश्रयः ।\nमत् प्रसादात् अवाप्नोति शाश्वतम् पदम् अव्ययम् ॥\n\n\"अहमेव सर्वस्वम्\" इति ज्ञात्वा समस्तानि कर्माणि निरन्तरं कुर्वन्, मत्प्रसादेन नाशरहितं अपरिवर्तनीयं स्थानं प्राप्नोति।\n\nभगवानेव सर्वस्वम् इति ज्ञात्वा, यत्किमपि कर्म कुर्वन्तः तस्य कर्मणः लक्ष्यं भगवन्तमेव कृत्वा, पूर्णभगवदर्पणबुद्ध्या कर्म कुर्वन्तः, भगवतः अनुग्रहेण कदापि न विचलितं मोक्षं प्राप्नुवन्ति।",
  "18.57": "चेतसा सर्वकर्माणि मयि संन्यस्य मत् परः ।\nबुद्धियोगमुपाश्रित्य मच्चित्तः सततं भव ॥\n\nचेतसा सर्वकर्माणि मयि संन्यस्य मत् परः ।\nबुद्धियोगम् उपाश्रित्य मत् चित्तः सततम् भव -- अन्तरङ्गेण समस्तानि कर्माणि मयि अर्प्य, माम् एव परतत्त्वं ज्ञात्वा, ज्ञानयोगस्य मार्गम् अवलम्ब्य निरन्तरं मय्येव मनः स्थापय।\n\nअत्र कृष्णः वदति -- \"मां ज्ञात्वा, सर्वं कर्म मयि अर्पयित्वा, ज्ञानयोगेन मनः निरन्तरं मयि स्थापय\" इति। वयं कुर्वत् समस्तं कर्म भगवते अर्पयित्वा कर्तव्यम् इति अतिमुख्यं विषयम्। अद्य एतादृशी कर्मसाधना नास्ति भवति। अस्य मूलं कारणम् अज्ञानम्। वयं पूजां कुर्मः यस्याः कस्याश्चित् फलेच्छया। कदाचित् ज्योतिषिणः कञ्चन ग्रहदोषम् अस्ति इति वदन्ति। उदाहरणार्थं कुजदोषः। सामान्यतः ज्योतिषिणः कुजदोषः इति उक्ते सति अस्मभ्यं प्रथमं दृश्यते -- \"एषः ग्रहः अस्मान् पीडयति\" इति। वस्तुतः कुजदोषः इत्युक्ते कुजस्य दोषः न, तत् अस्मदीयः दोषः, अस्मदीयं प्रारब्धकर्म। तत् एषः ग्रहः सूचयति इत्येव। तत् वयं भ्रान्त्या कुजः एव मम पृष्ठे पतितः इति ज्ञातव्याः भवामः। ग्रहाः अस्मभ्यं कष्टं दातुं न सन्ति। ते कदापि कष्टं न ददति। अपि तु अस्मभ्यम् अस्मदीयात् प्रारब्धात् आगन्तुं कष्टं ते सूचयन्ति। अस्मभ्यं कष्टस्य आगमनसम्भावनाम् अस्मभ्यं पूर्वं ज्ञापयित्वा, वयं तम् अनिष्टं प्रतिभटयितुं मानसिकां सिद्धतां कारयितुं ग्रहाणां कर्तव्यम्। एवं प्रारब्धकर्म अस्ति इति ज्ञाते सति, तां समस्यां प्रतिभट्य, साधनामार्गे अग्रे गन्तुं भगवति शरणं गमनं प्रायश्चित्तपूजा एव -- न ग्रहेभ्यः दत्तं लञ्चम्। उदाहरणार्थं नवग्रहपूजा। अस्मदीयं प्रारब्धकर्म ग्रहाः सूचितवन्तः इति, तेषां ग्रहाणाम् अन्तर्यामिणं भगवन्तं प्रार्थनं नवग्रहपूजा।\n\nनारायणस्य भक्तमपि प्रारब्धकर्म न त्यजति। अस्मदीयप्रारब्धानुगुणं वयम् अस्मदीयं ग्रहचारम् अनुभवितव्यमेव। ज्ञानिभ्योऽपि कष्टम् आगच्छति। तत् दुःखं प्रतिभटितुं सामर्थ्यं यदा नास्ति, तदा भगवन्तं प्रार्थयनं दोषः न। अत्र अतिमुख्यः विषयः -- फलापेक्षां विना परमात्मनि प्रार्थना। \"अहं पूर्वजन्मनि कृतस्य कर्मणः फलतया अद्य इदम् अनिष्टं प्राप्तवान्। मम पुरतः स्थितम् इमं ग्रहचारं त्वं ग्रहाणाम् अन्तर्यामी भूत्वा मह्यं दर्शितवान्। तुभ्यं मम कोटिकोटिनमनम्। मम अज्ञातेन कृतं दोषं क्षमित्वा, अहम् इदम् अनिष्टं प्रतिभट्य ज्ञानमार्गे अग्रे गत्वा त्वां प्राप्तुं मह्यं मार्गं दर्शय; मदन्तः स्थितः त्वं स्वपूजां मां माध्यमं कृत्वा कारयस्व; अहं त्वयि शरणागतः अस्मि\" इति अनुसन्धानम् अस्याः पूजायाः पृष्ठे स्यात्। एवं भगवान् सर्वश्रेष्ठः इति जागृत्या, समस्तानां देवतानाम् आराधनां कुर्वतोऽपि, तेषाम् अन्तर्यामिणं भगवन्तं ज्ञात्वा, कर्म मानसिकतया भगवति अर्पणीयम्। इदं यथार्थकर्मणः विधानम्।\n\nसंक्षेपेण वक्तव्यं चेत् -- वयम् अस्मदीयं मनः अन्यत्र न गच्छत् निरुध्य भगवति स्थापयेम; अस्मदीयानि समस्तानि कर्माणि भगवतः पूजारूपाणि, तानि भगवान् अस्मदीयेन हस्तेन कारयति इति जागृतिः अस्मदीये मनसि स्थिरा भवेत्। अस्मदीयम् अनुष्ठानम् अनुसन्धानं च आनन्दमयं भवेत्। तत्र कोऽपि दबावः, भयं, फलापेक्षा न स्यात्।",
  "18.58": "मत् चित्तः सर्वदुर्गाणि मत् प्रसादात् तरिष्यसि ।\nअथ चेत् त्वम् अहंकारात् न श्रोष्यसि विनंक्ष्यसि ॥\n\nमयि मनः स्थापिते सति, मत्प्रसादेन सर्वाणि कष्टानि तरिष्यसि। अथ त्वम् अहङ्कारेण न शृणुयाः चेत् विनश्यसि।\n\nमनः भगवति प्रवाह्य, बुद्धौ भगवन्तं स्थापयित्वा, चित्ते भगवन्तं स्थिरीकृत्य, सुप्तप्रज्ञायामपि भगवतः स्मरणं शाश्वतीकृत्य सत्सु, अस्मदीयाः सर्वाः क्रियाः भगवतः पूजा भवन्ति। अनेन अस्मदीये समस्ते व्यवहारे पूर्णा प्रामाणिकता व्यक्ता भवति, जीवने आगच्छत् दुर्गमां स्थितिं कष्टं दैन्यं च प्रतिभटितुं क्षमता आगच्छति। एवं ज्ञानी स्वजीवनयात्रायाम् अनिवार्यतया आगच्छन्तः समस्ताः आपदः निरायासेन अतिक्रम्य अग्रे गच्छति। इदं जीवितं चेत् भगवान् अस्मदीये जीवने आगच्छत् सर्वाणि अनिष्टानि रक्षति। तस्य रक्षाकवचं सदा अस्मान् आवृणोति। अनेन जीवने आगच्छत् समस्ताभ्यः आपद्भ्यः वयं मुच्यामहे। इदं त्यक्त्वा वेदान्तः केवलं वृथावादः, तत्र मह्यं विश्वासः नास्ति इति अहङ्कारं धरेत् चेत्, वयं स्वहस्तेन स्वभविष्यं नाशं कृत्वा विनाशं प्राप्नुमः।",
  "18.59": "यत् अहंकारम् आश्रित्य न योत्स्ये इति मन्यसे ।\nमिथ्या एषः व्यवसायः ते प्रकृतिः त्वाम् नियोक्ष्यति ॥\n\nअहङ्कारम् आश्रित्य \"न योत्स्ये\" इति यत् मन्यसे तत् -- एषः निश्चयः मिथ्या। तव स्वभावः [भगवतः इच्छा] त्वां योद्धुं नियोक्ष्यति।\n\nअर्जुनः \"अहं युद्धं न करिष्यामि\" इति रथे कुसीदित्वा उपविष्टवान् इति वयं प्रथमाध्याये दृष्टवन्तः। अत्र कृष्णः वदति -- \"'अहं युद्धं न करिष्यामि' इति एषः तव अहङ्कारभरितः भ्रमः। यत् त्वं न करिष्यामि इति उक्तवान्, तदेव त्वं करिष्यसि\" इति। यतः अस्मान् नियन्त्रयन्ती शक्तिः प्रकृतिः। अत्र अस्मदीयं भौतिकं निर्णयं व्यर्थम्। अस्मदीयः जीवस्वभावः, तदनुगुणम् आनुवंशिकः प्रभावः, परिसरस्य प्रभावः, एतत् सर्वं नियन्त्रयन् भगवत इच्छानुगुणं क्रिया प्रवर्तते एव प्रवर्तते।",
  "18.60": "स्वभावजेन कौंतेय निबद्धः स्वेन कर्मणा ।\nकर्तुं न इच्छसि यत् मोहात् करिष्यसि अवशः अपि तत् ॥\n\nहे कौन्तेय, स्वस्य स्वभावजेन कर्मणा त्वं बद्धः असि। मोहेन यत् कर्तुं न इच्छसि तत् त्वम् अवशः अपि करिष्यसि।\n\nवयं \"एवं करणीयम्, तथा करणीयम्\" इति अहङ्कारेण चिन्तयामः इदम् अस्मदीयेन अज्ञानेन। एवं यत् किमपि चिन्तयेम अन्ततः वयं कुर्मः तत् अस्मदीयजीवस्वभावानुगुणमेव। अस्य नियन्त्रणम् अस्मासु नास्ति। तत् अस्मदज्ञाततया भगवतः इच्छानुगुणं प्रवर्तते।",
  "18.61": "ईश्वरः सर्वभूतानां हृत् देशे अर्जुन तिष्ठति ।\nभ्रामयन् सर्वभूतानि यंत्र आरूढानि मायया ॥\n\nहे अर्जुन, समस्तानां जीवानां हृदयस्थाने सर्वशक्तः भगवान् स्थितः, परिभ्रमति जगद्यन्त्रे उपविष्टानि समस्तानि जीवानि प्रकृतेः मायया [स्वेच्छया] भ्रामयन्।\n\nसमस्तानां जीवानां हृदयमध्ये सर्वशक्तः भगवान् स्थितः। इदं पिण्डाण्डं ब्रह्माण्डं च नामकम् अद्भुतं यन्त्रं निरन्तरं चलत् कारयन् सः भगवान्। सः एव ब्रह्माण्डस्य पिण्डाण्डस्य च स्वामी। सर्वेषाम् अन्तः स्थित्वा तेभ्यः अनुभवं दत्त्वा नियन्त्रयन् महाचैतन्यं सः भगवान्। समस्तं कर्म भगवतः महिम्ना तस्य इच्छानुगुणं प्रवर्तते।",
  "18.62": "तम् एव शरणं गच्छ सर्वभावेन भारत ।\nतत् प्रसादात् परां शांति स्थानं प्राप्स्यसि शाश्वतम् ॥\n\nहे भारत, सर्वभावेन तमेव शरणं गच्छ। तस्य कृपया श्रेष्ठं सुखं, नाशरहितं स्थानं प्राप्स्यसि।\n\nसर्वसमर्थाय भगवते वयम् आत्मानम् अर्पयेम। अस्मदीयस्य जीवनस्य सर्वेषु स्तरेषु भगवति शरणागतिः स्यात् [केवलं कष्टकाले न]। अस्मासु सत्त्वगुणं वर्धयित्वा, तमः दूरं कृत्वा, भगवति आत्मानम् अर्पयित्वा सति -- अस्मभ्यं यथार्थस्य पूर्णसत्त्वस्य दर्शनं भवति। सः भगवान् नेत्रे उद्घाट्य अनुग्रहं कृतवान् चेत्, अनन्तरम् अवबोधाय अन्यत् कापि साधनं न आवश्यकम्। सत्यं स्वयमेव उद्घाटितं भवति, सर्वोत्कृष्टः आनन्दः अस्माकं भवति। अनेन ज्ञानानन्दस्य पराकाष्ठाभूतं मोक्षं प्राप्तुं शक्यते।",
  "18.63": "इति ते ज्ञानम् आख्यातं गुह्यात् गुह्यतरं मया।\nविमृश्य एतत् अशेषेण यथा इच्छसि तथा कुरु ॥\n\nएवं गुह्याद् अपि गुह्यतरं ज्ञानं मया तुभ्यम् उक्तम्। एतत् सर्वं विमृश्य, यथा इच्छसि तथा कुरु।\n\nकृष्णः पञ्चदशाध्याये ज्ञानस्य उपसंहारं कृतवान्। अत्र उपासनायाः समस्तम् अवबोधं दत्त्वा अनन्तरं तस्य उपसंहारं कुर्वन् वदति -- \"इदं जगति विद्यमानेषु रहस्येषु रहस्यम्। अध्यात्मस्य अन्तरङ्गं रहस्यं तुभ्यम् उक्तवान्। मया उक्तं विषयं समग्रतया विमृश्य, तव मनसि यथा मनोवरिकं भवति तथा कुरु\" इति। अत्र \"तव जीवस्वरूपं, आत्मसाक्षी किं वदति तथा कुरु\" इति अर्जुनाय वदन् -- वयम् अन्यस्य उपरि अस्मदीयम् अभिप्रायं न आरोपयेम इति समाजनीतिं कृष्णः उद्घाटितवान्।",
  "18.64": "सर्व गुह्य तमम् भूयः शृणु मे परमं वचः ।\nइष्टः असि मे दृढम् इति ततः वक्ष्यामि ते हितम् ॥\n\nसमस्तेभ्यः अधिकं गोपनीयं मम श्रेष्ठं वचनं पुनः शृणु। त्वं मह्यं दृढतया इष्टः असि, अतः तव हितं वदामि।\n\nपूर्वम् उक्तायाः साधनायाः सारं, अस्माभिः ज्ञातव्येषु विषयेषु अत्यन्तं गोपनीयं साधनायाः रहस्यं सात्त्विकाय तुभ्यं पुनरपि वदामि; मम भक्तः त्वं ज्ञानी; ज्ञानिनः मह्यम् अत्यन्तं प्रियाः, अतः पुनरपि वदामि -- शृणु।",
  "18.65": "मत् मनाः भव मत् भक्तः मत् याजी मां नमस्कुरु ।\nमाम् एव एष्यसि सत्यं ते प्रतिजाने प्रियः असि मे ॥\n\nमयि मनः स्थापय, मयि भक्तिं धारय, माम् एव आराधय, मह्यं नमस्कुरु। एवं मामेव प्राप्स्यसि। एतत् सत्यं, तुभ्यं प्रतिजानामि। त्वं मम प्रियः।\n\nसाधनायाः सारं विवृण्वन् कृष्णः अत्र पूर्वं विवृतं विषयं, साधनायाः सारसङ्ग्रहं पुनः उपसंहाररूपेण वदति। कृष्णः वदति -- \"मयि एव मनः स्थापय\" इति। साधनायां वयम् अनन्यचिन्तनं कुर्याम। केवलं भगवद्विषयकम् एकभक्तिः स्यात्। ज्ञानपूर्वकं भगवान् सर्वोत्तमः इति भगवन्तं स्मरेम। भगवति \"शुद्धा प्रीतिः\" स्यात्। वयं कुर्वत् समस्तं कर्म प्रीतिपूर्वकं भगवदर्पणं भवेत्। \"सर्वदेव नमस्कारः केशवं प्रतिगच्छति\" इति सत्यं ज्ञात्वा सर्वान्तर्यामिणं भगवन्तं पूजय। एवं समस्तायाम् उपासनायां भगवन्तं पश्येत् चेत् \"मामेव आगत्य प्राप्स्यसि, इदं निश्चयेन सत्यम्\" इति वदति कृष्णः।",
  "18.66": "सर्वधर्मान् परित्यज्य माम् एकम् शरणं व्रज ।\nअहं त्वाम् सर्व पापेभ्यः मोक्षयिष्यामि मा शुचः ॥\n\nसमस्तान् क्षुद्रान् धर्मान् फलाशाश्च त्यक्त्वा मामेकं शरणं व्रज। अहं त्वां समस्तेभ्यः पापेभ्यः मोचयिष्यामि। मा शोकं कुरु।\n\n\"सर्वधर्मान् परित्यज्य\" इत्युक्ते समस्तानि पुण्यकर्माणि कृत्वा तेभ्यः फलापेक्षां अनिच्छनम्। अस्मदीयं धर्मकार्यं व्यापारः न भवेत्। अस्मै उत्तमः दृष्टान्तः धर्मरायस्य द्रौपद्याश्च मध्ये संवादः। द्रौपदी वदति -- \"धर्मः रक्षति रक्षितः -- यः धर्मं रक्षति तं धर्मः रक्षति इति श्रुतवती अस्मि, सः त्वां किमर्थं न अरक्षत्? वयं किमर्थं राज्यं हारयित्वा वनं गन्तव्याः अभवाम?\" इति। तस्मै धर्मरायः ददत् उत्तरं रोचकम्। सः वदति -- \"अहं धर्मस्य वणिक् न; अहं धर्माचरणं करोमि मम आत्मसन्तोषायैव, न तु यस्याः कस्याश्चित् फलापेक्षया\" इति। एवं यत्किमपि धर्मः भवतु सः केवलं भगवतः आराधना। तत्र फलापेक्षा नास्ति। एवं जीविते सति भगवान् अस्मदीयानि समस्तजन्मनां पापानि दग्ध्वा नाशयति। भगवति पूर्णं शरणागते सति भगवतः हस्ते वयं सुरक्षिततया धैर्येण स्थातुं शक्नुमः। इदं गीतायाः उपदेशे कृष्णः अस्मभ्यं दत्तम् अन्तिमम् आश्वासनम्। अत्र गीतायां भगवतः उपदेशस्य भागः समाप्तः। अस्य अध्यायस्य अग्रिमेषु श्लोकेषु गीतायाः फलश्रुतिं द्रष्टुं शक्यते।",
  "18.67": "इदं ते न अतपस्काय न अभक्ताय कदाचन ।\nनच अशुश्रूषवे वाच्यं नच मां यः अभ्यसूयति ॥\n\nइदं तपोरहिताय कदापि न वाच्यम्, भक्तिरहिताय न वाच्यम्, श्रोतुम् अनिच्छते न वाच्यम्, मयि द्वेषं धरते न वाच्यम्।\n\nअत्र कृष्णः ज्ञानपरम्परां कथं रक्षणीया इति विवृतवान्। यस्मै गभीरं चिन्तनशीलत्वं नास्ति तस्मै इदं न वाच्यम्; चिन्तनशीलत्वम् अस्ति परं श्रोतुम् आसक्तिः नास्ति तस्मै न वाच्यम्; आसक्तिः अस्ति परं भक्तिः प्रीतिः च नास्ति तस्मै न वाच्यम्; सर्वेभ्यः अधिकं भगवतः विषये असहनताम्, ईर्ष्याम्, द्वेषं धरतेभ्यः सर्वथा न वाच्यम्। अध्यात्मं कदापि वीथ्यां न स्थापनीयम्।\n\nएककाले वेदान्तं सार्वजनिकतया न उद्घाटनीयम्, तत् गोपनीयं रक्षणीयम् इति अभिप्रायः अधिकतया वृद्धिं गतवान्। अस्य परिणामेन क्रमेण गूढं ज्ञानम् उद्घाटयितारः एव न अभवन्। अद्य अस्मासु अधिकाः अध्यात्मिकग्रन्थेभ्यः आरतिं कृत्वा कुङ्कुमं दत्त्वा आवृण्वन्तः एव अधिकाः जाताः। अस्मात् कारणात् वयम् आवृतम् इदम् अमूल्यं ज्ञानम् उद्घाट्य आसक्तेभ्यः दातुं कार्यं करणीयम्।\n\nभगवद्गीतायाः इमम् अमूल्यं सन्देशम् अध्ययनं मनयनं च कृत्वा लभ्यमानां फलश्रुतिं कृष्णः अग्रिमेषु चतुर्षु श्लोकेषु विवृतवान्। भगवद्गीतायाः यथार्थं फलं मनुष्यस्य पुरुषार्थेषु अन्तिमः मोक्षः। अध्यात्मविद्यां वदतां समस्तशास्त्राणां सारः भगवद्गीता। भगवतः स्वरूपं ज्ञात्वा भगवतः लोकं प्राप्तुम् एतत् एकः एव ग्रन्थः पर्याप्तः। समस्तशास्त्रेषु विद्यमानं समस्तं सारं, समस्तं रहस्यं वयम् एतस्मिन् कृष्णार्जुनसंवादे द्रष्टुं शक्नुमः। एवं समस्तशास्त्राणां पूर्णा सारसंहतिः अन्तर्भूता अस्ति यत्र, तादृशः ग्रन्थः अन्यः नास्ति। एतादृशीं गीतां वयं गुरुमुखेन ज्ञातवन्तः, मननं कृतवन्तः, अत्र उक्तम् उपायम् अस्मदीये जीवने अनुसृतवन्तः, अस्माभिः ज्ञातं ज्ञानम् आसक्तेभ्यः ज्ञापितवन्तः चेत् -- वयं भगवतः लोकं (मोक्षं) प्राप्तुं शक्नुमः।",
  "18.68": "यः इमं परमं गुह्यं मत् भक्तेषु अभिधास्यति ।\nभक्तिं मयि परां कृत्वा माम् एव एष्यति असंशयः ॥\n\nयः इदं परमं गोप्यं मद्भक्तेषु वदति सः मयि श्रेष्ठां भक्तिं कृत्वा मामेव प्राप्नोति -- अत्र सन्देहः नास्ति।\n\nयः एतादृशं ज्ञानम् अवगत्य, तत् \"मयि श्रद्धाभक्तियुक्ताय साधकाय\" ददाति, सः निश्चितं मामेव आगत्य प्राप्नोति। अत्र सन्देहः नास्ति।",
  "18.69": "नच तस्मात् मनुष्येषु कश्चित् मे प्रियकृत् तमः ।\nभविता नच मे तस्मात् अन्यः प्रियतरः भुवि ॥\n\nमनुष्येषु तस्मात् अधिकं मह्यं प्रियं कृत्वा अन्यः नास्ति। तस्मात् अधिकं मह्यं प्रियतमः अन्यः भुवि अग्रे अपि न जनिष्यते।\n\nगीतां ज्ञात्वा तां भक्तजनाय प्रापयत् श्रेष्ठं कार्यं कुर्वन्तः मनुष्येषु मह्यम् अत्यन्तं प्रियाः। एतेभ्यः अधिकम् इष्टं कर्म कुर्वन् मानवः अस्यां भुवि नास्ति -- इति वदति कृष्णः। भगवते ज्ञानिनः अतिप्रियाः। तेभ्योऽपि अतिप्रियाः स्वयं ज्ञानिनः भूत्वा, तस्य ज्ञानस्य माधुर्यं समाजाय ददन्तः। \"एते भुवि मह्यम् इष्टं कर्म कुर्वतां सर्वश्रेष्ठाः\" इति उक्तवान् कृष्णः।",
  "18.70": "अध्येष्यते च यः इमं धर्म्यं संवादम् आवयोः ।\nज्ञान यज्ञेन तेन अहम् इष्टः स्याम् इति मे मतिः ॥\n\nयः इमं धर्मबोधकं आवयोः संवादम् अध्ययनं करिष्यति सः ज्ञानयज्ञेन मामेव पूजितवान् भविष्यति इति मम अभिप्रायः।\n\nयदि गीतायाः ज्ञानं पचनं कृत्वा अन्यस्मै वक्तुं क्षमता अस्मासु नास्ति चेत्, धर्मविषयकम् इमं कृष्णार्जुनसंवादं गुरुमुखेन अध्ययनं कृत्वा अपि -- तत् ज्ञानयज्ञवत् भगवतः पूजा भवति। \"इदं मम अभिप्रायः\" इति वदति कृष्णः। भगवतः विषये मनुष्येण किं ज्ञातव्यं तत् ज्ञात्वा कथं धर्मस्य मार्गे गन्तव्यम् इति \"जीवनधर्मं\" गीतायाः मुखेन ज्ञात्वा पालयन् मोक्षं प्राप्नोति।",
  "18.71": "श्रद्धावान् अनसूयः च शृणुयात् अपि यः नरः ।\nसः अपि मुक्तः शुभान् लोकान् प्राप्नुयात् पुण्यकर्मणाम् ॥\n\nश्रद्धावान्, ईर्ष्यारहितः यः मनुष्यः शृणुयादपि, सोऽपि पापेभ्यः मुक्तः भूत्वा पुण्यकर्मणां मङ्गलमयान् लोकान् प्राप्नुयात्।\n\nयदि गीतां स्वयम् अध्ययनं कर्तुं सामर्थ्यम् अस्मासु न स्यात् चेत्, कयापि ईर्ष्यया विना, श्रद्धाभक्तिभ्यां ज्ञातवद्भ्यः श्रुत्वा ज्ञातम् अपि सत्यां वयम् अस्मदीयं पापं प्रक्षाल्य भगवतः लोकं प्राप्तुं शक्नुमः। इदं कृष्णस्य आश्वासनम्।",
  "18.72": "कच्चित् एतत् श्रुतं पार्थ त्वया एकाग्रेण चेतसा ।\nकच्चित् अज्ञान संम्मोहः प्रणष्टः ते धनंजय ॥\n\nहे पार्थ, इदं त्वया एकाग्रेण मनसा श्रुतं किम्? हे धनञ्जय, तव अज्ञानजः मोहः नष्टः किम्?\n\nइयं गीतायां कृष्णस्य अन्तिमा वाक्। सर्वं विवृत्य कृष्णः स्वशिष्यम् अर्जुनं पृच्छति -- \"मया उक्तं तव कर्णं प्रविश्य हृदयं स्पृष्टवत् किम्? अनेन तव मनसि विद्यमाना विभ्रान्तिः दूरं गता किम्?\" इति। अत्र कृष्णः -- गुरुः स्वशिष्यं पृच्छति यथा -- अर्जुनं प्रश्नितवान्। अत्र गीतायां कृष्णस्य वचनयुक्तानि पञ्चसप्तत्यधिकपञ्चशतशत् (५७४) श्लोकाः समाप्ताः। अर्जुनस्य समग्रेषु चतुरशीतिषु (८४) श्लोकेषु अन्तिमः श्लोकः, सञ्जयस्य समग्रेषु एकचत्वारिंशत्षु (४१) श्लोकेषु अन्तिमाः पञ्च श्लोकाः अस्य अध्यायस्य शेषः भागः। [कृष्णः ५७४; अर्जुनः ८४; सञ्जयः ४१; धृतराष्ट्रः १; समग्रतया ७०० श्लोकाः।]",
  "18.73": "अर्जुनः उवाच\n\nनष्टः मोहः स्मृति लब्धा त्वत् प्रसादात् मया अच्युत ।\nस्थितः अस्मि गतसंदेहः करिष्ये वचनं तव ॥\n\nहे अच्युत, मोहः नष्टः, तव प्रसादेन मया स्मृतिः पुनः प्राप्ता। सन्देहरहितः स्थितः अस्मि। तव वचनानुगुणं करिष्ये।\n\nमयि विद्यमाना विपरीता ज्ञप्तिः दूरं गता। किं सम्यक् किम् असम्यक् इति ज्ञातुम् अशक्या स्थितिः मयि आसीत् -- सा अपगता। बन्धुमोहेन गता मम स्मृतिः पुनः आगता। अच्युतस्य तव अनुग्रहेण मम विस्मृतिः विनष्टा। मम सर्वेभ्यः प्रश्नेभ्यः उत्तरं लब्धम्। तव वचनं मनसि दृढतया स्थितम्। तव वचनानुगुणमेव अहं वर्तिष्ये।\n\nअत्र वयम् अवधानेन गृह्णीयाम -- अर्जुनः कृष्णस्य उपदेशेन \"मह्यं ज्ञानम् आगतम्\" इति अनुक्त्वा स्मृतिः आगता इति उक्तवान्। अनेन अस्मभ्यं ज्ञायते -- अर्जुनः तत्कालस्य महाज्ञानी। परं युद्धरङ्गे सः स्वां समस्तां स्मृतिं हारयित्वा कुसीदितवान्। इदम् एका भगवतः लीला। जगते एतादृशम् अमूल्यं कृतिं दातुं कृष्णः अर्जुनं माध्यमतया एवं प्रयुक्तवान्। भगवद्गीतायां यत् सन्देशम् अस्ति तस्य प्रायोगिकं विवरणं महाभारतम्। तत्र आगच्छन्ति पात्राणि प्रत्येकम् अपि गीतायाः एकैकं सन्देशं प्रतिनिधीकरोति। मनःशास्त्रीयदृष्ट्या पश्येम चेत् महाभारतं पञ्चसहस्रवर्षपूर्वं कौरवपाण्डवयोः मध्ये घटितः इतिहासः न। तत् अस्मदीयस्य अन्तरङ्गस्य, अस्मदीयस्य जीवनस्य संघर्षः। ज्ञानसन्देशः (सिद्धान्तः) तस्य प्रायोगिकं निरूपणं च अस्मभ्यं भगवता दत्तं महाभारतस्य मुखेन।",
  "18.74": "संजय उवाच\n\nइति अहं वासुदेवस्य पार्थस्य च महात्मनः ।\nसंवादम् इमम् अश्रौषम् अद्भुतं रोमहर्षणम् ॥\n\nहे धृतराष्ट्र, एवं महात्मनोः वासुदेवपार्थयोः इमम् अद्भुतं रोमाञ्चकरं संवादम् अहं श्रुतवान्।\n\nसञ्जयः कृष्णार्जुनयोः इमम् अपूर्वं संवादं साक्षात् दृष्ट्वा विस्मयं प्राप्तवान्। सः वदति -- \"मम नेत्रयोः पुरतः प्रवृत्तम् इमं वासुदेवार्जुनयोः संवादम् अहं श्रुतवान्। इदं मम भाग्यम्। मह्यं जातम् अनुभवं शब्दैः वर्णयितुं न शक्नोमि। इदम् अद्भुतम्। इमं संवादं श्रुत्वा आनन्देन मम रोमाणि उत्थितानि। आनन्दस्य पुलकः मां व्याप्तवान्\" इति।",
  "18.75": "व्यासप्रसादात् श्रुतवान् एतत् गुह्यम् अहं परम् ।\nयोगं योगेश्वरात् कृष्णात् साक्षात् कथयतः स्वयम् ॥\n\nव्यासस्य कृपया इमं परमं गुह्यं योगं, यम् योगमार्गाणां समस्तानाम् अधिपतिः कृष्णः स्वयं साक्षात् वदति स्म, तम् अहं श्रुतवान्।\n\nपरमपूज्यानां गुरूणां व्यासानाम् अनुग्रहेण अहम् इदम् अद्भुतं भाग्यं प्राप्तवान्। इच्छिते सत्यपि अलभ्यं जगतः अत्यन्तं गोपनीयं रहस्यम् अपि मया ज्ञातम्। सम्पूर्णस्य जगतः समस्तानां शक्तीनाम् एकं समग्ररूपं योगेश्वरात् कृष्णात् अध्यात्मस्य सारसर्वस्वं साक्षात् श्रुतवान् अहम्।",
  "18.76": "राजन् संस्कृत्यसंस्कृत्य संवादम् इमम् अद्भुतम् ।\nकेशव अर्जुनयोः पुण्यं हृष्यामि च मुहुः मुहुः ॥\n\nहे राजन्, केशवार्जुनयोः इमं पुण्यम् अद्भुतं संवादं स्मृत्वा स्मृत्वा पुनः पुनः रोमाञ्चितः भवामि।\n\nहे राजन् (धृतराष्ट्रं उद्दिश्य), इमम् अद्भुतं संवादं स्मृत्वा स्मृत्वा विस्मयः, आनन्दः, रोमाञ्चः, आश्चर्यं च। एतादृशम् इदं पूर्वं न अभवत्, अग्रे अपि न भविष्यति। सम्पूर्णं विश्वं नियन्त्रयन्ती, समस्तान् देवाधिदेवतान् नियन्त्रयन्ती शक्तिः -- अत्र अर्जुनस्य सारथिरूपेण स्थित्वा उक्तवान् इमम् अद्भुतं सन्देशम् -- पूर्वं कोऽपि न श्रुतवान्, न अनुभूतवान्। इदं स्मृत्वा पुनः पुनः पुलकितः भवामि।",
  "18.77": "तत् च संस्कृत्यसंस्कृत्य रूपम् अत्यद्भुतं हरेः ।\nविस्मयः मे महान् राजन् हृष्यामि च पुनःपुनः ॥\n\nहे राजन्, हरेः अत्यद्भुतं रूपं स्मृत्वा स्मृत्वा मह्यं महान् विस्मयः। पुनः पुनः रोमाञ्चितः भवामि।\n\nकृष्णस्य विश्वरूपदर्शनं प्राप्तवान् सञ्जयः अग्रे वदति -- हे राजन्, अस्मदीयाः समस्ताः समस्याः निवारयन् (हरिः) सः परमात्मा, अद्य अस्मभ्यं समस्तां समस्याम् अपि निवारयत् इमम् अद्भुतं सन्देशं दत्तवान्। अहं कृष्णं दृष्टवान्; तस्य अद्भुतं विश्वरूपं दृष्टवान्; तस्य वचनं श्रुतवान्; इदं मम वचनम् अतिक्रान्तः आनन्दः। अहम् आनन्देन पूर्णः अभवम्।",
  "18.78": "यत्र योगेश्वरः कृष्णः यत्र पार्थः धनुर्धरः ।\nतत्र श्रीः विजयः भूतिः ध्रुवा नीतिः मतिः मम ॥\n\nयत्र योगेश्वरः कृष्णः, यत्र धनुर्धरः पार्थः [नरनारायणौ] -- तत्र श्रीः, विजयः, ऐश्वर्यम्, ध्रुवा नीतिश्च वर्तते इति मम निश्चयः।\n\nयत्र यत्र नरनारायणौ स्तः तत्र सर्वं वर्तते। समस्तप्रकारा सम्पत्तिः, विजयः, अन्तरङ्गसाधना, बाह्या उन्नतिः -- सर्वं तत्र स्थितं भवति। इदं मम निश्चयः -- इति वदति सञ्जयः।\n\nभगवद्गीता अस्मभ्यं प्रापञ्चिकसुखस्य आकर्षणम् अतिक्रम्य उच्चैः आरोढुम् अपेक्षितं अध्यात्मज्ञानं वेदविद्यां च ददत् अपूर्वः ग्रन्थः। गीता मनसि स्थिता चेत् असत्यं वञ्चना च असाध्ये। यत्र गीतायाः अध्ययनम् अस्ति तत्र प्रामाणिकता अस्ति। गीतां पठित्वा, गीतां स्पृष्ट्वा वयम् असत्यं वदेम, अप्रामाणिकतया जीवेम चेत् तत् तस्मै गीताचार्याय वयं कुर्वन् द्रोहः। यत्र गीतायाः ज्ञानम् अस्ति तत्र विजयः अस्ति, उन्नतिः अस्ति, नीतिः अस्ति, समष्टिः अपि अस्ति -- इत्यत्र भगवद्गीतायाः अत्यद्भुतः सन्देशः समाप्तः।\n\nइति अष्टादशोऽध्यायः।\n\nसर्वे जनाः सुखिनः भवन्तु।\nश्रीकृष्णार्पणमस्तु।"
};

